				wordDatum.Value.Desc = dictionary[empty];
			}
		}
	}

	[BlackList]
	public WorldClass GetWorldClass(int key)
	{
		if (!WorldClassData.TryGetValue(key, out var value))
		{
			return null;
		}
		return value;
	}

	[BlackList]
	public void UnloadWorldClass()
	{
		WorldClass_Map = null;
	}

	private void AddWorldClassBin(int key, byte[] data)
	{
		WorldClass worldClass = WorldClass.Parser.ParseFrom(data);
		if (worldClass != null)
		{
			WorldClass_Map.Add(key, worldClass);
		}
	}

	private void LoadWorldClassBin()
	{
		if (WorldClass_Map == null)
		{
			WorldClass_Map = new Dictionary<int, WorldClass>();
		}
		WorldClass_Map.Clear();
		LoadCommonBinData("bin/WorldClass.bytes", AddWorldClassBin, null, null, null);
		if (!isLQA)
		{
			HandleWorldClassLanguage();
		}
	}

	private void LoadWorldClassJson()
	{
		if (WorldClass_Map == null)
		{
			WorldClass_Map = new Dictionary<int, WorldClass>();
		}
		WorldClass_Map.Clear();
		string text = LoadTableData("json/WorldClass.json");
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		table_WorldClass table_WorldClass2 = table_WorldClass.Parser.ParseJson(text);
		if (table_WorldClass2 != null)
		{
			int count = table_WorldClass2.List.Count;
			for (int i = 0; i < count; i++)
			{
				WorldClass worldClass = table_WorldClass2.List[i];
				WorldClass_Map.Add(worldClass.Id, worldClass);
			}
			if (!isLQA)
			{
				HandleWorldClassLanguage();
			}
		}
	}

	private void HandleWorldClassLanguage()
	{
		Dictionary<string, string> dictionary = LoadLanguageJsonTable("WorldClass");
		foreach (KeyValuePair<int, WorldClass> worldClassDatum in WorldClassData)
		{
			string empty = string.Empty;
			empty = worldClassDatum.Value.FuncChangeText1;
			if (!string.IsNullOrEmpty(empty))
			{
				if (!dictionary.ContainsKey(empty))
				{
					continue;
				}
				worldClassDatum.Value.FuncChangeText1 = dictionary[empty];
			}
			empty = worldClassDatum.Value.FuncChangeText2;
			if (!string.IsNullOrEmpty(empty))
			{
				if (!dictionary.ContainsKey(empty))
				{
					continue;
				}
				worldClassDatum.Value.FuncChangeText2 = dictionary[empty];
			}
			empty = worldClassDatum.Value.FuncChangeText3;
			if (!string.IsNullOrEmpty(empty) && dictionary.ContainsKey(empty))
			{
				worldClassDatum.Value.FuncChangeText3 = dictionary[empty];
			}
		}
	}

