public class BrickSkillInfo
{
	public int skillId;

	public FP curSkillEnergy;

	public FP maxSkillEnergy;

	public FP curTime;

	public FP skillCd;

	public bool autoCd;

	public bool IsFull
	{
		get
		{
			if (curSkillEnergy >= maxSkillEnergy)
			{
				return curTime <= 0;
			}
			return false;
		}
	}

	public BrickSkillInfo(int skillId, FP maxSkillEnergy, FP Cd)
	{
		this.skillId = skillId;
		this.maxSkillEnergy = maxSkillEnergy;
		skillCd = Cd;
	}

	public void OnInit()
	{
		curSkillEnergy = 0;
		curTime = 0;
		autoCd = true;
	}

	public void Clear()
	{
		curSkillEnergy = 0;
		curTime = skillCd;
		autoCd = true;
	}
}
public class BrickActorSkillCom : LogicComponent
{
	private FP recoveryEnerey = 10;

	private FP recoveryEnerey_rate = 1;

	private readonly Dictionary<int, BrickSkillInfo> DicSkill = new Dictionary<int, BrickSkillInfo>();

	public BrickActor Owner => (BrickActor)base.Entity;

	public override void OnActive()
	{
		base.OnActive();
	}

	public override void OnDeactive()
	{
		base.OnDeactive();
	}

	public void RegisterAllSkill(List<BrickSkillInfo> skillInfos)
	{
		for (int i = 0; i < skillInfos.Count; i++)
		{
			BrickSkillInfo brickSkillInfo = skillInfos[i];
			brickSkillInfo.OnInit();
			DicSkill.Add(brickSkillInfo.skillId, brickSkillInfo);
		}
	}

	public void UnRegisterAllSkill()
	{
		DicSkill.Clear();
	}

	public void SetRecoveryEnerey(FP Enerey)
	{
		recoveryEnerey = Enerey;
	}

	public void SetRecoveryEnerey_Rate(FP rate)
	{
		recoveryEnerey_rate = rate;
	}

	public void OnLogicUpdate(FP deltaTime)
	{
		foreach (BrickSkillInfo value in DicSkill.Values)
		{
			if (!value.IsFull && value.autoCd)
			{
				FP val = value.curSkillEnergy + recoveryEnerey_rate * recoveryEnerey * deltaTime;
				FP maxSkillEnergy = value.maxSkillEnergy;
				value.curSkillEnergy = TSMath.Min(val, maxSkillEnergy);
				value.curTime -= deltaTime;
				value.curTime = TSMath.Min(0, value.skillCd);
			}
		}
	}

	public bool CanExcute(int skillId)
	{
		if (DicSkill.TryGetValue(skillId, out var value))
		{
			return value.IsFull;
		}
		return false;
	}

	public void ResetEnergy(int skillId, bool auto = true)
	{
		if (DicSkill.TryGetValue(skillId, out var value))
		{
			value.Clear();
			value.autoCd = auto;
			SyncLua(value);
		}
	}

	public void ModifyEnergyByAbs(int skillId, FP energy)
	{
		if (DicSkill.TryGetValue(skillId, out var value))
		{
			value.curSkillEnergy += energy * recoveryEnerey_rate;
			value.curSkillEnergy = TSMath.Min(value.curSkillEnergy, value.maxSkillEnergy);
			SyncLua(value);
		}
	}

	public void ModifyEnergyByPercent(int skillId, FP percent)
	{
		if (DicSkill.TryGetValue(skillId, out var value))
		{
			value.curSkillEnergy += value.maxSkillEnergy * percent / 100f;
			value.curSkillEnergy = TSMath.Min(value.curSkillEnergy, value.maxSkillEnergy);
			SyncLua(value);
		}
	}

	private void SyncLua(BrickSkillInfo skillInfo)
	{
		MonoSingleton<LuaManager>.Instance?.FireEvent("BrickActorEnergy", Owner.dataID, skillInfo.skillId, skillInfo.curSkillEnergy, skillInfo.maxSkillEnergy, recoveryEnerey, skillInfo.curTime);
	}
}
public class BrickBreakerController : AdventureLevelController
{
	private BreakOutFloor floorData;

	private bool isStartTime;

	private FP timeing = 0;

	private int totalTime;

	private int timeLimit;

	private int currentLife;

	private int currentScrole;

	private int destructCount;

	private int roleId;

	protected bool isSettlement;

	protected const string ZoomFreezeKey = "ZoomFreeze";

	protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

	protected float _zoomFreeze;

	protected float _zoomDurationTime;

	protected UIGameSystemSetup.TimeLinePlayType timeLinePlayType;

	public Text textScrole;

	public Text textLife;

	public Text textLeftTime;

	private List<int> dropIdsPool;

	private List<int> dropParmas;

	private void InitActor(int roleID)
	{
		if (roleId <= 0)
		{
			NovaLogger.Error("打砖块角色 id==" + roleID);
		}
		else
		{
			SpawnRole(roleID, TSVector2.zero, 0, 0, RoleSpawn);
		}
		static void RoleSpawn(BrickActor _actor)
		{
			Singleton<BrickBreakerManager>.Instance.InitActor(_actor);
			_actor.LogicActive();
		}
	}

	private void SpawnRole(int roleID, TSVector2 pos, FP posY, FP rot, Action<BrickActor> callback)
	{
		BreakOutCharacter breakOutCharacter = Singleton<HotfixDataController>.Instance.GetBreakOutCharacter(roleID);
		if (breakOutCharacter == null)
		{
			NovaLogger.Error($"打砖块角色没有找到数据:{roleID}");
			return;
		}
		string model = breakOutCharacter.Model;
		if (string.IsNullOrEmpty(model))
		{
			return;
		}
		string loadPath = "Assets/AssetBundles/" + model + ".prefab";
		AdventureLevelObjPoolMgr.PoolBase poolBase = SceneSingleton<AdventureLevelObjPoolMgr>.Instance.De_Player(loadPath);
		if (poolBase == null)
		{
			NovaLogger.Error($"ID={roleID}的角色资源不存在");
			return;
		}
		poolBase.Enabled(enable: true);
		AdventureLevelObjPoolMgr.PoolObj poolObj = poolBase as AdventureLevelObjPoolMgr.PoolObj;
		GameObject gameObject = poolObj.gameObject;
		if (gameObject == null)
		{
			NovaLogger.Error($"ID={roleID}的角色资源不存在");
			return;
		}
		BrickActor brickActor = gameObject.AddOrGetComponent<BrickActor>();
		if (brickActor == null)
		{
			NovaLogger.Error($"ID={roleID}BrickActor get fail");
			return;
		}
		brickActor.SyncMovementLocation(pos, posY, rot);
		brickActor.enabled = true;
		brickActor.isDeclareDead = false;
		brickActor.LoadData(breakOutCharacter);
		brickActor.spawnPoolObj = poolObj;
		brickActor.LevelStart();
		callback(brickActor);
	}

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		MonoSingleton<GameController>.Instance.teamConfig = null;
		base.Load(param, callback);
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		floorData = Singleton<HotfixDataController>.Instance.GetBreakOutFloor(CommonHelper.ParseStringParamToInt(param.id));
		string[] enterDynamicLevelParams = param.enterDynamicLevelParams;
		if (enterDynamicLevelParams != null && enterDynamicLevelParams.Length != 0)
		{
			roleId = CommonHelper.ParseStringParamToInt(param.enterDynamicLevelParams[0]);
		}
		if (floorData != null)
		{
			timeLimit = floorData.Time;
			musicName = floorData.BGM;
			leaveMusicEvent = floorData.LeaveTriggerEvent;
			currentLife = floorData.Heart;
			currentScrole = 0;
			scenePath = "Assets/AssetBundles/" + floorData.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
		}
		else
		{
			Debug.LogError("平衡性测试关卡 data is null");
		}
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		string assetName = scenePath + "/" + floorData.ConfigPrefabName + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = floorData.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + floorData.ConfigPrefabName);
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(floorData.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
				}
				UnityEngine.Transform transform2 = gameObject2.transform.Find("==== BrikNode ====");
				if (transform2 != null)
				{
					DestructibleObject[] componentsInChildren2 = transform2.GetComponentsInChildren<DestructibleObject>();
					destructCount = componentsInChildren2.Length;
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
			if (gameObject2.name.Equals("Canvas"))
			{
				Text[] componentsInChildren3 = gameObject2.GetComponentsInChildren<Text>();
				textScrole = componentsInChildren3[0];
				textLife = componentsInChildren3[1];
				textLeftTime = componentsInChildren3[2];
				textLeftTime.text = $"剩余时间:{timeLimit - totalTime}";
				textLife.text = $"剩余生命:{currentLife}";
				isStartTime = true;
				currentLife = floorData.Heart;
			}
		}
		InitActor(roleId);
		base.LevelLoadComplete(sceneName);
	}

	public override void LevelStart(System.Action callback = null)
	{
		base.LevelStart();
		timeLinePlayType = Singleton<UIGameSystemSetup>.Instance.PlayType;
		Singleton<UIGameSystemSetup>.Instance.PlayType = UIGameSystemSetup.TimeLinePlayType.everyTime;
		totalTime = 0;
		timeing = 0;
		isStartTime = true;
		isSettlement = false;
		callback?.Invoke();
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("DESTRUCTIBLEOBJECT_DIE", OnDestructDie);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDie);
		OnDropEventLisenterAdd();
	}

	public override void LevelEnd()
	{
		base.LevelEnd();
		isStartTime = false;
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("DESTRUCTIBLEOBJECT_DIE", OnDestructDie);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDie);
		OnDropEventLisenterRemove();
		Singleton<UIGameSystemSetup>.Instance.PlayType = timeLinePlayType;
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		if (isStartTime)
		{
			timeing += logicDeltaTime;
			if (totalTime >= timeLimit)
			{
				isStartTime = false;
				LevelStateChanged(GameEnum.levelState.Failed);
				MonoSingleton<LuaManager>.Instance.FireEvent("BrickBreaker_Time", 0);
			}
			else if (timeing >= 1)
			{
				totalTime++;
				textLeftTime.text = $"剩余时间:{timeLimit - totalTime}";
				MonoSingleton<LuaManager>.Instance.FireEvent("BrickBreaker_Time", timeLimit - totalTime);
				timeing -= (FP)1;
			}
		}
	}

	private void StartTiming(IEvent evt)
	{
		isStartTime = true;
	}

	private void OnDestructDie(IEvent evt)
	{
		if (evt is DestructibleObjectBeDestoryEvent { configID: var configID } destructibleObjectBeDestoryEvent)
		{
			DestroyObjectSpr destroyObjectSpr = Singleton<HotfixDataController>.Instance.GetDestroyObjectSpr((int)configID);
			if (destroyObjectSpr == null)
			{
				NovaLogger.Error("NULL tDestroyObjectSpr===" + configID);
				return;
			}
			UpdateScrole(destroyObjectSpr.Score);
			ShowDropItem(destructibleObjectBeDestoryEvent.pos);
		}
	}

	private void OnMonsterDie(IEvent evt)
	{
		if (!(evt is AdventureMonsterDiedEvent { monsterID: var monsterID } adventureMonsterDiedEvent))
		{
			return;
		}
		BreakOutEnemySpr breakOutEnemySpr = Singleton<HotfixDataController>.Instance.GetBreakOutEnemySpr(monsterID);
		if (breakOutEnemySpr == null)
		{
			NovaLogger.Error("NULL BreakOutEnemySp===" + monsterID);
			return;
		}
		UpdateScrole(breakOutEnemySpr.Score);
		if (adventureMonsterDiedEvent.sender is LogicEntity logicEntity)
		{
			ShowDropItem(logicEntity.tsTransform.Position);
		}
	}

	protected void LevelStateChangedCall(GameEnum.levelState levelState)
	{
		if (!isSettlement)
		{
			isStartTime = false;
			isSettlement = true;
			MonoSingleton<LuaManager>.Instance.FireEvent("BrickBreaker_GameEnd", timeing.AsFloat());
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
			ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
		}
		void Action()
		{
			LevelStateChanged(levelState);
		}
	}

	public void UpdateLife(int life)
	{
		currentLife += life;
		if (currentLife < 0)
		{
			currentLife = 0;
		}
		MonoSingleton<LuaManager>.Instance.FireEvent("BrickBreaker_Life", currentLife);
		if (currentLife == 0)
		{
			LevelStateChangedCall(GameEnum.levelState.Failed);
		}
		textLife.text = $"剩余生命:{currentLife}";
	}

	public void UpdateScrole(int scrole)
	{
		currentScrole += scrole;
		MonoSingleton<LuaManager>.Instance.FireEvent("BrickBreaker_Scrole", currentScrole);
		textScrole.text = $"获得分数:{currentScrole}";
	}

	public override void InitSpawnPoints()
	{
		base.InitSpawnPoints();
		if (!base.isViewSceneMode)
		{
			HandleSpawnGizmos();
		}
	}

	public override void HandleSpawnGizmos()
	{
		base.HandleSpawnGizmos();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			base.monsterSpawnWaves[i].Initialize(-1, -1);
		}
		for (int j = 0; j < base.trapGroups.Count; j++)
		{
			base.trapGroups[j].Initialize(-1, -1);
		}
		PreloadAssets();
		for (int k = 0; k < base.monsterSpawnWaves.Count; k++)
		{
			if (!base.monsterSpawnWaves[k].isTriggerActived)
			{
				base.monsterSpawnWaves[k].EnableSpawnLogic();
			}
		}
		InitMonsterAndDestructCount();
		for (int l = 0; l < base.trapGroups.Count; l++)
		{
			base.trapGroups[l].EnableSpawnLogic();
		}
	}

	private void OnDropEventLisenterAdd()
	{
		ModuleController<AdventureModuleController>.Instance.AddEventListener("DROP_EFFECT_FINISH", OnDropFinish);
	}

	private void OnDropEventLisenterRemove()
	{
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("DROP_EFFECT_FINISH", OnDropFinish);
	}

	private void GetMonsterCount(BaseSpawnPointGizmo pointGizmo, ref int count)
	{
		if (pointGizmo is MonsterSpawnPointGizmo { monsterID: >0 })
		{
			count++;
			return;
		}
		List<BaseSpawnPointGizmo> childrenGizmos = pointGizmo.childrenGizmos;
		if (childrenGizmos != null && childrenGizmos.Count > 0)
		{
			for (int i = 0; i < pointGizmo.childrenGizmos.Count; i++)
			{
				GetMonsterCount(pointGizmo.childrenGizmos[i], ref count);
			}
		}
	}

	private void InitMonsterAndDestructCount()
	{
		int count = destructCount;
		if (base.monsterSpawnWaves.Count > 0)
		{
			for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
			{
				GetMonsterCount(base.monsterSpawnWaves[i], ref count);
			}
		}
		InitDropPool((floorData.Drops != null) ? floorData.Drops.Count : 0, count);
	}

	private void Shuffle<T>(List<T> list, List<T> listP)
	{
		System.Random random = new System.Random();
		for (int num = list.Count - 1; num > 0; num--)
		{
			int index = random.Next(num + 1);
			T value = list[num];
			list[num] = list[index];
			list[index] = value;
			T value2 = listP[num];
			listP[num] = listP[index];
			listP[index] = value2;
		}
	}

	private void InitDropPool(int indexCount, int monsterCount)
	{
		if (indexCount <= 0)
		{
			return;
		}
		List<int> list = new List<int>();
		List<int> list2 = new List<int>();
		for (int i = 0; i < indexCount; i++)
		{
			int num = floorData.Counts[i];
			for (int j = 0; j < num; j++)
			{
				list.Add(floorData.Drops[i]);
				list2.Add(floorData.DropParam[i]);
			}
		}
		if (list.Count >= monsterCount)
		{
			Shuffle(list, list2);
			dropIdsPool = list;
			dropParmas = list2;
			return;
		}
		dropIdsPool = new List<int>();
		dropParmas = new List<int>();
		List<int> list3 = new List<int>(monsterCount);
		for (int k = 0; k < monsterCount; k++)
		{
			list3.Add(k);
			dropIdsPool.Add(0);
			dropParmas.Add(0);
		}
		System.Random random = new System.Random();
		for (int l = 0; l < list.Count; l++)
		{
			int index = random.Next(list3.Count);
			int index2 = list3[index];
			dropIdsPool[index2] = list[l];
			dropParmas[index2] = list2[l];
			list3.RemoveAt(index);
		}
	}

	private (int, int) GetRandomDropId()
	{
		if (dropIdsPool.Count > 0)
		{
			int item = dropIdsPool[0];
			int item2 = dropParmas[0];
			dropIdsPool.RemoveAt(0);
			dropParmas.RemoveAt(0);
			return (item, item2);
		}
		return (0, 0);
	}

	private void ShowDropItem(TSVector2 pos)
	{
		var (num, paramasValue) = GetRandomDropId();
		if (num > 0)
		{
			(SceneSingleton<DropsManager>.Instance.PlayBrickDrop(num, pos) as BrickDrop)?.SetParamasValue(paramasValue);
		}
	}

	private void OnDropFinish(IEvent evt)
	{
		AdventureDropFinishEvent adventureDropFinishEvent = evt as AdventureDropFinishEvent;
		if (adventureDropFinishEvent.isPickUp && adventureDropFinishEvent.sender is BrickDrop dropItem)
		{
			Singleton<BrickBreakerManager>.Instance.OnGetDropItem(dropItem);
		}
	}
}
public class BrickBreakerManager : Singleton<BrickBreakerManager>
{
	private int exceptDropScro;

	private readonly List<Gear_BlackHole> _blackHoleList = new List<Gear_BlackHole>(3);

	private readonly List<Gear_BouncePole> _speedBouncePoleList = new List<Gear_BouncePole>(3);

	private List<GearBase> _gearList = new List<GearBase>(8);

	public Brick_Paddle Paddle { get; private set; }

	public Brick_Ball BrickBall { get; private set; }

	public PaddleCollider CurrentPaddleCollider { get; private set; }

	public BrickActor Actor { get; private set; }

	public bool IsLaunched { get; private set; }

	public void InitPaddle(Brick_Paddle paddle)
	{
		Paddle = paddle;
	}

	public void InitBall(Brick_Ball ball)
	{
		BrickBall = ball;
	}

	public void InitActor(BrickActor _actor)
	{
		Actor = _actor;
		if (!(CurrentPaddleCollider == null))
		{
			Actor.tsTransform.Position = CurrentPaddleCollider.tsTransform.Position;
		}
	}

	public void ResetBalltoPaddle()
	{
		if (!(Paddle == null) && !(BrickBall == null))
		{
			BrickBall.ResetOnPaddle();
			SwitchPaddle(0);
			ResetBouncePoleAddSpeed();
		}
	}

	public void BallLaunchState(bool launch)
	{
		IsLaunched = launch;
		if (!launch)
		{
			ResetBalltoPaddle();
		}
	}

	public void SwitchPaddle(int index)
	{
		if (!(Paddle == null))
		{
			Paddle.SwitchPaddle(index);
		}
	}

	public void ChangePaddleCollider(PaddleCollider paddleC)
	{
		CurrentPaddleCollider = paddleC;
		CurrentPaddleCollider.dtcollider.collisionListener = Paddle;
	}

	public FP GetPaddleColliderIndex(DeterministicRaycastHit dRaycastHit)
	{
		if (dRaycastHit.isValid && CurrentPaddleCollider != null)
		{
			FP rayCastColliderPointToLocalPercent = CurrentPaddleCollider.GetRayCastColliderPointToLocalPercent(dRaycastHit);
			return Paddle.GetFixAngle(rayCastColliderPointToLocalPercent);
		}
		return 0;
	}

	public bool CheckInArea(TSVector2 pos)
	{
		FP fP = CurrentPaddleCollider.tsTransform.Position.y - 5;
		float num = Paddle.xLimit + 5f;
		bool result = true;
		if (pos.y < fP || pos.y > fP + 50)
		{
			result = false;
		}
		if (pos.x > num || pos.x < 0f - num)
		{
			result = false;
		}
		return result;
	}

	public void UpdateLife(int life)
	{
		if (ModuleController<AdventureModuleController>.Instance.levelInstance is BrickBreakerController brickBreakerController)
		{
			brickBreakerController.UpdateLife(life);
		}
	}

	public void UpdateScrole(int scrole)
	{
		if (scrole != 0 && ModuleController<AdventureModuleController>.Instance.levelInstance is BrickBreakerController brickBreakerController)
		{
			brickBreakerController.UpdateScrole(scrole);
		}
	}

	public void OnGetDropItem(BrickDrop dropItem)
	{
		if (dropItem == null)
		{
			return;
		}
		bool flag = true;
		switch (dropItem.dropType)
		{
		case HotfixEnum.BrickDropType.BrickFire:
			BrickBall.SwitchBall(1);
			break;
		case HotfixEnum.BrickDropType.BrickBoom:
			UpdateLife(-1);
			break;
		case HotfixEnum.BrickDropType.BrickEnergy:
			if (Actor != null)
			{
				Actor.skillMgr?.ModifyEnergyByAbs(Actor.mainSkillId, dropItem.SpecialParmas);
			}
			break;
		case HotfixEnum.BrickDropType.BrickExpCoin:
			UpdateScrole(dropItem.SpecialParmas);
			break;
		case HotfixEnum.BrickDropType.BrickHp:
			UpdateLife(1);
			break;
		case HotfixEnum.BrickDropType.BrickPaddle:
			SwitchPaddle(dropItem.SpecialParmas);
			break;
		default:
			flag = false;
			break;
		}
		if (flag)
		{
			UpdateScrole(exceptDropScro);
		}
	}

	public void SetExceptDropScro(int exceptScro)
	{
		exceptDropScro = exceptScro;
	}

	public void AddOrRemoveBlackHole(Gear_BlackHole blackHole, bool iAdd = true)
	{
		if (blackHole == null)
		{
			return;
		}
		if (iAdd)
		{
			if (!_blackHoleList.Contains(blackHole))
			{
				_blackHoleList.Add(blackHole);
			}
		}
		else if (_blackHoleList.Contains(blackHole))
		{
			_blackHoleList.Remove(blackHole);
		}
	}

	public bool HaveGriavity()
	{
		return _blackHoleList.Count > 0;
	}

	public (TSVector2, FP) CaculateGriavityDirAndDis(ref TSVector2 moveData)
	{
		TSVector2 tSVector = moveData;
		TSVector2 tSVector2;
		FP fP;
		for (int i = 0; i < _blackHoleList.Count; i++)
		{
			if (!_blackHoleList[i].inTriggerCD)
			{
				TrueSyncTransform tsTransform = _blackHoleList[i].tsTransform;
				tSVector2 = tsTransform.Position - BrickBall.tsTransform.Position;
				fP = TSVector2.Distance(BrickBall.tsTransform.Position, tsTransform.Position);
				FP fP2 = _blackHoleList[i].gravitySpeed * BrickBall.LogicDeltaTime;
				if (fP2 > fP)
				{
					fP2 = fP;
				}
				tSVector += tSVector2.normalized * fP2 * _blackHoleList[i].angle_change_rat;
				moveData += tSVector2.normalized * fP2;
			}
		}
		tSVector2 = tSVector.normalized;
		fP = FP.Sqrt(moveData.LengthSquared());
		return (tSVector2, fP);
	}

	public Gear_BouncePole IsGearBouncePole(DeterministicRaycastHit dRaycastHit)
	{
		if (_gearList.Find((GearBase gearBase) => gearBase.Id == dRaycastHit.collider.Entity.Id) is Gear_BouncePole gear_BouncePole)
		{
			gear_BouncePole.AddSpeed();
			if (!_speedBouncePoleList.Contains(gear_BouncePole))
			{
				_speedBouncePoleList.Add(gear_BouncePole);
			}
			return gear_BouncePole;
		}
		return null;
	}

	public FP GetBouncePoleAddSpeed()
	{
		if (_speedBouncePoleList.Count <= 0)
		{
			return 0;
		}
		FP result = 0;
		for (int num = _speedBouncePoleList.Count - 1; num >= 0; num--)
		{
			if (_speedBouncePoleList[num].Add_Speed > 0)
			{
				result += _speedBouncePoleList[num].Add_Speed;
			}
			else
			{
				_speedBouncePoleList.RemoveAt(num);
			}
		}
		return result;
	}

	public void ResetBouncePoleAddSpeed()
	{
		_speedBouncePoleList.Clear();
	}

	public long GetGearToScence(string fxAlias, TSVector2 position = default(TSVector2), FP rotation = default(FP))
	{
		if (string.IsNullOrEmpty(fxAlias))
		{
			return 0L;
		}
		fxAlias = "Assets/AssetBundles/" + fxAlias + ".prefab";
		GameObject gameObject = GameResourceLoader.LoadAsset(GameResourceLoader.ResourceType.Any, fxAlias, typeof(GameObject)) as GameObject;
		if (gameObject == null)
		{
			Debug.LogError("机关资源不存在:" + fxAlias);
			return 0L;
		}
		Vector3 spawnPosition = new Vector3((float)position.x, 0f, (float)position.y);
		Quaternion spawnRotation = Quaternion.Euler(0f, 0f - (float)rotation, 0f);
		GearBase gearBase = Spawn(gameObject, spawnPosition, spawnRotation);
		if (gearBase != null)
		{
			return gearBase.Id;
		}
		return 0L;
	}

	public void ClearGearById(long id)
	{
		if (id > 0)
		{
			GearBase gearBase = _gearList.Find((GearBase gearBase2) => gearBase2.Id == id);
			if (gearBase != null)
			{
				gearBase.ActiveSelf = false;
			}
		}
	}

	public void ClearAllGear()
	{
		if (_gearList.Count > 0)
		{
			for (int num = _gearList.Count - 1; num >= 0; num--)
			{
				_gearList[num].ActiveSelf = false;
			}
		}
	}

	protected GearBase Spawn(GameObject fxPrefab, Vector3 spawnPosition, Quaternion spawnRotation)
	{
		SpawnPool spawnPool = PoolManager.Pools["Effect"];
		UnityEngine.Transform transform = ((!(spawnPool != null)) ? UnityEngine.Object.Instantiate(fxPrefab, spawnPosition, spawnRotation).transform : spawnPool.Spawn(fxPrefab.transform, spawnPosition, spawnRotation));
		transform.SetParent(ObjectPoolUtils.GetPoolRootNode("Effect"));
		if (transform.TryGetComponent<GearBase>(out var component))
		{
			_gearList.Add(component);
			return component;
		}
		spawnPool.Despawn(transform, spawnPool.group);
		return null;
	}

	public void Despawn(GearBase entity)
	{
		_gearList.Remove(entity);
		if (PoolManager.Pools.TryGetValue("Effect", out var spawnPool))
		{
			spawnPool.Despawn(entity.transform, spawnPool.group);
		}
	}
}
public class Brick_Ball : LogicEntity, IHitBoxContext
{
	public FP read_initialSpeed = 8f;

	public float normal_maxSpeed = 15f;

	public float limitSpeed = 25f;

	public float minSpeed = 5f;

	public FP read_changeSpeed = 1f;

	public FP random_Angle = 5f;

	public GameObject[] BallSkin;

	private Collider collider;

	private const int hitableLayerMask_Default = 4264192;

	private TSVector2 startPosition;

	private TSVector2 moveDirection;

	private FP chSpeed;

	private int wallIndex;

	private int ballIndex;

	private FP limit_paddleReflectAngle = 80;

	public int hitDamageId;

	public HitBox.FeatureFlag hitFlags;

	public HitBox.HitBoxFeatureData hitFeatureData;

	public HitBox.HurtAnimType hurtAnimType = HitBox.HurtAnimType.Small;

	public GameObject hittedEffectPrefab;

	public bool isHittedEffectScale = true;

	public bool effectIgnoreTimeScale = true;

	public FP damageImmuneDuration;

	protected Dictionary<long, FP> _hitedEntities = new Dictionary<long, FP>(10);

	protected List<int> _hitIds = new List<int>();

	public DeterministicCollider dtCollider { get; private set; }

	public HitBox Hit_Box { get; private set; }

	protected AdventureActor Player => Singleton<BrickBreakerManager>.Instance.Actor;

	protected int UniqueAttackId
	{
		get
		{
			if (SceneSingleton<AdventurePlayerController>.Instance != null)
			{
				return SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId();
			}
			return 0;
		}
	}

	protected override void OnInit()
	{
		startPosition = base.tsTransform.Position;
		DeterministicCollider deterministicCollider = null;
		this.SetDeterministicCollider(ref collider, ref deterministicCollider);
		dtCollider = deterministicCollider;
		base.gameObject.layer = 23;
		OnHitDataInit();
		Singleton<BrickBreakerManager>.Instance.InitBall(this);
	}

	protected override void OnActive()
	{
		EnableLogicUpdate();
		SwitchBall(0);
		Singleton<BrickBreakerManager>.Instance.BallLaunchState(launch: false);
	}

	protected override void OnDeactive()
	{
	}

	protected override void OnShutdown()
	{
	}

	private int GetBallHitLayMask()
	{
		return 4264192;
	}

	protected override void OnLogicUpdate()
	{
		if (!Singleton<BrickBreakerManager>.Instance.IsLaunched)
		{
			FP x = Singleton<BrickBreakerManager>.Instance.CurrentPaddleCollider.tsTransform.Position.x;
			base.tsTransform.Position = new TSVector2(x, startPosition.y);
			return;
		}
		FP fP = Mathf.Clamp((float)(Mathf.Clamp((float)(read_initialSpeed + chSpeed), minSpeed, normal_maxSpeed) + Singleton<BrickBreakerManager>.Instance.GetBouncePoleAddSpeed()), minSpeed, limitSpeed) * base.LogicDeltaTime;
		TSVector2 moveData = moveDirection * fP;
		if (Singleton<BrickBreakerManager>.Instance.HaveGriavity())
		{
			(moveDirection, fP) = Singleton<BrickBreakerManager>.Instance.CaculateGriavityDirAndDis(ref moveData);
		}
		TSVector2 origin = base.tsTransform.Position;
		TSVector2 direction = moveDirection;
		FP fP2 = fP;
		if (SceneSingleton<DeterministicCollisionManager>.Instance.SphereCastHit(ref origin, ref direction, out var hitInfo, fP2, dtCollider.Radius, GetBallHitLayMask()))
		{
			bool flag = true;
			bool hitWall = false;
			bool flag2 = false;
			int layer = hitInfo.collider.gameObject.layer;
			FP fP3 = 0;
			switch (layer)
			{
			case 12:
				hitWall = true;
				break;
			case 8:
				HitTarget(ref hitInfo);
				if (ballIndex != 0)
				{
					flag = false;
				}
				break;
			case 16:
				HitTarget(ref hitInfo);
				if (ballIndex != 0)
				{
					flag = false;
				}
				break;
			case 22:
			{
				Gear_BouncePole gear_BouncePole = Singleton<BrickBreakerManager>.Instance.IsGearBouncePole(hitInfo);
				if (gear_BouncePole != null)
				{
					gear_BouncePole.PlayHitFx(hitInfo.point, base.transform.rotation);
					break;
				}
				flag2 = true;
				fP3 = Singleton<BrickBreakerManager>.Instance.GetPaddleColliderIndex(hitInfo);
				break;
			}
			default:
				flag = false;
				break;
			}
			if (flag)
			{
				chSpeed += read_changeSpeed;
				fP3 += ReflectAngleFix(hitWall);
				FP fP4 = TSMath.Max(fP2 - hitInfo.distance, 0);
				TSVector2 tSVector = TSVector2.Reflect(moveDirection, hitInfo.normal).normalized;
				if (fP3 != 0)
				{
					tSVector = TSVector2.Rotate(tSVector, fP3);
				}
				if (flag2)
				{
					tSVector = FixPaddleReflectAngle(tSVector);
				}
				TSVector2 point = hitInfo.point;
				if (fP4 > 0)
				{
					point += tSVector * fP4;
				}
				base.tsTransform.Position = point;
				moveDirection = tSVector;
			}
			else
			{
				base.tsTransform.Position += moveData;
			}
		}
		else
		{
			base.tsTransform.Position += moveData;
		}
		base.tsTransform.Forward = moveDirection;
		CheckOutArea();
	}

	private TSVector2 FixPaddleReflectAngle(TSVector2 reflectDirection)
	{
		FP angle = reflectDirection.GetAngle();
		if (angle < -limit_paddleReflectAngle)
		{
			return TSVector2.Rotate(reflectDirection, -limit_paddleReflectAngle - angle);
		}
		if (angle > limit_paddleReflectAngle)
		{
			return TSVector2.Rotate(reflectDirection, limit_paddleReflectAngle - angle);
		}
		return reflectDirection;
	}

	private FP ReflectAngleFix(bool hitWall)
	{
		FP fP = TSRandom.Range(-random_Angle, random_Angle);
		if (hitWall)
		{
			wallIndex++;
			if (wallIndex > 3)
			{
				return fP + TSRandom.Range(-30, 30);
			}
		}
		else
		{
			wallIndex = 0;
		}
		return fP;
	}

	private void CheckOutArea()
	{
		if (!Singleton<BrickBreakerManager>.Instance.CheckInArea(base.tsTransform.Position))
		{
			Singleton<BrickBreakerManager>.Instance.BallLaunchState(launch: false);
			Singleton<BrickBreakerManager>.Instance.UpdateLife(-1);
		}
	}

	public void SwitchBall(int newSkinIndex)
	{
		if (BallSkin.Length >= newSkinIndex + 1)
		{
			ballIndex = newSkinIndex;
			for (int i = 0; i < BallSkin.Length; i++)
			{
				BallSkin[i].SetActive(i == ballIndex);
			}
			ChangeHitId();
		}
	}

	public void ResetOnPaddle()
	{
		chSpeed = 0;
		FP x = Singleton<BrickBreakerManager>.Instance.CurrentPaddleCollider.tsTransform.Position.x;
		base.tsTransform.Position = new TSVector2(x, startPosition.y);
		moveDirection = TSVector2.up;
		base.tsTransform.Forward = moveDirection;
		SwitchBall(0);
	}

	protected void OnHitDataInit()
	{
		Hit_Box = HitBox.Setup(base.gameObject, this, this);
		Hit_Box.hitDamageId = hitDamageId;
		Hit_Box.featureFlags = hitFlags;
		Hit_Box.featureData = hitFeatureData;
		Hit_Box.hurtAnimType = hurtAnimType;
		for (int i = 0; i < BallSkin.Length; i++)
		{
			_hitIds.Add(hitDamageId);
		}
	}

	protected void HitTarget(ref DeterministicRaycastHit raycastHit)
	{
		if (!(Hit_Box == null))
		{
			Hit_Box.HitSingleTarget(UniqueAttackId, raycastHit.collider, out var _, out var _, ref raycastHit, hittedEffectPrefab, isHittedEffectScale, damageImmuneDuration, 1, effectIgnoreTimeScale);
		}
	}

	protected void ChangeHitId()
	{
		if (_hitIds.Count > ballIndex)
		{
			Hit_Box.hitDamageId = _hitIds[ballIndex];
		}
	}

	public void SetBallHitId(int hitId, int index)
	{
		if (_hitIds.Count > index)
		{
			_hitIds[index] = hitId;
		}
	}

	public FP QueryHitBoxContextTime()
	{
		return base.LogicTime;
	}

	public TSVector2 QueryHitBoxContextPosition()
	{
		return base.tsTransform.Position;
	}

	public TSVector2 QueryHitBoxContextDirection()
	{
		return base.tsTransform.Forward;
	}

	public bool QueryActorHitedTimeout(long entityId, FP timeout)
	{
		if (_hitedEntities.TryGetValue(entityId, out var value) && base.LogicTime <= value + timeout)
		{
			return false;
		}
		return true;
	}

	public void SetActorHitedTime(long entityId, FP time)
	{
		_hitedEntities[entityId] = time;
	}

	public bool CheckHitable(HitBox hitBox, LogicEntity entity)
	{
		if (!(Player == null) && (hitBox.featureFlags & HitBox.FeatureFlag.NoDiffDamage) != HitBox.FeatureFlag.NoDiffDamage && !Player.IsConfrontWith(entity))
		{
			return Player.IsNeutralWith(entity);
		}
		return true;
	}

	public bool OnHitActor(HitBox hitBox, int uniqueAttackId, int onceAttackTargetCount, LogicEntity entity, ref DeterministicRaycastHit raycastHit, out bool damaged, GameObject hurtEffectPrefab, bool isHittedEffectScale, bool effectIgnoreTimeScale = true)
	{
		damaged = false;
		if (Player == null)
		{
			return false;
		}
		if (!entity.GetLogicComponent<ActorHealthInfo>().isAlive)
		{
			return true;
		}
		(damaged, _, _) = (entity as AdventureActor).Damage((LogicEntity)Player, uniqueAttackId, onceAttackTargetCount, hitBox.hitDamageId, hurtEffectPrefab, hitBox, isHittedEffectScale, true, effectIgnoreTimeScale);
		return true;
	}

	public bool OnHitShield(HitBox hitBox, AdventureWeapon shield, ref DeterministicRaycastHit raycastHit)
	{
		return true;
	}

	public bool OnHitObstacle(HitBox hitBox, AdventureObstacle obstacle, ref DeterministicRaycastHit raycastHit)
	{
		return true;
	}

	public bool OnHitDestructibleObstacle(HitBox hitBox, int uniqueAttackId, int onceAttackTargetCount, LogicEntity actor, ref DeterministicRaycastHit raycastHit, out bool damaged, GameObject hurtEffectPrefab, bool isHittedEffectScale, bool effectIgnoreTimeScale = true)
	{
		damaged = false;
		if (Player == null)
		{
			return false;
		}
		AdventureActor component = actor.GetComponent<AdventureActor>();
		if (!component.CurrentStepCanbeHurt())
		{
			return true;
		}
		(damaged, _, _) = component.Damage((LogicEntity)Player, uniqueAttackId, onceAttackTargetCount, hitBox.hitDamageId, hurtEffectPrefab, hitBox, isHittedEffectScale, true, effectIgnoreTimeScale);
		return true;
	}
}
public class BrickDrop : DropEntity
{
	public HotfixEnum.BrickDropType dropType = HotfixEnum.BrickDropType.BrickFire;

	public float moveSpeed = 5f;

	public DeterministicCollider dtCollider { get; private set; }

	public int SpecialParmas { get; private set; }

	public BrickDrop()
	{
		doType = DropObjType.brick;
		sameMaxCount = 999;
	}

	protected override void OnInit()
	{
		base.OnInit();
		dtCollider = AddOrGetMonoLogicComponent<DeterministicCollider>();
	}

	protected override void OnDeactive()
	{
		base.OnDeactive();
		SpecialParmas = 0;
	}

	public override void bornShow()
	{
		base.bornShow();
	}

	public override void Finish(bool isPick = false)
	{
		if (base.ActiveSelf)
		{
			if (isPick && takeEffectFx != null)
			{
				AdventureFXPlayer.PlayFX(takeEffectFx, 1f, cTrans.position, cTrans.rotation);
			}
			if (base.fxPlayer != null)
			{
				base.fxPlayer.Stop();
			}
			base.fxPlayer = null;
			AdventureDropFinishEvent adventureDropFinishEvent = AdventureDropFinishEvent.Generate();
			adventureDropFinishEvent.sender = this;
			adventureDropFinishEvent.entityID = base.Id;
			adventureDropFinishEvent.dropTag = dropTag;
			adventureDropFinishEvent.owner = base.owner;
			adventureDropFinishEvent.isPickUp = isPick;
			ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureDropFinishEvent);
			base.ActiveSelf = false;
		}
	}

	protected override void OnLogicUpdate()
	{
		if (isBornEnd)
		{
			TSVector2 tSVector = TSVector2.down * moveSpeed * base.LogicDeltaTime;
			base.tsTransform.Position += tSVector;
			if (!Singleton<BrickBreakerManager>.Instance.CheckInArea(base.tsTransform.Position))
			{
				Finish();
			}
		}
		else
		{
			_bornTime -= base.LogicDeltaTime;
			if (_bornTime < 0)
			{
				isBornEnd = true;
				base.tsTransform.PositionY = _spawnPos.y;
			}
		}
	}

	public void SetParamasValue(int paramas)
	{
		SpecialParmas = paramas;
	}
}
