public class Gear_BlackHole : GearBase, IDeterministicCollisionListener
{
	public int checkDuration;

	public FP angle_change_rat = 0.2;

	public FP gravitySpeed = 1;

	private DeterministicCollider targetCollier;

	private int currentFrameCount;

	public bool inTriggerCD { get; private set; }

	protected override void OnInit()
	{
		base.OnInit();
	}

	protected override void OnActive()
	{
		EnableLogicUpdate();
		dtCollider.collisionListener = this;
		targetCollier = Singleton<BrickBreakerManager>.Instance.BrickBall.dtCollider;
		inTriggerCD = false;
	}

	protected override void OnDeactive()
	{
		base.OnDeactive();
		Singleton<BrickBreakerManager>.Instance.AddOrRemoveBlackHole(this, iAdd: false);
	}

	protected override void OnShutdown()
	{
	}

	public int GetDration()
	{
		if (checkDuration > 0)
		{
			return checkDuration;
		}
		return 1;
	}

	private void CheckDuration()
	{
		currentFrameCount++;
		if (checkDuration > 1)
		{
			if (currentFrameCount >= checkDuration)
			{
				currentFrameCount = 0;
				inTriggerCD = false;
			}
			else
			{
				inTriggerCD = true;
			}
		}
		else
		{
			inTriggerCD = false;
		}
	}

	protected override void OnLogicUpdate()
	{
		int frameCount = LockStepManager.frameCount;
		targetCollier.ColliderSync();
		dtCollider.ColliderSync();
		SceneSingleton<DeterministicCollisionManager>.Instance.ContactEvaluate(frameCount, dtCollider, targetCollier, duplex: false);
		CheckDuration();
	}

	public void OnDeterministicCollisionEnter(DeterministicCollider other)
	{
		Singleton<BrickBreakerManager>.Instance.AddOrRemoveBlackHole(this);
	}

	public void OnDeterministicCollisionStay(DeterministicCollider other)
	{
	}

	public void OnDeterministicCollisionExit(DeterministicCollider other)
	{
		Singleton<BrickBreakerManager>.Instance.AddOrRemoveBlackHole(this, iAdd: false);
	}
}
