public class Brick_Paddle : LogicEntity, IDeterministicCollisionListener
{
	[Serializable]
	public class PaddleAngleData
	{
		public FP SpacePercent;

		public FP AngleFix;
	}

	public float moveSpeed = 10f;

	public float xLimit = 12.5f;

	public PaddleCollider normalPaddle;

	public PaddleCollider longPaddle;

	public PaddleCollider shortPaddle;

	[Space]
	public PaddleAngleData[] AngleFix_Datas;

	[Space]
	public TSVector2 actorOffeset;

	private TSVector2 currentPaddlePos;

	protected override void OnInit()
	{
		Singleton<BrickBreakerManager>.Instance.InitPaddle(this);
		currentPaddlePos = TSVector2.zero;
	}

	protected override void OnActive()
	{
		EnableLogicUpdate();
		SwitchPaddle(0);
	}

	protected override void OnDeactive()
	{
	}

	protected override void OnShutdown()
	{
	}

	protected override void OnLogicUpdate()
	{
		TSVector2 tSVector = MonoSingleton<InputManager>.Instance.GetAxis("Horizontal") * moveSpeed * (float)base.LogicDeltaTime * TSVector2.right;
		PaddleCollider currentPaddleCollider = Singleton<BrickBreakerManager>.Instance.CurrentPaddleCollider;
		currentPaddlePos = currentPaddleCollider.tsTransform.Position + tSVector;
		currentPaddlePos.x = Mathf.Clamp((float)currentPaddlePos.x, 0f - xLimit, xLimit);
		currentPaddleCollider.tsTransform.Position = currentPaddlePos;
		if (Singleton<BrickBreakerManager>.Instance.Actor != null)
		{
			Singleton<BrickBreakerManager>.Instance.Actor.tsTransform.Position = currentPaddlePos + actorOffeset;
		}
		currentPaddleCollider.dtcollider.ColliderSync();
		List<DropEntity> dropsList = SceneSingleton<DropsManager>.Instance._dropsList;
		if (dropsList != null && dropsList.Count > 0)
		{
			for (int i = 0; i < SceneSingleton<DropsManager>.Instance._dropsList.Count; i++)
			{
				if (SceneSingleton<DropsManager>.Instance._dropsList[i] is BrickDrop brickDrop)
				{
					brickDrop.dtCollider.ColliderSync();
					SceneSingleton<DeterministicCollisionManager>.Instance.ContactEvaluate(LockStepManager.frameCount, currentPaddleCollider.dtcollider, brickDrop.dtCollider, duplex: false);
				}
			}
		}
		AdventureModuleController instance = ModuleController<AdventureModuleController>.Instance;
		if ((object)instance != null && instance.weapons.Count > 0)
		{
			for (int j = 0; j < ModuleController<AdventureModuleController>.Instance.weapons.Count; j++)
			{
				if (ModuleController<AdventureModuleController>.Instance.weapons[j] is AdventureBullet adventureBullet)
				{
					adventureBullet.dtCollider.ColliderSync();
					SceneSingleton<DeterministicCollisionManager>.Instance.ContactEvaluate(LockStepManager.frameCount, currentPaddleCollider.dtcollider, adventureBullet.dtCollider, duplex: false);
				}
			}
		}
		TestButtonEvent();
	}

	public void SwitchPaddle(int index)
	{
		if (index <= 2 && index >= 0)
		{
			normalPaddle.ActiveSelf = index == 0;
			longPaddle.ActiveSelf = index == 1;
			shortPaddle.ActiveSelf = index == 2;
			if (currentPaddlePos != TSVector2.zero)
			{
				Singleton<BrickBreakerManager>.Instance.CurrentPaddleCollider.tsTransform.Position = currentPaddlePos;
			}
		}
	}

	public FP GetFixAngle(FP percent)
	{
		if (AngleFix_Datas == null || AngleFix_Datas.Length < 1)
		{
			return 0;
		}
		FP fP = 0;
		int num = 0;
		for (int i = 0; i < AngleFix_Datas.Length; i++)
		{
			fP += AngleFix_Datas[i].SpacePercent / 100;
			if (percent <= fP)
			{
				num = i;
				break;
			}
		}
		return AngleFix_Datas[num].AngleFix;
	}

	public void OnDeterministicCollisionEnter(DeterministicCollider other)
	{
		BrickDrop component = other.GetComponent<BrickDrop>();
		if (component != null)
		{
			component.Finish(isPick: true);
			return;
		}
		AdventureBullet component2 = other.GetComponent<AdventureBullet>();
		if (component2 != null)
		{
			if (component2.hitPrefab != null)
			{
				AdventureFXPlayer.PlayFX(component2.hitPrefab, 1f, component2.transform.position, component2.transform.rotation);
			}
			component2.Finish(cancel: true);
			Singleton<BrickBreakerManager>.Instance.UpdateLife(-1);
		}
	}

	public void OnDeterministicCollisionStay(DeterministicCollider other)
	{
	}

	public void OnDeterministicCollisionExit(DeterministicCollider other)
	{
	}

	private void TestButtonEvent()
	{
		if (Input.GetKey(KeyCode.R))
		{
			Singleton<BrickBreakerManager>.Instance.BallLaunchState(launch: false);
		}
		if (!Singleton<BrickBreakerManager>.Instance.IsLaunched && Input.GetKey(KeyCode.Space))
		{
			Singleton<BrickBreakerManager>.Instance.BallLaunchState(launch: true);
		}
	}
}
