public class EquipmentInstanceLevelController : AdventureLevelController
{
	private CharGemInstance equipmentInstanceData;

	private CharGemInstanceFloor equipmentInstanceFloor;

	private GameplayRoom room;

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		base.Load(param, callback);
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		if (base.isViewSceneMode)
		{
			equipmentInstanceFloor = Singleton<HotfixDataController>.Instance.GetCharGemInstanceFloor(param.floor);
		}
		else
		{
			equipmentInstanceData = Singleton<HotfixDataController>.Instance.GetCharGemInstance(CommonHelper.ParseStringParamToInt(param.id));
			equipmentInstanceFloor = Singleton<HotfixDataController>.Instance.GetCharGemInstanceFloor(equipmentInstanceData.FloorId);
		}
		if (equipmentInstanceFloor != null)
		{
			scenePath = "Assets/AssetBundles/" + equipmentInstanceFloor.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
			param.monsterLevel = equipmentInstanceFloor.MonsterLv;
			param.dropEntityGroupId = equipmentInstanceFloor.DropObjectGroupId;
			param.dropEntityRate = (float)equipmentInstanceFloor.DropObjectRate / 10000f;
			param.dropMaxNum = equipmentInstanceFloor.DropMaxNum;
			musicName = equipmentInstanceFloor.BGM;
			leaveMusicEvent = equipmentInstanceFloor.LeaveTriggerEvent;
		}
		else
		{
			Debug.LogError("EquipmentInstanceFloor data is null");
		}
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		string assetName = scenePath + "/" + equipmentInstanceFloor.ConfigPrefabName + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = equipmentInstanceFloor.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + equipmentInstanceFloor.ConfigPrefabName);
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(equipmentInstanceFloor.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
					List<AdventureLevelTeleporter> list = transform.GetComponentsInChildren<AdventureLevelTeleporter>().ToList();
					if (list != null && list.Count > 0)
					{
						for (int j = 0; j < list.Count; j++)
						{
							AdventureLevelTeleporter adventureLevelTeleporter = list[j];
							adventureLevelTeleporter.SetPosition(-1, -1);
							adventureLevelTeleporter.RegisterTeleporterCallback(LevelTeleporterTriggered);
						}
						teleporters.AddRange(list);
					}
				}
			}
			else if (gameObject2.name.Equals("==== Triggers ===="))
			{
				AdventureLevelTeleporter[] componentsInChildren2 = gameObject2.GetComponentsInChildren<AdventureLevelTeleporter>();
				if (componentsInChildren2 != null && componentsInChildren2.Length > 0)
				{
					foreach (AdventureLevelTeleporter obj in componentsInChildren2)
					{
						obj.SetPosition(-1, -1);
						obj.RegisterTeleporterCallback(LevelTeleporterTriggered);
					}
					teleporters.AddRange(componentsInChildren2);
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	public override bool HasTimelinePerformance()
	{
		int num;
		if (equipmentInstanceFloor != null)
		{
			num = ((!string.IsNullOrEmpty(equipmentInstanceFloor.IntroCutscene)) ? 1 : 0);
			if (num != 0)
			{
				timelineName = equipmentInstanceFloor.IntroCutscene;
			}
		}
		else
		{
			num = 0;
		}
		return (byte)num != 0;
	}

	public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
	{
		base.PlayTimelinePerformance(delegate
		{
			callback?.Invoke();
			MonoSingleton<LuaManager>.Instance.FireEvent("CloseJumpOverTimeLine");
			MonoSingleton<LuaManager>.Instance.FireEvent("TimeLineFinishBattleDashboardVisible", a1: true);
		}, needLimitPlayTimes);
	}

	public override void LevelStart(System.Action callback = null)
	{
		if (!base.isViewSceneMode)
		{
			InitRoom();
			room?.EntryRoom();
		}
		base.LevelStart(callback);
		callback?.Invoke();
	}

	private void InitRoom()
	{
		CharGemInstance charGemInstance = equipmentInstanceData;
		if (charGemInstance == null)
		{
			Debug.LogError("装备副本【EquipmentInstanceLevel】数据为空!");
			return;
		}
		GameplayRoomData gameplayRoomData = new GameplayRoomData
		{
			worldLevelType = GameEnum.worldLevelType.EquipmentInstance,
			floorId = equipmentInstanceFloor.Id,
			isReconnected = base.isReconnected,
			isBattleFinish = base.isBattleFinish,
			eventId = equipmentInstanceData.Type,
			monsterSpawnPointsGizmos = base.monsterSpawnWaves
		};
		switch (gameplayRoomData.eventId)
		{
		case 1:
			room = new EquipmentInstanceGameplayRoom_Circle();
			break;
		case 2:
			room = new EquipmentInstanceGameplayRoom_Pentagon();
			break;
		case 3:
			room = new EquipmentInstanceGameplayRoom_Square();
			break;
		}
		if (room == null)
		{
			Debug.LogError("副本房间为空!");
		}
		else
		{
			room?.InitRoom(gameplayRoomData, LevelStateChangedCallback);
		}
	}

	protected void LevelStateChangedCallback(GameEnum.levelState levelState, int star)
	{
		base._logger.LogInfo($"equipment level state changed:{levelState}");
		LevelStateChanged(levelState);
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		room?.UpdateLogic(logicDeltaTime);
	}

	public override void InitSpawnPoints()
	{
		base.InitSpawnPoints();
		StarTowerPorts starTowerPorts = UnityEngine.Object.FindObjectOfType<StarTowerPorts>();
		if (null != starTowerPorts)
		{
			starTowerPorts.gameObject.SetActive(value: false);
		}
		playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
		if (playerSpawnPoints == null || playerSpawnPoints.Count == 0)
		{
			Debug.LogError("关卡中没有配置玩家出生点!");
			return;
		}
		if (!string.IsNullOrEmpty(nextLevelData.bornID))
		{
			for (int i = 0; i < playerSpawnPoints.Count; i++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo = playerSpawnPoints[i];
				if (nextLevelData.bornID.Equals(playerSpawnPointGizmo.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			for (int j = 0; j < playerSpawnPoints.Count; j++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo2 = playerSpawnPoints[j];
				if (string.IsNullOrEmpty(playerSpawnPointGizmo2.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo2;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			base._logger.LogError("没有找到合适的角色出生点!");
			return;
		}
		base.playerSpawnPointGizmo.Initialize(0, 0);
		base.playerSpawnPointGizmo.EnableSpawnLogic();
		base.playerSpawnPointGizmo.ExecuteSpawnLogic();
		if (!base.isViewSceneMode)
		{
			HandleSpawnGizmos();
		}
	}

	public override void HandleSpawnGizmos()
	{
		base.HandleSpawnGizmos();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			base.monsterSpawnWaves[i].Initialize(-1, -1);
		}
		for (int j = 0; j < base.virtualMonsterSpawnWaves.Count; j++)
		{
			base.virtualMonsterSpawnWaves[j].Initialize(-1, -1);
		}
		for (int k = 0; k < base.trapGroups.Count; k++)
		{
			base.trapGroups[k].Initialize(-1, -1);
		}
		PreloadAssets();
		for (int l = 0; l < base.monsterSpawnWaves.Count; l++)
		{
			if (!base.monsterSpawnWaves[l].isTriggerActived)
			{
				base.monsterSpawnWaves[l].EnableSpawnLogic();
			}
		}
		for (int m = 0; m < base.trapGroups.Count; m++)
		{
			base.trapGroups[m].EnableSpawnLogic();
		}
		HandleTreasureBoxSpawnPoints();
	}

	protected override void HandleTreasureBoxSpawnPoints()
	{
		if (base.levelLoadParams == null)
		{
			Debug.LogError("主线关卡加载参数为空");
			return;
		}
		if (equipmentInstanceFloor == null)
		{
			Debug.LogError("主线层数据为空");
			return;
		}
		string[] array = equipmentInstanceFloor.SceneName.Split('/');
		string text = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(text);
		if (!sceneByName.IsValid())
		{
			Debug.LogError("没有找到场景" + text);
			return;
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject in rootGameObjects)
		{
			if (!gameObject.name.Equals(equipmentInstanceFloor.ConfigPrefabName))
			{
				continue;
			}
			UnityEngine.Transform transform = gameObject.transform.Find("==== SpawnPoints ====");
			if (!(transform != null))
			{
				break;
			}
			for (int j = 0; j < transform.childCount; j++)
			{
				UnityEngine.Transform child = transform.transform.GetChild(j);
				if (child.name.Equals("---- TreasureBoxSpawnPoints ----"))
				{
					treasureBoxSpawnPoints = child.GetComponentsInChildren<TreasureBoxSpawnPoint>().ToList();
					break;
				}
			}
			break;
		}
		if (treasureBoxSpawnPoints.Count == 0)
		{
			return;
		}
		string text2 = "已开启宝箱：";
		int[] mainlineOpenedTreasureBoxs = base.levelLoadParams.mainlineOpenedTreasureBoxs;
		if (mainlineOpenedTreasureBoxs != null)
		{
			for (int k = 0; k < mainlineOpenedTreasureBoxs.Length; k++)
			{
				int num = mainlineOpenedTreasureBoxs[k];
				text2 = text2 + num + "_";
				for (int l = 0; l < treasureBoxSpawnPoints.Count; l++)
				{
					TreasureBoxSpawnPoint treasureBoxSpawnPoint = treasureBoxSpawnPoints[l];
					if (treasureBoxSpawnPoint.boxID == num)
					{
						treasureBoxSpawnPoint.enabled = false;
						treasureBoxSpawnPoint.gameObject.SetActive(value: false);
						break;
					}
				}
			}
		}
		ConsoleProDebug.LogToFilter(text2, "宝箱");
		for (int m = 0; m < treasureBoxSpawnPoints.Count; m++)
		{
			TreasureBoxSpawnPoint treasureBoxSpawnPoint2 = treasureBoxSpawnPoints[m];
			treasureBoxSpawnPoint2.Initialize(-1, -1);
			if (treasureBoxSpawnPoint2.isActiveAndEnabled && !treasureBoxSpawnPoint2.isTriggerActived)
			{
				treasureBoxSpawnPoint2.EnableSpawnLogic();
			}
		}
	}

	public override List<BaseSpawnPointGizmo> GetWaves(string waveName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			MonsterSpawnWaveGizmo monsterSpawnWaveGizmo = base.monsterSpawnWaves[i];
			if (monsterSpawnWaveGizmo.name.Equals(waveName))
			{
				list.Add(monsterSpawnWaveGizmo);
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetPlans(string planName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos[j];
				if (baseSpawnPointGizmo.name.Equals(planName))
				{
					list.Add(baseSpawnPointGizmo);
				}
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetGroups(string groupName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> result = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				List<BaseSpawnPointGizmo> childrenGizmos2 = childrenGizmos[j].childrenGizmos;
				if (childrenGizmos2 == null)
				{
					continue;
				}
				for (int k = 0; k < childrenGizmos2.Count; k++)
				{
					BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos2[k];
					if (baseSpawnPointGizmo.name.Equals(groupName))
					{
						childrenGizmos2.Add(baseSpawnPointGizmo);
					}
				}
			}
		}
		return result;
	}

	public override void PreloadAssets()
	{
		base.PreloadAssets();
		List<int> list = new List<int>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			if (base.monsterSpawnWaves[i].waveType != MonsterSpawnWaveGizmo.WaveType.Default)
			{
				continue;
			}
			List<MonsterSpawnPointGizmo> list2 = base.monsterSpawnWaves[i].transform.GetComponentsInChildren<MonsterSpawnPointGizmo>().ToList();
			for (int j = 0; j < list2.Count; j++)
			{
				int monsterID = list2[j].monsterID;
				if (!list.Contains(monsterID))
				{
					list.Add(monsterID);
				}
			}
		}
		if (list.Count > 0)
		{
			MonoSingleton<AdventureModulePreloadAssetsMrg>.Instance.PreloadMonsters_IDList(list, isRoguelikeMonster: false);
		}
	}

	public override void LevelEnd()
	{
		base.LevelEnd();
		room?.LeaveRoom();
		MonoSingleton<AdventureModulePreloadAssetsMrg>.Instance.LevelFinish();
	}
}
public class InfinityTowerLevelController : AdventureLevelController
{
	protected const string ZoomFreezeKey = "ZoomFreeze";

	protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

	private float _zoomFreeze;

	private float _zoomDurationTime;

	protected bool isStartTime;

	protected FP timeing = 0;

	protected int totalTime;

	protected int limitTime;

	protected InfinityTowerFloor floorData;

	protected InfinityTowerMap mapData;

	protected bool isContinue;

	protected List<InfinityTowerEnemySet> enemySetList;

	protected InfinityTowerGameplayTypeGizmo itGameplayTypeGizmo;

	protected GameEnum.infinityTowerGameplayType levelType;

	protected MonsterSpawnWaveGizmo firstMonsterSpawnWave;

	protected HotfixEnum.fixedRoguelikeFunc0 floorFunc;

	protected InfinityTowerPlayerSpawnPointGizmo itPlayerPointGizmo;

	public bool isSettlement;

	private int MaxMonsterCount;

	private int RemainingMonsterCount;

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		base.Load(param, callback);
		isSettlement = false;
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		floorData = Singleton<HotfixDataController>.Instance.GetInfinityTowerFloor(CommonHelper.ParseStringParamToInt(base.levelLoadParams.id));
		mapData = Singleton<HotfixDataController>.Instance.GetInfinityTowerMap(floorData.MapId);
		param.monsterLevel = floorData.MonsterLv;
		isContinue = param.isInfinityContinueBattle;
		limitTime = floorData.LimitTime;
		MaxMonsterCount = 0;
		RemainingMonsterCount = 0;
		if (mapData != null)
		{
			scenePath = "Assets/AssetBundles/" + mapData.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
			musicName = mapData.BGM;
			leaveMusicEvent = mapData.LeaveTriggerEvent;
		}
		else
		{
			Debug.LogError("infinityTowerMap data is null");
		}
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		Scene sceneByName = SceneManager.GetSceneByName(array[array.Length - 1]);
		string text = (isContinue ? mapData.ContinuePrefabName : mapData.ConfigPrefabName);
		string assetName = scenePath + "/" + text + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (null == gameObject)
		{
			Debug.LogError("无尽塔:map配置项没有找到对应的prefab!");
			return;
		}
		configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
		configPrefab.transform.localScale = Vector3.one;
		configPrefab.name = mapData.ConfigPrefabName;
		SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName);
			}
		}
		UnityEngine.Transform transform = configPrefab.transform.Find("==== Triggers ====");
		TriggerCom[] array2 = null;
		if (null == transform)
		{
			Debug.LogError("没有找到触发器节点==== Triggers ====");
		}
		else
		{
			array2 = transform.GetComponentsInChildren<TriggerCom>();
			Singleton<TriggerManager>.Instance.AddTriggers(array2, -1, -1);
		}
		UnityEngine.Transform transform2 = configPrefab.transform.Find("==== SpawnPoints ====");
		if (null == transform2)
		{
			Debug.LogError("没有找到出生节点==== SpawnPoints ====");
			return;
		}
		if (!base.isViewSceneMode)
		{
			floorFunc = (HotfixEnum.fixedRoguelikeFunc0)floorData.FloorFunc;
			if (floorFunc == HotfixEnum.fixedRoguelikeFunc0.Boss)
			{
				UnityEngine.Transform transform3 = transform2.transform.Find("---- MonsterSpawnPoints ----");
				if (null != transform3)
				{
					base.monsterSpawnWaves = transform2.transform.GetComponentsInChildren<MonsterSpawnWaveGizmo>().ToList();
					base.virtualMonsterSpawnWaves = transform2.transform.GetComponentsInChildren<VirtualMonsterSpawnWaveGizmo>().ToList();
				}
			}
			else
			{
				UnityEngine.Transform transform4 = transform2.transform.Find("---- InfinityTowerMonsterSpawnPoints ----");
				if (null == transform4)
				{
					base._logger.LogInfo("无尽塔怪物出生点为空!");
				}
				else
				{
					if (!transform4.gameObject.activeSelf)
					{
						transform4.gameObject.SetActive(value: true);
					}
					enemySetList = new List<InfinityTowerEnemySet>();
					List<InfinityTowerEnemySet> infinityTowerEnemySetData = Singleton<GameDataController>.Instance.InfinityTowerEnemySetData;
					for (int j = 0; j < infinityTowerEnemySetData.Count; j++)
					{
						InfinityTowerEnemySet infinityTowerEnemySet = infinityTowerEnemySetData[j];
						if (infinityTowerEnemySet.SetId == floorData.SetId)
						{
							levelType = (GameEnum.infinityTowerGameplayType)infinityTowerEnemySet.CommonGameplayType;
							MaxMonsterCount += infinityTowerEnemySet.MaxNumPerWave;
							RemainingMonsterCount += infinityTowerEnemySet.MaxNumPerWave;
							enemySetList.Add(infinityTowerEnemySet);
						}
					}
					if (enemySetList.Count == 0)
					{
						base._logger.LogError($"无尽塔Floor = {floorData.Id}找不到合适的Set数据,SetId = {floorData.SetId}");
						return;
					}
					InfinityTowerGameplayTypeGizmo[] componentsInChildren = transform2.GetComponentsInChildren<InfinityTowerGameplayTypeGizmo>();
					for (int k = 0; k < componentsInChildren.Length; k++)
					{
						if (componentsInChildren[k].waveModel == levelType)
						{
							itGameplayTypeGizmo = componentsInChildren[k];
							break;
						}
					}
					if (!(null != itGameplayTypeGizmo))
					{
						base._logger.LogInfo($"无尽塔Floor = {floorData.Id},Map = {mapData.Id},找不到合适的玩法类型,CommonGameplayType = {levelType}");
					}
				}
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	public override bool HasTimelinePerformance()
	{
		int num;
		if (base.levelLoadParams != null && mapData != null)
		{
			num = ((!string.IsNullOrEmpty(mapData.IntroCutscene)) ? 1 : 0);
			if (num != 0)
			{
				timelineName = mapData.IntroCutscene;
			}
		}
		else
		{
			num = 0;
		}
		return (byte)num != 0;
	}

	public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
	{
		base.PlayTimelinePerformance(delegate
		{
			callback?.Invoke();
			MonoSingleton<LuaManager>.Instance.FireEvent("CloseJumpOverTimeLine");
			MonoSingleton<LuaManager>.Instance.FireEvent("TimeLineFinishBattleDashboardVisible", a1: true);
		}, needLimitPlayTimes);
	}

	public override void LevelStart(System.Action callback = null)
	{
		base.LevelStart(callback);
		totalTime = 0;
		timeing = 0;
		isStartTime = false;
		ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_CLEARED", MonsterClear);
		Singleton<EventDispatchManager>.Instance?.AddEventListener("GM_SET_LEVEL_COUNTTIMR", GMSetLevelCountTime);
		if (floorFunc == HotfixEnum.fixedRoguelikeFunc0.Boss)
		{
			HandleBossMode();
		}
		itPlayerPointGizmo?.LevelStart();
		callback?.Invoke();
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		if (!isStartTime)
		{
			return;
		}
		timeing += logicDeltaTime;
		if (timeing >= 1)
		{
			timeing -= (FP)1;
			totalTime++;
			MonoSingleton<LuaManager>.Instance.FireEvent("Infinity_Tower_RunTime", totalTime);
			if (totalTime >= limitTime)
			{
				LevelFailedCallBack();
				isStartTime = false;
			}
		}
	}

	public override void LevelEnd()
	{
		itPlayerPointGizmo?.LevelEnd();
		itPlayerPointGizmo = null;
		base.LevelEnd();
		isStartTime = false;
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_CLEARED", MonsterClear);
		Singleton<EventDispatchManager>.Instance?.RemoveEventListener("GM_SET_LEVEL_COUNTTIMR", GMSetLevelCountTime);
		enemySetList?.Clear();
		floorData = null;
		mapData = null;
		itGameplayTypeGizmo = null;
		firstMonsterSpawnWave = null;
		if (floorFunc == HotfixEnum.fixedRoguelikeFunc0.Boss)
		{
			MonoSingleton<AdventureModulePreloadAssetsMrg>.Instance?.ClearMonsters();
			MonoSingleton<AdventureModulePreloadAssetsMrg>.Instance?.ClearSkill();
		}
	}

	public override void LevelFinish()
	{
		base.LevelFinish();
	}

	private void OnPlayerDied(IEvent ievent)
	{
		isStartTime = false;
		LevelFailedCallBack();
	}

	private void StartTiming(IEvent evt)
	{
		isStartTime = true;
		if (null != itGameplayTypeGizmo)
		{
			itGameplayTypeGizmo.InitTypeMonsterDatas(enemySetList, LevelSuccessCallBack, RefreshMonsterCount);
			itGameplayTypeGizmo.EnableSpawnLogic();
		}
		MonoSingleton<LuaManager>.Instance.FireEvent("Infinity_Tower_StartTime");
	}

	private void MonsterClear(IEvent evt)
	{
		if (floorFunc == HotfixEnum.fixedRoguelikeFunc0.Boss)
		{
			LevelSuccessCallBack();
		}
	}

	public override void InitSpawnPoints()
	{
		base.InitSpawnPoints();
		if (floorFunc == HotfixEnum.fixedRoguelikeFunc0.Battle)
		{
			InfinityTowerPlayerSpawnPointGizmo[] array = UnityEngine.Object.FindObjectsOfType<InfinityTowerPlayerSpawnPointGizmo>();
			if (array == null || array.Length == 0)
			{
				Debug.LogError("关卡中没有配置玩家出生点!");
				return;
			}
			if (!string.IsNullOrEmpty(nextLevelData.bornID))
			{
				foreach (InfinityTowerPlayerSpawnPointGizmo infinityTowerPlayerSpawnPointGizmo in array)
				{
					if (nextLevelData.bornID.Equals(infinityTowerPlayerSpawnPointGizmo.spawnPointID) && infinityTowerPlayerSpawnPointGizmo.groupIndex == levelType)
					{
						itPlayerPointGizmo = infinityTowerPlayerSpawnPointGizmo;
						break;
					}
				}
			}
			if (null == itPlayerPointGizmo)
			{
				foreach (InfinityTowerPlayerSpawnPointGizmo infinityTowerPlayerSpawnPointGizmo2 in array)
				{
					if (string.IsNullOrEmpty(infinityTowerPlayerSpawnPointGizmo2.spawnPointID))
					{
						itPlayerPointGizmo = infinityTowerPlayerSpawnPointGizmo2;
						break;
					}
				}
			}
			if (null == itPlayerPointGizmo)
			{
				base._logger.LogError("没有找到合适的角色出生点!");
				return;
			}
			itPlayerPointGizmo.Initialize(0, 0);
			itPlayerPointGizmo.EnableSpawnLogic();
			itPlayerPointGizmo.ExecuteSpawnLogic();
		}
		else
		{
			PlayerSpawnPointGizmo[] array2 = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>();
			if (array2 == null || array2.Length == 0)
			{
				Debug.LogError("关卡中没有配置玩家出生点!");
				return;
			}
			if (!string.IsNullOrEmpty(nextLevelData.bornID))
			{
				foreach (PlayerSpawnPointGizmo playerSpawnPointGizmo in array2)
				{
					if (nextLevelData.bornID.Equals(playerSpawnPointGizmo.spawnPointID))
					{
						base.playerSpawnPointGizmo = playerSpawnPointGizmo;
						break;
					}
				}
			}
			if (null == base.playerSpawnPointGizmo)
			{
				foreach (PlayerSpawnPointGizmo playerSpawnPointGizmo2 in array2)
				{
					if (string.IsNullOrEmpty(playerSpawnPointGizmo2.spawnPointID))
					{
						base.playerSpawnPointGizmo = playerSpawnPointGizmo2;
						break;
					}
				}
			}
			if (null == base.playerSpawnPointGizmo)
			{
				base._logger.LogError("没有找到合适的角色出生点!");
				return;
			}
			base.playerSpawnPointGizmo.Initialize(0, 0);
			base.playerSpawnPointGizmo.EnableSpawnLogic();
			base.playerSpawnPointGizmo.ExecuteSpawnLogic();
		}
		if (!base.isViewSceneMode)
		{
			HandleSpawnGizmos();
		}
	}

	public override void HandleSpawnGizmos()
	{
		base.HandleSpawnGizmos();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			base.monsterSpawnWaves[i].Initialize(-1, -1);
		}
		for (int j = 0; j < base.virtualMonsterSpawnWaves.Count; j++)
		{
			base.virtualMonsterSpawnWaves[j].Initialize(-1, -1);
		}
		for (int k = 0; k < base.monsterSpawnWaves.Count; k++)
		{
			if (!base.monsterSpawnWaves[k].isTriggerActived)
			{
				base.monsterSpawnWaves[k].EnableSpawnLogic();
			}
		}
	}

	public override List<BaseSpawnPointGizmo> GetWaves(string waveName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			MonsterSpawnWaveGizmo monsterSpawnWaveGizmo = base.monsterSpawnWaves[i];
			if (monsterSpawnWaveGizmo.name.Equals(waveName))
			{
				list.Add(monsterSpawnWaveGizmo);
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetPlans(string planName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos[j];
				if (baseSpawnPointGizmo.name.Equals(planName))
				{
					list.Add(baseSpawnPointGizmo);
				}
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetGroups(string groupName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> result = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				List<BaseSpawnPointGizmo> childrenGizmos2 = childrenGizmos[j].childrenGizmos;
				if (childrenGizmos2 == null)
				{
					continue;
				}
				for (int k = 0; k < childrenGizmos2.Count; k++)
				{
					BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos2[k];
					if (baseSpawnPointGizmo.name.Equals(groupName))
					{
						childrenGizmos2.Add(baseSpawnPointGizmo);
					}
				}
			}
		}
		return result;
	}

	public void HandleBossMode()
	{
		if (base.isLevelLogicComplete)
		{
			return;
		}
		bool flag = true;
		if (base.monsterSpawnWaves == null || base.monsterSpawnWaves.Count == 0)
		{
			Debug.Log("怪物波次为空!");
		}
		else
		{
			for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
			{
				MonsterSpawnWaveGizmo monsterSpawnWaveGizmo = base.monsterSpawnWaves[i];
				if (!monsterSpawnWaveGizmo.isTriggerActived && !(monsterSpawnWaveGizmo is RandomMonsterSpawnWaveGizmo))
				{
					flag = false;
					firstMonsterSpawnWave = monsterSpawnWaveGizmo;
					break;
				}
			}
		}
		if (!flag)
		{
			if (null == firstMonsterSpawnWave)
			{
				Debug.LogError("无尽塔:没有找到无指令激活的怪物波次!");
				return;
			}
			firstMonsterSpawnWave.Initialize(-1, -1);
			firstMonsterSpawnWave.EnableSpawnLogic();
			firstMonsterSpawnWave = null;
		}
		else
		{
			firstMonsterSpawnWave = null;
		}
	}

	protected void LevelStateChangedCallback(GameEnum.levelState levelState)
	{
		AdventureMsgBattleFinishEvent aEvent = AdventureMsgBattleFinishEvent.Generate();
		ModuleController<AdventureModuleController>.Instance.DispatchEvent(aEvent);
		base._logger.LogInfo($"fixed rog level state changed:{levelState}");
		if (levelState != GameEnum.levelState.Failed && levelState == GameEnum.levelState.Success)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("LevelUseTotalTime", totalTime);
		}
		LevelStateChanged(levelState);
		MonoSingleton<LuaManager>.Instance.FireEvent("InfinityTowerEnd", (int)levelState);
	}

	protected void LevelSuccessCallBack()
	{
		if (!isSettlement)
		{
			isSettlement = true;
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
			ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
		}
		void Action()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("InfinityTowerEnd_ZoomTime", a1: false);
			LevelStateChangedCallback(GameEnum.levelState.Success);
		}
	}

	protected void LevelFailedCallBack()
	{
		if (!isSettlement)
		{
			isSettlement = true;
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
			ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
		}
		void Action()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("InfinityTowerEnd_ZoomTime", a1: false);
			LevelStateChangedCallback(GameEnum.levelState.Failed);
		}
	}

	private void GMSetLevelCountTime(IEvent ievent)
	{
		if (isStartTime && ievent is GeneralEvent generalEvent)
		{
			CommonHelper.TryParseStringParamToInt((generalEvent.data as LuaTable)[1].ToString(), out var intValue);
			totalTime = floorData.LimitTime - intValue;
			MonoSingleton<LuaManager>.Instance.FireEvent("Infinity_Tower_RunTime", totalTime);
		}
	}

	public void RefreshMonsterCount()
	{
		RemainingMonsterCount--;
		MonoSingleton<LuaManager>.Instance.FireEvent("Infinity_RefreshCountRemaining", RemainingMonsterCount, MaxMonsterCount);
	}
}
public class MainlineLevelController : AdventureLevelController
{
	private FP timing = 0;

	private int totalTime;

	private bool isTestingSceneMode;

	private bool doMir;

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		base.Load(param, callback);
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		MainlineFloor mainlineFloorData = (base.isViewSceneMode ? param.mainlineFloorData : param.Mainline_GenerateFloorData());
		if (true)
		{
			BGSceneLoadComplete(default(Scene));
		}
		void BGSceneLoadComplete(Scene scene)
		{
			if (mainlineFloorData != null)
			{
				scenePath = "Assets/AssetBundles/" + mainlineFloorData.SceneName;
				MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
				{
					LevelLoadProcessUpdate(sceneName, process);
					return true;
				});
			}
			else
			{
				Debug.LogError("Mainline data is null");
			}
		}
	}

	public override bool HasTimelinePerformance()
	{
		int num;
		if (base.levelLoadParams != null && base.levelLoadParams.mainlineFloorData != null)
		{
			num = ((!string.IsNullOrEmpty(base.levelLoadParams.mainlineFloorData.IntroCutscene)) ? 1 : 0);
			if (num != 0)
			{
				timelineName = base.levelLoadParams.mainlineFloorData.IntroCutscene;
			}
		}
		else
		{
			num = 0;
		}
		return (byte)num != 0;
	}

	public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
	{
		base.PlayTimelinePerformance(delegate
		{
			callback?.Invoke();
			MonoSingleton<LuaManager>.Instance.FireEvent("CloseJumpOverTimeLine");
			MonoSingleton<LuaManager>.Instance.FireEvent("TimeLineFinishBattleDashboardVisible", a1: true);
		}, needLimitPlayTimes);
	}

	public override void LevelStart(System.Action callback = null)
	{
		base.LevelStart(callback);
		totalTime = 0;
		timing = 0;
		ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		callback?.Invoke();
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		timing += logicDeltaTime;
		if (timing >= 1)
		{
			totalTime++;
			MonoSingleton<LuaManager>.Instance.FireEvent("Mainline_Time_CountUp", totalTime);
			timing = 0;
		}
	}

	public override void LevelEnd()
	{
		base.LevelEnd();
		MonoSingleton<AdventureModulePreloadAssetsMrg>.Instance.LevelFinish();
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
	}

	private void OnPlayerDied(IEvent ievent)
	{
		LevelStateChanged(GameEnum.levelState.Failed);
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		MainlineFloor mainlineFloorData = base.levelLoadParams.mainlineFloorData;
		GameObject gameObject = null;
		if (!isTestingSceneMode)
		{
			string assetName = scenePath + "/" + mainlineFloorData.ConfigPrefabName + ".prefab";
			gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		}
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = mainlineFloorData.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
			if (doMir)
			{
				Vector3 localScale = configPrefab.transform.localScale;
				configPrefab.transform.localScale = new Vector3(0f - localScale.x, localScale.y, localScale.z);
			}
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + mainlineFloorData.ConfigPrefabName);
		}
		if (doMir)
		{
			SceneSingleton<AdventurePlayerController>.Instance.reversalCameraRotationAngle = -1;
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(mainlineFloorData.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
					List<AdventureLevelTeleporter> list = transform.GetComponentsInChildren<AdventureLevelTeleporter>().ToList();
					if (list.Count > 0)
					{
						for (int j = 0; j < list.Count; j++)
						{
							AdventureLevelTeleporter adventureLevelTeleporter = list[j];
							adventureLevelTeleporter.SetPosition(-1, -1);
							adventureLevelTeleporter.RegisterTeleporterCallback(LevelTeleporterTriggered);
						}
						teleporters.AddRange(list);
					}
				}
			}
			else if (gameObject2.name.Equals("==== Triggers ===="))
			{
				AdventureLevelTeleporter[] componentsInChildren2 = gameObject2.GetComponentsInChildren<AdventureLevelTeleporter>();
				if (componentsInChildren2 != null && componentsInChildren2.Length > 0)
				{
					foreach (AdventureLevelTeleporter obj in componentsInChildren2)
					{
						obj.SetPosition(-1, -1);
						obj.RegisterTeleporterCallback(LevelTeleporterTriggered);
					}
					teleporters.AddRange(componentsInChildren2);
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	protected override void LevelTeleporterTriggered(AdventureLevelTeleporter.NextLevelData nextData)
	{
		if (!nextData.enterSettlementState)
		{
			if (!nextData.isCurScene)
			{
				return;
			}
			string bornID = nextData.bornID;
			if (string.IsNullOrEmpty(bornID))
			{
				for (int i = 0; i < playerSpawnPoints.Count; i++)
				{
					PlayerSpawnPointGizmo playerSpawnPointGizmo = playerSpawnPoints[i];
					if (string.IsNullOrEmpty(playerSpawnPointGizmo.spawnPointID))
					{
						base.playerSpawnPointGizmo = playerSpawnPointGizmo;
						break;
					}
				}
			}
			else
			{
				List<PlayerSpawnPointGizmo> list = new List<PlayerSpawnPointGizmo>();
				for (int j = 0; j < playerSpawnPoints.Count; j++)
				{
					PlayerSpawnPointGizmo playerSpawnPointGizmo2 = playerSpawnPoints[j];
					if (bornID.Equals(playerSpawnPointGizmo2.spawnPointID))
					{
						list.Add(playerSpawnPointGizmo2);
					}
				}
				int count = list.Count;
				switch (count)
				{
				case 0:
					base._logger.LogError("找不到ID为" + bornID + "的角色出生点!");
					break;
				case 1:
					base.playerSpawnPointGizmo = list[0];
					break;
				default:
				{
					int index = MonoSingleton<GameController>.Instance.Random_Roguelike(0, count);
					base.playerSpawnPointGizmo = list[index];
					break;
				}
				}
			}
			if (null == base.playerSpawnPointGizmo)
			{
				base._logger.LogError("找不到ID为" + bornID + "的角色出生点!");
			}
			else
			{
				base.playerSpawnPointGizmo.PlayerTransfer();
			}
		}
		else
		{
			nextData.levelSuccess = true;
			OnLevelTeleporterTriggered(nextData);
		}
	}

	public override void InitSpawnPoints()
	{
		base.InitSpawnPoints();
		StarTowerPorts starTowerPorts = UnityEngine.Object.FindObjectOfType<StarTowerPorts>();
		if (null != starTowerPorts)
		{
			starTowerPorts.gameObject.SetActive(value: false);
		}
		playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
		if (playerSpawnPoints == null || playerSpawnPoints.Count == 0)
		{
			Debug.LogError("关卡中没有配置玩家出生点!");
			return;
		}
		if (null == base.playerSpawnPointGizmo && !string.IsNullOrEmpty(nextLevelData.bornID))
		{
			for (int i = 0; i < playerSpawnPoints.Count; i++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo = playerSpawnPoints[i];
				if (nextLevelData.bornID.Equals(playerSpawnPointGizmo.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			for (int j = 0; j < playerSpawnPoints.Count; j++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo2 = playerSpawnPoints[j];
				if (string.IsNullOrEmpty(playerSpawnPointGizmo2.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo2;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			base._logger.LogError("没有找到合适的角色出生点!");
			return;
		}
		base.playerSpawnPointGizmo.Initialize(0, 0);
		base.playerSpawnPointGizmo.EnableSpawnLogic();
		base.playerSpawnPointGizmo.ExecuteSpawnLogic();
		if (!base.isViewSceneMode)
		{
			HandleSpawnGizmos();
		}
	}

	public override void HandleSpawnGizmos()
	{
		base.HandleSpawnGizmos();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			base.monsterSpawnWaves[i].Initialize(-1, -1);
		}
		for (int j = 0; j < base.virtualMonsterSpawnWaves.Count; j++)
		{
			base.virtualMonsterSpawnWaves[j].Initialize(-1, -1);
		}
		for (int k = 0; k < base.trapGroups.Count; k++)
		{
			base.trapGroups[k].Initialize(-1, -1);
		}
		for (int l = 0; l < base.monsterSpawnWaves.Count; l++)
		{
			if (!base.monsterSpawnWaves[l].isTriggerActived)
			{
				base.monsterSpawnWaves[l].EnableSpawnLogic();
			}
		}
		for (int m = 0; m < base.trapGroups.Count; m++)
		{
			base.trapGroups[m].EnableSpawnLogic();
		}
		HandleTreasureBoxSpawnPoints();
		PreloadAssets();
	}

	protected override void HandleTreasureBoxSpawnPoints()
	{
		if (base.levelLoadParams == null)
		{
			Debug.LogError("主线关卡加载参数为空");
			return;
		}
		MainlineFloor mainlineFloorData = base.levelLoadParams.mainlineFloorData;
		if (mainlineFloorData == null)
		{
			Debug.LogError("主线层数据为空");
			return;
		}
		string[] array = mainlineFloorData.SceneName.Split('/');
		string text = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(text);
		if (!sceneByName.IsValid())
		{
			Debug.LogError("没有找到场景" + text);
			return;
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject in rootGameObjects)
		{
			if (!gameObject.name.Equals(mainlineFloorData.ConfigPrefabName))
			{
				continue;
			}
			UnityEngine.Transform transform = gameObject.transform.Find("==== SpawnPoints ====");
			if (!(transform != null))
			{
				break;
			}
			for (int j = 0; j < transform.childCount; j++)
			{
				UnityEngine.Transform child = transform.transform.GetChild(j);
				if (child.name.Equals("---- TreasureBoxSpawnPoints ----"))
				{
					treasureBoxSpawnPoints = child.GetComponentsInChildren<TreasureBoxSpawnPoint>().ToList();
					break;
				}
			}
			break;
		}
		if (treasureBoxSpawnPoints.Count == 0)
		{
			return;
		}
		string text2 = "已开启宝箱：";
		int[] mainlineOpenedTreasureBoxs = base.levelLoadParams.mainlineOpenedTreasureBoxs;
		if (mainlineOpenedTreasureBoxs != null)
		{
			for (int k = 0; k < mainlineOpenedTreasureBoxs.Length; k++)
			{
				int num = mainlineOpenedTreasureBoxs[k];
				text2 = text2 + num + "_";
				for (int l = 0; l < treasureBoxSpawnPoints.Count; l++)
				{
					TreasureBoxSpawnPoint treasureBoxSpawnPoint = treasureBoxSpawnPoints[l];
					if (treasureBoxSpawnPoint.boxID == num)
					{
						treasureBoxSpawnPoint.enabled = false;
						treasureBoxSpawnPoint.gameObject.SetActive(value: false);
						break;
					}
				}
			}
		}
		ConsoleProDebug.LogToFilter(text2, "宝箱");
		for (int m = 0; m < treasureBoxSpawnPoints.Count; m++)
		{
			TreasureBoxSpawnPoint treasureBoxSpawnPoint2 = treasureBoxSpawnPoints[m];
			treasureBoxSpawnPoint2.Initialize(-1, -1);
			if (treasureBoxSpawnPoint2.isActiveAndEnabled && !treasureBoxSpawnPoint2.isTriggerActived)
			{
				treasureBoxSpawnPoint2.EnableSpawnLogic();
			}
		}
	}
}
public class RegionBossLevelController : AdventureLevelController
{
	private bool isStartTime;

	private FP timeing = 0;

	private int totalTime;

	protected const string ZoomFreezeKey = "ZoomFreeze";

	protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

	private float _zoomFreeze;

	private float _zoomDurationTime;

	private Coroutine corSettlement;

	private RegionBossSummonMonsterGroupGizmo regionBossSummonMonsterGroupGizmo;

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		base.Load(param, callback);
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		RegionBossFloor regionBossFloor = (base.isViewSceneMode ? param.regionBossFloor : param.RegionBoss_GenerateFloorData());
		if (regionBossFloor != null)
		{
			scenePath = "Assets/AssetBundles/" + regionBossFloor.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
		}
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		RegionBossFloor regionBossFloor = base.levelLoadParams.RegionBoss_GenerateFloorData();
		string assetName = scenePath + "/" + regionBossFloor.ConfigPrefabName + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = regionBossFloor.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + regionBossFloor.ConfigPrefabName);
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(regionBossFloor.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
					teleporters = transform.GetComponentsInChildren<AdventureLevelTeleporter>().ToList();
					if (teleporters != null)
					{
						for (int j = 0; j < teleporters.Count; j++)
						{
							teleporters[j].SetPosition(-1, -1);
						}
					}
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	public override bool HasTimelinePerformance()
	{
		int num;
		if (base.levelLoadParams != null && base.levelLoadParams.regionBossFloor != null)
		{
			num = ((!string.IsNullOrEmpty(base.levelLoadParams.regionBossFloor.IntroCutscene)) ? 1 : 0);
			if (num != 0)
			{
				timelineName = base.levelLoadParams.regionBossFloor.IntroCutscene;
			}
		}
		else
		{
			num = 0;
		}
		return (byte)num != 0;
	}

	public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
	{
		base.PlayTimelinePerformance(delegate
		{
			callback?.Invoke();
			MonoSingleton<LuaManager>.Instance.FireEvent("CloseJumpOverTimeLine");
			MonoSingleton<LuaManager>.Instance.FireEvent("TimeLineFinishBattleDashboardVisible", a1: true);
		}, needLimitPlayTimes);
	}

	public override void LevelStart(System.Action callback)
	{
		base.LevelStart(callback);
		totalTime = 0;
		timeing = 0;
		isStartTime = false;
		ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActor_Died);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_CHANGE_LEVEL_STATE", ChangeLevelState);
		Singleton<EventDispatchManager>.Instance?.AddEventListener("GM_SET_LEVEL_COUNTTIMR", GMSetLevelCountTime);
		callback?.Invoke();
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		if (isStartTime)
		{
			timeing += logicDeltaTime;
			if (timeing >= 1)
			{
				totalTime++;
				MonoSingleton<LuaManager>.Instance.FireEvent("RegionBoss_Time_CountUp", totalTime);
				timeing -= (FP)1;
			}
		}
	}

	public override void LevelEnd()
	{
		base.LevelEnd();
		isStartTime = false;
		if (corSettlement != null)
		{
			StopCoroutine(corSettlement);
			corSettlement = null;
		}
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActor_Died);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_CHANGE_LEVEL_STATE", ChangeLevelState);
		Singleton<EventDispatchManager>.Instance?.RemoveEventListener("GM_SET_LEVEL_COUNTTIMR", GMSetLevelCountTime);
	}

	private void OnActor_Died(IEvent ievent)
	{
		if (((AdventureActorDiedEvent)ievent).actor is PlayerAdventureActor)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("Region_Boss_PlayerDied");
		}
	}

	private void OnPlayerDied(IEvent ievent)
	{
		isStartTime = false;
		LevelStateChanged(GameEnum.levelState.Failed);
		MonoSingleton<LuaManager>.Instance.FireEvent("Region_Boss_Result", a1: false, totalTime);
	}

	private void StartTiming(IEvent evt)
	{
		MonoSingleton<LuaManager>.Instance.FireEvent("RegionBoss_StartTime");
		isStartTime = true;
	}

	protected void ChangeLevelState(IEvent evt)
	{
		isStartTime = false;
		corSettlement = StartCoroutine(CorSettlement((float)base.levelLoadParams.regionBossFloor.DungeonDelay / 10000f));
		if (((AdventureChangeLevelStateEvent)evt).levelState == GameEnum.levelState.Success)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("RegionBoss_Success");
		}
	}

	private IEnumerator CorSettlement(float delayTime)
	{
		yield return new WaitForSecondsRealtime(delayTime);
		MonoSingleton<LuaManager>.Instance.FireEvent("Region_Boss_Result", a1: true, totalTime);
	}

