	private void GMSetLevelCountTime(IEvent ievent)
	{
		if (isStartTime && base.levelLoadParams.regionBossLevel.RegionType != 2 && ievent is GeneralEvent generalEvent)
		{
			CommonHelper.TryParseStringParamToInt((generalEvent.data as LuaTable)[1].ToString(), out var intValue);
			int num = JsonConvert.DeserializeObject<List<int>>(base.levelLoadParams.regionBossLevel.TwoStarCondition)[1] - intValue;
			totalTime = num;
			MonoSingleton<LuaManager>.Instance.FireEvent("RegionBoss_Time_CountUp", totalTime);
		}
	}
