			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
			musicName = floorData.BGM;
			leaveMusicEvent = floorData.LeaveTriggerEvent;
		}
		else
		{
			Debug.LogError("scoreBossFloor data is null");
		}
