		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		string assetName = scenePath + "/" + floorData.ConfigPrefabName + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = floorData.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + floorData.ConfigPrefabName);
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(floorData.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
					teleporters = transform.GetComponentsInChildren<AdventureLevelTeleporter>().ToList();
					if (teleporters != null)
					{
						for (int j = 0; j < teleporters.Count; j++)
						{
							teleporters[j].SetPosition(-1, -1);
						}
					}
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	public override void LevelStart(System.Action callback)
	{
		base.LevelStart(callback);
		totalTime = 0;
		timeing = 0;
		levelTotalTime = CommonHelper.ParseStringParamToInt(Singleton<GameDataController>.Instance.GetConfig("ScoreBossTimeLimit").Value);
		isStartTime = false;
		isSettlement = false;
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_SPAWN_BEFORE", MonsterSpawnBefore);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_SPAWN", MonsterSpawn);
		callback?.Invoke();
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		base.UpdateLogic(logicDeltaTime);
		if (isStartTime)
		{
			timeing += logicDeltaTime;
			if (timeing >= 1)
			{
				totalTime++;
				timeing -= (FP)1;
				MonoSingleton<LuaManager>.Instance.FireEvent("ScoreBoss_Gameplay_Time", levelTotalTime - totalTime);
			}
			if (totalTime >= levelTotalTime)
			{
				LevelStateChangedCall(GameEnum.levelState.Success);
			}
		}
	}

	public override void LevelEnd()
	{
		base.LevelEnd();
		isStartTime = false;
		if (corSettlement != null)
		{
			StopCoroutine(corSettlement);
			corSettlement = null;
		}
		ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_SPAWN_BEFORE", MonsterSpawnBefore);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_SPAWN", MonsterSpawn);
	}

	private void OnActor_Died(IEvent ievent)
	{
		_ = ((AdventureActorDiedEvent)ievent).actor is PlayerAdventureActor;
	}

	private void OnPlayerDied(IEvent ievent)
	{
		LevelStateChangedCall(GameEnum.levelState.Failed);
	}

	private void StartTiming(IEvent evt)
	{
		isStartTime = true;
	}

	public void MonsterDeclareDeath(IEvent evt)
	{
		if (((AdventureMonsterDeclareDiedEvent)evt).epicType == GameEnum.monsterEpicType.BOSSRUSH)
		{
			LevelStateChangedCall(GameEnum.levelState.Success);
		}
	}

	private void MonsterSpawnBefore(IEvent evt)
	{
		AdventureMonsterSpawnedBeforeEvent adventureMonsterSpawnedBeforeEvent = (AdventureMonsterSpawnedBeforeEvent)evt;
		if (adventureMonsterSpawnedBeforeEvent.MonsterActor == null)
		{
			return;
		}
		int scoreBossAbility = levelData.ScoreBossAbility;
		ScoreBossAbility scoreBossAbility2 = Singleton<HotfixDataController>.Instance.GetScoreBossAbility(scoreBossAbility);
		if (scoreBossAbility2 != null)
		{
			List<AddEffectInfo> list = new List<AddEffectInfo>();
			foreach (int item in scoreBossAbility2.EffectID)
			{
				list.Add(new AddEffectInfo(item, -1, 0L));
			}
			string[] bossTags = scoreBossAbility2.ScriptID.ToArray();
			adventureMonsterSpawnedBeforeEvent.MonsterActor.effectManage?.AddEffectByTalent(list);
			adventureMonsterSpawnedBeforeEvent.MonsterActor.SetBossTags(bossTags);
		}
		int nonDamageScoreGet = levelData.NonDamageScoreGet;
		ScoreBossGetControl scoreBossGetControl = Singleton<HotfixDataController>.Instance.GetScoreBossGetControl(nonDamageScoreGet);
		if (scoreBossGetControl != null)
		{
			adventureMonsterSpawnedBeforeEvent.MonsterActor.SetScoreBossBehaviour((scoreBossBehavior)scoreBossGetControl.ScoreBossBehavior);
		}
		adventureMonsterSpawnedBeforeEvent.MonsterActor.summonMonsterUseBattleLevelAsDifficultLevel = levelData.SummonLevelUp;
	}

	private void MonsterSpawn(IEvent evt)
	{
		AdventureMonsterSpawnedEvent adventureMonsterSpawnedEvent = (AdventureMonsterSpawnedEvent)evt;
		if (adventureMonsterSpawnedEvent != null)
		{
			MonsterAdventureActor monsterAdventureActor = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(adventureMonsterSpawnedEvent.id) as MonsterAdventureActor;
			if (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.BOSSRUSH)
			{
				MonoSingleton<LuaManager>.Instance.FireEvent("BossRush_Spawn_Id", monsterAdventureActor.Id);
			}
		}
	}

	protected void LevelStateChangedCall(GameEnum.levelState levelState)
	{
		if (!isSettlement)
		{
			isStartTime = false;
			isSettlement = true;
			base._logger.LogInfo($"fixed rog level state changed:{levelState}");
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
			CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
			ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
		}
		void Action()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("ScoreBoss_Result_Time", totalTime);
			LevelStateChanged(levelState);
		}
	}

	public override void InitSpawnPoints()
	{
		base.InitSpawnPoints();
		StarTowerPorts starTowerPorts = UnityEngine.Object.FindObjectOfType<StarTowerPorts>();
		if (null != starTowerPorts)
		{
			starTowerPorts.gameObject.SetActive(value: false);
		}
		playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
		if (playerSpawnPoints == null || playerSpawnPoints.Count == 0)
		{
			Debug.LogError("关卡中没有配置玩家出生点!");
			return;
		}
		if (!string.IsNullOrEmpty(nextLevelData.bornID))
		{
			for (int i = 0; i < playerSpawnPoints.Count; i++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo = playerSpawnPoints[i];
				if (nextLevelData.bornID.Equals(playerSpawnPointGizmo.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			for (int j = 0; j < playerSpawnPoints.Count; j++)
			{
				PlayerSpawnPointGizmo playerSpawnPointGizmo2 = playerSpawnPoints[j];
				if (string.IsNullOrEmpty(playerSpawnPointGizmo2.spawnPointID))
				{
					base.playerSpawnPointGizmo = playerSpawnPointGizmo2;
					break;
				}
			}
		}
		if (null == base.playerSpawnPointGizmo)
		{
			base._logger.LogError("没有找到合适的角色出生点!");
			return;
		}
		base.playerSpawnPointGizmo.Initialize(0, 0);
		base.playerSpawnPointGizmo.EnableSpawnLogic();
		base.playerSpawnPointGizmo.ExecuteSpawnLogic();
		if (!base.isViewSceneMode)
		{
			HandleSpawnGizmos();
		}
	}

	public override void HandleSpawnGizmos()
	{
		base.HandleSpawnGizmos();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			base.monsterSpawnWaves[i].Initialize(-1, -1);
		}
		for (int j = 0; j < base.virtualMonsterSpawnWaves.Count; j++)
		{
			base.virtualMonsterSpawnWaves[j].Initialize(-1, -1);
		}
		for (int k = 0; k < base.trapGroups.Count; k++)
		{
			base.trapGroups[k].Initialize(-1, -1);
		}
		PreloadAssets();
		for (int l = 0; l < base.monsterSpawnWaves.Count; l++)
		{
			if (!base.monsterSpawnWaves[l].isTriggerActived)
			{
				base.monsterSpawnWaves[l].EnableSpawnLogic();
			}
		}
		for (int m = 0; m < base.trapGroups.Count; m++)
		{
			base.trapGroups[m].EnableSpawnLogic();
		}
		HandleTreasureBoxSpawnPoints();
	}

	protected override void HandleTreasureBoxSpawnPoints()
	{
	}

	public override List<BaseSpawnPointGizmo> GetWaves(string waveName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			MonsterSpawnWaveGizmo monsterSpawnWaveGizmo = base.monsterSpawnWaves[i];
			if (monsterSpawnWaveGizmo.name.Equals(waveName))
			{
				list.Add(monsterSpawnWaveGizmo);
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetPlans(string planName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> list = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos[j];
				if (baseSpawnPointGizmo.name.Equals(planName))
				{
					list.Add(baseSpawnPointGizmo);
				}
			}
		}
		return list;
	}

	public override List<BaseSpawnPointGizmo> GetGroups(string groupName, int x = -1, int y = -1)
	{
		if (base.monsterSpawnWaves == null)
		{
			return null;
		}
		List<BaseSpawnPointGizmo> result = new List<BaseSpawnPointGizmo>();
		for (int i = 0; i < base.monsterSpawnWaves.Count; i++)
		{
			List<BaseSpawnPointGizmo> childrenGizmos = base.monsterSpawnWaves[i].childrenGizmos;
			if (childrenGizmos == null)
			{
				continue;
			}
			for (int j = 0; j < childrenGizmos.Count; j++)
			{
				List<BaseSpawnPointGizmo> childrenGizmos2 = childrenGizmos[j].childrenGizmos;
				if (childrenGizmos2 == null)
				{
					continue;
				}
				for (int k = 0; k < childrenGizmos2.Count; k++)
				{
					BaseSpawnPointGizmo baseSpawnPointGizmo = childrenGizmos2[k];
					if (baseSpawnPointGizmo.name.Equals(groupName))
					{
						childrenGizmos2.Add(baseSpawnPointGizmo);
					}
				}
			}
		}
		return result;
	}
}
public class SkillInstanceGameplayRoom : GameplayRoom
{
	protected const string ZoomFreezeKey = "ZoomFreeze";

	protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

	public FP levelTime;

	public bool isStartTime;

	public Action<GameEnum.levelState, int> LevelStateCallback;

	private SkillInstanceFloor floorData;

	private readonly List<int> starCondition = new List<int>();

	public int monsterId;

	private int killMonsterCount;

	private int levelTotalTime;

	private FP timeing = 0;

	private bool isTimeEndSettlement;

	private int starConditionType;

	private bool typeHpSendUidToLua;

	private float _zoomFreeze;

	private float _zoomDurationTime;

	private bool isAlreadySettled;

	public override void InitRoom(GameplayRoomData data, Action<GameEnum.levelState, int> levelStateCallback)
	{
		LevelStateCallback = levelStateCallback;
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_SPAWN", MonsterSpawn);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDeath);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_CLEARED", MonsterClear);
		ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_LEVEL_ON_TELEPORTER_TRIGGERED", TaskSettlement);
		floorData = Singleton<HotfixDataController>.Instance.GetSkillInstanceFloor(data.floorId);
		if (floorData != null)
		{
			initFloorMsg();
		}
	}

	public override void UpdateLogic(FP logicDeltaTime)
	{
		if (!isStartTime)
		{
			return;
		}
		levelTime += logicDeltaTime;
		timeing += logicDeltaTime;
		if (timeing >= 1)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("Skill_Instance_Gameplay_Time", (int)(long)levelTime);
			if (levelTotalTime != -1)
			{
				CountDown();
			}
			timeing -= (FP)1;
		}
	}

	public override void Pause()
	{
	}

	public override void Resume()
	{
	}

	public override void LeaveRoom()
	{
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_SPAWN", MonsterSpawn);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDeath);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_CLEARED", MonsterClear);
		ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_LEVEL_ON_TELEPORTER_TRIGGERED", TaskSettlement);
	}

	private void initFloorMsg()
	{
		starConditionType = floorData.StarConditionType;
		starCondition.Add(floorData.OneStarCondition);
		starCondition.Add(floorData.TwoStarCondition);
		starCondition.Add(floorData.ThreeStarCondition);
		monsterId = floorData.MonsterId;
		levelTotalTime = floorData.LevelTotalTime;
		isTimeEndSettlement = floorData.TimeEndSettlement;
	}

	public void levelEnd(bool isSettlement = true)
	{
		if (isAlreadySettled)
		{
			return;
		}
		isAlreadySettled = true;
		bool flag = false;
		if (isSettlement)
		{
			List<bool> list = judgeStar();
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i])
				{
					flag = true;
					break;
				}
			}
			isStartTime = false;
			LevelStateCallback(GameEnum.levelState.Success, 0);
			levelEndSendMsg(list);
		}
		else
		{
			LevelStateCallback(GameEnum.levelState.Failed, 0);
			List<bool> starBool = new List<bool> { false, false, false };
			levelEndSendMsg(starBool);
		}
		if (!flag)
		{
			return;
		}
		List<LogicEntity> monsterActors = ModuleController<AdventureModuleController>.Instance.monsterActors;
		if (monsterActors == null)
		{
			return;
		}
		for (int j = 0; j < monsterActors.Count; j++)
		{
			MonsterAdventureActor monsterAdventureActor = monsterActors[j] as MonsterAdventureActor;
			if (!monsterAdventureActor.isDead && monsterAdventureActor.monsterInfo.subType != GameEnum.monsterSubType.Trap)
			{
				monsterAdventureActor.DestroySelf();
			}
		}
	}

	private void levelEndSendMsg(List<bool> starBool)
	{
		MonoSingleton<LuaManager>.Instance.FireEvent("SkillInstanceGameEnd", starBool);
		CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
		CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
		ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
		static void Action()
		{
		}
	}

	private List<bool> judgeStar()
	{
		List<bool> list = new List<bool> { false, false, false };
		int num = 0;
		List<LogicEntity> monsterActors = ModuleController<AdventureModuleController>.Instance.monsterActors;
		for (int i = 0; i < monsterActors.Count; i++)
		{
			MonsterAdventureActor monsterAdventureActor = monsterActors[i] as MonsterAdventureActor;
			if (monsterAdventureActor != null && !monsterAdventureActor.isDead && monsterAdventureActor.monsterInfo.subType != GameEnum.monsterSubType.Trap && monsterAdventureActor.dataID == monsterId)
			{
				num = (int)(long)(monsterAdventureActor.actorHealthInfo.hpPercentage * 100);
				break;
			}
		}
		for (int j = 0; j < starCondition.Count; j++)
		{
			int num2 = starCondition[j];
			switch (starConditionType)
			{
			case 1:
				if (num <= num2)
				{
					list[j] = true;
				}
				break;
			case 2:
				if (killMonsterCount >= num2)
				{
					list[j] = true;
				}
				break;
			case 3:
				if (num2 != -1)
				{
					if (levelTime <= num2)
					{
						list[j] = true;
					}
				}
				else
				{
					list[j] = true;
				}
				break;
			}
		}
		return list;
	}

	private void MonsterSpawn(IEvent evt)
	{
		AdventureMonsterSpawnedEvent adventureMonsterSpawnedEvent = (AdventureMonsterSpawnedEvent)evt;
		if (adventureMonsterSpawnedEvent.dataID == monsterId && starConditionType == 1 && !typeHpSendUidToLua)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("Skill_Instance_Gameplay_TypeOne_UniqueID", adventureMonsterSpawnedEvent.id);
			typeHpSendUidToLua = true;
		}
	}

	public void MonsterDeath(IEvent evt)
	{
		if (((AdventureMonsterDiedEvent)evt).monsterID == monsterId && starConditionType == 2 && !isAlreadySettled)
		{
			killMonsterCount++;
			MonoSingleton<LuaManager>.Instance.FireEvent("Skill_Instance_Gameplay_TypeTwo_KillCount", killMonsterCount);
		}
	}

	public void MonsterDeclareDeath(IEvent evt)
	{
		if (((AdventureMonsterDeclareDiedEvent)evt).monsterID == monsterId && starConditionType == 1)
		{
			levelEnd();
		}
	}

	private void StartTiming(IEvent evt)
	{
		MonoSingleton<LuaManager>.Instance.FireEvent("Skill_Instance_Gameplay_Time", 0);
		isStartTime = true;
	}

	private void OnPlayerDied(IEvent ievent)
	{
		isStartTime = false;
		levelEnd(isSettlement: false);
	}

	private void MonsterClear(IEvent evt)
	{
		levelEnd();
	}

	private void CountDown()
	{
		levelTotalTime--;
		if (levelTotalTime <= 0)
		{
			isStartTime = false;
			levelEnd(isTimeEndSettlement);
		}
	}

	protected void TaskSettlement(IEvent evt)
	{
		object data = ((GeneralEvent)evt).data;
		if (data != null)
		{
			AdventureLevelTeleporter.NextLevelData nextLevelData = (AdventureLevelTeleporter.NextLevelData)data;
			isStartTime = false;
			levelEnd(nextLevelData.levelSuccess);
		}
	}
}
