public class SkillInstanceLevelController : AdventureLevelController
{
	private SkillInstance skillInstanceData;

	private SkillInstanceFloor skillInstanceFloor;

	private GameplayRoom room;

	public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
	{
		base.Load(param, callback);
		if (param == null)
		{
			callback?.Invoke();
			return;
		}
		if (base.isViewSceneMode)
		{
			skillInstanceFloor = Singleton<HotfixDataController>.Instance.GetSkillInstanceFloor(param.floor);
		}
		else
		{
			skillInstanceData = Singleton<HotfixDataController>.Instance.GetSkillInstance(CommonHelper.ParseStringParamToInt(param.id));
			skillInstanceFloor = Singleton<HotfixDataController>.Instance.GetSkillInstanceFloor(skillInstanceData.FloorId);
		}
		if (skillInstanceFloor != null)
		{
			scenePath = "Assets/AssetBundles/" + skillInstanceFloor.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string sceneName, int process)
			{
				LevelLoadProcessUpdate(sceneName, process);
				return true;
			});
			param.monsterLevel = skillInstanceFloor.MonsterLv;
			param.dropEntityGroupId = skillInstanceFloor.DropObjectGroupId;
			param.dropEntityRate = (float)skillInstanceFloor.DropObjectRate / 10000f;
			param.dropMaxNum = skillInstanceFloor.DropMaxNum;
			musicName = skillInstanceFloor.BGM;
			leaveMusicEvent = skillInstanceFloor.LeaveTriggerEvent;
		}
		else
		{
			Debug.LogError("SkillInstanceFloor data is null");
		}
	}

	protected override void LevelLoadComplete(string sceneName)
	{
		string[] array = sceneName.Split('/');
		string sceneName2 = array[array.Length - 1];
		Scene sceneByName = SceneManager.GetSceneByName(sceneName2);
		string assetName = scenePath + "/" + skillInstanceFloor.ConfigPrefabName + ".prefab";
		GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, assetName, typeof(GameObject)) as GameObject;
		if (gameObject != null)
		{
			configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
			configPrefab.transform.localScale = Vector3.one;
			configPrefab.name = skillInstanceFloor.ConfigPrefabName;
			SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
		}
		else
		{
			Debug.LogError("策划配置预制体加载失败：" + skillInstanceFloor.ConfigPrefabName);
		}
		GameObject[] rootGameObjects = sceneByName.GetRootGameObjects();
		foreach (GameObject gameObject2 in rootGameObjects)
		{
			if (gameObject2.name.Equals(skillInstanceFloor.ConfigPrefabName))
			{
				UnityEngine.Transform transform = gameObject2.transform.Find("==== Triggers ====");
				if (transform != null)
				{
					TriggerCom[] componentsInChildren = transform.GetComponentsInChildren<TriggerCom>();
					Singleton<TriggerManager>.Instance.AddTriggers(componentsInChildren, -1, -1);
					List<AdventureLevelTeleporter> list = transform.GetComponentsInChildren<AdventureLevelTeleporter>().ToList();
					if (list != null && list.Count > 0)
					{
						for (int j = 0; j < list.Count; j++)
						{
							AdventureLevelTeleporter adventureLevelTeleporter = list[j];
							adventureLevelTeleporter.SetPosition(-1, -1);
							adventureLevelTeleporter.RegisterTeleporterCallback(LevelTeleporterTriggered);
						}
						teleporters.AddRange(list);
					}
				}
			}
			else if (gameObject2.name.Equals("==== Triggers ===="))
			{
				AdventureLevelTeleporter[] componentsInChildren2 = gameObject2.GetComponentsInChildren<AdventureLevelTeleporter>();
				if (componentsInChildren2 != null && componentsInChildren2.Length > 0)
				{
					foreach (AdventureLevelTeleporter obj in componentsInChildren2)
					{
						obj.SetPosition(-1, -1);
						obj.RegisterTeleporterCallback(LevelTeleporterTriggered);
					}
					teleporters.AddRange(componentsInChildren2);
				}
			}
			if (gameObject2.name.Equals("==== Navigation ===="))
			{
				HandleNavigation(gameObject2, sceneName2);
			}
		}
		base.LevelLoadComplete(sceneName);
	}

	public override bool HasTimelinePerformance()
	{
		int num;
		if (skillInstanceFloor != null)
		{
			num = ((!string.IsNullOrEmpty(skillInstanceFloor.IntroCutscene)) ? 1 : 0);
			if (num != 0)
			{
				timelineName = skillInstanceFloor.IntroCutscene;
			}
		}
		else
		{
			num = 0;
		}
		return (byte)num != 0;
	}

	public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
	{
