	public class ElementTagManager
	{
		private readonly Dictionary<GameEnum.elementType, BaseElementTag> elementTagDic = new Dictionary<GameEnum.elementType, BaseElementTag>();

		public virtual void OnEnable()
		{
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE_BEFORE_SETTLEMENT", OnReceiveHit);
			EnableElementTagData();
		}

		public virtual void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE_BEFORE_SETTLEMENT", OnReceiveHit);
			elementTagDic.Clear();
		}

		private void EnableElementTagData()
		{
			List<PlayerAdventureActor> list = SceneSingleton<AdventurePlayerController>.Instance?.ActorLs;
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < list.Count; i++)
			{
				GameEnum.elementType elementType = list[i].actorElementInfo.elementType;
				if (!elementTagDic.ContainsKey(elementType))
				{
					BaseElementTag baseElementTag = CreateInstance(elementType);
					if (baseElementTag != null)
					{
						elementTagDic.Add(elementType, baseElementTag);
						baseElementTag.OnEnable();
						baseElementTag.actorFilterDic.Add(list[i].Id, list[i].dataID);
					}
				}
				else
				{
					elementTagDic[elementType].actorFilterDic.Add(list[i].Id, list[i].dataID);
				}
			}
		}

		private BaseElementTag CreateInstance(GameEnum.elementType type)
		{
			return type switch
			{
				GameEnum.elementType.AE => new ElementTag_Wind(), 
				GameEnum.elementType.DE => new ElementTag_Dark(), 
				GameEnum.elementType.FE => new ElementTag_Fire(), 
				GameEnum.elementType.LE => new ElementTag_Light(), 
				GameEnum.elementType.SE => new ElementTag_Land(), 
				GameEnum.elementType.WE => new ElementTag_Water(), 
				_ => null, 
			};
		}

		private void OnElementMarkTrigger(IEvent evt)
		{
			AdventureElementMarkTriggerEvent adventureElementMarkTriggerEvent = evt as AdventureElementMarkTriggerEvent;
			MonsterAdventureActor monster = adventureElementMarkTriggerEvent.markActor as MonsterAdventureActor;
			PlayerAdventureActor playerAdventureActor = adventureElementMarkTriggerEvent.triggerActor as PlayerAdventureActor;
			if (playerAdventureActor != null && elementTagDic.TryGetValue(playerAdventureActor.actorElementInfo.elementType, out var value))
			{
				value.OnEvent(adventureElementMarkTriggerEvent, playerAdventureActor, monster);
			}
		}

		private void OnReceiveHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeSettlementEvent adventureActorReceiveDamageBeforeSettlementEvent = evt as AdventureActorReceiveDamageBeforeSettlementEvent;
			MonsterAdventureActor monsterAdventureActor = adventureActorReceiveDamageBeforeSettlementEvent.to as MonsterAdventureActor;
			PlayerAdventureActor playerAdventureActor = adventureActorReceiveDamageBeforeSettlementEvent.from as PlayerAdventureActor;
			if (playerAdventureActor != null && adventureActorReceiveDamageBeforeSettlementEvent.hitDamageTag != null && monsterAdventureActor != null && elementTagDic.TryGetValue(playerAdventureActor.actorElementInfo.elementType, out var value))
			{
				value.OnBeHit(adventureActorReceiveDamageBeforeSettlementEvent, playerAdventureActor, monsterAdventureActor);
			}
		}
	}
	public class FateCardThemeManager : AIBase
	{
		private readonly List<BaseFateCardTheme> themes = new List<BaseFateCardTheme>();

		public virtual void OnEnable()
		{
			Init();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REFRESH_FATECARD_THEME", OnRefreshTheme);
		}

		public virtual void OnDisable()
		{
			Clear();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REFRESH_FATECARD_THEME", OnRefreshTheme);
		}

		private void OnRefreshTheme(IEvent _evt)
		{
			if (!(_evt is ActorRefreshFateCardTheme))
			{
				return;
			}
			foreach (Lua2CSharpInfo_FateCardThemeInfo fateCardThemeInfo in ModuleController<AdventureModuleController>.Instance.FateCardThemeInfos)
			{
				if (fateCardThemeInfo.operateType == 1)
				{
					CreateInstance(fateCardThemeInfo.theme, fateCardThemeInfo.rank, fateCardThemeInfo.triggerTypes);
				}
				else if (fateCardThemeInfo.operateType == 2)
				{
					RemoveOldTheme(fateCardThemeInfo.theme);
					CreateInstance(fateCardThemeInfo.theme, fateCardThemeInfo.rank, fateCardThemeInfo.triggerTypes);
				}
				else if (fateCardThemeInfo.operateType == 3)
				{
					RemoveOldTheme(fateCardThemeInfo.theme);
				}
			}
			void RemoveOldTheme(GameEnum.fateCardTheme themeType)
			{
				BaseFateCardTheme baseFateCardTheme = null;
				foreach (BaseFateCardTheme theme in themes)
				{
					if (theme.theme == themeType)
					{
						baseFateCardTheme = theme;
						break;
					}
				}
				if (baseFateCardTheme != null)
				{
					baseFateCardTheme.OnDisable();
					themes.Remove(baseFateCardTheme);
				}
			}
		}

		private void Init()
		{
			foreach (Lua2CSharpInfo_FateCardThemeInfo fateCardThemeInfo in ModuleController<AdventureModuleController>.Instance.FateCardThemeInfos)
			{
				CreateInstance(fateCardThemeInfo.theme, fateCardThemeInfo.rank, fateCardThemeInfo.triggerTypes);
			}
		}

		private void Clear()
		{
			for (int i = 0; i < themes.Count; i++)
			{
				themes[i].OnDisable();
				themes[i] = null;
			}
			themes.Clear();
		}

		private void CreateInstance(GameEnum.fateCardTheme theme, GameEnum.fateCardThemeRank rank, GameEnum.fateCardThemeTriggerType[] triggerTypes)
		{
			BaseFateCardTheme baseFateCardTheme = null;
			switch (theme)
			{
			case GameEnum.fateCardTheme.FireRing:
				baseFateCardTheme = new FateCard_FireRing();
				break;
			case GameEnum.fateCardTheme.FireWave:
				baseFateCardTheme = new FateCard_FireWave();
				break;
			case GameEnum.fateCardTheme.Meteor:
				baseFateCardTheme = new FateCard_FallingStone();
				break;
			case GameEnum.fateCardTheme.ChainLightning:
				baseFateCardTheme = new FateCard_LightingChain();
				break;
			case GameEnum.fateCardTheme.LightningBolt:
				baseFateCardTheme = new FateCard_LightingBolt();
				break;
			case GameEnum.fateCardTheme.WindBlade:
				baseFateCardTheme = new FateCard_WindBlade();
				break;
			case GameEnum.fateCardTheme.Blizzard:
				baseFateCardTheme = new FateCard_Blizzard();
				break;
			case GameEnum.fateCardTheme.WhirlWind:
				baseFateCardTheme = new FateCard_WhirlWind();
				break;
			case GameEnum.fateCardTheme.WindEagle:
				baseFateCardTheme = new FateCard_WindEagle();
				break;
			case GameEnum.fateCardTheme.LightingGhost:
				baseFateCardTheme = new FateCard_LightingGhost();
				break;
			case GameEnum.fateCardTheme.Shark:
				baseFateCardTheme = new FateCard_Shark();
				break;
			case GameEnum.fateCardTheme.CloudBottle:
				baseFateCardTheme = new FateCard_CloudBottle();
				break;
			case GameEnum.fateCardTheme.EarthSpike:
				baseFateCardTheme = new FateCard_EarthSpike();
				break;
			case GameEnum.fateCardTheme.EarthSpear:
				baseFateCardTheme = new FateCard_EarthSpear();
				break;
			case GameEnum.fateCardTheme.EarthQuake:
				baseFateCardTheme = new FateCard_EarthQuake();
				break;
			case GameEnum.fateCardTheme.EarthFissure:
				baseFateCardTheme = new FateCard_EarthFissure();
				break;
			case GameEnum.fateCardTheme.DarkBurst:
				baseFateCardTheme = new FateCard_Dark_DarkBurst();
				break;
			case GameEnum.fateCardTheme.NightPierce:
				baseFateCardTheme = new FateCard_Dark_NightPierce();
				break;
			case GameEnum.fateCardTheme.ShadowSphere:
				baseFateCardTheme = new FateCard_Dark_ShadowSphere();
				break;
			case GameEnum.fateCardTheme.VoidVortex:
				baseFateCardTheme = new FateCard_Dark_VoidVortex();
				break;
			}
			if (baseFateCardTheme != null)
			{
				baseFateCardTheme.OnInit(theme, rank, triggerTypes);
				baseFateCardTheme.OnEnable();
				themes.Add(baseFateCardTheme);
			}
		}
	}
