			GameObject gameObject = GameResourceLoader.LoadAsset(GameResourceLoader.ResourceType.Actor, "Assets/AssetBundles/FX/TowerDefence/fx_td_base_exp_point.prefab", typeof(GameObject)) as GameObject;
