		{
			if (ievent == null)
			{
				return;
			}
			bool flag = false;
			if (ievent is GeneralEvent generalEvent)
			{
				LuaTable obj = generalEvent.data as LuaTable;
				int intValue = 0;
				if (CommonHelper.TryParseStringParamToInt(obj[1].ToString(), out intValue))
				{
					flag = intValue == 1;
