		protected void OnStartDragRole(int roleID)
		{
			TryUnSelectRole();
			if (curRoles.TryGetValue(roleID, out var value))
			{
				dragState = DragState.Role;
				dragRoleID = roleID;
				dragRole = value;
				TowerDefenseMouseFollower towerDefenseMouseFollower = mouseFollower;
				towerDefenseMouseFollower.callback = (Action<Vector3>)Delegate.Combine(towerDefenseMouseFollower.callback, new Action<Vector3>(OnDrag));
				mouseFollower.StartFollow();
				dragRole.Visible();
				ActiveRoleOutline(roleID);
				ShowDragRoleTipQuads();
				FP fP = FP.One * 5;
				TowerDefenseCharacter towerDefenseCharacter = Singleton<HotfixDataController>.Instance.GetTowerDefenseCharacter(dragRoleID);
				if (towerDefenseCharacter != null)
				{
					fP = towerDefenseCharacter.SearchRadius * GameDataController.IntFloatPrecisionFP;
				}
				indicator.BindValue((float)fP, dragRole.gameObject);
			}
		}

		private void OnStartDragItem()
		{
			TryUnSelectRole();
			dragState = DragState.Item;
			indicator.BindValue(ItemIndicatorRng, (GameObject)null);
			ShowDragItemTipQuads();
		}

