		protected void ShowRoutes()
		{
			if (routeLines == null)
			{
				return;
			}
			List<TowerDefenseMapData.TowerDefenseRoute> routes = mapData.routes;
			for (int i = 0; i < routes.Count; i++)
			{
				TowerDefenseMapData.TowerDefenseRoute towerDefenseRoute = routes[i];
				if (!towerDefenseRoute.Reachable2End())
				{
					continue;
				}
				for (int j = 0; j < routeLines.Count; j++)
				{
					TowerDefenseMapLineController towerDefenseMapLineController = routeLines[j];
					if (towerDefenseMapLineController.id == towerDefenseRoute.id)
					{
						towerDefenseMapLineController.Show();
						break;
					}
				}
			}
		}

		protected void HideRoutes()
		{
			if (routeLines != null)
			{
				for (int i = 0; i < routeLines.Count; i++)
				{
					routeLines[i].Hide();
				}
			}
		}

		protected void ShowRoute(int id)
		{
			if (routeLines == null)
			{
				return;
			}
			List<TowerDefenseMapData.TowerDefenseRoute> routes = mapData.routes;
			for (int i = 0; i < routes.Count; i++)
			{
				TowerDefenseMapData.TowerDefenseRoute towerDefenseRoute = routes[i];
				if (id != routes[i].id)
				{
					continue;
				}
				if (!towerDefenseRoute.Reachable2End())
				{
					break;
				}
				for (int j = 0; j < routeLines.Count; j++)
				{
					if (routeLines[j].id == id)
					{
						routeLines[j].Show();
					}
				}
			}
		}

		protected void HideRoute(int id)
		{
			if (routeLines == null)
			{
				return;
			}
			for (int i = 0; i < routeLines.Count; i++)
			{
				if (routeLines[i].id == id)
				{
					routeLines[i].Hide();
				}
			}
		}

