	internal class TowerDefenseTipQuad
	{
		private GameObject tipQuad;

		private int index;

		private readonly string[] CHILDS = new string[6] { "pass", "select", "set", "lock", "self", "target" };

		public int Index => index;

		public void Init(GameObject tipQuad)
		{
			this.tipQuad = tipQuad;
			index = -1;
		}

		public void UpdateIndex(int index)
		{
			this.index = index;
		}

		public void UpdatePosition(Vector3 position)
		{
			tipQuad.transform.position = position;
		}

		public void UpdateState(string openChild)
		{
			for (int i = 0; i < CHILDS.Length; i++)
			{
				UnityEngine.Transform transform = tipQuad.transform.Find(CHILDS[i]);
				if (null == transform)
				{
					Debug.LogWarning(tipQuad.name + "没有找到子节点" + CHILDS[i]);
				}
				else
				{
					transform.gameObject.SetActive(value: false);
				}
			}
			if (string.IsNullOrEmpty(openChild))
			{
				index = -1;
				return;
			}
			UnityEngine.Transform transform2 = tipQuad.transform.Find(openChild);
			if (null != transform2)
			{
				transform2.gameObject.SetActive(value: true);
			}
		}

		public void Clear()
		{
			UnityEngine.Object.Destroy(tipQuad);
			tipQuad = null;
			index = -1;
		}
	}
	public abstract class TowerDefenseItemBase
	{
		protected float indicatorRange;

		public float IndicatorRng => indicatorRange;

		public virtual void InitConfig()
		{
		}

		public abstract void DoMainLogic(TSVector2 position);

		protected void PlayAreaEffect(int templeteID, string[] fxAlias, TSVector2 position)
		{
			if (fxAlias == null || fxAlias.Length == 0)
			{
				Debug.LogWarning($"播放区域效果，特效路径为空!{GetType()}");
				return;
			}
			long globAttributeId = GetGlobAttributeId(templeteID);
			FakeAdventureActor fakeActor = ModuleController<AdventureModuleController>.Instance.GetFakeActor(templeteID, globAttributeId, createNew: true, 1);
			if (null == fakeActor)
			{
				Debug.LogError($"创建FakeActor失败:templeteID_{templeteID},attributeID:{globAttributeId}");
				return;
			}
			for (int i = 0; i < fxAlias.Length; i++)
			{
				ILRuntimeAPI.PlayAreaEffect((AdventureActor)fakeActor, fxAlias[i], position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private long GetGlobAttributeId(int templeteID)
		{
			MonsterValueTempleteAdjust monsterValueTempleteAdjust = Singleton<GameDataController>.Instance.GetMonsterValueTempleteAdjust(templeteID);
			if (monsterValueTempleteAdjust != null)
			{
				int num = 1;
				int num2 = 1;
				return (long)monsterValueTempleteAdjust.TemplateId * 1000L + num2 * 10 + num;
			}
			Debug.LogError($"Task Trigger, MonsterValueTempleteAdjust Config Not Exist, Id:{templeteID}");
			return 0L;
		}
	}
