		protected RequestComboAttack BeginAttack(int keyIndex, ComboInputBuffer.ActionKey[] keys, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null)
		{
			if (requestComboAttack == null)
			{
				requestComboAttack = new RequestComboAttack();
			}
			requestComboAttack.Reset();
			requestComboAttack.comboIndex = keyIndex;
			if (comboAttack == null)
			{
				comboAttack = new ComboAttack();
			}
			ComboAttack obj = comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action action = onAnticipationEnd;
			System.Action action2 = onActivationEnd;
			System.Action action3 = onComboLoop;
			System.Action action4 = onRecoveryBegin;
			System.Action action5 = onComboFinish;
			System.Action action6 = onInterrupt;
			Action<string> action7 = onCustomEvent;
			System.Action action8 = onSendSkillTakeEffect;
			obj.BeginAttack(actor, skill, keys, flushInputedKeys, skillId, forceInterruptAttack, autoLookAtTarget, attackTarget, null, default(TSVector2), action, action4, action3, action5, action6, action7, action2, fadeOutAnim: true, action8);
			return requestComboAttack;
		}

		protected RequestComboAttack BeginAttack(int keyIndex, string actionKey, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null)
		{
			if (requestComboAttack == null)
			{
				requestComboAttack = new RequestComboAttack();
			}
			requestComboAttack.Reset();
			requestComboAttack.comboIndex = keyIndex;
			ref ComboAttack reference = ref comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action action = onAnticipationEnd;
			System.Action action2 = onActivationEnd;
			System.Action action3 = onComboLoop;
			System.Action action4 = onRecoveryBegin;
			System.Action action5 = onComboFinish;
			System.Action action6 = onInterrupt;
			Action<string> action7 = onCustomEvent;
			System.Action action8 = onSendSkillTakeEffect;
			ILRuntimeAPI.BeginComboAttack(ref reference, actor, skill, null, flushInputedKeys, skillId, forceInterruptAttack, autoLookAtTarget, attackTarget, null, default(TSVector2), action, action4, action3, action5, action6, action7, action2, fadeOutAnim: true, action8, keyPerfectMatch: false, actionKey);
			return requestComboAttack;
		}

