		}

		protected void SummonMonster(int summonActorID, int summonGroupID, TSVector2 spawnPosition, TSVector2 spawnDirection)
		{
			if (summonActorID > 0)
			{
				ILRuntimeAPI.SummonMonster(_actor, 0, summonActorID, spawnPosition, spawnDirection, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			}
