		private IEnumerator ContinueAimAtMonsterTarget(float limitAngle)
		{
			while (_actor != null)
			{
				if ((_actor.monsterTarget != null || aimTarget != null) && aimTarget?.Id != _actor.monsterTarget?.Id)
				{
					_actor.CancelAiming();
					aimTarget = _actor.monsterTarget;
					if (aimTarget != null)
					{
						_actor.AimAtTarget(aimTarget, limitAngle, -1);
					}
				}
				yield return WaitFrame(1);
			}
		}

