		{
			if (!(_actor == null))
			{
				if (moveReq == null)
				{
					moveReq = new RequestDefaultState();
				}
				AdventureActor actor = _actor;
				System.Action onLeave = MoveFinish;
				bool stopDisIgnoreRadius = _stopDisIgnoreRadius;
				if (actor.MoveTo(position, stopDistance, enableNavigation: true, moveMode, null, randomMove: false, forceMove: false, default(FP), onLeave, stayWhenReachTarget: false, stopDisIgnoreRadius))
				{
					moveReq.Reset();
					StartCor(ref waitDurationCorNode, waitMoveDuration(_maxDuration));
				}
				else
				{
					MoveFinish();
				}
			}
		}

