		protected IEnumerator blink(ComboInputBuffer.ActionKey[] hideKeys, TSVector2 blinkPosition, FP blinkDuration, string blinkBeginFx, FP blinkHideDelay, string blinkFinishFx, FP blinkShowDelay, LogicEntity target = null, ComboInputBuffer.ActionKey[] showKeys = null, int showCombWaitIndex = 1)
		{
			if (hideKeys != null && hideKeys.Length != 0)
			{
				BeginAttack(100, hideKeys, flushInputedKeys: true, forceInterruptAttack: true);
			}
			if (!string.IsNullOrEmpty(blinkBeginFx))
			{
				PlayFx(blinkBeginFx, (float)_actor.logicTimeScale, 0, _actor.tsTransform.Position, default(FP), _actor.transform);
			}
			yield return WaitTime(blinkHideDelay);
			HideSelf();
			Teleport(blinkPosition);
			yield return WaitTime(blinkDuration);
			if (target != null)
			{
				yield return BeginLookAt(target, 0, 0);
			}
			if (!string.IsNullOrEmpty(blinkFinishFx))
			{
				PlayFx(blinkFinishFx, (float)_actor.logicTimeScale, 0, _actor.tsTransform.Position, default(FP), _actor.transform);
			}
			yield return WaitTime(blinkShowDelay);
			if (showKeys != null && showKeys.Length != 0)
			{
				BeginAttack(101, showKeys, flushInputedKeys: true, forceInterruptAttack: true);
				_actor.Visible();
				yield return WaitFrame(showCombWaitIndex);
				_actor.DisableInvincible();
				_actor.DisableSearchedImmunity();
			}
			else
			{
				ShowSelf();
			}
		}

