	public class BaseBranchInfo
	{
		public int id;

		public FP releaseDistance;

		public FP releaseAngle;

		public FP traceDuration;

		public Func<bool> finishTraceConditionFunc;

		public MonsterActionBase.OperateDelegate operateIEnumerator;

		public System.Action operateCompleteCallback;

		public BaseBranchInfo(int id, FP releaseDistance = default(FP), FP releaseAngle = default(FP), FP traceDuration = default(FP), Func<bool> finishTraceConditionFunc = null, MonsterActionBase.OperateDelegate operateIEnumerator = null, System.Action operateCompleteCallback = null)
		{
			this.id = id;
			this.releaseDistance = ((releaseDistance == default(FP)) ? ((FP)999) : releaseDistance);
			this.releaseAngle = ((releaseAngle == default(FP)) ? ((FP)360) : releaseAngle);
			this.traceDuration = ((traceDuration == default(FP)) ? ((FP)5) : traceDuration);
			this.finishTraceConditionFunc = finishTraceConditionFunc;
			this.operateIEnumerator = operateIEnumerator;
			this.operateCompleteCallback = operateCompleteCallback;
		}
	}
	public class PoolBranchesInfo
	{
		public int index;

		public List<PoolBranchInfo> braches;

		public void ResetBranchCdExpireTime()
		{
			if (braches == null || braches.Count <= 0)
			{
				return;
			}
			foreach (PoolBranchInfo brach in braches)
			{
				brach.ResetBranchCdExpireTime();
			}
		}
	}
	public class PoolBranchInfo : BaseBranchInfo
	{
		public int priority;

		public FP cd;

		private FP initCd;

		public bool active;

		public Func<bool> operationConditionFunc;

		public FP startCdTime;

		public FP branchCdExpireTime;

		private AdventureActor actor;

		public PoolBranchInfo(AdventureActor actor, int id, int priority, FP cd, FP initCd, bool active = true, FP releaseDistance = default(FP), FP releaseAngle = default(FP), FP traceDuration = default(FP), Func<bool> operationConditionFunc = null, Func<bool> finishTraceConditionFunc = null, MonsterActionBase.OperateDelegate operateIEnumerator = null, System.Action operateCompleteCallback = null, FP startCdTime = default(FP))
			: base(id, releaseDistance, releaseAngle, traceDuration, finishTraceConditionFunc, operateIEnumerator, operateCompleteCallback)
		{
			this.actor = actor;
			this.priority = priority;
			this.cd = cd;
			this.initCd = initCd;
			this.active = active;
			this.operationConditionFunc = operationConditionFunc;
			this.startCdTime = startCdTime;
			ResetBranchCdExpireTime();
		}

		public void SetBranchCdExpireTime(FP cd)
		{
			branchCdExpireTime = actor.LogicTime + cd;
		}

		public void ResetBranchCdExpireTime()
		{
			branchCdExpireTime = actor.LogicTime + initCd;
		}

		public void SetBranchActive(bool active)
		{
			this.active = active;
		}
	}
	public class ParallelBase : AIBase
	{
		private Dictionary<long, FP> _perkTimeDic;

		public virtual void OnEnable()
		{
		}

		public virtual void OnDisable()
		{
			_perkTimeDic?.Clear();
		}

		protected override bool CheckPerkCd(long perkId, FP Cd)
		{
			if (Cd <= 0 || Cd == default(FP))
			{
				return true;
			}
			if (_perkTimeDic == null)
			{
				_perkTimeDic = new Dictionary<long, FP>(10);
			}
			if (_perkTimeDic.TryGetValue(perkId, out var value))
			{
				if (_actor.LogicTime - value > Cd)
				{
					_perkTimeDic[perkId] = _actor.LogicTime;
					return true;
				}
				return false;
			}
			_perkTimeDic.Add(perkId, _actor.LogicTime);
			return true;
		}

		protected void SetPerkCd(long perkId)
		{
			if (_perkTimeDic == null)
			{
				_perkTimeDic = new Dictionary<long, FP>(10);
			}
			if (_perkTimeDic.TryGetValue(perkId, out var _))
			{
				_perkTimeDic[perkId] = _actor.LogicTime;
			}
			else
			{
				_perkTimeDic.Add(perkId, _actor.LogicTime);
			}
		}

		protected bool IsTeamMember(AdventureActor advAc)
		{
			if (advAc == null)
			{
				return false;
			}
			if (advAc is PlayerAdventureActor)
			{
				return true;
			}
			return false;
		}
	}
