	public class SkillAdvancedBase : AIBase
	{
		protected bool _isDisableByLostControl;

		private bool _isReceiveSkillTakeEffect;

		private ComboAttack _comboAttack;

		private AimTarget _aim;

		public ComboAttack comboAttack => _comboAttack;

		public void OnEnable()
		{
			_actor = _skill.actor;
			_isDisableByLostControl = false;
			_isReceiveSkillTakeEffect = false;
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_BE_CONTROLLED", OnActorBeControlled);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			OnSkillEnable();
		}

		public void OnDisable()
		{
			ILRuntimeAPI.ClearComboAttack(_comboAttack);
			if (_actor is PlayerAdventureActor && _skill.checkCdRestore && !_isReceiveSkillTakeEffect)
			{
				ILRuntimeAPI.ReturnSkillResumeTime(_skill.skillId, _actor);
			}
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_BE_CONTROLLED", OnActorBeControlled);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			CancelLockDirection();
			OnSkillDisable();
		}

		protected virtual void OnSkillDisable()
		{
		}

		protected virtual void OnSkillEnable()
		{
		}

		protected virtual void OnActorDied(IEvent evt)
		{
			if (_actor != null && _actor == (evt as AdventureActorDiedEvent).actor)
			{
				_skill?.Clear();
			}
		}

		protected virtual void OnActorLostControl(IEvent evt)
		{
			if (_actor != null && _actor == (evt as AdventureActorLostControlEvent).actor)
			{
				_isDisableByLostControl = true;
				_skill?.Clear();
			}
		}

		protected virtual void OnActorBeControlled(IEvent evt)
		{
			if (_actor != null && _actor == (evt as AdventureActorBeControlledEvent).actor)
			{
				_isDisableByLostControl = true;
				_skill?.Clear();
			}
		}

		protected virtual void OnReceiveAttack(IEvent evt)
		{
		}

		protected virtual void OnReceiveDamage(IEvent evt)
		{
		}

		protected IEnumerator Finish(FP waitSeconds)
		{
			if (waitSeconds > 0)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitSeconds));
			}
			_skill?.Clear();
		}

		protected void SetSkillPhaseConfig(SkillPhaseFeatureFlag executeConfigFlag, List<int> executeConfigSkillIds, SkillPhaseFeatureFlag breakConfigFlag, List<int> breakConfigSkillIds)
		{
			if (_skill != null)
			{
				_skill.SetCurrentPhaseExecuteConfig(new SkillPhaseConfig
				{
					skillPhaseFeatureFlag = executeConfigFlag,
					skillIds = executeConfigSkillIds
				});
				_skill.SetCurrentPhaseBreakConfig(new SkillPhaseConfig
				{
					skillPhaseFeatureFlag = breakConfigFlag,
					skillIds = breakConfigSkillIds
				});
			}
		}

		protected RequestComboAttack BeginAttack(ComboInputBuffer.ActionKey key, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null, LogicEntity aimTarget = null, TSVector2 aimTargetPosition = default(TSVector2), System.Action onAnticipationEnd = null, System.Action onRecoveryBegin = null, System.Action onComboFinish = null, System.Action onInterrupt = null, Action<string> onCustomEvent = null, System.Action onActivationEnd = null, bool fadeOutAnim = false, System.Action onComboLoop = null, bool recoveryBeginCheckCdStart = true)
		{
			ComboInputBuffer.ActionKey[] keys = new ComboInputBuffer.ActionKey[1] { key };
			return BeginAttack(keys, "", flushInputedKeys, forceInterruptAttack, autoLookAtTarget, attackTarget, aimTarget, aimTargetPosition, onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd, fadeOutAnim, onComboLoop, recoveryBeginCheckCdStart);
		}

		protected RequestComboAttack BeginAttack(ComboInputBuffer.ActionKey[] keys, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null, LogicEntity aimTarget = null, TSVector2 aimTargetPosition = default(TSVector2), System.Action onAnticipationEnd = null, System.Action onRecoveryBegin = null, System.Action onComboFinish = null, System.Action onInterrupt = null, Action<string> onCustomEvent = null, System.Action onActivationEnd = null, bool fadeOutAnim = false, System.Action onComboLoop = null, bool recoveryBeginCheckCdStart = true)
		{
			return BeginAttack(keys, "", flushInputedKeys, forceInterruptAttack, autoLookAtTarget, attackTarget, aimTarget, aimTargetPosition, onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd, fadeOutAnim, onComboLoop, recoveryBeginCheckCdStart);
		}

		protected RequestComboAttack BeginAttack(string actionTag, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null, LogicEntity aimTarget = null, TSVector2 aimTargetPosition = default(TSVector2), System.Action onAnticipationEnd = null, System.Action onRecoveryBegin = null, System.Action onComboFinish = null, System.Action onInterrupt = null, Action<string> onCustomEvent = null, System.Action onActivationEnd = null, bool fadeOutAnim = false, System.Action onComboLoop = null, bool recoveryBeginCheckCdStart = true)
		{
			return BeginAttack(null, actionTag, flushInputedKeys, forceInterruptAttack, autoLookAtTarget, attackTarget, aimTarget, aimTargetPosition, onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd, fadeOutAnim, onComboLoop, recoveryBeginCheckCdStart);
		}

		private RequestComboAttack BeginAttack(ComboInputBuffer.ActionKey[] keys, string actionTag, bool flushInputedKeys = false, bool forceInterruptAttack = false, bool autoLookAtTarget = false, LogicEntity attackTarget = null, LogicEntity aimTarget = null, TSVector2 aimTargetPosition = default(TSVector2), System.Action onAnticipationEnd = null, System.Action onRecoveryBegin = null, System.Action onComboFinish = null, System.Action onInterrupt = null, Action<string> onCustomEvent = null, System.Action onActivationEnd = null, bool fadeOutAnim = false, System.Action onComboLoop = null, bool recoveryBeginCheckCdStart = true)
		{
			RequestComboAttack requestComboAttack = new RequestComboAttack();
			_skill.isActivationEnd = false;
			ILRuntimeAPI.BeginComboAttack(ref _comboAttack, _actor, _skill, keys, flushInputedKeys, (_skill != null) ? _skill.skillId : 0, forceInterruptAttack, autoLookAtTarget, attackTarget, aimTarget, aimTargetPosition, delegate
			{
				requestComboAttack.isAnticipationEnd = true;
				onAnticipationEnd?.Invoke();
			}, delegate
			{
				requestComboAttack.isRecoveryBegin = true;
				if (recoveryBeginCheckCdStart && _skill.CountdownTiming == SkillCountdownTiming.End)
				{
					_skill.SetResumeTime();
				}
				onRecoveryBegin?.Invoke();
				_skill.isActivationEnd = false;
			}, delegate
			{
				onComboLoop?.Invoke();
			}, delegate
			{
				requestComboAttack.isComboFinish = true;
				onComboFinish?.Invoke();
			}, delegate
			{
				requestComboAttack.isComboFinish = true;
				onInterrupt?.Invoke();
			}, delegate(string eventName)
			{
				onCustomEvent?.Invoke(eventName);
			}, delegate
			{
				requestComboAttack.isActivationEnd = true;
				onActivationEnd?.Invoke();
				_skill.isActivationEnd = true;
				if (_skill.isDodgeSkill)
				{
					(_actor as PlayerAdventureActor)?.dodgeSkillActivationEndEvent?.Invoke();
				}
			}, fadeOutAnim, delegate
			{
				_isReceiveSkillTakeEffect = true;
			}, keyPerfectMatch: false, actionTag);
			return requestComboAttack;
		}

		public void BeginTurn(FP turnTime, System.Action onComplete = null, System.Action onInterrupted = null)
		{
			if (turnTime < 0.2)
			{
				onComplete?.Invoke();
			}
			else if (turnTime >= 0.2 && turnTime < 0.4)
			{
				System.Action onComboFinish = onComplete;
				BeginAttack(ComboInputBuffer.ActionKey.U, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish);
			}
			else if (turnTime >= 0.4 && turnTime < 0.6)
			{
				System.Action onComboFinish = onComplete;
				BeginAttack(ComboInputBuffer.ActionKey.V, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish);
			}
			else if (turnTime >= 0.6 && turnTime < 0.8)
			{
				System.Action onComboFinish = onComplete;
				BeginAttack(ComboInputBuffer.ActionKey.W, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish);
			}
			else
			{
				System.Action onComboFinish = onComplete;
				BeginAttack(ComboInputBuffer.ActionKey.X, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish);
			}
		}

		protected void LockDirection(TSVector2 direction = default(TSVector2))
		{
			if (_aim == null)
			{
				_aim = new AimTarget();
			}
			if (direction != default(TSVector2))
			{
				_aim.Aim(_actor, null, direction);
			}
			else if (_actor.attackTarget != null)
			{
				_aim.Aim(_actor, _actor.attackTarget as AdventureActor);
			}
		}

		protected void CancelLockDirection()
		{
			_aim?.Cancel();
			_aim?.Clear();
		}

		protected void DefaultLookAt(bool useInputDirectionFirst = false, bool useSemiAutoBattleMode = false)
		{
			if (_actor.aimMode != AdventureActor.AimMode.Forward)
			{
				return;
			}
			if (useSemiAutoBattleMode && ModuleController<AdventureModuleController>.Instance.SemiAutoBattle)
			{
				if (_actor.attackTarget != null)
				{
					_actor.LookAt(_actor.attackTarget.tsTransform.Position, 0);
				}
				return;
			}
			TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (useInputDirectionFirst && movementInputDirection != TSVector2.zero)
			{
				_actor.LookAtDir(movementInputDirection, 0);
			}
			else if (_actor.attackTarget != null)
			{
				_actor.LookAt(_actor.attackTarget.tsTransform.Position, 0);
			}
		}
	}
	public class ThemeManager : AIBase
	{
		private readonly List<BaseTheme> themeClsList = new List<BaseTheme>();

		public virtual void OnEnable()
		{
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REFRESH_THEMEPERK", OnRefreshTheme);
			ParseThemeData();
			for (int i = 0; i < themeClsList.Count; i++)
			{
				themeClsList[i].OnEnable();
			}
		}

		public virtual void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REFRESH_THEMEPERK", OnRefreshTheme);
			for (int i = 0; i < themeClsList.Count; i++)
			{
				themeClsList[i].OnDisable();
			}
			themeClsList.Clear();
		}

		private void ParseThemeData()
		{
			List<int> perkThemes = ModuleController<AdventureModuleController>.Instance.PerkThemes;
			if (perkThemes == null)
			{
				return;
			}
			foreach (int item in perkThemes)
			{
				CreateInstance((HotfixEnum.rglTheme)item);
			}
		}

		private void CreateInstance(HotfixEnum.rglTheme type)
		{
			switch (type)
			{
			case HotfixEnum.rglTheme.FireRing:
				themeClsList.Add(new Theme_FireRing());
				break;
			case HotfixEnum.rglTheme.FireWave:
				themeClsList.Add(new Theme_FireWave());
				break;
			case HotfixEnum.rglTheme.Meteor:
				themeClsList.Add(new Theme_FallingStone());
				break;
			case HotfixEnum.rglTheme.LightningBall:
				themeClsList.Add(new Theme_ElectroBall());
				break;
			case HotfixEnum.rglTheme.ChainLightning:
				themeClsList.Add(new Theme_LightingChain());
				break;
			case HotfixEnum.rglTheme.FireBall:
				themeClsList.Add(new Theme_FireBall());
				break;
			case HotfixEnum.rglTheme.LightningBolt:
				themeClsList.Add(new Theme_LightningBolt());
				break;
			case HotfixEnum.rglTheme.WindBlade:
				themeClsList.Add(new Theme_WindBlade());
				break;
			case HotfixEnum.rglTheme.Blizzard:
				themeClsList.Add(new Theme_Blizzard());
				break;
			case HotfixEnum.rglTheme.WhirlWind:
				themeClsList.Add(new Theme_WhirlWind());
				break;
			case HotfixEnum.rglTheme.WindEagle:
				themeClsList.Add(new Theme_WindEagle());
				break;
			case HotfixEnum.rglTheme.WindArea:
				themeClsList.Add(new Theme_WindArea());
				break;
			case HotfixEnum.rglTheme.LightingGhost:
				themeClsList.Add(new Theme_LightingGhost());
				break;
			case HotfixEnum.rglTheme.Shark:
				themeClsList.Add(new Theme_Shark());
				break;
			case HotfixEnum.rglTheme.CloudBottle:
				themeClsList.Add(new Theme_CloudBottle());
				break;
			case HotfixEnum.rglTheme.FreezeArea:
				themeClsList.Add(new Theme_FreezeArea());
				break;
			}
		}

		private void OnRefreshTheme(IEvent _evt)
		{
			if (_evt is ActorRefreshThemePerk)
			{
				for (int i = 0; i < themeClsList.Count; i++)
				{
					themeClsList[i].OnDisable();
					themeClsList[i] = null;
				}
				themeClsList.Clear();
				ParseThemeData();
				for (int j = 0; j < themeClsList.Count; j++)
				{
					themeClsList[j].OnEnable();
				}
			}
		}
	}
}
namespace AIScript.Trigger
{
	public class BianSuCiKeController_Lv1 : AIBase
	{
		private int killTime = 15;

		private FP curTime;

		private int count;

		private readonly int TeamId = 5050500;

		private readonly int shieldBuffId = 501619910;

		private readonly FP wakeupDistance = 9;

		private readonly FP attackInterval_phase1 = 0.5;

		private FP attackInterval_phase2 = 3;

		private readonly FP attackInterval_phase2_min = 3;

		private readonly FP attackInterval_phase2_decrease = 0;

		private readonly List<List<int>> skillGroupConfig = new List<List<int>>
		{
			new List<int> { 1, 1, 2 },
			new List<int> { 1, 1, 3 },
			new List<int> { 1, 2, 3 },
			new List<int> { 2, 2, 3 },
			new List<int> { 2, 2, 3 },
			new List<int> { 2, 1, 3 }
		};

		private readonly FP shootLoopTimeAdditional = 1;

		private int leaderMonsterId;

		private int monsterId;

		private AdventureMonsterBiansucikeMessage messageEvent;

		private List<string> optionSkillNames = new List<string> { "castSkill_dash", "castSkill_shoot", "castSkill_topDown" };

		private bool wakeupChecked;

		private List<LogicEntity> monsters;

		private long leaderId;

		private AdventureActor leader;

		private int summonCount;

		private bool summonFinish;

		private bool summonBegin;

		private int actionPhase;

		private FP time_count_phase;

		private Queue<int> selectedSkills = new Queue<int>();

		private List<int> options = new List<int>();

		private List<long> freeMonsters = new List<long>();

		private int skillIndexCount;

		private List<int> selectedSkillGroup;

		private bool isVolley;

		private bool isVolleyDuring;

		private int liveMonsterCount;

		private bool castingSkill;

		private bool leaderHide;

		private bool FirstInP2;

		private PlayerAdventureActor mainCtr => SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;

		public void OnEnable_Partial()
		{
			curTime = 0;
			count = 0;
		}

		public void OnDied_Partial(int _monsterId)
		{
			if (_monsterId == leaderMonsterId || _monsterId == monsterId)
			{
				if (curTime <= 0)
				{
					curTime = mainCtr.LogicTime;
				}
				count++;
				if (count >= 3 && mainCtr.LogicTime - curTime < killTime && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.SanJianKe_002))
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.SanJianKe_002);
				}
			}
		}

		public void OnEnable()
		{
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_BIANSUCIKE_MESSAGE", OnReceiveMessage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_BREAK_SHIELD", OnShieldBreak);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			monsters = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(CommonHelper.GetMonsterTeammateId(TeamId, 1));
			leader = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(CommonHelper.GetMonsterTeammateId(TeamId, 0))?[0] as AdventureActor;
			if (leader != null)
			{
				leaderId = leader.Id;
				leaderMonsterId = leader.dataID;
				monsters.Add(leader);
				monsterId = (monsters[0] as AdventureActor).dataID;
			}
			liveMonsterCount = monsters.Count;
			FirstInP2 = true;
			OnEnable_Partial();
		}

		public void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_BIANSUCIKE_MESSAGE", OnReceiveMessage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_BREAK_SHIELD", OnShieldBreak);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			wakeupChecked = false;
			leaderId = 0L;
			summonCount = 0;
			summonFinish = false;
			summonBegin = false;
			actionPhase = 0;
			time_count_phase = 0;
			monsters?.Clear();
			selectedSkills?.Clear();
			options?.Clear();
			freeMonsters?.Clear();
			skillIndexCount = 0;
			selectedSkillGroup?.Clear();
			isVolley = false;
			castingSkill = false;
			leaderHide = false;
			isVolleyDuring = false;
		}

		private void OnActorDied(IEvent evt)
		{
			if (evt is AdventureActorDiedEvent adventureActorDiedEvent)
			{
				if (freeMonsters.Contains(adventureActorDiedEvent.actor.Id))
				{
					freeMonsters.Remove(adventureActorDiedEvent.actor.Id);
				}
				if (monsters.Contains(adventureActorDiedEvent.actor))
				{
					monsters.Remove(adventureActorDiedEvent.actor);
				}
				liveMonsterCount = monsters.Count;
				if (actionPhase == 2 && freeMonsters.Count == liveMonsterCount)
				{
					isVolleyDuring = false;
					castingSkill = false;
				}
				OnDied_Partial(adventureActorDiedEvent.actor.dataID);
			}
		}

		public void OnUpdate()
		{
			//IL_01d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_01de: Unknown result type (might be due to invalid IL or missing references)
			if (!wakeupChecked && ILRuntimeAPI.CalcDistanceBetweenMonsterAndPlayer(leader) <= wakeupDistance)
			{
				SendOperateMessage(leaderId, "wakeUpLeader");
				wakeupChecked = true;
			}
			if (summonBegin)
			{
				summonBegin = false;
				SendOperateMessage(leaderId, "castSkill_summon");
			}
			if (!summonFinish && summonCount == 2)
			{
				summonFinish = true;
				actionPhase = 2;
				time_count_phase = 0;
				foreach (LogicEntity monster in monsters)
				{
					string message = "castSkill_hide_1";
					if (monster.Id == leaderId)
					{
						message = "castSkill_hide_2";
					}
					SendOperateMessage(monster.Id, message);
				}
			}
			if (leaderHide)
			{
				leaderHide = false;
				SendOperateMessage(leaderId, "castSkill_hide_1");
			}
			if (!castingSkill && actionPhase == 1)
			{
				time_count_phase += LockStepManager.deltaTime;
				if (time_count_phase >= attackInterval_phase1)
				{
					time_count_phase = 0;
					options.Clear();
					options.Add(1);
					options.Add(2);
					options.Add(3);
					if (selectedSkills.Count == 2)
					{
						if (((IEnumerable<int>)selectedSkills).Distinct().Count() == 1)
						{
							options.Remove(selectedSkills.Peek());
						}
					}
					else if (selectedSkills.Count == 3 && ((IEnumerable<int>)selectedSkills).Distinct().Count() == 2)
					{
						Enumerator<int> enumerator2 = selectedSkills.GetEnumerator();
						try
						{
							while (enumerator2.MoveNext())
							{
								int current2 = enumerator2.Current;
								options.Remove(current2);
							}
						}
						finally
						{
							((IDisposable)enumerator2/*cast due to constrained. prefix*/).Dispose();
						}
					}
					SelectRandomSkillForPhase1();
				}
			}
			if (actionPhase != 2)
			{
				return;
			}
			if (!isVolley)
			{
				if (FirstInP2)
				{
					attackInterval_phase2 = 2;
					FirstInP2 = false;
				}
				else
				{
					attackInterval_phase2 = 3;
				}
				time_count_phase += LockStepManager.deltaTime;
				if (!isVolleyDuring && time_count_phase >= attackInterval_phase2 && freeMonsters.Count > 0)
				{
					time_count_phase = 0;
					long num = freeMonsters[0];
					freeMonsters.RemoveAt(0);
					if (skillIndexCount == 0)
					{
						selectedSkillGroup = skillGroupConfig[UnityEngine.Random.Range(0, 2)];
					}
					else if (skillIndexCount == 3)
					{
						selectedSkillGroup = skillGroupConfig[UnityEngine.Random.Range(2, 4)];
					}
					else if (skillIndexCount == 6)
					{
						selectedSkillGroup = skillGroupConfig[UnityEngine.Random.Range(4, 6)];
					}
					if (selectedSkillGroup == null || selectedSkillGroup.Count < 3)
					{
						selectedSkillGroup = skillGroupConfig[0];
					}
					int index = skillIndexCount % 3;
					index = selectedSkillGroup[index];
					skillIndexCount++;
					if (skillIndexCount == 9)
					{
						skillIndexCount = 0;
						attackInterval_phase2 -= attackInterval_phase2_decrease;
						attackInterval_phase2 = TSMath.Max(attackInterval_phase2, attackInterval_phase2_min);
					}
					SendOperateMessage(num, optionSkillNames[index - 1]);
				}
			}
			else
			{
				if (freeMonsters.Count != liveMonsterCount)
				{
					return;
				}
				isVolley = false;
				isVolleyDuring = true;
				freeMonsters.Clear();
				foreach (LogicEntity monster2 in monsters)
				{
					(monster2 as AdventureActor).logicVariable.ToggleLogicTag("isVolley", value: true);
					(monster2 as AdventureActor).logicVariable.SetLogicTagValue("shootLoopTimeAdditional", shootLoopTimeAdditional);
					SendOperateMessage(monster2.Id, optionSkillNames[1]);
				}
			}
		}

		private void SelectRandomSkillForPhase1()
		{
			int index = UnityEngine.Random.Range(0, options.Count);
			int num = options[index];
			selectedSkills.Enqueue(num);
			if (((IEnumerable<int>)selectedSkills).Count() > 3)
			{
				selectedSkills.Dequeue();
			}
			SendOperateMessage(leaderId, optionSkillNames[num - 1]);
		}

		private void SendOperateMessage(long monsterId, string message)
		{
			messageEvent = AdventureMonsterBiansucikeMessage.Generate();
			messageEvent.monsterId = monsterId;
			messageEvent.operationType = message;
			ModuleController<AdventureModuleController>.Instance.DispatchEvent(messageEvent);
			if (message.Contains("castSkill"))
			{
				castingSkill = true;
			}
		}

		private void OnReceiveMessage(IEvent evt)
		{
			if (!(evt is AdventureMonsterBiansucikeMessage adventureMonsterBiansucikeMessage))
			{
				return;
			}
			if (adventureMonsterBiansucikeMessage.operationType == "summonFinish")
			{
				if (adventureMonsterBiansucikeMessage.monsterId != leaderId)
				{
					summonCount++;
					return;
				}
				leaderHide = true;
				actionPhase = 1;
			}
			else
			{
				if (!(adventureMonsterBiansucikeMessage.operationType == "skillFinish"))
				{
					return;
				}
				if (actionPhase == 0 || actionPhase == 1)
				{
					castingSkill = false;
				}
				else if (actionPhase == 2)
				{
					if (!freeMonsters.Contains(adventureMonsterBiansucikeMessage.monsterId))
					{
						freeMonsters.Add(adventureMonsterBiansucikeMessage.monsterId);
					}
					if (freeMonsters.Count == liveMonsterCount)
					{
						isVolleyDuring = false;
						castingSkill = false;
					}
				}
			}
		}

		private void OnShieldBreak(IEvent evt)
		{
			if (((evt as AdventureActorBreakShield).sender as AdventureActor).Id == leaderId)
			{
				leader?.buffComponent?.RemoveBuffByBuffId(shieldBuffId);
				summonBegin = true;
				actionPhase = 0;
			}
		}
	}
