			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(501509, out var perkLevel2))
			{
				AdventureActor.AddFromAttr(additionalAttrIdDic_9[perkLevel2], base._actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(501514, out var perkLevel3) && CheckPerkCDTimeout(501514, cd_14) && (CommonUtils.CheckElementMark(CommonDefine.Water, monsterAdventureActor) || TSRandom.Range(0f, 100f) <= triggerPercentageDic_14[perkLevel3]))
			{
