		private IEnumerator CheckLogic_Perk11(FP checkInteval)
		{
			FP interval = checkInteval;
			while (interval > 0)
			{
				if (ElectroBallCount >= _electroBallEntity.maxCount)
				{
					interval = checkInteval;
				}
				else
				{
					interval -= base.LogicDeltaTime;
					if (interval < 0)
					{
						GenerateElectroBall(500401);
						interval = checkInteval;
					}
				}
				yield return null;
			}
		}

		private IEnumerator CheckLogic_Perk14(FP checkInteval)
		{
			FP interval = checkInteval;
			while (interval > 0)
			{
				if (ElectroBallCount >= _electroBallEntity.maxCount)
				{
					interval -= base.LogicDeltaTime;
					if (interval < 0)
					{
						AdventureActor actor = base._actor;
						TSVector2 position = base._actor.tsTransform.Position;
						ILRuntimeAPI.Shoot("Misc/FateCard/Theme_ElectroBall_14", actor, default(FP), default(TSVector2), default(FP), position, null, AimType.Position, BulletDirectionType.BulletToTarget);
						interval = checkInteval;
					}
				}
				else
				{
					interval = checkInteval;
				}
				yield return null;
			}
		}

