		private void GenerateElectroBall(int hitDamageId, bool isInfinite = false)
		{
			if (_electroBallEntity == null)
			{
				return;
			}
			CommonUtils.PlayOneOffFx(base._actor, "FX/Perk/fx_perk_base_light_trigger_s");
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500416, out var _) && ElectroBallCount >= _electroBallEntity.maxCount)
			{
				LogicEntity logicEntity = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, searchRadius_Task_1);
				if (logicEntity != null)
				{
					TSVector2 firstElectroBallPosition = _electroBallEntity.GetFirstElectroBallPosition();
					AdventureActor actor = base._actor;
					LogicEntity target = logicEntity;
					ILRuntimeAPI.Shoot("Misc/FateCard/Theme_ElectroBall_13", actor, default(FP), firstElectroBallPosition, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				}
			}
			_electroBallEntity.GenerateElectroBall(base._actor, hitDamageId, isInfinite);
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent _evt)
		{
			base.OnBeforeHit(_evt);
			_ = _evt.from;
			MonsterAdventureActor monsterAdventureActor = _evt.to as MonsterAdventureActor;
			if (!(monsterAdventureActor != null) || !CommonUtils.CheckHitByTag(_evt.hitDamageTag, electroBallDamageTag))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500408, out var perkLevel) && CommonUtils.CheckHitByTag(_evt.hitDamageTag, electroBallDamageTag))
			{
				int buffNum = monsterAdventureActor.buffComponent.GetBuffNum(40811, 0);
				if (buffNum > 0)
				{
					AdventureActor.AddFromAttr(additionalAttrIdDic_8[perkLevel], base._actor, buffNum);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500415, out var _))
			{
				AdventureActor.AddFromAttr(20, base._actor);
			}
		}

		protected override void OnCrit(AdventureActorReceiveCritDamageEvent _evt)
		{
			base.OnCrit(_evt);
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500413, out var _) && ElectroBallCount >= 3 && CheckPerkCDTimeout(500413, cd_13))
			{
				LogicEntity logicEntity = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, searchRadius_13);
				if (logicEntity != null)
				{
					TSVector2 position = _electroBallEntity.FinishElectroBall();
					AdventureActor actor = base._actor;
					LogicEntity target = logicEntity;
					ILRuntimeAPI.Shoot("Misc/FateCard/Theme_ElectroBall_13", actor, default(FP), position, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
					TriggerPerk(500413);
				}
			}
		}

		protected override void OnHitPost(AdventureActorReceiveDamageEvent _evt)
		{
			base.OnHitPost(_evt);
			AdventureActor adventureActor = _evt.to as AdventureActor;
			if (!CommonUtils.CheckHitByTag(_evt.hitDamageTag, electroBallDamageTag))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500408, out var _))
			{
				adventureActor.buffComponent?.AddBuff(40811, base._actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500409, out var perkLevel2) && TSRandom.Range(0f, 100f) <= trigger_Percentage9)
			{
				adventureActor.buffComponent?.AddBuff(buffIdDic_9[perkLevel2], base._actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500410, out var perkLevel3) && CheckPerkCDTimeout(500410, cd_10) && (CommonUtils.CheckElementMark(CommonDefine.Light, adventureActor) || TSRandom.Range(0f, 100f) <= trigger_Percentage10))
			{
				base._actor.buffComponent.AddBuff(buffIdDic_10[perkLevel3], base._actor);
				TriggerPerk(500410);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500412, out var perkLevel4))
			{
				_perkTriggerTime_12++;
				if (_perkTriggerTime_12 >= triggerTimeDic_12[perkLevel4])
				{
					AdventureActor actor = base._actor;
					TSVector2 position = base._actor.tsTransform.Position;
					ILRuntimeAPI.Shoot("Misc/FateCard/Theme_ElectroBall_12", actor, default(FP), default(TSVector2), default(FP), position, null, AimType.Position, BulletDirectionType.BulletToTarget);
					_perkTriggerTime_12 = 0;
				}
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_electroBallEntity?.Finish();
			_electroBallEntity = null;
			if (_perkCor_11 != null)
			{
				StopLogicCoroutine(_perkCor_11);
			}
			_perkCor_11 = null;
			_perkTriggerTime_12 = 0;
			if (_perkCor_14 != null)
			{
				StopLogicCoroutine(_perkCor_14);
			}
			_perkCor_14 = null;
		}
	}
