		private void Shoot(string bullut, LogicEntity target, int hitDamageId)
		{
			target = ((target != null) ? target : CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius));
			if (!(target == null))
			{
				int hashCode = 0;
				if (GetPerkLv(500614, out var lv) && TSVector2.Distance(base._actor.tsTransform.Position, target.tsTransform.Position) < dicRange_14[lv] && CheckPerkCD(500614, cd_14))
				{
					bullut = bullut_14;
					hashCode = bullutTag_14;
				}
				CommonUtils.PlayOneOffFx(base._actor, "FX/Perk/fx_perk_base_fire_trigger_s");
				string bulletAlias = bullut;
				AdventureActor actor = base._actor;
				FP heightCenter = base._actor.dtCollider.HeightCenter;
				LogicEntity target2 = target;
				bullutObj = ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), default(TSVector2), heightCenter, default(TSVector2), target2, AimType.Target, BulletDirectionType.BulletToTarget);
				bullutObj.hitBox.hitDamageId = hitDamageId;
				bullutObj.ModifyBulletTag(hashCode);
				RefreshShootRC();
			}
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent evt)
		{
