			if (evt.hitDamageTag == null)
			{
				return;
			}
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (!CommonUtils.CheckHitByTag(evt.hitDamageTag, fireTag))
			{
				return;
			}
			if (GetPerkLv(500608, out var lv) && CheckPerkCD(500608, cd_8))
			{
				monsterAdventureActor.buffComponent.AddBuff(dicBuff_8[lv], base._actor);
			}
			if (GetPerkLv(500609, out lv) && CheckPerkCD(500609, cd_9))
			{
				base._actor.buffComponent.AddBuff(dicBuff_9[lv], base._actor);
			}
			if (GetPerkLv(500612, out lv) && TSRandom.Range(0, 100) <= dicProb_12[lv] && CheckPerkCD(500612, cd_12) && monsterAdventureActor != null)
			{
				List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(monsterAdventureActor, radius_12, isConfront: false, includeSelf: false);
				int num = Mathf.Min(list.Count, dicCount_12[lv]);
				for (int i = 0; i < num; i++)
				{
					LogicEntity logicEntity = list[i];
					TSVector2 normalized = (logicEntity.tsTransform.Position - monsterAdventureActor.tsTransform.Position).normalized;
					TSVector2 position = monsterAdventureActor.tsTransform.Position + normalized * TSMath.Max(monsterAdventureActor.dtCollider.Radius + 0.5, AdventureModuleController.Config.dtRadius);
					string bulletAlias = hitBullut_12;
					AdventureActor actor = base._actor;
					LogicEntity target = logicEntity;
					ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), position, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
					RefreshShootRC();
				}
			}
			if (GetPerkLv(500613, out lv) && monsterAdventureActor != null)
			{
				int num2 = ((monsterAdventureActor != null && monsterAdventureActor.CheckTag(hitTag)) ? (dicPro_13[lv] + basePro_13) : dicPro_13[lv]);
				if (TSRandom.Range(0, 100) < num2 && CheckPerkCD(500613, dicCd_13[lv]))
				{
					CoroutineNode item = StartLogicCoroutine(DelayHit(monsterAdventureActor, areaEffect_13, dicDmg_13));
					corList.Add(item);
				}
			}
		}

		protected override void OnMonsterKilled(AdventureActorReceiveDamageEvent evt)
		{
			if (GetPerkLv(500611, out var lv) && CheckPerkCD(500611, dicCd_11[lv]))
			{
				FP fP = TSMath.Floor(360f / (float)dicCount_11[lv]);
				for (int i = 0; i < dicCount_11[lv]; i++)
				{
					Vector3 vector = Quaternion.AngleAxis((fP * i).AsFloat(), Vector3.up) * base._actor.transform.forward;
					TSVector2 tSVector = new TSVector2(vector.x, vector.z);
					TSVector2 tSVector2 = base._actor.tsTransform.Position + tSVector.normalized * 10;
					string bulletAlias = fireBullut_11;
					AdventureActor actor = base._actor;
					FP heightCenter = base._actor.dtCollider.HeightCenter;
					TSVector2 targetPosition = tSVector2;
					ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), default(TSVector2), heightCenter, targetPosition, null, AimType.Position, BulletDirectionType.BulletToTarget);
					RefreshShootRC();
				}
			}
		}

		private IEnumerator DelayHit(AdventureActor to, string areaEffect, int damageId = 0)
		{
			if (to != null)
			{
				AreaEffect_AttackComponent areaEffect_AttackComponent = ILRuntimeAPI.GetAreaEffect(ILRuntimeAPI.PlayAreaEffect(base._actor, areaEffect, to.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null))?.GetLogicComponent<AreaEffect_AttackComponent>();
				if (areaEffect_AttackComponent != null && damageId != 0)
				{
					areaEffect_AttackComponent.hitDamageId = damageId;
				}
			}
			yield return null;
		}

		private void RefreshShootRC()
		{
			if (GetPerkLv(perkId_0, out var _) && !isInStrongState)
			{
				AddKey(tagCastCount);
				if (GetKeyCount(tagCastCount) >= maxShootRC && CheckPerkCDTimeout(perkId_0, cd_strong))
				{
					TriggerPerk(perkId_0);
					ClearKey(tagCastCount);
					EnterStrongState();
				}
			}
		}

		private void EnterStrongState()
		{
			base._actor.buffComponent.AddBuff(buff_Strong, base._actor);
		}

		private IEnumerator IntervalShoot()
		{
			while (true)
			{
				if (isInStrongState)
				{
					List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(base._actor, radius_strong, isConfront: true, includeSelf: false);
					for (int i = 0; i < list.Count; i++)
					{
						LogicEntity logicEntity = list[i];
						string bulletAlias = fireBullut;
						AdventureActor actor = base._actor;
						LogicEntity target = logicEntity;
						ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), base._actor.tsTransform.Position, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget).hitBox.hitDamageId = damageId_0;
					}
				}
				yield return base._actor.StartLogicCoroutine(base._actor.WaitForSeconds(interval));
			}
		}
	}
