		protected override void OnHitPre(AdventureActorReceiveDamageBeforeSettlementEvent _evt)
		{
			base.OnHitPre(_evt);
			if (_evt.from != base._actor)
			{
				return;
			}
			for (int i = 0; i < _evt.hitDamageTag.Count; i++)
			{
				if (!object.Equals(_evt.hitDamageTag[i], fireWaveDamageTag))
				{
					continue;
				}
				long num = ((_evt.weapon != null) ? _evt.weapon.Id : 0);
				if (num > 0)
				{
					if (_bulletHitCountDic == null)
					{
						_bulletHitCountDic = new Dictionary<long, int>(10);
					}
					if (_bulletHitCountDic.ContainsKey(num))
					{
						_bulletHitCountDic[num]++;
					}
					else
					{
						_bulletHitCountDic.Add(num, 1);
					}
				}
				AdventureActor target = _evt.to as AdventureActor;
				if (ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500208, out var perkLevel) && num > 0 && CheckPerkCDTimeout(500208, cd_8) && _bulletHitCountDic[num] == 3)
				{
					base._actor.buffComponent.AddBuff(buffIdDic_8[perkLevel], base._actor);
					TriggerPerk(500208);
				}
				if (!ModuleController<AdventureModuleController>.Instance.GetThemePerkLevel(500214, out var level_14) || (!CommonUtils.CheckElementMark(CommonDefine.Fire, target) && TSRandom.Range(0, 100) >= dicTriggerPercent_14[level_14]) || !CheckPerkCD(500214, dicCD_14[level_14]))
				{
					break;
				}
				ILRuntimeAPI.SearchByRangeAndPosition(base._actor, target.tsTransform.Position, range_14, delegate(List<LogicEntity> result)
				{
					if (result.Count > 0)
					{
						for (int num2 = result.Count - 1; num2 > -1; num2--)
						{
							if (result[num2].Id == target.Id)
							{
								result.RemoveAt(num2);
								break;
							}
						}
					}
					if (result.Count > 0)
					{
						int num3 = dicNum_14[level_14];
						num3 = ((num3 >= result.Count) ? result.Count : num3);
						for (int j = 0; j < num3; j++)
						{
							MonsterAdventureActor monsterAdventureActor = result[j] as MonsterAdventureActor;
							if (monsterAdventureActor != null)
							{
								TSVector2 normalized = (monsterAdventureActor.tsTransform.Position - target.tsTransform.Position).normalized;
								base._actor.shootBehaviour.Shoot(getFireBulletPrefab("Misc/FateCard/Theme_fireWave_14"), (TSVector2?)target.tsTransform.Position, (FP?)null, (TSVector2?)normalized, (TSVector2?)null, (LogicEntity)null, false, default(FP), AimType.Default, (Action<LogicEntity>)null).ResetHitID(500214);
