		private void CheckPlayIceElf(int perkId, int perkIndex, int prob, FP cd, int hitDamageId)
		{
			if (!GetPerkLv(perkId, out var _) || !CheckPerkCDTimeout(perkId, cd) || TSRandom.Range(0, 100) > prob)
			{
				return;
			}
			TriggerPerk(perkId);
			LogicEntity logicEntity = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, searchTargetRadius);
			if (!(logicEntity != null))
			{
				return;
			}
			TSVector2 position = base._actor.tsTransform.Position;
			randomIceElf();
			if (_tmpIceElf != string.Empty)
			{
				string tmpIceElf = _tmpIceElf;
				AdventureActor actor = base._actor;
				LogicEntity target = logicEntity;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(tmpIceElf, actor, default(FP), position, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				if (adventureBulletBase != null)
				{
					_tmpIceElf = string.Empty;
					adventureBulletBase.hitDamageId = hitDamageId;
					adventureBulletBase.hitBox.hitDamageId = hitDamageId;
				}
			}
			if (!checkHaveIceArea())
			{
				_iceAreaLevel = 1;
				PalyAreaEffect(1);
			}
			_shootIceElfCount++;
			ShootIceElfCount();
			playPrek_11();
			playPrek_8(hitDamageId);
			playPrek_9(perkId);
		}

		private void ShootIceElfCount()
		{
			if (_shootIceElfCount >= iceElfCount)
			{
				if (_iceAreaLevel < 3)
				{
					_iceAreaLevel++;
					PalyAreaEffect(_iceAreaLevel);
				}
				else if (_corReduceArea != null)
				{
					base._actor.StopLogicCoroutine(_corReduceArea);
					_corReduceArea = null;
					_corReduceArea = base._actor.StartLogicCoroutine(CorReduceArea());
				}
				_shootIceElfCount = 0;
			}
		}

		private void playPrek_8(int hitDamageId)
		{
			if (GetPerkLv(perkId_8, out var lv) && TSRandom.Range(0, 100) <= dicProb_8[lv])
			{
				CoroutineNode item = base._actor.StartLogicCoroutine(CorPlayPrek_8(hitDamageId));
				_corPlayPrek8List.Add(item);
			}
		}

		private IEnumerator CorPlayPrek_8(int hitDamageId)
		{
			yield return base._actor.StartLogicCoroutine(base._actor.WaitForSeconds(delay_8));
			LogicEntity logicEntity = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, searchTargetRadius);
			if (!(logicEntity != null))
			{
				yield break;
			}
			TSVector2 position = base._actor.tsTransform.Position;
			randomIceElf();
			if (_tmpIceElf != string.Empty)
			{
				string tmpIceElf = _tmpIceElf;
				AdventureActor actor = base._actor;
				LogicEntity target = logicEntity;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(tmpIceElf, actor, default(FP), position, default(FP), default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				if (adventureBulletBase != null)
				{
					_tmpIceElf = string.Empty;
					adventureBulletBase.hitDamageId = hitDamageId;
					adventureBulletBase.hitBox.hitDamageId = hitDamageId;
				}
			}
			_shootIceElfCount++;
			ShootIceElfCount();
			playPrek_11();
		}

		private void playPrek_9(int perkId)
		{
			if (GetPerkLv(perkId_9, out var lv))
			{
				List<LogicEntity> currentAreaEnemy = getCurrentAreaEnemy();
				if (currentAreaEnemy != null && currentAreaEnemy.Count >= dicEnemyCount_9[lv])
				{
					FP reduceCd = dicCoolTime_9[lv];
					ModifyPerkCD(perkId, reduceCd);
				}
			}
		}

		private void playPrek_11()
		{
			if (!GetPerkLv(perkId_11, out var lv))
			{
				return;
			}
			_shootIceElfCount_11++;
			if (_shootIceElfCount_11 < dicElfCount_11[lv])
			{
				return;
			}
			if (checkHaveIceArea())
			{
				List<LogicEntity> currentAreaEnemy = getCurrentAreaEnemy();
				if (currentAreaEnemy != null)
				{
					for (int i = 0; i < currentAreaEnemy.Count; i++)
					{
						AdventureActor adventureActor = currentAreaEnemy[i] as AdventureActor;
						ILRuntimeAPI.HitActor(base._actor, adventureActor, hitDamageId_11, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
						adventureActor.buffComponent.AddBuff(dicbuff_11[lv], base._actor);
					}
				}
				string fxAlias = dicHitFx_11[_iceAreaLevel];
				new PlayFX().Play(base._actor, fxAlias, 1f, base._actor.transform.position, Quaternion.identity);
			}
			_shootIceElfCount_11 = 0;
		}

		private void clearAreaMsg()
		{
			if (_corReduceArea != null)
			{
				base._actor.StopLogicCoroutine(_corReduceArea);
				_corReduceArea = null;
			}
			if (_fx_PrekBuff_15 != 0)
			{
				base._actor.buffComponent.RemoveBuffByBuffId(_fx_PrekBuff_15);
				_fx_PrekBuff_15 = 0;
			}
			if (_corCheckAreaPrek_16 != null)
			{
				base._actor.StopLogicCoroutine(_corCheckAreaPrek_16);
				_corCheckAreaPrek_16 = null;
			}
			_currentAreaId = 0L;
			_iceAreaLevel = 0;
			_shootIceElfCount = 0;
		}

		private bool checkHaveIceArea()
		{
			if (_currentAreaId == 0L)
			{
				return false;
			}
			if (ILRuntimeAPI.GetAreaEffect(_currentAreaId) != null)
			{
				return true;
			}
			clearAreaMsg();
			return false;
		}

		private List<LogicEntity> getCurrentAreaEnemy()
		{
			if (_currentAreaId == 0L)
			{
				return null;
			}
			AreaEffectEntity areaEffect = ILRuntimeAPI.GetAreaEffect(_currentAreaId);
			if (areaEffect == null)
			{
				clearAreaMsg();
				return null;
			}
			return CommonUtils.SearchNearTargetsByCircle(base._actor, areaEffect.hitBoxRadius, isConfront: true, includeSelf: false);
		}

		private AreaEffectEntity getCurrentArea()
		{
			if (_currentAreaId == 0L)
			{
				return null;
			}
			AreaEffectEntity areaEffect = ILRuntimeAPI.GetAreaEffect(_currentAreaId);
			if (areaEffect == null)
			{
				clearAreaMsg();
				return null;
			}
			return areaEffect;
		}

		private void PalyAreaEffect(int _lv)
		{
			string text = iceArea_Com[_lv];
			if (GetPerkLv(taskPerkId_2, out var _))
			{
				text = iceArea_Special[_lv];
			}
			TSVector2 position = base._actor.tsTransform.Position;
			FP angle = base._actor.tsTransform.Forward.GetAngle();
			ILRuntimeAPI.PlayAreaEffect(base._actor, text, position, angle, (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
			{
				_currentAreaId = entity.Id;
				if (_corReduceArea == null)
				{
					_corReduceArea = base._actor.StartLogicCoroutine(CorReduceArea());
				}
				else
				{
					base._actor.StopLogicCoroutine(_corReduceArea);
					_corReduceArea = null;
					_corReduceArea = base._actor.StartLogicCoroutine(CorReduceArea());
				}
				if (GetPerkLv(perkId_15, out var _))
				{
					_fx_PrekBuff_15 = dicFXBuff_15[_iceAreaLevel];
