				FP val2 = iFP.op_Implicit(base._actor.actorInfo.atk * (FP)((float)DicAtkPercentForDamageLimit_10[lv] / 100f));
				val = TSMath.Min(val, val2);
				((AdventureActor)monsterAdventureActor).DirectDamage((int)(long)val, attackTag_10, base._actor.Id, true, (GameObject)null, (GameObject)null, true, true);
			}
