		protected int GetLightingGhostCountByType(LightingGhostEntity.LightingGhostType type)
		{
			if (_lightingGhostDic == null)
			{
				return 0;
			}
			int num = 0;
			foreach (LightingGhostEntity value in _lightingGhostDic.Values)
