		private void CheckShoot(int perkId, int prob, FP cd, int dmgId)
		{
			if (GetPerkLv(perkId, out var _) && CheckPerkCDTimeout(perkId, cd) && TSRandom.Range(0, 100) <= prob)
			{
				Shoot(sharkBullut, base._actor.attackTarget, dmgId);
				TriggerPerk(perkId);
			}
		}

		private void Shoot(string bullut, LogicEntity target, int hitDamageId)
		{
			target = ((target != null) ? target : CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius));
			if (!(target == null))
			{
				CommonUtils.PlayOneOffFx(base._actor, "");
				string bullut2 = GetBullut();
				AdventureActor actor = base._actor;
				FP heightCenter = base._actor.dtCollider.HeightCenter;
				LogicEntity target2 = target;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bullut2, actor, default(FP), default(TSVector2), heightCenter, default(TSVector2), target2, AimType.Target, BulletDirectionType.BulletToTarget);
				adventureBulletBase.hitBox.hitDamageId = hitDamageId;
				if (GetPerkLv(501418, out var _) && string.Equals(bullut2, bullut_18))
				{
					adventureBulletBase.hitBox.hitDamageId = hitDmgId_18;
				}
				FixBullutInfo(adventureBulletBase, adventureBulletBase.hitBox.hitDamageId);
				RefreshCount(bullut2);
				if (GetPerkLv(501408, out var lv2))
				{
					adventureBulletBase.velocitySpeed += dicAddSpd_8[lv2];
				}
			}
		}

		private string GetBullut()
		{
			if (GetPerkLv(501417, out var lv))
			{
				return bullut_17;
			}
			if (GetPerkLv(501418, out lv) && shootCount >= count_18)
			{
				shootCount = 0;
				return bullut_18;
			}
			return sharkBullut;
		}

		private void RefreshCount(string tempBullut)
		{
			if (GetPerkLv(501418, out var _) && string.Equals(tempBullut, sharkBullut))
			{
				shootCount++;
			}
		}

		protected override void OnNoDmgHit(AdventureActorNoDamageEvent evt)
		{
			base.OnNoDmgHit(evt);
			if (evt.weapon != null && evt.weapon.CheckBulletTag(bullutTag))
			{
				CoroutineNode item = StartLogicCoroutine(DelayHit(evt.to, evt.weapon.temphitDmgId), runImmediately: true);
				corList.Add(item);
			}
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent evt)
		{
			base.OnBeforeHit(evt);
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (!(monsterAdventureActor != null))
			{
				return;
			}
			bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark);
			bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_strong);
			if (!(num || flag))
			{
				return;
			}
			if (GetPerkLv(501408, out var lv))
			{
				AdventureActor.AddFromAttr(dicOnce_8[lv], base._actor);
			}
			if (GetPerkLv(501409, out lv) && monsterAdventureActor.actorHealthInfo.hpPercentage < dicHp_9[lv])
			{
				AdventureActor.AddFromAttr(dicOnce_9[lv], base._actor);
			}
			if (!GetPerkLv(501411, out lv))
			{
				return;
			}
			for (int i = 0; i < buffTag_12.Count; i++)
			{
				if (monsterAdventureActor.buffComponent.CheckBuffByBuffTag(buffTag_12[i]))
				{
					AdventureActor.SetFromForceCrit(val: true);
					AdventureActor.AddFromAttr(dicOnce_11[lv], base._actor);
					break;
				}
			}
		}

		protected override void OnBeforeHurt(AdventureActorReceiveDamageBeforeHitEvent evt)
		{
			base.OnBeforeHurt(evt);
			if (evt.to as PlayerAdventureActor != null && CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_small) && GetPerkLv(501414, out var lv))
			{
				base._actor.buffComponent.AddBuff(dicBuff_14[lv], base._actor);
			}
		}

		protected override void OnHitPre(AdventureActorReceiveDamageBeforeSettlementEvent evt)
		{
			base.OnHitPre(evt);
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (!(monsterAdventureActor != null))
			{
				return;
			}
			bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark);
			bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_strong);
			if (!(num || flag))
			{
				return;
			}
			if (GetPerkLv(501410, out var lv))
			{
				monsterAdventureActor.buffComponent.AddBuff(dicBuff_10[lv], base._actor);
			}
			if (GetPerkLv(501413, out lv) && (CommonUtils.CheckElementMark(CommonDefine.Water, monsterAdventureActor) || TSRandom.Range(0, 100) < dicPro_13[lv]) && CheckPerkCD(501413, cd_13))
			{
				TSVector2 tSVector = CommonUtils.RandomReachablePointInsideRing(base._actor, base._actor.tsTransform.Position, circleInner_13, circleOuter_13);
				playFX_perk13.Play(base._actor, null, summonEffect_13, base._actor.tsTransform.PositionY, tSVector, base._actor.tsTransform.Forward);
				CoroutineNode item = StartLogicCoroutine(IntervalShoot(monsterAdventureActor, tSVector, dicCount_13[lv]));
				corList.Add(item);
			}
			if (GetPerkLv(501417, out lv))
			{
				if (monsterAdventureActor.IsBossMonster())
				{
					AdventureActor.AddFromAttr(dicOnce_17[lv], base._actor);
				}
				else if (monsterAdventureActor.actorHealthInfo.hpPercentage < dicHp_17[lv])
				{
					monsterAdventureActor.Kill(base._actor);
				}
			}
			if (GetPerkLv(501418, out lv) && flag)
			{
				monsterAdventureActor.buffComponent.AddBuff(dicBuff_18[lv], base._actor);
			}
		}

		protected override void OnHitPost(AdventureActorReceiveDamageEvent evt)
		{
			base.OnHitPost(evt);
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (!(monsterAdventureActor != null))
			{
				return;
			}
			bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark);
			bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_strong);
			if (num || flag)
			{
				if (GetPerkLv(501412, out var lv) && evt.isKill && CheckPerkCD(501412, cd_12))
				{
					string areaEffect = (flag ? aoe_12_high : aoe_12_base);
					CoroutineNode item = StartLogicCoroutine(DelayHit(monsterAdventureActor, areaEffect));
					corList.Add(item);
				}
				if (GetPerkLv(501414, out lv) && CheckPerkCD(501414, cd_14))
				{
					string bulletAlias = bullut_14;
					TSVector2 position = monsterAdventureActor.tsTransform.Position;
					FP heightCenter = base._actor.dtCollider.HeightCenter;
					LogicEntity actor = base._actor;
					ILRuntimeAPI.Shoot(bulletAlias, monsterAdventureActor, default(FP), position, heightCenter, default(TSVector2), actor, AimType.Target, BulletDirectionType.BulletToTarget).hitBox.hitDamageId = hitDmgId_14;
				}
			}
		}

		protected override void OnHurt(AdventureActorReceiveDamageEvent evt)
		{
			base.OnHurt(evt);
			bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark);
			bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_strong);
			if ((num || flag) && GetPerkLv(501414, out var lv))
			{
				base._actor.buffComponent.AddBuff(dicBuff_14[lv], base._actor);
			}
		}

		private void OnDropFinish(IEvent evt)
		{
			AdventureDropFinishEvent obj = evt as AdventureDropFinishEvent;
			long entityID = obj.entityID;
			if (obj.isPickUp && GetPerkLv(501416, out var _) && dropHash_16.Contains(entityID))
			{
				LogicEntity logicEntity = ((base._actor.attackTarget != null) ? base._actor.attackTarget : CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius));
				if (logicEntity != null)
				{
					string bullut = GetBullut();
					AdventureActor actor = base._actor;
					TSVector2 position = logicEntity.tsTransform.Position;
					ILRuntimeAPI.Shoot(bullut, actor, default(FP), default(TSVector2), default(FP), position, null, AimType.Position, BulletDirectionType.BulletToTarget).hitBox.hitDamageId = hitDmgId_16;
					RefreshCount(bullut);
				}
				dropHash_16.Remove(entityID);
			}
		}

		private IEnumerator DelayHit(AdventureActor to, string areaEffect, int damageId = 0)
		{
			ILRuntimeAPI.PlayAreaEffect(base._actor, areaEffect, to.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return null;
		}

		private IEnumerator IntervalMark()
		{
			_ = dicInterval_15[perk15Lv];
			FP curTime = 0;
			while (true)
			{
				if (curMarkedMonster == null || curMarkedMonster.IsDead())
				{
					curMarkedMonster = null;
					List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(base._actor, circleRadius, isConfront: true, includeSelf: false);
					if (list.Count > 0)
					{
						IOrderedEnumerable<LogicEntity> source = list.OrderBy((LogicEntity logicEntity) => (logicEntity as AdventureActor).actorHealthInfo.hp);
						curMarkedMonster = source.First();
						(curMarkedMonster as AdventureActor).buffComponent.AddBuff(dicBuff_15[perk15Lv], base._actor);
					}
				}
				else if (curTime < 0 && curMarkedMonster != null)
				{
					TSVector2 tSVector = CommonUtils.RandomReachablePointInsideRing(base._actor, curMarkedMonster.tsTransform.Position, circleInner_15, circleOuter_15);
					playFX_perk15.Play(base._actor, null, summonEffect_15, curMarkedMonster.tsTransform.PositionY, tSVector, base._actor.tsTransform.Forward);
					CoroutineNode item = StartLogicCoroutine(DelayShoot(curMarkedMonster, tSVector, hitDmgId_15, 0.5f), runImmediately: true);
					corList.Add(item);
					curTime = dicInterval_15[perk15Lv];
				}
				curTime -= base.LogicDeltaTime;
				yield return null;
			}
		}

		private IEnumerator IntervalDrop()
		{
			int rawTime = dicInterval_16[perk16Lv];
			FP curTime = 0;
			while (true)
			{
				if (curTime < 0)
				{
					long num = ILRuntimeAPI.PlayDrop(base._actor, drop_16);
					if (num > 0)
					{
						dropHash_16.Add(num);
					}
					curTime = rawTime;
				}
				curTime -= base.LogicDeltaTime;
				yield return null;
			}
		}

		private IEnumerator IntervalShoot(LogicEntity target, TSVector2 startPos, int count)
		{
			yield return 0.5f;
			int i = 0;
			while (i < count && !target.IsDead())
			{
				string bullut = GetBullut();
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bullut, base._actor, default(FP), startPos, base._actor.dtCollider.HeightCenter, target.tsTransform.Position, null, AimType.Position, BulletDirectionType.BulletToTarget);
				adventureBulletBase.hitBox.hitDamageId = hitDmgId_13;
				if (GetPerkLv(501418, out var lv))
				{
					adventureBulletBase.hitBox.hitDamageId = hitDmgId_18;
				}
				FixBullutInfo(adventureBulletBase, adventureBulletBase.hitBox.hitDamageId);
				RefreshCount(bullut);
				yield return interval_13;
				lv = i++;
			}
			playFX_perk13.Stop();
		}

		private IEnumerator DelayShoot(LogicEntity to, TSVector2 shootPos, int hitDmgId, FP delayTime)
		{
			yield return delayTime;
			string bullut = GetBullut();
			AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bullut, base._actor, default(FP), shootPos, base._actor.dtCollider.HeightCenter, to.tsTransform.Position, null, AimType.Position, BulletDirectionType.BulletToTarget);
			adventureBulletBase.hitBox.hitDamageId = hitDmgId;
			if (GetPerkLv(501418, out var _))
			{
				adventureBulletBase.hitBox.hitDamageId = hitDmgId_18;
			}
			FixBullutInfo(adventureBulletBase, adventureBulletBase.hitBox.hitDamageId);
			RefreshCount(bullut);
			playFX_perk15.Stop();
		}

		private IEnumerator DelayHit(LogicEntity to, int hitDmgId)
		{
			yield return baseDelayTime;
			ILRuntimeAPI.HitActor(base._actor, to as AdventureActor, hitDmgId, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
		}

		private void FixBullutInfo(AdventureBulletBase bullCom, int finalHitDmgId)
		{
			bullCom.temphitDmgId = finalHitDmgId;
			bullCom.hitBox.hitDamageId = -3;
			bullCom.ModifyBulletTag(bullutTag);
		}
	}
