		private IEnumerator CheckLogic_Task1(FP duration)
		{
			FP leftTime = duration;
			base._actor.buffComponent.AddBuff(81611, base._actor);
			FP triggerInterval = TSRandom.Range(minTriggerTime_Task_1, maxTriggerTime_Task_1);
			while (leftTime > 0)
			{
				triggerInterval -= LockStepManager.deltaTime;
				if (triggerInterval < 0)
				{
					int index = TSRandom.Range(0, scatteringDartsPathList_Task_1.Count);
					if (_scatteringDartsPrefabDic == null)
					{
						_scatteringDartsPrefabDic = new Dictionary<string, GameObject>(10);
					}
					if (!_scatteringDartsPrefabDic.ContainsKey(scatteringDartsPathList_Task_1[index]))
					{
						string assetName = "Assets/AssetBundles/" + scatteringDartsPathList_Task_1[index] + ".prefab";
						GameObject value = GameResourceLoader.LoadAsset(GameResourceLoader.ResourceType.Any, assetName, typeof(GameObject)) as GameObject;
						_scatteringDartsPrefabDic.Add(scatteringDartsPathList_Task_1[index], value);
					}
					GameObject gameObject = _scatteringDartsPrefabDic[scatteringDartsPathList_Task_1[index]];
					if (gameObject != null)
					{
						SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(base._actor, gameObject, base._actor.transform.position, Quaternion.identity);
					}
					triggerInterval = TSRandom.Range(minTriggerTime_Task_1, maxTriggerTime_Task_1);
				}
				leftTime -= LockStepManager.deltaTime;
				yield return null;
			}
			base._actor.buffComponent.RemoveBuffByBuffId(81611);
		}

