	public enum fsmStatus
	{
		Enter,
		Exit
	}
	public class IState
	{
		private fsmStatus fsmStatus;

		public LogicEntity entity;

		public PrologueMgr prologueMgr;

		private List<CoroutineNode> corList = new List<CoroutineNode>();

		private Dictionary<WorldOBB, Action<WorldOBB>> dicObb = new Dictionary<WorldOBB, Action<WorldOBB>>();

		private List<WorldOBB> obbs = new List<WorldOBB>();

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public SimpleMonsterAdventrueActor monsterActor => PrologueMgr.Ins.monsterActor;

		public SimplePlayerAdventureActor playerActor => PrologueMgr.Ins.playerActor;

		public IState(LogicEntity entity, PrologueMgr prologueMgr)
		{
			this.entity = entity;
			this.prologueMgr = prologueMgr;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
			for (int i = 0; i < obbs.Count; i++)
			{
				obbs[i].OnUpdate(playerActor.transform.position);
			}
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
			foreach (KeyValuePair<WorldOBB, Action<WorldOBB>> item in dicObb)
			{
				item.Key.RemoveListener(item.Value);
			}
			obbs.Clear();
			dicObb.Clear();
		}

		protected void StartCor(ref CoroutineNode cor, IEnumerator enumerator)
		{
			if (cor != null)
			{
				entity.StopLogicCoroutine(cor);
			}
			cor = entity.StartLogicCoroutine(enumerator);
		}

		protected void StopCor(ref CoroutineNode cor)
		{
			if (cor != null)
			{
				entity.StopLogicCoroutine(cor);
			}
			cor = null;
		}

		public void MaskFadeOut(float duration = 0.3f)
		{
			ProloguelevelMgr.Instance.MaskFadeOut(duration);
		}

		public void MaskFadeIn(float duration = 0.3f)
		{
			ProloguelevelMgr.Instance.MaskFadeIn(duration);
		}

		public void Register(WorldOBB worldOBB, Action<WorldOBB> cb)
		{
			obbs.Add(worldOBB);
			dicObb.Add(worldOBB, cb);
			worldOBB.AddListener(cb);
		}

		public void Register(List<WorldOBB> worldOBBs, Action<WorldOBB> cb)
		{
			for (int i = 0; i < worldOBBs.Count; i++)
			{
				Register(worldOBBs[i], cb);
			}
		}
	}
	public class EnterState : IState
	{
		private bool isPlaying;

		private CoroutineNode corMain;

		public EnterState(LogicEntity _entity, PrologueMgr prologueMgr)
			: base(_entity, prologueMgr)
		{
		}

		public override void Enter()
		{
			base.Enter();
			MonoSingleton<LuaManager>.Instance.FireEvent("Prologue_EventUpload", "1");
			MonoSingleton<LuaManager>.Instance.FireEvent("MainBattleMenuBtnPauseActive", a1: false);
			base.playerActor.SwithAnimationGroup();
			base.playerActor.SwithToUnBattle(0.1f);
			MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_setState");
			MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_inCS");
			ProloguelevelMgr.Instance.SetMaskObjectActive(true);
			ProloguelevelMgr.Instance.SetMaskObjectAlpha(1f);
			MonoSingleton<ProVideoManager>.Instance.PlayVideo(PrologueConfig.videoUrl_start, (Action<bool>)delegate
			{
				isPlaying = true;
				MaskFadeOut(PrologueConfig.fadeInTime);
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_explore_setState");
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_outCS");
			}, true, PrologueConfig.fadeInTime, true, PrologueConfig.fadeOutTime, PrologueConfig.videoUrl_start_skip, true, (System.Action)delegate
			{
				ProloguelevelMgr.Instance.SetMaskObjectActive(false);
			});
			StartCor(ref corMain, DoMainLogic());
		}

		private IEnumerator DoMainLogic()
		{
			CommonHelper.EnableSkillInput(enable: false);
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			while (!isPlaying)
			{
				yield return null;
			}
			base.playerActor.buffComponent.AddBuff(PrologueConfig.buff, base.playerActor);
			base.playerActor.movAgent.canBlock = false;
			base.playerActor.EnableForbiddenRush();
			base.monsterActor.movAgent.canBlock = false;
			base.playerActor.PlayComboByKey(PrologueConfig.combo_phone, delegate
			{
				Debug.Log("==>播放完成");
			});
			yield return 0.5f;
			ProloguelevelMgr.Instance.SetVCamPriority(0);
			yield return PrologueConfig.camraTime;
			MonoSingleton<LuaManager>.Instance.FireEvent("FadeIn");
			yield return 1f;
			SceneSingleton<DeterministicCollisionManager>.Instance.UnRegisterCollider(base.playerActor.dtCollider, ignoreLock: true);
			SceneSingleton<DeterministicCollisionManager>.Instance.RegisterCollider(base.playerActor.dtCollider, ignoreLock: true);
			yield return 0.5f;
			SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Guide_Index", 6);
			MonoSingleton<LuaManager>.Instance.FireEvent("Prologue_EventUpload", "2");
			Exit();
		}

		public override void Exit()
		{
			base.Exit();
			StopCor(ref corMain);
			prologueMgr.ChangeState(PrologueMgr.Status.FirstPart);
		}
	}
	public class FirstPartState : IState
	{
		private CoroutineNode corMain;

		private CoroutineNode corNpcGuild;

		private CoroutineNode corTurnDown;

		private CoroutineNode corTurnBack;

		private CoroutineNode corEnd;

		private CoroutineNode corCheckPlayerPosition;

		private bool isInTurn;

		private bool stage2;

		private bool isSlideReady;

		private Vector3 orginalGravity;

		private const string AVG_BB_END = "AVG_BB_END";

		private bool isAvgEnd;

		private ActorState lastState;

		private bool isTrigger;

		public FirstPartState(LogicEntity _entity, PrologueMgr prologueMgr)
			: base(_entity, prologueMgr)
		{
		}

		public override void Enter()
		{
			base.Enter();
			lastState = ActorState.StandBy;
			isTrigger = false;
			orginalGravity = ProloguelevelMgr.Instance.GetGravity();
			Singleton<EventDispatchManager>.Instance.AddEventListener("AVG_BB_END", OnAvgEnd);
			Register(prologueMgr.edgeOBBs, OnForceTurn);
			Register(prologueMgr.endOBB_1, OnEnd);
			StartCor(ref corMain, DoMainLogic());
			StartCor(ref corCheckPlayerPosition, CheckPlayerMove());
		}

		private IEnumerator DoMainLogic()
		{
			stage2 = false;
			isSlideReady = false;
			base.playerActor.SetAnimMaxSpd(PrologueConfig.maxSpd_1);
			base.playerActor.SetSpeed(PrologueConfig.playSpeed_1);
			base.monsterActor.SetSpeed(PrologueConfig.npcSpeed_1);
			StartCor(enumerator: DoNpcGuild(new TSVector2(prologueMgr.npcTargetPos.position.x, prologueMgr.npcTargetPos.position.z)), cor: ref corNpcGuild);
			yield return 1f;
			MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 1);
			while (!isAvgEnd)
			{
				yield return null;
			}
			if (!stage2)
			{
				stage2 = true;
				yield return 6f;
				base.playerActor.TriggerStage(2);
				base.playerActor.SetAnimMaxSpd(PrologueConfig.maxSpd_2);
				base.playerActor.HidePhone();
			}
		}

		private IEnumerator CheckPlayerMove()
		{
			bool isMoving = false;
			bool isFirstMove = false;
			FP countTime = 0;
			TSVector2 position = base.playerActor.tsTransform.Position;
			while (true)
			{
				if (!isFirstMove)
				{
					if (position != base.playerActor.tsTransform.Position)
					{
						isFirstMove = true;
						isMoving = true;
					}
					yield return null;
					continue;
				}
				if (isMoving)
				{
					countTime = 0;
					position = base.playerActor.tsTransform.Position;
					yield return null;
					if (position == base.playerActor.tsTransform.Position)
					{
						isMoving = false;
					}
					continue;
				}
				if (position != base.playerActor.tsTransform.Position)
				{
					isMoving = true;
				}
				countTime += (FP)0.03;
				if (countTime >= 10)
				{
					MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Guide_Index", 6);
					isTrigger = false;
					isFirstMove = false;
					countTime = 0;
				}
				yield return null;
			}
		}

		protected void OnAvgEnd(IEvent evt)
		{
			GeneralEvent generalEvent = (GeneralEvent)evt;
			if (generalEvent == null)
			{
				return;
			}
			string[] array = ((string)generalEvent.data).Split('|');
			if (array.Length != 0)
			{
				_ = array[0];
				string obj = array[1];
				if (obj == "1" && !isSlideReady)
				{
					MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 2);
				}
				if (obj == "2" && !isSlideReady)
				{
					MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 4);
					isAvgEnd = true;
				}
			}
		}

		private IEnumerator DoNpcGuild(TSVector2 targetPos)
		{
			isInTurn = false;
			while (true)
			{
				FP fP = TSMath.Abs(TSVector2.Dot(base.playerActor.tsTransform.Position - base.monsterActor.tsTransform.Position, new TSVector2(-0.8, 0.6)));
				if (fP < PrologueConfig.wait_move)
				{
					base.monsterActor.MoveTo(targetPos, 0.1);
				}
				else if (fP > PrologueConfig.wait_idle && !isSlideReady)
				{
					((AdventureActor)base.monsterActor).StandBy((System.Action)null);
				}
				if (fP > PrologueConfig.wait_turnback && !isInTurn && !isSlideReady)
				{
					isInTurn = true;
					StartCor(ref corTurnBack, DoTurnBack());
				}
				yield return null;
			}
		}

		private IEnumerator DoTurnBack()
		{
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			((AdventureActor)base.playerActor).StandBy((System.Action)null);
			TSVector2 dir = (base.playerActor.tsTransform.Position - base.monsterActor.tsTransform.Position).normalized;
			bool flage = false;
			base.playerActor.LookAtDir(dir, 0, delegate
			{
				flage = true;
			});
			while (!flage)
			{
				yield return null;
			}
			base.playerActor.PlayComboByKey(stage2 ? PrologueConfig.combo_turnBack : PrologueConfig.combo_turnBack0, delegate
			{
			});
			yield return PrologueConfig.time_1;
			base.playerActor.InterruptAttack(force: true, fadeOutAnim: false);
			TSVector2 targetPosition = base.playerActor.tsTransform.Position + -dir * PrologueConfig.moveDis_1;
			base.playerActor.MoveTo(targetPosition, 0.1, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
			{
				SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
				isInTurn = false;
			}, randomMove: false, forceMove: true);
		}

		private void OnForceTurn(WorldOBB worldOBB)
		{
			StartCor(ref corTurnDown, DoTurnDown(worldOBB));
		}

		private IEnumerator DoTurnDown(WorldOBB worldOBB)
		{
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			((AdventureActor)base.playerActor).StandBy((System.Action)null);
			TSVector2 dir = base.playerActor.tsTransform.Forward.normalized;
			base.playerActor.PlayComboByKey(stage2 ? PrologueConfig.combo_turnDown : PrologueConfig.combo_turnDown0, delegate
			{
			});
			yield return PrologueConfig.time_2;
			base.playerActor.InterruptAttack(force: true, fadeOutAnim: false);
			TSVector2 targetPosition = base.playerActor.tsTransform.Position + -dir * PrologueConfig.moveDis_2;
			base.playerActor.MoveTo(targetPosition, 0.1, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
			{
				SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			}, randomMove: false, forceMove: true);
		}

		private void OnEnd(WorldOBB worldOBB)
		{
			StartCor(ref corEnd, DoSlide(worldOBB));
		}

		private IEnumerator DoSlide(WorldOBB worldOBB)
		{
			isSlideReady = true;
			if (!stage2)
			{
				stage2 = true;
			}
			base.monsterActor.SetSpeed(PrologueConfig.npcSpeed_1_2);
			ProloguelevelMgr.Instance.SetGravity(new Vector3(0f, PrologueConfig.gravity, 0f));
			base.playerActor.SetSpeed(PrologueConfig.playSpeed_1_2);
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			((AdventureActor)base.playerActor).StandBy((System.Action)null);
			if (!isAvgEnd)
			{
				MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 3);
			}
			bool flage = false;
			TSVector2 targetPosition = new TSVector2(prologueMgr.preSlidePos.position.x, prologueMgr.preSlidePos.position.z);
			base.playerActor.MoveTo(targetPosition, 0.1, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
			{
				flage = true;
			});
			yield return 1f;
			StopCor(ref corNpcGuild);
			base.monsterActor.LookAtDir(PrologueConfig.slideDir, 0);
			yield return 1f;
			TSVector2 StartPos2 = new TSVector2(-33.65, -26.5);
			base.monsterActor.PlayComboByKey(PrologueConfig.combo_slope2, delegate
			{
				base.monsterActor.SyncMovementLocation(StartPos2, CommonHelper.GetTerrainHeight(StartPos2, 0), base.monsterActor.tsTransform.Rotation);
				Debug.Log("==>蝴蝶滑沙动作播放完成");
			});
			base.playerActor.TriggerStage(2);
			base.playerActor.SetAnimMaxSpd(PrologueConfig.maxSpd_2);
			while (!flage)
			{
				yield return null;
			}
			TSVector2 slideDir = PrologueConfig.slideDir;
			FP duration = TSVector2.Angle(slideDir, base.playerActor.tsTransform.Forward) / PrologueConfig.rotSpd_2;
			flage = false;
			base.playerActor.LookAtDir(slideDir, duration, delegate
			{
				flage = true;
			});
			while (!flage)
			{
				yield return null;
			}
			base.playerActor.PlayComboByKey(PrologueConfig.combo_slope, delegate
			{
				Debug.Log("==>播放完成");
			});
			base.playerActor.HidePhone();
			yield return PrologueConfig.slideTime - 4f;
			ProloguelevelMgr.Instance.SetGravity(orginalGravity);
			base.monsterActor.MoveTo(new TSVector2(-28.6, -1.25), 0.1, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
			{
				base.monsterActor.ShowSelf(flage: false);
				Singleton<InteractiveManager>.Instance.triggerOpListener("ActivePost");
			});
			yield return 4f;
			SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			Exit();
		}

		public override void Update()
		{
			base.Update();
			if (!isTrigger)
			{
				if (base.playerActor.movementState == ActorState.Move && lastState == ActorState.StandBy)
				{
					MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Prologue_Move");
					isTrigger = true;
				}
				lastState = base.playerActor.movementState;
			}
		}

		public override void Exit()
		{
			base.Exit();
			ProloguelevelMgr.Instance.SetGravity(orginalGravity);
			Singleton<EventDispatchManager>.Instance.RemoveEventListener("AVG_BB_END", OnAvgEnd);
			StopCor(ref corMain);
			StopCor(ref corTurnDown);
			StopCor(ref corTurnBack);
			StopCor(ref corNpcGuild);
			StopCor(ref corEnd);
			StopCor(ref corCheckPlayerPosition);
			prologueMgr.ChangeState(PrologueMgr.Status.SencondPart);
		}
	}
	public class SecondPartState : IState
	{
		private CoroutineNode corMain;

		private CoroutineNode corEnterBattle;

		private CoroutineNode corPlaySound;

		private bool isPlaying;

		private bool isBattle2End;

		public SecondPartState(LogicEntity _entity, PrologueMgr prologueMgr)
			: base(_entity, prologueMgr)
		{
		}

		public override void Enter()
		{
			base.Enter();
			Register(prologueMgr.runOBB, OnRun);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("INTERACTIVEID", OnNextState);
			StartCor(ref corMain, DoMainLogic());
		}

		private IEnumerator DoMainLogic()
		{
			while (!isPlaying)
			{
				yield return null;
			}
			new TSVector2(prologueMgr.battle2StartPoint.position.x, prologueMgr.battle2StartPoint.position.z);
			if (base.playerActor.visualControl != null && base.playerActor.visualControl.interactiveEnvPawn != null)
			{
				base.playerActor.visualControl.interactiveEnvPawn.Active();
			}
			SceneSingleton<AdventurePlayerController>.Instance.cameraBeacon = base.playerActor.transform;
			SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			yield return 1.5f;
			SceneSingleton<AdventurePlayerController>.Instance.showVisionAttackRange = true;
			SceneSingleton<AdventureIndicatorController>.Instance.StartHintAttackRangeGraphic();
			MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Guide_AttackRange");
			while (!isBattle2End)
			{
				yield return null;
			}
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			TSVector2 targetPos = new TSVector2(prologueMgr.climbStartPos.position.x, prologueMgr.climbStartPos.position.z);
			TSVector2 dir = targetPos - base.playerActor.tsTransform.Position;
			base.playerActor.LookAtDir(dir, 0);
			yield return null;
			base.playerActor.InterruptAttack(force: true);
			base.playerActor.PlayComboByKey(PrologueConfig.combo_unfire_look);
			base.playerActor.SwithToUnBattle(PrologueConfig.fadeTime);
			yield return PrologueConfig.time_DelayBorn;
			dir = (targetPos - base.playerActor.tsTransform.Position).normalized;
			TSVector2 tSVector = dir * PrologueConfig.dis_Born + base.playerActor.tsTransform.Position;
			base.monsterActor.tsTransform.Position = tSVector;
			base.monsterActor.tsTransform.PositionY = CommonHelper.GetTerrainHeight(tSVector, 0);
			base.monsterActor.tsTransform.Forward = dir;
			base.monsterActor.Teleport(tSVector);
			base.monsterActor.ShowSelf(flage: true);
			base.monsterActor.PlayComboByKey(PrologueConfig.combo_born, delegate
			{
			});
			yield return PrologueConfig.bornTime;
			SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			Exit();
		}

		private void OnRun(WorldOBB worldOBB)
		{
			base.playerActor.SetSpeed(PrologueConfig.playSpeed_2);
		}

		private void OnNextState(IEvent evt)
		{
			if (!(evt is AdventureInteractiveIDTrigger adventureInteractiveIDTrigger))
			{
				return;
			}
			if (adventureInteractiveIDTrigger.interactiveID.Equals("SeeSignPost"))
			{
				SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			}
			else if (adventureInteractiveIDTrigger.interactiveID.Equals("Skill_Open"))
			{
				List<string> btnList = new List<string> { "Fire2" };
				CommonHelper.EnableSkillInput(enable: true, btnList);
				MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Guide_Index", 22);
			}
			else if (adventureInteractiveIDTrigger.interactiveID.Equals("SeePostAnime"))
			{
				SceneSingleton<AdventureIndicatorController>.Instance.StartHintAttackRangeGraphic();
				base.playerActor.SwithToBattle(0.1f);
				SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
				if (base.playerActor.visualControl != null && base.playerActor.visualControl.interactiveEnvPawn != null)
				{
					base.playerActor.visualControl.interactiveEnvPawn.Deactive();
				}
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_inCS");
				MonoSingleton<LuaManager>.Instance.FireEvent("Prologue_EventUpload", "3");
				MonoSingleton<ProVideoManager>.Instance.PlayVideo(PrologueConfig.videoUrl_middle, (Action<bool>)delegate(bool isJump)
				{
					if (isJump)
					{
						StopCor(ref corEnterBattle);
						MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_skip_setState");
					}
					MonoSingleton<LuaManager>.Instance.FireEvent("Prologue_EventUpload", "4");
					MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_outCS");
					Singleton<InteractiveManager>.Instance.triggerOpListener("MonsterWave_2");
					isPlaying = true;
					MaskFadeOut(PrologueConfig.fadeInTime);
					MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_explore_setState");
				}, true, PrologueConfig.fadeInTime, true, PrologueConfig.fadeOutTime, PrologueConfig.videoUrl_middle_skip, true, (System.Action)null);
				StartCor(ref corPlaySound, DoPlaySound());
			}
			else if (adventureInteractiveIDTrigger.interactiveID.Equals(PrologueConfig.interactID_battle2End))
			{
				isBattle2End = true;
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_combatEnd_setState");
				SceneSingleton<AdventurePlayerController>.Instance.showVisionAttackRange = false;
			}
		}

		private IEnumerator DoPlaySound()
		{
			yield return PrologueConfig.video_triggerTime;
			MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologue_secondCombat_setState");
		}

		private void OnFireEnd()
		{
			SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
		}

		public override void Exit()
		{
			base.Exit();
			AdventureTargetBlob.onAttackRangeGraphicStateChange = null;
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("INTERACTIVEID", OnNextState);
			StopCor(ref corMain);
			StopCor(ref corPlaySound);
			StopCor(ref corEnterBattle);
			prologueMgr.ChangeState(PrologueMgr.Status.ThirdPart);
		}
	}
	public class ThirdPartState : IState
	{
		private CoroutineNode corNpcGuild;

		private CoroutineNode corTrun;

		private CoroutineNode corClimb;

		private bool isClimbing;

		public ThirdPartState(LogicEntity _entity, PrologueMgr prologueMgr)
			: base(_entity, prologueMgr)
		{
		}

		public override void Enter()
		{
			base.Enter();
			Register(prologueMgr.climbOBB, OnClimb);
			Register(prologueMgr.endOBB_3, OnEnd);
			Register(prologueMgr.sandstormOBB, OnSandStormStart);
			base.playerActor.SetSpeed(4.2);
			base.monsterActor.SetSpeed(4.2);
			StartCor(ref corNpcGuild, DoNpcGuild());
			MonoSingleton<LuaManager>.Instance.FireEvent("ProloguelEnableBtnControl", 2, a2: false);
		}

		private IEnumerator DoNpcGuild()
		{
			TSVector2 targetPos = new TSVector2(prologueMgr.climbStartPos.position.x, prologueMgr.climbStartPos.position.z);
			bool firstMoveEnd = false;
			while (true)
			{
				FP fP = TSMath.Abs(TSVector2.Dot(base.playerActor.tsTransform.Position - base.monsterActor.tsTransform.Position, new TSVector2(0.21, 0.98)));
				if (fP < PrologueConfig.wait_move_3)
				{
					base.monsterActor.MoveTo(targetPos, 0.1);
				}
				else if (fP > PrologueConfig.wait_idle_3)
				{
					((AdventureActor)base.monsterActor).StandBy((System.Action)null);
				}
				if (TSVector2.Distance(targetPos, base.monsterActor.tsTransform.Position) <= 0.3 && !firstMoveEnd)
				{
					((AdventureActor)base.monsterActor).StandBy((System.Action)null);
					targetPos = new TSVector2(prologueMgr.climbEndPos.position.x, prologueMgr.climbEndPos.position.z);
					firstMoveEnd = true;
				}
				yield return null;
			}
		}

		private void OnSandStormStart(WorldOBB worldOBB)
		{
			base.playerActor.TriggerStage(3);
			base.playerActor.SetAnimMaxSpd(PrologueConfig.maxSpd_3);
			base.playerActor.SetSpeed(PrologueConfig.playSpeed_3_move);
			base.monsterActor.SetSpeed(PrologueConfig.npcSpeed_3);
		}

		private void OnClimb(WorldOBB worldOBB)
		{
			StartCor(ref corClimb, DoClimb(worldOBB));
		}

		private IEnumerator DoClimb(WorldOBB worldOBB)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 8);
			isClimbing = true;
			base.playerActor.TriggerStage(4);
			base.playerActor.SetSpeed(PrologueConfig.playSpeed_3_climb);
			TSVector2 normalized = (new TSVector2(prologueMgr.EndPos.position.x, prologueMgr.EndPos.position.z) - base.playerActor.tsTransform.Position).normalized;
			base.playerActor.FixedMoveDir = normalized;
			base.playerActor.IsFixedMoveDir = true;
			yield return 20f;
			MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", "BBm00_01", 9);
		}

		public override void Update()
		{
			base.Update();
			if (!SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() || !isClimbing)
			{
				return;
			}
			if (TSMath.Abs(TSVector2.SignedAngle(SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection(), base.playerActor.tsTransform.Forward)) < PrologueConfig.offsetAngleY)
			{
				base.playerActor.forceStandBy = false;
				return;
			}
			base.playerActor.forceStandBy = true;
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			base.playerActor.PlayComboByKey(PrologueConfig.combo_notBack, delegate
			{
				SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			}, delegate
			{
				SceneSingleton<AdventurePlayerController>.Instance.InputEnable();
			});
			MonoSingleton<LuaManager>.Instance.FireEvent("AvgBubbleShow", PrologueConfig.bubbleID3, PrologueConfig.bubbleGroupID3);
		}

		private void OnEnd(WorldOBB worldOBB)
		{
			StartCor(ref corClimb, DoEnd(worldOBB));
		}

		private IEnumerator DoEnd(WorldOBB worldOBB)
		{
			isClimbing = false;
			base.playerActor.IsFixedMoveDir = false;
			SceneSingleton<AdventurePlayerController>.Instance.InputDisable();
			bool flage = false;
			TSVector2 targetPosition = new TSVector2(prologueMgr.EndPos.position.x, prologueMgr.EndPos.position.z);
			base.playerActor.MoveTo(targetPosition, 0.1, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
			{
				flage = true;
			}, randomMove: false, forceMove: true);
			while (!flage)
			{
				yield return null;
			}
			base.playerActor.PlayComboByKey(PrologueConfig.combo_stop, delegate
			{
			});
			yield return 1f;
			MaskFadeIn(PrologueConfig.fadeInTime);
			yield return PrologueConfig.fadeInTime - 0.1f;
			MonoSingleton<GameCameraStackManager>.Instance?.CloseMainCamera(0.2f);
			MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_inCS");
			MonoSingleton<ProVideoManager>.Instance.PlayVideo(PrologueConfig.videoUrl_end, (Action<bool>)delegate
			{
				MonoSingleton<LuaManager>.Instance.FireEvent("Prologue_EventUpload", "5");
				ProloguelevelMgr.Instance.SetMaskObjectActive(true);
				ProloguelevelMgr.Instance.SetMaskObjectAlpha(1f);
				CommonHelper.EnableSkillInput(enable: true);
				MonoSingleton<LuaManager>.Instance.FireEvent("ProloguelEnableBtnControl", 2, a2: true);
				SceneSingleton<AdventurePlayerController>.Instance.cameraBeacon = prologueMgr.cacheCameraBeacon;
				MonoSingleton<LuaManager>.Instance.FireEvent("MainBattleMenuBtnPauseActive", a1: true);
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_prologuel_all_stop");
				MonoSingleton<LuaManager>.Instance.FireEvent("LevelStateChanged", 3, 0);
				Singleton<InteractiveManager>.Instance.triggerOpListener("PrologueNextFloor");
				MonoSingleton<GameCameraStackManager>.Instance?.OpenMainCamera(0.2f);
				MonoSingleton<WwiseAudioManager>.Instance.PlaySound("desert_outCS");
			}, true, PrologueConfig.fadeInTime, true, PrologueConfig.fadeOutTime, PrologueConfig.videoUrl_end_skip, false, (System.Action)null);
			SceneSingleton<AdventureIndicatorController>.Instance.StopHintAttackRangeGraphic();
			yield return null;
		}

		public override void Exit()
		{
			base.Exit();
			StopCor(ref corClimb);
			StopCor(ref corTrun);
		}
	}
	public class PrologueMgr : AIBase
	{
		public enum Status
		{
			Enter,
			FirstPart,
			SencondPart,
			ThirdPart,
			End_Sec
		}

		public static PrologueMgr Ins;

		public string key_npcTargetPos = "SlideStartPoint";

		public UnityEngine.Transform npcTargetPos;

		public List<string> key_edgeOBBs = new List<string> { "LookDownArea1", "LookDownArea2", "LookDownArea3", "LookDownArea4", "LookDownArea5" };

		public List<WorldOBB> edgeOBBs = new List<WorldOBB>();

		public string key_endOBB_1 = "SlideReadyArea";

		public WorldOBB endOBB_1;

		public string key_preSlidePos = "SlideStartPoint";

		public UnityEngine.Transform preSlidePos;

		public string key_runOBB = "ChangeToRunArea";

		public WorldOBB runOBB;

		public string key_monsterOBB = "StartBattleArea";

		public WorldOBB monsterOBB;

		public string key_battle2StartPoint = "Battle2StartPoint";

		public UnityEngine.Transform battle2StartPoint;

		public string key_climbStartPos = "ClimbStartPoint_Butterfly";

		public UnityEngine.Transform climbStartPos;

		public string key_sandstormOBB = "SandstormArea";

		public WorldOBB sandstormOBB;

		public string key_climbEndPos = "ClimbEndPoint_Butterfly";

		public UnityEngine.Transform climbEndPos;

		public string key_climbOBB = "StartClimbArea";

		public WorldOBB climbOBB;

		public string key_endOBB_3 = "EndClimbArea";

		public WorldOBB endOBB_3;

		public string key_EndPos = "ChimbEndPoint";

		public UnityEngine.Transform EndPos;

		private LogicEntity entity;

		public RefTool refTool;

		private readonly Status curStatus;

		private IState curState;

		private readonly Dictionary<Status, IState> dicState = new Dictionary<Status, IState>();

		public UnityEngine.Transform cacheCameraBeacon;

		public SimpleMonsterAdventrueActor monsterActor;

		public SimplePlayerAdventureActor playerActor;

		public void OnEnable()
		{
			Ins = this;
			entity = ProloguelevelMgr.Instance;
			refTool = ProloguelevelMgr.Instance.refTool;
			npcTargetPos = refTool.GetTransformByKey(key_npcTargetPos);
			for (int i = 0; i < key_edgeOBBs.Count; i++)
			{
				edgeOBBs.Add(refTool.GetWorldOBBByKey(key_edgeOBBs[i]));
			}
			endOBB_1 = refTool.GetWorldOBBByKey(key_endOBB_1);
			preSlidePos = refTool.GetTransformByKey(key_preSlidePos);
			runOBB = refTool.GetWorldOBBByKey(key_runOBB);
			monsterOBB = refTool.GetWorldOBBByKey(key_monsterOBB);
			battle2StartPoint = refTool.GetTransformByKey(key_battle2StartPoint);
			climbStartPos = refTool.GetTransformByKey(key_climbStartPos);
			sandstormOBB = refTool.GetWorldOBBByKey(key_sandstormOBB);
			climbEndPos = refTool.GetTransformByKey(key_climbEndPos);
			climbOBB = refTool.GetWorldOBBByKey(key_climbOBB);
			endOBB_3 = refTool.GetWorldOBBByKey(key_endOBB_3);
			EndPos = refTool.GetTransformByKey(key_EndPos);
			UnityEngine.Transform transformByKey = refTool.GetTransformByKey("player");
			playerActor = transformByKey.gameObject.AddComponent<SimplePlayerAdventureActor>();
			UnityEngine.Transform transformByKey2 = refTool.GetTransformByKey("monster");
			monsterActor = transformByKey2.gameObject.AddComponent<SimpleMonsterAdventrueActor>();
			dicState.Add(Status.Enter, new EnterState(entity, this));
			dicState.Add(Status.FirstPart, new FirstPartState(entity, this));
			dicState.Add(Status.SencondPart, new SecondPartState(entity, this));
			dicState.Add(Status.ThirdPart, new ThirdPartState(entity, this));
			ProloguelevelMgr.Instance.SetCanvas();
			SceneSingleton<AdventurePlayerController>.Instance.showVisionAttackRange = false;
			SceneSingleton<AdventureIndicatorController>.Instance?.ShowHighlightBlob(show: false);
			cacheCameraBeacon = SceneSingleton<AdventurePlayerController>.Instance.cameraBeacon;
		}

		public void OnDisable()
		{
		}

		public void OnLevelStart()
		{
			ChangeState(Status.Enter);
		}

		public void OnLevelStop()
		{
		}

		public void OnUpdate()
		{
			curState?.Update();
		}

		public void ChangeState(Status status)
		{
			if (curStatus != status)
			{
				_ = curState;
			}
			curState = dicState[status];
			curState.Enter();
		}
	}
	public class SimpleActorMovementFSM(GameObject gObj) : ActorMovementFSM(gObj)
	{
		public bool isOverride;

		private ActorState lastState;

		private bool isSpdDown;

		private FP curSpeed;

		private FP fadeTime = 0.25;

		private FP deltaSpeedDown;

		public override void OnUpdate()
		{
			base.OnUpdate();
		}

		public override void UpdateAnimation(bool applyRootMotion, bool applyRootMotionRotate)
		{
			if (!isOverride)
			{
				base.UpdateAnimation(applyRootMotion, applyRootMotionRotate);
			}
			else
			{
				if (_actor.animatorController == null)
				{
					return;
				}
				if (applyRootMotionRotate)
				{
					_actor.rootBoneRotationLocked = true;
				}
				else
				{
					_actor.rootBoneRotationLocked = false;
				}
				bool flag = _actor is SimplePlayerAdventureActor;
				FP fP = (flag ? (_actor as SimplePlayerAdventureActor).animMaxSpd : _actor.GetMaxSpeed());
				float value = (float)(_actor.velocitySpeed / fP);
				if (_actor.movementState == ActorState.StandBy && lastState == ActorState.Move)
				{
					isSpdDown = true;
					curSpeed = _actor.GetMaxSpeed();
					deltaSpeedDown = curSpeed * _actor.LogicDeltaTime / fadeTime;
				}
				else if (_actor.movementState == ActorState.Move && lastState == ActorState.StandBy)
				{
					isSpdDown = false;
				}
				lastState = _actor.movementState;
				if (isSpdDown)
				{
					curSpeed -= deltaSpeedDown;
					if (curSpeed < 0)
					{
						isSpdDown = false;
						curSpeed = 0;
					}
					value = (float)(curSpeed / fP);
				}
				_actor.animatorController.SetFloat(SimplePlayerAdventureActor.actorSpeedHash, value, flag);
			}
		}

		protected override void Move(TSVector2 movementDelta)
		{
			if (!isOverride)
			{
				base.Move(movementDelta);
				return;
			}
			_accumulatedMovementDelta += movementDelta;
			_actor.AgentMove(new TSVector(movementDelta.x, 0f, movementDelta.y));
		}
	}
