	public class AmendAtkByMoveSpdAmend : PassiveSkillBase
	{
		private float atkPercentAmend;

		protected override void OnSkillEnable()
		{
			atkPercentAmend = 0f;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_MOVESPEED_CHANGED", OnMoveSpeedChanged);
		}

		protected override void OnSkillDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_MOVESPEED_CHANGED", OnMoveSpeedChanged);
		}

		private void OnMoveSpeedChanged(IEvent evt)
		{
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			if (evt is AdventureActorMoveSpeedChangedEvent adventureActorMoveSpeedChangedEvent && adventureActorMoveSpeedChangedEvent.actorId == _actor.Id)
			{
				if (atkPercentAmend != 0f)
				{
					_actor.attributeList.ChangeValue(1, 2, 0f - atkPercentAmend);
				}
				atkPercentAmend = iFP.op_Implicit(_actor.attributeList.GetAttributeValue(GameEnum.effectAttributeType.MOVESPEED) / _actor.attributeList.GetOriginValue(GameEnum.effectAttributeType.MOVESPEED));
				atkPercentAmend -= 1f;
				if (atkPercentAmend != 0f)
				{
					_actor.attributeList.ChangeValue(1, 2, atkPercentAmend);
				}
			}
		}
	}
	public class Outfit_1000000 : SkillAdvancedBase
	{
		private readonly int _buffId1 = 230000232;

		private readonly int _buffId2 = 230000233;

		private readonly int _buffId3 = 230000234;

		private readonly int _buffId4 = 230000235;

		private readonly string _fxPath = "Actor/Character/Troubadour/FX/fx_troubadour_base_dodge_1";

		protected PlayFX _playFX;

		protected override void OnSkillEnable()
		{
			if (_playFX == null)
			{
				_playFX = new PlayFX();
			}
			_playFX.Play(_actor, _skill, _fxPath, 0, _actor.tsTransform.Position, _actor.tsTransform.Forward);
			int num = UnityEngine.Random.Range(0, 100);
			int buffID = _buffId1;
			if (num <= 70 && num > 50)
			{
				buffID = _buffId2;
			}
			else if (num <= 50 && num > 30)
			{
				buffID = _buffId3;
			}
			else if (num <= 30)
			{
				buffID = _buffId4;
			}
			_actor?.buffComponent.AddBuff(buffID, _actor);
			_skill.Clear();
		}

		protected override void OnSkillDisable()
		{
			_playFX?.Stop();
			_playFX?.Clear();
		}
	}
