	public class OperateAreaEffectByInterval : PassiveSkillBase
	{
		private FP interval = 2;

		private string areaEffectAlias = "AreaEffect_VampireMonster";

		private CoroutineNode countdownCoroutineNode;

		private long areaEffectId;

		protected override void OnSkillEnable()
		{
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
			areaEffectId = ILRuntimeAPI.PlayAreaEffect(_actor, areaEffectAlias, _actor.tsTransform.Position, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}

		protected override void OnSkillDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
			StopCoroutine(ref countdownCoroutineNode);
			ILRuntimeAPI.StopAreaEffect(areaEffectId);
		}

		private void OnDamage(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent && !(adventureActorReceiveDamageEvent.to != _actor))
			{
				ILRuntimeAPI.StopAreaEffect(areaEffectId);
				areaEffectId = 0L;
				StartCoroutine(ref countdownCoroutineNode, Countdown());
			}
		}

		private IEnumerator Countdown()
		{
			yield return _actor.WaitTime(interval);
			areaEffectId = ILRuntimeAPI.PlayAreaEffect(_actor, areaEffectAlias, _actor.tsTransform.Position, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}
	}
	public class StandbyAmend : PassiveSkillBase
	{
		private int atkAmendBuffId;

		private FP addBuffTimeThreshold = 3f;

		private FP moveTimeInterval = 1f;

		private FP moveEnergyLoss = 5;

		private CoroutineNode mainCoroutine;

		private FP standbyTimer = 0f;

		private FP moveTimer = 0f;

		private bool buffAdded;

		protected override void OnSkillEnable()
		{
			standbyTimer = 0;
			moveTimer = 0;
			buffAdded = false;
			StartCoroutine(ref mainCoroutine, Main());
		}

		protected override void OnSkillDisable()
		{
			StopCoroutine(ref mainCoroutine);
		}

		private IEnumerator Main()
		{
			while (true)
			{
				if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput())
				{
					standbyTimer += _actor.LogicDeltaTime;
					moveTimer = 0;
					if (standbyTimer >= addBuffTimeThreshold && !buffAdded)
					{
						_actor.buffComponent.AddBuff(atkAmendBuffId, _actor);
						buffAdded = true;
					}
				}
				else
				{
					standbyTimer = 0;
					moveTimer += _actor.LogicDeltaTime;
					if (buffAdded)
					{
						_actor.buffComponent.RemoveBuffByBuffId(atkAmendBuffId);
						buffAdded = false;
					}
					if (moveTimer >= moveTimeInterval)
					{
						moveTimer = 0;
						if (_actor is PlayerAdventureActor playerAdventureActor)
						{
							playerAdventureActor.playerSkillCd.AddEnergy(-moveEnergyLoss);
						}
					}
				}
				yield return null;
			}
		}
	}
	public class SummonMonsterKillAmend : PassiveSkillBase
	{
		private int addTotalCount = 2;

		private FP addTime = 3;

		private int addCount;

		protected override void OnSkillEnable()
		{
			addCount = 0;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
		}

		protected override void OnSkillDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
		}

		private void OnDamage(IEvent evt)
		{
			if (addCount >= addTotalCount || !(evt is AdventureActorReceiveDamageEvent { isKill: not false } adventureActorReceiveDamageEvent))
			{
				return;
			}
			MonsterAdventureActor monsterAdventureActor = adventureActorReceiveDamageEvent.from as MonsterAdventureActor;
			if (monsterAdventureActor == null || monsterAdventureActor.monsterSummonInfo.SummonActor == null || monsterAdventureActor.monsterSummonInfo.SummonActor.Id != _actor.Id)
			{
				return;
			}
			bool flag = _actor is PlayerAdventureActor;
			foreach (AdventureModuleController.MonsterSummonData monsterSummonInfo in ModuleController<AdventureModuleController>.Instance.MonsterSummonInfos)
			{
				if (monsterSummonInfo.isPlayerSummons == flag)
				{
					monsterSummonInfo.monster.monsterSummonInfo.AddLeftTime(addTime);
				}
			}
			addCount++;
		}
	}
	public class UltimateSkillKillAmend : PassiveSkillBase
	{
		private GameEnum.skillSlotType skillType = GameEnum.skillSlotType.D;

		private FP checkTime = 3;

		private int atkAmendBuffId;

		private bool killMonster;

		private CoroutineNode timeCoroutine;

		protected override void OnSkillEnable()
		{
			killMonster = false;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
		}

		protected override void OnSkillDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			StopCoroutine(ref timeCoroutine);
		}

		private void OnCastSkill(IEvent evt)
		{
			if (evt is AdventureActorCastSkillEvent adventureActorCastSkillEvent && !(adventureActorCastSkillEvent.sender as AdventureActor != _actor) && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == skillType)
			{
				StartCoroutine(ref timeCoroutine, Countdown());
			}
		}

		private void OnDamage(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent && adventureActorReceiveDamageEvent.from.Id == _actor.Id && adventureActorReceiveDamageEvent.isKill)
			{
				killMonster = true;
			}
		}

		private IEnumerator Countdown()
		{
			killMonster = false;
			yield return _actor.WaitTime(checkTime);
			if (!killMonster)
			{
				_actor.buffComponent.AddBuff(atkAmendBuffId, _actor);
			}
		}
	}
}
