		public void OnStart()
		{
			_checkQualifiedAIBranchCoroutine = _actor.StartLogicCoroutine(CheckQualifiedAIBranch());
		}

		private IEnumerator CheckQualifiedAIBranch()
		{
			while (true)
			{
				while (_castingSkill || (_actor.logicVariable?.GetLogicTagToggle("ExecutingSpecialSkill") ?? false))
				{
					LogicVariable logicVariable = _actor.logicVariable;
					if (logicVariable == null || logicVariable.GetLogicTagToggle("ExecutingCanBreakSkill"))
					{
						break;
					}
					yield return null;
				}
				if (_executeBranch == null)
				{
					Action action = this;
					LogicEntity logicEntity = (_actor.monsterTarget = SearchTarget());
					action.target = logicEntity;
					if (target == null && _actor is MonsterAdventureActor)
					{
						break;
					}
				}
				FP fP = _actor.DistanceWithRadius(target);
				BranchInfo qualifiedBranch = _aiBranchPool.CheckQualifiedBranch(fP, target);
				if (qualifiedBranch != null && qualifiedBranch != _executeBranch && ((_executeBranch != null && qualifiedBranch.baseInfo.Priority > _executeBranch.baseInfo.Priority) || _executeBranch == null))
				{
					if (_actor.logicVariable?.GetLogicTagToggle("ExecutingCanBreakSkill") ?? false)
					{
						_actor.actorSkillManage.DestoryAllSkill();
					}
					_traceTarget?.CancelTrace();
					_lookAtTarget?.StopLookAt();
					_executeBranch = qualifiedBranch;
					AdventureActorRunBranchEvent adventureActorRunBranchEvent = AdventureActorRunBranchEvent.Generate();
					adventureActorRunBranchEvent.sender = _actor;
					adventureActorRunBranchEvent.branchId = qualifiedBranch.baseInfo.Id;
					adventureActorRunBranchEvent.skillId = qualifiedBranch.baseInfo.SkillId;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureActorRunBranchEvent);
					if (_actor.actorInfo.moveType == GameEnum.actorMovType.STATIC || fP <= qualifiedBranch.baseInfo.ReleaseDistance * GameDataController.IntFloatPrecisionFP)
					{
						if (_actor.actorInfo.moveType != GameEnum.actorMovType.STATIC)
						{
							TSVector2 a = target.tsTransform.Position - _actor.tsTransform.Position;
							TSVector2 forward = _actor.tsTransform.Forward;
							if (TSVector2.Angle(a, forward) > qualifiedBranch.baseInfo.ReleaseAngle * GameDataController.IntFloatPrecisionFP)
							{
								if (_lookAtTarget == null)
								{
									_lookAtTarget = new LookAtTarget();
								}
								_lookAtTarget.BeginLookAt(_actor, target, 0, 0, delegate
								{
									CastSkill(qualifiedBranch);
								}, ignoreActorTimeScale: false, delegate
								{
									_executeBranch = null;
								});
							}
							else
							{
								CastSkill(qualifiedBranch);
							}
						}
						else
						{
							CastSkill(qualifiedBranch);
						}
					}
					else
					{
						if (_traceTarget == null)
						{
							_traceTarget = new TraceTarget();
						}
						_traceTarget.BeginTrace(_actor, target, qualifiedBranch.baseInfo.ReleaseDistance * GameDataController.IntFloatPrecisionFP, -1, qualifiedBranch.baseInfo.TraceDuration * GameDataController.IntFloatPrecisionFP, delegate
						{
							CastSkill(qualifiedBranch);
						}, delegate
						{
							_executeBranch = null;
						});
					}
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_thinkInterval));
			}
			_actor.Idle();
		}

		private void CastSkill(BranchInfo qualifiedBranch)
		{
			StartProcessBranchCdByConfig();
			if (qualifiedBranch.baseInfo.SkillId != 0)
			{
				_castingSkill = true;
				_aiBranchPool.RefreshBranchCastSkillTimes(qualifiedBranch);
				ILRuntimeAPI.CreateSkill(qualifiedBranch.baseInfo.SkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
				{
					if (_castingSkill)
					{
						EndProcessBranchCdByConfig();
						_aiBranchPool.ExecuteFollowEvent(_executeBranch.baseInfo);
						_executeBranch = null;
						_castingSkill = false;
						if (_inSwitchStateProtect)
						{
							_inSwitchStateProtect = false;
							_actor.DisableImmuneControl();
							(_actor as MonsterAdventureActor).monsterToughnessInfo.lockToughness = false;
						}
					}
				}, delegate(FP cd)
				{
					if (_castingSkill)
					{
						_executeBranch.SetSkillCdExpireTime(cd, _actor.LogicTime);
					}
				});
			}
			else
			{
				EndProcessBranchCdByConfig();
				_aiBranchPool.ExecuteFollowEvent(_executeBranch.baseInfo);
				_executeBranch = null;
			}
		}

		private void StartProcessBranchCdByConfig()
		{
			if (_executeBranch.baseInfo.StartCDTime == 0)
			{
				_executeBranch.ResetAiCdExpireTime(_actor.LogicTime);
			}
			else
			{
				_setBranchCdByConfigCoroutine = _actor.StartLogicCoroutine(ProcessBranchCdByConfig());
			}
		}

		private void EndProcessBranchCdByConfig()
		{
			if (_setBranchCdByConfigCoroutine != null)
			{
				_actor.StopLogicCoroutine(_setBranchCdByConfigCoroutine);
				_setBranchCdByConfigCoroutine = null;
			}
		}

		private IEnumerator ProcessBranchCdByConfig()
		{
			FP currentTime = 0;
			FP startTime = _executeBranch.baseInfo.StartCDTime * GameDataController.IntFloatPrecisionFP;
			while (true)
			{
				currentTime += _actor.LogicDeltaTime;
				if (currentTime >= startTime)
				{
					break;
				}
				yield return null;
			}
			_executeBranch?.ResetAiCdExpireTime(_actor.LogicTime);
		}

		public void OnStop()
		{
			if (_checkQualifiedAIBranchCoroutine != null)
			{
				_actor.StopLogicCoroutine(_checkQualifiedAIBranchCoroutine);
				_checkQualifiedAIBranchCoroutine = null;
			}
			_castingSkill = false;
			_executeBranch = null;
			EndProcessBranchCdByConfig();
			_traceTarget?.CancelTrace();
			_lookAtTarget?.StopLookAt();
			if (_inSwitchStateProtect)
			{
				_inSwitchStateProtect = false;
				_actor.DisableImmuneControl();
				(_actor as MonsterAdventureActor).monsterToughnessInfo.lockToughness = false;
			}
		}

		public virtual LogicEntity SearchTarget()
		{
			return _actor.actorSearchTargetInfo.GetMonsterAttackTarget();
		}
	}
	public class Death : AIBase
	{
		protected int _skillId;

		public void OnEnable()
		{
			_skillId = (_actor as MonsterAdventureActor).monsterAIInfo.deathSkillId;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		}

		public void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
		}

		public void OnStart()
		{
			_actor.inDying = true;
			if (_skillId != 0)
			{
				_actor.EnableDyingSuperArmor();
				ILRuntimeAPI.CreateSkill(_skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
				{
					_actor.DisableDyingSuperArmor();
					DeathFinish();
				});
			}
			else
			{
				DeathFinish();
			}
			void DeathFinish()
			{
				_actor.inDying = false;
			}
		}

		protected void MonsterDeclareDeath(IEvent ievent)
		{
			if ((ievent as AdventureMonsterDeclareDiedEvent).id == _actor.Id)
			{
				OnThemSkill();
			}
		}

		private void OnThemSkill()
		{
			int themeSkillId = (_actor as MonsterAdventureActor).monsterAIInfo.themeSkillId;
			if (themeSkillId > 0)
			{
				ModuleController<AdventureModuleController>.Instance?.UseMonsterCloneActorCastSkill(_actor as MonsterAdventureActor, themeSkillId);
			}
		}
	}
	public class Idle : AIBase
	{
		protected FP _wanderRange;

		protected FP _wanderInterval;

		protected FP _wanderRate;

		private bool _castSpawnSkill;

		protected CoroutineNode _patrolCoroutine;

		protected CoroutineNode _wanderCoroutine;

		private bool _skillFinish;

		private TSVector2[] strollPoints;

		private bool strollInCircle;

		private bool isToughnessBroken;

		public void OnEnable()
		{
			_castSpawnSkill = true;
			_wanderRange = (_actor as MonsterAdventureActor).monsterAIInfo.wanderRange;
			_wanderInterval = (_actor as MonsterAdventureActor).monsterAIInfo.wanderInterval;
			_wanderRate = (_actor as MonsterAdventureActor).monsterAIInfo.wanderRate;
			strollPoints = (_actor as MonsterAdventureActor).spawnerInfo.strollPoints;
			strollInCircle = (_actor as MonsterAdventureActor).spawnerInfo.strollInCircle;
		}

		public void OnStart()
		{
			isToughnessBroken = true;
			if (!(_actor is MonsterAdventureActor { ToughnessBrokenToIdle: false } monsterAdventureActor))
			{
				return;
			}
			isToughnessBroken = false;
			_skillFinish = false;
			bool jumpOverSpawnPerformance = monsterAdventureActor.spawnerInfo.jumpOverSpawnPerformance;
			int spawnSkillId = monsterAdventureActor.monsterAIInfo.spawnSkillId;
			if (!jumpOverSpawnPerformance && spawnSkillId > 0 && _castSpawnSkill)
			{
				ILRuntimeAPI.CreateSkill(spawnSkillId, monsterAdventureActor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: true, SkillCountdownTiming.Start, delegate
				{
					EnterIdleShowSkill();
				});
				_castSpawnSkill = false;
			}
			else
			{
				EnterIdleShowSkill();
			}
		}

		private void EnterIdleShowSkill()
		{
			int idleShowSkillId = (_actor as MonsterAdventureActor).monsterAIInfo.idleShowSkillId;
			if (idleShowSkillId > 0)
			{
				ILRuntimeAPI.CreateSkill(idleShowSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: true, SkillCountdownTiming.Start, delegate
				{
					BeginPatrol();
				});
			}
			else
			{
				BeginPatrol();
			}
		}

		private void BeginPatrol()
		{
			_skillFinish = true;
			if (strollPoints != null && strollPoints.Length != 0)
			{
				StartCoroutine(ref _wanderCoroutine, Wander());
			}
			else if (_wanderRange > 0 && _wanderRate > 0)
			{
				_patrolCoroutine = _actor.StartLogicCoroutine(Patrol());
			}
		}

		private IEnumerator Wander()
		{
			int index = 0;
			int _index = 0;
			int dirction = 1;
			int count = strollPoints.Length;
			bool moveFinish = false;
			while (true)
			{
				moveFinish = false;
				_actor.MoveTo(strollPoints[index], 0.1f, enableNavigation: false, AdventureActor.MovementMode.Run, delegate
				{
					moveFinish = true;
					if (strollInCircle)
					{
						index = _index++ % count;
					}
					else
					{
						if (index == 0 && dirction == -1)
						{
							dirction = 1;
						}
						else if (index == count - 1 && dirction == 1)
						{
							dirction = -1;
						}
						index += dirction;
					}
				});
				while (!moveFinish)
				{
					yield return null;
				}
			}
		}

		private IEnumerator Patrol()
		{
			TSVector2 initPosition = _actor.tsTransform.Position;
			while (true)
			{
				TSVector2 targetPosition = _actor.RandomActorReachablePointInsideRing(initPosition, 0.1, _wanderRange);
				bool moveFinish = false;
				_actor.MoveTo(targetPosition, 0.1f, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
				{
					moveFinish = true;
				});
				while (!moveFinish)
				{
					yield return null;
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_wanderInterval));
				while (!(TSRandom.Range(0f, 1f) <= _wanderRate))
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_wanderInterval));
				}
			}
		}

		public void OnStop()
		{
			if (!isToughnessBroken)
			{
				StopCoroutine(ref _wanderCoroutine);
				if (_patrolCoroutine != null)
				{
					_actor.StopLogicCoroutine(_patrolCoroutine);
					_patrolCoroutine = null;
				}
				int idleShowSkillId = (_actor as MonsterAdventureActor).monsterAIInfo.idleShowSkillId;
				if (idleShowSkillId > 0)
				{
					_actor.actorSkillManage.ClearSkillById(idleShowSkillId);
				}
				int spawnSkillId = (_actor as MonsterAdventureActor).monsterAIInfo.spawnSkillId;
				if (spawnSkillId > 0)
				{
					_actor.actorSkillManage.ClearSkillById(spawnSkillId);
				}
			}
		}

		public void OnUpdate()
		{
			if (!(_actor is MonsterAdventureActor monsterAdventureActor))
			{
				return;
			}
			if (isToughnessBroken)
			{
				if (!monsterAdventureActor.ToughnessBrokenToIdle)
				{
					_actor.Action();
				}
			}
			else
			{
				if (!_skillFinish || (!ModuleController<AdventureModuleController>.Instance.InBattleState && !monsterAdventureActor.monsterSummonInfo.isPlayerSummoned))
				{
					return;
				}
				ILRuntimeAPI.RangeSearch(_actor, delegate(List<LogicEntity> result)
				{
					if (result.Count > 0)
					{
						_actor.Action();
					}
				});
			}
		}
	}
	public class Parallel : AIBase
	{
		private HashSet<int> StateSet = new HashSet<int>();

		private List<CoroutineNode> protectNodes;

		protected PlayerAdventureActor _player;

		public virtual void OnStart()
		{
			InitState();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("SEARCHIMMUNITY_STATE_CHANGE", OnSearchImmunityStateChange);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("FORCE_TARGET_STATE_CHANGE", OnForceTargetStateChange);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
		}

		public virtual void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("SEARCHIMMUNITY_STATE_CHANGE", OnSearchImmunityStateChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("FORCE_TARGET_STATE_CHANGE", OnForceTargetStateChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			if (protectNodes == null)
			{
				return;
			}
			foreach (CoroutineNode protectNode in protectNodes)
			{
				_actor.StopLogicCoroutine(protectNode);
			}
			protectNodes.Clear();
			protectNodes = null;
		}

		private void OnForceTargetStateChange(IEvent e)
		{
			if (_actor.actorHealthInfo.isAlive && e is AdventureForceTargetStateChangedEvent adventureForceTargetStateChangedEvent && adventureForceTargetStateChangedEvent.actor.Id == _actor.Id)
			{
				_actor.monsterTarget = _actor.actorSearchTargetInfo.GetMonsterAttackTarget();
			}
		}

		private void OnSearchImmunityStateChange(IEvent e)
		{
			if (_actor.actorHealthInfo.isAlive && !(_actor.monsterTarget == null) && e is AdventureSearchImmunityStateChangedEvent adventureSearchImmunityStateChangedEvent && adventureSearchImmunityStateChangedEvent.actor.Id == _actor.monsterTarget.Id)
			{
				_actor.monsterTarget = _actor.actorSearchTargetInfo.GetMonsterAttackTarget();
			}
		}

		protected virtual void OnActorDied(IEvent e)
		{
			if (e is AdventureActorDiedEvent adventureActorDiedEvent)
			{
				OnDied(adventureActorDiedEvent.actor.dataID);
				if (_actor.actorHealthInfo.isAlive && !(_actor.monsterTarget == null) && adventureActorDiedEvent.actor.Id == _actor.monsterTarget.Id)
				{
					_actor.monsterTarget = _actor.actorSearchTargetInfo.GetMonsterAttackTarget();
				}
			}
		}

		public virtual void OnDied(int monsterId)
		{
		}

		private IEnumerator Search()
		{
			while (true)
			{
				yield return null;
			}
		}

		private void InitState()
		{
			_player = SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor;
			OnInitState();
			SaveMonsterState();
		}

		protected virtual void OnInitState()
		{
		}

		protected bool EnterState(int stateIndex)
		{
			return StateSet.Add(stateIndex);
		}

		protected bool SwitchState(bool breakCurrentAction, bool breakForceControl, int lastStateIndex, int nextStateIndex)
		{
			if (StateSet.Contains(nextStateIndex))
			{
				return false;
			}
			if (StateSet.Contains(lastStateIndex))
			{
				StateSet.Remove(lastStateIndex);
				StateSet.Add(nextStateIndex);
				SaveMonsterState();
				AdventureMonsterSwitchCustomStateEvent adventureMonsterSwitchCustomStateEvent = AdventureMonsterSwitchCustomStateEvent.Generate();
				adventureMonsterSwitchCustomStateEvent.sender = _actor;
				adventureMonsterSwitchCustomStateEvent.commonHandle = true;
				adventureMonsterSwitchCustomStateEvent.breakCurrentAction = breakCurrentAction;
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureMonsterSwitchCustomStateEvent);
				if (breakForceControl && _actor.state == ActorState.LostControl)
				{
					_actor.InterruptForceControl();
					CoroutineNode item = _actor.StartLogicCoroutine(Protect());
					if (protectNodes == null)
					{
						protectNodes = new List<CoroutineNode>();
					}
					protectNodes.Add(item);
				}
				OnSwitchState();
				return true;
			}
			return false;
		}

		private void SaveMonsterState()
		{
			string text = "";
			foreach (int item in StateSet)
			{
				text = text + item + ",";
			}
			_actor.logicVariable.SetLogicTagStringValue("Monster_In_State", text);
		}

		protected virtual void OnSwitchState()
		{
		}

		protected IEnumerator Protect()
		{
			_actor.EnableImmuneControl();
			(_actor as MonsterAdventureActor).monsterToughnessInfo.lockToughness = true;
			while (_actor.state == ActorState.LostControl)
			{
				yield return null;
			}
			_actor.DisableImmuneControl();
			(_actor as MonsterAdventureActor).monsterToughnessInfo.lockToughness = false;
		}

		protected bool MonsterInState(int state)
		{
			return StateSet.Contains(state);
		}
	}
	public class Parallel_BossRush : Parallel
	{
		private static readonly FP triggerTime_ContinuousAttack = 5;

		private static readonly FP interruptTime_ContinuousAttack = 1;

		protected MonsterAdventureActor _monster;

		private List<FP> _receiveDamageTimeList;

		public override void OnStart()
		{
			base.OnStart();
			_monster = _actor as MonsterAdventureActor;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnActorCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnActorCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnMonsterToughtnessStateChange);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnActorReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnReceiveBeforeHit);
		}

		private void OnActorCastSkill(IEvent evt)
		{
			if (!(evt is AdventureActorCastSkillEvent adventureActorCastSkillEvent))
			{
				return;
			}
			if (adventureActorCastSkillEvent.sender as AdventureActor is PlayerAdventureActor playerAdventureActor)
			{
				if (adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.D)
				{
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)10))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)10);
					}
				}
				else if (playerAdventureActor.isAssist && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B && _monster.CheckScoreBossBehaviour((scoreBossBehavior)9))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)9);
				}
			}
			OnActorCastSkill(adventureActorCastSkillEvent);
		}

		private void OnActorCastSkillEnd(IEvent evt)
		{
			if (evt is AdventureActorCastSkillEndEvent castSkillEndEvent)
			{
				OnActorCastEndSkill(castSkillEndEvent);
			}
		}

		protected virtual void OnActorCastSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
		}

		protected virtual void OnActorCastEndSkill(AdventureActorCastSkillEndEvent castSkillEndEvent)
		{
		}

		private void OnMonsterToughtnessStateChange(IEvent evt)
		{
			if (evt is MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent)
			{
				if (monsterToughnessStateChangeEvent.actor == _actor && monsterToughnessStateChangeEvent.isToughnessBroken && _monster.CheckScoreBossBehaviour((scoreBossBehavior)7))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)7);
				}
				OnMonsterToughtnessStateChange(monsterToughnessStateChangeEvent);
			}
		}

		protected virtual void OnMonsterToughtnessStateChange(MonsterToughnessStateChangeEvent toughtnessStateChangeEvent)
		{
		}

		private void OnActorReceiveDamage(IEvent evt)
		{
			if (!(evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent))
			{
				return;
			}
			if (adventureActorReceiveDamageEvent.to == _actor && _monster.CheckScoreBossBehaviour((scoreBossBehavior)8))
			{
				if (_receiveDamageTimeList == null)
				{
					_receiveDamageTimeList = new List<FP>();
				}
				if (_receiveDamageTimeList.Count > 0)
				{
					FP fP = _receiveDamageTimeList.Last();
					if (_actor.LogicTime - fP > interruptTime_ContinuousAttack)
					{
						_receiveDamageTimeList.Clear();
					}
					else
					{
						FP fP2 = _receiveDamageTimeList.First();
						if (_actor.LogicTime - fP2 > triggerTime_ContinuousAttack)
						{
							_monster.TriggerScoreBossBehaviour((scoreBossBehavior)8);
							_receiveDamageTimeList.Clear();
						}
					}
				}
				_receiveDamageTimeList.Add(_actor.LogicTime);
			}
			OnActorReceiveDamage(adventureActorReceiveDamageEvent);
		}

		protected virtual void OnActorReceiveDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private void OnElementMarkTrigger(IEvent evt)
		{
			if (!(evt is AdventureElementMarkTriggerEvent adventureElementMarkTriggerEvent))
			{
				return;
			}
			if (adventureElementMarkTriggerEvent.markActor == _actor)
			{
				switch (adventureElementMarkTriggerEvent.elementType)
				{
				case GameEnum.elementType.WE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)3))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)3);
					}
					break;
				case GameEnum.elementType.FE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)2))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)2);
					}
					break;
				case GameEnum.elementType.SE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)1))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)1);
					}
					break;
				case GameEnum.elementType.AE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)4))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)4);
					}
					break;
				case GameEnum.elementType.LE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)5))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)5);
					}
					break;
				case GameEnum.elementType.DE:
					if (_monster.CheckScoreBossBehaviour((scoreBossBehavior)6))
					{
						_monster.TriggerScoreBossBehaviour((scoreBossBehavior)6);
					}
					break;
				}
			}
			OnElementMarkTrigger(adventureElementMarkTriggerEvent);
		}

		protected virtual void OnElementMarkTrigger(AdventureElementMarkTriggerEvent elementMarkTriggerEvent)
		{
		}

		protected virtual void OnReceiveBeforeHit(IEvent evt)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnActorCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnActorCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnMonsterToughtnessStateChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnActorReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnReceiveBeforeHit);
			_receiveDamageTimeList?.Clear();
		}
	}
	public class Skill_DrawGraphicIndicator : SkillSimpleBase
	{
		protected override IEnumerator DoMainLogic()
		{
			GetEntityPosition(GetCurrentPlayer());
			yield return null;
		}

		protected IEnumerator DrawCircleGraphicIndicator(bool IsFull, TSVector2 Position, FP Radius, Color Color, FP DelayTime)
		{
			double ElapsedTime = 0.0;
			CircleGraphicIndicator GraphicIndicator = SceneSingleton<AdventureIndicatorController>.Instance.SpawnCircleGraphicIndicator();
			GraphicIndicator.position = Position.ToVector2();
			GraphicIndicator.rotation = 0f;
			GraphicIndicator.size = (float)Radius * 2f;
			GraphicIndicator.progress = 0f;
			GraphicIndicator.progressColor = Color;
			while (ElapsedTime <= DelayTime)
			{
				ElapsedTime += 0.03;
				FP fP = ((DelayTime > 0f) ? TSMath.Clamp01(ElapsedTime / DelayTime) : ((FP)1f));
				if (!IsFull)
				{
					GraphicIndicator.progress = (float)fP;
				}
				else
				{
					GraphicIndicator.progress = 1f;
				}
				yield return WaitTime(0.03);
			}
			GraphicIndicator.gameObject.SetActive(value: false);
		}

