	public class Skill_Wind_Cyclone : SkillSimpleBase
	{
		private readonly string fx_Path = "FX/MonsterDrop/fx_common_Cristal_Charge_Wind";

		private readonly string fx_Path_Shoot = "FX/MonsterDrop/fx_monster_drop_base_wind_shoot_1";

		private static readonly string AreaEffectAlias = "Actor/Monster/RogueMonsterTheme/Weapon/Theme_Wind_Cyclone";

		private static readonly int totalFrame = 150;

		private static FP playAreaEffectCD = 3f;

		private static FP playAreaEffectDistance = 10;

		private PlayFX _playFxA;

		private PlayFX _playFxB;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_playFxA?.Clear();
			_playFxB?.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			_playFxA = new PlayFX();
			_playFxB = new PlayFX();
			Quaternion rotation = Quaternion.Euler(0f, 0f - (float)_actor.tsTransform.Rotation, 0f);
			_playFxA.Play(_actor, fx_Path, 1f, _actor.transform.position, rotation);
			yield return WaitTime(1);
			int currentFrame = 0;
			FP lastPlayAreaEffectTime = 0;
			while (currentFrame <= totalFrame)
			{
				yield return WaitFrame(1);
				currentFrame++;
				if (lastPlayAreaEffectTime > 0 && _actor.LogicTime - lastPlayAreaEffectTime < playAreaEffectCD)
				{
					continue;
				}
				LogicEntity attackTarget = GetAttackTarget(isUpToDate: true);
				if (!(attackTarget == null))
				{
					TSVector2 entityPosition = GetEntityPosition(attackTarget);
					if (!(Distance(entityPosition, GetPosition()) > playAreaEffectDistance))
					{
						_playFxB.Play(_actor, fx_Path_Shoot, 1f, _actor.transform.position, rotation);
						PlayAreaEffect(AreaEffectAlias, entityPosition);
						lastPlayAreaEffectTime = _actor.LogicTime;
					}
				}
			}
			_playFxA.Stop();
			_playFxB.Stop();
		}
	}
