	public class CommonAction : AIBase
	{
		protected SkillPool _skillPool;

		protected TraceTarget _traceTarget;

		protected CoroutineNode _checkQualifiedSkillCoroutine;

		public virtual void OnDisable()
		{
			_skillPool = null;
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
			if (_checkQualifiedSkillCoroutine != null)
			{
				_actor.StopLogicCoroutine(_checkQualifiedSkillCoroutine);
				_checkQualifiedSkillCoroutine = null;
			}
		}

		public virtual void OnStart()
		{
			if (_skillPool == null)
			{
				_skillPool = new SkillPool();
				InitSkill();
				_checkQualifiedSkillCoroutine = _actor.StartLogicCoroutine(CheckQualifiedSkill());
			}
			else
			{
				_actor.StartLogicCoroutine(WaitAndCheckQualifiedSkill(0.5f));
			}
		}

		protected virtual void InitSkill()
		{
			List<SkillVariable> list = new List<SkillVariable>();
			SkillVariable item = new SkillVariable(1000100, 1, 0, 2, 5, immBondage: false, _actor.LogicTime);
			list.Add(item);
			item = new SkillVariable(9999999, 1, 0, 2, 2, immBondage: false, _actor.LogicTime);
			list.Add(item);
			_skillPool.Init(_actor, list, 0.1);
		}

		private IEnumerator WaitAndCheckQualifiedSkill(FP seconds)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(seconds));
			_checkQualifiedSkillCoroutine = _actor.StartLogicCoroutine(CheckQualifiedSkill());
		}

		private IEnumerator CheckQualifiedSkill()
		{
			while (true)
			{
				string text = _actor.logicVariable?.GetLogicTagStringValue("Target");
				LogicEntity logicEntity = null;
				if (text != "none")
				{
					CommonUtils.TryParseStringParamToInt(text, out var intValue);
					logicEntity = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(intValue);
					if (logicEntity == null)
					{
						logicEntity = ModuleController<AdventureModuleController>.Instance.QueryPlayerEntityByID(intValue);
					}
				}
				if (logicEntity == null)
				{
					break;
				}
				SkillVariable qualifiedSkill = _skillPool.CheckQualifiedSkill(_actor.LogicTime);
				if (qualifiedSkill == null)
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_skillPool.checkInterval));
					continue;
				}
				if (_traceTarget == null)
				{
					_traceTarget = new TraceTarget();
				}
				bool traceFinish = false;
				bool skillFinish = false;
				_traceTarget.BeginTrace(_actor, logicEntity, qualifiedSkill.releaseDistance, -1, qualifiedSkill.trackTime, delegate
				{
					qualifiedSkill.ResetExpireTime(_actor.LogicTime);
					ILRuntimeAPI.CreateSkill(qualifiedSkill.id, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
					{
						skillFinish = true;
					});
					traceFinish = true;
				}, delegate(bool isdie, bool isInterrupt)
				{
					if (!isdie)
					{
						qualifiedSkill.ResetExpireTime(_actor.LogicTime);
					}
					traceFinish = true;
					skillFinish = true;
				});
				while (!traceFinish)
				{
					yield return null;
				}
				while (!skillFinish)
				{
					yield return null;
				}
			}
			_actor.Idle();
		}

		public virtual void OnStop()
		{
			_traceTarget?.Clear();
			if (_checkQualifiedSkillCoroutine != null)
			{
				_actor.StopLogicCoroutine(_checkQualifiedSkillCoroutine);
				_checkQualifiedSkillCoroutine = null;
			}
		}
	}
	public class Idle : AIBase
	{
		protected List<LogicEntity> scopeVision;

		protected List<LogicEntity> scopeHear;

		public bool onlyAlive = true;

		public bool includeSelf;

		public void OnUpdate()
		{
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (monsterAdventureActor == null || (!ModuleController<AdventureModuleController>.Instance.InBattleState && !monsterAdventureActor.monsterSummonInfo.isPlayerSummoned))
			{
				return;
			}
			ILRuntimeAPI.RangeSearch(_actor, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					_actor.Action();
				}
			});
		}
	}
	public class IdlePatrol : AIBase
	{
		protected CoroutineNode _patrolCoroutine;

		public void OnStart()
		{
			_patrolCoroutine = _actor.StartLogicCoroutine(Patrol());
		}

		private IEnumerator Patrol()
		{
			TSVector2 initPostion = _actor.tsTransform.Position;
			while (true)
			{
				TSVector2 tSVector = _actor.RandomActorReachablePointInsideRing(initPostion, 1, 2);
				if (TSVector2.Distance(_actor.tsTransform.Position, tSVector) >= 2)
				{
					bool moveFinish = false;
					_actor.MoveTo(tSVector, 0.1f, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
					{
						moveFinish = true;
					});
					while (!moveFinish)
					{
						yield return null;
					}
					int num = TSRandom.Range(1, 2);
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(num));
				}
				else
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.5f));
				}
			}
		}

		public void OnStop()
		{
			if (_patrolCoroutine != null)
			{
				_actor.StopLogicCoroutine(_patrolCoroutine);
				_patrolCoroutine = null;
			}
		}

		public void OnUpdate()
		{
			if (!ModuleController<AdventureModuleController>.Instance.InBattleState)
			{
				return;
			}
			ILRuntimeAPI.RangeSearch(_actor, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					_actor.Action();
				}
			});
		}

		public void OnDisable()
		{
		}

		public void OnEnable()
		{
		}
	}
	public class Parallel : AIBase
	{
		protected CoroutineNode _searchCoroutine;

		protected LogicVariable _logicVariable;

		public void OnStart()
		{
			_logicVariable = ActorHelper.GetFlowLogicVariable(_actor.gameObject);
			_searchCoroutine = _actor.StartLogicCoroutine(Search());
		}

		private IEnumerator Search()
		{
			while (true)
			{
				if (_logicVariable != null)
				{
					_actor.monsterTarget = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
					if (_actor.monsterTarget != null)
					{
						_logicVariable.SetLogicTagStringValue("Target", _actor.monsterTarget.Id.ToString());
					}
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.1f));
			}
		}

		public void OnDisable()
		{
			if (_searchCoroutine != null)
			{
				_actor.StopLogicCoroutine(_searchCoroutine);
				_searchCoroutine = null;
			}
		}

		public void OnEnable()
		{
		}
	}
	public class Skill_AlertMove : Skill_AlertMoveBase
	{
		private new FP movementMaXRuningTime = 5;

		private new FP nearValue_Melee = 3;

		private new FP farValuee_Melee = 6.5;

		private new FP nearValue_Range = 4;

		private new FP farValuee_Range = 8;

		private new FP moveForwardDistance = 5;

		private new FP moveForwardDirection = 10;

		private new FP moveBackwardDistance = 3;

		private new FP moveBackwardRangeOffset = 4.5;

		private new FP moveBackwardDirection = 15;

		private new FP moveOrbitalDistance = 5;

		private new FP moveOrbitalDirection = 180;

		public Skill_AlertMove()
		{
			base.nearValue_Melee = nearValue_Melee;
			base.farValuee_Melee = farValuee_Melee;
			base.movementMaXRuningTime = movementMaXRuningTime;
			base.nearValue_Range = nearValue_Range;
			base.farValuee_Range = farValuee_Range;
			base.moveForwardDistance = moveForwardDistance;
			base.moveForwardDirection = moveForwardDirection;
			base.moveBackwardDistance = moveBackwardDistance;
			base.moveBackwardRangeOffset = moveBackwardRangeOffset;
			base.moveBackwardDirection = moveBackwardDirection;
			base.moveOrbitalDistance = moveOrbitalDistance;
			base.moveOrbitalDirection = moveOrbitalDirection;
		}

		protected override void OnSkillEnable()
		{
			Enable();
		}

		protected override void OnSkillDisable()
		{
			Disable();
		}

		protected override IEnumerator DoMainLogic()
		{
			if (MovementCor() != null)
			{
				yield return MovementCor();
			}
		}
	}
	public class Skill_AlertMoveBase : SkillSimpleBase
	{
		private enum MovementType
		{
			close,
			awayFrom,
			orbital
		}

		protected FP nearValue_Melee;

		protected FP farValuee_Melee;

		protected FP movementMaXRuningTime;

		protected FP nearValue_Range;

		protected FP farValuee_Range;

		protected FP moveForwardDistance;

		protected FP moveForwardDirection;

		protected FP moveBackwardDistance;

		protected FP moveBackwardRangeOffset;

		protected FP moveBackwardDirection;

		protected FP moveOrbitalDistance;

		protected FP moveOrbitalDirection;

		private FP moveAcc;

		private LogicEntity target;

		private MovementType movementType;

		private bool hasFinish;

		private int playerATKType;

		private FP nearValue;

		private FP farValue;

		private int orbitalDirection;

		protected void Enable()
		{
			target = GetTarget();
			hasFinish = false;
			playerATKType = GetPlayerJobType((AdventureActor)GetCurrentPlayer());
			moveAcc = _actor.actorInfo.moveAcceleration;
			switch (playerATKType)
			{
			case 1:
				nearValue = ((nearValue_Melee == 0) ? (nearValue = 0.1) : (nearValue = nearValue_Melee));
				farValue = ((farValuee_Melee == 0) ? (farValue = 0.1) : (farValue = farValuee_Melee));
				break;
			case 2:
				nearValue = ((nearValue_Range == 0) ? (nearValue = 0.1) : (nearValue = nearValue_Range));
				farValue = ((farValuee_Range == 0) ? (farValue = 0.1) : (farValue = farValuee_Range));
				break;
			}
		}

		protected void Disable()
		{
			_actor.actorInfo.moveAcceleration = moveAcc;
		}

		protected CoroutineNode MovementCor()
		{
			movementType = GetMoveMentType();
			return movementType switch
			{
				MovementType.close => StartCor(MoveForward()), 
				MovementType.awayFrom => StartCor(MoveBackward()), 
				MovementType.orbital => StartCor(MoveOrbital()), 
				_ => null, 
			};
		}

		protected virtual IEnumerator MoveForward()
		{
			yield return BeginLookAt(target, 0.1, 1800);
			yield return StartCor(MovementUpdate());
		}

		protected virtual IEnumerator MoveBackward()
		{
			yield return BeginLookAt(target, 0.1, 1800);
			yield return StartCor(MovementUpdate());
		}

		protected virtual IEnumerator MoveOrbital()
		{
			yield return BeginLookAt(target, 0.1, 1800);
			yield return StartCor(MovementUpdate());
		}

		protected virtual IEnumerator MovementUpdate()
		{
			bool loopCondition = !hasFinish;
			_actor.actorInfo.moveAcceleration = 40;
			FP updateInterval = 0.05;
			switch (movementType)
			{
			case MovementType.close:
			{
				CoroutineNode DRITConsitionCor = StartCor(DirectionCondition());
				CoroutineNode DISTConsitionCor = StartCor(DistanceCondition());
				CoroutineNode RuningTimeConsitionCor = StartCor(RuningTimeCondition());
				while (loopCondition)
				{
					TSVector2 entityPosition = GetEntityPosition(target);
					MoveToPosition(entityPosition, 0.1, AdventureActor.MovementMode.Walk, 2f);
					loopCondition = !hasFinish;
					yield return WaitTime(updateInterval);
				}
				StopMove();
				StopCor(DRITConsitionCor);
				StopCor(DISTConsitionCor);
				StopCor(RuningTimeConsitionCor);
				break;
			}
			case MovementType.awayFrom:
			{
				TransLocalPosToWorldPos(GetPosition(), GetPosition() - GetEntityPosition(target), new TSVector2(0, 10));
				CoroutineNode DISTConsitionCor = StartCor(DistanceCondition());
				CoroutineNode DRITConsitionCor = StartCor(DirectionCondition());
				CoroutineNode RuningTimeConsitionCor = StartCor(RuningTimeCondition());
				while (loopCondition)
				{
					AimAtPosition(GetEntityPosition(target), 100f);
					TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetPosition() - GetEntityPosition(target), new TSVector2(0, 10));
					MoveToPosition(position, 0.1, AdventureActor.MovementMode.Walk, 2f);
					loopCondition = !hasFinish;
					yield return WaitTime(updateInterval);
				}
				CancelAim();
				StopMove();
				StopCor(DISTConsitionCor);
				StopCor(DRITConsitionCor);
				StopCor(RuningTimeConsitionCor);
				break;
			}
			case MovementType.orbital:
			{
				orbitalDirection = ((GetRandomValue(0, 1) > 0.5) ? 1 : (-1));
				CoroutineNode DISTConsitionCor = StartCor(DistanceCondition());
				CoroutineNode RuningTimeConsitionCor = StartCor(RuningTimeCondition());
				while (loopCondition)
				{
					AimAtPosition(GetEntityPosition(target));
					TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetEntityPosition(target) - GetPosition(), new TSVector2(10 * orbitalDirection, 0));
					MoveToPosition(position, 0.1, AdventureActor.MovementMode.Walk, 2f);
					loopCondition = !hasFinish;
					yield return WaitTime(updateInterval);
				}
				CancelAim();
				StopMove();
				StopCor(DISTConsitionCor);
				StopCor(RuningTimeConsitionCor);
				break;
			}
			}
		}

		protected virtual IEnumerator DistanceCondition()
		{
			_ = _actor.actorInfo.walkSpeed;
			bool result = true;
			FP interval = 0.05;
			switch (movementType)
			{
			case MovementType.close:
			{
				FP movementDistance = moveForwardDistance;
				while (result)
				{
					yield return WaitTime(interval);
					movementDistance -= _actor.actorInfo.walkSpeed * interval;
					TSVector2 position2 = GetPosition();
					TSVector2 entityPosition2 = GetEntityPosition(target);
					if (Distance(position2, entityPosition2) <= nearValue)
					{
						result = false;
					}
					else if (0 >= movementDistance)
					{
						result = false;
					}
				}
				break;
			}
			case MovementType.awayFrom:
			{
				FP fP2;
				if (GetPlayerJobType((AdventureActor)GetCurrentPlayer()) != 1)
				{
					FP fP = moveBackwardDistance + moveBackwardRangeOffset;
					fP2 = fP;
				}
				else
				{
					FP fP = moveBackwardDistance;
					fP2 = fP;
				}
				FP movementDistance = fP2;
				while (result)
				{
					yield return WaitTime(interval);
					movementDistance -= _actor.actorInfo.walkSpeed * interval;
					TSVector2 position3 = GetPosition();
					TSVector2 entityPosition3 = GetEntityPosition(target);
					if (Distance(position3, entityPosition3) >= nearValue)
					{
						result = false;
					}
				}
				break;
			}
			case MovementType.orbital:
			{
				FP movementDistance = moveOrbitalDistance;
				while (result)
				{
					yield return WaitTime(interval);
					movementDistance -= _actor.actorInfo.walkSpeed * interval;
					TSVector2 position = GetPosition();
					TSVector2 entityPosition = GetEntityPosition(target);
					if (0 >= movementDistance)
					{
						result = false;
					}
					else if (Distance(position, entityPosition) <= nearValue * 0.8)
					{
						result = false;
					}
				}
				break;
			}
			}
			hasFinish = true;
		}

		protected virtual IEnumerator DirectionCondition()
		{
			bool result = true;
			FP interval = 0.05;
			switch (movementType)
			{
			case MovementType.close:
				while (result)
				{
					yield return WaitTime(interval);
					TSVector2 to = GetEntityPosition(target) - GetPosition();
					TSVector2 forward = GetForward();
					if (AngleBetween2TSVector(forward, to, signed: false) > moveForwardDirection)
					{
						result = false;
					}
				}
				break;
			case MovementType.awayFrom:
				while (result)
				{
					yield return WaitTime(interval);
					TSVector2 to = GetEntityPosition(target) - GetPosition();
					TSVector2 forward = GetForward();
					if (AngleBetween2TSVector(forward, to, signed: false) > moveBackwardDirection)
					{
						result = false;
					}
				}
				break;
			case MovementType.orbital:
				while (result)
				{
					yield return WaitTime(interval);
					TSVector2 to = GetEntityPosition(target) - GetPosition();
					TSVector2 forward = GetForward();
					if (AngleBetween2TSVector(forward, to, signed: false) > moveOrbitalDirection)
					{
						result = false;
					}
				}
				break;
			}
			hasFinish = true;
		}

		protected virtual IEnumerator RuningTimeCondition()
		{
			bool result = true;
			FP interval = 0.05;
			FP time = 0;
			while (result)
			{
				yield return WaitTime(interval);
				time += interval;
				if (time > movementMaXRuningTime)
				{
					result = false;
				}
			}
			hasFinish = true;
		}

		private MovementType GetMoveMentType()
		{
			TSVector2 position = GetPosition();
			TSVector2 entityPosition = GetEntityPosition(target);
			FP fP = Distance(position, entityPosition);
			if (fP > farValue)
			{
				return MovementType.close;
			}
			if (farValue > fP && fP > nearValue)
			{
				return MovementType.orbital;
			}
			return MovementType.awayFrom;
		}

		private LogicEntity GetTarget()
		{
			LogicEntity logicEntity = null;
			if (CheckTargetIsValid(GetAttackTarget(isUpToDate: true)))
			{
				return GetAttackTarget(isUpToDate: true);
			}
			return GetCurrentPlayer();
		}
	}
	public class Skill_CommonWander_Far : SkillSimpleBase
	{
		private static readonly FP OutsideDiameter_Common = 12;

		private static readonly FP InsideDiameter_Common = 7;

		private static readonly FP CentralSectorAngle_Common = 10;

		private static readonly FP SideSectorAngle_Common = 10;

		private static readonly FP CentralSectorAngle_Near = 20;

		private static readonly FP SideSectorAngle_Near = 30;

		private static readonly FP SectorAngle_Common = 40;

		private static readonly FP SectorAngle_Near = 150;

		private DeterministicShape CentralAnnularSector;

		private DeterministicShape ClockwiseAnnularSector;

		private DeterministicShape AnticlockwiseAnnularSector;

		private DeterministicShape BackupAnnularSector;

		private DeterministicShape ChosenAnnularSector;

		private TSVector2 SectorDirection;

		private FP CentralSectorRotation;

		private FP ClockwiseSectorRotation;

		private FP AnticlockwiseSectorRotation;

		private FP OutsideDiameter;

		private FP InsideDiameter;

		private FP CentralSectorAngle;

		private FP SideSectorAngle;

		private FP SectorAngle;

		private TSVector2 TargetPosition;

		private TSVector2 NextPosition;

		private string WanderMode;

		private string LastWanderArea;

		private CoroutineNode AimCor;

		protected override void OnSkillEnable()
		{
			SetLogicTagToggleValue(_actor, "ExecutingCanBreakSkill", value: true);
			GetNextPoint();
			OutsideDiameter = OutsideDiameter_Common;
			InsideDiameter = InsideDiameter_Common;
			CentralSectorAngle = CentralSectorAngle_Common;
			SideSectorAngle = SideSectorAngle_Common;
			SectorAngle = SectorAngle_Common;
		}

		protected override void OnSkillDisable()
		{
			StopCor(AimCor);
			StopMove();
			CancelAim();
		}

		protected override IEnumerator DoMainLogic()
		{
			StartCor(ref AimCor, KeepAiming());
			while (true)
			{
				MoveToPosition(NextPosition, 0.1, AdventureActor.MovementMode.Walk);
				yield return WaitMoveStatus();
				yield return WaitTime(GetRandomValue(3, 4));
				GetNextPoint();
			}
		}

		private void GetNextPoint()
		{
			TargetPosition = GetEntityPosition(GetAttackTarget(isUpToDate: true));
			SectorDirection = GetPosition() - TargetPosition;
			if (Distance(GetPosition(), TargetPosition) > OutsideDiameter_Common)
			{
				WanderMode = "ComeCloser";
			}
			else if (Distance(GetPosition(), TargetPosition) < InsideDiameter_Common)
			{
				WanderMode = "StayAway";
				if (GetRandomValue(0, 1) < 0.7)
				{
					OutsideDiameter = Distance(GetPosition(), TargetPosition) + 2;
					InsideDiameter = Distance(GetPosition(), TargetPosition) + 1;
					CentralSectorAngle = CentralSectorAngle_Near;
					SideSectorAngle = SideSectorAngle_Near;
					SectorAngle = SectorAngle_Near;
				}
			}
			else
			{
				WanderMode = "KeepDistance";
			}
			CentralSectorRotation = GetTSVectToAngle(SectorDirection, 0);
			ClockwiseSectorRotation = GetTSVectToAngle(SectorDirection, -(SectorAngle / 2 - SideSectorAngle / 2));
			AnticlockwiseSectorRotation = GetTSVectToAngle(SectorDirection, SectorAngle / 2 - SideSectorAngle / 2);
			TSVector2 targetPosition = TargetPosition;
			FP outsideDiameter = OutsideDiameter;
			FP insideDiameter = InsideDiameter;
			FP centralSectorAngle = CentralSectorAngle;
			FP centralSectorRotation = CentralSectorRotation;
			CentralAnnularSector = GetShapeData(DeterministicShape.ShapeType.Fan, targetPosition, default(FP), default(FP), outsideDiameter, insideDiameter, centralSectorAngle, centralSectorRotation);
			TSVector2 targetPosition2 = TargetPosition;
			centralSectorRotation = OutsideDiameter;
			centralSectorAngle = InsideDiameter;
			insideDiameter = SideSectorAngle;
			outsideDiameter = ClockwiseSectorRotation;
			ClockwiseAnnularSector = GetShapeData(DeterministicShape.ShapeType.Fan, targetPosition2, default(FP), default(FP), centralSectorRotation, centralSectorAngle, insideDiameter, outsideDiameter);
			TSVector2 targetPosition3 = TargetPosition;
			outsideDiameter = OutsideDiameter;
			insideDiameter = InsideDiameter;
			centralSectorAngle = SideSectorAngle;
			centralSectorRotation = AnticlockwiseSectorRotation;
			AnticlockwiseAnnularSector = GetShapeData(DeterministicShape.ShapeType.Fan, targetPosition3, default(FP), default(FP), outsideDiameter, insideDiameter, centralSectorAngle, centralSectorRotation);
			TSVector2 targetPosition4 = TargetPosition;
			centralSectorRotation = OutsideDiameter;
			centralSectorAngle = InsideDiameter;
			insideDiameter = 270;
			outsideDiameter = CentralSectorRotation;
			BackupAnnularSector = GetShapeData(DeterministicShape.ShapeType.Fan, targetPosition4, default(FP), default(FP), centralSectorRotation, centralSectorAngle, insideDiameter, outsideDiameter);
			LastWanderArea = GetLogicTagStringValue(_actor, "LastWanderArea");
			if (WanderMode == "ComeCloser")
			{
				SetLogicTagStringValue(_actor, "LastWanderArea", "CentralSector");
				ChosenAnnularSector = CentralAnnularSector;
			}
			else if (WanderMode == "StayAway")
			{
				if (LastWanderArea == "CentralSector")
				{
					ChosenAnnularSector = GetRandomSector();
				}
				else
				{
					ChosenAnnularSector = CentralAnnularSector;
					SetLogicTagStringValue(_actor, "LastWanderArea", "CentralSector");
				}
			}
			else
			{
				ChosenAnnularSector = GetRandomSector();
			}
			NextPosition = GetShapeRandomPoint(ChosenAnnularSector, _actor, isReachable: true);
			if (NextPosition == TargetPosition)
			{
				ChosenAnnularSector = GetBackupSector();
				NextPosition = GetShapeRandomPoint(ChosenAnnularSector, _actor, isReachable: true);
			}
		}

		private DeterministicShape GetRandomSector()
		{
			if (LastWanderArea == "ClockwiseSector")
			{
				SetLogicTagStringValue(_actor, "LastWanderArea", "AnticlockwiseSector");
				return AnticlockwiseAnnularSector;
			}
			if (LastWanderArea == "AnticlockwiseSector")
			{
				SetLogicTagStringValue(_actor, "LastWanderArea", "ClockwiseSector");
				return ClockwiseAnnularSector;
			}
			if (GetRandomValue(0, 1) >= 0.5)
			{
				SetLogicTagStringValue(_actor, "LastWanderArea", "AnticlockwiseSector");
				return AnticlockwiseAnnularSector;
			}
			SetLogicTagStringValue(_actor, "LastWanderArea", "ClockwiseSector");
			return ClockwiseAnnularSector;
		}

		private DeterministicShape GetBackupSector()
		{
			LastWanderArea = GetLogicTagStringValue(_actor, "LastWanderArea");
			if (LastWanderArea == "CentralSector")
			{
				return BackupAnnularSector;
			}
			if (LastWanderArea == "ClockwiseSector")
			{
				if (TargetPosition != GetShapeRandomPoint(AnticlockwiseAnnularSector, _actor, isReachable: true))
				{
					return AnticlockwiseAnnularSector;
				}
				return BackupAnnularSector;
			}
			if (TargetPosition != GetShapeRandomPoint(AnticlockwiseAnnularSector, _actor, isReachable: true))
			{
				return AnticlockwiseAnnularSector;
			}
			return BackupAnnularSector;
		}

		private IEnumerator KeepAiming()
		{
			LogicEntity Target = GetAttackTarget();
			AimAtTarget(Target, 50f);
			while (true)
			{
				if (!CheckTargetIsValid(Target))
				{
					InterruptSkill();
				}
				if (CalcAngleBetweenSelfAndAttackTarget() > 45)
				{
					CancelAim();
					yield return BeginLookAt(Target, 0, 300);
					AimAtTarget(Target, 50f);
				}
				yield return null;
			}
		}
	}
	public class Skill_CommonWander_Near : SkillSimpleBase
	{
		private static readonly FP OutsideDiameter = 8;

		private static readonly FP InsideDiameter = 4;

		private static readonly FP CentralSectorAngle = 20;

