		private IEnumerator GeneralAttack()
		{
			BeginAttack(NinjutsuIndex, NinjutsuKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator WaitINTR()
		{
			if (skillType == 0)
			{
				yield return WaitTime(5.2);
			}
			else
			{
				yield return WaitTime(0.5);
			}
			StopCor(CheckDash);
		}
	}
	public class Skill_Death : SkillSimpleBase
	{
		private List<LogicEntity> _entities = new List<LogicEntity>();

		protected override void OnSkillEnable()
		{
			_entities.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			_entities.AddRange(GetTargetsByFaction(isFriend: true));
			if (_entities.Count > 0)
			{
				ClearActors(_entities);
			}
			int keyIndex = 0;
			string actionKey = "Death";
			BeginAttack(keyIndex, actionKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			SendDeclareDeadEvent();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return WaitTime(1);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == 0 && eventName == "HYDeath")
			{
				TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, -1));
				PlayEffect("fx_70022_base_Kagebunsin_Flash", 1f, default(FP), position, default(FP), 2.5f);
				SetHideModelEnable();
			}
		}
	}
	public class Skill_Flash : SkillSimpleBase
	{
		private static readonly int FlashIndex = 0;

		private static readonly string FlashKey = "Flash";

		private static readonly string Fx_Flash = "fx_70022_loop_Substitute_StandIn";

		private static long FxIndex;

		private static readonly FP Wait = 0.75;

		private static TSVector2 SelfPOS;

		private static TSVector2 TargetPOS;

		private static LogicEntity Target;

		private static readonly FP RadiusLimit = 8;

		private static readonly TSVector2 ZeroPOS = new TSVector2(0, 0);

		private static TSVector2 TeleportPOS;

		protected override IEnumerator DoMainLogic()
		{
			StartCor(ControlledImmunity());
			BeginAttack(FlashIndex, FlashKey, flushInputedKeys: true, forceInterruptAttack: true);
			SetUnparalleledEnable();
			SetSearchedImmunityEnable();
			SetCloseBlockEnable();
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			FxIndex = PlayEffect(Fx_Flash, 1f, default(FP), GetPosition(), GetTSVectToAngle(GetForward(), 0));
			yield return WaitTime(0.4);
			SelfPOS = GetPosition();
			Target = GetCurrentPlayer();
			for (int i = 0; i < 20; i++)
			{
				TeleportPOS = GetShapeRandomPoint(GetShapeData(DeterministicShape.ShapeType.Circle, ZeroPOS, default(FP), default(FP), RadiusLimit, 0), _actor, isReachable: true);
				TargetPOS = GetEntityPosition(Target);
				if (Distance(TeleportPOS, TargetPOS) >= 7)
				{
					Teleport(TeleportPOS);
					break;
				}
				if (i == 19)
				{
					Teleport(TeleportPOS);
					break;
				}
			}
			yield return WaitTime(Wait - 0.4);
			SetInvincibleDisable();
			SetSearchedImmunityDisable();
			SetCloseBlockDisable();
			CancelAttack();
			BeginLookAt_NotWait(Target, 0.3, 999);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopEffect(FxIndex);
			StopLookAt();
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
	public class Skill_Illusion_BFan : SkillSimpleBase
	{
		private static readonly string FlashFx = "fx_70022_base_Kagebunsin_Flash";

		private static TSVector2 TargetPOS;

		private static List<TSVector2> SummonPOS = new List<TSVector2>
		{
