		}
	}
	public class Skill_T_BassDash : SkillSimpleBase
	{
		private static readonly string WarningFx_Actor = "fx_common_base_charge_fire_actor";

		private static string LineFx = "fx_70022_laser_STrow";

		private static List<long> LineFxList = new List<long>();

		private static readonly int ActionIndex = 0;

		private static readonly string ActionKey = "Dash";

		private static readonly string DashBaseFx = "fx_70022_loop_Dodge_Shukuchi";

		private static long DashBaseIndex;

		private static int DashIndex = 10;

		private static TSVector2 Direction;

		private static FP Speed;

		private static FP DIST;

		private static FP AngleLimit = 999;

		private static LogicEntity Target;

		private static TSVector2 TargetPOS = default(TSVector2);

		private static TSVector2 SelfPOS = default(TSVector2);

		private static readonly int FlashIndex = 0;

		private static readonly string FlashKey = "Flash";

		private static readonly string Fx_Flash = "fx_70022_loop_Substitute_StandIn";

		private static long FxIndex;

		private static readonly FP Wait = 1;

		private static readonly FP RadiusLimit = 8;

		private static readonly TSVector2 ZeroPOS = new TSVector2(0, 0);

		private static TSVector2 TeleportPOS;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			LineFxList.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			StartCor(ControlledImmunity());
			SelfPOS = GetPosition();
			Target = GetCurrentPlayer();
			if (Distance(SelfPOS, GetEntityPosition(Target)) <= 5)
			{
				yield return StartCor(FlashMove());
			}
			BeginLookAtByPos_NotWait(GetEntityPosition(GetCurrentPlayer()), 0.1, 9999);
			BeginAttack(ActionIndex, ActionKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.4);
			TargetPOS = GetEntityPosition(Target);
			SelfPOS = GetPosition();
			Direction = TargetPOS - SelfPOS;
			DIST = Distance(TargetPOS, SelfPOS) + 7;
			LineFxList.Add(PlayLinkEffect(LineFx, useCustomSource: true, null, SelfPOS, 1, null, TransLocalPosToWorldPos(TargetPOS, Direction, new TSVector2(0, DIST)), 0, breakWhenLostSourceOrTarget: false, 1f, actorScale: true));
			yield return WaitTime(0.3);
			PlayEffect(WarningFx_Actor, 1f, 1.5, GetPosition(), default(FP), 1.4f);
			yield return WaitTime(0.4);
			StopEffect(LineFxList[0]);
			CancelAttack();
			Speed = DIST / 0.25;
			BeginDash(DashIndex, Direction, Speed, DIST, AngleLimit, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false);
			DashBaseIndex = PlayEffect(DashBaseFx);
			yield return WaitDashFinish();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator FlashMove()
		{
			BeginAttack(FlashIndex, FlashKey, flushInputedKeys: true, forceInterruptAttack: true);
			SetUnparalleledEnable();
			SetCloseBlockEnable();
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			FxIndex = PlayEffect(Fx_Flash, 1f, default(FP), GetPosition(), GetTSVectToAngle(GetForward(), 0));
			yield return WaitTime(0.4);
			SelfPOS = GetPosition();
			Target = GetCurrentPlayer();
			for (int i = 0; i < 20; i++)
			{
				TeleportPOS = GetShapeRandomPoint(GetShapeData(DeterministicShape.ShapeType.Circle, ZeroPOS, default(FP), default(FP), RadiusLimit, 0), _actor, isReachable: true);
				TargetPOS = GetEntityPosition(Target);
				if (Distance(TeleportPOS, TargetPOS) >= 7)
				{
					Teleport(TeleportPOS);
					break;
				}
				if (i == 19)
				{
					Teleport(TeleportPOS);
					break;
				}
			}
			yield return WaitTime(Wait - 0.4);
			SetUnparalleledDisable();
			SetCloseBlockDisable();
			CancelAttack();
			BeginLookAt_NotWait(Target, 0.3, 999);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopEffect(FxIndex);
			StopLookAt();
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
