	public class Skill_T_DashBunshin : SkillSimpleBase
	{
		private bool IsNormalEnd;

		private static readonly string FlashFx = "fx_70022_base_Kagebunsin_Flash";

		private static readonly string ControlFx = "fx_70022_bullet_Kagebunsin_Control";

		private static List<long> ControlFxList = new List<long>();

		private static readonly string ControllineFx = "fx_70022_loop_Kagebunsin_Control_line";

		private static List<long> ControllineFxList = new List<long>();

		private static readonly string ClockFx = "fx_70022_ground_Kagebunsin_Clock";

		private static List<long> ClockFxList = new List<long>();

		private static readonly string ActiveFx = "fx_70022_loop_Kagebunsin_Active";

		private static List<long> ActiveFxList = new List<long>();

		private static TSVector2 SelfPOS;

		private static TSVector2 TargetPOS;

		private static int MonsterID = 1;

		private static List<LogicEntity> SummonList = new List<LogicEntity>();

		private static List<TSVector2> SummonPOS = new List<TSVector2>();

		private static List<TSVector2> SummonPOS01 = new List<TSVector2>
		{
			new TSVector2(-7.5, 7.5),
			new TSVector2(7.5, -7.5)
		};

		private static List<TSVector2> SummonPOS02 = new List<TSVector2>
		{
			new TSVector2(7.5, 7.5),
			new TSVector2(-7.5, -7.5)
		};

		private static int SkillBranch;

		private static readonly string WarningFx_Actor = "fx_common_base_charge_fire_actor";

		private static int NinjutsuIndex = 0;

		private static string NinjutsuKey = "Ninjutsu_G";

		private static int NinjutsuIndex_Loop = 1;

		private static string NinjutsuKey_Loop = "Nijutsu_Loop";

		private static long WarningFxIndex_Cir;

		private static readonly string WarningFX_Cir = "fx_70022_loop_warning_Skill01";

		private static readonly string BaseFX_Cir = "fx_70022_base_Skill01_Start";

		private static readonly string DamageFx_Cir = "fx_70022_atk_Skill01";

		private static readonly string Dot_Cir = "Cir_atk";

		private static long WarningFxIndex_Ring;

		private static readonly string WarningFX_Ring = "fx_70022_loop_warning_Skill02";

		private static readonly string BaseFX_Ring = "fx_70022_base_Skill02_Start";

		private static readonly string DamageFx_Ring = "fx_70022_atk_Skill02";

		private static readonly string Dot_Ring = "Ring_atk";

		private static long WarningFxIndex_Fan;

		private static readonly string WarningFX_Fan = "fx_70022_loop_warning_Skill03";

		private static readonly string BaseFX_Fan = "fx_70022_base_Skill03_Start";

		private static readonly string DamageFx_Fan = "fx_70022_atk_Skill03";

		private static readonly string Dot_Fan = "Fan_atk";

		private static string LineFx = "fx_70022_laser_STrow";

		private static List<long> LineFxList = new List<long>();

		private static long IndexFxDogde;

		private static readonly string Fx_Dogde = "fx_70022_loop_Dodge_Shukuchi";

		private static readonly TSVector2 ZeroPOS = new TSVector2(0, 0);

		private static readonly int ActionIndex = 0;

		private static readonly string ActionKey = "Dash";

		private static readonly int JumpIndex = 1;

		private static readonly string JumpKey = "Jump";

		private static readonly int DashLoopIndex = 2;

		private static readonly string DashLoopKey = "DashLoop";

		private static int DashIndex = 10;

		private static TSVector2 Direction;

		private static FP Speed;

		private static FP DIST;

		private static FP AngleLimit = 999;

		private static bool Select;

		private static List<TSVector2> DashPOS = new List<TSVector2>();

		protected override void OnSkillEnable()
		{
			SkillBranch = 0;
			SummonList.Clear();
			ControlFxList.Clear();
			ControllineFxList.Clear();
			ClockFxList.Clear();
			ActiveFxList.Clear();
			SummonPOS.Clear();
			Select = false;
			DashPOS.Clear();
			LineFxList.Clear();
		}

		protected override void OnSkillDisable()
		{
			SummonList.Clear();
			ControlFxList.Clear();
			ControllineFxList.Clear();
			ClockFxList.Clear();
			DashPOS.Clear();
			LineFxList.Clear();
			if (!IsNormalEnd)
			{
				List<LogicEntity> targetsByFaction = GetTargetsByFaction(isFriend: true);
				if (targetsByFaction.Count > 0)
				{
					for (int i = 0; i < targetsByFaction.Count; i++)
					{
						PlayEffect(FlashFx, 1f, default(FP), GetEntityPosition(targetsByFaction[i]), default(FP), 2.2f);
					}
					ClearActors(targetsByFaction);
				}
				if (ActiveFxList.Count > 0)
				{
					for (int j = 0; j < ActiveFxList.Count; j++)
					{
						StopEffect(ActiveFxList[j]);
					}
				}
			}
			ActiveFxList.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			StartCor(ControlledImmunity());
			yield return StartCor(Summon_One());
			yield return StartCor(Control());
			yield return StartCor(Link());
			yield return StartCor(Attack_Master());
			yield return StartCor(Tag_Bunsin());
			IsNormalEnd = true;
			yield return StartCor(MultipleDash());
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator Summon_One()
		{
			BeginAttack(NinjutsuIndex, NinjutsuKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			if ((int)(long)GetRandomValue(0, 1.5, isInt: true) == 0)
			{
				SummonPOS.AddRange(SummonPOS01);
			}
			else
			{
				SummonPOS.AddRange(SummonPOS02);
			}
			for (int i = 0; i < SummonPOS.Count; i++)
			{
				SummonTeammate(MonsterID, SummonPOS[i], new TSVector2(0, 0) - SummonPOS[i]);
				PlayEffect(FlashFx, 1f, default(FP), SummonPOS[i], default(FP), 2.2f);
			}
			yield return WaitTime(0.1);
			SummonList.AddRange(GetTargetByTeammateIndex(MonsterID));
			for (int j = 0; j < SummonList.Count; j++)
			{
				SetLogicTagToggleValue(SummonList[j], "release", value: false);
			}
		}

		protected IEnumerator Control()
		{
			SelfPOS = GetPosition();
			for (int i = 0; i < SummonList.Count; i++)
			{
				TargetPOS = GetEntityPosition(SummonList[i]);
				ControlFxList.Add(PlayLinkEffect(ControlFx, useCustomSource: true, null, SelfPOS, default(FP), null, TargetPOS, default(FP), breakWhenLostSourceOrTarget: true, 1f, actorScale: true));
			}
			yield return WaitTime(0.25);
			for (int j = 0; j < SummonList.Count; j++)
			{
				TargetPOS = GetEntityPosition(SummonList[j]);
				ControllineFxList.Add(PlayLinkEffect(ControllineFx, useCustomSource: true, null, SelfPOS, 0.3, null, TargetPOS, default(FP), breakWhenLostSourceOrTarget: true, 1f, actorScale: true));
			}
			yield return WaitTime(0.4);
		}

		protected IEnumerator Attack_Master()
		{
			SkillBranch = 1;
			switch (SkillBranch)
			{
			case 0:
			{
				yield return StartCor(CircleAOE());
				for (int k = 0; k < SummonList.Count; k++)
				{
					SetLogicTagFpValue(SummonList[k], "bunsinSkill", 0);
				}
				break;
			}
			case 1:
			{
				yield return StartCor(RingAOE());
				for (int j = 0; j < SummonList.Count; j++)
				{
					SetLogicTagFpValue(SummonList[j], "bunsinSkill", 1);
				}
				break;
			}
			default:
			{
				yield return StartCor(CircleAOE());
				for (int i = 0; i < SummonList.Count; i++)
				{
					SetLogicTagFpValue(SummonList[i], "bunsinSkill", 0);
				}
				break;
			}
			}
			yield return WaitTime(0.4);
		}

		protected IEnumerator Link()
		{
			for (int i = 0; i < SummonList.Count; i++)
			{
				TargetPOS = GetEntityPosition(SummonList[i]);
				ActiveFxList.Add(PlayEffect(ActiveFx, 1f, 3.7, TargetPOS, default(FP), 1.2f, actorScale: true));
			}
			yield return null;
		}

		protected IEnumerator Tag_Bunsin()
		{
			for (int i = 0; i < SummonList.Count; i++)
			{
				StopEffect(ControlFxList[i]);
				StopEffect(ControllineFxList[i]);
				StopEffect(ActiveFxList[i]);
				TargetPOS = GetEntityPosition(SummonList[i]);
				ClockFxList.Add(PlayEffect(ClockFx, 0.45f, default(FP), TargetPOS, default(FP), 1.5f, actorScale: true));
				SetLogicTagToggleValue(SummonList[i], "release", value: true);
			}
			yield return null;
		}

		protected IEnumerator CircleAOE()
		{
			BeginAttack(NinjutsuIndex_Loop, NinjutsuKey_Loop, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.7);
			WarningFxIndex_Cir = PlayEffect(WarningFX_Cir, 1f, 0.3, GetPosition());
			yield return WaitTime(0.7);
			PlayEffect(BaseFX_Cir, 1f, default(FP), GetPosition());
			yield return WaitTime(0.6);
			PlayEffect(WarningFx_Actor, 1f, 2, GetPosition(), default(FP), 1.4f);
			yield return WaitTime(0.6);
			PlayAreaEffect(Dot_Cir, GetPosition(), GetRotation());
			PlayEffect(DamageFx_Cir, 1f, default(FP), GetPosition());
			StopEffect(WarningFxIndex_Cir);
			yield return WaitTime(0.2);
			yield return WaitTime(0.4);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator RingAOE()
		{
			BeginAttack(NinjutsuIndex_Loop, NinjutsuKey_Loop, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.7);
			WarningFxIndex_Ring = PlayEffect(WarningFX_Ring, 1f, 0.3, GetPosition());
			yield return WaitTime(0.7);
			PlayEffect(BaseFX_Ring, 1f, default(FP), GetPosition());
			yield return WaitTime(0.6);
			PlayEffect(WarningFx_Actor, 1f, 2, GetPosition(), default(FP), 1.4f);
			yield return WaitTime(0.6);
			PlayAreaEffect(Dot_Ring, GetPosition(), GetRotation());
			PlayEffect(DamageFx_Ring, 1f, default(FP), GetPosition());
			StopEffect(WarningFxIndex_Ring);
			yield return WaitTime(0.2);
			yield return WaitTime(0.4);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator DashOnce()
		{
			BeginLookAtByPos_NotWait(TargetPOS, 0.05, 9999);
			SelfPOS = GetPosition();
			Direction = TargetPOS - SelfPOS;
			DIST = Distance(TargetPOS, SelfPOS);
			Speed = DIST / 0.25;
			yield return WaitTime(0.08);
			BeginDash(DashIndex, Direction, Speed, DIST, AngleLimit, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false);
			yield return WaitDashFinish();
			yield return WaitTime(0.15);
		}

		protected IEnumerator BackPOS()
		{
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			SetSearchedImmunityEnable();
			SetUnparalleledEnable();
			BeginAttack(JumpIndex, JumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			Teleport(ZeroPOS);
			yield return WaitTime(0.8);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetSearchedImmunityDisable();
			SetInvincibleDisable();
		}

		protected IEnumerator MultipleDash()
		{
			int i = 0;
			int num = 1;
			for (; i < 8; i++)
			{
				if (!Select)
				{
					if (num == 0)
					{
						DashPOS.Add(new TSVector2(GetRandomValue(-7, 7), 10));
						num++;
					}
					else
					{
						DashPOS.Add(new TSVector2(GetRandomValue(-7, 7), -10));
						num = 0;
						Select = true;
					}
				}
				else if (num == 0)
				{
					DashPOS.Add(new TSVector2(10, GetRandomValue(-7, 7)));
					num++;
				}
				else
				{
					DashPOS.Add(new TSVector2(-10, GetRandomValue(-7, 7)));
					num = 0;
					Select = false;
				}
			}
			BeginAttack(ActionIndex, ActionKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAtByPos_NotWait(new TSVector2(0, -5), 0.1, 9999);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			for (int j = 0; j < DashPOS.Count; j++)
			{
				if (j == 0)
				{
					LineFxList.Add(PlayLinkEffect(LineFx, useCustomSource: true, null, GetPosition(), 0.5, null, DashPOS[0], 0.5, breakWhenLostSourceOrTarget: false, 1f, actorScale: true));
				}
				else
				{
					LineFxList.Add(PlayLinkEffect(LineFx, useCustomSource: true, null, DashPOS[j - 1], 0.5, null, DashPOS[j], 0.5, breakWhenLostSourceOrTarget: false, 1f, actorScale: true));
				}
			}
			yield return WaitTime(0.5);
			PlayEffect(WarningFx_Actor, 1f, 1.5, GetPosition(), default(FP), 1.4f);
			yield return WaitTime(0.4);
			SetSearchedImmunityEnable();
			IndexFxDogde = PlayEffect(Fx_Dogde);
			for (int k = 0; k < DashPOS.Count; k++)
			{
				TargetPOS = DashPOS[k];
				if (k == 0)
				{
					CancelAttack();
				}
				else
				{
					BeginAttack(DashLoopIndex, DashLoopKey, flushInputedKeys: true, forceInterruptAttack: true);
				}
				yield return StartCor(DashOnce());
			}
			StopEffect(IndexFxDogde);
			for (int l = 0; l < LineFxList.Count; l++)
			{
				StopEffect(LineFxList[l]);
			}
			SetSearchedImmunityDisable();
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
	public class Skill_T_Illusion : SkillSimpleBase
	{
		private bool IsNormalEnd;

		private static long ScreenIndex;

		private static string ScreenFx = "fx_70022_loop_Skill04_screen";

		private static readonly TSVector2 ZeroPOS = new TSVector2(0, 0);

		private static readonly string FlashFx = "fx_70022_base_Kagebunsin_Flash";

		private static int NinjutsuIndex = 0;

		private static string NinjutsuKey = "Ninjutsu_G";

		private static readonly int JumpIndex = 1;

		private static readonly string JumpKey = "Jump";

		private static List<TSVector2> SummonPOS = new List<TSVector2>();

		private static int MonsterID01 = 2;

		private static int MonsterID02 = 3;

		private static List<LogicEntity> SummonList = new List<LogicEntity>();

		private static TSVector2 TargetPOS;

		private static List<TSVector2> SummonPOS02 = new List<TSVector2>
		{
			new TSVector2(0, 10),
			new TSVector2(10, 0),
			new TSVector2(0, -10),
			new TSVector2(-10, 0)
		};

		private static List<TSVector2> SummonPOS01 = new List<TSVector2>
		{
			new TSVector2(-3, 0),
			new TSVector2(3, 0)
		};

		private static int numb;

		private static LogicEntity Target;

		private static TSVector2 SelfPOS;

		private static FP DIST;

		private static bool StateSwitch;

		private static FP CheckINTR = 0.2;

		private static CoroutineNode Check;

		private static FP HideDuration = 6;

		private static DeterministicShape DamageShape_Fan;

		private static DeterministicShape DamageShape_Rectangle;

		private static TSVector2 POS_Fan;

		private static TSVector2 POS_Rectangle;

		private static FP Width_Rectangle = 22;

		private static FP Length_Rectangle = 17;

		private static FP Radius_Fan = 6;

		private static FP InnerRadius_Fan = 0;

		private static FP Angle_Fan = 90;

		private static FP Rotation_Fan = default(FP);

		private static FP Rotation_Rectangle = default(FP);

		private static HitFeatureData HitData;

		private static HitFeatureData HitfeatureData;

		private static FP HitSrenth = 4;

		private static int hitDamegeID = 70022001;

		private static FP damageimmuneDuration = 0;

		private static string hittedEffect = "fx_70022_hit_Acition";

		private static readonly string AtkFx = "fx_70022_loop_Skill04";

		private static long AtkFxIndex;

		private static bool MoveSwitch;

		protected override void OnSkillEnable()
		{
			AttackHintHide();
		}

		protected override void OnSkillDisable()
		{
			AttackHintShow();
			if (IsNormalEnd)
			{
				return;
			}
			List<LogicEntity> targetsByFaction = GetTargetsByFaction(isFriend: true);
			if (targetsByFaction.Count > 0)
			{
				for (int i = 0; i < targetsByFaction.Count; i++)
				{
					PlayEffect(FlashFx, 1f, default(FP), GetEntityPosition(targetsByFaction[i]), default(FP), 2.2f);
				}
				ClearActors(targetsByFaction);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			StartCor(ControlledImmunity());
			SetLogicTagToggleValue(_actor, "SkillTag_Illusion", value: true);
			SetSearchedImmunityEnable();
			SetUnparalleledEnable();
			yield return StartCor(BackPOS());
			SetSearchedImmunityDisable();
			SetInvincibleDisable();
			yield return StartCor(Summon());
			yield return WaitTime(0.7);
			ScreenIndex = PlayEffect(ScreenFx);
			yield return WaitTime(0.3);
			SetUnparalleledEnable();
			yield return StartCor(GotoPOS());
			Check = StartCor(CheckTarget());
			yield return WaitTime(HideDuration);
			StopCor(Check);
			SetHideModelDisable();
			SetHideOutDisable();
			for (int i = 0; i < SummonList.Count; i++)
			{
				SetLogicTagToggleValue(SummonList[i], "Attack", value: true);
			}
			yield return WaitTime(1.5);
			yield return StartCor(Attack());
			yield return WaitTime(1);
			StopEffect(ScreenIndex);
			yield return WaitTime(0.7);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			IsNormalEnd = true;
		}

		protected IEnumerator BackPOS()
		{
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			BeginAttack(JumpIndex, JumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			Teleport(ZeroPOS);
			BeginLookAtByPos_NotWait(new TSVector2(0, -10), 0.2, 999);
			yield return WaitTime(0.5);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator Summon()
		{
			BeginAttack(NinjutsuIndex, NinjutsuKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayEffect(FlashFx, 1f, default(FP), SummonPOS01[0], default(FP), 2.2f);
			SummonTeammate(MonsterID01, SummonPOS01[0], GetForward());
			PlayEffect(FlashFx, 1f, default(FP), SummonPOS01[1], default(FP), 2.2f);
			SummonTeammate(MonsterID02, SummonPOS01[1], GetForward());
			yield return WaitTime(0.1);
			SummonList.AddRange(GetTargetByTeammateIndex(MonsterID01));
			SummonList.AddRange(GetTargetByTeammateIndex(MonsterID02));
		}

		protected IEnumerator GotoPOS()
		{
			for (int i = 0; i < SummonList.Count; i++)
			{
				SetLogicTagToggleValue(SummonList[i], "MoveSwitch", value: true);
			}
			PlayEffect(FlashFx, 1f, default(FP), GetPosition(), default(FP), 2.2f);
			yield return WaitTime(0.1);
			numb = (int)(long)GetRandomValue(0, 3.5, isInt: true);
			switch (numb)
			{
			case 0:
			{
				TargetPOS = SummonPOS02[numb];
				for (int m = 0; m < SummonList.Count; m++)
				{
					SetLogicTagFpValue(SummonList[m], "Dnumb", 0);
				}
				break;
			}
			case 1:
			{
				TargetPOS = SummonPOS02[numb];
				for (int k = 0; k < SummonList.Count; k++)
				{
					SetLogicTagFpValue(SummonList[k], "Dnumb", 1);
				}
				break;
			}
			case 2:
			{
				TargetPOS = SummonPOS02[numb];
				for (int l = 0; l < SummonList.Count; l++)
				{
					SetLogicTagFpValue(SummonList[l], "Dnumb", 2);
				}
				break;
			}
			case 3:
			{
				TargetPOS = SummonPOS02[numb];
				for (int j = 0; j < SummonList.Count; j++)
				{
					SetLogicTagFpValue(SummonList[j], "Dnumb", 3);
				}
				break;
			}
			}
			Teleport(TargetPOS);
			SetHideModelEnable();
			SetHideOutEnable();
			BeginLookAtByPos_NotWait(ZeroPOS, 0.3, 999);
			yield return WaitTime(2);
		}

		protected IEnumerator CheckTarget()
		{
			Target = GetCurrentPlayer();
			SelfPOS = GetPosition();
			StateSwitch = true;
			for (int i = 0; i < HideDuration / CheckINTR; i++)
			{
				TargetPOS = GetEntityPosition(Target);
				DIST = Distance(SelfPOS, TargetPOS);
				if (DIST <= 3.5 && StateSwitch)
				{
					SetHideModelDisable();
					SetHideOutDisable();
					StateSwitch = false;
				}
				else if (DIST > 3.5 && !StateSwitch)
				{
					SetHideOutEnable();
					yield return WaitTime(0.3);
					SetHideModelEnable();
					StateSwitch = true;
				}
				yield return WaitTime(CheckINTR);
			}
			yield return null;
		}

		protected IEnumerator Attack()
		{
			AtkFxIndex = PlayEffect(AtkFx, 1f, default(FP), new TSVector2(0, 0), GetTSVectToAngle(new TSVector2(0, 0) - GetPosition(), 0));
			SelfPOS = GetPosition();
			POS_Fan = SelfPOS;
			POS_Rectangle = TransLocalPosToWorldPos(SelfPOS, GetForward(), new TSVector2(0, 12.5));
			HitData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 4);
			Rotation_Rectangle = GetRotation();
			DamageShape_Rectangle = GetShapeData(DeterministicShape.ShapeType.Rectangle, POS_Rectangle, Width_Rectangle, Length_Rectangle, default(FP), default(FP), default(FP), Rotation_Rectangle);
			Rotation_Fan = GetRotation();
			DamageShape_Fan = GetShapeData(DeterministicShape.ShapeType.Fan, POS_Fan, default(FP), default(FP), Radius_Fan, InnerRadius_Fan, Angle_Fan, Rotation_Fan);
			for (int i = 0; i < 3; i++)
			{
				AreaHit_Simple(_actor, DamageShape_Fan, HitData, 70022007, 0.5, HitBox.HurtAnimType.Small, "fx_70022_hit_Acition");
				AreaHit_Simple(_actor, DamageShape_Rectangle, HitData, 70022007, 0.5, HitBox.HurtAnimType.Small, "fx_70022_hit_Acition");
				yield return WaitTime(0.5);
			}
			StopEffect(AtkFxIndex);
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
