			PlayAreaEffect(Dot_Fan, GetPosition(), GetRotation());
			PlayAreaEffect(Dot_Fan, SummonPOS, GetTSVectToAngle(GetForward(), 180));
			PlayEffect(DamageFx_Fan, 1f, default(FP), GetPosition(), GetRotation());
			PlayEffect(DamageFx_Fan, 1f, default(FP), SummonPOS, GetTSVectToAngle(GetForward(), 180));
			StopEffect(WarningFxIndex_Fan01);
			StopEffect(WarningFxIndex_Fan02);
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
