		protected IEnumerator BackShoot()
		{
			SetSearchedImmunityEnable();
			BeginLookAt_NotWait(GetCurrentPlayer(), 0.2, 9999);
			BeginAttack(ThrowBStartIndex, ThrowBStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			Direction_JumpB = GetPosition() - GetEntityPosition(GetCurrentPlayer());
			yield return WaitTime(0.1);
			Speed_JumoB = 16;
			DIST_JumoB = 20;
			BeginDash(DashIndex_JumpB, Direction_JumpB, Speed_JumoB, DIST_JumoB, AngleLimit_JumoB, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitTime(0.3);
			Speed_JumoB = 5;
			DIST_JumoB = 10;
			BeginDash(DashIndex_JumpB, Direction_JumpB, Speed_JumoB, DIST_JumoB, AngleLimit_JumoB, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitTime(0.15);
			CancelAttack();
			yield return WaitTime(0.1);
			BulletAngle = GetRotation();
			if (GetLogicTagToggleValue(_actor, "SkillTag_SLJTrace"))
			{
				for (int i = 0; i < 3; i++)
				{
					if (i == 0)
					{
						PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle, 1.05f);
						BulletPOSList.Add(TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 5)));
						continue;
					}
					PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle + AngleOffset * i, 1.05f);
					PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle - AngleOffset * i, 1.05f);
					BulletPOSList.Add(TransLocalPosToWorldPos(GetPosition(), RotateTo(GetForward(), AngleOffset * i), new TSVector2(0, 5)));
					BulletPOSList.Add(TransLocalPosToWorldPos(GetPosition(), RotateTo(GetForward(), -AngleOffset * i), new TSVector2(0, 5)));
				}
			}
			else
			{
				for (int j = 0; j < 3; j++)
				{
					if (j == 0)
					{
						PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle, 1.05f);
						continue;
					}
					PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle + AngleOffset * j, 1.05f);
					PlayEffect(BulletFx, 0.8f, default(FP), GetPosition(), BulletAngle - AngleOffset * j, 1.05f);
				}
			}
			for (int k = 0; k < BulletPOSList.Count; k++)
			{
				_BulletGroundFx.Add(PlayAreaEffect(BulletGroundFx, BulletPOSList[k], BulletAngle));
				LineFxList.Add(PlayLinkEffect(LineFx, useCustomSource: true, _actor, default(TSVector2), default(FP), null, BulletPOSList[k], default(FP), breakWhenLostSourceOrTarget: false));
			}
			yield return WaitTime(0.3);
			StopDash();
			yield return WaitTime(0.4);
			SetSearchedImmunityDisable();
		}

		protected IEnumerator DodgeMove()
		{
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			for (int i = 0; i < 3; i++)
			{
				Target = GetAttackTarget(isUpToDate: true);
				if (CheckTargetIsValid(Target))
				{
					break;
				}
				if (i == 2)
				{
					Target = GetCurrentPlayer();
				}
				yield return WaitTime(0.15);
			}
			SetSearchedImmunityEnable();
			SetCloseBlockEnable();
			SetUnparalleledEnable();
			BeginLookAt_NotWait(Target, 0.2, 2000);
			BeginAttack(IndexDodge, DodgeKey, flushInputedKeys: true, forceInterruptAttack: true);
			IndexFxDogde = PlayEffect(Fx_Dogde);
			MovePOS = TransLocalPosToWorldPos(GetEntityPosition(Target), GetEntityPosition(Target) - GetPosition(), new TSVector2(0, 2));
			BeginBezierPathMove(IndexMove, MovePOS, XOffsetRatio, YOffsetRatio, comboWithAttack: true, SpeedRatioAmend, AdventureActor.MovementMode.None, MoveStep);
			yield return WaitBezierPathMoveFinish();
			SetSearchedImmunityDisable();
			SetCloseBlockDisable();
			SetInvincibleDisable();
			StopEffect(IndexFxDogde);
			if (GetLogicTagToggleValue(_actor, "SkillTag_SLJTrace"))
			{
				BeginAttack(ThrowSTraceIndex, ThrowSTraceKey, flushInputedKeys: true, forceInterruptAttack: true);
				yield return WaitTime(0.25);
				for (int j = 0; j < _BulletGroundFx.Count; j++)
				{
					ShootPOS = BulletPOSList[j];
					MultishootDirection = GetPosition() - ShootPOS;
					StopAreaEffect(_BulletGroundFx[j]);
					StopEffect(LineFxList[j]);
					FanMultipleShoot(BulletAlias_S, AdventureWeapon.MultipleShootStyle.FromCenterToSide, AlignShoot, AlignShootDelay, BulletCount, Duration, ShootPOS, ShootPOSY, MultishootDirection, BulletDirectionOffset, AimType.Target, BulletDirectionType.BulletToTarget, Angle, Radius, InnerRadius, default(TSVector2), _actor);
				}
			}
			else
			{
				CancelAttack();
			}
			BeginLookAt_NotWait(Target, 0.2, 2000);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}
	}
