					entitiesFromShape.Clear();
					friendEntity.Clear();
				}
				else
				{
					InterruptAttack();
				}
				yield return null;
			}
			SummonList.Clear();
			SummonList.AddRange(summons);
			summons.Clear();
			linkFxId = PlayLinkEffect(lineFx, useCustomSource: true, SummonList[2], default(TSVector2), default(FP), SummonList[3]);
		}

		private IEnumerator ControlBunsin(List<LogicEntity> targets)
		{
			TSVector2 selfPOS = GetPosition();
			for (int i = 0; i < targets.Count; i++)
			{
				TSVector2 entityPosition = GetEntityPosition(targets[i]);
				ControlFxList.Add(PlayLinkEffect(ControlFx, useCustomSource: true, null, selfPOS, default(FP), null, entityPosition, default(FP), breakWhenLostSourceOrTarget: true, 1f, actorScale: true));
			}
			yield return WaitTime(0.25);
			for (int j = 0; j < targets.Count; j++)
			{
				TSVector2 entityPosition = GetEntityPosition(targets[j]);
				ControllineFxList.Add(PlayLinkEffect(ControllineFx, useCustomSource: true, null, selfPOS, 0.3, null, entityPosition, default(FP), breakWhenLostSourceOrTarget: true, 1f, actorScale: true));
			}
		}

		private IEnumerator RecordingFx(List<LogicEntity> targets)
		{
			for (int i = 0; i < targets.Count; i++)
			{
				TSVector2 entityPosition = GetEntityPosition(targets[i]);
				ActiveFxList.Add(PlayEffect(ActiveFx, 1f, 3.7, entityPosition, default(FP), 1.2f, actorScale: true));
			}
			yield return null;
		}

		private IEnumerator MasterAttack(int[] atkType, List<LogicEntity> targets)
		{
			List<LogicEntity> list = new List<LogicEntity>();
			List<LogicEntity> targetsGroup2 = new List<LogicEntity>();
			if (atkType[0] == 0)
			{
				switch (atkType[1])
				{
				case 0:
					if (targets.Count > 0 && targets != null)
					{
						list.Add(targets[1]);
						list.Add(targets[2]);
						targetsGroup2.Add(targets[0]);
						targetsGroup2.Add(targets[3]);
					}
					else
					{
						InterruptAttack();
					}
					break;
				case 1:
					if (targets.Count > 0 && targets != null)
					{
						list.Add(targets[1]);
						list.Add(targets[3]);
						targetsGroup2.Add(targets[0]);
						targetsGroup2.Add(targets[2]);
					}
					else
					{
						InterruptAttack();
					}
					break;
				default:
					InterruptAttack();
					break;
				}
			}
			else
			{
				switch (atkType[1])
				{
				case 0:
					if (targets.Count > 0 && targets != null)
					{
						list.Add(targets[1]);
						list.Add(targets[2]);
						targetsGroup2.Add(targets[0]);
						targetsGroup2.Add(targets[3]);
					}
					else
					{
						InterruptAttack();
					}
					break;
				case 1:
					if (targets.Count > 0 && targets != null)
					{
						list.Add(targets[1]);
						list.Add(targets[3]);
						targetsGroup2.Add(targets[0]);
						targetsGroup2.Add(targets[2]);
					}
					else
					{
						InterruptAttack();
					}
					break;
				default:
					InterruptAttack();
					break;
				}
			}
			yield return StartCor(ConnectBunshinProcess(list, 1.5, 1, 0.12f));
			yield return WaitTime(0.5);
			yield return StartCor(ConnectBunshinProcess(targetsGroup2, 1.5, 0, 0.4f));
		}

		private IEnumerator BunsinAction(List<LogicEntity> targets)
		{
			if (targets != null && targets.Count >= 4)
			{
				SetLogicTagToggleValue(targets[2], "Sync_SWC_Action", value: true);
				SetLogicTagToggleValue(targets[3], "Sync_SWC_Action", value: true);
				StopEffect(linkFxId);
				_ = targets[2];
				_ = targets[3];
				List<long> bunsinDashState = new List<long>();
				for (int i = 0; i < 50; i++)
				{
					bunsinDashState.Clear();
					bunsinDashState.AddRange(GetLogicTagListLongValue(_actor, "bunsinDashState"));
					if (i > 45)
					{
						InterruptAttack();
					}
					else if (bunsinDashState.Count((long n) => n == 1) == 2)
					{
						break;
					}
					yield return WaitTime(0.2);
				}
				for (int num = 0; num < targets.Count; num++)
				{
					SetLogicTagToggleValue(targets[num], "Sync_SWC_Release", value: true);
				}
			}
			else
			{
				InterruptAttack();
			}
		}

		private void ReleaseBunsin()
		{
			if (ControlFxList != null && ControlFxList.Count > 0)
			{
				for (int i = 0; i < ControlFxList.Count; i++)
				{
					StopEffect(ControlFxList[i]);
				}
				ControlFxList.Clear();
			}
			if (ControllineFxList != null && ControllineFxList.Count > 0)
			{
				for (int j = 0; j < ControllineFxList.Count; j++)
				{
					StopEffect(ControllineFxList[j]);
				}
				ControllineFxList.Clear();
			}
			if (ActiveFxList != null && ActiveFxList.Count > 0)
			{
				for (int k = 0; k < ActiveFxList.Count; k++)
				{
					StopEffect(ActiveFxList[k]);
				}
				ActiveFxList.Clear();
			}
		}

		private IEnumerator ConnectBunshinProcess(List<LogicEntity> targets, FP durationOfAction, int type, float clockFxPlaySpeed)
		{
			yield return StartCor(ControlBunsin(targets));
			yield return StartCor(RecordingFx(targets));
			switch (type)
			{
			case 0:
				yield return StartCor(CircleAOE(durationOfAction));
				break;
			case 1:
				yield return StartCor(RingAOE(durationOfAction));
				break;
			default:
				InterruptAttack();
				break;
			}
			ReleaseBunsin();
			if (targets != null && targets.Count > 0)
			{
				for (int i = 0; i < targets.Count; i++)
				{
					ClockFxList.Add(PlayEffect(clockFx, clockFxPlaySpeed, default(FP), GetEntityPosition(targets[i]), default(FP), 2f));
				}
			}
		}

		private IEnumerator ControlledImmunity()
		{
			yield return WaitTime(0.2);
			SetImmuneControlEnable();
		}

		private IEnumerator CoordinathedAtkDMG(List<DeterministicShape> affectedArea, List<DeterministicShape> safetyArea)
		{
			FP damageInterval = 0.5;
			int duration = 10;
			LogicEntity player = GetCurrentPlayer();
			List<bool> searchResults = new List<bool>();
			List<LogicEntity> targetsFromShape = new List<LogicEntity>();
			HitFeatureData hitData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 3);
			if (affectedArea == null || affectedArea.Count <= 0)
			{
				yield break;
			}
			for (int j = 0; j < (int)(long)(duration / damageInterval); j++)
			{
				searchResults.Clear();
				if (safetyArea != null && safetyArea.Count > 0)
				{
					for (int i = 0; i < safetyArea.Count; i++)
					{
						targetsFromShape.Clear();
						targetsFromShape.AddRange(GetTargetsFromShape(safetyArea[i], null, includeSelf: false, player));
						if (targetsFromShape != null && targetsFromShape.Count > 0)
						{
							searchResults.Add(item: true);
						}
						else
						{
							searchResults.Add(item: false);
						}
					}
					if (searchResults.Contains(item: true))
					{
						yield return WaitTime(damageInterval);
						continue;
					}
				}
				for (int k = 0; k < affectedArea.Count; k++)
				{
					AreaHit_Simple(_actor, affectedArea[k], hitData, 70022010, 0.4, HitBox.HurtAnimType.Small, "fx_70022_hit_Skill01");
				}
				yield return WaitTime(damageInterval);
			}
		}
	}
}
namespace AIScript.Monster._70021MaoYan
{
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private int hitCount = 20;

		private int count;

		public override void OnStart()
		{
			base.OnStart();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			count = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (_actor.Id == adventureActorReceiveDamageEvent.from.Id)
			{
				count++;
			}
		}

		public override void OnDied(int monsterId)
		{
			if (monsterId == _actor.dataID && count >= hitCount && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.MaoYanLvRenBoss_003))
			{
				ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.MaoYanLvRenBoss_003);
			}
		}
	}
	public class SkillBaseMaoYan : SkillSimpleBase
	{
		protected enum E_TypeOfFire
		{
			Random,
			Tree,
			Triplet,
			Sweep
		}

		protected readonly string dodgeFxAlias = "fx_common_base_charge_fire_actor";

		protected readonly string ReloadAction = "Reload";

		protected readonly int ReloadIndex = 1;

		protected readonly string ShootAction = "HipFire";

		protected readonly int ShootIndex = 2;

		protected readonly string LFRDodge = "LFR_Dodge";

		protected readonly int LFRIndex = 3;

		protected readonly string FDodge = "F_Dodge";

		protected readonly int FIndex = 4;

		protected readonly string L2RShoot = "L2R_Shoot";

		protected readonly int L2RIndex = 5;

		protected readonly string R2LShoot = "R2L_Shoot";

		protected readonly int R2LIndex = 6;

		protected readonly string BarrageCombo = "Barrage";

		protected readonly int BarrageIndex = 7;

		protected readonly int rollIndex = 100;

		protected readonly int slideIndex = 101;

		protected LogicEntity GetTarget()
		{
			LogicEntity logicEntity = GetAttackTarget();
			if (!CheckTargetIsValid(logicEntity))
			{
				logicEntity = GetCurrentPlayer();
			}
			return logicEntity;
		}

		protected IEnumerator Reload()
		{
			LogicEntity currentPlayer = GetCurrentPlayer();
			CancelAttack();
			AimAtTarget(currentPlayer, 450f);
			BeginAttack(ReloadIndex, ReloadAction, flushInputedKeys: true, forceInterruptAttack: true);
			AlertMovement(GetPosition(), GetEntityPosition(GetTarget()), TSVector2.zero, GetTarget());
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopMove();
			CancelAim();
		}

		protected void PlayEarlyWarning()
		{
			PlayEffect(dodgeFxAlias, 1f, 1.6, GetPosition(), default(FP), 2.3f);
		}

		protected void AlertMovement(TSVector2 selfPos, TSVector2 playerPos, TSVector2 sceneCenter, LogicEntity target)
		{
			FP fP = 7;
			FP fP2 = Distance(selfPos, playerPos);
			FP fP3 = 9;
			int num = ((Distance(selfPos, sceneCenter) >= fP3) ? 1 : 2);
			if (num == 2)
			{
				num = ((!(fP2 <= fP)) ? 2 : 0);
			}
			TSVector2 zero = TSVector2.zero;
			switch (num)
			{
			case 0:
			{
				FP tSVectToAngle = 8;
				FP angle2 = 4;
				FP innerRadius = 30;
				FP radius = GetTSVectToAngle(selfPos - playerPos, 0);
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, selfPos, default(FP), default(FP), tSVectToAngle, angle2, innerRadius, radius);
				zero = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				break;
			}
			case 1:
				zero = TSVector2.zero;
				break;
			case 2:
			{
				FP angle = ((GetRandomValue(0, 1) >= 0.5) ? (-30) : 30);
				FP radius = 8;
				FP innerRadius = 4;
				FP angle2 = 30;
				FP tSVectToAngle = GetTSVectToAngle(sceneCenter - selfPos, angle);
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, selfPos, default(FP), default(FP), radius, innerRadius, angle2, tSVectToAngle);
				zero = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				break;
			}
			default:
				zero = TSVector2.zero;
				break;
			}
			MoveToPosition(zero, 0.5, AdventureActor.MovementMode.Walk, 3f, _stopDisIgnoreRadius: false);
		}

		protected IEnumerator Roll(TSVector2 targetPOS, bool playEarlyWarning)
		{
			LogicEntity target = GetTarget();
			TSVector2 selfPOS = GetPosition();
			FP relativeDIST = Distance(selfPOS, targetPOS);
			FP dashSpeed = relativeDIST / 0.4;
			BeginAttack(FIndex, FDodge, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginLookAt_NotWait(target, 0.1, 1800);
			BeginDash(rollIndex, targetPOS - selfPOS, dashSpeed, relativeDIST, 0, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0.3);
			yield return WaitDashFinish();
			if (playEarlyWarning)
			{
				PlayEarlyWarning();
			}
		}

		protected IEnumerator Slide(TSVector2 targetPOS, bool playEarlyWarning)
		{
			LogicEntity target = GetTarget();
			TSVector2 position = GetPosition();
			FP fP = Distance(position, targetPOS);
			FP speed = fP / 0.3;
			BeginAttack(LFRIndex, LFRDodge, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAtByPos_NotWait(targetPOS, 0.1, 1800);
			BeginDash(slideIndex, targetPOS - position, speed, fP, 0, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0.3);
			yield return WaitTime(0.1);
			CancelAttack();
			yield return WaitDashFinish();
			if (playEarlyWarning)
			{
				PlayEarlyWarning();
			}
			yield return BeginLookAt(target, 0.1, 1800);
		}

		protected void HipFire(int magazineCapacity, E_TypeOfFire EtypeOfFire)
		{
			SetLogicTagFpValue(_actor, "MagazineCapacity", magazineCapacity);
			switch (EtypeOfFire)
			{
			case E_TypeOfFire.Random:
				StartCor(TypeRandom());
				break;
			case E_TypeOfFire.Tree:
				StartCor(TypeTree());
				break;
			case E_TypeOfFire.Triplet:
				StartCor(TypeRandom());
				break;
			case E_TypeOfFire.Sweep:
				TpyeSweep();
				break;
			default:
				StartCor(TypeRandom());
				break;
			}
		}

		protected void HipFire(int magazineCapacity, E_TypeOfFire EtypeOfFire, out IEnumerator HipFireCoroutine)
		{
			SetLogicTagFpValue(_actor, "MagazineCapacity", magazineCapacity);
			switch (EtypeOfFire)
			{
			case E_TypeOfFire.Random:
				HipFireCoroutine = TypeRandom();
				break;
			case E_TypeOfFire.Tree:
				HipFireCoroutine = TypeTree();
				break;
			case E_TypeOfFire.Triplet:
				HipFireCoroutine = TypeRandom();
				break;
			case E_TypeOfFire.Sweep:
				HipFireCoroutine = TpyeSweep();
				break;
			default:
				HipFireCoroutine = TypeRandom();
				break;
			}
		}

		private IEnumerator TypeRandom()
		{
			int magazineCapacity = (int)(long)GetLogicTagFpValue(_actor, "MagazineCapacity");
			for (int i = 0; i < 3; i++)
			{
				for (int j = 0; j < magazineCapacity; j++)
				{
					PlayEffect("fx_70021_base_Fire", 1f, default(FP), default(TSVector2), default(FP), 1.5f);
					TSVector2 shootPosition = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 1.5));
					FanMultipleShoot("Bullet_Fire_Strike_COM", AdventureWeapon.MultipleShootStyle.RandomDirection, alignShoot: false, 0, 1, 0, shootPosition, 1.7, GetForward(), 0, AimType.Default, BulletDirectionType.ActorToBullet, 30, 0, 0);
					yield return WaitTime(0.05);
				}
				yield return WaitTime(0.3);
			}
		}

		private IEnumerator TypeTree()
		{
			CoroutineNode diffusionShootCor = null;
			int magazineCapacity = (int)(long)GetLogicTagFpValue(_actor, "MagazineCapacity");
			for (int i = 0; i < magazineCapacity; i++)
			{
				TSVector2 shootPos = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0.1, 1.5));
				TSVector2 forward = GetForward();
				Shooting(shootPos, forward);
				if (i == 1)
				{
					diffusionShootCor = StartCor(DiffusionShoot());
				}
				yield return WaitTime(0.1);
			}
			StopCor(diffusionShootCor);
		}

		private IEnumerator DiffusionShoot()
		{
			FP diffusionAngle = 10;
			for (int i = 0; i < 4; i++)
			{
				TSVector2 forward = GetForward();
				TSVector2 shootPos = TransLocalPosToWorldPos(GetPosition(), forward, new TSVector2(0, 1.5));
				TSVector2 direction = RotateTo(forward, -diffusionAngle);
				Shooting(shootPos, direction);
				TSVector2 direction2 = RotateTo(forward, diffusionAngle);
				Shooting(shootPos, direction2);
				yield return WaitTime(0.3);
				diffusionAngle += (FP)5;
			}
		}

		private IEnumerator TpyeSweep()
		{
			bool StrafingDirection = GetLogicTagToggleValue(_actor, "SweepDirection");
			FP deflectingDirection = (StrafingDirection ? 45 : (-45));
			for (int m = 0; m < 10; m++)
			{
				TSVector2 position = GetPosition();
				TSVector2 forward = GetForward();
				TSVector2 tSVector = ((!StrafingDirection) ? RotateTo(forward, deflectingDirection + 10.5 * (double)m) : RotateTo(forward, deflectingDirection - 10.5 * (double)m));
				TSVector2 shootPos = TransLocalPosToWorldPos(position, tSVector, new TSVector2(0, 1.3));
				Shooting(shootPos, tSVector);
				yield return WaitTime(0.07);
			}
		}

		private void Shooting(TSVector2 shootPos, TSVector2 direction)
		{
			FanMultipleShoot("Bullet_Fire_Strike_COM", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 1, 0, shootPos, 1.7, direction, 0, AimType.Default, BulletDirectionType.ActorToBullet, 0, 0, 0);
			PlayEffect("fx_70021_base_Fire", 1f, default(FP), default(TSVector2), default(FP), 1f, actorScale: true);
		}
	}
