			}
			_skill?.Clear();
		}

		private void onCustomEvent(string eveName)
		{
			if (string.Equals(evt_dodge_1, eveName))
			{
				DoDodge(dodge_time_1);
			}
			else if (string.Equals(evt_dodge_2, eveName))
			{
				DoDodge(dodge_time_2);
			}
			else if (string.Equals(evt_turn, eveName))
			{
				StartCoroutine(ref corTurn, DoLookAt());
			}
			else if (string.Equals(evt_shoot_1, eveName))
			{
				ILRuntimeAPI.FanMultipleShoot(_actor, bullut_1, isLeft ? AdventureWeapon.MultipleShootStyle.FromCenterToSide : AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 15, 0.8, _actor.tsTransform.Position, 1.7, _actor.tsTransform.Forward, 0, AimType.Default, BulletDirectionType.ActorToBullet, 2, 0, 0.5, default(TSVector2), null, null, useRef: true);
				corDelayShoot = StartCoroutine(DelayShoot());
			}
			else if (string.Equals(evt_shoot_2, eveName))
			{
				ILRuntimeAPI.FanMultipleShoot(_actor, bullut_2, isLeft ? AdventureWeapon.MultipleShootStyle.FromLeftToRight : AdventureWeapon.MultipleShootStyle.FromLeftToRight, alignShoot: false, 0, 10, 0.8, _actor.tsTransform.Position, 1.7, _actor.tsTransform.Forward, 0, AimType.Default, BulletDirectionType.ActorToBullet, 90, 0, 0.5, default(TSVector2), null, null, useRef: true);
			}
			else if (string.Equals(evt_shoot_3, eveName))
			{
				ILRuntimeAPI.FanMultipleShoot(_actor, bullut_3, isLeft ? AdventureWeapon.MultipleShootStyle.FromRightToLeft : AdventureWeapon.MultipleShootStyle.FromRightToLeft, alignShoot: false, 0, 10, 0.8, _actor.tsTransform.Position, 1.7, _actor.tsTransform.Forward, 0, AimType.Default, BulletDirectionType.ActorToBullet, 90, 0, 0.5, default(TSVector2), null, null, useRef: true);
			}
		}

		private void DoDodge(FP dodgeTime)
		{
			PlayerAdventureActor activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
			FP angle = (_actor.tsTransform.Position - activedPlayerActor.tsTransform.Position).normalized.GetAngle();
			TSVector2 position = _actor.tsTransform.Position;
			if (TSRandom.Range(0, 100) < 50)
			{
				isLeft = true;
				FP rotation = angle + offsetAngle;
				position = CommonUtils.RandomReachablePointInsideRingS(_actor, activedPlayerActor.tsTransform.Position, innterRadius, outerRadius, rotation, deltaAngle);
			}
			else
			{
				isLeft = false;
				FP rotation2 = angle - offsetAngle + deltaAngle / 2f;
				position = CommonUtils.RandomReachablePointInsideRingS(_actor, activedPlayerActor.tsTransform.Position, innterRadius, outerRadius, rotation2, deltaAngle);
			}
			TSVector2 normalized = (position - _actor.tsTransform.Position).normalized;
			FP magnitude = (position - _actor.tsTransform.Position).magnitude;
			dodge.Begin(_actor, normalized, dodgeTime, magnitude, null, comboWithAttack: true);
		}

		private IEnumerator DelayShoot()
		{
			yield return shootInterval;
			ILRuntimeAPI.FanMultipleShoot(_actor, bullut_other, isLeft ? AdventureWeapon.MultipleShootStyle.FromSideToCenter : AdventureWeapon.MultipleShootStyle.FromSideToCenter, alignShoot: false, 0, 6, 0.6, _actor.tsTransform.Position, 1.7, _actor.tsTransform.Forward, 0, AimType.Default, BulletDirectionType.ActorToBullet, 80, 0, 0, default(TSVector2), null, null, useRef: true);
		}

		private IEnumerator DoLookAt()
		{
			PlayerAdventureActor target = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
			FP curTime = lookat_time;
			while (curTime > 0)
			{
				lookAtTarget.BeginLookAtByPos(_actor, target.tsTransform.Position, lookat_time, lookat_speed, null);
				curTime -= _actor.LogicDeltaTime;
				yield return null;
			}
			lookAtTarget.StopLookAt();
		}
	}
	public class Skill_MobileHipFire_LD : SkillBaseMaoYan
	{
		private LogicEntity target;

		private bool sweepDirection;

		private IEnumerator ShootingCor;

		protected override void OnSkillEnable()
		{
			sweepDirection = false;
		}

		protected override void OnSkillDisable()
		{
			ShootingCor = null;
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			TSVector2 destination = GetDestination();
			yield return StartCor(Roll(destination, playEarlyWarning: true));
			yield return StartCor(SweepFire());
			destination = GetDestination();
			yield return StartCor(Slide(destination, playEarlyWarning: true));
			yield return StartCor(StationaryFire());
			destination = GetDestination();
			yield return StartCor(Roll(destination, playEarlyWarning: true));
			yield return StartCor(SweepFire());
			yield return StartCor(Reload());
		}

		private TSVector2 GetDestination()
		{
			TSVector2 tSVector = TSVector2.zero;
			TSVector2 position = GetPosition();
			FP fP = Distance(position, TSVector2.zero);
			TSVector2 entityPosition = GetEntityPosition(target);
			FP tSVectToAngle = GetTSVectToAngle(position - entityPosition, 0);
			if (fP > 10)
			{
				entityPosition = position;
				tSVectToAngle = GetTSVectToAngle(TSVector2.zero - position, 0);
			}
			else
			{
				entityPosition = GetEntityPosition(target);
				tSVectToAngle = GetTSVectToAngle(position - entityPosition, 0);
			}
			FP fP2 = 0;
			FP fP3 = 1;
			FP fP4 = 1;
			FP fP5 = 0;
			switch (GetPlayerJobType((AdventureActor)GetCurrentPlayer()))
			{
			case 1:
				fP2 = 4;
				fP3 = 7;
				fP4 = 8;
				fP5 = 5;
				break;
			case 2:
				fP2 = 10;
				fP3 = 15;
				fP4 = 15;
				fP5 = 7;
				break;
			default:
				fP2 = 4;
				fP3 = 7;
				fP4 = 8;
				fP5 = 5;
				break;
			}
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, entityPosition, default(FP), default(FP), fP4, fP5, 90, tSVectToAngle);
			for (int i = 0; i < 10; i++)
			{
				tSVector = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				FP fP6 = Distance(tSVector, position);
				if (fP3 > fP6 && fP6 >= fP2)
				{
					break;
				}
			}
			return tSVector;
		}

		private IEnumerator StationaryFire()
		{
			BeginAttack(ShootIndex, ShootAction, flushInputedKeys: true, forceInterruptAttack: true);
			AimAtTarget(target, 450f);
			yield return WaitTime(0.3);
			CancelAim();
			HipFire(12, E_TypeOfFire.Tree, out ShootingCor);
			yield return StartCor(ShootingCor);
			CancelAttack();
		}

		private IEnumerator SweepFire()
		{
			if (sweepDirection)
			{
				SetLogicTagToggleValue(_actor, "SweepDirection", value: true);
				BeginAttack(L2RIndex, L2RShoot, flushInputedKeys: true, forceInterruptAttack: true);
			}
			else
			{
				SetLogicTagToggleValue(_actor, "SweepDirection", value: false);
				BeginAttack(R2LIndex, R2LShoot, flushInputedKeys: true, forceInterruptAttack: true);
			}
			sweepDirection = !sweepDirection;
			BeginLookAt_NotWait(target, 0.2, 900);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			HipFire(10, E_TypeOfFire.Sweep, out ShootingCor);
			yield return StartCor(ShootingCor);
			CancelAttack();
		}
	}
	public class Skill_MobileHipFire_LD_02 : SkillBaseMaoYan
	{
		private bool sweepDirection;

		private IEnumerator ShootingCor;

		private static LogicEntity target;

		protected override void OnSkillEnable()
		{
			sweepDirection = false;
		}

		protected override void OnSkillDisable()
		{
			ShootingCor = null;
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			BeginAttack(BarrageIndex, BarrageCombo, flushInputedKeys: false, forceInterruptAttack: true);
			yield return WaitTime(0.3);
			List<TSVector2> barragePOS = new List<TSVector2>
			{
				new TSVector2(0, 6.5),
				new TSVector2(-6.5, 0),
				new TSVector2(0, -6.5),
				new TSVector2(6.5, 0)
			};
			for (int i = 0; i < 4; i++)
			{
				StartCor(SpawnBullet(barragePOS[i], 8));
				yield return WaitTime(0.8);
			}
			yield return WaitTime(2);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return StartCor(AttackFlow());
		}

		protected IEnumerator SpawnBullet(TSVector2 spawnPos, int bulletCount)
		{
			long groundFxID = PlayEffect("fx_m70021_loop_atk_Eyes_Loop_ground", 1f, default(FP), spawnPos);
			yield return WaitTime(0.5);
			TSVector2 direction = spawnPos - TSVector2.zero;
			List<long> spawnBulletFxID = new List<long>();
			for (int i = 0; i < bulletCount; i++)
			{
				TSVector2 tSVector = RotateTo(direction, 180 / bulletCount);
				TSVector2 position = TransLocalPosToWorldPos(spawnPos, tSVector, RotateTo(new TSVector2(0, 1.8) - TSVector2.zero, 45 * -i));
				FP tSVectToAngle = GetTSVectToAngle(tSVector, 360 / bulletCount * -i);
				spawnBulletFxID.Add(PlayEffect("fx_m70021_base_atk_Eyes_born", 1f, 1, position, tSVectToAngle));
				yield return WaitTime(0.2);
			}
			yield return WaitTime(2.5);
			StopEffect(groundFxID);
			if (spawnBulletFxID != null && spawnBulletFxID.Count > 0)
			{
				for (int j = 0; j < spawnBulletFxID.Count; j++)
				{
					StopEffect(spawnBulletFxID[j]);
				}
			}
			CircleMultipleShoot("Bullet_Barrage_Slow", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, bulletCount, 0, spawnPos, 1, direction, 0, AimType.Default, BulletDirectionType.ActorToBullet, 0, 1.8);
			MonoSingleton<WwiseAudioManager>.Instance.PlaySound("mon_70021_base_screen_BrarrageSpreadSlowMULTI");
		}

