			StopEffect(FxID_1);
			StopWaitLookAt();
			Position_2 = GetPosition();
			long FxID_2 = PlayEffect(FxAlias_2, PlaybackSpd_2, FxPositionY_2, Position_2);
			while (HitLoopTime <= RotateTime_Attack_2)
			{
