		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = Attack01;
			list.Add(new BaseBranchInfo(1, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack02;
			list.Add(new BaseBranchInfo(2, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack03;
			list.Add(new BaseBranchInfo(3, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack04;
			list.Add(new BaseBranchInfo(4, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack05;
			list.Add(new BaseBranchInfo(5, default(FP), default(FP), default(FP), null, operateIEnumerator));
