	public class Skill_Boom : SkillSimpleBase
	{
		private string key_Base = "Stage1_Skill03";

		private string areaEffect_Boom = "Area_70001_Skill03_Dot";

		private string evt_Boom = "evt_Boom";

		private LogicEntity Targetenemy;

		protected override IEnumerator DoMainLogic()
		{
			GetEnemy();
			TSVector2 targetPos = Targetenemy.tsTransform.Position;
			BeginAttack(1, key_Base);
			yield return WaitCustomEvent("SpawnArea");
			PlayAreaEffect("Area_70001_Skill03_Warn_1", targetPos);
			yield return WaitCustomEvent("SpawnArea");
			PlayAreaEffect("Area_70001_Skill03_Warn_2", targetPos);
			yield return WaitCustomEvent("SpawnArea");
			PlayAreaEffect("Area_70001_Skill03_Warn_3", targetPos);
			yield return WaitFrame(19);
			CancelAttack();
			yield return WaitFrame(11);
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_Boom, targetPos, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return WaitFrame(150);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void GetEnemy()
		{
			Targetenemy = GetAttackTarget();
			if (Targetenemy == null)
			{
				Targetenemy = GetCurrentPlayer();
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (eventName.Equals(evt_Boom))
			{
				DispatchCustomEvent(evt_Boom, isSelfEvent: false);
			}
		}
	}
	public class Skill_Danmu : SkillSimpleBase
	{
		private string key_Base1 = "Stage1_Skill04_1";

		private string key_Base2 = "Stage1_Skill04_2";

		private string bulletDanmu = "Bullet_70001_Skill04_1";

		private string evt_Danmu = "evt_Danmu";

		private TSVector2 center = new TSVector2(0, -7.5);

		private LogicEntity Targetenemy;

		protected override void OnInterrupt(int comboIndex)
		{
			_actor.tsTransform.Forward = new TSVector2(0, -1);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, key_Base1);
			yield return WaitFrame(44);
			BeginAttack(2, key_Base2, flushInputedKeys: true, forceInterruptAttack: true);
			GetEnemy();
			if (Targetenemy.tsTransform.Position.x < center.x)
			{
				BeginRotateAngle_NotWait(-50, 180);
				yield return WaitFrame(15);
				BeginRotateAngle_NotWait(180, 52);
				ShootFromRight();
				yield return WaitFrame(160);
				CancelAttack();
				BeginLookAtByDir_NotWait(center, 0, 150);
			}
			else
			{
				BeginRotateAngle_NotWait(110, 275);
				yield return WaitFrame(15);
				ShootFromLeft();
				yield return WaitFrame(20);
				BeginRotateAngle_NotWait(-170, 52);
				yield return WaitFrame(140);
				CancelAttack();
				BeginLookAtByDir_NotWait(center, 0, 100);
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void GetEnemy()
		{
			Targetenemy = GetAttackTarget();
			if (Targetenemy == null)
			{
				Targetenemy = GetCurrentPlayer();
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (eventName.Equals(evt_Danmu))
			{
				DispatchCustomEvent(evt_Danmu, isSelfEvent: false);
			}
		}

		private void ShootFromLeft()
		{
			FanMultipleShoot(bulletDanmu, AdventureWeapon.MultipleShootStyle.FromLeftToRight, alignShoot: false, 0, 12, 4, new TSVector2(0, 0), 1.5, new TSVector2(0, -7.5) - new TSVector2(0, 0), 0, AimType.Default, BulletDirectionType.ActorToBullet, 170, 0, 5);
		}

		private void ShootFromRight()
		{
			FanMultipleShoot(bulletDanmu, AdventureWeapon.MultipleShootStyle.FromRightToLeft, alignShoot: false, 0, 12, 4, new TSVector2(0, 0), 1.5, new TSVector2(0, -7.5) - new TSVector2(0, 0), 0, AimType.Default, BulletDirectionType.ActorToBullet, 170, 0, 5);
		}
	}
	public class Skill_GravityField : SkillSimpleBase
	{
		private string key_Base1 = "Stage1_Skill06_1";

		private string key_Base2 = "Stage1_Skill06_2";

		private List<long> moveSummonIds = new List<long>();

		private int unmoveSummonId = 7010098;

		private string areaEffect_GravityField = "Area_70001_Skill06_Gravity_1";

		private string areaEffect_AccField = "Area_70001_Skill06_Gravity_2";

		private string areaEffect_BigAccField = "Area_70001_Skill06_Gravity_3";

		private string evt_Ultra = "evt_Ultra";

		private int liveCount;

		private List<string> summonPosList_Unmove = new List<string> { "Jin_01", "Jin_02", "Jin_03", "Jin_04" };

		private List<string> summonPosList_Move = new List<string> { "Zuo_01_01", "Zuo_02_01", "You_01_01", "You_02_01" };

		private TSVector2 center = new TSVector2(0, -7.5);

		private List<MonsterAdventureActor> summons = new List<MonsterAdventureActor>();

		private MonsterAdventureActor Actor => _actor as MonsterAdventureActor;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			moveSummonIds = GetLogicTagListLongValue(_actor, "MonsterSpawnList");
			Actor.monsterInfo.currentEnergy = 0;
			MonoSingleton<LuaManager>.Instance.FireEntityEvent("JointDrillBossEnergyChanged", _actor.Id, 0, a2: false);
			MonoSingleton<LuaManager>.Instance.FireEntityEvent("CastUltra", _actor.Id);
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			summons.Clear();
		}

		protected override void OnInterrupt(int comboIndex)
		{
			GetSummons(ref summons, new List<int> { unmoveSummonId });
			liveCount = 0;
			for (int i = 0; i < summons.Count; i++)
			{
				if (!summons[i].isDead)
				{
					liveCount++;
				}
				TSVector2 position = summons[i].tsTransform.Position;
				summons[i].ClearSelf();
				PlayEffect("fx_m70001_base_skill06_shunyi_out", 1f, 0.5, position);
			}
			liveCount = Math.Min(liveCount, summonPosList_Move.Count);
			for (int j = 0; j < liveCount; j++)
			{
				TSVector2 placeHolderPosition = GetPlaceHolderPosition(summonPosList_Move[j]);
				ILRuntimeAPI.SummonMonster(_actor, 0, (int)moveSummonIds[j], placeHolderPosition, center - placeHolderPosition, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, key_Base1, flushInputedKeys: true, forceInterruptAttack: true);
			StartCor(BookLogic());
			StartCor(AreaLogic());
			yield return WaitFrame(259);
			BeginAttack(2, key_Base2, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitFrame(101);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator BookLogic()
		{
			yield return WaitFrame(10);
			GetAllSummons(ref summons);
			foreach (MonsterAdventureActor summon in summons)
			{
				PlayEffect(position: summon.tsTransform.Position, fxAlias: "fx_m70001_base_skill06_shunyi_out", playbackSpeed: 1f, fxPositionY: 0.5);
				summon.ClearSelf();
			}
			yield return WaitFrame(3);
			for (int i = 0; i < summonPosList_Unmove.Count; i++)
			{
				TSVector2 placeHolderPosition = GetPlaceHolderPosition(summonPosList_Unmove[i]);
				ILRuntimeAPI.SummonMonster(_actor, 0, unmoveSummonId, placeHolderPosition, center - placeHolderPosition, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			}
			yield return WaitFrame(32);
			yield return WaitFrame(220);
			GetSummons(ref summons, new List<int> { unmoveSummonId });
			liveCount = 0;
			for (int j = 0; j < summons.Count; j++)
			{
				if (!summons[j].isDead)
				{
					liveCount++;
				}
				TSVector2 position = summons[j].tsTransform.Position;
				summons[j].ClearSelf();
				PlayEffect("fx_m70001_base_skill06_shunyi_out", 1f, 0.5, position);
			}
			yield return WaitFrame(139);
			liveCount = Math.Min(liveCount, summonPosList_Move.Count);
			for (int k = 0; k < liveCount; k++)
			{
				TSVector2 placeHolderPosition2 = GetPlaceHolderPosition(summonPosList_Move[k]);
				ILRuntimeAPI.SummonMonster(_actor, 0, (int)moveSummonIds[k], placeHolderPosition2, center - placeHolderPosition2, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			}
		}

		protected IEnumerator AreaLogic()
		{
			yield return WaitFrame(10);
			PlayAreaEffect(areaEffect_GravityField, center);
			PlayAreaEffect("Area_70001_Skill06_Tractor_1", center);
			yield return WaitFrame(254);
			GetAllSummons(ref summons);
			yield return WaitFrame(2);
			if (summons.Count > 0)
			{
				PlayAreaEffect(areaEffect_BigAccField, center);
			}
			else
			{
				PlayAreaEffect(areaEffect_AccField, center);
			}
			PlayAreaEffect("Area_70001_Skill06_Tractor_2", center);
		}

		private void GetSummons(ref List<MonsterAdventureActor> monsters, List<int> ids)
		{
			monsters.Clear();
			List<AdventureModuleController.MonsterSummonData> monsterSummonInfos = ModuleController<AdventureModuleController>.Instance.MonsterSummonInfos;
			for (int i = 0; i < monsterSummonInfos.Count; i++)
			{
				if (ids.Contains(monsterSummonInfos[i].dataID))
				{
					LogicEntity logicEntity = ModuleController<AdventureModuleController>.Instance.QueryEntityByID(monsterSummonInfos[i].entityID);
					if (logicEntity != null && logicEntity is MonsterAdventureActor item)
					{
						monsters.Add(item);
					}
				}
			}
		}

		private void GetAllSummons(ref List<MonsterAdventureActor> monsters)
		{
			monsters.Clear();
			List<AdventureModuleController.MonsterSummonData> monsterSummonInfos = ModuleController<AdventureModuleController>.Instance.MonsterSummonInfos;
			for (int i = 0; i < monsterSummonInfos.Count; i++)
			{
				if (monsterSummonInfos[i].SummonActorID == _actor.Id)
				{
					LogicEntity logicEntity = ModuleController<AdventureModuleController>.Instance.QueryEntityByID(monsterSummonInfos[i].entityID);
					if (logicEntity != null && logicEntity is MonsterAdventureActor item)
					{
						monsters.Add(item);
					}
				}
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (eventName.Equals(evt_Ultra))
			{
				DispatchCustomEvent(evt_Ultra, isSelfEvent: false);
