	public class Skill_Laser : SkillSimpleBase
	{
		private string key_Base = "Stage1_Skill05";

		private Dictionary<string, string> bullet_Laser = new Dictionary<string, string>
		{
			["Lv1"] = "Bullet_70001_Skill05_Laser_Slow",
			["Lv2"] = "Bullet_70001_Skill05_Laser_Slow",
			["Lv3"] = "Bullet_70001_Skill05_Laser_Slow",
			["Lv4"] = "Bullet_70001_Skill05_Laser"
		};

		private Dictionary<string, string> bullet_Ball = new Dictionary<string, string>
		{
			["Lv1"] = "Bullet_70001_Skill05_Ball_Loop_Slow",
			["Lv2"] = "Bullet_70001_Skill05_Ball_Loop_Slow",
			["Lv3"] = "Bullet_70001_Skill05_Ball_Loop_Slow",
			["Lv4"] = "Bullet_70001_Skill05_Ball_Loop"
		};

		private Dictionary<string, int> loopCount = new Dictionary<string, int>
		{
			["Lv1"] = 1,
			["Lv2"] = 1,
			["Lv3"] = 1,
			["Lv4"] = 2
		};

		private string evt_Laser = "evt_Laser";

		private TSVector2 edge_up = new TSVector2(0, 0);

		private TSVector2 edge_down = new TSVector2(0, -15);

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, key_Base);
			yield return WaitFrame(9);
			SpawnBall();
			yield return WaitFrame(30);
			StartCor(LoopLaser1());
			StartCor(LoopLaser2());
			StartCor(LoopBall1());
			StartCor(LoopBall2());
			yield return WaitFrame(180);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator LoopLaser1()
		{
			for (int i = 0; i < loopCount[GetMonsterTagValue(_actor, 1)]; i++)
			{
				TSVector2 tSVector = ((i % 2 == 0) ? edge_down : edge_up);
				TSVector2 obj = ((i % 2 == 0) ? edge_up : edge_down);
				AdventureBulletBase bullet1 = ILRuntimeAPI.ShootByDirection(shootDir: (obj - tSVector).normalized, bulletAlias: bullet_Laser[GetMonsterTagValue(_actor, 1)], actor: _actor, range: default(FP), position: tSVector, positionY: 0.5);
				FP waitSeconds = (obj - tSVector).magnitude / bullet1.velocitySpeed;
				yield return WaitTime(waitSeconds);
				bullet1.Finish();
			}
		}

		protected IEnumerator LoopLaser2()
		{
			for (int i = 0; i < loopCount[GetMonsterTagValue(_actor, 1)]; i++)
			{
				TSVector2 tSVector = ((i % 2 == 0) ? edge_down : edge_up);
				TSVector2 tSVector2 = ((i % 2 == 0) ? edge_up : edge_down);
				TSVector2 normalized = (tSVector - tSVector2).normalized;
				AdventureBulletBase bullet2 = ILRuntimeAPI.ShootByDirection(bullet_Laser[GetMonsterTagValue(_actor, 1)], _actor, default(FP), normalized, tSVector2, 0.5);
				FP waitSeconds = (tSVector2 - tSVector).magnitude / bullet2.velocitySpeed;
				yield return WaitTime(waitSeconds);
				bullet2.Finish();
			}
		}

		protected IEnumerator LoopBall1()
		{
			for (int i = 0; i < loopCount[GetMonsterTagValue(_actor, 1)]; i++)
			{
				TSVector2 tSVector = ((i % 2 == 0) ? edge_down : edge_up);
				TSVector2 obj = ((i % 2 == 0) ? edge_up : edge_down);
				AdventureBulletBase bullet3 = ILRuntimeAPI.ShootByDirection(shootDir: (obj - tSVector).normalized, bulletAlias: bullet_Ball[GetMonsterTagValue(_actor, 1)], actor: _actor, range: default(FP), position: tSVector, positionY: 0.5);
				FP waitSeconds = (obj - tSVector).magnitude / bullet3.velocitySpeed;
				yield return WaitTime(waitSeconds);
				bullet3.Finish();
			}
		}

		protected IEnumerator LoopBall2()
		{
			for (int i = 0; i < loopCount[GetMonsterTagValue(_actor, 1)]; i++)
			{
				TSVector2 tSVector = ((i % 2 == 0) ? edge_down : edge_up);
				TSVector2 tSVector2 = ((i % 2 == 0) ? edge_up : edge_down);
				TSVector2 normalized = (tSVector - tSVector2).normalized;
				AdventureBulletBase bullet4 = ILRuntimeAPI.ShootByDirection(bullet_Ball[GetMonsterTagValue(_actor, 1)], _actor, default(FP), normalized, tSVector2, 0.5);
				FP waitSeconds = (tSVector2 - tSVector).magnitude / bullet4.velocitySpeed;
				yield return WaitTime(waitSeconds);
				bullet4.Finish();
			}
		}

		private void SpawnBall()
		{
			Shoot("Bullet_70001_Skill05_Ball_Start", edge_up, 0.5, 0);
			Shoot("Bullet_70001_Skill05_Ball_Start", edge_down, 0.5, 0);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (eventName.Equals(evt_Laser))
			{
				DispatchCustomEvent(evt_Laser, isSelfEvent: false);
			}
		}
	}
	public class Skill_LightShoot : SkillSimpleBase
	{
		private string key_Base1 = "Stage1_Skill02_1";

		private string key_Base2 = "Stage1_Skill02_2";

		private string key_Base3 = "Stage1_Skill02_3";

		private string bullet_laser = "Bullet_70001_Skill02_Laser_Wave";

		private List<int> shootTime = new List<int> { 0, 16 };

		private string bullet_tide = "Bullet_70001_Skill02_Tide_1";

		private string evt_Wave = "evt_Wave";

		private List<TSVector2> shootPos = new List<TSVector2>
		{
			new TSVector2(-10, 0),
			new TSVector2(0, 0),
			new TSVector2(10, 0)
		};

		private TSVector2 shootOffset = new TSVector2(0, 3);

		private FP shootY = 1.5;

		private TSVector2 center = new TSVector2(0, -7.5);

		private TSVector2 edge_up = new TSVector2(0, 0);

		private TSVector2 edge_down = new TSVector2(0, -15);

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, key_Base1);
			yield return WaitFrame(15);
			LogicEntity logicEntity = GetAttackTarget();
			if (logicEntity == null)
			{
				logicEntity = GetCurrentPlayer();
			}
			AimAtTarget(logicEntity, 120f);
			yield return WaitFrame(69);
			CancelAim();
			BeginAttack(2, key_Base2, flushInputedKeys: true, forceInterruptAttack: true);
			ShootLaser();
			yield return WaitFrame(16);
			ShootLaser();
			yield return WaitFrame(20);
			CancelAttack();
			BeginAttack(3, key_Base3, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAtByDir_NotWait(center, 1.5, 150);
			WaveBullet();
			yield return WaitFrame(75);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void ShootLaser()
		{
			TSVector2 tSVector = _actor.tsTransform.TransformLocalPointToWorldSpace(shootOffset);
			TSVector2 shootDir = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 5)) - tSVector;
			ILRuntimeAPI.ShootByDirection(bullet_laser, _actor, default(FP), shootDir, tSVector, shootY);
		}

		protected IEnumerable ShootLaserLoop()
		{
			for (int i = 0; i < shootTime.Count; i++)
			{
				LogicEntity target = GetAttackTarget();
				if (target == null)
				{
					target = GetCurrentPlayer();
				}
				yield return WaitFrame(shootTime[i]);
				TSVector2 tSVector = _actor.tsTransform.TransformLocalPointToWorldSpace(shootOffset);
				TSVector2 normalized = (new TSVector2(target.tsTransform.Position.x, target.tsTransform.Position.y) - tSVector).normalized;
				ILRuntimeAPI.ShootByDirection(bullet_laser, _actor, default(FP), normalized, tSVector, shootY);
			}
		}

		private void WaveBullet()
		{
			LogicEntity logicEntity = GetAttackTarget();
			if (logicEntity == null)
			{
				logicEntity = GetCurrentPlayer();
			}
			TSVector2 value = new TSVector2(logicEntity.tsTransform.Position.x, 0);
			TSVector2 tSVector = shootPos[0];
			FP fP = Distance(value, tSVector);
			for (int i = 0; i < shootPos.Count; i++)
			{
				FP fP2 = Distance(value, shootPos[i]);
				if (fP2 <= fP)
				{
					fP = fP2;
					tSVector = shootPos[i];
				}
			}
			TSVector2 tSVector2 = tSVector;
			TSVector2 tSVector3 = new TSVector2(tSVector.x, edge_down.y);
			int num = 0;
			TSVector2 shootDir = tSVector3 - tSVector2;
			ILRuntimeAPI.ShootByDirection(bullet_tide, _actor, default(FP), shootDir, tSVector2, num);
			PlayAreaEffect("Area_70001_Skill02_Tide_Warn01", tSVector2, 180);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (eventName.Equals(evt_Wave))
			{
				DispatchCustomEvent(evt_Wave, isSelfEvent: false);
			}
		}
	}
	public class Skill_Smash : SkillSimpleBase
	{
		private string key_smash = "Stage1_Skill01_1";

		private string key_sweep_right = "Stage1_Skill01_2";

		private string key_sweep_left = "Stage1_Skill01_3";

		private string areaEffect_Smash = "Area_70001_Skill01";

		private TSVector2 center = new TSVector2(0, 0);

		private TSVector2 pos;

		private LogicEntity Targetenemy;

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, key_smash);
			yield return WaitFrame(39);
			GetEnemy();
			pos = Targetenemy.tsTransform.Position;
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_Smash, Targetenemy.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return WaitFrame(16);
			CancelAttack();
			yield return WaitTime(1);
			if (pos.x < center.x)
			{
				BeginAttack(2, key_sweep_right, flushInputedKeys: true, forceInterruptAttack: true);
				PlayAreaEffect("Area_70001_Skill01_Wave", pos, -90);
				Shoot("Bullet_70001_Skill01_1", pos, 0, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, TransLocalPosToWorldPos(pos, GetForward(), new TSVector2(-1, 0)));
				yield return WaitFrame(45);
				CancelAttack();
			}
			else
			{
				BeginAttack(2, key_sweep_left, flushInputedKeys: true, forceInterruptAttack: true);
				PlayAreaEffect("Area_70001_Skill01_Wave", pos, 90);
				Shoot("Bullet_70001_Skill01_1", pos, 0, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, TransLocalPosToWorldPos(pos, GetForward(), new TSVector2(1, 0)));
				yield return WaitFrame(45);
				CancelAttack();
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void GetEnemy()
		{
			Targetenemy = GetAttackTarget();
			if (Targetenemy == null)
			{
				Targetenemy = GetCurrentPlayer();
			}
		}
	}
	public class Action_Stage2_Lv1 : MonsterActionBase
	{
		private string moveTag = "Move";

		private int Skill_Attack01 = 7000108;

		private int Skill_Attack02 = 7000109;

		private int Skill_Attack03 = 7000110;

		private int Skill_Attack04 = 7000111;

		private int Skill_Attack05 = 7000112;

		private int Skill_Attack06 = 7000113;

		private int Skill_Attack07 = 7000114;

		private int ultraSeqInex = 2;

		private List<int> moveSummonIds = new List<int> { 7010024, 7010025, 7010026, 7010027 };

		private List<string> summonPosList_Move = new List<string> { "Zuo_01_01", "Zuo_02_01", "You_01_01", "You_02_01" };

		private FP reviveTime = 30f;

		private Dictionary<int, string> dicSpawnPoint = new Dictionary<int, string>
		{
			[7010024] = "Zuo_01_01",
			[7010025] = "Zuo_02_01",
			[7010026] = "You_01_01",
			[7010027] = "You_02_01"
		};

		private List<int> seqList = new List<int>();

		private int seqCount;

		private SummonCfg summonCfg = new SummonCfg();

		private int lastSeqIndex;

		private int lastBranchIndex;

		private MonsterAdventureActor actor => _actor as MonsterAdventureActor;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnDied);
			SpawnSummon();
			AddMonsterIdToList();
			summonCfg.summonFollowType = SummonFollowType.NotFollow;
			summonCfg.summonAttrType = SummonAttrType.InheritByInitialSnapshot;
			summonCfg.summonRelation = SummonRelation.Independent;
			summonCfg.attrPercent = 100;
			summonCfg.leftTime = -1;
			summonCfg.retainWhenCrossLevel = false;
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnDied);
		}

		protected override void SetListenEvents()
		{
			InitListenEvent(MonsterEventType.MonsterDie, true, OnMonsterDied, 7010024, 7010025, 7010026, 7010027);
			InitListenEvent(MonsterEventType.SelfToughnessBroken, active: true, InterruptStrong);
		}

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = Attack01;
			list.Add(new BaseBranchInfo(1, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack02;
			list.Add(new BaseBranchInfo(2, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack03;
			list.Add(new BaseBranchInfo(3, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack04;
			list.Add(new BaseBranchInfo(4, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack05;
			list.Add(new BaseBranchInfo(5, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack06;
			list.Add(new BaseBranchInfo(6, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack07;
			list.Add(new BaseBranchInfo(7, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Attack08;
			list.Add(new BaseBranchInfo(99, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> dictionary = new Dictionary<int, List<int>>
			{
				[0] = new List<int> { 99, 1, 99, 2, 99, 4, 99, 5, 99, 6 },
				[1] = new List<int> { 99, 1, 99, 2, 99, 4, 99, 5, 99, 6 },
				[2] = new List<int> { 7 }
			};
			seqCount = dictionary.Count - 1;
			for (int i = 0; i < seqCount; i++)
			{
				seqList.Add(i);
			}
			lastSeqIndex = RandomIndexFromLeft();
			InitSequenceBranches(lastSeqIndex, sequenceBranches, dictionary);
		}

		private void InterruptStrong(IEvent evt)
		{
			if (GetCurrentSequenceIndex() == ultraSeqInex)
			{
				if (actor.monsterInfo.currentEnergy < actor.monsterInfo.maxEnergy)
				{
					SetCurrentSequenceIndex(lastBranchIndex);
					SwitchSequence(lastSeqIndex, initialIndex: false);
				}
			}
			else
			{
				lastSeqIndex = RandomIndexFromLeft();
				SwitchSequence(lastSeqIndex);
			}
		}

		protected override void OnSequenceBranchOperateComplete(int curSeqIndex, int nextBranchIndex, bool isSeqEnd)
		{
			if (curSeqIndex != ultraSeqInex)
			{
				lastBranchIndex = nextBranchIndex;
			}
			if (isSeqEnd)
			{
				if (actor.monsterInfo.currentEnergy >= actor.monsterInfo.maxEnergy)
				{
					SwitchSequence(ultraSeqInex);
				}
				else if (curSeqIndex == ultraSeqInex)
				{
					SetCurrentSequenceIndex(lastBranchIndex);
					SwitchSequence(lastSeqIndex, initialIndex: false);
				}
				else
				{
					lastSeqIndex = RandomIndexFromLeft();
					SwitchSequence(lastSeqIndex);
				}
			}
			else if (actor.monsterInfo.currentEnergy >= actor.monsterInfo.maxEnergy)
			{
				SwitchSequence(ultraSeqInex);
			}
		}

		private int RandomIndexFromLeft()
		{
			if (seqCount == seqList.Count)
			{
				seqList.RemoveAt(0);
				return 0;
			}
			int index = TSRandom.Range(0, seqList.Count);
			int result = seqList[index];
			seqList.RemoveAt(index);
			if (seqList.Count == 0)
			{
				for (int i = 1; i < seqCount; i++)
				{
					seqList.Add(i);
				}
			}
			return result;
		}

		private IEnumerator Attack01()
		{
			CastSkill(Skill_Attack01);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack02()
		{
			CastSkill(Skill_Attack02);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack03()
		{
			CastSkill(Skill_Attack03);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack04()
		{
			CastSkill(Skill_Attack04);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack05()
		{
			CastSkill(Skill_Attack05);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack06()
		{
			CastSkill(Skill_Attack06);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack07()
		{
			CastSkill(Skill_Attack07);
			yield return WaitSkillFinish();
		}

		private IEnumerator Attack08()
		{
			yield return WaitTime(2);
		}

		private void OnDied(IEvent evt)
		{
			AdventureActorDiedEvent adventureActorDiedEvent = evt as AdventureActorDiedEvent;
			if (adventureActorDiedEvent.deadType == DeadType.ClearSelf && adventureActorDiedEvent.actor is MonsterAdventureActor monsterAdventureActor && monsterAdventureActor.monsterInfo.Tag4.Equals(moveTag))
			{
				StartCor(DoRevive(adventureActorDiedEvent.actor.dataID));
			}
		}

		private void OnMonsterDied(IEvent evt)
		{
			AdventureMonsterDiedEvent adventureMonsterDiedEvent = evt as AdventureMonsterDiedEvent;
			if (adventureMonsterDiedEvent.summonId == _actor.Id && ModuleController<AdventureModuleController>.Instance.QueryEntityByID(adventureMonsterDiedEvent.id) is MonsterAdventureActor monsterAdventureActor && monsterAdventureActor.monsterInfo.Tag4.Equals(moveTag))
			{
				StartCor(DoRevive(adventureMonsterDiedEvent.monsterID));
			}
		}

		private IEnumerator DoRevive(int monsterId)
		{
			FP curTime = 0;
			while (curTime < reviveTime)
			{
				yield return null;
				if (!_actor.logicVariable.GetLogicTagToggle("guild"))
				{
					curTime += _actor.LogicDeltaTime;
				}
			}
			TSVector2 placeHolderPosition = GetPlaceHolderPosition(dicSpawnPoint[monsterId]);
			ILRuntimeAPI.SummonMonster(_actor, 0, monsterId, placeHolderPosition, _actor.tsTransform.Forward, summonCfg, (string)null, (Action<MonsterAdventureActor>)null);
		}

		private void SpawnSummon()
		{
			for (int i = 0; i < 4; i++)
			{
				TSVector2 placeHolderPosition = GetPlaceHolderPosition(summonPosList_Move[i]);
				TSVector2 tSVector = new TSVector2(0, -7.5);
				ILRuntimeAPI.SummonMonster(_actor, 0, moveSummonIds[i], placeHolderPosition, tSVector - placeHolderPosition, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			}
		}

		private void AddMonsterIdToList()
		{
			SetLogicTagListLongValue(_actor, "MonsterSpawnList", new List<long> { 7010024L, 7010025L, 7010026L, 7010027L });
		}
	}
