	public class Skill_RunAwayBomb : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Run_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		private static readonly TSVector2 FixedPoints1 = new TSVector2(0, 6.5);

		private static readonly TSVector2 FixedPoints2 = new TSVector2(0, -6.5);

		private static readonly TSVector2 FixedPoints3 = new TSVector2(6.5, 0);

		private static readonly TSVector2 FixedPoints4 = new TSVector2(-6.5, 0);

		private List<LogicEntity> FixedPoints;

		private int PositionIndex;

		private System.Random rng = new System.Random();

		private long PresentFX;

		private long Emoji;

		private int[] BombWeights;

		private int RandomBomb;

		private string BombName;

		private DeterministicShape AttackShape;

		private TSVector2 AttackPosition;

		private CoroutineNode PresentShootNode;

		private LogicEntity NextAimTarget;

		protected override void OnSkillEnable()
		{
			FixedPoints = GetTargetByDataID(6100402);
			Shuffle(FixedPoints);
			BombWeights = new int[4] { 1, 1, 1, 1 };
			PositionIndex = 0;
		}

		protected override void OnSkillDisable()
		{
			FixedPoints.Clear();
			StopEffect(PresentFX);
			StopEffect(Emoji);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Run_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			PresentFX = PlayEffect("PresentFX");
			Emoji = PlayEffect("RunBomb_Emoji");
			NextAimTarget = GetTargetNearOrFar(iNear: false, FixedPoints);
			FixedPoints.Remove(NextAimTarget);
			FixedPoints.Insert(0, NextAimTarget);
			BeginLookAt_NotWait(NextAimTarget, 0, 360);
			yield return WaitTime(1.25);
			StartCor(ref PresentShootNode, PresentShoot());
			yield return StartCor(GoToPositions());
			StopCor(PresentShootNode);
			StopEffect(PresentFX);
			StopEffect(Emoji);
			CancelAttack();
			yield return WaitTime(1);
		}

		private void Shuffle(List<LogicEntity> List)
		{
			int num = List.Count;
			while (num > 1)
			{
				num--;
				int index = rng.Next(num + 1);
				LogicEntity value = List[index];
				List[index] = List[num];
				List[num] = value;
			}
		}

		private IEnumerator GoToPositions()
		{
			while (PositionIndex <= 3)
			{
				BeginDash(1, GetForward(), 12, Distance(GetEntityPosition(NextAimTarget), GetPosition()) - 1, 0, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
				yield return WaitDashFinish();
				PositionIndex++;
				if (PositionIndex == 4 || PositionIndex >= FixedPoints.Count)
				{
					NextAimTarget = GetCurrentPlayer();
				}
				else
				{
					NextAimTarget = FixedPoints[PositionIndex];
				}
				BeginDash(2, GetForward(), 8, 4, 999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
				PlayWwiseSound("mon_50801_attack_shoot_brake");
				yield return WaitLookAt(NextAimTarget, 0.5, 360);
				yield return WaitTime(0.3);
			}
		}

		private IEnumerator PresentShoot()
		{
			while (true)
			{
				RandomBomb = randomWeight(BombWeights);
				switch (RandomBomb)
				{
				case 1:
					BombName = "GiftBomb_1";
					break;
				case 2:
					BombName = "GiftBomb_2";
					break;
				case 3:
					BombName = "GiftBomb_3";
					break;
				case 4:
					BombName = "GiftBomb_4";
					break;
				}
				Skill_RunAwayBomb skill_RunAwayBomb = this;
				Skill_RunAwayBomb skill_RunAwayBomb2 = this;
				TSVector2 position = GetPosition();
				FP radius = 5;
				FP innerRadius = 3;
				FP angle = 240;
				FP rotation = GetRotation();
				skill_RunAwayBomb.AttackShape = skill_RunAwayBomb2.GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, rotation);
				AttackPosition = GetShapeRandomPoint(AttackShape, _actor, isReachable: true);
				PlayEffect("RunBomb_Shoot");
				FanMultipleShoot(BombName, alignShootDelay: 0, duration: 0, shootPosition: TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 2)), shootPositionY: 2, bulletDirectionOffset: 0, multipleShootStyle: AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, bulletCount: 1, multiShootDirection: GetPosition(), aimType: AimType.Position, bulletDirectionType: BulletDirectionType.BulletToTarget, angle: 1, radius: 1, innerRadius: 0, targetPosition: AttackPosition);
				yield return WaitTime(0.15);
			}
		}
	}
	public class Skill_RunningAway : SkillSimpleBase
	{
		private static readonly FP BackPointX = 4;

		private static readonly FP BackPointY = 10;

		private static readonly FP BackBrakeDistance = 0;

		private static readonly FP FrontPointX = 5;

		private static readonly FP FrontPointY = 12;

		private static readonly FP FrontBrakeDistance = 6;

		private static readonly FP DashSpeed = 30;

		private DeterministicShape RunShape;

		private TSVector2 RunPoint;

		private int RunPointIndex;

		private TSVector2 ChosenRunPoint;

		private TSVector2 ShapePositionRatio;

		private int RunMode;

		private TSVector2 StartDashDirection;

		private FP Ratio;

		private List<TSVector2> RunPointList;

		private FP BrakeDistance;

		private long Emoji;

		protected override void OnSkillEnable()
		{
			RunPointList = new List<TSVector2>();
			RunPointIndex = 0;
		}

		protected override void OnSkillDisable()
		{
			StopEffect(Emoji);
		}

		protected override IEnumerator DoMainLogic()
		{
			Emoji = PlayEffect("Run_Emoji");
			yield return WaitTime(0.5);
			GetRunPoint();
			if (RunMode == 1)
			{
				Ratio = -1;
			}
			else
			{
				Ratio = 1;
			}
			StartDashDirection = GetForward() * -Ratio;
			TSVector2 tSVector = TransLocalPosToWorldPos(ChosenRunPoint, (ChosenRunPoint - GetPosition()) * Ratio, new TSVector2(0, 100));
			FP fP = AngleBetween2TSVector(GetForward(), tSVector - ChosenRunPoint, signed: false);
			BeginDash(1, StartDashDirection, 2, 1, 999, comboWithAttack: false, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			PlayWwiseSound("mon_50801_brake");
			BeginLookAtByPos_NotWait(tSVector, 0.5, fP / 0.5);
			yield return WaitDashFinish();
			TSVector2 DashDirection = ChosenRunPoint - GetPosition();
			FP distance = Distance(GetPosition(), ChosenRunPoint);
			BeginDash(2, DashDirection, DashSpeed, distance, 0, comboWithAttack: false, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			BeginDash(3, DashDirection, 12, BrakeDistance, 999, comboWithAttack: false, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			BeginLookAt_NotWait(GetAttackTarget(), BrakeDistance / 12, 400);
			yield return WaitDashFinish();
			StopEffect(Emoji);
		}

		private void GetRunPoint()
		{
			ShapePositionRatio = new TSVector2(BackPointX, -BackPointY);
			CheckPositionValid(ShapePositionRatio);
			ShapePositionRatio = new TSVector2(-BackPointX, -BackPointY);
			CheckPositionValid(ShapePositionRatio);
			ShapePositionRatio = new TSVector2(FrontPointX, FrontPointY);
			CheckPositionValid(ShapePositionRatio);
			ShapePositionRatio = new TSVector2(-FrontPointX, FrontPointY);
			CheckPositionValid(ShapePositionRatio);
			ChosenRunPoint = RunPointList[0];
			if (RunPointIndex <= 1)
			{
				BrakeDistance = BackBrakeDistance;
				RunMode = 1;
			}
			else
			{
				BrakeDistance = FrontBrakeDistance;
				RunMode = 2;
			}
		}

		private void CheckPositionValid(TSVector2 ShapePositionRatio)
		{
			TSVector2 entityPosition = GetEntityPosition(GetAttackTarget());
			TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), entityPosition - GetPosition(), ShapePositionRatio);
			FP radius = 1;
			FP innerRadius = 0;
			RunShape = GetShapeData(DeterministicShape.ShapeType.Circle, tSVector, default(FP), default(FP), radius, innerRadius);
			RunPoint = GetShapeRandomPoint(RunShape, _actor, isReachable: true);
			if (RunPoint != tSVector)
			{
				RunPointList.Add(RunPoint);
			}
			else
			{
				RunPointIndex++;
			}
		}
	}
