			list.Add(new BaseBranchInfo(id3, default(FP), default(FP), default(FP), null, operateIEnumerator));
			int id4 = to1;
			operateIEnumerator = To1;
			list.Add(new BaseBranchInfo(id4, default(FP), default(FP), default(FP), null, operateIEnumerator));
			int id5 = to2;
