			}
			if (Mathf.Abs((float)AngleBetween2TSVector(GetForward(), GetEntityPosition(GetCurrentPlayer()) - GetPosition(), signed: true)) > 70f && Distance(GetPosition(), TSVector2.zero) >= 8)
			{
				yield return StartCor(BackJump());
