		private IEnumerator Appel2Zero()
		{
			_ = TSVector2.zero;
			_ = (FP)0;
			_ = (FP)0;
			_ = TSVector2.zero;
			int i = 0;
			int j = ((!(UnityEngine.Random.value < 0.5f)) ? 1 : (-1));
			while (i < 2)
			{
				TSVector2 zero = TSVector2.zero;
				TSVector2 tSVector = RotateTo(zero - GetPosition(), GetRandomValue(10, 30) * j);
				FP fP = Mathf.Clamp((float)Distance(tSVector, GetPosition()), 4f, 8f);
				FP speed = fP / 0.3;
				if (j < 0)
				{
					BeginAttack(AppelRIndex, AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
				}
				else
				{
					BeginAttack(AppelLIndex, AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
				}
				BeginDash(10, tSVector, speed, fP, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false, 0.2);
				BeginLookAtByPos_NotWait(zero, 0.25, 720);
				yield return WaitDashFinish();
				StopLookAt();
				i++;
				j *= -1;
			}
			yield return null;
			InterruptAttack();
		}

		private IEnumerator BackJump()
		{
			LogicEntity currentPlayer = GetCurrentPlayer();
			yield return BeginLookAtByPos(GetEntityPosition(currentPlayer), 0.05, 3600);
			BeginAttack(JumpBackIndex, JumpBackKey, flushInputedKeys: true, forceInterruptAttack: true);
			SetCloseBlockEnable();
			SetSearchedImmunityEnable();
			TSVector2 forward = GetForward();
			TSVector2 Direction = RotateTo(forward, 180);
			FP speed = 20.0;
			FP DIST = 10;
			FP angleLimit = 360;
			BeginDash(dashiIndex, Direction, speed, DIST, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitTime(0.4);
			SetSearchedImmunityDisable();
			for (int i = 0; i < 15; i++)
			{
				StopDash();
				speed += (FP)(-2.0);
				if (speed <= 0)
				{
					break;
				}
				BeginDash(dashiIndex, Direction, speed, DIST, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0.2);
				yield return WaitTime(0.02);
			}
			SetCloseBlockDisable();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return null;
		}

		private IEnumerator Appel()
		{
			Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer()));
			_ = TSVector2.zero;
			_ = (FP)0;
			_ = (FP)0;
			_ = TSVector2.zero;
			int i = 0;
			int j = ((!(UnityEngine.Random.value < 0.5f)) ? 1 : (-1));
			while (i < 2)
			{
				FP fP = Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer()));
				FP fP2 = AngleBetween2TSVector(GetForward(), GetEntityPosition(GetCurrentPlayer()) - GetPosition(), signed: true);
				if (fP <= 4)
				{
					TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetPosition() - GetEntityPosition(GetCurrentPlayer()), new TSVector2(0, 6));
					TSVector2 direction = RotateTo(tSVector, GetRandomValue(50, 80) * j);
					FP fP3 = Distance(tSVector, GetPosition());
					FP speed = fP3 / 0.3;
					if (j > 0)
					{
						BeginAttack(AppelRIndex, AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					else
					{
						BeginAttack(AppelLIndex, AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					BeginDash(10, direction, speed, fP3, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
					BeginLookAtByPos_NotWait(GetEntityPosition(GetCurrentPlayer()), 0.25, 720);
					yield return WaitDashFinish();
					StopLookAt();
				}
				else
				{
					TSVector2 direction;
					FP fP3;
					FP speed;
					if (fP <= 7 && fP > 4)
					{
						GetEntityPosition(GetCurrentPlayer());
						fP3 = 8;
						speed = fP3 / 0.3;
						if (fP2 > 0)
						{
							direction = RotateTo(GetEntityPosition(GetCurrentPlayer()) - GetPosition(), 40);
							BeginAttack(AppelLIndex, AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
						}
						else
						{
							direction = RotateTo(GetEntityPosition(GetCurrentPlayer()) - GetPosition(), -40);
							BeginAttack(AppelRIndex, AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
						}
						BeginDash(10, direction, speed, fP3, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
						BeginLookAtByPos_NotWait(GetEntityPosition(GetCurrentPlayer()), 0.25, 720);
						yield return WaitDashFinish();
						StopLookAt();
						break;
					}
					TSVector2 tSVector = GetEntityPosition(GetCurrentPlayer());
					direction = RotateTo(tSVector - GetPosition(), 40 * j);
					fP3 = Mathf.Clamp((float)Distance(direction, GetPosition()), 4f, 10f);
					speed = fP3 / 0.3;
					if (j < 0)
					{
						BeginAttack(AppelRIndex, AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					else
					{
						BeginAttack(AppelLIndex, AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					BeginDash(10, direction, speed, fP3, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
					BeginLookAtByPos_NotWait(tSVector, 0.25, 720);
					yield return WaitDashFinish();
					StopLookAt();
				}
				yield return null;
				i++;
				j *= -1;
			}
			yield return null;
		}
	}
	public class Skill_AlertMovement : JinDuanLiRongSkillBase
	{
		private TSVector2 targetPOS;

		private LogicEntity target;

		private string alertTypeName = "AlertType";

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			targetPOS = MoveTargetPOS();
			target = GetTarget();
			switch ((int)(long)GetLogicTagFpValue(_actor, alertTypeName))
			{
			case 0:
				yield return StartCor(AlertMove());
				break;
			case 1:
				yield return StartCor(AlertLookAt());
				break;
			default:
				yield return StartCor(AlertMove());
				break;
			}
		}

		private IEnumerator AlertMove()
		{
			AimAtTarget(target, 180f);
			MoveToPosition(targetPOS, 0.5, AdventureActor.MovementMode.Walk, 4f);
			yield return WaitMoveStatus();
			CancelAim();
		}

		private IEnumerator AlertLookAt()
		{
			BeginAttack(JinDuanLiRongSkillBase.idleIndex, JinDuanLiRongSkillBase.idle2Key, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 99, 180);
			yield return WaitTime(GetRandomValue(1.5, 2.5));
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopLookAt();
		}

		private TSVector2 MoveTargetPOS()
		{
			TSVector2 zero = TSVector2.zero;
			TSVector2 entityPosition = GetEntityPosition(GetCurrentPlayer());
			TSVector2 position = GetPosition();
			FP radius = 12;
			FP innerRadius = 9;
			FP angle = 60;
			FP tSVectToAngle = GetTSVectToAngle(position - entityPosition, 0);
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, tSVectToAngle);
			for (int i = 0; i < 5; i++)
			{
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			for (int j = 0; j < 5; j++)
			{
				FP fP = ((!(GetRandomValue(0, 1) < 0.5)) ? 1 : (-1));
				tSVectToAngle = 12;
				angle = 9;
				innerRadius = 15;
				radius = GetTSVectToAngle(entityPosition - position, 40 * fP);
				shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), tSVectToAngle, angle, innerRadius, radius);
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			return TSVector2.zero;
		}
	}
