	public class Skill_Cyclone_SC : SkillSimpleBase
	{
		private string hitEffect = "fx_50601JinDuanLiRong_hit_Skill01";

		private CoroutineNode damageCor;

		private CoroutineNode CycloneMoveCor;

		private bool selfForward;

		private bool isMoveFinish;

		protected override void OnSkillEnable()
		{
			selfForward = false;
			isMoveFinish = false;
			SetImmuneControlEnable();
			SetUnparalleledEnable();
			SetCloseBlockEnable();
		}

		protected override void OnSkillDisable()
		{
			StopCor(CycloneMoveCor);
			StopCor(damageCor);
		}

		protected override IEnumerator DoMainLogic()
		{
			long ljf = PlayEffect("fx_50601JinDuanLiRong_bullet_Cyclone");
			bool flag = false;
			if (GetTargetByTeammateIndex(0) != null && GetTargetByTeammateIndex(0).Count > 0)
			{
				flag = GetLogicTagToggleValue(GetTargetByTeammateIndex(0)[0], "IsLeftMove");
			}
			if (flag)
			{
				yield return BeginRotateAngle(60, 600);
				selfForward = true;
			}
			else
			{
				yield return BeginRotateAngle(-60, 600);
			}
			CycloneMoveCor = StartCor(CycloneMove());
			damageCor = StartCor(Damage());
			for (int i = 0; i < 100; i++)
			{
				if (isMoveFinish)
				{
					StopCor(CycloneMoveCor);
					break;
				}
				yield return WaitTime(0.1);
			}
			List<LogicEntity> actorList = new List<LogicEntity> { _actor };
			StopEffect(ljf);
			StopCor(damageCor);
			PlayEffect("fx_50601JinDuanLiRong_bullet_Cyclone_end ");
			yield return WaitTime(3);
			KillActors(actorList);
		}

		protected IEnumerator Damage()
		{
			for (int i = 0; i < 1000; i++)
			{
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, GetPosition(), default(FP), default(FP), 2);
				Skill_Cyclone_SC skill_Cyclone_SC = this;
				FP hitStrenth = 2;
				HitFeatureData hitFeatureData = skill_Cyclone_SC.GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, hitStrenth);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50601092, 0.5, HitBox.HurtAnimType.Small, hitEffect);
				yield return WaitTime(0.1);
			}
			yield return null;
		}

		protected IEnumerator CycloneMove()
		{
			FP dashSpeed = 5;
			while (true)
			{
				dashSpeed = Mathf.Clamp((float)dashSpeed, 5f, 100f);
				BeginDashActorForward(10, dashSpeed, 99, 999, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
				if (selfForward)
				{
					BeginRotateAngle_NotWait(13, 160);
				}
				else
				{
					BeginRotateAngle_NotWait(-13, 160);
				}
				yield return WaitTime(0.1);
				StopDash();
				dashSpeed += (FP)1.15;
			}
		}

		protected override void DashFinishByObstacle(int index)
		{
			if (index == 10)
			{
				isMoveFinish = true;
			}
		}
	}
	public class Skill_Die : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Z };

		private static readonly string airBorneDeathEffectAlias = "fx_common_base_die_airborne";

		private static readonly FP effectDuration = 2f;

		protected override IEnumerator DoMainLogic()
		{
			List<LogicEntity> list = new List<LogicEntity>();
			list.AddRange(GetTargetsByFaction(isFriend: true));
			if (list != null && list.Count > 0)
			{
				KillActors(list);
			}
			SetCloseBlockEnable();
			SendDeclareDeadEvent();
			if (DieWithAirBorne() && !_actor.IsBossMonster())
			{
				_actor.PlayHurtAnim();
				PlayEffect(airBorneDeathEffectAlias, 1f, _actor.tsTransform.PositionY, _actor.tsTransform.Position, (_actor.killer != null) ? _actor.killer.tsTransform.Rotation : _actor.tsTransform.Rotation);
				yield return WaitTime(1);
			}
			else
			{
				_actor.PlayDeathAnim();
				BeginAttack(1, actionKeys);
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
		}

		private bool DieWithAirBorne()
		{
			if (_actor.movementState == ActorState.Jump)
			{
				return true;
			}
			if (_actor.killerHitBox == null)
			{
				return false;
			}
			if ((_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.KnockBack) == HitBox.FeatureFlag.KnockBack)
			{
				return true;
			}
			return (_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.AirBorne) == HitBox.FeatureFlag.AirBorne;
		}
	}
	public class Skill_FA : JinDuanLiRongSkillBase
	{
		private string diffusionBubble = "50601JinDuanLiRong_DiffusionBubble";

		private string sound = "mon_50601_JC2_greencircle";

		private string areaEffect = "RepelExplosiveRing";

		private string fbxFire = "fx_common_base_Fire_YuJing_circular_8";

		private List<LogicEntity> teamMateList = new List<LogicEntity>();

		private List<long> fxList = new List<long>();

		private long weapondieFx;

		private CoroutineNode RingCor;

		private CoroutineNode ScoreCor;

		private int aiType;

		private bool interrupt;

		private readonly string decorativeRib = "fx_50601JinDuanLiRong_loop_FA_shuizi_Area";

		private long ribFxID;

		protected override void OnSkillEnable()
		{
			aiType = GetAiType();
			interrupt = true;
		}

		protected override void OnSkillDisable()
		{
			if (interrupt)
			{
				StopCor(ScoreCor);
				SetLogicTagToggleValue(_actor, In_CheckBossScro_Tag2, value: false);
			}
			if (fxList.Count > 0)
			{
				for (int i = 0; i < fxList.Count; i++)
				{
					StopEffect(fxList[i]);
				}
			}
			StopCor(RingCor);
			teamMateList.Clear();
			fxList.Clear();
			teamMateList.AddRange(GetTargetByTeammateIndexes(new List<int> { 2, 3, 4 }));
			if (teamMateList.Count > 0 && teamMateList != null)
			{
				for (int j = 0; j < teamMateList.Count; j++)
				{
					SetLogicTagToggleValue(teamMateList[j], "Stop", value: true);
				}
			}
			StopEffect(ribFxID);
			ModelNodeShow("comb", isShow: true);
			ModelNodeShow("clipper", isShow: true);
			ModelNodeShow("drier", isShow: true);
		}

		protected override IEnumerator DoMainLogic()
		{
			PlayWwiseSound("mon_50601_transform2");
			yield return StartCor(Switch());
			yield return StartCor(Return());
			BeginAttack(JinDuanLiRongSkillBase.FAIndex, JinDuanLiRongSkillBase.FAKey, flushInputedKeys: true, forceInterruptAttack: true);
			PlayEffect("fx_common_warning_square_3side_2x17.5_start", 1f, default(FP), TSVector2.zero, GetTSVectToAngle(TSVector2.left, 0));
			PlayEffect("fx_common_warning_square_3side_2x17.5_start", 1f, default(FP), TSVector2.zero, GetTSVectToAngle(TSVector2.right, 0));
			ribFxID = PlayEffect(decorativeRib, 1f, default(FP), TSVector2.zero);
			yield return WaitTime(0.5);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			FASummonMate();
			if (aiType == 3)
			{
				ScoreCor = StartCor(ScoreCheck());
			}
			for (int i = 0; i < fxList.Count; i++)
			{
				StopEffect(fxList[i]);
			}
			yield return WaitTime(2);
			RingCor = StartCor(ExplosiveRing());
			yield return WaitTime(10);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			teamMateList.AddRange(GetTargetByTeammateIndexes(new List<int> { 2, 3, 4 }));
			for (int j = 0; j < teamMateList.Count; j++)
			{
				SetLogicTagToggleValue(teamMateList[j], "Stop", value: true);
			}
			StopCor(ScoreCor);
			interrupt = false;
			SetLogicTagToggleValue(_actor, In_CheckBossScro_Tag2, value: false);
			StopEffect(ribFxID);
		}

		private void FASummonMate()
		{
			SetLogicTagToggleValue(_actor, In_CheckBossScro_Tag2, value: true);
			SummonTeammate(2, new TSVector2(-2, 0), new TSVector2(1, 0));
			SummonTeammate(2, new TSVector2(2, 0), new TSVector2(-1, 0));
			SummonTeammate(3, new TSVector2(-8, 0), new TSVector2(7, 0));
			SummonTeammate(3, new TSVector2(8, 0), new TSVector2(-7, 0));
			SummonTeammate(4, new TSVector2(-13.5, 0), new TSVector2(12.5, 0));
			SummonTeammate(4, new TSVector2(13.5, 0), new TSVector2(-12.5, 0));
		}

		private IEnumerator Switch()
		{
			BeginAttack(JinDuanLiRongSkillBase.SwitchIndex, JinDuanLiRongSkillBase.SwitchKey, flushInputedKeys: true, forceInterruptAttack: true);
			weapondieFx = PlayEffect("fx_50601JinDuanLiRong_base_JC_weapondie");
			yield return WaitTime(0.5);
			ModelNodeShow("comb", isShow: false);
			ModelNodeShow("clipper", isShow: false);
			ModelNodeShow("drier", isShow: false);
		}

		private IEnumerator Return()
		{
			BeginAttack(JinDuanLiRongSkillBase.ReturnIndex, JinDuanLiRongSkillBase.ReturnKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			SetHideModelEnable();
			SetSearchedImmunityEnable();
			SetCloseBlockEnable();
			SetUnparalleledEnable();
			yield return WaitTime(1);
			Teleport(TSVector2.zero);
			SetHideModelDisable();
			SetSearchedImmunityDisable();
			SetCloseBlockDisable();
			SetUnparalleledDisable();
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			if (GetAiType() == 1)
			{
				yield return WaitTime(0.5);
			}
		}

		private IEnumerator ExplosiveRing()
		{
			for (int i = 0; i < 3; i++)
			{
				fxList.Add(PlayEffect(fbxFire, 0.3f, default(FP), TSVector2.zero));
				yield return WaitTime(3.6);
				PlayAreaEffect(areaEffect, GetPosition(), GetRotation());
				int num = 1;
				int bulletCount = 36;
				FP angle = 360;
				for (int j = 0; j < num; j++)
				{
					TSVector2 multiShootDirection = RotateTo(GetForward(), 360 / num * j);
					FanMultipleShoot(diffusionBubble, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, bulletCount, 0, GetPosition(), 0, multiShootDirection, 0, AimType.Default, BulletDirectionType.ActorToBullet, angle, 0, 8);
					PlayWwiseSound(sound);
				}
				yield return WaitTime(0.5);
			}
		}

		private IEnumerator ScoreCheck()
		{
			yield return WaitTime(2);
			while (true)
			{
				yield return StartCor(ScoreLogicTag2());
				yield return WaitTime(0.4);
			}
		}
	}
	public class Skill_FA_CycloneATK : JinDuanLiRongSkillBase
	{
		protected override IEnumerator DoMainLogic()
		{
			yield return StartCor(SummonMate());
