	public class Skill_FA_ScoreCloneActor : SkillSimpleBase
	{
		private bool corState;

		private CoroutineNode ScoreCheckCor;

		private LogicEntity master;

		private List<LogicEntity> mateList = new List<LogicEntity>();

		private readonly string in_CheckBossScro_Tag1 = "In_CheckBossScro_Tag1";

		protected override void OnSkillEnable()
		{
			corState = false;
			master = GetMonsterCloner();
		}

		protected override void OnSkillDisable()
		{
			if (corState)
			{
				StopCor(ScoreCheckCor);
			}
			mateList.Clear();
			SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: false);
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return WaitTime(0.3);
			FP mateCount = GetLogicTagFpValue(master, "SummonsCount");
			for (int i = 0; i < 10; i++)
			{
				if (GetTargetsByFaction(isFriend: true) != null && GetTargetsByFaction(isFriend: true).Count >= mateCount + 1)
				{
					foreach (LogicEntity item in GetTargetsByFaction(isFriend: true))
					{
						if (GetLogicTagToggleValue(item, "Summons"))
						{
							mateList.Add(item);
						}
					}
					break;
				}
				yield return WaitTime(0.2);
			}
			corState = true;
			ScoreCheckCor = StartCor(ScoreLogicTag());
			while (true)
			{
				if (mateList[0].IsDead() || master.IsDead())
				{
					InterruptSkill();
				}
				yield return WaitTime(0.2);
			}
		}

		private IEnumerator ScoreLogicTag()
		{
			yield return WaitTime(2);
			for (int i = 0; i < 6; i++)
			{
				SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: true);
				yield return WaitTime(2.1);
				SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: false);
				yield return WaitTime(1);
			}
			corState = false;
		}
	}
	public class Skill_FirstAttack : JinDuanLiRongSkillBase
	{
		private CoroutineNode DamageCor;

		private LogicEntity target;

		private FP maxSpeed;

		private FP speed;

		private FP distance;

		protected override void OnSkillEnable()
		{
			ModelNodeShow("drier", isShow: false);
			maxSpeed = 0;
			speed = 0;
		}

		protected override void OnSkillDisable()
		{
			StopCor(DamageCor);
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return StartCor(ChargeATK());
		}

		protected IEnumerator ChargeATK()
		{
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				target = GetAttackTarget();
			}
			else
			{
				target = GetCurrentPlayer();
			}
			BeginAttack(JinDuanLiRongSkillBase.chargeIndex, JinDuanLiRongSkillBase.chargeKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.5, 360);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(0.1);
			CancelAttack();
			yield return WaitTime(0.16);
			PlayEffect(warningFx, 1f, 3, GetPosition(), default(FP), 3f);
			yield return WaitTime(0.3);
			bool dashBranch = false;
			if (Distance(GetPosition(), GetEntityPosition(target)) <= 5.5)
			{
				dashBranch = true;
				distance = 10;
				maxSpeed = 25;
			}
			else
			{
				distance = 27;
				maxSpeed = 40;
			}
			DamageCor = StartCor(Damage());
			for (int i = 0; i < 11; i++)
			{
				if (i < 7)
				{
					if (dashBranch)
					{
						speed = Mathf.Clamp((float)speed + 8f, 0f, 50f);
					}
					else
					{
						speed = Mathf.Clamp((float)speed + 14f, 0f, 80f);
						BeginLookAt_NotWait(target, 0.02, 150);
					}
				}
				else if (dashBranch)
				{
					speed = Mathf.Clamp((float)speed - 6f, 0f, 100f);
				}
				else
				{
					speed = Mathf.Clamp((float)speed - 20f, 0f, 100f);
					BeginLookAt_NotWait(target, 0.02, 150);
				}
				BeginDashActorForward(10, speed, distance, 2, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
				yield return WaitTime(0.02);
				if (speed <= 0)
				{
					StopLookAt();
					StopDash();
					break;
				}
				StopDash();
				StopLookAt();
			}
			StopCor(DamageCor);
			StopDash();
			StopLookAt();
			yield return WaitTime(0.55);
			BeginLookAt_NotWait(target, 0.4, 400);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopLookAt();
			yield return null;
		}

