	public class Skill_Kick : JinDuanLiRongSkillBase
	{
		private FP AngleBetween;

		private CoroutineNode DamageCor;

		private LogicEntity target;

		private Dash dash;

		private readonly int DashIndex = 10;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			StopCor(DamageCor);
		}

		protected override IEnumerator DoMainLogic()
		{
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				target = GetAttackTarget();
			}
			else
			{
				target = GetCurrentPlayer();
			}
			yield return StartCor(Move());
			yield return StartCor(KickFlow());
		}

		protected IEnumerator Damage()
		{
			for (int i = 0; i < 1; i++)
			{
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, GetPosition(), default(FP), default(FP), 10, default(FP), 240, GetRotation());
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50601086, 0.5, HitBox.HurtAnimType.Small, "fx_50601JinDuanLiRong_hit_Skill01");
				yield return WaitTime(0.05);
			}
			yield return null;
		}

		protected IEnumerator BackJump()
		{
			yield return BeginLookAtByPos(GetEntityPosition(target), 0.05, 3600);
			BeginAttack(JinDuanLiRongSkillBase.JumpBackIndex, JinDuanLiRongSkillBase.JumpBackKey, flushInputedKeys: true, forceInterruptAttack: true);
			SetCloseBlockEnable();
			SetSearchedImmunityEnable();
			TSVector2 forward = GetForward();
			TSVector2 Direction = RotateTo(forward, 180);
			FP speed = 20.0;
			FP DIST = 10;
			FP angleLimit = 360;
			dash = BeginDash(DashIndex, Direction, speed, DIST, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitTime(0.4);
			SetSearchedImmunityDisable();
			for (int i = 0; i < 15; i++)
			{
				StopDash();
				speed += (FP)(-2.0);
				if (speed <= 0)
				{
					break;
				}
				BeginDash(DashIndex, Direction, speed, DIST, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0.2);
				yield return WaitTime(0.02);
			}
			SetCloseBlockDisable();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return StartCor(KickFlow());
		}

		protected IEnumerator Appel()
		{
			Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer()));
			_ = TSVector2.zero;
			_ = (FP)0;
			_ = (FP)0;
			_ = TSVector2.zero;
			int i = 0;
			int j = ((!(UnityEngine.Random.value < 0.5f)) ? 1 : (-1));
			while (i < 2)
			{
				FP fP = Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer()));
				AngleBetween = AngleBetween2TSVector(GetForward(), GetEntityPosition(GetCurrentPlayer()) - GetPosition(), signed: true);
				if (fP <= 5)
				{
					TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetPosition() - GetEntityPosition(GetCurrentPlayer()), new TSVector2(0, 4));
					TSVector2 direction = RotateTo(tSVector, GetRandomValue(50, 80) * j);
					FP fP2 = Distance(tSVector, GetPosition());
					FP speed = fP2 / 0.35;
					if (j > 0)
					{
						BeginAttack(JinDuanLiRongSkillBase.AppelRIndex, JinDuanLiRongSkillBase.AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					else
					{
						BeginAttack(JinDuanLiRongSkillBase.AppelLIndex, JinDuanLiRongSkillBase.AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					BeginDash(10, direction, speed, fP2, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
					BeginLookAtByPos_NotWait(GetEntityPosition(GetCurrentPlayer()), 0.25, 720);
					yield return WaitDashFinish();
					StopLookAt();
				}
				else
				{
					TSVector2 direction;
					FP fP2;
					FP speed;
					if (fP <= 7)
					{
						GetEntityPosition(GetCurrentPlayer());
						fP2 = 8;
						speed = fP2 / 0.35;
						if (AngleBetween > 0)
						{
							direction = RotateTo(GetEntityPosition(GetCurrentPlayer()) - GetPosition(), 30);
							BeginAttack(JinDuanLiRongSkillBase.AppelLIndex, JinDuanLiRongSkillBase.AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
						}
						else
						{
							direction = RotateTo(GetEntityPosition(GetCurrentPlayer()) - GetPosition(), -30);
							BeginAttack(JinDuanLiRongSkillBase.AppelRIndex, JinDuanLiRongSkillBase.AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
						}
						BeginDash(10, direction, speed, fP2, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
						BeginLookAtByPos_NotWait(GetEntityPosition(GetCurrentPlayer()), 0.25, 720);
						yield return WaitDashFinish();
						StopLookAt();
						break;
					}
					TSVector2 tSVector = GetEntityPosition(GetCurrentPlayer());
					direction = RotateTo(tSVector - GetPosition(), 40 * j);
					fP2 = Mathf.Clamp((float)Distance(direction, GetPosition()), 4f, 10f);
					speed = fP2 / 0.35;
					if (j < 0)
					{
						BeginAttack(JinDuanLiRongSkillBase.AppelRIndex, JinDuanLiRongSkillBase.AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					else
					{
						BeginAttack(JinDuanLiRongSkillBase.AppelLIndex, JinDuanLiRongSkillBase.AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
					}
					BeginDash(10, direction, speed, fP2, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
					BeginLookAtByPos_NotWait(tSVector, 0.25, 720);
					yield return WaitDashFinish();
					StopLookAt();
				}
				yield return null;
				i++;
				j *= -1;
			}
			yield return null;
		}

		protected IEnumerator Appel2Zero()
		{
			_ = TSVector2.zero;
			_ = (FP)0;
			_ = (FP)0;
			_ = TSVector2.zero;
			int i = 0;
			int j = ((!(UnityEngine.Random.value < 0.5f)) ? 1 : (-1));
			while (i < 2)
			{
				TSVector2 zero = TSVector2.zero;
				TSVector2 tSVector = RotateTo(zero - GetPosition(), GetRandomValue(10, 30) * j);
				FP fP = Mathf.Clamp((float)Distance(tSVector, GetPosition()), 4f, 8f);
				FP speed = fP / 0.3;
				if (j < 0)
				{
					BeginAttack(JinDuanLiRongSkillBase.AppelRIndex, JinDuanLiRongSkillBase.AppelRKey, flushInputedKeys: true, forceInterruptAttack: true);
				}
				else
				{
					BeginAttack(JinDuanLiRongSkillBase.AppelLIndex, JinDuanLiRongSkillBase.AppelLKey, flushInputedKeys: true, forceInterruptAttack: true);
				}
				BeginDash(10, tSVector, speed, fP, 99999, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false, 0.2);
				BeginLookAtByPos_NotWait(zero, 0.25, 720);
				yield return WaitDashFinish();
				StopLookAt();
				i++;
				j *= -1;
			}
			yield return StartCor(KickFlow());
			yield return null;
		}

		protected IEnumerator KickFlow()
		{
			BeginAttack(JinDuanLiRongSkillBase.KickIndex, JinDuanLiRongSkillBase.KickKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAtByPos_NotWait(GetEntityPosition(target), 0.3, 450);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayEffect("fx_50601JinDuanLiRong_base_Skill03_A_warning", 0.8f, default(FP), GetPosition(), GetRotation());
			yield return WaitTime(1.2);
			CancelAttack();
			PlayEffect(warningFx, 1f, 3, GetPosition(), default(FP), 3f);
