				HitFeatureData hitFeatureData = skill_LJF_Outside.GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, hitStrenth);
