				Skill_NormalAttack_SC skill_NormalAttack_SC = this;
				FP hitStrenth = 2;
				HitFeatureData hitFeatureData = skill_NormalAttack_SC.GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, hitStrenth);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50601093, 0.5, HitBox.HurtAnimType.Small, "fx_50601JinDuanLiRong_hit_Skill01");
				yield return WaitTime(0.05);
			}
			yield return null;
		}

		protected IEnumerator Summon()
		{
			if ((int)(long)GetRandomValue(0, 1.5, isInt: true) == 0)
			{
				summonPOSList = new List<TSVector2>
				{
					new TSVector2(0, 8),
					RotateTo(new TSVector2(0, 8), 120),
					RotateTo(new TSVector2(0, 8), -120)
				};
				SetLogicTagToggleValue(_actor, "IsLeftMove", value: true);
			}
			else
			{
				summonPOSList = new List<TSVector2>
				{
					RotateTo(new TSVector2(0, 8), 45),
					RotateTo(RotateTo(new TSVector2(0, 8), 120), 45),
					RotateTo(RotateTo(new TSVector2(0, 8), -120), 45)
				};
				SetLogicTagToggleValue(_actor, "IsLeftMove", value: false);
			}
			for (int i = 0; i < summonPOSList.Count; i++)
			{
				if (QueryPositionReachable(_actor, summonPOSList[i]))
				{
					fxList.Add(PlayEffect("fx_common_base_Fire_YuJing_circular_2", 0.5f, default(FP), summonPOSList[i], GetTSVectToAngle(summonPOSList[i] - TSVector2.zero, 0)));
				}
			}
			yield return WaitTime(2.2);
			for (int j = 0; j < summonPOSList.Count; j++)
			{
				if (QueryPositionReachable(_actor, summonPOSList[j]))
				{
					SummonTeammate(1, summonPOSList[j], summonPOSList[j] - TSVector2.zero);
				}
			}
			if (GetAiType() != 3)
			{
				yield break;
			}
			FP mateCount = 3;
			SetLogicTagFpValue(_actor, "SummonsCount", mateCount);
			UseMonsterCloneActorCastSkill(5060136);
			for (int k = 0; k < 10; k++)
			{
				if (GetTargetByTeammateIndex(1) != null && GetTargetByTeammateIndex(1).Count == mateCount)
				{
					foreach (LogicEntity item in GetTargetByTeammateIndex(1))
					{
						SetLogicTagToggleValue(item, "Summons", value: true);
					}
					break;
				}
				yield return WaitTime(0.2);
			}
		}
	}
	public class Skill_SC_ScoreCloneActor : SkillSimpleBase
	{
		private bool corState;

		private CoroutineNode ScoreCheckCor;

		private LogicEntity master;

		private List<LogicEntity> mateList = new List<LogicEntity>();

		private readonly string in_CheckBossScro_Tag1 = "In_CheckBossScro_Tag1";

		protected override void OnSkillEnable()
		{
			corState = false;
			master = GetMonsterCloner();
		}

		protected override void OnSkillDisable()
		{
			if (corState)
			{
				StopCor(ScoreCheckCor);
			}
			mateList.Clear();
			SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: false);
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return WaitTime(0.3);
			FP mateCount = GetLogicTagFpValue(master, "SummonsCount");
			for (int i = 0; i < 10; i++)
			{
				if (GetTargetsByFaction(isFriend: true) != null && GetTargetsByFaction(isFriend: true).Count >= mateCount + 1)
				{
					foreach (LogicEntity item in GetTargetsByFaction(isFriend: true))
					{
						if (GetLogicTagToggleValue(item, "Summons"))
						{
							mateList.Add(item);
						}
					}
					break;
				}
				yield return WaitTime(0.2);
			}
			corState = true;
			ScoreCheckCor = StartCor(ScoreLogicTag());
			while (true)
			{
				if (mateList[0].IsDead() || master.IsDead())
				{
					InterruptSkill();
				}
				yield return WaitTime(0.2);
			}
		}

		private IEnumerator ScoreLogicTag()
		{
			for (int i = 0; i < 1; i++)
			{
				SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: true);
				yield return WaitTime(2.1);
				SetLogicTagToggleValue(master, in_CheckBossScro_Tag1, value: false);
				yield return WaitTime(1);
			}
			corState = false;
		}
	}
