				}
				for (int i = 0; i < times; i++)
				{
					if (phaseTag == 1)
					{
						if (i == 0 || i == 2)
						{
							yield return StartCor(AreaATK());
						}
						else
						{
							yield return WaitTime(2.5);
						}
					}
					else
