		protected IEnumerator Return()
		{
			BeginAttack(JinDuanLiRongSkillBase.SwitchArmsnIndex, JinDuanLiRongSkillBase.SwitchArmsKey, flushInputedKeys: true, forceInterruptAttack: true);
