			yield return WaitTime(0.5);
			BeginAttack(1, Spawn_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			SetHideModelDisable();
			yield return WaitCustomEvent("BattleStart");
			SetBattleOutDisable();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
