	public class Skill_SpinShoot : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] SpinShoot_Combo_D2 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.G };

		private static readonly ComboInputBuffer.ActionKey[] SpinShoot_Combo_D1 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.L };

		private static readonly ComboInputBuffer.ActionKey[] SpinShoot_Combo_D3 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.M };

		private static readonly FP RotateTimeP1 = 1;

		private static readonly FP RotateTimeP2 = 2;

		private static readonly FP DashSpeed = 2;

		private static readonly FP SkillRadius = 4;

		private FP Phase;

		private FP RotateTime;

		private FP RotateDuration;

		private TSVector2 DashDirection;

		private ComboInputBuffer.ActionKey[] SpinShoot_Combo;

		private FP Difficulty;

		protected override void OnSkillEnable()
		{
			Phase = GetLogicTagFpValue(_actor, "Phase");
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
			if (Phase == 1)
			{
				RotateTime = RotateTimeP1;
			}
			else
			{
				RotateTime = RotateTimeP2;
			}
			if (Difficulty == 3)
			{
				RotateTime = RotateTimeP1;
			}
			RotateDuration = RotateTime;
			if (Difficulty == 1)
			{
				SpinShoot_Combo = SpinShoot_Combo_D1;
			}
			else if (Difficulty == 2)
			{
				SpinShoot_Combo = SpinShoot_Combo_D2;
			}
			else if (Difficulty == 3)
			{
				SpinShoot_Combo = SpinShoot_Combo_D3;
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			TSVector2 tSVector = GetEntityPosition(GetAttackTarget()) - GetPosition();
			TSVector2 position = TransLocalPosToWorldPos(GetPosition(), tSVector * -1, new TSVector2(0, RotateDuration * DashSpeed));
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: false) <= SkillRadius && QueryPositionReachable(_actor, position))
			{
				DashDirection = -tSVector;
			}
			else
			{
				DashDirection = tSVector;
			}
			BeginAttack(1, SpinShoot_Combo, flushInputedKeys: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginDash(1, DashDirection, DashSpeed, DashSpeed * RotateDuration, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			CancelAttack();
			WaitLookAt_NoWait(GetAttackTarget(), 999, 360);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopWaitLookAt();
		}
	}
	public class Skill_StormBlade : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] StormBlade_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.I };

		private static readonly int LoopAmount = 15;

		private static readonly int BalloonAmount = 12;

		private static readonly FP MaxDistance = 12;

		private static readonly FP MinDistance = 11;

		private static readonly FP MoveSpeed = 1.5;

		private int LoopCount;

		private int BalloonCount;

		private FP CurrentRotation;

		private TSVector2 CenterPosition;

		private long AreaEffect_Ultra_Attack;

		private CoroutineNode PullCor;

		private bool IsInterrupted;

		private FP Difficulty;

		protected override void OnSkillEnable()
		{
			CenterPosition = GetPlaceHolderPosition("CenterPoint");
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
			CurrentRotation = 180 / BalloonAmount + 90;
			LoopCount = 0;
			BalloonCount = 0;
			IsInterrupted = true;
		}

		protected override void OnSkillDisable()
		{
			if (IsInterrupted)
			{
				AddBuffToTarget(_actor, 505719913);
				StopAreaEffect(AreaEffect_Ultra_Attack);
				StopCor(PullCor);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, StormBlade_Combo, flushInputedKeys: true);
			TSVector2 Dir = GetPosition() - GetPlaceHolderPosition("CenterPoint");
			FP Dis = Distance(GetPosition(), GetPlaceHolderPosition("CenterPoint"));
			if (Dis >= 2)
			{
				BeginLookAtByDir_NotWait(Dir, 0, 450);
			}
			yield return WaitCustomEvent("StartDash");
			BeginDash(1, -Dir, Dis / 0.5, Dis, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			BeginLookAtByDir(TSVector2.down, 0, 200);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			if (GetLogicTagToggleValue(_actor, "IsFirstInPhase2"))
			{
				AddBuffToTarget(_actor, 505719914);
				SetLogicTagToggleValue(_actor, "IsFirstInPhase2", value: false);
			}
			else
			{
				AddBuffToTarget(_actor, 505719912);
			}
			StartCor(ref PullCor, Pull());
			AreaEffect_Ultra_Attack = PlayAreaEffect("AreaEffect_Ultra_Attack", GetPosition());
			StartCor(SummonBalloon());
			while (LoopCount < LoopAmount)
			{
				yield return null;
			}
			yield return WaitCustomEvent("LoopEnd");
			CancelAttack();
			AddBuffToTarget(_actor, 505719913);
			StopAreaEffect(AreaEffect_Ultra_Attack);
			StopCor(PullCor);
			IsInterrupted = false;
			yield return WaitCombo(ComboAttackType.isComboFinish);
			if (Difficulty == 1 || Difficulty == 2)
			{
				yield return BeginLookAtMonsterTarget(0.5, 180);
				yield return BeginLookAtMonsterTarget(2.5, 90);
			}
		}

		protected override void OnComboLoop(int comboIndex)
		{
			LoopCount++;
		}

		private IEnumerator SummonBalloon()
		{
			while (BalloonCount < BalloonAmount)
			{
				Skill_StormBlade skill_StormBlade = this;
				TSVector2 centerPosition = CenterPosition;
				FP maxDistance = MaxDistance;
				FP minDistance = MinDistance;
				FP angle = 360 / BalloonAmount;
				FP currentRotation = CurrentRotation;
				DeterministicShape shapeData = skill_StormBlade.GetShapeData(DeterministicShape.ShapeType.Fan, centerPosition, default(FP), default(FP), maxDistance, minDistance, angle, currentRotation);
				TSVector2 shapeRandomPoint = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				SummonTeammate(1, shapeRandomPoint, RotateTo(TSVector2.down, GetRandomValue(0, 180)));
				CurrentRotation += (FP)(360 / BalloonAmount);
				BalloonCount++;
				yield return WaitTime(0.4);
			}
		}

		private IEnumerator Pull()
		{
			while (true)
			{
				ILRuntimeAPI.ForceMoveByDistanceToPosition(_actor, GetPosition(), GetTargetsByFaction(isFriend: false), MoveSpeed * 0.1, MoveSpeed, 4, 20, isPull: true, withRadius: false, isCoExist: true, isChangeForward: false);
				ILRuntimeAPI.ForceMoveByDistanceToPosition(_actor, GetPosition(), GetTargetsByFaction(isFriend: true).Except(GetTargetByBuffID(505719901)).ToList(), MoveSpeed * 0.1, MoveSpeed, 4, 30, isPull: true, withRadius: false, isCoExist: true, isChangeForward: false);
				yield return WaitTime(0.1);
			}
		}
	}
	public class Skill_WindBlade : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] WindBlade_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.J };

		private static readonly List<TSVector2> BalloonPositionOffset = new List<TSVector2>
		{
			new TSVector2(2.5, 4),
			new TSVector2(1.25, 4),
			new TSVector2(0, 4),
			new TSVector2(-1.25, 4),
			new TSVector2(-2.5, 4)
		};

		private FP Difficulty;

		protected override void OnSkillEnable()
		{
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return BeginLookAt(GetAttackTarget(), 0, 200);
			BeginAttack(1, WindBlade_Combo, flushInputedKeys: true);
			if (Difficulty == 3)
			{
				foreach (TSVector2 item in BalloonPositionOffset)
				{
					TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), item);
					if (QueryPositionReachable(_actor, tSVector))
					{
						SummonTeammate(2, tSVector, tSVector - GetPosition());
					}
				}
			}
			if (Difficulty != 3)
			{
				WaitLookAt_NoWait(GetAttackTarget(), 999, 50);
			}
			yield return WaitCustomEvent("StopTurn");
			Skill_WindBlade skill_WindBlade = this;
			TSVector2 position = GetPosition();
			FP rotation = GetRotation();
			skill_WindBlade.PlayEarlyWarningEffect("CrushWarningLine2", 0.76f, default(FP), position, rotation, 0.75f);
			StopWaitLookAt();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
