	public class Skill_WindBlast_Lv3 : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] WindBlast_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.K };

		private static readonly float ZoneFXSizeP1 = 1f;

		private static readonly float ZoneFXSizeP2 = 1.2f;

		private static readonly float GroundFXSizeP1 = 1.2f;

		private static readonly float GroundFXSizeP2 = 1.44f;

		private static readonly FP LoopWaitTimeP1 = 0.5;

		private static readonly FP LoopWaitTimeP2 = 1.5;

		private static readonly int BallonAmout = 5;

		private FP Phase;

		private long ZoneFX;

		private long WindBallFX;

		private long WindBallArea;

		private float ZoneFXSize;

		private float GroundFXSize;

		private FP LoopWaitTime;

		private FP WindBallGroundFXPosition;

		private string WindBallGroundAreaEffectName;

		private int BallonCount;

		protected override void OnSkillEnable()
		{
			BallonCount = 0;
			Phase = GetLogicTagFpValue(_actor, "Phase");
			if (Phase == 1)
			{
				ZoneFXSize = ZoneFXSizeP1;
				GroundFXSize = GroundFXSizeP1;
				LoopWaitTime = LoopWaitTimeP1;
				WindBallGroundFXPosition = 1;
				WindBallGroundAreaEffectName = "AreaEffect_WindBall_GroundAttack_1";
			}
			else
			{
				ZoneFXSize = ZoneFXSizeP2;
				GroundFXSize = GroundFXSizeP2;
				LoopWaitTime = LoopWaitTimeP2;
				WindBallGroundFXPosition = 1.2;
				WindBallGroundAreaEffectName = "AreaEffect_WindBall_GroundAttack_2";
			}
		}

		protected override void OnSkillDisable()
		{
			StopEffect(WindBallFX);
			StopEffect(ZoneFX);
			StopAreaEffect(WindBallArea);
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return BeginLookAt(GetAttackTarget(), 0, 200);
			BeginAttack(1, WindBlast_Combo, flushInputedKeys: true);
			yield return WaitCustomEvent("ZoneFXStart");
			WaitLookAt_NoWait(GetAttackTarget(isUpToDate: true), 999, 60);
			TSVector2 position;
			float zoneFXSize;
			if (Phase == 2)
			{
				Skill_WindBlast_Lv3 skill_WindBlast_Lv = this;
				Skill_WindBlast_Lv3 skill_WindBlast_Lv2 = this;
				position = GetPosition();
				zoneFXSize = ZoneFXSize;
				skill_WindBlast_Lv.ZoneFX = skill_WindBlast_Lv2.PlayEffect("ZoneFX", 1f, default(FP), position, default(FP), zoneFXSize);
				WindBallArea = PlayAreaEffect("AreaEffect_WindBall_Plus", GetPosition(), GetRotation());
			}
			yield return WaitCustomEvent("BallFXStart");
			Skill_WindBlast_Lv3 skill_WindBlast_Lv3 = this;
			Skill_WindBlast_Lv3 skill_WindBlast_Lv4 = this;
			position = GetPosition();
			FP rotation = GetRotation();
			skill_WindBlast_Lv3.WindBallFX = skill_WindBlast_Lv4.PlayEffect("WindBallFX", 1f, default(FP), position, rotation);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			StopWaitLookAt();
			FP rotation2;
			if (Phase == 2)
			{
				while (BallonCount < BallonAmout)
				{
					TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 3.7));
					Skill_WindBlast_Lv3 skill_WindBlast_Lv5 = this;
					rotation = 5;
					FP innerRadius = 4;
					FP angle = 360 / BallonAmout;
					rotation2 = 360 * BallonCount / BallonAmout;
					DeterministicShape shapeData = skill_WindBlast_Lv5.GetShapeData(DeterministicShape.ShapeType.Fan, tSVector, default(FP), default(FP), rotation, innerRadius, angle, rotation2);
					TSVector2 shapeRandomPoint = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
					if (shapeRandomPoint != tSVector)
					{
						SummonTeammate(2, shapeRandomPoint, shapeRandomPoint - GetPosition());
					}
					BallonCount++;
				}
			}
			yield return WaitTime(LoopWaitTime);
			PlayAreaEffect(WindBallGroundAreaEffectName, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 3.7)));
			yield return WaitTime(0.32);
			CancelAttack();
			if (Phase == 2)
			{
				yield return WaitCustomEvent("ZoneEndFX");
				Skill_WindBlast_Lv3 skill_WindBlast_Lv6 = this;
				position = GetPosition();
				zoneFXSize = ZoneFXSize;
				skill_WindBlast_Lv6.PlayEffect("ZoneEndFX", 1f, default(FP), position, default(FP), zoneFXSize);
			}
			yield return WaitCustomEvent("StopFX");
			StopEffect(WindBallFX);
			StopEffect(ZoneFX);
			StopAreaEffect(WindBallArea);
			yield return WaitCustomEvent("WindBallGroundFX");
			Skill_WindBlast_Lv3 skill_WindBlast_Lv7 = this;
			position = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, -2 * WindBallGroundFXPosition));
			rotation2 = GetRotation();
			zoneFXSize = GroundFXSize;
			skill_WindBlast_Lv7.PlayEffect("WindBallGroundFX", 1f, default(FP), position, rotation2, zoneFXSize);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
}
namespace AIScript.Monster._50561CanDao
{
	public class Action : AIBase
	{
		private static readonly int skillId_throw = 5056102;

		private static readonly int skillCD_throw = 11;

		private static readonly int skillId_idle = 9999999;

		private static readonly int skillCD_idle = 1;

		private static readonly int skillId_born = 5056101;

		private static readonly int skillId_catch = 5056103;

		private SkillPool _skillPool;

		private CoroutineNode _checkQualifiedSkillCoroutine;

		private LogicEntity target;

		private TraceTarget _traceTarget;

		public void OnStart()
		{
			if (_skillPool == null)
			{
				_skillPool = new SkillPool();
				List<SkillVariable> list = new List<SkillVariable>();
				SkillVariable item = new SkillVariable(skillId_throw, skillCD_throw, 1, 9, 5, immBondage: false, _actor.LogicTime);
				list.Add(item);
				item = new SkillVariable(skillId_idle, skillCD_idle, 0, 9, 5, immBondage: false, _actor.LogicTime);
				list.Add(item);
				_skillPool.Init(_actor, list, 0.1);
			}
			_checkQualifiedSkillCoroutine = _actor.StartLogicCoroutine(CheckQualifiedSkill());
		}

		public void OnStop()
		{
			_traceTarget?.Clear();
			if (_checkQualifiedSkillCoroutine != null)
			{
				_actor.StopLogicCoroutine(_checkQualifiedSkillCoroutine);
				_checkQualifiedSkillCoroutine = null;
			}
		}

		public void OnDisable()
		{
			_skillPool = null;
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
		}

		private IEnumerator CheckQualifiedSkill()
		{
			while (true)
			{
				Action action = this;
				LogicEntity logicEntity = (_actor.monsterTarget = _actor.actorSearchTargetInfo.GetMonsterAttackTarget());
				action.target = logicEntity;
				if ((target == null || !(target as AdventureActor).actorHealthInfo.isAlive) && _actor is MonsterAdventureActor)
				{
					break;
				}
				if (_actor.logicVariable.GetLogicTagToggle("getBullet"))
				{
					bool logicTagToggle = _actor.logicVariable.GetLogicTagToggle("born");
					int skillId = skillId_catch;
					if (logicTagToggle)
					{
						skillId = skillId_born;
					}
					else
					{
						_skillPool.GetSkill(skillId_throw)?.ClearExpireTime();
					}
					bool skillFinish = false;
					ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
					{
						skillFinish = true;
					});
					while (!skillFinish)
					{
						yield return null;
					}
					continue;
				}
				SkillVariable qualifiedSkill = _skillPool.CheckQualifiedSkill(_actor.LogicTime);
				if (qualifiedSkill == null)
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_skillPool.checkInterval));
					continue;
				}
				bool flag = true;
				bool logicTagToggle2 = _actor.logicVariable.GetLogicTagToggle("haveBullet");
				if (qualifiedSkill.id == skillId_throw && !logicTagToggle2)
				{
					flag = false;
				}
				if (flag)
				{
					if (_traceTarget == null)
					{
						_traceTarget = new TraceTarget();
					}
					bool traceFinish = false;
					bool skillFinish2 = false;
					_traceTarget.BeginTrace(_actor, target, qualifiedSkill.releaseDistance, -1, qualifiedSkill.trackTime, delegate
					{
						qualifiedSkill.ResetExpireTime(_actor.LogicTime);
						ILRuntimeAPI.CreateSkill(qualifiedSkill.id, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
						{
							skillFinish2 = true;
						});
						traceFinish = true;
					}, delegate(bool isdie, bool isInterrupt)
					{
						if (!isdie)
						{
							qualifiedSkill.ResetExpireTime(_actor.LogicTime);
						}
						traceFinish = true;
						skillFinish2 = true;
					});
					while (!traceFinish)
					{
						yield return null;
					}
					while (!skillFinish2)
					{
						yield return null;
					}
				}
				else
				{
					yield return null;
				}
			}
			_actor.Idle();
		}
	}
	public class Action_LD : MonsterActionBase
	{
		private readonly int shootSkill = 5056102;

		private readonly int reloadSkill = 5056101;

		private readonly int catchSkill = 5056103;

		private readonly int wanderSkill = 5056104;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_actor.logicVariable.ToggleLogicTag("isCatchBullet", value: false);
			_actor.logicVariable.ToggleLogicTag("haveBullet", value: true);
			_actor.logicVariable.ToggleLogicTag("needReload", value: false);
		}

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.POOL;
			_thinkInterval = 0.05;
			List<PoolBranchesInfo> list = new List<PoolBranchesInfo>();
			PoolBranchesInfo obj = new PoolBranchesInfo
			{
				index = 1
			};
			List<PoolBranchInfo> list2 = new List<PoolBranchInfo>();
			AdventureActor actor = _actor;
			FP cd = 0.5;
			FP initCd = 2;
			OperateDelegate operateIEnumerator = shootCondition;
			list2.Add(new PoolBranchInfo(actor, 1000, 3, cd, initCd, active: true, default(FP), default(FP), default(FP), null, null, operateIEnumerator));
			AdventureActor actor2 = _actor;
			FP cd2 = 0;
			FP initCd2 = 0;
			operateIEnumerator = reloadCondition;
			list2.Add(new PoolBranchInfo(actor2, 1001, 4, cd2, initCd2, active: false, default(FP), default(FP), default(FP), null, null, operateIEnumerator));
			AdventureActor actor3 = _actor;
			FP cd3 = 0.1;
			FP initCd3 = 2;
			operateIEnumerator = catchCondition;
			list2.Add(new PoolBranchInfo(actor3, 1002, 2, cd3, initCd3, active: true, default(FP), default(FP), default(FP), null, null, operateIEnumerator));
			AdventureActor actor4 = _actor;
			FP cd4 = 3;
			FP initCd4 = 0;
			operateIEnumerator = wanderCondition;
			list2.Add(new PoolBranchInfo(actor4, 1003, 1, cd4, initCd4, active: true, default(FP), default(FP), default(FP), null, null, operateIEnumerator));
			obj.braches = list2;
			list.Add(obj);
			List<PoolBranchesInfo> poolBranches = list;
			InitPoolBranches(1, poolBranches);
		}

		private IEnumerator shootCondition()
		{
			if (GetLogicTagToggleValue(_actor, "haveBullet"))
			{
				CastSkill(shootSkill);
				yield return WaitSkillFinish();
				_actor.logicVariable.ToggleLogicTag("haveBullet", value: false);
			}
			else
			{
				SetPoolBranchActive(1001, active: true);
			}
		}

		private IEnumerator reloadCondition()
		{
			_actor.logicVariable.ToggleLogicTag("haveBullet", value: true);
			_actor.logicVariable.ToggleLogicTag("needReload", value: false);
			CastSkill(reloadSkill);
			SetPoolBranchActive(1001, active: false);
			yield return WaitSkillFinish();
			SetPoolBranchCD(1000, 0);
		}

		private IEnumerator catchCondition()
		{
			if (GetLogicTagToggleValue(_actor, "isCatchBullet"))
			{
				CastSkill(catchSkill);
				_actor.logicVariable.ToggleLogicTag("haveBullet", value: true);
			}
			_actor.logicVariable.ToggleLogicTag("isCatchBullet", value: false);
			yield break;
		}

		private IEnumerator wanderCondition()
		{
			CastSkill(wanderSkill);
			yield break;
		}
	}
