		private string BulletKnifeName;

		private string BulletForkName;

		private string BulletName;

		private string BulletBornFXName;

		private string BulletKnifeReadyName;

		private string BulletForkReadyName;

		private string BulletReadyName;

		private List<long> BulletReadyFXList;

		protected override void OnSkillEnable()
		{
			BattleStage = (int)(long)GetLogicTagFpValue(_actor, "BattleStage");
			if (BattleStage == 1)
			{
				BulletAmount = BulletAmount_Stage1;
				BulletKnifeName = "Knife_Parabola";
				BulletForkName = "Fork_Parabola";
				BulletBornFXName = "BulletBorn_NoFire";
				BulletKnifeReadyName = "BulletReady_Knife";
				BulletForkReadyName = "BulletReady_Fork";
			}
			else if (BattleStage == 2)
			{
				BulletAmount = BulletAmount_Stage2;
				BulletKnifeName = "Knife_Parabola_Fire";
				BulletForkName = "Fork_Parabola_Fire";
				BulletBornFXName = "BulletBorn";
				BulletKnifeReadyName = "BulletReady_Knife_Fire";
				BulletForkReadyName = "BulletReady_Fork_Fire";
			}
			else if (BattleStage == 3)
			{
				BulletAmount = BulletAmount_Stage3;
				BulletKnifeName = "Knife_Parabola_Fire";
				BulletForkName = "Fork_Parabola_Fire";
				BulletBornFXName = "BulletBorn";
				BulletKnifeReadyName = "BulletReady_Knife_Fire";
				BulletForkReadyName = "BulletReady_Fork_Fire";
			}
			BulletCount = 0;
			BulletReadyFXList = new List<long>();
			BulletReadyFXList = new List<long>();
		}

		protected override void OnSkillDisable()
		{
			BulletReadyFXList.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Throw_Combo);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			while (BulletCount < BulletAmount)
			{
				if (BulletCount % 2 == 0)
				{
					BulletReadyName = BulletKnifeReadyName;
				}
				else
				{
					BulletReadyName = BulletForkReadyName;
				}
				TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), RotateTo(new TSVector2(0, ShootRadius), BulletCount * (360 / BulletAmount)));
				PlayEffect(BulletBornFXName, 1f, ShootHeight, tSVector, GetTSVectToAngle(tSVector - GetPosition(), 0), 1.5f);
				BulletReadyFXList.Add(PlayEffect(BulletReadyName, 1f, ShootHeight, tSVector, GetTSVectToAngle(tSVector - GetPosition(), 0)));
				yield return WaitTime(1.5f / (float)BulletAmount);
				BulletCount++;
			}
			for (BulletCount = 0; BulletCount < BulletAmount; BulletCount++)
			{
				TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetForward(), RotateTo(new TSVector2(0, ShootRadius), BulletCount * (360 / BulletAmount)));
				Skill5_2_ThrowKnife_Parabola_BossRush skill5_2_ThrowKnife_Parabola_BossRush = this;
				FP radius = 2;
				DeterministicShape shapeData = skill5_2_ThrowKnife_Parabola_BossRush.GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), radius);
				TSVector2 shapeRandomPoint = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				if (BulletCount % 2 == 0)
				{
					BulletName = BulletKnifeName;
				}
				else
				{
					BulletName = BulletForkName;
				}
				if (BulletCount < BulletReadyFXList.Count)
				{
					StopEffect(BulletReadyFXList[BulletCount]);
				}
				Skill5_2_ThrowKnife_Parabola_BossRush skill5_2_ThrowKnife_Parabola_BossRush2 = this;
				string bulletName = BulletName;
				FP shootHeight = ShootHeight;
				FP range = 0;
				TSVector2 entityPosition = GetEntityPosition(GetAttackTarget(isUpToDate: true));
				skill5_2_ThrowKnife_Parabola_BossRush2.Shoot(bulletName, shapeRandomPoint, shootHeight, range, default(TSVector2), AimType.Position, BulletDirectionType.BulletToTarget, entityPosition);
				yield return WaitTime(2f / (float)BulletAmount);
			}
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private const GameEnum.questCompleteCondClient achievementType_1 = GameEnum.questCompleteCondClient.ChuShi_001;

		private static readonly List<int> teammateIndex_1 = new List<int> { 1, 2 };

		private const int teammateCountSameTime_1 = 15;

		private const GameEnum.questCompleteCondClient achievementType_2 = GameEnum.questCompleteCondClient.ChuShi_002;

		private static readonly int bulletTag_2 = CommonHelper.StringToHash("Knife_CallBack_Fire");

		private const GameEnum.questCompleteCondClient achievementType_3 = GameEnum.questCompleteCondClient.ChuShi_003;

		private static readonly List<int> killTeammateIndex_3 = new List<int> { 1, 2 };

		private bool _achievementTypeFinish_1;

		private int _teammateCount_1;

		private bool _achievementTypeFinish_2;

		private bool _canFinishAchievementType_2;

		private bool _achievementTypeFinish_3;

		public override void OnStart()
		{
			base.OnStart();
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_SPAWN", OnActorSpawn);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_BORN", OnBulletBorn);
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ChuShi_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ChuShi_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ChuShi_003);
			_teammateCount_1 = 0;
			_canFinishAchievementType_2 = true;
		}

		private void OnActorSpawn(IEvent evt)
		{
			if (MonoSingleton<GameController>.Instance.levelLoadParam == null || !MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower || !((evt as AdventurActorSpawned).sender is MonsterAdventureActor item) || _achievementTypeFinish_1)
			{
				return;
			}
			for (int i = 0; i < teammateIndex_1.Count; i++)
			{
				int teammateIdByIndex = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, teammateIndex_1[i]);
				if (ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex).Contains(item))
				{
					_teammateCount_1++;
					break;
				}
			}
			if (_teammateCount_1 >= 15)
			{
				_achievementTypeFinish_1 = SetAchievementState(GameEnum.questCompleteCondClient.ChuShi_001);
			}
		}

		private void OnBulletBorn(IEvent evt)
		{
			AdventureBulletBornEvent adventureBulletBornEvent = evt as AdventureBulletBornEvent;
			if (adventureBulletBornEvent.owner is MonsterAdventureActor && !_achievementTypeFinish_2 && _canFinishAchievementType_2 && adventureBulletBornEvent.bulletHashCode == bulletTag_2)
			{
				_canFinishAchievementType_2 = false;
			}
		}

		protected override void OnActorDied(IEvent evt)
		{
			base.OnActorDied(evt);
			AdventureActorDiedEvent adventureActorDiedEvent = evt as AdventureActorDiedEvent;
			if (!(adventureActorDiedEvent.actor is MonsterAdventureActor item))
			{
				return;
			}
			if (adventureActorDiedEvent.killer is PlayerAdventureActor && !_achievementTypeFinish_3)
			{
				for (int i = 0; i < killTeammateIndex_3.Count; i++)
				{
					int teammateIdByIndex = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, killTeammateIndex_3[i]);
					if (ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex).Contains(item))
					{
						_achievementTypeFinish_3 = SetAchievementState(GameEnum.questCompleteCondClient.ChuShi_003);
						break;
					}
				}
			}
			if (MonoSingleton<GameController>.Instance.levelLoadParam == null || !MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower || _achievementTypeFinish_1)
			{
				return;
			}
			for (int j = 0; j < teammateIndex_1.Count; j++)
			{
				int teammateIdByIndex2 = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, teammateIndex_1[j]);
				if (ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex2).Contains(item))
				{
					_teammateCount_1--;
					break;
				}
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_SPAWN", OnActorSpawn);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_BORN", OnBulletBorn);
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.ChuShi_002);
			}
		}
	}
	public class SimpleAPI_ChuShi : SkillSimpleBase
	{
		protected IEnumerator JumpToPoints(TSVector2 Position)
		{
			ComboInputBuffer.ActionKey[] array = new ComboInputBuffer.ActionKey[2]
			{
				ComboInputBuffer.ActionKey.U,
				ComboInputBuffer.ActionKey.U
			};
			ComboInputBuffer.ActionKey[] array2 = new ComboInputBuffer.ActionKey[2]
			{
				ComboInputBuffer.ActionKey.V,
				ComboInputBuffer.ActionKey.V
			};
			FP fP = 15;
			ComboInputBuffer.ActionKey[] keys;
			FP fP2;
			if (Distance(GetPosition(), Position) >= fP)
			{
				keys = array2;
				fP2 = 25.714285714285715;
			}
			else
			{
				keys = array;
				fP2 = 20;
			}
			TSVector2 DashDirection = Position - GetPosition();
			FP DashDistance = Distance(Position, GetPosition());
			FP DashSpeed = DashDistance / (fP2 / 60f);
			BeginAttack(1, keys);
			yield return WaitCustomEvent("Dash");
			BeginDash(1, DashDirection, DashSpeed, DashDistance, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0);
			yield return WaitCustomEvent("CloseBlock");
			SetCloseBlockEnable();
			yield return WaitCustomEvent("OpenBlock");
			SetCloseBlockDisable();
			yield return WaitCustomEvent("StopDash");
			StopDash();
		}
	}
