		protected override IEnumerator DoMainLogic()
		{
			long WarningFX;
			TSVector2 blinkPosition;
			FP rotation;
			if (ActionPhase == 1)
			{
				WaitTimeAtSky = WaitTimeAtSky_Phase1;
				BeginAttack(1, JumpSlash, flushInputedKeys: true);
