		private static readonly FP DanmakuAngle = 180;

		private static readonly TSVector2 CallBackTargetPosition = new TSVector2(0, 15.8);

		private static readonly TSVector2 CallLineTargetPosition = new TSVector2(0, 13.8);

		private FP TurnSpeed;

		private bool IsCallBackChargeEnd;

		private TSVector2 SkillPoint;

