namespace AIScript.Monster._50531DaGuanZi
{
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private const GameEnum.questCompleteCondClient achievementType_1 = GameEnum.questCompleteCondClient.DaGuanZi_001;

		private const GameEnum.questCompleteCondClient achievementType_2 = GameEnum.questCompleteCondClient.DaGuanZi_002;

		private bool _achievementTypeFinish_1;

		private bool _achievementTypeFinish_2;

		private bool _canFinishAchievementType_2;

		public override void OnStart()
		{
			base.OnStart();
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessStateChange);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
		}

		protected void OnToughnessStateChange(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (monsterToughnessStateChangeEvent.actor.Id == _actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.buffComponent.AddBuff(990050050, _actor);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessStateChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.DaGuanZi_002);
			}
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.DaGuanZi_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.DaGuanZi_002);
			_canFinishAchievementType_2 = true;
		}

		protected override void OnActorDied(IEvent evt)
		{
			base.OnActorDied(evt);
			if (MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower && (evt as AdventureActorDiedEvent).actor is MonsterAdventureActor monsterAdventureActor && monsterAdventureActor == _actor && !_achievementTypeFinish_1 && monsterAdventureActor.monsterToughnessInfo.isToughnessBroken)
			{
				_achievementTypeFinish_1 = SetAchievementState(GameEnum.questCompleteCondClient.DaGuanZi_001);
			}
		}

		private void OnCastSkill(IEvent evt)
		{
			if ((evt as AdventureActorCastSkillEvent).sender is MonsterAdventureActor monsterAdventureActor && monsterAdventureActor == _actor && !_achievementTypeFinish_1 && _canFinishAchievementType_2 && monsterAdventureActor.monsterToughnessInfo.isToughnessBroken)
			{
				_canFinishAchievementType_2 = false;
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}
	}
