			BeginAttack(startKeyIndex1, startKey, flushInputedKeys: true);
			BeginLookAt_NotWait(AttackTarget, 1.8, 360);
			yield return WaitCustomEvent(StopLookAT_Event);
			StopLookAt();
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
