		}

		private void DoNormalSpeedList(List<int[,]> points, List<FP> times, List<string> group)
		{
			for (int i = 0; i < points.Count; i++)
			{
				CoroutineNode item = _actor.StartLogicCoroutine(PlayArae(Area_Points[points[i].GetLength(0), points[i].GetLength(1)], times, group));
				corPlayAreaList.Add(item);
			}
		}

		private TSVector2 FindNearestPoint()
		{
			TSVector2 result = new TSVector2(0, 0);
			FP fP = 9999;
			TSVector2 position = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position;
			for (int i = 0; i < Area_Points.GetLength(0); i++)
			{
				for (int j = 0; j < Area_Points.GetLength(1); j++)
				{
					FP fP2 = TSVector2.Distance(position, Area_Points[i, j]);
					if (fP2 < fP)
					{
						fP = fP2;
						result = Area_Points[i, j];
					}
				}
			}
			return result;
		}

		private int[,] FindNearestCoordinate()
		{
			int[,] result = new int[0, 0];
			FP fP = 9999;
			TSVector2 position = _actor.tsTransform.Position;
			for (int i = 0; i < Area_Points.GetLength(0); i++)
			{
				for (int j = 0; j < Area_Points.GetLength(1); j++)
				{
					FP fP2 = TSVector2.Distance(position, Area_Points[i, j]);
					if (fP2 < fP)
					{
						fP = fP2;
						result = new int[i, j];
					}
				}
			}
			return result;
		}

		private IEnumerator PlayArae(TSVector2 pos, List<FP> times, List<string> group)
		{
			ILRuntimeAPI.PlayAreaEffect(_actor, group[0], pos, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(times[0]));
			ILRuntimeAPI.PlayAreaEffect(_actor, group[1], pos, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(times[1]));
			ILRuntimeAPI.PlayAreaEffect(_actor, group[2], pos, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(times[2]));
			ILRuntimeAPI.PlayAreaEffect(_actor, group[3], pos, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}

		private void FromStype_1(int speedType, List<string> group)
		{
			int[,] array = FindNearestCoordinate();
			int length = array.GetLength(0);
			int length2 = array.GetLength(1);
			int length3 = Area_Points.GetLength(0);
			int length4 = Area_Points.GetLength(1);
			List<int[,]> list = new List<int[,]>();
			for (int i = length - 1; i <= length + 1; i++)
			{
				for (int j = length2 - 1; j <= length2 + 1; j++)
				{
					int num = i;
					int num2 = j;
					if (num >= 0 && num < length3 && num2 >= 0 && num2 < length4)
					{
						int[,] item = new int[num, num2];
						list.Add(item);
					}
				}
			}
			DoNormalSpeedList(list, wait_Time[speedType - 1], group);
		}

		private void FromStype_2(int speedType, List<string> group)
		{
			int[,] array = FindNearestCoordinate();
			int length = array.GetLength(0);
			int length2 = array.GetLength(1);
			int length3 = Area_Points.GetLength(0);
			int length4 = Area_Points.GetLength(1);
			List<int[,]> list = new List<int[,]> { new int[length, length2] };
			for (int i = 0; i < length3; i++)
			{
				if (i != length)
				{
					int[,] item = new int[i, length2];
					list.Add(item);
				}
			}
			for (int j = 0; j < length4; j++)
			{
				if (j != length2)
				{
					int[,] item2 = new int[length, j];
					list.Add(item2);
				}
			}
			DoNormalSpeedList(list, wait_Time[speedType - 1], group);
		}

		private void FromStype_3(int speedType, List<string> group)
		{
			int[,] array = FindNearestCoordinate();
			int length = array.GetLength(0);
			int length2 = array.GetLength(1);
			int length3 = Area_Points.GetLength(0);
			int length4 = Area_Points.GetLength(1);
			List<int[,]> list = new List<int[,]> { new int[length, length2] };
			for (int i = 1; i < length3; i++)
			{
				int num = length - i;
				if (num >= 0 && num < length3)
				{
					int num2 = length2 - i;
					if (num2 >= 0 && num2 < length4)
					{
						list.Add(new int[num, num2]);
					}
					int num3 = length2 + i;
					if (num3 >= 0 && num3 < length4)
					{
						list.Add(new int[num, num3]);
					}
				}
				int num4 = length + i;
				if (num4 >= 0 && num4 < length3)
				{
					int num5 = length2 - i;
					if (num5 >= 0 && num5 < length4)
					{
						list.Add(new int[num4, num5]);
					}
					int num6 = length2 + i;
					if (num6 >= 0 && num6 < length4)
					{
						list.Add(new int[num4, num6]);
					}
				}
			}
			DoNormalSpeedList(list, wait_Time[speedType - 1], group);
		}

		private IEnumerator DoCorDicType()
		{
			foreach (KeyValuePair<List<int[,]>, List<FP>> item in dicType)
			{
				int num = (int)(long)item.Value[1];
				int num2 = (int)(long)item.Value[2];
				DoNormalSpeedList(item.Key, wait_Time[num2 - 1], Area_GroupList[num - 1]);
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(item.Value[0]));
			}
		}

		private void SoloDash()
		{
			TSVector2 tSVector = soloDashPoint[soloDashCount];
			TSVector2 normalized = (tSVector - _actor.tsTransform.Position).normalized;
			FP fP = TSVector2.Distance(tSVector, _actor.tsTransform.Position);
			if (_dash == null)
			{
				_dash = new Dash();
			}
			_dash.BeginDash(_actor, normalized, soloDashSpeed, fP, soloAngleLimit, (System.Action)DashFinishCallback, (System.Action)null, (System.Action)null, true, false, true, false, false, false, false, default(FP), true);
			soloDashCount++;
			if (soloDashCount == soloDashPoint.Count)
			{
				soloDashCount = 0;
			}
		}

		private void DashFinishCallback()
		{
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
		}

		private void ClearCor()
		{
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
			StopCoroutine(ref corPlayArea);
			for (int i = 0; i < corPlayAreaList.Count; i++)
			{
				StopCoroutine(corPlayAreaList[i]);
			}
			corPlayAreaList.Clear();
			if (corDicType != null)
			{
				_actor.StopLogicCoroutine(corDicType);
				corDicType = null;
			}
		}

		public void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("TRIGGER_PERFECTDODGE", OnTriggerPerfect);
			ClearCor();
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
			if (!_achievementTypeFinish_1 && _canFinishAchievementType_1)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.TiaoWuJi_001);
			}
			if (!_achievementTypeFinish_2 && _actor.logicVariable.GetLogicTagToggle("IsTetris"))
			{
				SetAchievementState(GameEnum.questCompleteCondClient.TiaoWuJi_002);
			}
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.TiaoWuJi_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.TiaoWuJi_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.TiaoWuJi_003);
			_canFinishAchievementType_1 = true;
			_triggerCount_3 = 0;
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from is MonsterAdventureActor && adventureActorReceiveDamageEvent.to is PlayerAdventureActor && !_achievementTypeFinish_1 && _canFinishAchievementType_1)
			{
				_canFinishAchievementType_1 = adventureActorReceiveDamageEvent.curValue <= 0;
			}
		}

		private void OnTriggerPerfect(IEvent evt)
		{
			if (MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower && !_achievementTypeFinish_3)
			{
				_triggerCount_3++;
				if (_triggerCount_3 >= 10)
				{
					_achievementTypeFinish_3 = SetAchievementState(GameEnum.questCompleteCondClient.TiaoWuJi_003);
				}
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}
	}
	public class SkillScript_Spawn : SkillAdvancedBase
