		private readonly int BuffID_Cir = 505210100;

		private readonly int BuffID_Ring = 505210110;

		private readonly int BuffID_Cro = 505210120;

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(ActionIndex01, ActionCombo01, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.55);
			BeginAttack(ActionIndex02, ActionCombo02, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.5);
			int num = ((GetBuffNum(_actor, BuffID_Cir) == 1) ? GetRandomValue(1, 3, isInt: true).AsInt() : ((GetBuffNum(_actor, BuffID_Ring) != 1) ? ((GetBuffNum(_actor, BuffID_Cro) != 1) ? GetRandomValue(0, 3, isInt: true).AsInt() : GetRandomValue(0, 2, isInt: true).AsInt()) : 0));
			int index = 0;
			switch (num)
			{
			case 0:
				while (index < 4)
				{
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[1, 1]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[1, 2]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[2, 1]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[2, 2]);
					index++;
					yield return WaitTime(AreaINTR);
				}
				AddBuffToTarget(_actor, BuffID_Cir);
				break;
			case 1:
				while (index < 4)
				{
					for (int k = 0; k < 4; k++)
					{
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[0, k]);
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[3, k]);
					}
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[1, 0]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[2, 0]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[1, 3]);
					PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[2, 3]);
					index++;
					yield return WaitTime(AreaINTR);
				}
				AddBuffToTarget(_actor, BuffID_Ring);
				break;
			case 2:
				while (index < 4)
				{
					for (int j = 0; j < 4; j++)
					{
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[j, j]);
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[j, Math.Abs(j - 3)]);
					}
					index++;
					yield return WaitTime(AreaINTR);
				}
				AddBuffToTarget(_actor, BuffID_Cro);
				break;
			default:
				while (index < 4)
				{
					for (int i = 0; i < 4; i++)
					{
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[i, i]);
						PlayAreaEffect(Area_GroupList[index], Parallel.Area_Points[i, Math.Abs(i - 3)]);
					}
					index++;
					yield return WaitTime(AreaINTR);
				}
				break;
			}
			List<LogicEntity> targetByTeammateIndex = GetTargetByTeammateIndex(1);
			if (targetByTeammateIndex != null && targetByTeammateIndex.Count > 0)
			{
				for (int l = 0; l < targetByTeammateIndex.Count; l++)
				{
					SetLogicTagToggleValue(targetByTeammateIndex[l], "SummonATK", value: true);
				}
			}
		}
	}
	public class Skill_Move_LD : SkillSimpleBase
	{
		private readonly string ActionCombo01 = "Solo_Start_D";

		private readonly int ActionIndex01 = 1;

		private readonly string ActionCombo02 = "Solo_End_D";

		private readonly int ActionIndex02 = 2;

		private readonly TSVector2[,] TeleportPoint = new TSVector2[2, 2]
		{
			{
				new TSVector2(-2.5, 2.5),
				new TSVector2(2.5, 2.5)
			},
			{
				new TSVector2(-2.5, -2.5),
				new TSVector2(2.5, -2.5)
			}
		};

		private readonly int DebuffTag = CommonHelper.StringToHash("DeBuff");

		private TSVector2 TargetPOS;

		private LogicEntity Target;

		protected override IEnumerator DoMainLogic()
		{
			switch (GetRandomValue(0, 4, isInt: true).AsInt())
			{
			case 0:
				TargetPOS = TeleportPoint[0, 0];
				break;
			case 1:
				TargetPOS = TeleportPoint[0, 1];
				break;
			case 2:
				TargetPOS = TeleportPoint[1, 0];
				break;
			case 3:
				TargetPOS = TeleportPoint[1, 1];
				break;
			default:
				TargetPOS = TeleportPoint[1, 1];
				break;
			}
			BeginAttack(ActionIndex01, ActionCombo01, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.55);
			BeginAttack(ActionIndex02, ActionCombo02, flushInputedKeys: true, forceInterruptAttack: true);
			PlayEffect("fx_m50521_base_skill3_start_LD", 1f, -0.3, GetPosition());
			yield return WaitTime(0.3);
			RemoveBuffFromTarget(_actor, 0, 0, DebuffTag);
			SetHideModelEnable();
			SetBattleOutEnable();
			SetCloseBlockEnable();
			yield return WaitTime(0.6);
			Teleport(TargetPOS);
			Target = GetAttackTarget(isUpToDate: true);
			if (CheckTargetIsValid(Target))
			{
				BeginLookAt_NotWait(Target, 0, 360);
			}
			yield return WaitTime(0.1);
			PlayEffect("fx_m50521_base_skill3_start_LD", 1f, -0.3, GetPosition());
			yield return WaitTime(0.4);
			SetHideModelDisable();
			SetBattleOutDisable();
			SetCloseBlockDisable();
			yield return WaitTime(0.55);
		}
	}
	public class Skill_Spawn : SkillSimpleBase
	{
		protected override void OnSkillEnable()
		{
			SetBattleOutEnable();
		}

		protected override void OnSkillDisable()
		{
			ShowCenterHpBar();
		}

		protected override IEnumerator DoMainLogic()
		{
			while (Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer())) > 15)
			{
				yield return WaitTime(0.5);
			}
		}
	}
	public class Skill_Tutti_LD : SkillSimpleBase
