		{
			List<BuffEntity> buffFromTarget = GetBuffFromTarget(_actor, 0, 505210000);
			if (buffFromTarget.Count != 0)
			{
				switch (buffFromTarget[0].buffConfig.Id)
				{
				case 505210000:
					branch = 0;
					randomValue01 = 1.5f;
					randomValue02 = 1.5f;
					break;
				case 505210001:
					branch = 1;
					randomValue01 = 1.5f;
					randomValue02 = 2.5f;
					break;
				case 505210002:
					branch = 2;
					randomValue01 = 4.5f;
					randomValue02 = 1.5f;
					break;
				default:
