		private IEnumerator TypeC()
		{
			if (branch > 0)
			{
				SummonTeammate(1, Parallel.Area_Points[0, 0], TSVector2.right);
				SummonTeammate(1, Parallel.Area_Points[3, 3], TSVector2.left);
			}
			for (int i = 0; i < 3; i++)
			{
				PlayAreaEffect(Area_GroupList_Fast_02[0], Parallel.Area_Points[0, i + 1]);
				PlayAreaEffect(Area_GroupList_Fast_02[0], Parallel.Area_Points[3, Math.Abs(i - 2)]);
