namespace AIScript.Monster._5051500ShuangShaYuFaShi_An
{
	public class Action : AIBase
	{
		protected enum Stage
		{
			Common,
			Fury
		}

		protected enum SkillId
		{
			QianShui = 5052000,
			QianShui_QiangHua = 5052004,
			AnYingQiu = 5052002,
			AnYingQiu_QiangHua = 5052006,
			AnYingChongJi = 5052001,
			AnYingChongJi_QiangHua = 5052005,
			AnYingGuangShu = 5052003,
			AnYingGuangShu_QiangHua = 5052007
		}

		private readonly int targetMonsterId = 5051500;

		private Stage stage;

		private SkillId curSkillId = SkillId.QianShui;

		private int qianshuiCount;

		private bool playOtherRdm;

		private int noCount;

		private bool forceQiangHuaGuangShu;

		public void OnEnable()
		{
			AdventureModuleController instance = ModuleController<AdventureModuleController>.Instance;
			instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDied);
			instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			stage = Stage.Common;
		}

		public void OnDisable()
		{
			AdventureModuleController instance = ModuleController<AdventureModuleController>.Instance;
			instance.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDied);
			instance.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
		}

		private void MonsterDied(IEvent ievent)
		{
			if (ievent != null && ((AdventureMonsterDiedEvent)ievent).id == targetMonsterId)
			{
				ResetStage(Stage.Fury);
			}
		}

		public void OnStart()
		{
			ResetStage(Stage.Common, switchFlow: true);
			SwitchStageFlow();
		}

		public void OnStop()
		{
		}

		private void OnCastSkillEnd(IEvent ievent)
		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = (AdventureActorCastSkillEndEvent)ievent;
			if (adventureActorCastSkillEndEvent != null && ((AdventureActor)adventureActorCastSkillEndEvent.sender).Id == _actor.Id)
			{
				SwitchStageFlow();
			}
		}

		private void SwitchStageFlow()
		{
			if (stage == Stage.Common)
			{
				CommonFlow();
			}
			else if (stage == Stage.Fury)
			{
				FuryFlow();
			}
		}

		private void ResetStage(Stage stage, bool switchFlow = false)
		{
			this.stage = stage;
			qianshuiCount = 0;
		}

		private void CommonFlow()
		{
			if (qianshuiCount < 2)
			{
				ILRuntimeAPI.CreateSkill(5052000, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				qianshuiCount++;
			}
			else
			{
				qianshuiCount = 0;
				SwitchSkill();
			}
			void SwitchSkill()
			{
				if (playOtherRdm)
				{
					playOtherRdm = false;
					int num = TSRandom.Range(0, 2);
					if (curSkillId == SkillId.AnYingChongJi)
					{
						if (num <= 1)
						{
							curSkillId = SkillId.AnYingQiu;
						}
						else
						{
							curSkillId = SkillId.AnYingGuangShu;
						}
					}
					else if (curSkillId == SkillId.AnYingGuangShu)
					{
						if (num <= 1)
						{
							curSkillId = SkillId.AnYingQiu;
						}
						else
						{
							curSkillId = SkillId.AnYingChongJi;
						}
					}
					else if (curSkillId == SkillId.AnYingQiu)
					{
						if (num <= 1)
						{
							curSkillId = SkillId.AnYingChongJi;
						}
						else
						{
							curSkillId = SkillId.AnYingGuangShu;
						}
					}
				}
				else
				{
					FP fP = TSVector2.Distance(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position, _actor.tsTransform.Position);
					if (fP <= 3)
					{
						if (curSkillId == SkillId.AnYingChongJi)
						{
							playOtherRdm = true;
						}
						curSkillId = SkillId.AnYingChongJi;
					}
					else if (fP <= 6)
					{
						if (curSkillId == SkillId.AnYingGuangShu)
						{
							playOtherRdm = true;
						}
						curSkillId = SkillId.AnYingGuangShu;
					}
					else
					{
						if (curSkillId == SkillId.AnYingQiu)
						{
							playOtherRdm = true;
						}
						curSkillId = SkillId.AnYingQiu;
					}
				}
				ILRuntimeAPI.CreateSkill((int)curSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
			}
		}

		private void FuryFlow()
		{
			if (forceQiangHuaGuangShu)
			{
				ILRuntimeAPI.CreateSkill(5052007, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				forceQiangHuaGuangShu = false;
				qianshuiCount = 0;
				noCount = 0;
				return;
			}
			if (qianshuiCount < 1)
			{
				qianshuiCount++;
				if (noCount >= 2)
				{
					_actor.logicVariable.SetLogicTagValue("QiangHuaQianShui", 1);
				}
				else
				{
					_actor.logicVariable.SetLogicTagValue("QiangHuaQianShui", 0);
				}
				ILRuntimeAPI.CreateSkill(5052004, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				return;
			}
			qianshuiCount = 0;
			if (noCount >= 2)
			{
				ILRuntimeAPI.CreateSkill((int)curSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				forceQiangHuaGuangShu = false;
				qianshuiCount = 0;
				noCount = 0;
			}
			else
			{
				SwitchSkill();
			}
			void SwitchSkill()
			{
				FP fP = TSVector2.Distance(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position, _actor.tsTransform.Position);
				if (fP <= 3)
				{
					noCount++;
					forceQiangHuaGuangShu = false;
					ILRuntimeAPI.CreateSkill(5052005, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				}
				else if (fP <= 6)
				{
					noCount++;
					forceQiangHuaGuangShu = false;
					ILRuntimeAPI.CreateSkill(5052006, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				}
				else
				{
					noCount = 0;
					forceQiangHuaGuangShu = true;
					_actor.logicVariable.SetLogicTagValue("QiangHuaQianShui", 1);
					ILRuntimeAPI.CreateSkill(5052004, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
				}
			}
		}
	}
	public class Skill_Sneak_LD : SkillSimpleBase
	{
		private LogicEntity target;

		private CoroutineNode CheckMateCor;

		private readonly int SneakIndex;

		private readonly string SneakKey = "Sneak";

		private readonly int ShootIndex = 1;

		private readonly string ShootKey = "NormalATK";

		private readonly string laserFx = "fx_70022_loop_Kagebunsin_Control_line";

		private List<long> _Fx = new List<long>();

		private TSVector2 targetPOS;

		private TSVector2 ZeroPOS = new TSVector2(0, 0);

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			if (_Fx.Count > 0)
			{
				for (int i = 0; i < _Fx.Count; i++)
				{
					StopEffect(_Fx[i]);
				}
			}
			_Fx.Clear();
			StopCor(CheckMateCor);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(SneakIndex, SneakKey, flushInputedKeys: true, forceInterruptAttack: true);
			targetPOS = TransLocalPosToWorldPos(ZeroPOS, GetPosition() - ZeroPOS, new TSVector2(0, 13));
			BeginLookAtByPos_NotWait(targetPOS, 0.3, 600);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			CheckMateCor = StartCor(CheckMateState());
			MoveToPosition(targetPOS, 0.05, AdventureActor.MovementMode.None);
			yield return WaitMoveStatus();
			yield return StartCor(MoveTo());
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return StartCor(ShootTarget());
		}

		protected IEnumerator MoveTo()
		{
			TSVector2 targetPos = RotateTo(GetPosition() - ZeroPOS, 30);
			yield return BeginLookAtByPos(targetPos, default(FP), 999);
			BeginDashActorForward(10, 8, 99, 999, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
			FP dashTime = 1.5;
			FP lookAtWaitTime = 0.2;
			for (int i = 0; i < dashTime / lookAtWaitTime; i++)
			{
				targetPos = RotateTo(GetPosition() - ZeroPOS, 10);
				BeginLookAtByPos_NotWait(targetPos, default(FP), 999);
				yield return WaitTime(lookAtWaitTime);
			}
			StopDash();
			yield return WaitDashFinish();
		}

		protected IEnumerator ShootTarget()
		{
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				target = GetAttackTarget();
			}
			else
			{
				target = GetCurrentPlayer();
			}
			BeginAttack(ShootIndex, ShootKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 1, 360);
			yield return WaitTime(1);
			StopLookAt();
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			shooting();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private IEnumerator CheckMateState()
		{
			List<LogicEntity> targetsByFaction = GetTargetsByFaction(isFriend: true);
			while (targetsByFaction != null && targetsByFaction.Count > 0)
			{
				yield return WaitTime(0.2);
				targetsByFaction = GetTargetsByFaction(isFriend: true);
			}
			KillActors(new List<LogicEntity> { _actor });
		}

		private void shooting()
		{
			int num = 0;
			if (GetMonsterTagValue(_actor, 1) == "SplitBullet")
			{
				num = 1;
			}
			if (num == 1)
			{
				FanMultipleShoot("Weapon_50200AnFaShi_MiniDark_SplitBullet_A", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 1, 0, GetPosition(), 0.75, GetForward(), 0, AimType.Default, BulletDirectionType.ActorToBullet, 75, 0, 2);
			}
			else
			{
				FanMultipleShoot("Weapon_50200AnFaShi_MiniDark_Bullet", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 5, 0, GetPosition(), 0.75, GetForward(), 0, AimType.Default, BulletDirectionType.ActorToBullet, 75, 0, 2);
			}
		}
	}
