namespace AIScript.Monster._5051500ShuangShaYuFaShi_Shui
{
	public class Action : AIBase
	{
		protected enum Stage
		{
			Common,
			Fury
		}

		protected enum SkillId
		{
			ShuiKeng = 5051500,
			ShuiKeng_QiangHua = 5051502,
			ShuiLiu = 5051501,
			ShuiLiu_QiangHua = 5051503
		}

		private readonly int targetMonsterId = 5052000;

		private readonly FP commonDuration = 6;

		private readonly FP furyDuration = 0;

		private Stage stage;

		private bool checkSkill;

		private FP skillDuration = 6;

		private CoroutineNode chooseSkill;

		private SkillId curSkillId = SkillId.ShuiLiu;

		private FP curDuration = 0;

		public void OnEnable()
		{
			checkSkill = true;
			AdventureModuleController instance = ModuleController<AdventureModuleController>.Instance;
			instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDied);
			instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			stage = Stage.Common;
			InitSkill();
		}

		public void OnDisable()
		{
			AdventureModuleController instance = ModuleController<AdventureModuleController>.Instance;
			instance.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", MonsterDied);
			instance.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
		}

		private void MonsterDied(IEvent ievent)
		{
			if (ievent != null && ((AdventureMonsterDiedEvent)ievent).id == targetMonsterId)
			{
				ResetStage(Stage.Fury);
				if (chooseSkill != null)
				{
					_actor.StopLogicCoroutine(chooseSkill);
					chooseSkill = null;
				}
				CheckSkill();
			}
		}

		protected void InitSkill()
		{
		}

		public void OnStart()
		{
			ResetStage(Stage.Common);
			CheckSkill();
		}

		public void OnStop()
		{
			Clear();
		}

		private void Clear()
		{
			if (chooseSkill != null)
			{
				StopCoroutine(chooseSkill);
				chooseSkill = null;
			}
			checkSkill = false;
		}

		private void ResetStage(Stage stage)
		{
			this.stage = stage;
			if (this.stage == Stage.Common)
			{
				curDuration = commonDuration;
				curSkillId = SkillId.ShuiLiu;
			}
			else if (this.stage == Stage.Fury)
			{
				curDuration = furyDuration;
				curSkillId = SkillId.ShuiLiu_QiangHua;
			}
		}

		private void CheckSkill()
		{
			switch (stage)
			{
			case Stage.Common:
				if (curSkillId == SkillId.ShuiKeng)
				{
					curSkillId = SkillId.ShuiLiu;
				}
				else if (curSkillId == SkillId.ShuiLiu)
				{
					curSkillId = SkillId.ShuiKeng;
				}
				break;
			case Stage.Fury:
				if (curSkillId == SkillId.ShuiKeng_QiangHua)
				{
					curSkillId = SkillId.ShuiLiu_QiangHua;
				}
				else if (curSkillId == SkillId.ShuiLiu_QiangHua)
				{
					curSkillId = SkillId.ShuiKeng_QiangHua;
				}
				break;
			}
			ILRuntimeAPI.CreateSkill((int)curSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
		}

		private IEnumerator Wait(System.Action callback, FP duration)
		{
			yield return duration;
			callback?.Invoke();
		}

		private void OnCastSkillEnd(IEvent ievent)
		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = (AdventureActorCastSkillEndEvent)ievent;
			if (adventureActorCastSkillEndEvent == null || ((AdventureActor)adventureActorCastSkillEndEvent.sender).Id != _actor.Id)
			{
				return;
			}
			if (curDuration <= 0)
			{
				CheckSkill();
				return;
			}
			if (chooseSkill != null)
			{
				StopCoroutine(chooseSkill);
				chooseSkill = null;
			}
			chooseSkill = StartCoroutine(Wait(CheckSkill, curDuration));
		}
	}
	public class Skill_AlertMovement : SkillSimpleBase
	{
		private TSVector2 targetPOS;

		private LogicEntity target;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			targetPOS = MoveTargetPOS();
			target = GetTarget();
			MoveToPosition(targetPOS, 0.5, AdventureActor.MovementMode.Walk, 4f);
			yield return WaitMoveStatus();
			yield return BeginLookAt(target, 0.3, 600);
		}

		private TSVector2 MoveTargetPOS()
		{
			TSVector2 zero = TSVector2.zero;
			TSVector2 entityPosition = GetEntityPosition(GetCurrentPlayer());
			TSVector2 position = GetPosition();
			FP radius = 12;
			FP innerRadius = 8;
			FP angle = 60;
			FP tSVectToAngle = GetTSVectToAngle(position - entityPosition, 0);
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, tSVectToAngle);
			for (int i = 0; i < 5; i++)
			{
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			for (int j = 0; j < 5; j++)
			{
				FP fP = ((!(GetRandomValue(0, 1) < 0.5)) ? 1 : (-1));
				tSVectToAngle = 12;
				angle = 8;
				innerRadius = 15;
				radius = GetTSVectToAngle(entityPosition - position, 40 * fP);
				shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), tSVectToAngle, angle, innerRadius, radius);
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			return TSVector2.zero;
		}

		protected LogicEntity GetTarget()
		{
			LogicEntity result = GetAttackTarget();
			if (!CheckTargetIsValid(result))
			{
				result = GetCurrentPlayer();
			}
			return result;
		}
	}
	public class Skill_Death_LD : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Z };

		private static readonly string airBorneDeathEffectAlias = "fx_common_base_die_airborne";

		private static readonly FP effectDuration = 2f;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			SendDeclareDeadEvent();
			yield return StartCor(KillTeammate());
			SetCloseBlockEnable();
			SendDeclareDeadEvent();
			if (DieWithAirBorne() && !_actor.IsBossMonster())
			{
				_actor.PlayHurtAnim();
				PlayEffect(airBorneDeathEffectAlias, 1f, _actor.tsTransform.PositionY, _actor.tsTransform.Position, (_actor.killer != null) ? _actor.killer.tsTransform.Rotation : _actor.tsTransform.Rotation);
			}
			else
			{
				_actor.PlayDeathAnim();
				BeginAttack(1, actionKeys);
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
		}

		private bool DieWithAirBorne()
		{
			if (_actor.movementState == ActorState.Jump)
			{
				return true;
			}
			if (_actor.killerHitBox == null)
			{
				return false;
			}
			if ((_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.KnockBack) == HitBox.FeatureFlag.KnockBack)
			{
				return true;
			}
			return (_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.AirBorne) == HitBox.FeatureFlag.AirBorne;
		}

		protected IEnumerator KillTeammate()
		{
			List<LogicEntity> targetsByFaction = GetTargetsByFaction(isFriend: true);
			for (int i = 0; i < targetsByFaction.Count; i++)
			{
				KillActors(targetsByFaction);
			}
			yield return null;
		}
	}
