	public class Skill_FloatHitFloor_F : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Fly = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.C };

		private static readonly ComboInputBuffer.ActionKey[] Fly_Plus = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };

		private static readonly FP TraceTime = 4;

		private static readonly int FireBallAmount = 10;

		private ComboInputBuffer.ActionKey[] Fly_Combo;

		private bool IsUpgrade;

		private long UpgradeAreaEffect;

		private FP TraceTimeCount;

		private LogicEntity TraceTarget;

		private CoroutineNode CheckTraceFinishNode;

		private FP Difficulty;

		private int FireBallCount;

		protected override void OnSkillEnable()
		{
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
			if (Difficulty == 3 || (!MonsterInState(1) && Difficulty == 2))
			{
				Fly_Combo = Fly_Plus;
				IsUpgrade = true;
			}
			else
			{
				Fly_Combo = Fly;
				IsUpgrade = false;
			}
			FireBallCount = 0;
		}

		protected override void OnSkillDisable()
		{
			StopAreaEffect(UpgradeAreaEffect);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Fly_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.5);
			if (IsUpgrade)
			{
				UpgradeAreaEffect = PlayAreaEffect("AreaEffect_FireAreaWhenFlying", GetPosition());
			}
			yield return WaitTime(0.5);
			TraceTarget = GetAttackTarget(isUpToDate: true);
			BeginTrace(TraceTarget, 1, -1, TraceTime);
			TraceTimeCount = TraceTime;
			StartCor(ref CheckTraceFinishNode, CheckTraceFinish());
			while (TraceTimeCount > 0)
			{
				if (!CheckTargetIsValid(TraceTarget))
				{
					TraceTimeCount = 0;
				}
				else if (TraceTarget != GetAttackTarget(isUpToDate: true))
				{
					TraceTarget = GetAttackTarget();
					StopTrace();
					BeginTrace(TraceTarget, 1, -1, TraceTimeCount);
				}
				yield return WaitTime(0.03);
				TraceTimeCount -= (FP)0.03;
			}
			Skill_FloatHitFloor_F skill_FloatHitFloor_F = this;
			TSVector2 position = GetPosition();
			skill_FloatHitFloor_F.PlayEarlyWarningEffect("FireEarlyWarning_5m", 1f, default(FP), position, default(FP), 0.95f);
			yield return WaitTime(0.5);
			StopCor(CheckTraceFinishNode);
			StopTrace();
			StopAreaEffect(UpgradeAreaEffect);
			CancelAttack();
			if (IsUpgrade)
			{
				yield return WaitCustomEvent("HitFloorFrame");
				FireBallShoot();
			}
			yield return WaitTime(0.5);
			BeginAttack(2, "FlyRest", flushInputedKeys: true, forceInterruptAttack: true);
			PlayWwiseSound("mon_50511_hover");
			yield return WaitTime(3);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator CheckTraceFinish()
		{
			yield return WaitTraceFinish();
			TraceTimeCount = 0;
		}

		private void FireBallShoot()
		{
			while (FireBallCount < FireBallAmount)
			{
				int num = 360 / FireBallAmount / 2 + 360 / FireBallAmount * FireBallCount;
				TSVector2 position = GetPosition();
				FP radius = 10;
				FP innerRadius = 7;
				FP angle = 360 / FireBallAmount;
				FP rotation = num;
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, rotation);
				if (GetShapeRandomPoint(shapeData, _actor, isReachable: true) != GetPosition())
				{
					FanMultipleShoot("Mine_Throw_Slow", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 1, 0, GetPosition(), 0, RotateTo(GetForward(), num), 0, AimType.Position, BulletDirectionType.BulletToTarget, 15, 0, 2.5, GetShapeRandomPoint(shapeData, _actor, isReachable: true));
				}
				FireBallCount++;
			}
		}
	}
	public class Skill_FloatMove_F : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Fly_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.C };

		private FP Radius = 15;

		private FP InnerRadius = 10;

		private FP DashSpeed = 16;

		protected FP RotationSpeed = 1;

		private TSVector2 MoveToPoint;

		private TSVector2 ShapePosition;

		private FP DashDistance;

		private TSVector2 DashDirection;

		protected override void OnSkillDisable()
		{
			StopWaitLookAt();
			RemoveBuffFromTarget(_actor, 990020140);
		}

		protected override IEnumerator DoMainLogic()
		{
			AddBuffToTarget(_actor, 990020140);
			TSVector2 SelfPosition = GetPosition();
			ShapePosition = GetEntityPosition(GetAttackTarget());
			Skill_FloatMove_F skill_FloatMove_F = this;
			TSVector2 shapePosition = ShapePosition;
			FP radius = Radius;
			FP innerRadius = InnerRadius;
			DeterministicShape RandomShape = skill_FloatMove_F.GetShapeData(DeterministicShape.ShapeType.Circle, shapePosition, default(FP), default(FP), radius, innerRadius);
			MoveToPoint = GetShapeRandomPoint(RandomShape, GetCurrentPlayer(), isReachable: true);
			DashDirection = MoveToPoint - SelfPosition;
			DashDistance = Distance(MoveToPoint, SelfPosition);
			while (DashDistance <= 5)
			{
				MoveToPoint = GetShapeRandomPoint(RandomShape, GetCurrentPlayer(), isReachable: true);
				DashDirection = MoveToPoint - SelfPosition;
				DashDistance = Distance(MoveToPoint, SelfPosition);
				yield return WaitFrame(1);
			}
			BeginAttack(1, Fly_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("StartDash");
			SetCloseBlockEnable();
			BeginDash(1, DashDirection, DashSpeed, DashDistance, 0, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			WaitLookAt_NoWait(GetAttackTarget(isUpToDate: true), 999, 200);
			yield return WaitDashFinish();
			CancelAttack();
			yield return WaitCustomEvent("TurnEnd");
			StopWaitLookAt();
			SetCloseBlockDisable();
			yield return WaitTime(0.25);
			BeginAttack(2, "FlyRest", flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(3);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_GroundFire : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] Shoot_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.E };

		private readonly FP AimTime = 1.5;

		private readonly FP AttackPrepareTimeNormal = 0.2;

		private readonly FP AttackPrepareTimePlus = 0;

		private readonly FP AttackShapeAngle = 120;

		private readonly int volcanoSkillId = 5051121;

		private TSVector2 AttackPosition;

		private TSVector2 LeftHandShootPosition;

		private TSVector2 RightHandShootPosition;

		private LogicEntity AimTarget;

		private CoroutineNode GetTargetPositionNode;

		private FP AimTimeCount;

		private long AimTargetLinkFX;

		private long AimTargetLinkFX_L;

		private long AimTargetLinkFX_R;

		private long AimPointLinkFX;

		private long AimPointLinkFX_L;

		private long AimPointLinkFX_R;

		private long BeginAttackFX;

		private long BeginAttackFX_L;

		private long BeginAttackFX_R;

		private long LeftHandFX;

		private long RightHandFX;

		private FP AttackPrepareTime;

		private DeterministicShape AttackShape;

		private FP Difficulty;

		protected override void OnSkillEnable()
		{
			AttackPosition = GetEntityPosition(GetAttackTarget());
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
			AimTimeCount = AimTime;
			if (MonsterInState(3))
			{
				AttackPrepareTime = AttackPrepareTimePlus;
			}
			else
			{
				AttackPrepareTime = AttackPrepareTimeNormal;
			}
		}

		protected override void OnSkillDisable()
		{
			StopEffect(AimTargetLinkFX);
			StopEffect(AimTargetLinkFX_L);
			StopEffect(AimTargetLinkFX_R);
			StopEffect(AimPointLinkFX);
			StopEffect(AimPointLinkFX_L);
			StopEffect(AimPointLinkFX_R);
			StopEffect(BeginAttackFX);
			StopEffect(BeginAttackFX_L);
			StopEffect(BeginAttackFX_R);
			StopEffect(LeftHandFX);
			StopEffect(RightHandFX);
		}

		protected override IEnumerator DoMainLogic()
		{
			Skill_GroundFire skill_GroundFire = this;
			Skill_GroundFire skill_GroundFire2 = this;
			TSVector2 position = GetPosition();
			FP radius = 200;
			FP innerRadius = 0;
			FP attackShapeAngle = AttackShapeAngle;
			FP rotation = GetRotation();
			skill_GroundFire.AttackShape = skill_GroundFire2.GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, attackShapeAngle, rotation);
			LeftHandShootPosition = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(-2.24, 1.96));
			RightHandShootPosition = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(1.94, 1.94));
			BeginAttack(1, Shoot_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1);
			LeftHandFX = PlayEffect("Shoot_HandFX_L");
			RightHandFX = PlayEffect("Shoot_HandFX_R");
			AimTarget = GetAttackTarget(isUpToDate: true);
			if (CheckTargetIsValid(AimTarget))
			{
				StartCor(ref GetTargetPositionNode, GetTargetPosition());
				PlayAimTargetLinkFX("LaserA");
				while (AimTimeCount > 0)
				{
					if (!CheckTargetIsValid(AimTarget) || !AreaCheckMonsterTarget(AttackShape))
					{
						StopEffect(AimTargetLinkFX);
						StopCor(GetTargetPositionNode);
						PlayAimPointLinkFX("LaserA");
						AimTimeCount = 0;
					}
					AimTimeCount -= (FP)0.03;
					yield return null;
				}
			}
			else
			{
				PlayAimPointLinkFX("LaserA");
				yield return WaitTime(AimTime);
			}
			StopEffect(AimTargetLinkFX);
			StopEffect(AimTargetLinkFX_L);
			StopEffect(AimTargetLinkFX_R);
			StopEffect(AimPointLinkFX);
			StopEffect(AimPointLinkFX_L);
			StopEffect(AimPointLinkFX_R);
			StopCor(GetTargetPositionNode);
			PlayBeginAttackFX("LaserB");
			if (Difficulty != 3)
			{
				PlayAreaEffect("GroundFire", AttackPosition);
			}
			else
			{
				PlayAreaEffect("GroundFire_Plus", AttackPosition);
				UseMonsterCloneActorCastSkill(volcanoSkillId);
				SetLogicTagTSVector2Value(_actor, "GroundFire_Plus_Position", AttackPosition);
			}
			yield return WaitTime(0.3);
			CancelAttack();
			yield return WaitTime(0.4);
			PlayLinkEffect("Laser_Shoot_L", useCustomSource: true, null, LeftHandShootPosition, 1.12, null, AttackPosition);
			PlayLinkEffect("Laser_Shoot_R", useCustomSource: true, null, RightHandShootPosition, 1.08, null, AttackPosition);
			StopEffect(BeginAttackFX);
			StopEffect(BeginAttackFX_L);
			StopEffect(BeginAttackFX_R);
			StopEffect(LeftHandFX);
			StopEffect(RightHandFX);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private IEnumerator GetTargetPosition()
		{
			while (CheckTargetIsValid(AimTarget))
			{
				if (AreaCheckMonsterTarget(AttackShape))
				{
					AttackPosition = GetEntityPosition(AimTarget);
				}
				yield return null;
			}
		}

		private void PlayAimTargetLinkFX(string FxName)
		{
			LogicEntity target = AimTarget;
			AimTargetLinkFX = PlayLinkEffect(FxName, useCustomSource: false, null, default(TSVector2), default(FP), target);
			string fxAlias = FxName + "_L";
			target = AimTarget;
			AimTargetLinkFX_L = PlayLinkEffect(fxAlias, useCustomSource: false, null, default(TSVector2), default(FP), target);
			string fxAlias2 = FxName + "_R";
			target = AimTarget;
			AimTargetLinkFX_R = PlayLinkEffect(fxAlias2, useCustomSource: false, null, default(TSVector2), default(FP), target);
		}

		private void PlayAimPointLinkFX(string FxName)
		{
			TSVector2 attackPosition = AttackPosition;
			FP targetPositionY = 0;
			AimPointLinkFX = PlayLinkEffect(FxName, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
			string fxAlias = FxName + "_L";
			attackPosition = AttackPosition;
			targetPositionY = 0;
			AimPointLinkFX_L = PlayLinkEffect(fxAlias, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
			string fxAlias2 = FxName + "_R";
			attackPosition = AttackPosition;
			targetPositionY = 0;
			AimPointLinkFX_R = PlayLinkEffect(fxAlias2, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
		}

		private void PlayBeginAttackFX(string FxName)
		{
			TSVector2 attackPosition = AttackPosition;
			FP targetPositionY = 0;
			BeginAttackFX = PlayLinkEffect(FxName, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
			string fxAlias = FxName + "_L";
			attackPosition = AttackPosition;
			targetPositionY = 0;
			BeginAttackFX_L = PlayLinkEffect(fxAlias, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
			string fxAlias2 = FxName + "_R";
			attackPosition = AttackPosition;
			targetPositionY = 0;
			BeginAttackFX_R = PlayLinkEffect(fxAlias2, useCustomSource: false, null, default(TSVector2), default(FP), null, attackPosition, targetPositionY);
		}
	}
