				skill_HitFloor_F5.PlusAreaWarningFXID = skill_HitFloor_F6.PlayEarlyWarningEffect("FireEarlyWarning", 9f, default(FP), fxPosition, default(FP), 2.75f);
			}
			yield return WaitTime(0.4);
			Skill_HitFloor_F skill_HitFloor_F7 = this;
			Skill_HitFloor_F skill_HitFloor_F8 = this;
			string loopFxName = LoopFxName;
			fxPosition = FxPosition;
			skill_HitFloor_F7.LoopFXID = skill_HitFloor_F8.PlayEffect(loopFxName, 1f, default(FP), fxPosition, default(FP), 1.5f);
			if (Difficulty != 1)
