			SetLogicTagToggleValue(_actor, "Achievement", value: false);
			Skill_HitFloor_F skill_HitFloor_F10 = this;
			AdventureActor actor = _actor;
			Skill_HitFloor_F skill_HitFloor_F11 = this;
			TSVector2 fxPosition2 = FxPosition;
			FP hitRadius_EndStrike = HitRadius_EndStrike;
			DeterministicShape shapeData = skill_HitFloor_F11.GetShapeData(DeterministicShape.ShapeType.Circle, fxPosition2, default(FP), default(FP), hitRadius_EndStrike);
			Skill_HitFloor_F skill_HitFloor_F12 = this;
			FP knockBackForce = 20;
			FP knockBackDistance = 4;
			hitRadius_EndStrike = 0.5;
			FP hitStrenth = 4;
			skill_HitFloor_F10.AreaHit_Simple(actor, shapeData, skill_HitFloor_F12.GetHitFeatureData(HitBox.FeatureFlag.KnockBack | HitBox.FeatureFlag.Stiff, knockBackForce, knockBackDistance, UseAtttackForward: false, default(FP), null, null, hitRadius_EndStrike, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, hitStrenth, UseHitBoxPosition: true), 50511112, 0.5, HitBox.HurtAnimType.Small, "HittedFX_Magic");
			if (Difficulty != 1)
			{
				StopEffect(PlusAreaFXID);
