		public void OnEnable()
		{
			isToughnessWhelmed = false;
			toughnessCount = 0;
			_currentStage = 1;
			_waitShadow = false;
			ShowBlood(isShow: true);
			InitSkill();
			if (_lookAtTarget == null)
			{
				_lookAtTarget = new LookAtTarget();
			}
			_actor.logicVariable.SetLogicTagValue("ViolentBuffId", ViolentBuffId);
			_actor.logicVariable.SetLogicTagValue("SkillId_whelmed", 5050110);
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			_actor.EnableImmuneControl();
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (monsterAdventureActor != null)
			{
				monsterAdventureActor.monsterToughnessInfo.isUseDefaultBrokenState = false;
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
		}

		protected void ShowBlood(bool isShow)
		{
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (!(monsterAdventureActor == null))
			{
				monsterAdventureActor.ShowBlood(isShow);
			}
		}

		public void OnStart()
		{
			_logicVariable = ActorHelper.GetFlowLogicVariable(_actor.gameObject);
			stageRandomSkill();
			_actor.StopImmuneControlCueEffect();
		}

		protected void InitSkill()
		{
			foreach (int key in skillInfo.Keys)
			{
				_runSkillCDEnd[key] = 0;
			}
		}

		public void OnStop()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
		}

		public void OnUpdate()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaViolent_Start"))
			{
				_receiveDamage = 0;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent_Start", value: false);
			}
			if (_logicVariable.GetLogicTagToggle("5050100EndWhelmed"))
			{
				_actor.logicVariable.ToggleLogicTag("5050100EndWhelmed", value: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: false);
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: true);
			}
			if (_logicVariable.GetLogicTagToggle("CheckSkill_ShaSha"))
			{
				stageRandomSkill();
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			}
		}

		public void OnDisable()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
			StopCoroutine(ref _corCountDown);
			StopCoroutine(ref _waitCreateSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
			_actor.DisableSuperArmor();
		}

		protected void OnRemoveBuff(IEvent evt)
		{
			if (evt.sender as AdventureActor == _actor && (evt as AdventureActorRemoveBuff).eventInfo.buffId == ViolentBuffId)
			{
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				StopCoroutine(ref _corCountDown);
				StartCoroutine(ref _corCountDown, CorCountDown());
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.InterruptForceControl();
				toughnessCount++;
				StopCoroutine(ref _waitCreateSkill);
				_lookAtTarget?.StopLookAt();
				if (toughnessCount <= 2)
				{
					isToughnessWhelmed = true;
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050110, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				}
				if (_currentStage == 2)
				{
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050110, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				}
			}
		}

		protected IEnumerator CorCountDown()
		{
			_waitShadow = false;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(ViolentTime));
			_waitShadow = true;
		}

		protected bool checkSkill(int _skillid, FP _logicTime)
		{
			if (_skillid < 0)
			{
				return true;
			}
			if (_runSkillCDEnd[_skillid] < _logicTime && skillInfo[_skillid][1] < _logicTime)
			{
				return true;
			}
			return false;
		}

		protected bool havePlayer()
		{
			List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(_actor, crushSearchRadius, isConfront: true, includeSelf: false);
			if (list != null && list.Count > 0)
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (TSVector2.Distance(_actor.tsTransform.Position, list[i].tsTransform.Position) > crushSearchInnerRadius)
					{
						return true;
					}
				}
			}
			return false;
		}

		protected FP RandomSkill(Dictionary<int, FP> dicGroup, FP waitTime, int _stage)
		{
			FP fP = 0;
			Dictionary<int, FP> dictionary = new Dictionary<int, FP>();
			FP logicTime = _actor.LogicTime;
			foreach (KeyValuePair<int, FP> item in dicGroup)
			{
				if (checkSkill(item.Key, logicTime))
				{
					fP += item.Value;
					dictionary[item.Key] = fP;
				}
			}
			if (fP > 0)
			{
				FP fP2 = TSRandom.Range(0, fP);
				foreach (KeyValuePair<int, FP> item2 in dictionary)
				{
					if (!(fP2 < item2.Value))
					{
						continue;
					}
					if (item2.Key >= 0)
					{
						CreateSkill(item2.Key, waitTime);
					}
					else if (item2.Key == -1)
					{
						LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
						if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
						{
							logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
						}
						_actor.MoveTo(logicEntity.tsTransform.Position, 5, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								if (_stage == 1)
								{
									CheckStageOne();
								}
								else
								{
									CheckStageTwo();
								}
							}
						});
					}
					else
					{
						tmpRunSpecialGroup = true;
						tmpSpecialGroup = dicSpecialSkillGroup[item2.Key];
						tmpSpecialIndex = 0;
						tmpWaitTime = 0;
						stageRandomSkill();
					}
					break;
				}
			}
			return fP;
		}

		protected void CheckStageOne()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050104] < _actor.LogicTime)
					{
						CreateSkill(5050104, stageOneWaitTime);
					}
					else if (RandomSkill(StageOne_DisLessThan6_Front, stageOneWaitTime, 1) == 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050113, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050104] < _actor.LogicTime)
				{
					CreateSkill(5050104, stageOneWaitTime);
				}
				else if (_runSkillCDEnd[5050103] < _actor.LogicTime)
				{
					CreateSkill(5050103, stageOneWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageOne();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050104] < _actor.LogicTime)
				{
					CreateSkill(5050104, stageOneWaitTime);
				}
				else
				{
					RandomSkill(StageOne_DisMoreThan6_Front, stageOneWaitTime, 1);
				}
			}
			else if (havePlayer() && fP2 < 150 && _runSkillCDEnd[5050104] < _actor.LogicTime)
			{
				CreateSkill(5050104, stageOneWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageOne();
				});
			}
		}

		protected void CheckStageTwo()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050104] < _actor.LogicTime)
					{
						CreateSkill(5050104, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisLessThan6_Front, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050113, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050104] < _actor.LogicTime)
				{
					CreateSkill(5050104, stageTwoWaitTime);
				}
				else if (checkSkill(5050103, _actor.LogicTime))
				{
					CreateSkill(5050103, stageTwoWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageTwo();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (_actor.buffComponent.CheckBuffByBuffID(ViolentBuffId))
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050104] < _actor.LogicTime)
					{
						CreateSkill(5050104, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisMoreThan6_Front_Violent, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050113, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050104] < _actor.LogicTime)
				{
					CreateSkill(5050104, stageTwoWaitTime);
				}
				else
				{
					RandomSkill(StageTwo_DisMoreThan6_Front_ViolentNone, stageTwoWaitTime, 2);
				}
			}
			else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050104] < _actor.LogicTime)
			{
				CreateSkill(5050104, stageTwoWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageTwo();
				});
			}
		}

		protected void CreateSkill(int skillId, FP waitTime)
		{
			if (_actor.actorHealthInfo.isAlive)
			{
				StopCoroutine(ref _waitCreateSkill);
				StartCoroutine(ref _waitCreateSkill, waitTimeRunSkill(skillId, waitTime));
			}
		}

		protected IEnumerator waitTimeRunSkill(int skillId, FP waitTime)
		{
			tempSkillId = skillId;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitTime));
			if (skillId != 5050104)
			{
				LogicEntity target = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
				if (_traceTarget == null)
				{
					_traceTarget = new TraceTarget();
				}
				_traceTarget.BeginTrace(_actor, target, skillInfo[skillId][2], -1, skillInfo[skillId][3], delegate
				{
					TSVector2 a = target.tsTransform.Position - _actor.tsTransform.Position;
					TSVector2 forward = _actor.tsTransform.Forward;
					if (TSVector2.Angle(a, forward) > skillInfo[skillId][4] && skillId != 5050103)
					{
						_lookAtTarget?.StopLookAt();
						if (_lookAtTarget == null)
						{
							_lookAtTarget = new LookAtTarget();
						}
						_lookAtTarget.BeginLookAt(_actor, target, 0, 0, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
								ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
							}
						});
					}
					else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
					{
						_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
						ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
					}
				}, OnTraceCancel);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
				ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnTraceCancel(bool targetDied, bool isInterrupt)
		{
			bool logicTagToggle = _logicVariable.GetLogicTagToggle("5050100ShaShaSpecial");
			if (_actor.actorHealthInfo.isAlive && !logicTagToggle && tempSkillId != 0)
			{
				_runSkillCDEnd[tempSkillId] = _actor.LogicTime + skillInfo[tempSkillId][0];
				ILRuntimeAPI.CreateSkill(tempSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnFinishCallback(bool success)
		{
			tempSkillId = 0;
			if (_waitShadow)
			{
				_waitShadow = false;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050108, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				stageRandomSkill();
			}
		}

		protected void stageRandomSkill()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaChangeStage"))
			{
				_currentStage = 2;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050109, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaChangeStage", value: false);
			}
			else if (tmpRunSpecialGroup)
			{
				CreateSkill(tmpSpecialGroup[tmpSpecialIndex], tmpWaitTime);
				tmpSpecialIndex++;
				if (tmpSpecialIndex == tmpSpecialGroup.Count)
				{
					tmpRunSpecialGroup = false;
				}
			}
			else if (_currentStage == 1)
			{
				CheckStageOne();
			}
			else if (!isSpecialSkillListEnd)
			{
				CreateSkill(specialSkillList[runSpecialSkillListCount], 0);
				runSpecialSkillListCount++;
				if (runSpecialSkillListCount == specialSkillList.Count)
				{
					isSpecialSkillListEnd = true;
				}
			}
			else
			{
				CheckStageTwo();
			}
		}
	}
	public class Action_Lv3_BossRush : MonsterActionBase
	{
		private static readonly int Dash = 5050191;

		private static readonly int Sweep = 5050192;

		private static readonly int ChargeFlick = 5050173;

		private static readonly int JumpFlick = 5050184;

		private static readonly int Crush = 5050194;

		private static readonly int CrargeBreath = 5050175;

		private static readonly int WaterSpit = 5050196;

		private static readonly int WaterSpit3 = 5050186;

		private static readonly int ShadowBall = 5050177;

		private static readonly int ShadowGathering = 5050198;

		private static readonly int TravelAround = 5050179;

		private static readonly int Whelmed = 5050180;

		private static readonly int Jump = 5050114;

		private static readonly int Wander = 5050199;

		private static readonly FP HpPercentStage2 = 0.7;

		private static readonly FP FarSkillOutRadius = 12;

		private static readonly FP FarSkillinnerRadius = 7.5;

		private static readonly FP NearSkillOutRadius = 5;

		private static readonly FP fanAngle = 90;

		private static readonly int testSkillId = 0;

		private static readonly int intervaltime = 0;

		private static readonly int Stage2RequireLevel = 20;

		private int SmallNearSkillCount;

		private int TmpSkillID;

		private bool IsPhase2;

		private bool IsPhase3;

		private bool skillrandom = true;

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = SkillGroup01;
			list.Add(new BaseBranchInfo(1001, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = SkillGroup02;
			list.Add(new BaseBranchInfo(1002, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = DashSkillCast;
			list.Add(new BaseBranchInfo(1003, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = StressSkillCast;
			list.Add(new BaseBranchInfo(1004, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = UltraSkillCast;
			list.Add(new BaseBranchInfo(1005, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = FarSkillCast;
			list.Add(new BaseBranchInfo(1006, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = ShadowSkillCast;
			list.Add(new BaseBranchInfo(1007, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = JumpFlickCast;
			list.Add(new BaseBranchInfo(1008, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = WanderCast;
			list.Add(new BaseBranchInfo(9999, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> sequenceDict = new Dictionary<int, List<int>>
			{
				[1] = new List<int> { 1004, 1003, 1008, 1001, 1003, 1002 },
				[2] = new List<int>
				{
					1007, 1006, 1005, 1001, 1003, 1002, 1007, 1006, 1006, 1005,
					1001, 1003, 1002
				}
			};
			InitSequenceBranches(1, sequenceBranches, sequenceDict);
		}

		protected override void OnActionEnable()
		{
			StartCor(StageTimeCount());
		}

		protected override void SetListenEvents()
		{
			InitListenEvent(MonsterEventType.SelfToughnessBroken, active: true, OnToughnessState);
			InitListenEvent(MonsterEventType.BattleLevelChange, active: true, LevelUp);
		}

		private IEnumerator StageTimeCount()
		{
			yield return WaitTime(60);
			SwitchSequence(2);
			yield return WaitTime(120);
		}

		private void GotoCastSkill(int ID)
		{
			if (testSkillId != 0)
			{
				ID = testSkillId;
			}
			TmpSkillID = ID;
			CastSkill(ID);
		}

		private bool SmallSkillWithLongDistance()
		{
			TSVector2 position = GetPosition();
			FP farSkillOutRadius = FarSkillOutRadius;
			FP farSkillinnerRadius = FarSkillinnerRadius;
			FP angle = fanAngle;
			FP rotation = GetRotation();
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), farSkillOutRadius, farSkillinnerRadius, angle, rotation);
			return IsAttackTargetInArea(shapeData);
		}

		private IEnumerator SkillGroup01()
		{
			GotoCastSkill(Sweep);
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator SkillGroup02()
		{
			if (_actor.buffComponent.CheckBuffByBuffID(505010110))
			{
				GotoCastSkill(WaterSpit3);
			}
			else
			{
				GotoCastSkill(WaterSpit);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator DashSkillCast()
		{
			GotoCastSkill(Dash);
			yield return WaitSkillFinish();
		}

		private IEnumerator StressSkillCast()
		{
			GotoCastSkill(CrargeBreath);
			yield return WaitSkillFinish();
		}

		private IEnumerator UltraSkillCast()
		{
			if (skillrandom)
			{
				GotoCastSkill(JumpFlick);
				skillrandom = false;
			}
			else
			{
				GotoCastSkill(Crush);
				skillrandom = true;
			}
			yield return WaitSkillFinish();
		}

		private IEnumerator FarSkillCast()
		{
			if (skillrandom)
			{
				GotoCastSkill(ShadowBall);
				skillrandom = false;
			}
			else
			{
				GotoCastSkill(CrargeBreath);
				skillrandom = true;
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator ShadowSkillCast()
		{
			if (TmpSkillID != ShadowGathering)
			{
				GotoCastSkill(ShadowGathering);
				yield return WaitSkillFinish();
			}
		}

		private IEnumerator JumpFlickCast()
		{
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) <= 6)
			{
				GotoCastSkill(ChargeFlick);
			}
			else
			{
				GotoCastSkill(JumpFlick);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator WanderCast()
		{
			GotoCastSkill(Wander);
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private void PhaseChange(IEvent evt)
		{
			if (_actor.actorHealthInfo.hpPercentage <= HpPercentStage2 && !IsPhase2)
			{
				_actor.actorSkillManage.DestoryAllSkill();
				_actor.InterruptAttack(force: true);
				base.OnHandleCustomSwitchState();
				SetLogicTagFpValue(_actor, "TaiDeng_Stage", 2);
				SwitchSequence(2);
				IsPhase2 = true;
			}
		}

		private void LevelUp(IEvent evt)
		{
			if ((evt as AdventureMonsterBattleLevelChangedEvent).newLevel == Stage2RequireLevel)
			{
				SwitchSequence(2);
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.InterruptForceControl();
				_actor.actorSkillManage.DestoryAllSkill();
				_actor.InterruptAttack(force: true);
				GotoCastSkill(Whelmed);
			}
		}
	}
	public class Parrallel_BossRush : Parallel_BossRush
	{
		private int skill_1 = 5050191;

		private int skill_2 = 5050186;

		private int skill_3 = 5050198;

		private int skill_4 = 5050196;

		private static int hitTag = CommonHelper.StringToHash("ShaSha_Duyu");

		private FP delayTime = 6;

		private bool isHit_1;

		private bool isHit_2;

		private bool isHit_3;

		private bool isHit_4;

		private CoroutineNode corSkill_1;

		private CoroutineNode corSkill_2;

		private CoroutineNode corSkill_3;

		private CoroutineNode corSkill_4;

		public override void OnStart()
		{
			base.OnStart();
			isHit_1 = false;
			isHit_2 = false;
			isHit_3 = false;
			isHit_4 = false;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			StopCoroutine(ref corSkill_1);
			StopCoroutine(ref corSkill_2);
			StopCoroutine(ref corSkill_3);
			StopCoroutine(ref corSkill_4);
		}

		protected override void OnActorCastSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
			base.OnActorCastSkill(castSkillEvent);
			if (_actor != null && castSkillEvent.sender as AdventureActor == _actor)
			{
				if (castSkillEvent.skillEventInfo.skillId == skill_1)
				{
					isHit_1 = false;
					StartCoroutine(ref corSkill_1, DoCheckHit(skill_1));
				}
				else if (castSkillEvent.skillEventInfo.skillId == skill_2)
				{
					isHit_2 = false;
					StartCoroutine(ref corSkill_2, DoCheckHit(skill_2));
				}
				else if (castSkillEvent.skillEventInfo.skillId == skill_3)
				{
					isHit_3 = false;
					StartCoroutine(ref corSkill_3, DoCheckHit(skill_3));
				}
				else if (castSkillEvent.skillEventInfo.skillId == skill_4)
				{
					isHit_4 = false;
					StartCoroutine(ref corSkill_4, DoCheckHit(skill_4));
				}
			}
		}

		private IEnumerator DoCheckHit(int skillId)
		{
			yield return _actor.WaitTime(delayTime);
			if (skillId == skill_1)
			{
				if (!isHit_1 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)15))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)15);
				}
				isHit_1 = false;
			}
			else if (skillId == skill_2)
			{
				if (!isHit_2 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)15))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)15);
				}
				isHit_2 = false;
			}
			if (skillId == skill_3)
			{
				if (!isHit_3 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)15))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)15);
				}
				isHit_3 = false;
			}
			else if (skillId == skill_4)
			{
				if (!isHit_4 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)15))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)15);
				}
				isHit_4 = false;
			}
		}

		protected override void OnActorReceiveDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
			if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, hitTag) && damageEvent.to is PlayerAdventureActor)
			{
				isHit_1 = true;
				isHit_2 = true;
				isHit_3 = true;
				isHit_4 = true;
			}
		}
	}
	public class Skill_Crush_3_BossRush : SkillSimpleBase
	{
		protected readonly ComboInputBuffer.ActionKey[] actionKey_Left_Water = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };

		protected readonly ComboInputBuffer.ActionKey[] actionKey_Right_Water = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.S };

		protected readonly ComboInputBuffer.ActionKey[] actionKey_Left_Dark = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.P };

		protected readonly ComboInputBuffer.ActionKey[] actionKey_Right_Dark = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Q };

		private static readonly string Jumpto = "Jumpto";

		protected FP RotateSpeed = 150;

		protected ComboInputBuffer.ActionKey[] _actionKey;

		protected ComboInputBuffer.ActionKey[] _JumpKey;

		protected TSVector2 targetdir;

		protected FP dis;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			UpdateData();
		}

		protected void UpdateData()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			LogicEntity target = GetAttackTarget();
			if (_actor.DistanceWithRadius(target) > 4.5)
			{
				BeginLookAt(target, 1, 240);
				yield return WaitTime(0.5);
				TSVector2 entityPosition = GetEntityPosition(target);
				Skill_Crush_3_BossRush skill_Crush_3_BossRush = this;
				Skill_Crush_3_BossRush skill_Crush_3_BossRush2 = this;
				FP radius = 6;
				FP innerRadius = 3;
				TSVector2 shapeRandomPoint = skill_Crush_3_BossRush.GetShapeRandomPoint(skill_Crush_3_BossRush2.GetShapeData(DeterministicShape.ShapeType.Circle, entityPosition, default(FP), default(FP), radius, innerRadius), _actor, isReachable: true);
				BeginLookAtByPos(shapeRandomPoint, 2, 300);
				BeginAttack(1, Jumpto, flushInputedKeys: true, forceInterruptAttack: true);
				AddBuffToTarget(_actor, 990010030);
				FP fP = Distance(GetPosition(), shapeRandomPoint);
				dis = fP + 2f;
				FP dash_spd = dis / 0.8;
				yield return WaitTime(0.1);
				doDash(dis, dash_spd);
				yield return WaitTime(1.1);
				CancelAttack();
				RemoveBuffFromTarget(_actor, 990010030);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				yield return WaitTime(0.2);
			}
			FP fP2 = CalcAngleBetweenSelfAndAttackTarget(isSingleAngle: true);
			if (_actor.buffComponent.CheckBuffByBuffID(505010110))
			{
				if (fP2 > 0)
				{
					_actionKey = actionKey_Left_Dark;
					targetdir = RotateTo(GetForward(), fP2 - 90);
				}
				else
				{
					_actionKey = actionKey_Right_Dark;
					targetdir = RotateTo(GetForward(), fP2 + 90);
				}
			}
			else if (fP2 > 0)
			{
				_actionKey = actionKey_Left_Water;
				targetdir = RotateTo(GetForward(), fP2 - 90);
			}
			else
			{
				_actionKey = actionKey_Right_Water;
				targetdir = RotateTo(GetForward(), fP2 + 90);
			}
			BeginLookAtByDir_NotWait(targetdir, 1, 160);
