				_playFX_2.Play(_actor, _skill, _fx_2_path, 0, _actor.tsTransform.Position, _actor.tsTransform.Forward);
			}
			else if (string.Equals(eventName, stopEffect))
			{
				if (_playFX_1 != null)
				{
					_playFX_1.Stop(dontPlaySubFX: true);
					_playFX_1.Clear();
				}
				if (_playFX_2 != null)
				{
