			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.to != _actor))
			{
				if (adventureActorReceiveDamageEvent.elementType == GameEnum.elementType.FE)
				{
					_receiveDamage += adventureActorReceiveDamageEvent.value;
				}
				if (iFP.op_Implicit(_receiveDamage * 100 / _actor.actorHealthInfo.hpMax) > ReceiveDamageFEPre)
				{
					_comboAttack.InterruptAttack();
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
