			_actor.EnableImmuneControl();
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (monsterAdventureActor != null)
			{
				monsterAdventureActor.monsterToughnessInfo.isUseDefaultBrokenState = false;
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
		}

		protected void ShowBlood(bool isShow)
		{
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (!(monsterAdventureActor == null))
			{
				monsterAdventureActor.ShowBlood(isShow);
			}
		}

		public void OnStart()
		{
			_logicVariable = ActorHelper.GetFlowLogicVariable(_actor.gameObject);
			stageRandomSkill();
			_actor.StopImmuneControlCueEffect();
		}

		protected void InitSkill()
		{
			foreach (int key in skillInfo.Keys)
			{
				_runSkillCDEnd[key] = 0;
			}
		}

		public void OnStop()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
		}

		public void OnUpdate()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaViolent_Start"))
			{
				_receiveDamage = 0;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent_Start", value: false);
			}
			if (_logicVariable.GetLogicTagToggle("5050100EndWhelmed"))
			{
				_actor.logicVariable.ToggleLogicTag("5050100EndWhelmed", value: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: false);
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: true);
			}
			if (_logicVariable.GetLogicTagToggle("CheckSkill_ShaSha"))
			{
				stageRandomSkill();
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			}
		}

		public void OnDisable()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
			StopCoroutine(ref _corCountDown);
			StopCoroutine(ref _waitCreateSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
			_actor.DisableSuperArmor();
		}

		protected void OnRemoveBuff(IEvent evt)
		{
			if (evt.sender as AdventureActor == _actor && (evt as AdventureActorRemoveBuff).eventInfo.buffId == ViolentBuffId)
			{
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				StopCoroutine(ref _corCountDown);
				StartCoroutine(ref _corCountDown, CorCountDown());
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.InterruptForceControl();
				toughnessCount++;
				StopCoroutine(ref _waitCreateSkill);
				_lookAtTarget?.StopLookAt();
				if (toughnessCount <= 2)
				{
					isToughnessWhelmed = true;
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050160, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				}
				if (_currentStage == 2)
				{
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050160, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				}
			}
		}

		protected IEnumerator CorCountDown()
		{
			_waitShadow = false;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(ViolentTime));
			_waitShadow = true;
		}

		protected bool checkSkill(int _skillid, FP _logicTime)
		{
			if (_skillid < 0)
			{
				return true;
			}
			if (_runSkillCDEnd[_skillid] < _logicTime && skillInfo[_skillid][1] < _logicTime)
			{
				return true;
			}
			return false;
		}

		protected bool havePlayer()
		{
			List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(_actor, crushSearchRadius, isConfront: true, includeSelf: false);
			if (list != null && list.Count > 0)
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (TSVector2.Distance(_actor.tsTransform.Position, list[i].tsTransform.Position) > crushSearchInnerRadius)
					{
						return true;
					}
				}
			}
			return false;
		}

		protected FP RandomSkill(Dictionary<int, FP> dicGroup, FP waitTime, int _stage)
		{
			FP fP = 0;
			Dictionary<int, FP> dictionary = new Dictionary<int, FP>();
			FP logicTime = _actor.LogicTime;
			foreach (KeyValuePair<int, FP> item in dicGroup)
			{
				if (checkSkill(item.Key, logicTime))
				{
					fP += item.Value;
					dictionary[item.Key] = fP;
				}
			}
			if (fP > 0)
			{
				FP fP2 = TSRandom.Range(0, fP);
				foreach (KeyValuePair<int, FP> item2 in dictionary)
				{
					if (!(fP2 < item2.Value))
					{
						continue;
					}
					if (item2.Key >= 0)
					{
						CreateSkill(item2.Key, waitTime);
					}
					else if (item2.Key == -1)
					{
						LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
						if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
						{
							logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
						}
						_actor.MoveTo(logicEntity.tsTransform.Position, 5, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								if (_stage == 1)
								{
									CheckStageOne();
								}
								else
								{
									CheckStageTwo();
								}
							}
						});
					}
					else
					{
						tmpRunSpecialGroup = true;
						tmpSpecialGroup = dicSpecialSkillGroup[item2.Key];
						tmpSpecialIndex = 0;
						tmpWaitTime = 0;
						stageRandomSkill();
					}
					break;
				}
			}
			return fP;
		}

		protected void CheckStageOne()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050154] < _actor.LogicTime)
					{
						CreateSkill(5050154, stageOneWaitTime);
					}
					else if (RandomSkill(StageOne_DisLessThan6_Front, stageOneWaitTime, 1) == 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050163, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050154] < _actor.LogicTime)
				{
					CreateSkill(5050154, stageOneWaitTime);
				}
				else if (_runSkillCDEnd[5050153] < _actor.LogicTime)
				{
					CreateSkill(5050153, stageOneWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageOne();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050154] < _actor.LogicTime)
				{
					CreateSkill(5050154, stageOneWaitTime);
				}
				else
				{
					RandomSkill(StageOne_DisMoreThan6_Front, stageOneWaitTime, 1);
				}
			}
			else if (havePlayer() && fP2 < 150 && _runSkillCDEnd[5050154] < _actor.LogicTime)
			{
				CreateSkill(5050154, stageOneWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageOne();
				});
			}
		}

		protected void CheckStageTwo()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050154] < _actor.LogicTime)
					{
						CreateSkill(5050154, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisLessThan6_Front, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050163, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050154] < _actor.LogicTime)
				{
					CreateSkill(5050154, stageTwoWaitTime);
				}
				else if (checkSkill(5050153, _actor.LogicTime))
				{
					CreateSkill(5050153, stageTwoWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageTwo();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (_actor.buffComponent.CheckBuffByBuffID(ViolentBuffId))
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050154] < _actor.LogicTime)
					{
						CreateSkill(5050154, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisMoreThan6_Front_Violent, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050163, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050154] < _actor.LogicTime)
				{
					CreateSkill(5050154, stageTwoWaitTime);
				}
				else
				{
					RandomSkill(StageTwo_DisMoreThan6_Front_ViolentNone, stageTwoWaitTime, 2);
				}
			}
			else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050154] < _actor.LogicTime)
			{
				CreateSkill(5050154, stageTwoWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageTwo();
				});
			}
		}

		protected void CreateSkill(int skillId, FP waitTime)
		{
			if (_actor.actorHealthInfo.isAlive)
			{
				StopCoroutine(ref _waitCreateSkill);
				StartCoroutine(ref _waitCreateSkill, waitTimeRunSkill(skillId, waitTime));
			}
		}

		protected IEnumerator waitTimeRunSkill(int skillId, FP waitTime)
		{
			tempSkillId = skillId;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitTime));
			if (skillId != 5050154)
			{
				LogicEntity target = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
				if (_traceTarget == null)
				{
					_traceTarget = new TraceTarget();
				}
				_traceTarget.BeginTrace(_actor, target, skillInfo[skillId][2], -1, skillInfo[skillId][3], delegate
				{
					TSVector2 a = target.tsTransform.Position - _actor.tsTransform.Position;
					TSVector2 forward = _actor.tsTransform.Forward;
					if (TSVector2.Angle(a, forward) > skillInfo[skillId][4] && skillId != 5050153)
					{
						_lookAtTarget?.StopLookAt();
						if (_lookAtTarget == null)
						{
							_lookAtTarget = new LookAtTarget();
						}
						_lookAtTarget.BeginLookAt(_actor, target, 0, 0, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
								ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
							}
						});
					}
					else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
					{
						_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
						ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
					}
				}, OnTraceCancel);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
				ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnTraceCancel(bool targetDied, bool isInterrupt)
		{
			bool logicTagToggle = _logicVariable.GetLogicTagToggle("5050100ShaShaSpecial");
			if (_actor.actorHealthInfo.isAlive && !logicTagToggle && tempSkillId != 0)
			{
				_runSkillCDEnd[tempSkillId] = _actor.LogicTime + skillInfo[tempSkillId][0];
				ILRuntimeAPI.CreateSkill(tempSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnFinishCallback(bool success)
		{
			tempSkillId = 0;
			if (_waitShadow)
			{
				_waitShadow = false;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050159, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				stageRandomSkill();
			}
		}

		protected void stageRandomSkill()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaChangeStage"))
			{
				_currentStage = 2;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050159, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaChangeStage", value: false);
			}
			else if (tmpRunSpecialGroup)
			{
				CreateSkill(tmpSpecialGroup[tmpSpecialIndex], tmpWaitTime);
				tmpSpecialIndex++;
				if (tmpSpecialIndex == tmpSpecialGroup.Count)
				{
					tmpRunSpecialGroup = false;
				}
			}
			else if (_currentStage == 1)
			{
				CheckStageOne();
			}
			else if (!isSpecialSkillListEnd)
			{
				CreateSkill(specialSkillList[runSpecialSkillListCount], 0);
				runSpecialSkillListCount++;
				if (runSpecialSkillListCount == specialSkillList.Count)
				{
					isSpecialSkillListEnd = true;
				}
			}
			else
			{
				CheckStageTwo();
			}
		}
	}
	public class Action_Lv2 : MonsterActionBase
	{
		private static readonly int Dash = 5050151;

		private static readonly int Sweep = 5050152;

		private static readonly int ChargeFlick = 5050153;

		private static readonly int JumpFlick = 5050184;

		private static readonly int Crush = 5050154;

		private static readonly int CrargeBreath = 5050155;

		private static readonly int WaterSpit = 5050156;

		private static readonly int WaterSpit3 = 5050166;

		private static readonly int ShadowBall = 5050157;

		private static readonly int ShadowGathering = 5050158;

		private static readonly int TravelAround = 5050159;

		private static readonly int Whelmed = 5050160;

		private static readonly int Jump = 5050114;

		private static readonly int Wander = 5050199;

		private static readonly FP HpPercentStage2 = 0.7;

		private static readonly FP FarSkillOutRadius = 12;

		private static readonly FP FarSkillinnerRadius = 7.5;

		private static readonly FP NearSkillOutRadius = 5;

		private static readonly FP fanAngle = 90;

		private static readonly int testSkillId = 0;

		private static readonly int intervaltime = 0;

		private int SmallNearSkillCount;

		private int TmpSkillID;

		private bool IsPhase2;

		private bool IsPhase3;

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = SkillGroup01;
			list.Add(new BaseBranchInfo(1001, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = SkillGroup02;
			list.Add(new BaseBranchInfo(1002, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = DashSkillCast;
			list.Add(new BaseBranchInfo(1003, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = StressSkillCast;
			list.Add(new BaseBranchInfo(1004, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = UltraSkillCast;
			list.Add(new BaseBranchInfo(1005, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = FarSkillCast;
			list.Add(new BaseBranchInfo(1006, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = ShadowSkillCast;
			list.Add(new BaseBranchInfo(1007, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = JumpFlickCast;
			list.Add(new BaseBranchInfo(1008, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = WanderCast;
			list.Add(new BaseBranchInfo(9999, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> sequenceDict = new Dictionary<int, List<int>>
			{
				[1] = new List<int>
				{
					1004, 1003, 9999, 1002, 1001, 1003, 1002, 9999, 1008, 1001,
					1002, 1001, 9999, 1002
				},
				[2] = new List<int>
				{
					1005, 1007, 1006, 1006, 9999, 1001, 1002, 1003, 1001, 1006,
					9999, 1008, 1003, 1006, 1002, 9999, 1001
				}
			};
			InitSequenceBranches(1, sequenceBranches, sequenceDict);
		}

		protected override void SetListenEvents()
		{
			InitListenEvent(MonsterEventType.SelfHpChanged, active: true, PhaseChange);
			InitListenEvent(MonsterEventType.SelfToughnessBroken, active: true, OnToughnessState);
		}

		private void GotoCastSkill(int ID)
		{
			if (testSkillId != 0)
			{
				ID = testSkillId;
			}
			TmpSkillID = ID;
			CastSkill(ID);
		}

		private bool SmallSkillWithLongDistance()
		{
			TSVector2 position = GetPosition();
			FP farSkillOutRadius = FarSkillOutRadius;
			FP farSkillinnerRadius = FarSkillinnerRadius;
			FP angle = fanAngle;
			FP rotation = GetRotation();
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), farSkillOutRadius, farSkillinnerRadius, angle, rotation);
			return IsAttackTargetInArea(shapeData);
		}

		private IEnumerator SkillGroup01()
		{
			FP fP = CalcAngleBetweenSelfAndAttackTarget();
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) <= 6.5f)
			{
				if (fP <= 60)
				{
					GotoCastSkill(Sweep);
				}
				else if (fP >= 120)
				{
					GotoCastSkill(ChargeFlick);
				}
				else if (fP <= 120 && fP >= 60)
				{
					GotoCastSkill(Crush);
