		public void OnEnable()
		{
			isToughnessWhelmed = false;
			toughnessCount = 0;
			_currentStage = 1;
			_waitShadow = false;
			ShowBlood(isShow: true);
			InitSkill();
			if (_lookAtTarget == null)
			{
				_lookAtTarget = new LookAtTarget();
			}
			_actor.logicVariable.SetLogicTagValue("ViolentBuffId", ViolentBuffId);
			_actor.logicVariable.SetLogicTagValue("SkillId_whelmed", 5050180);
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			_actor.EnableImmuneControl();
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (monsterAdventureActor != null)
			{
				monsterAdventureActor.monsterToughnessInfo.isUseDefaultBrokenState = false;
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
		}

		protected void ShowBlood(bool isShow)
		{
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			if (!(monsterAdventureActor == null))
			{
				monsterAdventureActor.ShowBlood(isShow);
			}
		}

		public void OnStart()
		{
			_logicVariable = ActorHelper.GetFlowLogicVariable(_actor.gameObject);
			stageRandomSkill();
			_actor.StopImmuneControlCueEffect();
		}

		protected void InitSkill()
		{
			foreach (int key in skillInfo.Keys)
			{
				_runSkillCDEnd[key] = 0;
			}
		}

		public void OnStop()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
		}

		public void OnUpdate()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaViolent_Start"))
			{
				_receiveDamage = 0;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent_Start", value: false);
			}
			if (_logicVariable.GetLogicTagToggle("5050100EndWhelmed"))
			{
				_actor.logicVariable.ToggleLogicTag("5050100EndWhelmed", value: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: false);
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: true);
			}
			if (_logicVariable.GetLogicTagToggle("CheckSkill_ShaSha"))
			{
				stageRandomSkill();
				_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			}
		}

		public void OnDisable()
		{
			if (_lookAtTarget != null)
			{
				_lookAtTarget.StopLookAt();
				_lookAtTarget.Clear();
			}
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
			StopCoroutine(ref _corCountDown);
			StopCoroutine(ref _waitCreateSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
			_actor.DisableSuperArmor();
		}

		protected void OnRemoveBuff(IEvent evt)
		{
			if (evt.sender as AdventureActor == _actor && (evt as AdventureActorRemoveBuff).eventInfo.buffId == ViolentBuffId)
			{
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				StopCoroutine(ref _corCountDown);
				StartCoroutine(ref _corCountDown, CorCountDown());
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.InterruptForceControl();
				toughnessCount++;
				StopCoroutine(ref _waitCreateSkill);
				_lookAtTarget?.StopLookAt();
				if (toughnessCount <= 2)
				{
					isToughnessWhelmed = true;
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050180, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				}
				if (_currentStage == 2)
				{
					_actor.actorSkillManage.DestoryAllSkill();
					_actor.InterruptAttack(force: true);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					_traceTarget?.Clear();
					tmpRunSpecialGroup = false;
					ILRuntimeAPI.CreateSkill(5050180, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: false);
				}
			}
		}

		protected IEnumerator CorCountDown()
		{
			_waitShadow = false;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(ViolentTime));
			_waitShadow = true;
		}

		protected bool checkSkill(int _skillid, FP _logicTime)
		{
			if (_skillid < 0)
			{
				return true;
			}
			if (_runSkillCDEnd[_skillid] < _logicTime && skillInfo[_skillid][1] < _logicTime)
			{
				return true;
			}
			return false;
		}

		protected bool havePlayer()
		{
			List<LogicEntity> list = CommonUtils.SearchNearTargetsByCircle(_actor, crushSearchRadius, isConfront: true, includeSelf: false);
			if (list != null && list.Count > 0)
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (TSVector2.Distance(_actor.tsTransform.Position, list[i].tsTransform.Position) > crushSearchInnerRadius)
					{
						return true;
					}
				}
			}
			return false;
		}

		protected FP RandomSkill(Dictionary<int, FP> dicGroup, FP waitTime, int _stage)
		{
			FP fP = 0;
			Dictionary<int, FP> dictionary = new Dictionary<int, FP>();
			FP logicTime = _actor.LogicTime;
			foreach (KeyValuePair<int, FP> item in dicGroup)
			{
				if (checkSkill(item.Key, logicTime))
				{
					fP += item.Value;
					dictionary[item.Key] = fP;
				}
			}
			if (fP > 0)
			{
				FP fP2 = TSRandom.Range(0, fP);
				foreach (KeyValuePair<int, FP> item2 in dictionary)
				{
					if (!(fP2 < item2.Value))
					{
						continue;
					}
					if (item2.Key >= 0)
					{
						CreateSkill(item2.Key, waitTime);
					}
					else if (item2.Key == -1)
					{
						LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
						if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
						{
							logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
						}
						_actor.MoveTo(logicEntity.tsTransform.Position, 5, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								if (_stage == 1)
								{
									CheckStageOne();
								}
								else
								{
									CheckStageTwo();
								}
							}
						});
					}
					else
					{
						tmpRunSpecialGroup = true;
						tmpSpecialGroup = dicSpecialSkillGroup[item2.Key];
						tmpSpecialIndex = 0;
						tmpWaitTime = 0;
						stageRandomSkill();
					}
					break;
				}
			}
			return fP;
		}

		protected void CheckStageOne()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050174] < _actor.LogicTime)
					{
						CreateSkill(5050174, stageOneWaitTime);
					}
					else if (RandomSkill(StageOne_DisLessThan6_Front, stageOneWaitTime, 1) == 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050183, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050174] < _actor.LogicTime)
				{
					CreateSkill(5050174, stageOneWaitTime);
				}
				else if (_runSkillCDEnd[5050173] < _actor.LogicTime)
				{
					CreateSkill(5050173, stageOneWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageOne();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050174] < _actor.LogicTime)
				{
					CreateSkill(5050174, stageOneWaitTime);
				}
				else
				{
					RandomSkill(StageOne_DisMoreThan6_Front, stageOneWaitTime, 1);
				}
			}
			else if (havePlayer() && fP2 < 150 && _runSkillCDEnd[5050174] < _actor.LogicTime)
			{
				CreateSkill(5050174, stageOneWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageOne();
				});
			}
		}

		protected void CheckStageTwo()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				logicEntity = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			}
			FP fP = _actor.DistanceWithRadius(logicEntity);
			TSVector2 forward = _actor.tsTransform.Forward;
			TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
			FP fP2 = TSVector2.Angle(forward, b);
			if (fP < 5)
			{
				if (fP2 <= 90)
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050174] < _actor.LogicTime)
					{
						CreateSkill(5050174, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisLessThan6_Front, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050183, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050174] < _actor.LogicTime)
				{
					CreateSkill(5050174, stageTwoWaitTime);
				}
				else if (checkSkill(5050173, _actor.LogicTime))
				{
					CreateSkill(5050173, stageTwoWaitTime);
				}
				else
				{
					_lookAtTarget?.StopLookAt();
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
					{
						CheckStageTwo();
					});
				}
			}
			else if (fP2 <= 90)
			{
				if (_actor.buffComponent.CheckBuffByBuffID(ViolentBuffId))
				{
					if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050174] < _actor.LogicTime)
					{
						CreateSkill(5050174, stageTwoWaitTime);
					}
					else if (RandomSkill(StageTwo_DisMoreThan6_Front_Violent, stageTwoWaitTime, 2) <= 0)
					{
						_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
						_actor.actorSkillManage.DestoryAllSkill();
						ILRuntimeAPI.CreateSkill(5050183, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
					}
				}
				else if (havePlayer() && fP2 > 60 && _runSkillCDEnd[5050174] < _actor.LogicTime)
				{
					CreateSkill(5050174, stageTwoWaitTime);
				}
				else
				{
					RandomSkill(StageTwo_DisMoreThan6_Front_ViolentNone, stageTwoWaitTime, 2);
				}
			}
			else if (havePlayer() && fP2 < 120 && _runSkillCDEnd[5050174] < _actor.LogicTime)
			{
				CreateSkill(5050174, stageTwoWaitTime);
			}
			else
			{
				_lookAtTarget?.StopLookAt();
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 1, 150, delegate
				{
					CheckStageTwo();
				});
			}
		}

		protected void CreateSkill(int skillId, FP waitTime)
		{
			if (_actor.actorHealthInfo.isAlive)
			{
				StopCoroutine(ref _waitCreateSkill);
				StartCoroutine(ref _waitCreateSkill, waitTimeRunSkill(skillId, waitTime));
			}
		}

		protected IEnumerator waitTimeRunSkill(int skillId, FP waitTime)
		{
			tempSkillId = skillId;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitTime));
			if (skillId != 5050174)
			{
				LogicEntity target = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
				if (_traceTarget == null)
				{
					_traceTarget = new TraceTarget();
				}
				_traceTarget.BeginTrace(_actor, target, skillInfo[skillId][2], -1, skillInfo[skillId][3], delegate
				{
					TSVector2 a = target.tsTransform.Position - _actor.tsTransform.Position;
					TSVector2 forward = _actor.tsTransform.Forward;
					if (TSVector2.Angle(a, forward) > skillInfo[skillId][4] && skillId != 5050173)
					{
						_lookAtTarget?.StopLookAt();
						if (_lookAtTarget == null)
						{
							_lookAtTarget = new LookAtTarget();
						}
						_lookAtTarget.BeginLookAt(_actor, target, 0, 0, delegate
						{
							if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
							{
								_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
								ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
							}
						});
					}
					else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
					{
						_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
						ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
					}
				}, OnTraceCancel);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				_runSkillCDEnd[skillId] = _actor.LogicTime + skillInfo[skillId][0];
				ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnTraceCancel(bool targetDied, bool isInterrupt)
		{
			bool logicTagToggle = _logicVariable.GetLogicTagToggle("5050100ShaShaSpecial");
			if (_actor.actorHealthInfo.isAlive && !logicTagToggle && tempSkillId != 0)
			{
				_runSkillCDEnd[tempSkillId] = _actor.LogicTime + skillInfo[tempSkillId][0];
				ILRuntimeAPI.CreateSkill(tempSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnFinishCallback);
			}
		}

		protected void OnFinishCallback(bool success)
		{
			tempSkillId = 0;
			if (_waitShadow)
			{
				_waitShadow = false;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050179, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false);
			}
			else if (!_logicVariable.GetLogicTagToggle("5050100ShaShaSpecial"))
			{
				stageRandomSkill();
			}
		}

		protected void stageRandomSkill()
		{
			if (_logicVariable.GetLogicTagToggle("5050100ShaShaChangeStage"))
			{
				_currentStage = 2;
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
				_actor.actorSkillManage.DestoryAllSkill();
				tmpRunSpecialGroup = false;
				ILRuntimeAPI.CreateSkill(5050179, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaChangeStage", value: false);
			}
			else if (tmpRunSpecialGroup)
			{
				CreateSkill(tmpSpecialGroup[tmpSpecialIndex], tmpWaitTime);
				tmpSpecialIndex++;
				if (tmpSpecialIndex == tmpSpecialGroup.Count)
				{
					tmpRunSpecialGroup = false;
				}
			}
			else if (_currentStage == 1)
			{
				CheckStageOne();
			}
			else if (!isSpecialSkillListEnd)
			{
				CreateSkill(specialSkillList[runSpecialSkillListCount], 0);
				runSpecialSkillListCount++;
				if (runSpecialSkillListCount == specialSkillList.Count)
				{
					isSpecialSkillListEnd = true;
				}
			}
			else
			{
				CheckStageTwo();
			}
		}
	}
	public class Action_Lv3 : MonsterActionBase
	{
		private static readonly int Dash = 5050171;

		private static readonly int Sweep = 5050172;

		private static readonly int ChargeFlick = 5050173;

		private static readonly int JumpFlick = 5050184;

		private static readonly int Crush = 5050174;

		private static readonly int CrargeBreath = 5050175;

		private static readonly int WaterSpit = 5050176;

		private static readonly int WaterSpit3 = 5050186;

		private static readonly int ShadowBall = 5050177;

		private static readonly int ShadowGathering = 5050178;

		private static readonly int TravelAround = 5050179;

		private static readonly int Whelmed = 5050180;

		private static readonly int Jump = 5050114;

		private static readonly int Wander = 5050199;

		private static readonly FP HpPercentStage2 = 0.7;

		private static readonly FP FarSkillOutRadius = 12;

		private static readonly FP FarSkillinnerRadius = 7.5;

		private static readonly FP NearSkillOutRadius = 5;

		private static readonly FP fanAngle = 90;

		private static readonly int testSkillId = 0;

		private static readonly int intervaltime = 0;

		private int SmallNearSkillCount;

		private int TmpSkillID;

		private bool IsPhase2;

		private bool IsPhase3;

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = SkillGroup01;
			list.Add(new BaseBranchInfo(1001, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = SkillGroup02;
			list.Add(new BaseBranchInfo(1002, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = DashSkillCast;
			list.Add(new BaseBranchInfo(1003, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = StressSkillCast;
			list.Add(new BaseBranchInfo(1004, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = UltraSkillCast;
			list.Add(new BaseBranchInfo(1005, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = FarSkillCast;
			list.Add(new BaseBranchInfo(1006, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = ShadowSkillCast;
			list.Add(new BaseBranchInfo(1007, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = JumpFlickCast;
			list.Add(new BaseBranchInfo(1008, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = WanderCast;
			list.Add(new BaseBranchInfo(9999, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> sequenceDict = new Dictionary<int, List<int>>
			{
				[1] = new List<int>
				{
					1004, 1003, 9999, 1002, 1001, 1003, 1002, 9999, 1008, 1001,
					1002, 1001, 9999, 1002
				},
				[2] = new List<int>
				{
					1005, 1007, 1006, 1006, 9999, 1001, 1002, 1003, 1001, 1006,
					9999, 1008, 1003, 1006, 1002, 9999, 1001
				}
			};
			InitSequenceBranches(1, sequenceBranches, sequenceDict);
		}

		protected override void SetListenEvents()
		{
			InitListenEvent(MonsterEventType.SelfHpChanged, active: true, PhaseChange);
			InitListenEvent(MonsterEventType.SelfToughnessBroken, active: true, OnToughnessState);
		}

		private void GotoCastSkill(int ID)
		{
			if (testSkillId != 0)
			{
				ID = testSkillId;
			}
			TmpSkillID = ID;
			CastSkill(ID);
		}

		private bool SmallSkillWithLongDistance()
		{
			TSVector2 position = GetPosition();
			FP farSkillOutRadius = FarSkillOutRadius;
			FP farSkillinnerRadius = FarSkillinnerRadius;
			FP angle = fanAngle;
			FP rotation = GetRotation();
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), farSkillOutRadius, farSkillinnerRadius, angle, rotation);
			return IsAttackTargetInArea(shapeData);
		}

		private IEnumerator SkillGroup01()
		{
			FP fP = CalcAngleBetweenSelfAndAttackTarget();
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) <= 6.5f)
			{
				if (fP <= 60)
				{
					GotoCastSkill(Sweep);
				}
				else if (fP >= 120)
				{
					GotoCastSkill(ChargeFlick);
				}
				else if (fP <= 120 && fP >= 60)
				{
					GotoCastSkill(Crush);
				}
			}
			else
			{
				GotoCastSkill(CrargeBreath);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator SkillGroup02()
		{
			FP distanceWithTarget = GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true);
			if (distanceWithTarget <= 8 && distanceWithTarget > 6)
			{
				GotoCastSkill(Dash);
			}
			else if (distanceWithTarget > 8)
			{
				if (_actor.buffComponent.CheckBuffByBuffID(505010110))
				{
					GotoCastSkill(WaterSpit3);
				}
				else
				{
					GotoCastSkill(WaterSpit);
				}
			}
			else
			{
				GotoCastSkill(ChargeFlick);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator DashSkillCast()
		{
			GotoCastSkill(Dash);
			yield return WaitSkillFinish();
		}

		private IEnumerator StressSkillCast()
		{
			GotoCastSkill(CrargeBreath);
			yield return WaitSkillFinish();
		}

		private IEnumerator UltraSkillCast()
		{
			if (!_actor.buffComponent.CheckBuffByBuffID(505010110))
			{
				GotoCastSkill(TravelAround);
				yield return WaitSkillFinish();
			}
		}

		private IEnumerator FarSkillCast()
		{
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) > 8)
			{
				if (GetRandomValue(1, 3, isInt: true) == 1)
				{
					GotoCastSkill(WaterSpit3);
				}
				else
				{
					GotoCastSkill(ShadowBall);
				}
			}
			else
			{
				GotoCastSkill(ShadowBall);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator ShadowSkillCast()
		{
			if (TmpSkillID != ShadowGathering)
			{
				GotoCastSkill(ShadowGathering);
				yield return WaitSkillFinish();
			}
		}

		private IEnumerator JumpFlickCast()
		{
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) <= 6)
			{
				GotoCastSkill(ChargeFlick);
			}
			else
			{
				GotoCastSkill(JumpFlick);
			}
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private IEnumerator WanderCast()
		{
			GotoCastSkill(Wander);
			yield return WaitSkillFinish();
			yield return WaitTime(intervaltime);
		}

		private void PhaseChange(IEvent evt)
		{
			if (_actor.actorHealthInfo.hpPercentage <= HpPercentStage2 && !IsPhase2)
			{
				_actor.actorSkillManage.DestoryAllSkill();
				_actor.InterruptAttack(force: true);
				base.OnHandleCustomSwitchState();
				SetLogicTagFpValue(_actor, "TaiDeng_Stage", 2);
				SwitchSequence(2);
				IsPhase2 = true;
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && monsterToughnessStateChangeEvent.isToughnessBroken)
			{
				_actor.InterruptForceControl();
				_actor.actorSkillManage.DestoryAllSkill();
				_actor.InterruptAttack(force: true);
				GotoCastSkill(Whelmed);
			}
		}
	}
	public class Parallel_3 : AIScript.Monster.Template.Parallel
	{
		protected FP hpPercentage_Stage = 0.7;

		protected bool isChangeSatge;

		private const GameEnum.questCompleteCondClient achievementType_1 = GameEnum.questCompleteCondClient.ShaSha_001;

		private static readonly int checkHitTag_1 = CommonHelper.StringToHash("ShaSha_Duyu");

		private const GameEnum.questCompleteCondClient achievementType_2 = GameEnum.questCompleteCondClient.ShaSha_002;

		private static readonly int checkBuffTag_2 = CommonHelper.StringToHash("SharkBuff");

		private const GameEnum.questCompleteCondClient achievementType_3 = GameEnum.questCompleteCondClient.ShaSha_003;

		private static readonly int checkBuffTag_3 = CommonHelper.StringToHash("SharkSlow");

		private static readonly FP checkBuffTime_3 = 10;

		private bool _achievementTypeFinish_1;

		private bool _canFinishAchievementType_1;

		private bool _achievementTypeFinish_2;

		private bool _achievementTypeFinish_3;

		private bool _haveBuff_3;

		private FP _haveBuffTime_3;

		public override void OnStart()
		{
			base.OnStart();
			isChangeSatge = false;
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_HP_CHANGED", OnHpChange);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessStateChange);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
		}

		protected override void OnInitState()
		{
			base.OnInitState();
			EnterState(1);
		}

		private void OnHpChange(IEvent iEvt)
		{
			if (iEvt is AdventureActorHpChangedEvent adventureActorHpChangedEvent && (adventureActorHpChangedEvent.sender as AdventureActor).Id == _actor.Id && _actor.actorHealthInfo.hpPercentage <= hpPercentage_Stage && !isChangeSatge)
			{
				isChangeSatge = true;
				SwitchState(breakCurrentAction: false, breakForceControl: false, 1, 2);
			}
		}

		protected override void OnSwitchState()
		{
			base.OnSwitchState();
			if (MonsterInState(2))
			{
				_actor.logicVariable.ToggleLogicTag("5050100ShaShaChangeStage", value: true);
				AdventureMonsterSwitchCustomStateEvent adventureMonsterSwitchCustomStateEvent = AdventureMonsterSwitchCustomStateEvent.Generate();
				adventureMonsterSwitchCustomStateEvent.commonHandle = false;
				adventureMonsterSwitchCustomStateEvent.breakCurrentAction = false;
				adventureMonsterSwitchCustomStateEvent.customHandle = true;
				_actor.DispatchEvent(adventureMonsterSwitchCustomStateEvent);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			if (!_achievementTypeFinish_1 && _canFinishAchievementType_1)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.ShaSha_001);
			}
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_HP_CHANGED", OnHpChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessStateChange);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShaSha_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShaSha_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShaSha_003);
			_canFinishAchievementType_1 = true;
			_haveBuff_3 = false;
			_haveBuffTime_3 = 0;
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is PlayerAdventureActor && !_achievementTypeFinish_1 && _canFinishAchievementType_1)
			{
				_canFinishAchievementType_1 = !CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, checkHitTag_1);
			}
		}

		private void OnToughnessStateChange(IEvent evt)
		{
			if (MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower)
			{
				MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
				if (monsterToughnessStateChangeEvent.actor == _actor && monsterToughnessStateChangeEvent.isToughnessBroken && !_achievementTypeFinish_2 && _actor.buffComponent.CheckBuffByBuffTag(checkBuffTag_2))
				{
					_achievementTypeFinish_2 = SetAchievementState(GameEnum.questCompleteCondClient.ShaSha_002);
				}
			}
		}

		private void OnGetBuff(IEvent evt)
		{
			AdventureActorGetBuff adventureActorGetBuff = evt as AdventureActorGetBuff;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (adventureActorGetBuff.sender is PlayerAdventureActor playerAdventureActor && playerAdventureActor == activedPlayerActor && adventureActorGetBuff.from == _actor && !_achievementTypeFinish_3 && adventureActorGetBuff.eventInfo.buffTags.Contains(checkBuffTag_3))
			{
				_haveBuff_3 = true;
			}
		}

		public void OnUpdate()
		{
			if (!_achievementTypeFinish_3 && _haveBuff_3)
			{
				_haveBuffTime_3 += _actor.LogicDeltaTime;
				if (_haveBuffTime_3 >= checkBuffTime_3)
				{
					_achievementTypeFinish_3 = SetAchievementState(GameEnum.questCompleteCondClient.ShaSha_003);
				}
			}
		}

		private void OnRemoveBuff(IEvent evt)
		{
			AdventureActorRemoveBuff adventureActorRemoveBuff = evt as AdventureActorRemoveBuff;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (adventureActorRemoveBuff.sender is PlayerAdventureActor playerAdventureActor && playerAdventureActor == activedPlayerActor && !_achievementTypeFinish_3 && adventureActorRemoveBuff.eventInfo.buffTags.Contains(checkBuffTag_3))
			{
				_haveBuff_3 = false;
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			NovaLogger.Error("完成成就" + achievementType);
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}
	}
	public class SkillScript_Born_3 : SkillSimpleBase
	{
		protected readonly ComboInputBuffer.ActionKey[] _actionKey = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.V };

		protected readonly string eventJumpOut = "jumpOut";

		protected ComboAttack _comboAttack;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			_comboAttack?.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			while (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: true) >= 6)
			{
				yield return WaitTime(0.1);
			}
			yield return WaitTime(0.5);
			SummonTeammate(2, new TSVector2(-4, -1), TSVector2.down);
			SummonTeammate(2, new TSVector2(4, -1), TSVector2.down);
			ShowCenterHpBar();
			yield return WaitTime(1);
		}

		protected void PlayerCombo()
		{
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			ComboInputBuffer.ActionKey[] actionKey = _actionKey;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			Action<string> action = OnCustomEvent;
			System.Action action2 = OnFinish;
			System.Action action3 = OnInterrupt;
			obj.BeginAttack(actor, skill, actionKey, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, action2, action3, action);
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventJumpOut, eventName))
			{
				_actor.Visible();
			}
		}

		protected void OnFinish()
		{
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}
	}
