				new TSVector2(-7, -7),
				new TSVector2(-5, -2)
			},
			new List<TSVector2>
			{
				new TSVector2(5, -2),
				new TSVector2(5, -12),
				new TSVector2(-5, -12)
			},
			new List<TSVector2>
			{
				new TSVector2(0, -4),
				new TSVector2(0, -12)
			},
			new List<TSVector2>
			{
				new TSVector2(5, -7),
				new TSVector2(-5, -7),
				new TSVector2(4, -3)
			},
			new List<TSVector2>
			{
				new TSVector2(-4, -3),
				new TSVector2(-4, -11),
				new TSVector2(4, -11)
			},
			new List<TSVector2>
			{
				new TSVector2(-3, -5),
				new TSVector2(-3, -11),
				new TSVector2(3, -5),
				new TSVector2(3, -11),
				new TSVector2(0, -8)
			}
		};

		protected readonly string bulletPath = "Weapon_50501ShaSha_Water_Empty";

		protected FP fxInterval = 0.5;

		protected FP fxBulletInterval = 1.5;

		protected readonly string fxPath_1 = "SkyShoot_Warning";

		protected readonly string fxPath_2 = "SkyShoot_End";

		protected FP endWaitTime = 0.1;

		protected readonly string addBuffEvent = "AddBuff";

		protected readonly List<PlayFX> fxList_1 = new List<PlayFX>();

		protected readonly List<PlayFX> fxList_2 = new List<PlayFX>();

		protected readonly List<CoroutineNode> buttleCor = new List<CoroutineNode>();

		protected CoroutineNode _createButtle;

		protected CoroutineNode _waitEnd;

		public override void OnStart()
		{
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			BeginSkill();
		}

		protected override void BeginSkill()
		{
			base.BeginSkill();
			_comboAttack.BeginAttack(_actor, _skill, _actionKey, flushInputedKeys: true, (_skill != null) ? _skill.skillId : 0, forceInterruptAttack: false, autoLookAtTarget: false, null, null, onCustomEvent: OnCustomEvent, onInterrupt: OnInterrupt, aimTargetPosition: default(TSVector2), onAnticipationEnd: null, onRecoveryBegin: null, onComboLoop: null, onComboFinish: delegate
			{
				StopCoroutine(ref _waitEnd);
				StartCoroutine(ref _waitEnd, WaitEnd());
			});
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventBoom, eventName))
			{
				for (int i = 0; i < strAreaEffectByTag.Count; i++)
				{
					ILRuntimeAPI.StopAreaEffectByTag(strAreaEffectByTag[i]);
				}
			}
			else if (string.Equals(addBuffEvent, eventName))
			{
				_actor.buffComponent.AddBuff(_violentBuffId, _actor);
			}
		}

		protected IEnumerator CreateButtle()
		{
			for (int i = 0; i < buttleInterval.Count; i++)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(buttleInterval[i]));
				TSVector2 position = _actor.tsTransform.Position;
				List<TSVector2> list = new List<TSVector2>();
				for (int j = 0; j < fanOffsetList[i].Count; j++)
				{
					TSVector2 tSVector = position + fanOffsetList[i][j];
					if (_actor.QueryPositionReachable(tSVector))
					{
						list.Add(tSVector);
					}
				}
				WaitDrop(list);
			}
		}

		protected void WaitDrop(List<TSVector2> pos)
		{
			for (int i = 0; i < pos.Count; i++)
			{
				PlayFX playFX = new PlayFX();
				playFX.Play(_actor, _skill, fxPath_1, 0, pos[i], _actor.tsTransform.Forward);
				fxList_1.Add(playFX);
				CoroutineNode item = _actor.StartLogicCoroutine(WaitFxTwo(pos[i]));
				buttleCor.Add(item);
			}
		}

		protected IEnumerator WaitFxTwo(TSVector2 pos)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(fxInterval));
			PlayFX playFX = new PlayFX();
			playFX.Play(_actor, _skill, fxPath_2, 0, pos, _actor.tsTransform.Forward);
			fxList_2.Add(playFX);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(fxBulletInterval));
			ILRuntimeAPI.Shoot(bulletPath, _actor, 0, pos, default(FP), default(TSVector2), null, AimType.Default, BulletDirectionType.BulletToTarget);
		}

		protected void OnFinish()
		{
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: true);
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected IEnumerator WaitEnd()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(endWaitTime));
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: false);
			_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent", value: true);
			_actor.logicVariable.ToggleLogicTag("5050100ShaShaViolent_Start", value: true);
			StopCoroutine(ref _createButtle);
			StopCoroutine(ref _waitEnd);
			for (int i = 0; i < buttleCor.Count; i++)
			{
				_actor.StopLogicCoroutine(buttleCor[i]);
			}
			buttleCor.Clear();
			for (int j = 0; j < fxList_1.Count; j++)
			{
				fxList_1[j].Clear();
			}
			fxList_1.Clear();
			for (int k = 0; k < fxList_2.Count; k++)
			{
				fxList_2[k].Clear();
			}
			fxList_2.Clear();
		}
	}
	public class SkillScript_SkillBase : SkillAdvancedBase
	{
		protected int _skillId_whelmed;

		protected int _violentBuffId;

		protected FP _rotateSpeed;

		protected LookAtTarget _lookAtTarget;

		protected ComboAttack _comboAttack;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			if (_lookAtTarget == null)
			{
				_lookAtTarget = new LookAtTarget();
			}
			_skillId_whelmed = (int)(long)_actor.logicVariable.GetLogicTagValue("SkillId_whelmed");
			_violentBuffId = (int)(long)_actor.logicVariable.GetLogicTagValue("ViolentBuffId");
		}

		public virtual void OnStart()
		{
			BeginLookAt();
		}

		public void BeginLookAt()
		{
			FP zero = FP.Zero;
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				TSVector2 forward = _actor.tsTransform.Forward;
				TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
				zero = TSVector2.Angle(forward, b);
				FP rotateSpeed = _rotateSpeed;
				FP fP = 0;
				bool flag;
				if (rotateSpeed > 0)
				{
					fP = zero / rotateSpeed;
					flag = !(fP < 0.2);
				}
				else
				{
					flag = false;
				}
				if (flag)
				{
					_lookAtTarget.BeginLookAt(_actor, logicEntity, fP, rotateSpeed, delegate
					{
						BeginSkill();
					});
				}
				else
				{
					BeginSkill();
				}
			}
			else
			{
				_skill?.Clear();
			}
		}

		protected virtual void BeginSkill()
		{
			_comboAttack.InterruptAttack();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_lookAtTarget?.StopLookAt();
			_lookAtTarget?.Clear();
			_comboAttack?.Clear();
		}
	}
