		public override void OnStart()
		{
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: false);
			BeginSkill();
			CommonUtils_MonsterAPI.SetBlockPriorityToStatic(_actor);
			StartCoroutine(camera());
			CommonUtils_MonsterAPI.AddBuffToTarget(_actor, 990020140, _actor);
		}

		protected override void BeginSkill()
		{
			moveToPoint();
		}

		protected IEnumerator camera()
		{
			ModuleController<AdventureModuleController>.Instance.ActivePlayerCameraTrigger("Travel");
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(cameraWaitTime));
			ModuleController<AdventureModuleController>.Instance.DeactivePlayerCameraTrigger("Travel");
		}

		protected void moveToPoint()
		{
			for (int i = 0; i < buffIdList.Count; i++)
			{
				_actor.buffComponent.AddBuff(buffIdList[i], _actor);
			}
			_lookAtTarget.BeginLookAtByPos(_actor, movePoint, 0, 0, delegate
			{
				_actor.MoveTo(movePoint, 0.1, enableNavigation: true, AdventureActor.MovementMode.Walk, delegate
				{
					_actor.LookAt(LookAtJumpTarget, 0.1, delegate
					{
						playJunpInto();
					});
				});
			});
		}

		protected void playJunpInto()
		{
			_comboAttack.BeginAttack(_actor, _skill, _actionKeyJumpInto, flushInputedKeys: true, (_skill != null) ? _skill.skillId : 0, forceInterruptAttack: false, autoLookAtTarget: false, null, null, onCustomEvent: OnCustomEvent, onInterrupt: OnInterrupt, aimTargetPosition: default(TSVector2), onAnticipationEnd: null, onRecoveryBegin: null, onComboLoop: null, onComboFinish: delegate
			{
			});
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventJumpInto, eventName))
			{
				_actor.Hide();
				new PlayMonsterTimeline().Play(_actor, delegate
				{
					_actor.LookAt(LookAtTarget, 0.1, delegate
					{
						playJunpOut();
					});
				});
				_actor.Teleport(telePoint);
				StopCoroutine(ref _waitDrop);
				StartCoroutine(ref _waitDrop, CreateButtle());
				StartCoroutine(CreateButtle2());
			}
			else if (string.Equals(eventJumpOut, eventName))
			{
				_actor.Visible();
			}
		}

		protected IEnumerator CreateButtle()
		{
			for (int i = 0; i < buttleInterval.Count; i++)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(buttleInterval[i]));
				TSVector2 zero = TSVector2.zero;
				List<TSVector2> list = new List<TSVector2>();
				for (int j = 0; j < fanOffsetList[i].Count; j++)
				{
					TSVector2 item = zero + fanOffsetList[i][j];
					list.Add(item);
				}
				WaitCreateDrop(list);
			}
		}

		protected IEnumerator CreateButtle2()
		{
			for (int i = 0; i < buttleInterval2.Count; i++)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(buttleInterval2[i]));
				TSVector2 tSVector = TSVector2.zero;
				LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
				if (CommonUtils.CheckTargetIsValid(logicEntity, 0L))
				{
					tSVector = logicEntity.tsTransform.Position;
				}
				List<TSVector2> list = new List<TSVector2>();
				for (int j = 0; j < fanOffsetList2[i].Count; j++)
				{
					TSVector2 item = tSVector + fanOffsetList2[i][j];
					list.Add(item);
				}
				WaitCreateDrop(list);
			}
		}

		protected void WaitCreateDrop(List<TSVector2> pos)
		{
			for (int i = 0; i < pos.Count; i++)
			{
				PlayFX playFX = new PlayFX();
				playFX.Play(_actor, _skill, fxPath_1, 0, pos[i], _actor.tsTransform.Forward);
				fxList_1.Add(playFX);
				CoroutineNode item = _actor.StartLogicCoroutine(WaitFxTwo(pos[i]));
				buttleCor.Add(item);
			}
		}

		protected IEnumerator WaitFxTwo(TSVector2 pos)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(fxInterval));
			PlayFX playFX = new PlayFX();
			playFX.Play(_actor, _skill, fxPath_2, 0, pos, _actor.tsTransform.Forward);
			fxList_2.Add(playFX);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(fxBulletInterval));
			ILRuntimeAPI.Shoot(bulletPath, _actor, 0, pos, default(FP), default(TSVector2), null, AimType.Default, BulletDirectionType.BulletToTarget);
		}

		protected void playJunpOut()
		{
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			ComboInputBuffer.ActionKey[] actionKeyJumpOut = _actionKeyJumpOut;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onInterrupt = OnInterrupt;
			System.Action onComboFinish = OnFinish;
			obj.BeginAttack(actor, skill, actionKeyJumpOut, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		protected void OnFinish()
		{
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			CommonUtils_MonsterAPI.ResetBlockPriority(_actor);
			CommonUtils_MonsterAPI.RemoveBuffFromTarget(_actor, 990020140);
			for (int i = 0; i < buffIdList.Count; i++)
			{
				_actor.buffComponent.RemoveBuffByBuffId(buffIdList[i]);
			}
			_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: false);
			_actor.logicVariable.ToggleLogicTag("CheckSkill_ShaSha", value: true);
			StopCoroutine(ref _waitDrop);
			for (int j = 0; j < buttleCor.Count; j++)
			{
				_actor.StopLogicCoroutine(buttleCor[j]);
			}
			buttleCor.Clear();
			for (int k = 0; k < buttleCorInterval.Count; k++)
			{
				_actor.StopLogicCoroutine(buttleCorInterval[k]);
			}
			buttleCorInterval.Clear();
			for (int l = 0; l < fxList_1.Count; l++)
			{
				fxList_1[l].Clear();
			}
			fxList_1.Clear();
			for (int m = 0; m < fxList_2.Count; m++)
			{
				fxList_2[m].Clear();
			}
			fxList_2.Clear();
		}
	}
	public class SkillScript_WaterSpit : SkillScript_SkillBase
	{
		protected readonly ComboInputBuffer.ActionKey[] _actionKey_Water = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.F };

		protected readonly ComboInputBuffer.ActionKey[] _actionKey_Dark = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.W };

		protected FP RotateSpeed = 150;

		protected readonly string eventStartTurn = "StartTurn";

		protected readonly string eventStopTurn = "StopTurn";

		protected FP ShootRotateSpeed = 100;

		protected readonly string eventShoot = "Shoot";

		protected readonly string bulletPath_Water = "Weapon_50501ShaSha_Water_Throw";

		protected readonly string bulletPath_Dark = "Weapon_50501ShaSha_Dark_Throw";

		protected FP bulletYPos = 4;

		protected TSVector2 bulletOffset = new TSVector2(0, 5);

		protected readonly int ReceiveDamageFEPre = 99;

		protected FP fanAngle = 160;

		protected FP innerRange = 6;

		protected FP fanRange = 24;

		protected TSVector2 NonePlayerOffset = new TSVector2(0, 8);

		protected FP waitCancelTime = 0.2;

		protected int _receiveDamage;

		protected ComboInputBuffer.ActionKey[] _actionKey;

		protected string _bulletPath;

		protected int _buttleCount;

		private readonly List<DeterministicCollider> _targets = new List<DeterministicCollider>();

		protected CoroutineNode _waitCancelAttack;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_buttleCount = 0;
			_receiveDamage = 0;
			_rotateSpeed = RotateSpeed;
			UpdateData();
		}

		protected void UpdateData()
		{
			if (_actor.buffComponent.CheckBuffByBuffID(_violentBuffId))
			{
				_actionKey = _actionKey_Dark;
				_bulletPath = bulletPath_Dark;
			}
			else
			{
				_actionKey = _actionKey_Water;
				_bulletPath = bulletPath_Water;
			}
		}

		public override void OnStart()
		{
			BeginSkill();
		}

		protected override void BeginSkill()
		{
			BeginLookAtPlayer();
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			ComboInputBuffer.ActionKey[] actionKey = _actionKey;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onInterrupt = OnInterrupt;
			System.Action onComboFinish = OnFinish;
			obj.BeginAttack(actor, skill, actionKey, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		protected void OnCustomEvent(string eventName)
		{
			if (!string.Equals(eventShoot, eventName))
			{
				return;
			}
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			_lookAtTarget?.StopLookAt();
			_rotateSpeed = ShootRotateSpeed;
			BeginLookAtPlayer();
			if (CheckPlay())
			{
				string bulletPath = _bulletPath;
				AdventureActor actor = _actor;
				FP range = 0;
				TSVector2 position = _actor.tsTransform.Position + TSVector2.Rotate(bulletOffset, _actor.tsTransform.Rotation);
				TSVector2 position2 = logicEntity.tsTransform.Position;
				LogicEntity target = logicEntity;
				ILRuntimeAPI.Shoot(bulletPath, actor, range, position, bulletYPos, position2, target, AimType.Target, BulletDirectionType.BulletToTarget);
				_buttleCount++;
				if (_buttleCount == 3)
				{
					_comboAttack?.CancelAttack();
				}
			}
			else
			{
				ILRuntimeAPI.Shoot(_bulletPath, _actor, 0, _actor.tsTransform.Position + TSVector2.Rotate(bulletOffset, _actor.tsTransform.Rotation), targetPosition: _actor.tsTransform.Position + TSVector2.Rotate(NonePlayerOffset, _actor.tsTransform.Rotation), positionY: bulletYPos, target: null, aimType: AimType.Position, bulletDirectionType: BulletDirectionType.BulletToTarget);
			}
		}

		protected IEnumerator WaitCancelAttack()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitCancelTime));
			_comboAttack?.CancelAttack();
		}

		private bool CheckPlay()
		{
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (!CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				return false;
			}
			_targets.Clear();
			DeterministicShape shape = new DeterministicShape
			{
				shapeType = DeterministicShape.ShapeType.Fan,
				angle = fanAngle,
				innerRadius = innerRange,
				rotation = _actor.tsTransform.Rotation,
				radius = fanRange,
				position = _actor.tsTransform.Position
			};
			SceneSingleton<DeterministicCollisionManager>.Instance.GetTargetByShape(_targets, shape, 256);
			if (_targets == null || _targets.Count == 0)
			{
				return false;
			}
			if (_targets.Count > 0)
			{
				bool flag = false;
				foreach (DeterministicCollider target in _targets)
				{
					if (target.GetComponent<AdventureActor>() == logicEntity)
					{
						flag = true;
					}
				}
				if (!flag)
				{
					return false;
				}
			}
			return true;
		}

		protected void OnFinish()
		{
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnReceiveDamage(IEvent evt)
		{
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.to != _actor))
			{
				if (adventureActorReceiveDamageEvent.elementType == GameEnum.elementType.FE)
				{
					_receiveDamage += adventureActorReceiveDamageEvent.value;
				}
				if (iFP.op_Implicit(_receiveDamage * 100 / _actor.actorHealthInfo.hpMax) > ReceiveDamageFEPre)
				{
					_comboAttack.InterruptAttack();
					_actor.logicVariable.ToggleLogicTag("5050100ShaShaSpecial", value: true);
					ILRuntimeAPI.CreateSkill(_skillId_whelmed, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
					OnFinish();
				}
			}
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			StopCoroutine(ref _waitCancelAttack);
		}

		public void BeginLookAtPlayer()
		{
			FP fP = FP.Zero;
			LogicEntity logicEntity = _actor.actorSearchTargetInfo?.GetMonsterAttackTarget();
			if (CommonUtils.CheckTargetIsValid(logicEntity, 0L))
			{
				TSVector2 forward = _actor.tsTransform.Forward;
				TSVector2 b = logicEntity.tsTransform.Position - _actor.tsTransform.Position;
				fP = TSVector2.Angle(forward, b);
			}
			FP duration = fP / _rotateSpeed;
			_lookAtTarget.BeginLookAt(_actor, logicEntity, duration, _rotateSpeed, delegate
			{
			});
		}
	}
