			FP initCd6 = 40;
			operateIEnumerator = WindCondition;
			list2.Add(new PoolBranchInfo(actor6, id6, 6, cd6, initCd6, active: true, default(FP), default(FP), default(FP), null, null, operateIEnumerator));
			obj.braches = list2;
			list.Add(obj);
			List<PoolBranchesInfo> poolBranches = list;
			InitPoolBranches(1, poolBranches);
		}

		private IEnumerator OneShootCondition()
		{
			CastSkill(Skill_OneShoot);
			yield return WaitSkillFinish();
		}

		private IEnumerator SplitBulletCondition()
		{
			CastSkill(Skill_SplitBullet);
			yield return WaitSkillFinish();
			CastSkill(Skill_Run);
			yield return WaitSkillFinish();
		}

		private IEnumerator DartleCondition()
		{
			CastSkill(Skill_Dartle);
			yield return WaitSkillFinish();
			CastSkill(Skill_Run);
			yield return WaitSkillFinish();
		}

		private IEnumerator TurnShootCondition()
		{
			CastSkill(Skill_TurnShoot);
			yield break;
		}

		private IEnumerator CircularAttackCondition()
		{
			CastSkill(Skill_CircularAttack);
			yield return WaitSkillFinish();
		}

		private IEnumerator BranchSkillCondition()
		{
			FP fP = Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer()));
			if (!branchSwitch)
			{
				if (fP > 5)
				{
					CastSkill(Skill_TurnShoot);
				}
				else
				{
					CastSkill(Skill_CircularAttack);
				}
			}
			else if (fP > 5)
			{
				CastSkill(Skill_CircularAttack);
			}
			else
			{
				CastSkill(Skill_TurnShoot);
			}
			yield return WaitSkillFinish();
			branchSwitch = !branchSwitch;
		}

		private IEnumerator WindCondition()
		{
			CastSkill(Skill_Wind);
			yield return WaitSkillFinish();
		}

		private IEnumerator RunCondition()
		{
			CastSkill(Skill_Run);
			yield return WaitSkillFinish();
		}
	}
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private string fbx = "fx_m50271_loop_pointer_fixed";

		private string evt_play = "PlayHintFx";

		private string evt_stop = "StopHintFx";

		private PlayFX playFx = new PlayFX();

		public override void OnStart()
		{
			base.OnStart();
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			playFx.Stop();
		}

		private void OnCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent)
			{
				if (adventureActorCustomEvent.eventName.Equals(evt_play))
				{
					playFx.Play(_actor, fbx, 1f, _actor.transform.position, _actor.transform.rotation);
				}
				else if (adventureActorCustomEvent.eventName.Equals(evt_stop))
				{
					playFx.Stop();
				}
			}
		}
	}
	public class Skill_CircularAttack : SkillSimpleBase
	{
		private CoroutineNode hitCor;

		private readonly int Circular_StartIndex;

		private readonly string Circular_StartKey = "Circular_Start";

		private readonly int Circular_InhaleIndex = 1;

		private readonly string Circular_InhaleKey = "Circular_Inhale";

		private readonly int Circular_SwitchIndex = 2;

		private readonly string Circular_SwitchKey = "Circular_Switch";

		private readonly int CircularAttackIndex = 3;

		private readonly string CircularAttackKey = "CircularAttack";

		private List<long> fxList;

		protected override void OnSkillEnable()
		{
			fxList = new List<long>();
		}

		protected override void OnSkillDisable()
		{
			if (fxList != null && fxList.Count > 0)
			{
				for (int i = 0; i < fxList.Count; i++)
				{
					StopEffect(fxList[i]);
				}
			}
			fxList.Clear();
			fxList = null;
			StopCor(hitCor);
			StopLookAt();
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(Circular_StartIndex, Circular_StartKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.17);
			fxList.Add(PlayEffect("fx_common_base_Dark_YuJing_circular_4", 0.7f, default(FP), GetPosition(), default(FP), 1.5f));
			BeginAttack(Circular_InhaleIndex, Circular_InhaleKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.22);
			BeginAttack(Circular_SwitchIndex, Circular_SwitchKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.35);
			PlayEffect("fx_common_base_charge_fire_actor", 1f, 2, GetPosition(), default(FP), 2.5f);
			yield return WaitTime(0.1);
			BeginLookAt_NotWait(GetCurrentPlayer(), 2, 120);
			BeginAttack(CircularAttackIndex, CircularAttackKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.2);
			TSVector2 position = GetPosition();
			fxList.Add(PlayEffect("fx_50271_loop_atk_B_Skill03_aoe", 1f, default(FP), position, default(FP), 1.5f));
			hitCor = StartCor(HitDamage(4, position));
			yield return WaitCombo(ComboAttackType.isComboFinish);
			if (fxList != null && fxList.Count > 0)
			{
				for (int i = 0; i < fxList.Count; i++)
				{
					StopEffect(fxList[i]);
				}
			}
			StopCor(hitCor);
		}

		protected IEnumerator HitDamage(int cycleIndex, TSVector2 pos)
		{
			for (int i = 0; i < cycleIndex; i++)
			{
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, pos, default(FP), default(FP), 6);
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50271015, 0.5, HitBox.HurtAnimType.Small, "fx_50271_hit_skill01");
				yield return WaitTime(0.2);
			}
		}
	}
	public class Skill_Dartle : SkillSimpleBase
	{
		private LogicEntity target;

		private readonly int SB_StartIndex;

		private readonly string SB_StartKey = "SplitBullet_Start";

		private readonly int SB_InhaleIndex = 1;

		private readonly string SB_InhaleKey = "SplitBullet_Inale";

		private readonly int SB_AttackIndex = 2;

		private readonly string SB_AttackKey = "SplitBullet_Attack";

		private readonly int DartleStartIndex = 3;

		private readonly string DartleStartKey = "Dartle_Start";

		private readonly int DartleAttackIndex = 4;

		private readonly string DartleAttackKey = "Dartle_Attack";

		private string bullet = "FengMeiGuai_skill02_Dartlebullet";

		private bool turnSwitch;

		private FP turnOffset;

		private CoroutineNode shootCor;

		protected override void OnSkillEnable()
		{
			turnSwitch = false;
			turnOffset = 0;
		}

		protected override void OnSkillDisable()
		{
			StopLookAt();
		}

		protected override IEnumerator DoMainLogic()
		{
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				target = GetAttackTarget();
			}
			else
			{
				target = GetCurrentPlayer();
			}
			BeginAttack(DartleStartIndex, DartleStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.1);
			BeginAttack(SB_StartIndex, SB_StartKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.4);
			BeginAttack(SB_InhaleIndex, SB_InhaleKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 99, 80);
			yield return WaitTime(1);
			BeginAttack(SB_AttackIndex, SB_AttackKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(0.67);
			PlayEffect("fx_common_base_charge_fire_actor", 1f, 2, GetPosition(), default(FP), 2.5f);
			yield return WaitTime(0.3);
			BeginAttack(DartleAttackIndex, DartleAttackKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(2.5);
			CancelAttack();
			StopCor(shootCor);
			StopLookAt();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == DartleAttackIndex && eventName == "beginShoot")
			{
				shootCor = StartCor(DartleShoot());
			}
		}

		protected IEnumerator DartleShoot()
		{
			for (int i = 0; i < 99; i++)
			{
				TSVector2 multiShootDirection = RotateTo(GetForward(), UpdateAngle());
				FanMultipleShoot(bullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 1, 0, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 0.2)), 0.5, multiShootDirection, 0, AimType.Default, BulletDirectionType.ActorToBullet, 5, 0, 3);
				yield return WaitTime(0.1);
			}
		}

		private FP UpdateAngle()
		{
			if (AngleBetween2TSVector(GetForward(), RotateTo(GetForward(), turnOffset), signed: false) > 25)
			{
				turnSwitch = !turnSwitch;
			}
			if (turnSwitch)
			{
				turnOffset -= (FP)4;
			}
			else
			{
				turnOffset += (FP)4;
			}
			return turnOffset;
		}
	}
