	public class Skill_TurnShoot : SkillSimpleBase
	{
		private readonly int TS_StartIndex;

		private readonly string TS_StartKey = "TurnShoot_Start";

		private readonly int TS_InhaleIndex = 1;

		private readonly string TS_InhaleKey = "TurnShoot_Inhale";

		private readonly int TS_SwitchIndex = 2;

		private readonly string TS_SwitchKey = "TurnShoot_Switch";

		private readonly int TS_AttackIndex = 3;

		private readonly string TS_AttackKey = "TurnShoot_Attack";

		private int TS_AttackLoopCount;

		private bool ChargeFxSwitch;

		private string bullet = "FengMeiGuai_skill03_bullet";

		private CoroutineNode shootCor;

		protected override void OnSkillEnable()
		{
			TS_AttackLoopCount = 0;
			ChargeFxSwitch = false;
		}

		protected override void OnSkillDisable()
		{
			StopLookAt();
			StopCor(shootCor);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginLookAt_NotWait(GetCurrentPlayer(), 0.8, 225, 30);
			BeginAttack(TS_StartIndex, TS_StartKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.17);
			BeginAttack(TS_InhaleIndex, TS_InhaleKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.2);
			BeginAttack(TS_SwitchIndex, TS_SwitchKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.5);
			BeginAttack(TS_AttackIndex, TS_AttackKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			yield return WaitTime(0.15);
			StopCor(shootCor);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == TS_AttackIndex && eventName == "ChargeFx" && !ChargeFxSwitch)
			{
				PlayEffect("fx_common_base_charge_fire_actor", 1f, 2, GetPosition(), default(FP), 2.5f);
				ChargeFxSwitch = true;
			}
		}

		protected IEnumerator TurnShoot()
		{
			FP animationDuration = 1;
			TSVector2 shootDirection = GetForward();
			FP shootDuration = 0.03;
			for (int i = 0; i < 99; i++)
			{
				FanMultipleShoot(bullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 1, 0, GetPosition(), 1.3, shootDirection, 0, AimType.Default, BulletDirectionType.ActorToBullet, 5, 0, 3);
				yield return WaitTime(shootDuration);
				shootDirection = RotateTo(shootDirection, -(360 / animationDuration) * shootDuration);
			}
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == TS_AttackIndex)
			{
				if (TS_AttackLoopCount > 0)
				{
					CancelAttack();
					return;
				}
				shootCor = StartCor(TurnShoot());
				TS_AttackLoopCount++;
			}
		}
	}
	public class Skill_Wind : SkillSimpleBase
	{
		private string evt_play = "PlayHintFx";

		private string evt_stop = "StopHintFx";

		private List<long> fxList = new List<long>();

		private readonly int windStartIndex;

		private readonly string windStartKey = "Wind_Start";

		private readonly int windHoldIndex = 1;

		private readonly string windHoldKey = "Wind_Hold";

		private readonly int windAttackIndex = 2;

		private readonly string windAttackKey = "Wind_Attack";

		private readonly int windInhaleIndex = 3;

		private readonly string windInhaleKey = "Wind_Inhale";

		private TSVector2 atkDir;

		private long windFxIndex;

		private string windFx = "fx_50271_loop_ground_wind";

		private long warningFxIndex;

		private string warningFx = "fx_50271_warning_windvane";

		private long pointer_motionFxIndex;

		private string pointer_motionFx = "fx_m50271_loop_pointer_rotate";

		private long pointer_motionlessFxIndex;

		private string pointer_motionlessFx = "fx_m50271_loop_pointer_rotate_end";

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			if (fxList != null && fxList.Count > 0)
			{
				for (int i = 0; i < fxList.Count; i++)
				{
					StopEffect(fxList[i]);
				}
			}
			fxList.Clear();
			DispatchCustomEvent(evt_play);
		}

		protected override IEnumerator DoMainLogic()
		{
			atkDir = ChooseDirectionOfATK();
			DispatchCustomEvent(evt_stop);
			pointer_motionFxIndex = PlayEffect(pointer_motionFx);
			fxList.Add(pointer_motionFxIndex);
			windFxIndex = PlayEffect(windFx, 1f, default(FP), GetPosition(), GetTSVectToAngle(atkDir, 0));
			fxList.Add(windFxIndex);
			MoveToPosition(TSVector2.zero, 0);
			yield return WaitMoveStatus();
			yield return BeginLookAtByPos(new TSVector2(0, -20), 0.6, 300);
			BeginAttack(windStartIndex, windStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.2);
			BeginAttack(windInhaleIndex, windInhaleKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.07);
			BeginAttack(windHoldIndex, windHoldKey, flushInputedKeys: true, forceInterruptAttack: true);
			StopEffect(pointer_motionFxIndex);
			pointer_motionlessFxIndex = PlayEffect(pointer_motionlessFx, 1f, default(FP), default(TSVector2), GetTSVectToAngle(atkDir, 0));
			fxList.Add(pointer_motionlessFxIndex);
			yield return WaitTime(0.8);
			warningFxIndex = PlayEffect(warningFx, 1f, default(FP), GetPosition(), GetTSVectToAngle(atkDir, 0));
			fxList.Add(warningFxIndex);
			yield return WaitTime(0.8);
			PlayEffect("fx_common_base_charge_fire_actor", 1f, 2, GetPosition(), default(FP), 2.5f);
			yield return BeginLookAtByPos(atkDir, 0.4, 450);
			StopEffect(warningFxIndex);
			BeginAttack(windAttackIndex, windAttackKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(2);
			StopEffect(windFxIndex);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private TSVector2 ChooseDirectionOfATK()
		{
			TSVector2 result;
			switch ((int)(long)GetRandomValue(0, 3.5, isInt: true))
			{
			case 0:
				result = new TSVector2(0, 40);
				break;
			case 1:
				result = new TSVector2(-40, 0);
				break;
			case 2:
				result = new TSVector2(40, 0);
				break;
			case 3:
				result = new TSVector2(0, -40);
				break;
			default:
				return TSVector2.down;
			}
			return result;
		}
	}
}
