	public class Skill_Confront : SkillSimpleBase
	{
		private readonly string combo_TrunKey = "NormalAtk";

		private readonly string combo_left_move = "Confront2L";

		private readonly string combo_right_move = "Confront2R";

		private readonly FP turnAngle_limit = 90;

		private readonly string event_start = "StartToTurn";

		private readonly string even_end = "StopTurn";

		private readonly int loopCount_Normal = 3;

		private readonly FP checkRadius = 5;

		private readonly FP checkAngle = 120;

		private readonly FP distance_b = 15;

		private readonly FP _moveSpeedRatioAbsAmend = 0.5;

		private readonly float time_min = 1f;

		private readonly float time_max = 6f;

		private readonly FP controlPointX_Offset = 0.5;

		private readonly FP controlPointY_Offset = 0.5;

		private bool inRange;

		private int index;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		private FP CrossProduct2D(TSVector2 a, TSVector2 b)
		{
			return a.x * b.y - a.y * b.x;
		}

		protected override IEnumerator DoMainLogic()
		{
			PlayerAdventureActor target = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
			if (target == null)
			{
				yield break;
			}
			TSVector2 targetPos = new TSVector2(0, 0);
			TSVector2 direction = _actor.tsTransform.Position.normalized;
			CoroutineNode lookCor = null;
			if (TSVector2.Angle(-direction, _actor.tsTransform.Forward) > 10)
			{
				BeginAttack(1, combo_TrunKey, flushInputedKeys: true, forceInterruptAttack: true);
				index = 0;
				yield return WaitCustomEvent(event_start);
				if (turnAngle_limit > 0)
				{
					Skill_Confront skill_Confront = this;
					TSVector2 targetPos2 = targetPos;
					FP rotateSpeed = turnAngle_limit;
					lookCor = skill_Confront.BeginLookAtByPos(targetPos2, default(FP), rotateSpeed);
				}
				yield return WaitCustomEvent(even_end);
				StopCor(lookCor);
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
			TSVector2 normalized = (target.tsTransform.Position - _actor.tsTransform.Position).normalized;
			FP fP = CrossProduct2D(-direction, normalized);
			targetPos = _actor.tsTransform.Position + _actor.tsTransform.Forward.normalized * distance_b;
			string actionKey = combo_left_move;
			FP offset_y = controlPointY_Offset;
			if (fP < 0)
			{
				offset_y = -controlPointY_Offset;
				actionKey = combo_right_move;
			}
			inRange = true;
			BeginAttack(2, actionKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginBezierPathMove(1, targetPos, controlPointX_Offset, offset_y, comboWithAttack: true, _moveSpeedRatioAbsAmend, AdventureActor.MovementMode.Run, 80, time_max);
			yield return WaitTime(time_min);
			while (inRange)
			{
				FP fP2 = CalcAngleBetweenSelfAndAttackTarget();
				FP fP3 = _actor.DistanceWithRadius(target);
				if (fP2 > checkAngle || fP3 > checkRadius)
				{
					inRange = false;
				}
				yield return WaitTime(0.1);
			}
			CancelAttack();
			CancelBezierPathMove();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			BeginAttack(3, combo_TrunKey, flushInputedKeys: true, forceInterruptAttack: true);
			index = 0;
			yield return WaitCustomEvent(event_start);
			if (turnAngle_limit > 0)
			{
				Skill_Confront skill_Confront2 = this;
				FP rotateSpeed = turnAngle_limit;
				lookCor = skill_Confront2.BeginLookAt(target, default(FP), rotateSpeed);
			}
			yield return WaitCustomEvent(even_end);
			StopCor(lookCor);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex != 2)
			{
				index++;
				if (index >= loopCount_Normal)
				{
					CancelAttack();
				}
			}
		}

		protected override void OnLookAtComplete()
		{
			base.OnLookAtComplete();
		}

		protected override void OnBezierPathMoveFinish(int index, bool reachTerminal)
		{
			base.OnBezierPathMoveFinish(index, reachTerminal);
			if (inRange)
			{
				_skill.Clear();
			}
		}
	}
	public class Skill_Dash : SkillSimpleBase
	{
		private readonly string combo_dash = "DashDMG";

		private readonly string combo_shuaiwei = "Drift";

		private readonly string combo_shache = "Dash_Brake";

		private readonly string combo_stun = "DashDMGWeak";

		private readonly FP _acceleration = 20;

		private readonly FP _initialVelocity = 5;

		private readonly FP _maxVelocity = 50;

		private readonly bool _useComboSpd = true;

		private readonly FP _initialComboSpd = 0.5;

		private readonly FP _maxComboSpd = 1.5;

		private readonly FP turnAngle_limit = 240;

		private readonly float time_max = 5f;

		private readonly FP timeStun_1 = 1.5;

		private readonly FP timeStun_2 = 3;

		private readonly FP angle = 180;

		private readonly FP angle_limit_1 = 10;

		private readonly FP angle_limit_2 = 1;

		private readonly string event_shache = "BrakeTurn";

		private readonly string event_shuaiwei = "DriftTurn";

		private bool dashFinish;

		private bool beBreak;

		private FP beginTime;

		protected override void OnSkillEnable()
		{
			SetCloseBlockEnable();
		}

		protected override void OnSkillDisable()
		{
			SetCloseBlockDisable();
		}

		private LogicEntity GetTarget()
		{
			LogicEntity attackTarget = GetAttackTarget(isUpToDate: true);
			if (CheckTargetIsValid(attackTarget))
			{
				return attackTarget;
			}
			return SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
		}

		protected override IEnumerator DoMainLogic()
		{
			LogicEntity target = GetTarget();
			if (target == null)
			{
				yield break;
			}
			beginTime = _actor.LogicTime;
			dashFinish = false;
			int num = 999;
			BeginDashWithAcc(1, combo_dash, _acceleration, _initialVelocity, _maxVelocity, _useComboSpd, _initialComboSpd, _maxComboSpd, 0.1f, num, turnAngle_limit, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false, 0.5f);
			CoroutineNode lookCor = null;
			if (turnAngle_limit > 0)
			{
				Skill_Dash skill_Dash = this;
				FP rotateSpeed = turnAngle_limit;
				lookCor = skill_Dash.BeginLookAt(target, default(FP), rotateSpeed);
			}
			FP state = GetLogicTagFpValue(_actor, "state");
			while (!dashFinish && beginTime + time_max > _actor.LogicTime)
			{
				yield return null;
			}
			StopCor(lookCor);
			StopDash();
			beBreak = beginTime + time_max > _actor.LogicTime;
			if (beBreak && state > 0)
			{
				BeginAttack(2, combo_stun, flushInputedKeys: true, forceInterruptAttack: true);
				FP waitSeconds = (GetLogicTagToggleValue(_actor, "OddNumer") ? timeStun_2 : timeStun_1);
				yield return WaitTime(waitSeconds);
				CancelAttack();
				yield break;
			}
			TSVector2 normalized = (target.tsTransform.Position - _actor.tsTransform.Position).normalized;
			FP angle_limit = angle_limit_2;
			string eventName = event_shuaiwei;
			FP fP = TSVector2.Angle(normalized, _actor.tsTransform.Forward);
			if (fP < angle / 2 || fP > 360 - angle / 2)
			{
				BeginAttack(3, combo_shache, flushInputedKeys: true, forceInterruptAttack: true);
				angle_limit = angle_limit_1;
				eventName = event_shache;
			}
			else
			{
				BeginAttack(3, combo_shuaiwei, flushInputedKeys: true, forceInterruptAttack: true);
