	public class Skill_Ice : SkillSimpleBase
	{
		private readonly string combo_key = "GeneralAtk";

		private readonly FP radius_max = 12;

		private readonly int num_max = 8;

		private readonly FP radius = 6;

		private readonly int num = 3;

		private readonly FP time_wait = 2;

		private readonly string area_Show = "IceCube_wait";

		private readonly string area_Boom = "IceCube_action";

		private readonly FP time_shifang = 1;

		private readonly FP ice_r = 3;

		private readonly FP ice_r_w = 3;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		private List<TSVector2> CalculatePositions(int n, FP radius)
		{
			List<TSVector2> list = new List<TSVector2>();
			if (n <= 0 || radius <= 0)
			{
				return list;
			}
			float num = (float)Math.PI * 2f / (float)n;
			for (int i = 0; i < n; i++)
			{
				float f = (float)i * num;
				FP x = radius * Mathf.Cos(f);
				FP y = radius * Mathf.Sin(f);
				list.Add(new TSVector2(x, y));
			}
			return list;
		}

		private int getPosIndex(AdventureActor target)
		{
			FP fP = TSVector2.Distance(target.tsTransform.Position, TSVector2.zero);
			if (fP >= radius_max - ice_r_w)
			{
				return 3;
			}
			if (fP > ice_r)
			{
				return 2;
			}
			return 1;
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, combo_key, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayerAdventureActor activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
			if (activedPlayerActor == null)
			{
				yield break;
			}
			List<TSVector2> pos_nei = CalculatePositions(this.num, radius);
			List<TSVector2> pos_wai = CalculatePositions(num_max, radius_max);
			if (Parallel_1.pointAreaId > 0)
			{
				int posIndex = getPosIndex(activedPlayerActor);
				if (activedPlayerActor.actorInfo.attackType == GameEnum.characterAttackType.MELEE)
				{
					if (posIndex == 2)
					{
						StopAreaEffect(Parallel_1.pointAreaId);
						PlayAreaEffect(area_Boom, TSVector2.zero);
						Parallel_1.pointAreaId = 0L;
						for (int i = 0; i < Parallel_1.dicWai.Count; i++)
						{
							StopAreaEffect(Parallel_1.dicWai[i]);
							PlayAreaEffect(area_Boom, pos_wai[i]);
						}
						Parallel_1.dicWai.Clear();
						yield return WaitTime(time_wait);
						for (int j = 0; j < Parallel_1.dicNei.Count; j++)
						{
							StopAreaEffect(Parallel_1.dicNei[j]);
							PlayAreaEffect(area_Boom, pos_nei[j]);
						}
						Parallel_1.dicNei.Clear();
					}
					else
					{
						for (int k = 0; k < Parallel_1.dicNei.Count; k++)
						{
							StopAreaEffect(Parallel_1.dicNei[k]);
							PlayAreaEffect(area_Boom, pos_nei[k]);
						}
						Parallel_1.dicNei.Clear();
						yield return WaitTime(time_wait);
						StopAreaEffect(Parallel_1.pointAreaId);
						PlayAreaEffect(area_Boom, TSVector2.zero);
						Parallel_1.pointAreaId = 0L;
						for (int l = 0; l < Parallel_1.dicWai.Count; l++)
						{
							StopAreaEffect(Parallel_1.dicWai[l]);
							PlayAreaEffect(area_Boom, pos_wai[l]);
						}
						Parallel_1.dicWai.Clear();
					}
				}
				else if (posIndex == 2)
				{
					for (int m = 0; m < Parallel_1.dicNei.Count; m++)
					{
						StopAreaEffect(Parallel_1.dicNei[m]);
						PlayAreaEffect(area_Boom, pos_nei[m]);
					}
					Parallel_1.dicNei.Clear();
					yield return WaitTime(time_wait);
					StopAreaEffect(Parallel_1.pointAreaId);
					PlayAreaEffect(area_Boom, TSVector2.zero);
					Parallel_1.pointAreaId = 0L;
					for (int n = 0; n < Parallel_1.dicWai.Count; n++)
					{
						StopAreaEffect(Parallel_1.dicWai[n]);
						PlayAreaEffect(area_Boom, pos_wai[n]);
					}
					Parallel_1.dicWai.Clear();
				}
				else
				{
					StopAreaEffect(Parallel_1.pointAreaId);
					PlayAreaEffect(area_Boom, TSVector2.zero);
					Parallel_1.pointAreaId = 0L;
					for (int num = 0; num < Parallel_1.dicWai.Count; num++)
					{
						StopAreaEffect(Parallel_1.dicWai[num]);
						PlayAreaEffect(area_Boom, pos_wai[num]);
					}
					Parallel_1.dicWai.Clear();
					yield return WaitTime(time_wait);
					for (int num2 = 0; num2 < Parallel_1.dicNei.Count; num2++)
					{
						StopAreaEffect(Parallel_1.dicNei[num2]);
						PlayAreaEffect(area_Boom, pos_nei[num2]);
					}
					Parallel_1.dicNei.Clear();
				}
				CancelAttack();
			}
			else
			{
				long pointAreaId = PlayAreaEffect(area_Show, TSVector2.zero);
				Parallel_1.pointAreaId = pointAreaId;
				for (int num3 = 0; num3 < pos_nei.Count; num3++)
				{
					pointAreaId = PlayAreaEffect(area_Show, pos_nei[num3]);
					Parallel_1.dicNei.Add(pointAreaId);
				}
				for (int num4 = 0; num4 < pos_wai.Count; num4++)
				{
					pointAreaId = PlayAreaEffect(area_Show, pos_wai[num4]);
					Parallel_1.dicWai.Add(pointAreaId);
				}
				yield return WaitTime(time_shifang);
				CancelAttack();
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Move : SkillSimpleBase
	{
		private readonly string combo_key = "DashNoDMG";

		private readonly FP turnAngle_limit = 90;

		private readonly FP move_speed = 7;

		private readonly float time_move = 2f;

		private readonly FP stopDistance = 3;

		private readonly FP turnAngle_limit_toPos = 90;

		private readonly FP stopDistance_move = 0.2;

		private bool beginDash;

		protected override void OnSkillEnable()
		{
			beginDash = false;
			SetCloseBlockEnable();
		}

		protected override void OnSkillDisable()
		{
			SetCloseBlockDisable();
			Parallel_1.toPos = false;
			Parallel_1.safemove = false;
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, combo_key, flushInputedKeys: true, forceInterruptAttack: true);
			FP distance = move_speed * time_move;
			beginDash = true;
			BeginDashActorForward(1, move_speed, distance, turnAngle_limit, comboWithAttack: true, isAngle: true, notChangeForward: false, Parallel_1.toPos, triggerEnemyStop: true, triggerFriendStop: false, Parallel_1.safemove ? 0.05 : 0.3);
			CoroutineNode lookCor = null;
			if (Parallel_1.toPos)
			{
				Skill_Move skill_Move = this;
				TSVector2 targetPos = Parallel_1.targetPos;
				FP rotateSpeed = turnAngle_limit_toPos;
				lookCor = skill_Move.BeginLookAtByPos(targetPos, default(FP), rotateSpeed);
			}
			else if (turnAngle_limit > 0)
			{
				lookCor = BeginLookAtMonsterTarget(999, turnAngle_limit);
			}
			yield return WaitDashFinish();
			beginDash = false;
			if (lookCor != null)
			{
				StopCor(lookCor);
				StopLookAt();
			}
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void DashFinishByObstacle(int index)
		{
		}

		public void OnUpdate()
		{
			if (!beginDash)
			{
				return;
			}
			if (Parallel_1.toPos)
			{
				if (TSVector2.Distance(_actor.tsTransform.Position, Parallel_1.targetPos) <= stopDistance_move)
				{
					StopDash();
				}
			}
			else if (_actor.monsterTarget != null && _actor.DistanceWithRadius(_actor.monsterTarget) < stopDistance)
			{
				StopDash();
			}
		}
	}
