			loopCount = ((logicTagFpValue == 1) ? loopCount_Normal : loopCount_Near);
			BeginAttack(1, actionKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent(event_start);
			CoroutineNode lookCor = null;
			if (Parallel_1.toRot)
			{
