	public class Action : AIBase
	{
		private static readonly int summonSkillId = 5001606;

		private static readonly int dashSkillId = 5001602;

		private static readonly int shootSkillId = 5001602;

		private static readonly int topdownSkillId = 5001602;

		private static readonly int hideSkillId = 5001605;
	}
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private static readonly int summonSkillId = 5016105;

		private static readonly int dashSkillId = 5016101;

		private static readonly int shootSkillId = 5016102;

		private static readonly int topdownSkillId = 5016103;

		private static readonly int hideSkillId = 5016104;

		private int _currentSkillId;

		private bool _skillFinishByLostControl;

		public void OnEnable()
		{
			_skillFinishByLostControl = false;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("MONSTER_BIANSUCIKE_MESSAGE", OnReceiveMessage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_STATE_SWITCH", OnStateSwitch);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_BIANSUCIKE_MESSAGE", OnReceiveMessage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_STATE_SWITCH", OnStateSwitch);
		}

		private void OnReceiveMessage(IEvent evt)
		{
			if (evt is AdventureMonsterBiansucikeMessage adventureMonsterBiansucikeMessage && adventureMonsterBiansucikeMessage.monsterId == _actor.Id)
			{
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_summon")
				{
					_skillFinishByLostControl = false;
					_actor.InterruptForceControl();
					_actor.InterruptChaos();
					CastSkill(summonSkillId);
				}
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_hide_1")
				{
					_actor.logicVariable.SetLogicTagValue("skillType", 1);
					CastSkill(hideSkillId);
				}
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_hide_2")
				{
					_actor.logicVariable.SetLogicTagValue("skillType", 2);
					CastSkill(hideSkillId);
				}
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_dash")
				{
					CastSkill(dashSkillId);
				}
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_shoot")
				{
					CastSkill(shootSkillId);
				}
				if (adventureMonsterBiansucikeMessage.operationType == "castSkill_topDown")
				{
					CastSkill(topdownSkillId);
				}
			}
		}

		private void CastSkill(int skillId)
		{
			if (_actor.state == ActorState.Action || _actor.state == ActorState.Idle)
			{
				_actor.InterruptAttack(force: true);
				_actor.actorSkillManage.DestoryAllSkill();
				_currentSkillId = skillId;
				_skillFinishByLostControl = false;
				ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
				{
					if (_actor.state == ActorState.Action)
					{
						SetActorState();
						SendSkillFinishMessage();
					}
					else if (_actor.state == ActorState.LostControl)
					{
						_skillFinishByLostControl = true;
						_actor.InterruptBattleOut();
						_actor.InterruptHideModel();
						_actor.InterruptCloseBlock();
						_actor.InterruptSuperArmor();
					}
					_currentSkillId = 0;
				});
			}
			else if (skillId != hideSkillId)
			{
				SendSkillFinishMessage();
			}
		}

		private void OnStateSwitch(IEvent evt)
		{
			if (evt is AdventureActorStateSwitchEvent adventureActorStateSwitchEvent && adventureActorStateSwitchEvent.Id == _actor.Id && adventureActorStateSwitchEvent._acState == ActorState.Action && _skillFinishByLostControl)
			{
				_actor.logicVariable.SetLogicTagValue("skillType", 1);
				_actor.logicVariable.ToggleLogicTag("FinishByLostControl", value: true);
				CastSkill(hideSkillId);
			}
		}

		private void SetActorState()
		{
			_actor.InterruptBattleOut();
			_actor.InterruptHideModel();
			_actor.InterruptCloseBlock();
			_actor.InterruptSuperArmor();
			if (!_actor.logicVariable.GetLogicTagToggle("SummonToDive"))
			{
				_actor.EnableBattleOut();
				_actor.EnableHideModel();
			}
			else
			{
				_actor.logicVariable.ToggleLogicTag("SummonToDive", value: false);
			}
		}

		private void SendSkillFinishMessage()
		{
			if (_currentSkillId != summonSkillId)
			{
				AdventureMonsterBiansucikeMessage adventureMonsterBiansucikeMessage = AdventureMonsterBiansucikeMessage.Generate();
				adventureMonsterBiansucikeMessage.monsterId = _actor.Id;
				adventureMonsterBiansucikeMessage.operationType = "skillFinish";
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureMonsterBiansucikeMessage);
			}
		}
	}
	public class Skill_Dash : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] actionKeys_1_1 = new ComboInputBuffer.ActionKey[3];

		private static readonly ComboInputBuffer.ActionKey[] actionKeys_1_2 = new ComboInputBuffer.ActionKey[3]
		{
			ComboInputBuffer.ActionKey.D,
			ComboInputBuffer.ActionKey.A,
			ComboInputBuffer.ActionKey.A
		};

		private static readonly ComboInputBuffer.ActionKey[] actionKeys_2_1 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.O };

		private static readonly ComboInputBuffer.ActionKey[] actionKeys_2_2 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Q };

		private static readonly string customEvent_JoinBattle = "JoinBattle";

		private static readonly string customEvent_Dash = "Dash";

		private static readonly string customEvent_ExitBattle = "ExitBattle";

		private static readonly string customEvent_FlashFX = "FlashFX";

		private static readonly string customEvent_HideModelDisable = "HideModelDisable";

		private static readonly string customEvent_BackDash = "BackDash";

		private static readonly FP searchDistanc = 5.5;

		private static readonly FP searchDistancNear = 4.5;

		private static readonly List<FP> searchAngles = new List<FP> { 120, 150, 180, 210, 240 };

		private static readonly ComboInputBuffer.ActionKey[] actionKeys_null = new ComboInputBuffer.ActionKey[0];

		private static readonly FP waitTime_original = 0;

		private static readonly FP waitTime_max = 4;

		private static readonly FP waitTime_extra = 0.75;

		private FP dashDistance = 10;

		private FP dashSpeed = 70;

		private bool isWaitingForSecondAttak;

		private CoroutineNode _waitingCoroutine;

		private FP realWaitTime;

		private FP remainWaitTime;

		private FP realWaitTimeMin;

		private FP realWaitTimeMax;

		private bool isAction;

		private ComboInputBuffer.ActionKey[] actionKeys_1;

		private ComboInputBuffer.ActionKey[] actionKeys_2;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			remainWaitTime = (realWaitTimeMin = waitTime_original);
			realWaitTimeMax = waitTime_max - _actor.logicVariable.GetLogicTagValue("waitTimeReduce");
			isAction = true;
			realWaitTime = 0;
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			if (GetLogicTagFpValue(_actor, "Phase") == 1)
			{
				actionKeys_1 = actionKeys_1_1;
			}
			else
			{
				actionKeys_1 = actionKeys_1_2;
			}
			GetAttackTarget(isUpToDate: true);
			TSVector2 pointsByActorAndScreenTopDirWithRotationAnglesAndDistance = ILRuntimeAPI.GetPointsByActorAndScreenTopDirWithRotationAnglesAndDistance(_actor, searchAngles, searchDistanc, searchDistancNear);
			Teleport(pointsByActorAndScreenTopDirWithRotationAnglesAndDistance);
			BeginLookAt_NotWait(GetAttackTarget(), 0.1, 999);
			BeginAttack(1, actionKeys_1, flushInputedKeys: true);
			BeginLookAt_NotWait(GetAttackTarget(), 999, 999);
			yield return WaitCustomEvent(customEvent_HideModelDisable);
			SetHideModelDisable();
			PlayEffect("DashCharge", 1f, 0, GetPosition(), 0, 1f, actorScale: true);
			yield return WaitCustomEvent(customEvent_JoinBattle);
			SetBattleOutDisable();
			yield return WaitCustomEvent(customEvent_BackDash);
			BeginDash(2, GetForward() * -1, 2.5, 1.5, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitCustomEvent(customEvent_FlashFX);
			PlayEffect("FlashFX", 1f, 3.8, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0.88, -0.72)), 0, 1f, actorScale: true);
			StopWaitLookAt();
			yield return WaitCustomEvent(customEvent_Dash);
			BeginDashActorForward(1, dashSpeed, dashDistance, 0, comboWithAttack: true, isAngle: true, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			long DashSpeedlineFX = PlayEffect("DashSpeedLine");
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopEffect(DashSpeedlineFX);
			BeginAttack(2, "Idle", flushInputedKeys: true);
			yield return BeginLookAtMonsterTarget(1, 100);
			CancelAttack();
			InterruptAttack();
			if (GetLogicTagFpValue(_actor, "Phase") == 1)
			{
				actionKeys_2 = actionKeys_2_1;
			}
			else
			{
				actionKeys_2 = actionKeys_2_2;
			}
			BeginAttack(2, actionKeys_2, flushInputedKeys: true);
			yield return WaitCustomEvent(customEvent_ExitBattle);
			SetBattleOutEnable();
			SetHideModelEnable();
			ShowBlood(isShow: false);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetBattleOutDisable();
			SetHideModelDisable();
		}

		private IEnumerator Waiting()
		{
			while (true)
			{
				realWaitTime += _actor.LogicDeltaTime;
				if (isAction)
				{
					remainWaitTime -= _actor.LogicDeltaTime;
					if (remainWaitTime <= 0)
					{
						break;
					}
				}
				yield return null;
			}
		}
	}
	public class Skill_Death : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] actionKeys_die = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Z };

		protected override void OnSkillEnable()
		{
			SetSuperArmorEnable();
		}

		protected override void OnSkillDisable()
		{
			SetSuperArmorDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			SendDeclareDeadEvent();
			if (GetLogicTagToggleValue(_actor, "BattleInterrupted"))
			{
				if (!ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.SanJianKe_001))
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.SanJianKe_001);
					NovaLogger.Error("完成成就1");
				}
				Singleton<InteractiveManager>.Instance.triggerOpListener("BattleInterrupted");
			}
			InterruptHideModel();
			SetCloseBlockEnable();
			BeginAttack(1, actionKeys_die, flushInputedKeys: true);
			yield return WaitTime(4);
			CancelAttack();
		}
	}
	public class Skill_Hide : SkillSimpleBase
