namespace AIScript.Monster._50111Xbuffjingling.Summons.CanChaZhu
{
	public class Action : MonsterActionBase
	{
		protected static List<BaseBranchInfo> sequenceBranchesList;

		private Dictionary<int, List<int>> sequenceDict;

		private List<int> addShield = new List<int>();

		private List<int> shooting = new List<int>();

		private List<int> waiting = new List<int>();

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			SetLogicTag();
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			addShield.Add(1001);
			shooting.Add(1002);
			waiting.Add(1003);
			sequenceBranchesList = new List<BaseBranchInfo>
			{
				new BaseBranchInfo(1001, 50, 360, 2, null, SetShield),
				new BaseBranchInfo(1002, 50, 360, 2, null, shootSkill),
				new BaseBranchInfo(1003, 50, 360, 2, null, Waiting)
			};
			sequenceDict = new Dictionary<int, List<int>>
			{
				[1] = addShield,
				[2] = waiting,
				[3] = shooting
			};
			InitSequenceBranches(1, sequenceBranchesList, sequenceDict);
		}

		private void SetLogicTag()
		{
			SetLogicTagFpValue(_actor, "ShootCount", 1);
		}

		protected override void OnActionDisable()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			SetLogicTagFpValue(_actor, "ShootCount", 1);
			addShield.Clear();
			shooting.Clear();
		}

		protected IEnumerator UpdateShootCount()
		{
			for (int i = 0; i < 10; i++)
			{
				yield return WaitTime(3);
				DispatchCustomEvent("AddShootCount");
			}
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && string.Equals(adventureActorCustomEvent.eventName, "AddShootCount"))
			{
				FP logicTagFpValue = GetLogicTagFpValue(_actor, "ShootCount");
				if (logicTagFpValue > 0 && logicTagFpValue < 3)
				{
					SetLogicTagFpValue(_actor, "ShootCount", logicTagFpValue + 1);
				}
				else if (logicTagFpValue >= 3)
				{
					SwitchSequence(3, initialIndex: false);
				}
			}
		}

		private IEnumerator SetShield()
		{
			CastSkill(5011160);
			yield return WaitSkillFinish();
			SwitchSequence(2);
		}

		private IEnumerator shootSkill()
		{
			CastSkill(5011161);
			yield return WaitSkillFinish();
			KillActors(new List<LogicEntity> { _actor });
		}

		private IEnumerator Waiting()
		{
			yield return WaitTime(10);
		}

		protected override void OnActionStart()
		{
			base.OnActionStart();
			StartCor(UpdateShootCount());
		}
	}
	public class Parallel_CanChasZhu : AIScript.Monster.Template.Parallel
	{
		private string evtMonsterPlayLinkFx = "MonsterPlayLinkFx";

		private string evtMonsterStopLinkFx = "MonsterStopLinkFx";

		private string linkFx = "fx_50111buffjingling_Warning_line";

		private PlayFX playFX = new PlayFX();

		public override void OnStart()
		{
			base.OnStart();
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			playFX.Stop();
		}

		private void OnCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent)
			{
				if (adventureActorCustomEvent.eventName.Equals(evtMonsterPlayLinkFx))
				{
					PlayerAdventureActor activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
					TSVector sourcePosition = new TSVector(_actor.tsTransform.Position.x, 0, _actor.tsTransform.Position.y);
					TSVector targetPosition = new TSVector(activedPlayerActor.tsTransform.Position.x, 0, activedPlayerActor.tsTransform.Position.y);
					playFX.PlayLinFx(_actor, linkFx, 1f, useCustSource: false, _actor.gameObject, sourcePosition, _actor.tsTransform.PositionY, activedPlayerActor.gameObject, targetPosition, activedPlayerActor.tsTransform.PositionY);
				}
				else if (adventureActorCustomEvent.eventName.Equals(evtMonsterStopLinkFx))
				{
					playFX.Stop();
				}
			}
		}
	}
