	public class Skill_Die : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Z };

		private static readonly string airBorneDeathEffectAlias = "fx_common_base_die_airborne";

		private static readonly FP effectDuration = 2f;

		protected override IEnumerator DoMainLogic()
		{
			RemoveShield();
			SetCloseBlockEnable();
			SendDeclareDeadEvent();
			if (DieWithAirBorne() && !_actor.IsBossMonster())
			{
				_actor.PlayHurtAnim();
				PlayEffect(airBorneDeathEffectAlias, 1f, _actor.tsTransform.PositionY, _actor.tsTransform.Position, (_actor.killer != null) ? _actor.killer.tsTransform.Rotation : _actor.tsTransform.Rotation);
				yield return WaitTime(1);
			}
			else
			{
				_actor.PlayDeathAnim();
				BeginAttack(1, actionKeys);
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
		}

		private bool DieWithAirBorne()
		{
			if (_actor.movementState == ActorState.Jump)
			{
				return true;
			}
			if (_actor.killerHitBox == null)
			{
				return false;
			}
			if ((_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.KnockBack) == HitBox.FeatureFlag.KnockBack)
			{
				return true;
			}
			return (_actor.killerHitBox.featureFlags & HitBox.FeatureFlag.AirBorne) == HitBox.FeatureFlag.AirBorne;
		}

		private void RemoveShield()
		{
			if (GetTargetByTeammateIndex(0) != null && GetTargetByTeammateIndex(0).Count > 0)
			{
				LogicEntity target = GetTargetByTeammateIndex(0)[0];
				RemoveShieldById(target, 501110000);
			}
		}
	}
	public class Skill_Shooting : SkillSimpleBase
	{
		protected override IEnumerator DoMainLogic()
		{
			LogicEntity target = GetTarget();
			int shootCount = (int)(long)GetLogicTagFpValue(_actor, "ShootCount");
			yield return BeginLookAt(target, 0.5, 360);
			BeginAttack(0, new ComboInputBuffer.ActionKey[1], flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.3);
			PlayEffect("fx_monster_base_waring", 1f, 1, GetPosition(), default(FP), 1.5f);
			yield return WaitTime(0.2);
			for (int i = 0; i < shootCount; i++)
			{
				Shooting(1, 120 + i * 15);
				yield return WaitTime(0.25);
			}
			SetLogicTagFpValue(_actor, "ShootCount", 1);
		}

		private LogicEntity GetTarget()
		{
			LogicEntity logicEntity = null;
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				return GetAttackTarget();
			}
			return GetCurrentPlayer();
		}

		private void Shooting(int bulletCount, FP angle)
		{
			string bulletAlias = "50111BuffJingLing_bulletc_earth";
			TSVector2 forward = GetForward();
			TSVector2 multiShootDirection = RotateTo(forward, angle);
			TSVector2 multiShootDirection2 = RotateTo(forward, -angle);
			FanMultipleShoot(bulletAlias, AdventureWeapon.MultipleShootStyle.FromLeftToRight, alignShoot: true, 0, bulletCount, 0, GetPosition(), 0.5, multiShootDirection, 0, AimType.Default, BulletDirectionType.ActorToBullet, 20, 0, 1.5);
			FanMultipleShoot(bulletAlias, AdventureWeapon.MultipleShootStyle.FromRightToLeft, alignShoot: true, 0, bulletCount, 0, GetPosition(), 0.5, multiShootDirection2, 0, AimType.Default, BulletDirectionType.ActorToBullet, 20, 0, 1.5);
		}
	}
