namespace AIScript.Monster._Common._50111buffjingling
{
	public class Skill_RoundFriend : SkillAdvancedBase
	{
		protected FP fanAngle = 120;

		protected FP innerRange = 6;

		protected FP fanRange = 8;

		protected FP fanRotation = 180;

		protected FP maxTime = 3;

		protected AdventureActor _target;

		protected DeterministicShape _shape;

		protected LookAtTarget _lookAtTarget;

		protected CoroutineNode _waitCoroutine;

		public void OnStart()
		{
			List<LogicEntity> list = new List<LogicEntity>();
			_actor.InitSearchEntityContext(list, onlyAlive: true, includeSelf: false);
			List<MonsterAdventureActor> list2 = new List<MonsterAdventureActor>();
			foreach (LogicEntity item in list)
			{
				MonsterAdventureActor component = item.gameObject.GetComponent<MonsterAdventureActor>();
				if (!(component == null) && component.monsterInfo.subType == GameEnum.monsterSubType.Monster)
				{
					list2.Add(component);
				}
			}
			if (list2.Count == 0)
			{
				_skill?.Clear();
				return;
			}
			FP fP = 99999;
			foreach (MonsterAdventureActor item2 in list2)
			{
				FP fP2 = _actor.DistanceWithRadius(item2);
				if (fP2 < fP)
				{
					_target = item2;
					fP = fP2;
				}
			}
			toRandomPoint();
			StopCoroutine(ref _waitCoroutine);
			StartCoroutine(ref _waitCoroutine, waitCoroutine());
		}

		protected void toRandomPoint()
		{
			_shape.shapeType = DeterministicShape.ShapeType.Fan;
			_shape.angle = fanAngle;
			_shape.radius = fanRange;
			_shape.innerRadius = innerRange;
			_shape.position = _target.tsTransform.Position;
			_shape.rotation = (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position - _target.tsTransform.Position).GetAngle() + fanRotation;
			TSVector2 tSVector = _actor.RandomActorReachablePointInsideShape(_shape);
			if (!(tSVector != _shape.position))
			{
				return;
			}
			_actor.MoveTo(tSVector, 0.1, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
			{
				LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				if (activedPlayerActor != null)
				{
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAtByPos(_actor, activedPlayerActor.tsTransform.Position, 0, 0, delegate
					{
						_skill.Clear();
					});
				}
			});
		}

		protected override void OnSkillDisable()
		{
			_lookAtTarget?.Clear();
			StopCoroutine(ref _waitCoroutine);
			_target = null;
		}

		protected IEnumerator waitCoroutine()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(maxTime));
			_skill.Clear();
		}
	}
	public class Skill_RunAway : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		protected readonly string eventBlink = "Blink";

		protected readonly string fxPathBlink = "fx_50111buffjingling_base_skill1_02";

		protected readonly int buffId = 990011100;

		protected readonly string fxPathShow = "fx_50111buffjingling_base_skill1_03";

		protected FP waitTime = 0.2;

		protected FP fanAngle = 120;

		protected FP innerRange = 6;

		protected FP fanRange = 8;

		protected FP fanRotation = 180;

		protected ComboAttack _comboAttack;

		protected CoroutineNode _corWaitShow;

		protected PlayFX _playFXBlink;

		protected PlayFX _playFXShow;

		protected DeterministicShape _shape;

		public void OnStart()
		{
			_actor.logicVariable.ToggleLogicTag("CheckSkill_jingling", value: false);
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			_comboAttack.BeginAttack(_actor, _skill, actionKeys, flushInputedKeys: true, (_skill != null) ? _skill.skillId : 0, forceInterruptAttack: false, autoLookAtTarget: false, null, null, onCustomEvent: OnCustomEvent, onInterrupt: OnInterrupt, aimTargetPosition: default(TSVector2), onAnticipationEnd: null, onRecoveryBegin: null, onComboLoop: null, onComboFinish: delegate
			{
				OnFinish();
			});
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, eventBlink))
			{
				StopCoroutine(ref _corWaitShow);
				StartCoroutine(ref _corWaitShow, CorWaitShow());
			}
		}

		protected IEnumerator CorWaitShow()
		{
			_actor.buffComponent.AddBuff(buffId, _actor);
			Teleportation();
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitTime));
			_actor.buffComponent.RemoveBuffByBuffId(buffId);
		}

		protected void Teleportation()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			_shape.shapeType = DeterministicShape.ShapeType.Fan;
			_shape.angle = fanAngle;
			_shape.radius = fanRange;
			_shape.innerRadius = innerRange;
			_shape.position = _actor.tsTransform.Position;
			_shape.rotation = (activedPlayerActor.tsTransform.Position - _actor.tsTransform.Position).GetAngle() + fanRotation;
			TSVector2 tSVector = _actor.RandomActorReachablePointInsideShape(_shape);
			if (tSVector != _shape.position)
			{
				_actor.Teleport(tSVector);
			}
		}

		protected void OnFinish()
		{
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			_comboAttack?.Clear();
			_playFXBlink?.Clear();
			_playFXShow?.Clear();
			StopCoroutine(ref _corWaitShow);
			_actor.logicVariable.ToggleLogicTag("CheckSkill_jingling", value: true);
			_actor.buffComponent.RemoveBuffByBuffId(buffId);
		}
	}
	public class Skill_ToRandomPoint : SkillAdvancedBase
	{
		protected readonly bool _playerCenter;

		protected FP _radius = 3;

		protected FP _innerRadius = 0;

		protected FP _angle = 120;

		protected FP _rotation = 180;

