		private void GotoCastSkill(int ID)
		{
			if (testSkillId != 0)
			{
				ID = testSkillId;
			}
			CastSkill(ID);
		}

		private IEnumerator Cast()
		{
			if (CheckMonsterCost())
			{
				GotoCastSkill(Skill_SummonAct);
				if (GroupIndex < 12)
				{
					GroupIndex++;
				}
				else
				{
					GroupIndex = 9;
				}
				yield return WaitTime(1);
				WaveActivate();
			}
			else if (SkillTimes % 3 == 0)
			{
				GotoCastSkill(Skill_DarkWave_Ring);
				SkillTimes++;
			}
			else
			{
				GotoCastSkill(Skill_DarkWave_Fan);
				SkillTimes++;
			}
			yield return WaitSkillFinish();
		}

		private bool CheckMonsterCost()
		{
			TotalCost = 0;
			foreach (LogicEntity item in GetTargetsByFaction(isFriend: true))
			{
				int dataID = (item as AdventureActor).dataID;
				if (MonsterCostDic.ContainsKey(dataID))
				{
					TotalCost += MonsterCostDic[dataID];
				}
			}
			if (SummonTryIndex <= 0)
			{
				HaveToSummon = true;
			}
			SummonTryIndex--;
			if (TotalCost <= MaxCostInBattle[GroupIndex - 1] && HaveToSummon)
			{
				HaveToSummon = false;
				SummonTryIndex = 3;
				return true;
			}
			return false;
		}

		private void WaveActivate()
		{
			foreach (KeyValuePair<int, int> item in MonsterSummonDic[GroupIndex - 1])
			{
				GoToSummonMonsters(item.Key, item.Value);
			}
		}

		private void GoToSummonMonsters(int MonsterID, int MonsterAmount)
		{
			int i = 0;
			TSVector2 zero = TSVector2.zero;
			FP randomValue = GetRandomValue(0, 180);
			for (; i < MonsterAmount; i++)
			{
				zero = TransLocalPosToWorldPos(CenterPosition, RotateTo(RotateTo(TSVector2.up, randomValue), i * 360 / MonsterAmount + GetRandomValue(-15, 15)), new TSVector2(0, GetRandomValue(-2.5, 2.5) + MonsterDistanceDic[MonsterID]));
				SummonMonster(MonsterID, 0, zero, CenterPosition - zero);
			}
		}
	}
