		private IEnumerator AddSpeedDown(DeterministicShape BuffShape)
		{
			FP TimeAmount = 1.5;
			FP TimeCount = 0;
			while (TimeCount < TimeAmount)
			{
				foreach (LogicEntity item in GetTargetsFromShape(BuffShape, GetTargetsByFaction(isFriend: false)))
				{
					AddBuffToTarget(item, 501010710);
				}
				TimeCount += (FP)0.1;
				yield return WaitTime(0.1);
			}
		}
	}
