	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private const string _skillSplitThrow_bigBullet_tag = "skillSplitThrow_bigBullet";

		private const string _skillSplitThrow_smallBullet_tag = "skillSplitThrow_smallBullet";

		private readonly string _skillSplitThrow_bullet_alias = "Slime_SplitThrow_Born";

		private readonly int _skillSplitThrow_summon_rate_first = 50;

		private readonly int _skillSplitThrow_summon_id_first = 5000312;

		private readonly int _skillSplitThrow_summon_id_second = 5000312;

		private readonly string _skillSplitThrow_summon_tag = "skillSplitThrow_summon";

		private readonly int _skillSplitThrow_summon_maxCount = 2;

		private readonly int _skillSplitThrow_inner_radius = 3;

		private readonly int _skillSplitThrow_outer_radius = 5;

		private readonly int _selectPointMaxCount = 15;

		private const string _skillSlide_bullet_tag = "skillSlide_bullet";

		private readonly int _skillSlide_summon_rate_first = 50;

		private readonly int _skillSlide_summon_id_first = 5000314;

		private readonly int _skillSlide_summon_id_second = 5000314;

		private readonly string _skillSlide_summon_tag = "skillSlide_summon";

		private int _skillSplitThrowSummonCount;

		private const GameEnum.questCompleteCondClient achievementType_1 = GameEnum.questCompleteCondClient.ShiLaiMuWang_001;

		private const string checkLogicTag_1 = "IsBurst";

		private const GameEnum.questCompleteCondClient achievementType_2 = GameEnum.questCompleteCondClient.ShiLaiMuWang_002;

		private const GameEnum.questCompleteCondClient achievementType_3 = GameEnum.questCompleteCondClient.ShiLaiMuWang_003;

		private const string checkLogicTag_3 = "IsBurst";

		private static readonly int checkHitTag_3 = CommonHelper.StringToHash("DaShiLaiMu_KuoSanBo");

		private const GameEnum.questCompleteCondClient achievementType_4 = GameEnum.questCompleteCondClient.ShiLaiMuWang_004;

		private static readonly List<int> checkSkillId_4 = new List<int> { 0, 0 };

		private const string checkLogicTag_4 = "slideFinish";

		private static readonly FP checkTime_4 = 13.3;

		private static readonly List<int> checkTeammateIndex_4 = new List<int> { 1, 2 };

		private const GameEnum.questCompleteCondClient achievementType_5 = GameEnum.questCompleteCondClient.ShiLaiMuWang_005;

		private static readonly List<int> checkSkillId_5 = new List<int> { 5008113, 5008193 };

		private const string checkLogicTag_5 = "slideFinish";

		private bool _achievementTypeFinish_1;

		private bool _achievementTypeFinish_2;

		private bool _achievementTypeFinish_3;

		private bool _hitPlayer_3;

		private bool _achievementTypeFinish_4;

		private bool _canCheck_4;

		private FP _checkTime_4;

		private bool _forceFailed_4;

		private bool _achievementTypeFinish_5;

		public override void OnStart()
		{
			base.OnStart();
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			if (!_achievementTypeFinish_1 && !_actor.logicVariable.GetLogicTagToggle("IsBurst"))
			{
				SetAchievementState(GameEnum.questCompleteCondClient.ShiLaiMuWang_001);
			}
			if (!_achievementTypeFinish_3 && _actor.logicVariable.GetLogicTagToggle("IsBurst") && _hitPlayer_3)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.ShiLaiMuWang_003);
			}
			_skillSplitThrowSummonCount = 0;
		}

		private void OnBulletFinish(IEvent iEvent)
		{
			AdventureBulletFinishEvent adventureBulletFinishEvent = iEvent as AdventureBulletFinishEvent;
			switch (adventureBulletFinishEvent.tag)
			{
			case "skillSplitThrow_bigBullet":
				SplitBullet(adventureBulletFinishEvent.bulletPosition);
				break;
			case "skillSplitThrow_smallBullet":
			{
				int num = _skillSplitThrow_summon_id_first;
				TSVector2 normalized = (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position - adventureBulletFinishEvent.bulletPosition).normalized;
				if (TSRandom.value * 100 < _skillSplitThrow_summon_rate_first)
				{
					num = _skillSplitThrow_summon_id_second;
				}
				ILRuntimeAPI.SummonMonster(_actor, 0, num, adventureBulletFinishEvent.bulletPosition, normalized, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
				break;
			}
			case "skillSlide_bullet":
			{
				int num = _skillSlide_summon_id_first;
				TSVector2 normalized = (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.tsTransform.Position - adventureBulletFinishEvent.bulletPosition).normalized;
				if (TSRandom.value * 100 < _skillSlide_summon_rate_first)
				{
					num = _skillSlide_summon_id_second;
				}
				ILRuntimeAPI.SummonMonster(_actor, 0, num, adventureBulletFinishEvent.bulletPosition, normalized, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("skillSlideSummonCount");
				_actor.logicVariable.SetLogicTagValue("skillSlideSummonCount", logicTagValue + 1);
				break;
			}
			}
		}

		private void SplitBullet(TSVector2 position)
		{
			int num = _skillSplitThrow_summon_maxCount - _skillSplitThrowSummonCount;
			if (num > 0)
			{
				TSVector2 forward = _actor.tsTransform.Forward;
				switch (num)
				{
				case 1:
					Shoot(position, forward);
					break;
				case 2:
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 180);
					Shoot(position, forward);
					break;
				case 3:
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 120);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 120);
					Shoot(position, forward);
					break;
				case 4:
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 90);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 90);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 90);
					Shoot(position, forward);
					break;
				case 5:
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 72);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 72);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 72);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 72);
					Shoot(position, forward);
					break;
				case 6:
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 60);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 60);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 60);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 60);
					Shoot(position, forward);
					forward = TSVector2.Rotate(forward, 60);
					Shoot(position, forward);
					break;
				}
			}
		}

		private void Shoot(TSVector2 shootPosition, TSVector2 direction)
		{
			int num = TSRandom.Range(_skillSplitThrow_inner_radius, _skillSplitThrow_outer_radius);
			TSVector2 tSVector = shootPosition + direction * num;
			if (!_actor.QueryPositionReachable(tSVector))
			{
				tSVector = GetRandomPoint(shootPosition);
			}
			if (shootPosition != tSVector)
			{
				string skillSplitThrow_bullet_alias = _skillSplitThrow_bullet_alias;
				AdventureActor actor = _actor;
				TSVector2 targetPosition = tSVector;
				ILRuntimeAPI.Shoot(skillSplitThrow_bullet_alias, actor, default(FP), shootPosition, default(FP), targetPosition, null, AimType.Position, BulletDirectionType.BulletToTarget);
				_skillSplitThrowSummonCount++;
			}
		}

		private TSVector2 GetRandomPoint(TSVector2 position)
		{
			DeterministicShape deterministicCircleShape = CommonUtils.GetDeterministicCircleShape(_skillSplitThrow_outer_radius, _skillSplitThrow_inner_radius, position);
			return ILRuntimeAPI.GetRandomPointInShape(_actor, deterministicCircleShape, isReachable: true, _selectPointMaxCount);
		}

		protected override void OnActorDied(IEvent iEvent)
		{
			base.OnActorDied(iEvent);
			AdventureActorDiedEvent adventureActorDiedEvent = iEvent as AdventureActorDiedEvent;
			if (!(adventureActorDiedEvent.actor is PlayerAdventureActor))
			{
				if (((MonsterAdventureActor)adventureActorDiedEvent.actor).monsterInfo.Tag1 == _skillSplitThrow_summon_tag)
				{
					_skillSplitThrowSummonCount--;
				}
				if (((MonsterAdventureActor)adventureActorDiedEvent.actor).monsterInfo.Tag1 == _skillSlide_summon_tag)
				{
					FP logicTagValue = _actor.logicVariable.GetLogicTagValue("skillSlideSummonCount");
					_actor.logicVariable.SetLogicTagValue("skillSlideSummonCount", logicTagValue - 1);
				}
				OnActorDied(adventureActorDiedEvent);
			}
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShiLaiMuWang_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShiLaiMuWang_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShiLaiMuWang_003);
			_achievementTypeFinish_4 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShiLaiMuWang_004);
			_achievementTypeFinish_5 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.ShiLaiMuWang_005);
			_hitPlayer_3 = false;
			_canCheck_4 = false;
			_checkTime_4 = 0;
			_forceFailed_4 = false;
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is PlayerAdventureActor)
			{
				if (!_achievementTypeFinish_2 && (adventureActorReceiveDamageEvent.lostControlType & LostControlType.AirBorne) != LostControlType.None)
				{
					_achievementTypeFinish_2 = SetAchievementState(GameEnum.questCompleteCondClient.ShiLaiMuWang_002);
				}
				if (!_achievementTypeFinish_3 && !_hitPlayer_3)
				{
					_hitPlayer_3 = CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, checkHitTag_3);
				}
			}
		}

		private void OnCastSkill(IEvent evt)
		{
			AdventureActorCastSkillEvent adventureActorCastSkillEvent = evt as AdventureActorCastSkillEvent;
			if (adventureActorCastSkillEvent.sender is MonsterAdventureActor monsterAdventureActor && monsterAdventureActor == _actor && !_achievementTypeFinish_4 && checkSkillId_4.Contains(adventureActorCastSkillEvent.skillEventInfo.skillId))
			{
				_canCheck_4 = true;
			}
		}

		public void OnUpdate()
		{
			if (_canCheck_4)
			{
				if (_actor.logicVariable.GetLogicTagToggle("slideFinish"))
				{
					_checkTime_4 += _actor.LogicDeltaTime;
					if (!(_checkTime_4 >= checkTime_4))
					{
						return;
					}
					if (!_forceFailed_4)
					{
						bool flag = false;
						for (int i = 0; i < checkTeammateIndex_4.Count; i++)
						{
							int teammateIdByIndex = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, checkTeammateIndex_4[i]);
							if (ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex).Count > 0)
							{
								flag = true;
								break;
							}
						}
						if (MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.isRaceStarTower && !flag)
						{
							_achievementTypeFinish_4 = SetAchievementState(GameEnum.questCompleteCondClient.ShiLaiMuWang_004);
						}
					}
					_canCheck_4 = false;
				}
				else
				{
					_checkTime_4 = 0;
				}
			}
			else
			{
				_checkTime_4 = 0;
			}
		}

		private void OnCastSkillEnd(IEvent evt)
		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = evt as AdventureActorCastSkillEndEvent;
			if (!_achievementTypeFinish_4 && checkSkillId_4.Contains(adventureActorCastSkillEndEvent.skillEventInfo.skillId) && !_actor.logicVariable.GetLogicTagToggle("slideFinish"))
			{
				_canCheck_4 = false;
			}
			if (!_achievementTypeFinish_5 && checkSkillId_5.Contains(adventureActorCastSkillEndEvent.skillEventInfo.skillId) && !_actor.logicVariable.GetLogicTagToggle("slideFinish"))
			{
				_achievementTypeFinish_5 = SetAchievementState(GameEnum.questCompleteCondClient.ShiLaiMuWang_005);
			}
		}

		private void OnActorDied(AdventureActorDiedEvent diedEvent)
		{
			if (!(diedEvent.actor is MonsterAdventureActor monsterAdventureActor) || !(diedEvent.killer is MonsterAdventureActor) || _achievementTypeFinish_4 || !_canCheck_4 || _forceFailed_4)
			{
				return;
			}
			for (int i = 0; i < checkTeammateIndex_4.Count; i++)
			{
				int teammateIdByIndex = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, checkTeammateIndex_4[i]);
				List<LogicEntity> list = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex);
				if (((list.Count > 0) ? (list[0] as MonsterAdventureActor) : null) == monsterAdventureActor)
				{
					_forceFailed_4 = true;
					break;
				}
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}
	}
	public class Skill_AlertMovement : SkillSimpleBase
	{
		private TSVector2 targetPOS;

		private LogicEntity target;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			targetPOS = MoveTargetPOS();
			target = GetTarget();
			AimAtTarget(target, 180f);
			MoveToPosition(targetPOS, 0.5, AdventureActor.MovementMode.Walk, 2f);
			yield return WaitMoveStatus();
			CancelAim();
		}

		private TSVector2 MoveTargetPOS()
		{
			TSVector2 zero = TSVector2.zero;
			TSVector2 entityPosition = GetEntityPosition(GetCurrentPlayer());
			TSVector2 position = GetPosition();
			FP radius = 12;
			FP innerRadius = 9;
			FP angle = 60;
			FP tSVectToAngle = GetTSVectToAngle(position - entityPosition, 0);
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, tSVectToAngle);
			for (int i = 0; i < 5; i++)
			{
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			for (int j = 0; j < 5; j++)
			{
				FP fP = ((!(GetRandomValue(0, 1) < 0.5)) ? 1 : (-1));
				tSVectToAngle = 12;
				angle = 9;
				innerRadius = 15;
				radius = GetTSVectToAngle(entityPosition - position, 40 * fP);
				shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), tSVectToAngle, angle, innerRadius, radius);
				zero = GetShapeRandomPoint(shapeData, _actor);
				if (QueryPositionReachable(_actor, zero) && Distance(entityPosition, zero) >= 4)
				{
					return zero;
				}
			}
			return TSVector2.zero;
		}

		protected LogicEntity GetTarget()
		{
			LogicEntity result = GetAttackTarget();
			if (!CheckTargetIsValid(result))
			{
				result = GetCurrentPlayer();
			}
			return result;
		}
	}
	public class Skill_Assault_LD : SkillSimpleBase
	{
		private static readonly string _AssaultCombo_L = "Assault_Long";

		private static readonly int AssaultKey_L = 1;

		private static readonly string _AssaultCombo_S = "Assault_Short";

		private static readonly int AssaultKey_S = 2;

		private static readonly string _DiffusionCombo = "DiffusionBubble";

		private static readonly int DiffusionComboIndex = 4;

		private static readonly FP THOfLongDist = 8;

		private static readonly FP THOfShortDist = 4;

		private static readonly FP Speed_L = 6;

		private static readonly FP Distance_L = 18;

		private static readonly FP Distance_S = 12;

		private static readonly FP Speed_S = 6;

		private static readonly FP F2FDist = 3;

		private static readonly FP THOfDist = 9;

		private static readonly FP AngleLimit = 180;

		private static LogicEntity Target;

		private static FP StopLoop;

		private static readonly int DashIndex = 5;

		private static FP DashSpeed;

		private static FP DashDistance;

		private static readonly bool ActionSwitch = true;

		private static readonly bool AngleSwitch = true;

		private static readonly bool NotChangeForward = true;

		private static readonly FP TurnTime = 99;

		private static FP RelativeDist;

		protected override IEnumerator DoMainLogic()
		{
			Target = GetAttackTarget(isUpToDate: true);
			if (!CheckTargetIsValid(Target))
			{
				InterruptSkill();
			}
			RelativeDist = Distance(GetPosition(), GetEntityPosition(Target));
			if (RelativeDist >= THOfLongDist)
			{
				BeginAttack(AssaultKey_L, _AssaultCombo_L, flushInputedKeys: false, forceInterruptAttack: true);
				DashSpeed = Speed_L;
				DashDistance = Distance_L;
				StopLoop = Distance_L / Speed_L * 0.9;
			}
			else if (RelativeDist < THOfShortDist && RelativeDist >= F2FDist)
			{
				BeginAttack(AssaultKey_S, _AssaultCombo_S, flushInputedKeys: false, forceInterruptAttack: true);
				DashSpeed = Speed_S;
				DashDistance = Distance_S;
				StopLoop = Distance_L / Speed_L * 0.8;
			}
			else
			{
				BeginAttack(AssaultKey_S, _AssaultCombo_S, flushInputedKeys: false, forceInterruptAttack: true);
				DashSpeed = 2;
				DashDistance = 1.8;
				StopLoop = DashDistance / DashSpeed;
			}
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			Target = GetAttackTarget(isUpToDate: true);
			if (!CheckTargetIsValid(Target))
			{
				Target = _actor;
			}
			BeginDashActorForward(DashIndex, DashSpeed, DashDistance, AngleLimit, ActionSwitch, AngleSwitch, NotChangeForward, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			WaitLookAt_NoWait(Target, TurnTime, AngleLimit);
			yield return WaitTime(StopLoop);
			CancelAttack();
			yield return WaitDashFinish();
			StopWaitLookAt();
			yield return WaitDashFinish();
			Target = GetAttackTarget();
			if (Target == null)
			{
				Target = _actor;
			}
			RelativeDist = Distance(GetPosition(), GetEntityPosition(Target));
			if (RelativeDist >= THOfDist)
			{
				BeginAttack(DiffusionComboIndex, _DiffusionCombo, flushInputedKeys: false, forceInterruptAttack: true);
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Assault_Long_LD : SkillSimpleBase
	{
		private int branch;

		private const int diffTag1 = 500810000;

		private const int diffTag2 = 500810001;

		private const int diffTag3 = 500810002;

		private static readonly string _AssaultCombo_L = "Assault_Long";

		private static readonly int AssaultKey_L = 1;

		private FP DashSpeed;

		private FP DashDistance = 99;

		private static readonly FP AngleLimit = 360;

		private static LogicEntity Target;

		private static FP StopLoop;

		private int times;

		private static readonly int DashIndex = 5;

		private static readonly bool ActionSwitch = true;

		private static readonly bool AngleSwitch = true;

		private readonly bool NotChangeForward = true;

		private static readonly FP TurnTime = 99;

		private static FP RelativeDist;

		protected override IEnumerator DoMainLogic()
		{
			List<BuffEntity> buffFromTarget = GetBuffFromTarget(_actor, 0, 500810000);
			if (buffFromTarget.Count != 0)
			{
				switch (buffFromTarget[0].buffConfig.Id)
				{
				case 500810000:
					branch = 0;
					break;
				case 500810001:
					branch = 1;
					break;
				case 500810002:
					branch = 2;
					break;
				default:
					branch = 2;
					break;
				}
			}
			else
			{
				branch = 2;
			}
			switch (branch)
			{
			case 0:
				DashSpeed = 15;
				times = 2;
				break;
			case 1:
				DashSpeed = 18;
				times = 2;
				break;
			case 2:
				DashSpeed = 20;
				times = 3;
				break;
			default:
				DashSpeed = 20;
				times = 3;
				break;
			}
			Target = GetAttackTarget(isUpToDate: true);
			if (!CheckTargetIsValid(Target))
			{
				Target = GetCurrentPlayer();
			}
			BeginAttack(AssaultKey_L, _AssaultCombo_L, flushInputedKeys: false, forceInterruptAttack: true);
			StopLoop = DashDistance / DashSpeed * 0.9;
			FP clampValue = 3;
			DashSpeed = Mathf.Clamp((float)DashSpeed, 9f, 1000f);
			clampValue = Mathf.Clamp((float)clampValue, (float)clampValue, 7f);
			TSVector2 targetPOS = GetEntityPosition(GetCurrentPlayer());
			targetPOS.x = Mathf.Clamp((float)targetPOS.x, (float)(-clampValue), (float)clampValue);
			targetPOS.y = Mathf.Clamp((float)targetPOS.y, (float)(-clampValue), (float)clampValue);
			Skill_Assault_Long_LD skill_Assault_Long_LD = this;
			TSVector2 position = GetPosition();
			FP tSVectToAngle = GetTSVectToAngle(targetPOS - GetPosition(), 0);
			skill_Assault_Long_LD.PlayEffect("fx_warning_dash_7_6x25", 1f, default(FP), position, tSVectToAngle);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			SetCloseBlockEnable();
			for (int i = 0; i < times; i++)
			{
				BeginDash(DashIndex, targetPOS - GetPosition(), DashSpeed, DashDistance * 2, AngleLimit, ActionSwitch, AngleSwitch, NotChangeForward, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false, 0.3);
				yield return WaitDashFinish();
				clampValue += (FP)1;
				DashSpeed *= (FP)0.6;
				DashSpeed = Mathf.Clamp((float)DashSpeed, 9f, 1000f);
				clampValue = Mathf.Clamp((float)clampValue, (float)clampValue, 7f);
				targetPOS = GetEntityPosition(GetCurrentPlayer());
				targetPOS.x = Mathf.Clamp((float)targetPOS.x, (float)(-clampValue), (float)clampValue);
				targetPOS.y = Mathf.Clamp((float)targetPOS.y, (float)(-clampValue), (float)clampValue);
			}
			CancelAttack();
			SetCloseBlockDisable();
			WaitLookAt_NoWait(Target, 0.1, 999);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Burst : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] actionKeys_dodge = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.F };

		private readonly ComboInputBuffer.ActionKey[] actionKeys_around = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.G };

		private readonly ComboInputBuffer.ActionKey[] actionKeys_summon = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.H };

		private readonly ComboInputBuffer.ActionKey[] actionKeys_burst = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.H,
			ComboInputBuffer.ActionKey.A
		};

		private readonly ComboInputBuffer.ActionKey[] actionKeys_weak = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.H,
			ComboInputBuffer.ActionKey.B
		};

		private readonly TSVector2 centerPoint = TSVector2.zero;

		private readonly FP rotateSpeed = 180;

		private readonly FP dodgeDuration = 1;

		private readonly FP aroundDuration = 10;

		private readonly FP summonDuration = 10;

		private readonly int summonMonsterId = 11;

		private readonly string monsterBulletAlias = "";

		private readonly string monsterBulletTag = "monsterBulletTag";

		private readonly List<AreaEffectInfo> burstAreaEffects = new List<AreaEffectInfo>
		{
			new AreaEffectInfo("areaEffect1", 2),
			new AreaEffectInfo("areaEffect2", 2),
			new AreaEffectInfo("areaEffect3", 2)
		};

		private readonly FP weakDuration = 5;

		private bool _gotoCenterFinish;

		private Dodge _dodge;

		private bool _dodgeFinish;

		private int bulletCount;

		protected override void OnSkillEnable()
		{
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
		}

		protected override void OnSkillDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			_gotoCenterFinish = false;
			_dodge?.Interrupte();
			_dodgeFinish = false;
			bulletCount = 0;
		}

		protected override IEnumerator DoMainLogic()
		{
			_actor.EnableImmuneControl();
			Skill_Burst skill_Burst = this;
			TSVector2 targetPos = centerPoint;
			FP fP = rotateSpeed;
			yield return skill_Burst.BeginLookAtByPos(targetPos, default(FP), fP);
			BeginAttack(1, actionKeys_dodge, flushInputedKeys: true);
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			TSVector2 normalized = (centerPoint - _actor.tsTransform.Position).normalized;
			FP distance = ILRuntimeAPI.CalcDistanceBetweenActorAndPosition(_actor, centerPoint, calcDistanceWithoutEntityRadius: true);
			_dodge.Begin(_actor, normalized, dodgeDuration, distance, delegate
			{
				_dodgeFinish = true;
			}, comboWithAttack: true);
			yield return _actor.StartLogicCoroutine(waitDodgeFinish());
			CancelAttack();
			_actor.tsTransform.Forward = new TSVector2(0, -1);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			BeginAttack(2, actionKeys_around, flushInputedKeys: true);
			yield return WaitTime(aroundDuration);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			BeginAttack(3, actionKeys_summon, flushInputedKeys: true);
			SetBattleOutEnable();
			yield return WaitTime(summonDuration);
			bool burst = false;
			List<LogicEntity> list = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(summonMonsterId);
			if (list != null && list.Count > 0)
			{
				burst = true;
				bulletCount = 0;
				foreach (LogicEntity item in list)
				{
					(item as AdventureActor).DestroySelf();
					Skill_Burst skill_Burst2 = this;
					string bulletAlias = monsterBulletAlias;
					TSVector2 position = item.tsTransform.Position;
					FP positionY = item.tsTransform.PositionY;
					FP range = 0;
					TSVector2 targetPosition = centerPoint;
					if (skill_Burst2.Shoot(bulletAlias, position, positionY, range, default(TSVector2), AimType.Position, BulletDirectionType.BulletToTarget, targetPosition) != 0L)
					{
						bulletCount++;
					}
				}
				yield return _actor.StartLogicCoroutine(waitBulletFinish());
			}
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetBattleOutDisable();
			if (burst)
			{
				BeginAttack(4, actionKeys_burst, flushInputedKeys: true);
				foreach (AreaEffectInfo burstAreaEffect in burstAreaEffects)
				{
					PlayAreaEffect(burstAreaEffect.areaEffectAlias, _actor.tsTransform.Position, _actor.tsTransform.Rotation);
					yield return WaitTime(burstAreaEffect.interval);
				}
			}
			else
			{
				BeginAttack(4, actionKeys_weak, flushInputedKeys: true);
				yield return WaitTime(weakDuration);
				CancelAttack();
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
			_actor.DisableImmuneControl();
		}

		private IEnumerator waitDodgeFinish()
		{
			while (!_dodgeFinish)
			{
				yield return null;
			}
		}

		private IEnumerator waitBulletFinish()
		{
			while (bulletCount > 0)
			{
				yield return null;
			}
		}

		private void OnBulletFinish(IEvent iEvent)
		{
			if ((iEvent as AdventureBulletFinishEvent).tag.Equals(monsterBulletTag))
			{
				bulletCount--;
			}
		}
	}
	public class AreaEffectInfo
	{
		public string areaEffectAlias;

		public FP interval;

		public AreaEffectInfo(string areaEffectAlias, FP interval)
		{
			this.areaEffectAlias = areaEffectAlias;
			this.interval = interval;
		}
	}
	public class Skill_Burst_LD : SkillSimpleBase
	{
		private readonly int mSlime = 5;

		private readonly string mSlimeCountTag = "mSlimeCount";

		private readonly int sSlime = 10;

		private readonly string sSlimeCountTag = "sSlimeCount";

		private const string aiTypeEasy = "Easy";

		private const string aiTypeNormal = "Normal";

		private const string aiTypeHard = "Hard";

		private readonly TSVector2 Origin = new TSVector2(0, 0);

		private readonly TSVector2 OriginLookAt = new TSVector2(0, -1);

		private readonly string SlidingAction = "Slide";

		private readonly int AttackIndex = 2;

		private readonly int AttackPlayTime = 1;

		private FP LoopTime;

		private readonly FP LoopFinishTime = 3.2;

		private readonly string DisappearedAction = "Disappeared_BurstStage";

		private readonly int DisappearedIndex = 3;

		private readonly FP SplitWaitTime = 16;

		private readonly string WeaknessAction = "Weakness";

		private readonly int WeaknessIndex = 6;

		private readonly string FxAlias = "fx_m50081_base_skill6_appear";

		private readonly string BulletAlias = "Slime_BurstThrow_Bullet";

		private readonly bool AlignShoot;

		private readonly FP AlignShootDelay = 0;

		private readonly int BulletCount = 1;

		private readonly FP Duration = 0;

		private TSVector2 ShootPosition;

		private readonly FP ShootPositionY = 1;

		private TSVector2 MultiShootDirection;

		private readonly FP BulletDirectionOffset = 0;

		private readonly FP Angle = 0;

		private readonly FP Radius = 0;

		private readonly FP InnerRadius = 2;

		private readonly string SummonBullet = "Slime_L_Born_BOSS";

		private readonly int SummonCount = 5;

		private readonly FP SummonRadius = 11;

		private readonly FP SummonInnerRadius = 0;

		private List<LogicEntity> SummonList = new List<LogicEntity>();

		private readonly string BurstAction = "Burst";

		private readonly int BurstIndex = 4;

		private int BurstTime;

		private readonly FP BurstFinishTime = 5;

		private readonly string BurstBulletAlias = "Burst_DiffusionBubble";

		private readonly bool BurstAlignShoot = true;

		private readonly FP BurstAlignShootDelay = 0;

		private readonly int BurstBulletCount = 36;

		private readonly FP BurstDuration = 0;

		private TSVector2 BurstShootPosition;

		private readonly FP BurstShootPositionY = 0;

		private TSVector2 BurstMultiShootDirection;

		private readonly FP BurstBulletDirectionOffset = 0;

		private readonly FP BurstRadius = 0;

		private readonly FP BurstInnerRadius = 0;

		private int AttackTime;

		private int AttackTime_Weakness;

		private FP Time;

		private int MateNUB;

		protected override void OnSkillEnable()
		{
			SetCloseBlockEnable();
			SetImmuneControlEnable();
			SetLockToughnessEnable();
			SetLogicTagToggleValue(_actor, "isMaster", value: true);
			SetLogicTagToggleValue(_actor, "slideFinish", value: false);
			SetLogicTagToggleValue(_actor, "IsBurst", value: false);
			SetLogicTagFpValue(_actor, mSlimeCountTag, 0);
			SetLogicTagFpValue(_actor, sSlimeCountTag, 0);
			SetBlockPriorityToStatic();
			SummonList.Clear();
		}

		protected override void OnSkillDisable()
		{
			SetLogicTagToggleValue(_actor, "slideFinish", value: false);
			AttackTime = 0;
			Time = 0;
			MateNUB = 0;
			LoopTime = 0;
			BurstTime = 0;
			RemoveBuffFromTarget(_actor, 50071051);
			InterruptLockToughness();
			ResetBlockPriority();
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginLookAtByPos(Origin, 1, 420);
			yield return WaitTime(1);
			MoveToPosition(TSVector2.zero, 0.1, AdventureActor.MovementMode.Run, 5f, _stopDisIgnoreRadius: false);
			yield return WaitMoveStatus();
			BeginLookAtByPos(OriginLookAt, 0.6, 420);
			yield return WaitTime(0.6);
			yield return StartCor(Shooting());
			SetLogicTagToggleValue(_actor, "slideFinish", value: true);
			yield return StartCor(Split());
			yield return StartCor(Result());
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == AttackIndex)
			{
				AttackTime++;
				if (AttackTime >= AttackPlayTime)
				{
					CancelAttack();
				}
			}
			else if (comboIndex == WeaknessIndex)
			{
				AttackTime_Weakness++;
				if (AttackTime_Weakness >= 2)
				{
					CancelAttack();
				}
			}
		}

		private IEnumerator Shooting()
		{
			BeginAttack(AttackIndex, SlidingAction, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayEffect("fx_common_base_charge_fire_actor", 1f, 2f, GetPosition(), default(FP), 3f);
			LoopTime = 0;
			MultiShootDirection = Origin - GetPosition();
			while (LoopTime < LoopFinishTime * AttackPlayTime)
			{
				ShootPosition = GetPosition();
				FanMultipleShoot(BulletAlias, AdventureWeapon.MultipleShootStyle.FromCenterToSide, AlignShoot, AlignShootDelay, BulletCount, Duration, ShootPosition, ShootPositionY, MultiShootDirection, BulletDirectionOffset, AimType.Default, BulletDirectionType.ActorToBullet, Angle, Radius, InnerRadius);
				MultiShootDirection = RotateTo(MultiShootDirection, 11.5);
				yield return WaitTime(0.1);
				LoopTime += (FP)0.1;
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
			if (Distance(GetPosition(), TSVector2.zero) >= 1.5)
			{
				MoveToPosition(TSVector2.zero, 0.05);
				yield return WaitMoveStatus();
				yield return BeginLookAtByPos(new TSVector2(0, -10), 0, 720);
			}
		}

		private IEnumerator Split()
		{
			BeginAttack(DisappearedIndex, DisappearedAction, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.3);
			ShootPosition = GetPosition();
			CircleMultipleShoot(SummonBullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, AlignShoot, AlignShootDelay, SummonCount, Duration, ShootPosition, ShootPositionY, MultiShootDirection, BulletDirectionOffset, AimType.Default, BulletDirectionType.ActorToBullet, SummonRadius, SummonInnerRadius);
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			SetSearchedImmunityEnable();
			SetBattleOutEnable();
			yield return WaitTime(2);
			int aiType = GetAiType();
			bool loopSwitch = true;
			while (Time <= SplitWaitTime && loopSwitch)
			{
				int num = (int)(long)GetLogicTagFpValue(_actor, mSlimeCountTag);
				int num2 = (int)(long)GetLogicTagFpValue(_actor, sSlimeCountTag);
				switch (aiType)
				{
				case 0:
				case 1:
					if (num >= mSlime)
					{
						loopSwitch = false;
					}
					else if (GetLogicTagToggleValue(_actor, "IsBurst"))
					{
						yield return WaitTime(1.3);
						loopSwitch = false;
					}
					break;
				case 2:
					if (num >= mSlime && num2 >= sSlime)
					{
						loopSwitch = false;
					}
					else if (GetLogicTagToggleValue(_actor, "IsBurst"))
					{
						yield return WaitTime(1.3);
						loopSwitch = false;
					}
					break;
				default:
					if (num >= mSlime)
					{
						loopSwitch = false;
					}
					else if (GetLogicTagToggleValue(_actor, "IsBurst"))
					{
						yield return WaitTime(1.3);
						loopSwitch = false;
					}
					break;
				}
				yield return WaitTime(0.2);
				Time += (FP)0.2;
				if (Time > SplitWaitTime)
				{
					ClearMates();
					SetLogicTagToggleValue(_actor, "IsBurst", value: true);
				}
			}
			yield return WaitTime(0.5);
		}

		private IEnumerator Result()
		{
			SetBattleOutDisable();
			SetCloseBlockDisable();
			if (GetLogicTagToggleValue(_actor, "IsBurst"))
			{
				CancelAttack();
				yield return WaitCombo(ComboAttackType.isComboFinish);
				BeginAttack(BurstIndex, BurstAction, flushInputedKeys: true, forceInterruptAttack: true);
				SetSearchedImmunityDisable();
				SetImmuneControlDisable();
				InterruptLockToughness();
				yield return WaitCombo(ComboAttackType.isAnticipationEnd);
				PlayEffect("fx_common_base_charge_fire_actor", 1f, 2f, GetPosition(), default(FP), 3f);
				BurstShootPosition = GetPosition();
				BurstMultiShootDirection = GetForward();
				while (BurstTime <= BurstFinishTime)
				{
					CircleMultipleShoot(BurstBulletAlias, AdventureWeapon.MultipleShootStyle.FromCenterToSide, BurstAlignShoot, BurstAlignShootDelay, BurstBulletCount, BurstDuration, BurstShootPosition, BurstShootPositionY, BurstMultiShootDirection, BurstBulletDirectionOffset, AimType.Default, BulletDirectionType.ActorToBullet, BurstRadius, BurstInnerRadius);
					BurstTime++;
					yield return WaitTime(1);
				}
				CancelAttack();
			}
			else
			{
				PlayEffect(FxAlias, 1f, default(FP), GetPosition(), GetRotation());
				yield return WaitTime(0.35);
				BeginAttack(WeaknessIndex, WeaknessAction, flushInputedKeys: true, forceInterruptAttack: true);
				SetSearchedImmunityDisable();
				SetImmuneControlDisable();
				InterruptLockToughness();
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void ClearMates()
		{
			List<LogicEntity> targetsByFaction = GetTargetsByFaction(isFriend: true);
			if (targetsByFaction.Count != 0)
			{
				for (int i = 0; i < targetsByFaction.Count; i++)
				{
					PlayEffect("fx_50071_base_die", 1f, default(FP), GetEntityPosition(targetsByFaction[i]), GetEntityAngle(targetsByFaction[i]));
				}
				ClearActors(targetsByFaction);
				SetLogicTagToggleValue(_actor, "IsBurst", value: true);
			}
		}

		private int GetAiType()
		{
			int num = 0;
			return GetMonsterTagValue(_actor, 1) switch
			{
				"Easy" => 0, 
				"Normal" => 1, 
				"Hard" => 2, 
				_ => 0, 
			};
		}
	}
