			int DashSpeed = 60;
			BeginAttack(SkillBaseXingXing.DashChargeIndex, SkillBaseXingXing.DashChargeJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
