			CancelAttack();
			SetCloseBlockEnable();
			BeginAttack(SkillBaseXingXing.DashATKIndex, SkillBaseXingXing.DashATKJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			target = GetTarget();
			targetPOS = GetEntityPosition(target);
