	public class Skill_EarthQuake_LD : SkillBaseXingXing
	{
		private static LogicEntity target;

		private int Times;

		private List<FP> _RelativeDIST = new List<FP>();

		private readonly int CrawlStartIndex = 2;

		private readonly string CrawlStartKey = "Crawl_Start";

		private readonly int CrawlEndIndex = 3;

		private readonly string CrawlEndKey = "Crawl_End";

		private List<long> _ATKLFx = new List<long>();

		protected override void OnSkillEnable()
		{
			_RelativeDIST.Clear();
			Times = 0;
		}

		protected override void OnSkillDisable()
		{
			if (_isDisableByLostControl)
			{
				Parallel.beDisable = true;
			}
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[i]);
				}
			}
			SetCloseBlockDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			BeginAttack(CrawlStartIndex, CrawlStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.8, 225);
			yield return WaitTime(1.2);
			BeginAttack(CrawlEndIndex, CrawlEndKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayEffect(SkillBaseXingXing.WarningFx, 1f, 2f, GetPosition(), default(FP), 3.5f);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == CrawlEndIndex)
			{
				Times++;
				if (Times > 2)
				{
					StopDash();
					CancelAttack();
				}
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (new List<string> { "MoveBegin", "MoveFinish", "TurnBegin", "TurnFinish", "Attack_L", "Attack_R", "warningFxGround_R", "warningFxGround_L" }.Contains(eventName))
			{
				TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(-1.4, 2));
				TSVector2 tSVector2 = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(1.5, 1.5));
				FP fP = 3;
				FP fP2 = 60;
				switch (eventName)
				{
				case "MoveBegin":
				{
					FP distance = 99;
					FP angleLimit = 0;
					BeginDash(SkillBaseXingXing.earthQuakeDashIndex, GetForward(), fP, distance, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
					break;
				}
				case "MoveFinish":
					StopDash();
					break;
				case "TurnBegin":
					BeginLookAt_NotWait(target, 99, 360);
					break;
				case "TurnFinish":
					StopLookAt();
					break;
				case "Attack_L":
				{
					FP radius = 3;
					Damage(tSVector, radius);
					break;
				}
				case "Attack_R":
				{
					FP radius = 2.6;
					Damage(tSVector2, radius);
					break;
				}
				case "warningFxGround_R":
				{
					FP fP3 = 19;
					TSVector2 position = TransLocalPosToWorldPos(tSVector2, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				case "warningFxGround_L":
				{
					FP fP3 = 21;
					TSVector2 position = TransLocalPosToWorldPos(tSVector, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				}
			}
		}

		private void Damage(TSVector2 position, FP radius)
		{
			FP innerRadius = 0;
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), radius, innerRadius);
			HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 3);
			AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011061, 0.5, HitBox.HurtAnimType.Small);
		}

		private long WarningFxGround(TSVector2 position, float playbackSpeed, float spawnSize)
		{
			return PlayEffect("fx_common_base_Fire_YuJing_circular_3", playbackSpeed, default(FP), position, default(FP), spawnSize);
		}
	}
	public class Skill_EarthShatter : SkillBaseXingXing
	{
		private readonly string playWarningEvent = "PlayWarningFx";

		private readonly string stopWarningEvent = "StopWarningFx";

		private long warningFxID;

		private readonly string warningFx = "fx_m50011_base_skill3_atk_ground_crack_common";

		private LogicEntity target;

		private TSVector2 movePos;

		protected override void OnSkillDisable()
		{
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == SkillBaseXingXing.ESATKIndex && eventName == playWarningEvent)
			{
				string fxAlias = warningFx;
				TSVector2 position = GetPosition();
				FP entityAngle = GetEntityAngle(_actor);
				warningFxID = PlayEffect(fxAlias, 1f, default(FP), position, entityAngle);
			}
			if (comboIndex == SkillBaseXingXing.ESATKIndex && eventName == stopWarningEvent)
			{
				StopEffect(warningFxID);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, GetEntityPosition(target), default(FP), default(FP), 12, 7.5);
			if (GetDestination(shapeData, out var destination))
			{
				movePos = destination;
				yield return StartCor(Jump());
			}
			yield return StartCor(Attack());
		}

		private bool GetDestination(DeterministicShape shape, out TSVector2 destination)
		{
			bool result = false;
			destination = TSVector2.zero;
			TSVector2 position = GetPosition();
			FP fP = 15;
			for (int i = 0; i <= 10; i++)
			{
				destination = GetShapeRandomPoint(shape, _actor, isReachable: true);
				if (fP <= Distance(position, destination))
				{
					result = true;
					break;
				}
			}
			return result;
		}

		private IEnumerator Jump()
		{
			TSVector2 selfPos = GetPosition();
			FP dashDist = Distance(selfPos, movePos);
			SetCloseBlockEnable();
			BeginAttack(SkillBaseXingXing.ESJumpIndex, SkillBaseXingXing.ESJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(0.45);
			BeginDash(SkillBaseXingXing.jumpIndex, movePos - selfPos, dashDist / 0.4, dashDist, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false, 0.2);
			yield return WaitTime(0.2);
			BeginLookAt_NotWait(target, 0.2, 675);
			yield return WaitDashFinish();
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetCloseBlockDisable();
		}

		private IEnumerator Attack()
		{
			BeginAttack(SkillBaseXingXing.ESATKIndex, SkillBaseXingXing.ESATKKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.3, 200);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Jump_LD : SkillBaseXingXing
	{
		private readonly FP INTR01 = 0.3;

		private LogicEntity Target;

		private TSVector2 TargetPOS;

		private bool breakOff;

		private string WarningBullet = "WarningBullet";

		private bool AlignShoot_WB = true;

		private readonly FP AlignShootDelay_WB = 0;

		private int BulletCount_WB = 1;

		private readonly FP Duration_WB = 0;

		private TSVector2 ShootPOS_WB;

		private readonly FP ShootPOSY_WB = 0;

		private TSVector2 MultishootDirectio_WB;

		private readonly FP BulletDirectionOffset_WB = 0;

		private FP Angle_WB = 0;

		private readonly FP Radius_WB = 0;

		private readonly FP InnerRadius_WB = 0;

		private List<long> _BulletIDList = new List<long>();

		private string WarningBulletArea = "WarningBulletArea";

		private List<long> _AreaEffectFx = new List<long>();

		protected override void OnSkillEnable()
		{
			SetLogicTagToggleValue(_actor, "DropAttackSwitch", value: false);
		}

		protected override void OnSkillDisable()
		{
			SetLogicTagToggleValue(_actor, "DropAttackSwitch", value: false);
			_BulletIDList.Clear();
			ClearShootBulletIdList();
			if (breakOff)
			{
				SetUnparalleledDisable();
				SetCloseBlockDisable();
				SetSearchedImmunityDisable();
			}
			if (_AreaEffectFx.Count > 0)
			{
				for (int i = 0; i < _AreaEffectFx.Count; i++)
				{
					StopAreaEffect(_AreaEffectFx[i]);
				}
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			Target = GetCurrentPlayer();
			BeginAttack(SkillBaseXingXing.DropIndex, SkillBaseXingXing.DropAttack);
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			yield return WaitTime(0.5);
			SetHideModelEnable();
			SetUnparalleledEnable();
			SetCloseBlockEnable();
			SetSearchedImmunityEnable();
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(INTR01);
			StartCor(Warning());
			yield return StartCoroutine(Attack());
		}

		protected IEnumerator Attack()
		{
			for (int i = 0; i < 30; i++)
			{
				if (GetLogicTagToggleValue(_actor, "DropAttackSwitch"))
				{
					break;
				}
				if (i > 29)
				{
					break;
				}
				yield return WaitTime(0.1);
			}
			if (_BulletIDList != null && _BulletIDList.Count > 0)
			{
				TargetPOS = GetBulletPosition(_BulletIDList[0]);
			}
			else
			{
				TargetPOS = TSVector2.zero;
			}
			CancelAttack();
			Teleport(TargetPOS);
			SetHideModelDisable();
			BeginLookAt_NotWait(Target, 0.1, 999);
