		protected void UpdateEffectTag(bool state)
		{
			if (state)
			{
				SetLogicTagToggleValue(_actor, "IsEnhanced", value: true);
			}
			else
			{
				SetLogicTagToggleValue(_actor, "IsEnhanced", value: false);
			}
		}

		protected IEnumerator Monsterteleport()
		{
			InterruptAttack();
			SetLogicTagFpValue(_actor, "ReleaseInterval", 1);
			TSVector2 position = TeleportSelectionPos();
			SetCloseBlockEnable();
			long hidingFx = PlayEffect("fx_common_loop_hiding");
			SetImmuneControlEnable();
			SkillScript_Base skillScript_Base = this;
			TSVector2 position2 = GetPosition();
			FP tSVectToAngle = GetTSVectToAngle(GetForward(), 0);
			skillScript_Base.PlayEffect("fx_m50011_base_disappear_light", 1.5f, default(FP), position2, tSVectToAngle);
			SkillScript_Base skillScript_Base2 = this;
			position2 = GetPosition();
			tSVectToAngle = GetTSVectToAngle(GetForward(), 0);
			skillScript_Base2.PlayEffect("fx_m50011_base_change_light", 1f, default(FP), position2, tSVectToAngle);
			long substituteFx = PlayEffect("fx_m50011_loop_substitute_light");
			MoveToPosition(position, 0.3, AdventureActor.MovementMode.Run, 2f);
			yield return WaitMoveStatus();
			BeginLookAt_NotWait(GetCurrentPlayer(), 0.1, 18600);
			yield return WaitTime(0.2);
			StopEffect(substituteFx);
			SkillScript_Base skillScript_Base3 = this;
			position2 = GetPosition();
			tSVectToAngle = GetTSVectToAngle(GetForward(), 0);
			skillScript_Base3.PlayEffect("fx_m50011_base_recover_light", 1f, default(FP), position2, tSVectToAngle);
			SkillScript_Base skillScript_Base4 = this;
			position2 = GetPosition();
			tSVectToAngle = GetTSVectToAngle(GetForward(), 0);
			skillScript_Base4.PlayEffect("fx_m50011_base_appear_light", 1.5f, default(FP), position2, tSVectToAngle);
			SetCloseBlockDisable();
			StopEffect(hidingFx);
			SetImmuneControlDisable();
			SetLogicTagToggleValue(_actor, "AttackTip", value: true);
			yield return null;
		}

		protected TSVector2 TeleportSelectionPos()
		{
			TSVector2 tSVector = TSVector2.zero;
			TSVector2 position = GetPosition();
			TSVector2 entityPosition = GetEntityPosition(GetCurrentPlayer());
			_ = TSVector2.zero;
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), Distance(position, entityPosition) + 2, Distance(position, entityPosition), 90, GetTSVectToAngle(entityPosition - position, 0));
			for (int i = 0; i < 5; i++)
			{
				tSVector = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				if (QueryPositionReachable(_actor, tSVector))
				{
					break;
				}
				if (i != 4)
				{
					continue;
				}
				shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, entityPosition, default(FP), default(FP), 3, 1.5);
				for (int j = 0; j < 5; j++)
				{
					tSVector = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
					if (QueryPositionReachable(_actor, tSVector))
					{
						break;
					}
				}
				tSVector = entityPosition;
				break;
			}
			return tSVector;
		}

		protected bool TeleportCondition()
		{
			FP logicTagFpValue = GetLogicTagFpValue(_actor, "ReleaseInterval");
			bool result = false;
			if (logicTagFpValue <= 0)
			{
				return true;
			}
			SetLogicTagFpValue(_actor, "ReleaseInterval", logicTagFpValue - 1);
			return result;
		}

		protected void PlayWarningFx()
		{
			if (GetLogicTagToggleValue(_actor, "AttackTip"))
			{
				PlayEffect(WarningFx, 1f, 1.5, GetPosition(), default(FP), 2.5f);
				SetLogicTagToggleValue(_actor, "AttackTip", value: false);
			}
		}

		protected int GetAiType()
		{
			int num = 0;
			string monsterTagValue = GetMonsterTagValue(_actor, 1);
			if (!(monsterTagValue == "Easy"))
			{
				if (monsterTagValue == "Hard")
				{
					return 1;
				}
				return 0;
			}
			return 0;
		}

		protected LogicEntity GetTarget()
		{
			LogicEntity logicEntity = null;
			if (CheckTargetIsValid(GetAttackTarget(isUpToDate: true)))
			{
				return GetAttackTarget(isUpToDate: true);
			}
			return GetCurrentPlayer();
		}
	}
	public class Skill_Attack_L_LD : SkillScript_Base
	{
		private LogicEntity target;

		private int aiType;

		private static readonly string WarningFx_ATKL = "fx_m50011_base_skill4_hint_L_light";

		private static readonly string Charge_ATKL = "fx_m50011_loop_skill4_charge_Rhand_L_light";

		private static readonly string hitFx = "fx_common_hit_light_strike";

		private List<long> _ATKLFx = new List<long>();

		protected override void OnSkillEnable()
		{
			aiType = GetAiType();
		}

		protected override void OnSkillDisable()
		{
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[0]);
				}
			}
			_ATKLFx.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return StartCor(ElementAttack());
			target = GetTarget();
			double ChargeRHandBegin = 0.3;
			double WarningBegin = 0.77 - ChargeRHandBegin;
			yield return BeginLookAtByPos(GetEntityPosition(target), 0.2, 300);
			BeginAttack(SkillScript_Base.ATKLIndex, SkillScript_Base.ATKLKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(ChargeRHandBegin);
			_ATKLFx.Add(PlayEffect(Charge_ATKL, 1f, default(FP), default(TSVector2), default(FP), 1f, actorScale: true));
			yield return WaitTime(WarningBegin);
			yield return WaitTime(0.1);
			PlayWarningFx();
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[i]);
				}
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == 0 && eventName == "HitFrame")
			{
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 3);
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, GetPosition(), default(FP), default(FP), 4, 0, 160, GetRotation());
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011011, 0, HitBox.HurtAnimType.Small, hitFx);
			}
		}

		protected IEnumerator turnLATKFlow()
		{
			FP atkRotation = GetTSVectToAngle(GetForward(), 60);
			BeginAttack(SkillScript_Base.TurnATKLIndex, SkillScript_Base.TurnATKLKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			StartCor(Damage(atkRotation));
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator turnRATKFlow()
		{
			FP atkRotation = GetTSVectToAngle(GetForward(), -60);
			BeginAttack(SkillScript_Base.TurnATKRIndex, SkillScript_Base.TurnATKRKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			StartCor(Damage(atkRotation));
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator Damage(FP rotation)
		{
			for (int i = 0; i < 1; i++)
			{
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, GetPosition(), default(FP), default(FP), 4, default(FP), 220, rotation);
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011013, 0.5, HitBox.HurtAnimType.Small, "fx_50601JinDuanLiRong_hit_Skill01");
				yield return WaitTime(0.05);
			}
			yield return null;
		}

		private IEnumerator ElementAttack()
		{
			int num = aiType;
			if (num != 0 && num == 1 && TeleportCondition())
			{
				yield return StartCor(Monsterteleport());
			}
		}
	}
