	public class Skill_Dash_LD : SkillScript_Base
	{
		private TSVector2 targetPOS;

		private LogicEntity target;

		private int aiType;

		private FP dashWaitTime = 1.2;

		private TSVector2 dashForward;

		private static readonly string WarningAreaFx = "WarningArea";

		private List<long> _ATKLFx = new List<long>();

		private readonly int DashIndex = 2;

		private CoroutineNode StartCheck;

		protected override void OnSkillEnable()
		{
			_ATKLFx.Clear();
			aiType = GetAiType();
		}

		protected override void OnSkillDisable()
		{
			StopCor(StartCheck);
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[i]);
				}
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			IEnumerator CheckCor = CheckObstacle();
			_ = (FP)1.2;
			int DashSpeed = 60;
			BeginAttack(SkillScript_Base.DashChargeIndex, SkillScript_Base.DashChargeJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return StartCor(ElementAttack());
			BeginAttack(SkillScript_Base.DashChargeIndex, SkillScript_Base.DashChargeJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			CancelAttack();
			SetCloseBlockEnable();
			BeginAttack(SkillScript_Base.DashATKIndex, SkillScript_Base.DashATKJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			target = GetTarget();
			targetPOS = GetEntityPosition(target);
			BeginLookAtByPos_NotWait(targetPOS, 0.3, 600);
			StartCor(WarningFxGround());
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			StopLookAt();
			BeginDash(DashIndex, GetForward(), DashSpeed, 999, default(FP), comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
			StartCheck = StartCor(CheckCor);
			yield return WaitDashFinish();
			SetCloseBlockDisable();
			CancelAttack();
			StopCor(StartCheck);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator CheckObstacle()
		{
			for (int i = 0; i < 100; i++)
			{
				if (!QueryPositionReachable(_actor, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 4))))
				{
					CancelAttack();
					yield return WaitTime(0.1);
					StopDash();
					break;
				}
				yield return WaitTime(0.05);
			}
		}

		private IEnumerator ElementAttack()
		{
			int num = aiType;
			if (num != 0 && num == 1 && TeleportCondition())
			{
				yield return StartCor(Monsterteleport());
			}
		}

		private IEnumerator WarningFxGround()
		{
			yield return WaitTime(0.3);
			string fxAlias = "fx_warning_dash_3x23";
			dashForward = targetPOS - GetPosition();
			FP tSVectToAngle = GetTSVectToAngle(dashForward, 0);
			PlayEffect(fxAlias, 1f, default(FP), GetPosition(), tSVectToAngle);
			yield return WaitTime(1);
		}
	}
	public class Skill_EarthQuake_LD : SkillScript_Base
	{
		private LogicEntity target;

		private int Times;

		private FP rotateAngleLimit;

		protected override void OnSkillEnable()
		{
			Times = 0;
		}

		protected override void OnSkillDisable()
		{
			if (_isDisableByLostControl)
			{
				Parallel.beDisable = true;
			}
			SetInvincibleDisable();
			SetCloseBlockDisable();
			SetSearchedImmunityDisable();
			StopLookAt();
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			BeginAttack(SkillScript_Base.CrawlStartIndex, SkillScript_Base.CrawlStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.8, 225);
			yield return WaitTime(1.2);
			for (int i = 0; i < 2; i++)
			{
				BeginAttack(SkillScript_Base.CrawlEndIndex, SkillScript_Base.CrawlEndKey, flushInputedKeys: true, forceInterruptAttack: true);
				yield return WaitCombo(ComboAttackType.isAnticipationEnd);
				PlayEffect(SkillScript_Base.WarningFx, 1f, 2f, GetPosition(), default(FP), 3.5f);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				if (i < 1)
				{
					yield return StartCor(Monsterteleport());
					PlayWarningFx();
				}
			}
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == SkillScript_Base.CrawlEndIndex)
			{
				Times++;
				if (Times > 2)
				{
					StopDash();
					StopLookAt();
					CancelAttack();
					Times = 0;
				}
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (new List<string> { "MoveBegin", "MoveFinish", "TurnBegin", "TurnFinish", "Attack_L", "Attack_R", "warningFxGround_R", "warningFxGround_L" }.Contains(eventName))
			{
				TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(-1.4, 2));
				TSVector2 tSVector2 = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(1.5, 1.5));
				FP fP = 3;
				FP fP2 = 60;
				switch (eventName)
				{
				case "MoveBegin":
				{
					FP distance = 99;
					FP angleLimit = 0;
					BeginDash(SkillScript_Base.earthQuakeDashIndex, GetForward(), fP, distance, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
					break;
				}
				case "MoveFinish":
					StopDash();
					break;
				case "TurnBegin":
					BeginLookAt_NotWait(target, 99, 360);
					break;
				case "TurnFinish":
					StopLookAt();
					break;
				case "Attack_L":
				{
					FP radius = 3;
					Damage(tSVector, radius);
					break;
				}
				case "Attack_R":
				{
					FP radius = 2.6;
					Damage(tSVector2, radius);
					break;
				}
				case "warningFxGround_R":
				{
					FP fP3 = 19;
					TSVector2 position = TransLocalPosToWorldPos(tSVector2, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				case "warningFxGround_L":
				{
					FP fP3 = 21;
					TSVector2 position = TransLocalPosToWorldPos(tSVector, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				}
			}
		}

		private void Damage(TSVector2 position, FP radius)
		{
			FP innerRadius = 0;
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), radius, innerRadius);
