	public class Skill_Dash_LD : SkillSimpleBase
	{
		private TSVector2 targetPOS;

		private static readonly string WarningFx = "fx_common_base_charge_fire_actor";

		private FP dashWaitTime = 1.2;

		private TSVector2 dashForward;

		private static readonly int DashChargeIndex = 0;

		private static readonly string DashChargeJumpKey = "Dash_Charge";

		private static readonly int DashATKIndex = 1;

		private static readonly string DashATKJumpKey = "Dash_Attack";

		private LogicEntity target;

		private static readonly string WarningAreaFx = "WarningArea";

		private List<long> _ATKLFx = new List<long>();

		private readonly int DashIndex = 2;

		private CoroutineNode StartCheck;

		protected override void OnSkillEnable()
		{
			_ATKLFx.Clear();
		}

		protected override void OnSkillDisable()
		{
			StopCor(StartCheck);
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[i]);
				}
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			IEnumerator CheckCor = CheckObstacle();
			_ = (FP)1.2;
			int DashSpeed = 60;
			BeginAttack(DashChargeIndex, DashChargeJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(1.3);
			CancelAttack();
			SetCloseBlockEnable();
			BeginAttack(DashATKIndex, DashATKJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			target = GetTarget();
			targetPOS = GetEntityPosition(target);
			BeginLookAtByPos_NotWait(targetPOS, 0.3, 600);
			StartCor(WarningFxGround());
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginDash(DashIndex, GetForward(), DashSpeed, 999, default(FP), comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false);
			StartCheck = StartCor(CheckCor);
			yield return WaitDashFinish();
			SetCloseBlockDisable();
			CancelAttack();
			StopCor(StartCheck);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator CheckObstacle()
		{
			for (int i = 0; i < 100; i++)
			{
				if (!QueryPositionReachable(_actor, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 4))))
				{
					CancelAttack();
					yield return WaitTime(0.1);
					StopDash();
					break;
				}
				yield return WaitTime(0.05);
			}
		}

		private IEnumerator WarningFxGround()
		{
			yield return WaitTime(0.3);
			string fxAlias = "fx_warning_dash_3x23";
			dashForward = targetPOS - GetPosition();
			FP tSVectToAngle = GetTSVectToAngle(dashForward, 0);
			PlayEffect(fxAlias, 1f, default(FP), GetPosition(), tSVectToAngle);
			yield return WaitTime(1);
		}

		protected LogicEntity GetTarget()
		{
			LogicEntity logicEntity = null;
			if (CheckTargetIsValid(GetAttackTarget(isUpToDate: true)))
			{
				return GetAttackTarget(isUpToDate: true);
			}
			return GetCurrentPlayer();
		}
	}
	public class Skill_EarthQuake_LD : SkillScript_Base
	{
		private CoroutineNode utimateCor;

		private FP rotateAngleLimit;

		private static LogicEntity target;

		private List<FP> _RelativeDIST = new List<FP>();

		private int Times;

		private static readonly string WarningAreaFx = "WarningArea";

		private List<long> _ATKLFx = new List<long>();

		private TSVector2 ShootPOS;

		protected override void OnSkillEnable()
		{
			_RelativeDIST.Clear();
			Times = 0;
		}

		protected override void OnSkillDisable()
		{
			StopCor(utimateCor);
			if (_isDisableByLostControl)
			{
				Parallel.beDisable = true;
			}
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[i]);
				}
			}
			SetLockToughnessDisable();
			SetCloseBlockDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			BeginAttack(SkillScript_Base.CrawlStartIndex, SkillScript_Base.CrawlStartKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.8, 225);
			yield return WaitTime(1.2);
			utimateCor = StartCor(ElementalUtimateEffect());
			BeginAttack(SkillScript_Base.CrawlEndIndex, SkillScript_Base.CrawlEndKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			PlayEffect(SkillScript_Base.WarningFx, 1f, 2f, GetPosition(), default(FP), 3.5f);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == SkillScript_Base.CrawlEndIndex)
			{
				Times++;
				if (Times > 3)
				{
					StopDash();
					CancelAttack();
					StopLookAt();
				}
			}
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (new List<string> { "MoveBegin", "MoveFinish", "TurnBegin", "TurnFinish", "Attack_L", "Attack_R", "warningFxGround_R", "warningFxGround_L" }.Contains(eventName))
			{
				TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(-1.4, 2));
				TSVector2 tSVector2 = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(1.5, 1.5));
				FP fP = 3;
				FP fP2 = 60;
				switch (eventName)
				{
				case "MoveBegin":
				{
					FP distance = 99;
					FP angleLimit = 0;
					BeginDash(SkillScript_Base.earthQuakeDashIndex, GetForward(), fP, distance, angleLimit, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
					break;
				}
				case "MoveFinish":
					StopDash();
					break;
				case "TurnBegin":
					BeginLookAt_NotWait(target, 99, 360);
					break;
				case "TurnFinish":
					StopLookAt();
					break;
				case "Attack_L":
				{
					FP radius = 3;
					Damage(tSVector, radius);
					break;
				}
				case "Attack_R":
				{
					FP radius = 2.6;
					Damage(tSVector2, radius);
					break;
				}
				case "warningFxGround_R":
				{
					FP fP3 = 19;
					TSVector2 position = TransLocalPosToWorldPos(tSVector2, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				case "warningFxGround_L":
				{
					FP fP3 = 21;
					TSVector2 position = TransLocalPosToWorldPos(tSVector, GetForward(), new TSVector2(0, fP * fP3 / fP2));
					WarningFxGround(position, 2.3f, 1f);
					break;
				}
				}
			}
			FP fP4 = 6;
			List<TSVector2> list = new List<TSVector2>();
			TSVector2 tSVector3 = new TSVector2(0, 0);
			for (int i = 0; i < 5; i++)
			{
				tSVector3 = TransLocalPosToWorldPos(ShootPOS, RotateTo(GetForward(), 72 * i), new TSVector2(0, fP4 + GetRandomValue(0, 3)));
				if (QueryPositionReachable(_actor, tSVector3))
				{
					list.Add(tSVector3);
				}
			}
		}

		private IEnumerator ElementalUtimateEffect()
		{
			for (int i = 0; i < 10; i++)
			{
				StartCor(AreaDamageULT());
				yield return WaitTime(3);
			}
		}

		private void Damage(TSVector2 position, FP radius)
		{
			FP innerRadius = 0;
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), radius, innerRadius);
			HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 3);
			AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011061, 0.5, HitBox.HurtAnimType.Small);
		}

		private long WarningFxGround(TSVector2 position, float playbackSpeed, float spawnSize)
		{
			return PlayEffect("fx_common_base_Fire_YuJing_circular_3", playbackSpeed, default(FP), position, default(FP), spawnSize);
		}
	}
	public class Skill_EarthShatter : SkillScript_Base
	{
		private readonly string playWarningEvent = "PlayWarningFx";

		private readonly string stopWarningEvent = "StopWarningFx";

		private long warningFxID;

		private readonly string warningFx = "fx_m50011_base_skill3_atk_ground_crack_fire";

		private LogicEntity target;

		private TSVector2 movePos;

		protected override void OnSkillEnable()
		{
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		protected override void OnSkillDisable()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == SkillScript_Base.ESJumpIndex && eventName == "JumpStart")
			{
				StartCor(Dash());
			}
			if (comboIndex == SkillScript_Base.ESATKIndex && eventName == playWarningEvent)
			{
				string fxAlias = warningFx;
				TSVector2 position = GetPosition();
				FP entityAngle = GetEntityAngle(_actor);
				warningFxID = PlayEffect(fxAlias, 1f, default(FP), position, entityAngle);
			}
			if (comboIndex == SkillScript_Base.ESATKIndex && eventName == stopWarningEvent)
			{
				StopEffect(warningFxID);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			target = GetTarget();
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, GetEntityPosition(target), default(FP), default(FP), 12, 7.5);
			if (GetDestination(shapeData, out var destination))
			{
				movePos = destination;
				yield return StartCor(Jump());
			}
			yield return StartCor(Attack());
		}

		private bool GetDestination(DeterministicShape shape, out TSVector2 destination)
		{
			bool result = false;
			destination = TSVector2.zero;
			TSVector2 position = GetPosition();
			FP fP = 15;
			for (int i = 0; i <= 10; i++)
			{
				destination = GetShapeRandomPoint(shape, _actor, isReachable: true);
				if (fP <= Distance(position, destination))
				{
					result = true;
					break;
				}
			}
			return result;
		}

		private IEnumerator Jump()
		{
			SetCloseBlockEnable();
			BeginAttack(SkillScript_Base.ESJumpIndex, SkillScript_Base.ESJumpKey, flushInputedKeys: true, forceInterruptAttack: true);
			StartCor(AreaDamageULT());
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetCloseBlockDisable();
		}

		private IEnumerator Dash()
		{
			TSVector2 position = GetPosition();
			FP fP = Distance(position, movePos);
			BeginDash(SkillScript_Base.jumpIndex, movePos - position, fP / 0.4, fP, 0, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: true, triggerEnemyStop: false, triggerFriendStop: false, 0.3);
			yield return WaitTime(0.2);
			BeginLookAt_NotWait(target, 0.2, 675);
			yield return WaitDashFinish();
			DispatchCustomEvent("XingXingDashFinish");
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && string.Equals(adventureActorCustomEvent.eventName, "XingXingDashFinish"))
			{
				CancelAttack();
			}
		}

		private IEnumerator Attack()
		{
			BeginAttack(SkillScript_Base.ESATKIndex, SkillScript_Base.ESATKKey, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(target, 0.3, 200);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			StartCor(AreaDamageULT());
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Jump_LD : SkillScript_Base
	{
		private LogicEntity Target;

		private TSVector2 TargetPOS;

		private readonly FP INTR01 = 0.3;

		private bool breakOff;

		private string WarningBullet = "WarningBullet";

		private bool AlignShoot_WB = true;

		private readonly FP AlignShootDelay_WB = 0;

		private int BulletCount_WB = 1;

		private readonly FP Duration_WB = 0;

		private TSVector2 ShootPOS_WB;

		private readonly FP ShootPOSY_WB = 0;

		private TSVector2 MultishootDirectio_WB;

		private readonly FP BulletDirectionOffset_WB = 0;

		private FP Angle_WB = 0;

		private readonly FP Radius_WB = 0;

		private readonly FP InnerRadius_WB = 0;

		private List<long> _BulletIDList = new List<long>();

		private string WarningBulletArea = "WarningBulletArea";

		private List<long> _AreaEffectFx = new List<long>();

		protected override void OnSkillEnable()
		{
			SetLogicTagToggleValue(_actor, "DropAttackSwitch", value: false);
			breakOff = true;
		}

		protected override void OnSkillDisable()
		{
			SetLogicTagToggleValue(_actor, "DropAttackSwitch", value: false);
			_BulletIDList.Clear();
			ClearShootBulletIdList();
			if (breakOff)
			{
				SetLockToughnessDisable();
				SetCloseBlockDisable();
				SetSearchedImmunityDisable();
				SetUnparalleledDisable();
			}
			if (_AreaEffectFx.Count > 0)
			{
				for (int i = 0; i < _AreaEffectFx.Count; i++)
				{
					StopAreaEffect(_AreaEffectFx[i]);
				}
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			Target = GetCurrentPlayer();
			BeginAttack(SkillScript_Base.DropIndex, SkillScript_Base.DropAttack);
			RemoveBuffFromTarget(_actor, 0, 0, CommonHelper.StringToHash("DeBuff"));
			yield return WaitTime(0.5);
			SetHideModelEnable();
			SetLockToughnessEnable();
			SetCloseBlockEnable();
			SetSearchedImmunityEnable();
			SetUnparalleledEnable();
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(INTR01);
			StartCor(Warning());
			ElementalSkill();
			yield return StartCoroutine(Attack());
		}

		protected IEnumerator Attack()
		{
			for (int i = 0; i < 30; i++)
			{
				if (GetLogicTagToggleValue(_actor, "DropAttackSwitch"))
				{
					break;
				}
				if (i > 29)
				{
					break;
				}
				yield return WaitTime(0.1);
			}
			if (_BulletIDList != null && _BulletIDList.Count > 0)
			{
				TargetPOS = GetBulletPosition(_BulletIDList[0]);
			}
			else
			{
				TargetPOS = TSVector2.zero;
			}
			CancelAttack();
			Teleport(TargetPOS);
			SetHideModelDisable();
			SetLockToughnessDisable();
			BeginLookAt_NotWait(Target, 0.1, 999);
			SetSearchedImmunityDisable();
			SetCloseBlockDisable();
			SetUnparalleledDisable();
			breakOff = false;
			yield return WaitTime(0.5);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator Warning()
		{
			FP fP = 1;
			FP DropBegin = 1.5 - fP;
			ShootPOS_WB = GetEntityPosition(Target);
			MultishootDirectio_WB = GetEntityForward(Target);
			FanMultipleShoot(WarningBullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, AlignShoot_WB, AlignShootDelay_WB, BulletCount_WB, Duration_WB, ShootPOS_WB, ShootPOSY_WB, MultishootDirectio_WB, BulletDirectionOffset_WB, AimType.Default, BulletDirectionType.ActorToBullet, Angle_WB, Radius_WB, InnerRadius_WB);
			_BulletIDList.AddRange(GetShootBulletIdList());
			yield return WaitTime(fP);
			_AreaEffectFx.Add(PlayAreaEffect(WarningBulletArea, new TSVector2(0, 0)));
			yield return WaitTime(DropBegin);
			SetLogicTagToggleValue(_actor, "DropAttackSwitch", value: true);
		}

		private void ElementalSkill()
		{
			int aiType = GetAiType();
			if (aiType != 0 && aiType == 1)
			{
				StartCor(AreaDamage());
			}
		}
	}
	public class Skill_Spawn : SkillSimpleBase
	{
		private static readonly FP PlayerDistance = 13;

		protected TSVector2 targetPOS;

		protected override void OnSkillEnable()
		{
			SetBattleOutEnable();
		}

		protected override void OnSkillDisable()
		{
			SetLogicTagFpValue(_actor, "ReleaseInterval", 1);
			ShowCenterHpBar();
		}

		protected override IEnumerator DoMainLogic()
		{
			LogicEntity target = GetCurrentPlayer();
			if (target != null)
			{
				targetPOS = GetEntityPosition(target);
			}
			while (Distance(targetPOS, GetPosition()) >= PlayerDistance)
			{
				if (target != null)
				{
					targetPOS = GetEntityPosition(target);
				}
				yield return WaitFrame(10);
			}
		}
	}
