		protected static readonly int ESJumpIndex = 12;

		protected static readonly string ESJumpKey = "EarthShatter_Jump";

		protected static readonly int ESATKIndex = 13;

		protected static readonly string ESATKKey = "EarthShatter_Attack";

		private readonly string bulletAliasRectangle = "50011XingXing_Earth_nullbullet_rectangle";

		private readonly string bulletAliasCircle = "50011XingXing_Earth_nullbullet_circle";

		private readonly int forwardBulletCount = 3;

		private readonly int backwardBulletCount = 1;

		private readonly FP forwardAngle = 50;

		private readonly FP backwardAngle = 20;

		protected static readonly int jumpIndex = 100;

		protected static readonly int earthQuakeDashIndex = 101;

		protected void GroundAttack(TSVector2 SpawnPos, TSVector2 SpawnForward)
		{
			TSVector2 multiShootDirection = RotateTo(SpawnForward, 180);
			FanMultipleShoot(bulletAliasCircle, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, forwardBulletCount, default(FP), SpawnPos, 0, SpawnForward, 0, AimType.Default, BulletDirectionType.ActorToBullet, forwardAngle, 0, 0);
			FanMultipleShoot(bulletAliasCircle, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, backwardBulletCount, default(FP), SpawnPos, 0, multiShootDirection, 0, AimType.Default, BulletDirectionType.ActorToBullet, backwardAngle, 0, 0);
			DispatchCustomEvent("StopEnhanceFx");
		}

		protected void UpdateEffectTag()
		{
			if (!GetLogicTagToggleValue(_actor, "IsEnhanced"))
			{
				SetLogicTagToggleValue(_actor, "IsEnhanced", value: true);
				DispatchCustomEvent("PlayEnhanceFx");
			}
		}

		protected void CheckSkillcondition()
		{
			if (!GetLogicTagToggleValue(_actor, "IsEnhanced"))
			{
				return;
			}
			GroundAttack(GetPosition(), GetForward());
			SetLogicTagToggleValue(_actor, "IsEnhanced", value: false);
			List<long> list = new List<long>();
			if (GetLogicTagListLongValue(_actor, "enhancedFxID") != null && GetLogicTagListLongValue(_actor, "enhancedFxID").Count > 0)
			{
				list.AddRange(GetLogicTagListLongValue(_actor, "enhancedFxID"));
				foreach (long item in list)
				{
					StopEffect(item);
				}
			}
			list.Clear();
			list = null;
		}

		protected void UltimateGroundAttack(TSVector2 SpawnPos, TSVector2 SpawnForward, int bulletcount)
		{
			CircleMultipleShoot(bulletAliasCircle, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, bulletcount, default(FP), SpawnPos, 0, SpawnForward, 0, AimType.Default, BulletDirectionType.ActorToBullet, 0, 0);
		}

		protected int GetAiType()
		{
			int num = 0;
			string monsterTagValue = GetMonsterTagValue(_actor, 1);
			if (!(monsterTagValue == "Easy"))
			{
				if (monsterTagValue == "Hard")
				{
					return 1;
				}
				return 0;
			}
			return 0;
		}

		protected LogicEntity GetTarget()
		{
			LogicEntity logicEntity = null;
			if (CheckTargetIsValid(GetAttackTarget(isUpToDate: true)))
			{
				return GetAttackTarget(isUpToDate: true);
			}
			return GetCurrentPlayer();
		}
	}
	public class Skill_Attack_L_LD : SkillScript_Base
	{
		private int aiType;

		private LogicEntity target;

		private static readonly string WarningFx_ATKL = "fx_m50011_base_skill4_hint_L_earth";

		private static readonly string Charge_ATKL = "fx_m50011_loop_skill4_charge_Rhand_L_earth";

		private static readonly string hitFx = "fx_common_hit_earth_strike";

		private List<long> _ATKLFx = new List<long>();

		protected override void OnSkillEnable()
		{
			aiType = GetAiType();
		}

		protected override void OnSkillDisable()
		{
			if (_ATKLFx.Count > 0)
			{
				for (int i = 0; i < _ATKLFx.Count; i++)
				{
					StopEffect(_ATKLFx[0]);
				}
			}
			_ATKLFx.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			if (CheckTargetIsValid(GetAttackTarget(isUpToDate: true)))
			{
				target = GetAttackTarget(isUpToDate: true);
			}
			else
			{
				target = GetCurrentPlayer();
			}
			double ChargeRHandBegin = 0.3;
			double WarningBegin = 0.77 - ChargeRHandBegin;
			_ = (FP)0;
			for (int i = 0; i < 2; i++)
			{
				FP fP = AngleBetween2TSVector(GetForward(), GetEntityPosition(target) - GetPosition(), signed: true);
				if (Mathf.Abs((float)fP) > 90f && i == 0)
				{
					if (fP > 0)
					{
						yield return StartCor(turnLATKFlow());
					}
					else if (fP < 0)
					{
						yield return StartCor(turnRATKFlow());
					}
				}
				else
				{
					if (!(Mathf.Abs((float)fP) > 90f) || i <= 0)
					{
						continue;
					}
					if (GetRandomValue(0, 1.5, isInt: true) > 0)
					{
						if (fP > 0)
						{
							yield return StartCor(turnLATKFlow());
						}
						else if (fP < 0)
						{
							yield return StartCor(turnRATKFlow());
						}
					}
					InterruptSkill();
					yield return null;
				}
			}
			yield return BeginLookAtByPos(GetEntityPosition(target), 0.2, 300);
			BeginAttack(SkillScript_Base.ATKLIndex, SkillScript_Base.ATKLKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(ChargeRHandBegin);
			_ATKLFx.Add(PlayEffect(Charge_ATKL, 1f, default(FP), default(TSVector2), default(FP), 1f, actorScale: true));
			yield return WaitTime(WarningBegin);
			if (_ATKLFx.Count > 0)
			{
				for (int j = 0; j < _ATKLFx.Count; j++)
				{
					StopEffect(_ATKLFx[j]);
				}
			}
			yield return StartCor(ElementAttack());
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected override void OnCustomEvent(int comboIndex, string eventName)
		{
			if (comboIndex == SkillScript_Base.ATKLIndex && eventName == "HitFrame")
			{
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 3);
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, GetPosition(), default(FP), default(FP), 4, 0, 160, GetRotation());
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011011, 0, HitBox.HurtAnimType.Small, hitFx);
			}
		}

		protected IEnumerator turnLATKFlow()
		{
			FP atkRotation = GetTSVectToAngle(GetForward(), 60);
			BeginAttack(SkillScript_Base.TurnATKLIndex, SkillScript_Base.TurnATKLKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			StartCor(Damage(atkRotation));
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator turnRATKFlow()
		{
			FP atkRotation = GetTSVectToAngle(GetForward(), -60);
			BeginAttack(SkillScript_Base.TurnATKRIndex, SkillScript_Base.TurnATKRKey, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isRecoveryBegin);
			StartCor(Damage(atkRotation));
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected IEnumerator Damage(FP rotation)
		{
			for (int i = 0; i < 1; i++)
			{
				DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Fan, GetPosition(), default(FP), default(FP), 4, default(FP), 220, rotation);
				HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 50011013, 0.5, HitBox.HurtAnimType.Small, "fx_50601JinDuanLiRong_hit_Skill01");
				yield return WaitTime(0.05);
			}
			yield return null;
		}

		private IEnumerator ElementAttack()
		{
			switch (aiType)
			{
			case 0:
				if (GetRandomValue(0, 1) > 0.5)
				{
					UpdateEffectTag();
				}
				break;
			case 1:
				UpdateEffectTag();
				break;
			}
			yield break;
		}
	}
