	public class Wind_Attack01 : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] Attack01 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.A,
			ComboInputBuffer.ActionKey._1
		};

		private readonly ComboInputBuffer.ActionKey[] Attack02 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.A,
			ComboInputBuffer.ActionKey._2
		};

		private readonly ComboInputBuffer.ActionKey[] Attack03 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.A,
			ComboInputBuffer.ActionKey._2
		};

		private LogicEntity Targetenemy;

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Attack01, flushInputedKeys: true, forceInterruptAttack: true);
			GetEnemy();
			BeginLookAt_NotWait(Targetenemy, 0.3, 300);
			if (GetBuffNum(_actor, 503010004) >= 1)
			{
				yield return WaitCustomEvent("LightShoot01");
				DoShoot01();
				yield return WaitCustomEvent("LightShoot02");
				DoShoot01();
			}
			yield return WaitCustomEvent("LightShootEnd");
			BeginAttack(2, Attack02, flushInputedKeys: true, forceInterruptAttack: true);
			GetEnemy();
			BeginLookAt_NotWait(Targetenemy, 0.3, 600);
			yield return WaitCustomEvent("Storage");
			GetEnemy();
			BeginLookAt_NotWait(Targetenemy, 0.5, 60);
			yield return WaitFrame(20);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void GetEnemy()
		{
			Targetenemy = GetAttackTarget();
			if (Targetenemy == null)
			{
				Targetenemy = GetCurrentPlayer();
			}
		}

		protected void DoShoot01()
		{
			TSVector2 shootPosition = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 2));
			FanMultipleShoot("Bullet_50301_MaoDa_Skill01_Small_01", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 2, 0, shootPosition, 1.85, GetForward(), 0, AimType.Default, BulletDirectionType.ActorToBullet, 30, 0, 0);
		}

		protected void DoShoot02()
		{
			TSVector2 shootPosition = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 2));
			FanMultipleShoot("Bullet_50301_MaoDa_Skill01_Small_01", AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: false, 0, 2, 0, shootPosition, 1.85, GetForward(), 0, AimType.Default, BulletDirectionType.ActorToBullet, 30, 0, 0);
		}

		protected void Shoot01()
		{
			TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 2));
			LogicEntity currentPlayer = GetCurrentPlayer();
			Shoot("Bullet_50301_MaoDa_Skill01_Small_03_1", position, 1.1, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, GetEntityPosition(currentPlayer));
			Shoot("Bullet_50301_MaoDa_Skill01_Small_03_2", position, 1.1, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, GetEntityPosition(currentPlayer));
			Shoot("Bullet_50301_MaoDa_Skill01_Small_03_3", position, 1.1, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, GetEntityPosition(currentPlayer));
			Shoot("Bullet_50301_MaoDa_Skill01_Small_03_4", position, 1.1, 0, GetForward(), AimType.Position, BulletDirectionType.BulletToTarget, GetEntityPosition(currentPlayer));
		}
	}
	public class Wind_Attack02 : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] Attack01 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		private List<int> RotateList = new List<int> { -90, 180, 180, 90, 0, -90 };

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Attack01, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(GetCurrentPlayer(), 0.5, 220);
			if (GetBuffNum(_actor, 503010000) >= 6)
			{
				List<LogicEntity> targetByTeammateIndex = GetTargetByTeammateIndex(1);
				for (int i = 0; i < targetByTeammateIndex.Count; i++)
				{
					LogicEntity target = targetByTeammateIndex[i];
					AddBuffToTarget(target, 503010001);
				}
			}
			else if (GetPlaceHolderPosition("MaoDaSquareScene") != new TSVector2(0, 0))
			{
				DoSpawnNuji02();
				DoSpawnNuji02();
			}
			else
			{
				DoSpawnNuji01();
				DoSpawnNuji01();
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		protected void DoSpawnNuji01()
		{
			int buffNum = GetBuffNum(_actor, 503010000);
			TSVector2 tSVector = new TSVector2(0, 15);
			List<int> list = new List<int> { 60, 30, -30, -120, -180, -270 };
			TSVector2 spawnPosition = RotateTo(tSVector, list[buffNum]);
			int num = RotateList[buffNum];
			TSVector2 spawnDirection = RotateTo(tSVector, num);
			SummonTeammate(1, spawnPosition, spawnDirection);
			AddBuffToTarget(_actor, 503010000);
		}

		protected void DoSpawnNuji02()
		{
			int buffNum = GetBuffNum(_actor, 503010000);
			List<int> list = new List<int> { 12, -12, -12, 12, -5, 5 };
			List<int> list2 = new List<int> { 9, -9, -3, 3, 15, -15 };
			TSVector2 tSVector = new TSVector2(list[buffNum], list2[buffNum]);
			List<int> list3 = new List<int> { 145, 145, 165, 165, 162, 162 };
			TSVector2 spawnDirection = RotateTo(tSVector, list3[buffNum]);
			SummonTeammate(1, tSVector, spawnDirection);
			AddBuffToTarget(_actor, 503010000);
		}
	}
