	public class Earth_Born : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Born = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Y };

		protected TSVector2 TargetPosition;

		protected override void OnSkillEnable()
		{
			SetBattleOutEnable();
			AddBuffToTarget(_actor, 990020140);
			AddBuffToTarget(_actor, 501810000);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Born, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("Born");
			LogicEntity attackTarget = GetAttackTarget(isUpToDate: true);
			if (attackTarget != null)
			{
				TargetPosition = GetEntityPosition(attackTarget);
			}
			while (Distance(TargetPosition, GetPosition()) >= 14)
			{
				yield return WaitFrame(3);
				attackTarget = GetAttackTarget(isUpToDate: true);
				if (attackTarget != null)
				{
					TargetPosition = GetEntityPosition(attackTarget);
				}
			}
			RemoveBuffFromTarget(_actor, 990020140);
			SetBattleOutDisable();
			ShowCenterHpBar();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Earth_Teleport : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Teleport01 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.T,
			ComboInputBuffer.ActionKey._1
		};

		private static readonly ComboInputBuffer.ActionKey[] Teleport02 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.T,
			ComboInputBuffer.ActionKey._2
		};

		private TSVector2 SkillPos;

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Teleport01, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("Disappear");
			SetHideModelEnable();
			SetUnparalleledEnable();
			LogicEntity currentPlayer = GetCurrentPlayer();
			if (Distance(GetPosition(), GetEntityPosition(currentPlayer)) <= 6)
			{
				Earth_Teleport earth_Teleport = this;
				TSVector2 entityPosition = GetEntityPosition(currentPlayer);
				FP radius = 12;
				FP innerRadius = 10;
				DeterministicShape shapeData = earth_Teleport.GetShapeData(DeterministicShape.ShapeType.Circle, entityPosition, default(FP), default(FP), radius, innerRadius);
				SkillPos = GetShapeRandomPoint(shapeData, _actor, isReachable: true);
				Teleport(SkillPos);
				BeginLookAt_NotWait(currentPlayer, 0.1, 3600);
			}
			else
			{
				Earth_Teleport earth_Teleport2 = this;
				TSVector2 entityPosition2 = GetEntityPosition(currentPlayer);
				FP innerRadius = 12;
				FP radius = 10;
				DeterministicShape shapeData2 = earth_Teleport2.GetShapeData(DeterministicShape.ShapeType.Circle, entityPosition2, default(FP), default(FP), innerRadius, radius);
				TSVector2 shapeRandomPoint = GetShapeRandomPoint(shapeData2, _actor, isReachable: true);
				while (Distance(shapeRandomPoint, GetPosition()) < 5)
				{
					shapeRandomPoint = GetShapeRandomPoint(shapeData2, _actor, isReachable: true);
				}
				SkillPos = shapeRandomPoint;
				Teleport(SkillPos);
				BeginLookAt_NotWait(currentPlayer, 0.1, 3600);
			}
			yield return WaitTime(0.15);
			BeginAttack(1, Teleport02, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("Appear");
			SetUnparalleledDisable();
			SetHideModelDisable();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
}
