	public class Skill : SkillAdvancedBase
	{
		protected FP speed = 12;

		protected readonly int forceStopTime = 10;

		protected FP _distanceLimit = 999;

		protected FP _angleLimit = 9;

		protected MonsterSummonInfo _monsterSummonInfo;

		protected ComboAttack _comboAttack;

		protected ComboInputBuffer.ActionKey[] _actionKeys;

		protected Dash _dash;

		protected CoroutineNode _corStop;

		protected TSVector2 targetPos;

		protected FP targetRadius;

		protected bool _checkDistance;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			SelectActionKeys();
			StopCoroutine(ref _corStop);
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			ComboInputBuffer.ActionKey[] actionKeys = _actionKeys;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onRecoveryBegin = OnRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, null, onComboFinish, onInterrupt);
			_checkDistance = false;
		}

		protected void SelectActionKeys()
		{
			if (_monsterSummonInfo == null)
			{
				_monsterSummonInfo = _actor.GetLogicComponent<MonsterSummonInfo>();
			}
			PlayerAdventureActor playerAdventureActor = _monsterSummonInfo.SummonActor as PlayerAdventureActor;
			if (playerAdventureActor != null)
			{
				switch (playerAdventureActor.GetTalentGroupType())
				{
				case PlayerTalentGroupType.Group14:
					_actionKeys = new ComboInputBuffer.ActionKey[3]
					{
						ComboInputBuffer.ActionKey.F,
						ComboInputBuffer.ActionKey.X,
						ComboInputBuffer.ActionKey.A
					};
					break;
				case PlayerTalentGroupType.Group24:
					_actionKeys = new ComboInputBuffer.ActionKey[3]
					{
						ComboInputBuffer.ActionKey.F,
						ComboInputBuffer.ActionKey.X,
						ComboInputBuffer.ActionKey.B
					};
					break;
				case PlayerTalentGroupType.Group34:
					_actionKeys = new ComboInputBuffer.ActionKey[3]
					{
						ComboInputBuffer.ActionKey.F,
						ComboInputBuffer.ActionKey.X,
						ComboInputBuffer.ActionKey.C
					};
					break;
				default:
					_actionKeys = new ComboInputBuffer.ActionKey[3]
					{
						ComboInputBuffer.ActionKey.F,
						ComboInputBuffer.ActionKey.X,
						ComboInputBuffer.ActionKey.X
					};
					break;
				}
			}
			else
			{
				_actionKeys = new ComboInputBuffer.ActionKey[3]
				{
					ComboInputBuffer.ActionKey.F,
					ComboInputBuffer.ActionKey.X,
					ComboInputBuffer.ActionKey.X
				};
			}
		}

		protected void OnAnticipationEnd()
		{
			if (_dash == null)
			{
				_dash = new Dash();
			}
			LookAtTarget();
			_dash.BeginDash(_actor, _actor.tsTransform.Forward, speed, _distanceLimit, _angleLimit, (System.Action)null, (System.Action)null, (System.Action)null, true, true, false, false, false, false, false, default(FP), true);
			StartCoroutine(ref _corStop, ForceStop());
			_checkDistance = true;
		}

		protected void LookAtTarget()
		{
			PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
			if (playerAdventureActor != null)
			{
				if (playerAdventureActor.attackTarget != null)
				{
					_actor.LookAt(playerAdventureActor.attackTarget.tsTransform.Position, 0);
					targetPos = playerAdventureActor.attackTarget.tsTransform.Position;
					AdventureActor adventureActor = playerAdventureActor.attackTarget as AdventureActor;
					targetRadius = adventureActor.dtCollider.Radius;
				}
				else
				{
					_actor.LookAt(playerAdventureActor.tsTransform.Position, 0);
					targetPos = playerAdventureActor.tsTransform.Position;
					targetRadius = playerAdventureActor.dtCollider.Radius;
				}
			}
		}

		public void OnUpdate()
		{
			if (_checkDistance && TSVector2.Distance(_actor.tsTransform.Position, targetPos) <= _actor.dtCollider.Radius + targetRadius + 0.1f)
			{
				_checkDistance = false;
				_comboAttack.CancelAttack();
			}
		}

		protected IEnumerator ForceStop()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(forceStopTime));
			_comboAttack.CancelAttack();
		}

		protected void OnRecoveryBegin()
		{
			_dash?.Interrupte();
			StopCoroutine(ref _corStop);
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			StopCoroutine(ref _corStop);
			_checkDistance = false;
			_dash?.Clear();
			_dash = null;
			_comboAttack?.Clear();
			_actor.DestroySelf();
		}
	}
}
