	public class Skill_PointRepulse : SkillSimpleBase
	{
		private List<long> fxIDList = new List<long>();

		private List<TSVector2> fxPOSList = new List<TSVector2>();

		private readonly List<TSVector2> atkPOSList = new List<TSVector2>
		{
