				AttackPOS02.Add(GetShapeRandomPoint(Attackshape02, _actor, isReachable: true));
				PlayAreaEffect(AreaEffectAlias01, AttackPOS02[i]);
				fxLoopA = PlayFxForNeedStop(fxA, 1f, _actor.tsTransform.PositionY, AttackPOS02[i], _actor.tsTransform.Rotation);
				yield return WaitTime(GetRandomValue(0.5, 1));
			}
		}
