	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private static readonly string bullet_tag = "";

		private const int beHitNum = 5;

		private const int beHitNum_Max = 0;

		private bool fengCao_001_finish;

		private bool fengCao_002_finish;

		private bool fengCao_003_finish;

		private bool fengCao_004_finish;

		private int num_hit_current;

		private bool beHit;

		private bool isToughnessBroken;

		public static bool inUltra;

		public override void OnStart()
		{
			base.OnStart();
			inUltra = false;
			if (MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel != null)
			{
				num_hit_current = 0;
				beHit = false;
				isToughnessBroken = false;
				fengCao_001_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengCao_001);
				fengCao_002_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengCao_002);
				fengCao_003_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengCao_003);
				fengCao_003_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengCao_004);
				if (!fengCao_002_finish)
				{
					ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
				}
				if (!fengCao_001_finish || !fengCao_003_finish || !fengCao_004_finish)
				{
					ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
				}
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			if (!fengCao_002_finish)
			{
				ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_TOUGHNESS_STATECHANGE", OnToughnessState);
			}
			if (!fengCao_001_finish || !fengCao_003_finish || !fengCao_004_finish)
			{
				ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (_actor != null && adventureActorReceiveDamageEvent.to == _player)
			{
				if (!fengCao_001_finish && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel.RegionType == 2 && adventureActorReceiveDamageEvent.attackType == DamageType.Range && adventureActorReceiveDamageEvent.weapon.tag == bullet_tag)
				{
					beHit = true;
				}
				if (!fengCao_003_finish || !fengCao_004_finish)
				{
					num_hit_current++;
				}
			}
		}

		private void OnToughnessState(IEvent evt)
		{
			MonsterToughnessStateChangeEvent monsterToughnessStateChangeEvent = evt as MonsterToughnessStateChangeEvent;
			if (_actor != null && _actor.Id == monsterToughnessStateChangeEvent.actor.Id && _player != null && _player.Id == monsterToughnessStateChangeEvent.source.Id && monsterToughnessStateChangeEvent.isToughnessBroken && inUltra && !isToughnessBroken)
			{
				isToughnessBroken = true;
				ModuleController<AdventureModuleController>.Instance?.SetAchievementFinish(GameEnum.questCompleteCondClient.FengCao_002);
			}
		}

		protected override void OnActorDied(IEvent e)
		{
			base.OnActorDied(e);
			if (e is AdventureActorDiedEvent adventureActorDiedEvent && adventureActorDiedEvent.actor.Id == _actor.Id && !(adventureActorDiedEvent.killer == null) && adventureActorDiedEvent.killer.Id != _actor.Id)
			{
				if (!beHit && !fengCao_001_finish)
				{
					ModuleController<AdventureModuleController>.Instance?.SetAchievementFinish(GameEnum.questCompleteCondClient.FengCao_001);
				}
				if (num_hit_current <= 5 && !fengCao_003_finish)
				{
					ModuleController<AdventureModuleController>.Instance?.SetAchievementFinish(GameEnum.questCompleteCondClient.FengCao_003);
				}
				if (num_hit_current <= 0 && !fengCao_004_finish)
				{
					ModuleController<AdventureModuleController>.Instance?.SetAchievementFinish(GameEnum.questCompleteCondClient.FengCao_004);
				}
			}
		}
	}
	public class Parrallel_BossRush : Parallel_BossRush
	{
		private int hitTag = CommonHelper.StringToHash("CyclonesHitTag");

		private FP liveTime = 10;

		private int bulletTag_Cyclone = CommonHelper.StringToHash("CyclonesTag");

		private int skill_1 = 1651007;

		private int skill_2 = 1651027;

		private int skill_3 = 1651002;

		private int skill_4 = 1651022;

		private FP delayTime = 6;

		private string bossTagId = "100001";

		private int buff_rage = 631003001;

		private int interval = 10;

		private int buff_dmg = 631003002;

		private int accumulate = 10;

		private int maxCount = 10;

		private int interval_dmg = 2;

		private int once_dmg = 50;

		private FP cd = 2;

		private int summonId;

		private Dictionary<long, FP> dicLiveTime = new Dictionary<long, FP>();

		private CoroutineNode corBuff;

		private Dictionary<int, List<FP>> dicSkillHit = new Dictionary<int, List<FP>>();

		private bool hasTag;

		private FP curTime;

		private bool isHit_1;

		private bool isHit_2;

		private bool isHit_3;

		private bool isHit_4;

		private CoroutineNode corSkill_1;

		private CoroutineNode corSkill_2;

		private CoroutineNode corSkill_3;

		private CoroutineNode corSkill_4;

		private AdventureActor mainCtrActor => SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;

		public override void OnStart()
		{
			base.OnStart();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BATTLE_MONSTER_SUMMONER_SPAWNED", OnAcorSummon);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			curTime = 0;
			MonsterAdventureActor monsterAdventureActor = _actor as MonsterAdventureActor;
			summonId = CommonHelper.GetMonsterTeammateId(monsterAdventureActor.monsterInfo.teamId, 1);
			for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
			{
				PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i];
				dicSkillHit.Add(playerAdventureActor.dataID, new List<FP>());
			}
			hasTag = _actor.CheckTag(bossTagId);
			if (hasTag)
			{
				StartCoroutine(ref corBuff, DoAddBuff());
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BATTLE_MONSTER_SUMMONER_SPAWNED", OnAcorSummon);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			StopCoroutine(ref corBuff);
			StopCoroutine(ref corSkill_1);
			StopCoroutine(ref corSkill_2);
			StopCoroutine(ref corSkill_3);
			StopCoroutine(ref corSkill_4);
			dicLiveTime.Clear();
			dicSkillHit.Clear();
		}

		private void OnCastSkill(IEvent evt)
		{
			AdventureActorCastSkillEvent adventureActorCastSkillEvent = evt as AdventureActorCastSkillEvent;
			if (_actor != null && adventureActorCastSkillEvent.sender as AdventureActor == _actor)
			{
				if (adventureActorCastSkillEvent.skillEventInfo.skillId == skill_1)
				{
					isHit_1 = false;
					StartCoroutine(ref corSkill_1, DoCheckHit(skill_1));
				}
				else if (adventureActorCastSkillEvent.skillEventInfo.skillId == skill_2)
				{
					isHit_2 = false;
					StartCoroutine(ref corSkill_2, DoCheckHit(skill_2));
				}
				else if (adventureActorCastSkillEvent.skillEventInfo.skillId == skill_3)
				{
					isHit_3 = false;
					StartCoroutine(ref corSkill_3, DoCheckHit(skill_3));
				}
				else if (adventureActorCastSkillEvent.skillEventInfo.skillId == skill_4)
				{
					isHit_4 = false;
					StartCoroutine(ref corSkill_4, DoCheckHit(skill_4));
				}
			}
		}

		private IEnumerator DoCheckHit(int skillId)
		{
			yield return _actor.WaitTime(delayTime);
			if (skillId == skill_1)
			{
				if (!isHit_1 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)11))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)11);
				}
			}
			else if (skillId == skill_2 && !isHit_2 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)11))
			{
				_monster.TriggerScoreBossBehaviour((scoreBossBehavior)11);
			}
			if (skillId == skill_3)
			{
				if (!isHit_3 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)11))
				{
					_monster.TriggerScoreBossBehaviour((scoreBossBehavior)11);
				}
			}
			else if (skillId == skill_4 && !isHit_4 && _monster.CheckScoreBossBehaviour((scoreBossBehavior)11))
			{
				_monster.TriggerScoreBossBehaviour((scoreBossBehavior)11);
			}
		}

		protected override void OnActorReceiveDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
			if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, hitTag) && damageEvent.to is PlayerAdventureActor && damageEvent.weapon != null && damageEvent.weapon is AdventureBullet adventureBullet && adventureBullet.BulletHashCode == bulletTag_Cyclone)
			{
				if (damageEvent.skillId == skill_1)
				{
					isHit_1 = true;
				}
				else if (damageEvent.skillId == skill_2)
				{
					isHit_2 = true;
				}
				else if (damageEvent.skillId == skill_3)
				{
					isHit_3 = true;
				}
				else if (damageEvent.skillId == skill_4)
				{
					isHit_4 = true;
				}
			}
			if (!hasTag || !(damageEvent.to == _actor))
			{
				return;
			}
			PlayerAdventureActor playerAdventureActor = damageEvent.from as PlayerAdventureActor;
			if (((object)playerAdventureActor == null && (!(damageEvent.from is MonsterAdventureActor monsterAdventureActor) || !ActorHelper.IsPlayerSummoned((LogicEntity)monsterAdventureActor, ref playerAdventureActor))) || (!(_actor.LogicTime - curTime > cd) && !(curTime <= 0)) || !dicSkillHit.TryGetValue(playerAdventureActor.dataID, out var value))
			{
				return;
			}
			value.Add(_actor.LogicTime);
			_ = _actor.LogicTime;
			FP fP = _actor.LogicTime - interval_dmg;
			for (int num = value.Count - 1; num >= 0; num--)
			{
				if (value[num] < fP)
				{
					value.RemoveAt(num);
				}
			}
			if (value.Count < accumulate)
			{
				return;
			}
			_actor.buffComponent.RemoveBuffByBuffId(buff_rage);
			mainCtrActor.buffComponent.AddBuffNum(buff_dmg, maxCount, playerAdventureActor);
			curTime = _actor.LogicTime;
			foreach (KeyValuePair<int, List<FP>> item in dicSkillHit)
			{
				item.Value.Clear();
			}
		}

		protected override void OnReceiveBeforeHit(IEvent evt)
		{
			if (hasTag)
			{
				AdventureActorReceiveDamageBeforeHitEvent obj = evt as AdventureActorReceiveDamageBeforeHitEvent;
				PlayerAdventureActor playerAdventureActor = obj.from as PlayerAdventureActor;
				if (obj.to as MonsterAdventureActor == _actor && playerAdventureActor == mainCtrActor && mainCtrActor.buffComponent.CheckBuffByBuffID(buff_dmg))
				{
					mainCtrActor.buffComponent.RemoveBuffByBuffId(buff_dmg, 1);
					AdventureActor.AddFromAttr(once_dmg, mainCtrActor);
				}
			}
		}

		private void OnAcorSummon(IEvent evt)
		{
			AdventureMonsterSummonerSpawnedEvent adventureMonsterSummonerSpawnedEvent = evt as AdventureMonsterSummonerSpawnedEvent;
			if (adventureMonsterSummonerSpawnedEvent.summonerId == _actor.Id && adventureMonsterSummonerSpawnedEvent.dataId == summonId)
			{
				dicLiveTime.Add(adventureMonsterSummonerSpawnedEvent.id, _actor.LogicTime);
			}
		}

		protected override void OnActorDied(IEvent e)
		{
			base.OnActorDied(e);
			if (e is AdventureActorDiedEvent adventureActorDiedEvent && adventureActorDiedEvent.actor.dataID == summonId && dicLiveTime.TryGetValue(adventureActorDiedEvent.actor.Id, out var value) && _actor.LogicTime - value <= liveTime && _monster.CheckScoreBossBehaviour((scoreBossBehavior)12))
			{
				_monster.TriggerScoreBossBehaviour((scoreBossBehavior)12);
			}
		}

		private IEnumerator DoAddBuff()
		{
			_actor.buffComponent.AddBuff(buff_rage, _actor);
			while (true)
			{
				yield return _actor.WaitTime(interval);
				_actor.buffComponent.AddBuff(buff_rage, _actor);
			}
		}
	}
}
