			TSVector2 position = GetPosition();
			Skill_TraceCharge skill_TraceCharge = this;
			FP radius = 6;
			FP innerRadius = 3;
			FP angle = 240;
			FP rotation = 180;
			DeterministicShape shapeData = skill_TraceCharge.GetShapeData(DeterministicShape.ShapeType.Fan, position, default(FP), default(FP), radius, innerRadius, angle, rotation);
