				{
				case 0:
					GotoCastSkill(Skill_FlyUp);
					break;
				case 1:
					GotoCastSkill(Skill_Dash);
					break;
				}
				yield return WaitSkillFinish();
			}
			else
			{
				yield return StartCoroutine(RandomSkillP1());
				if (!IsPhase2)
				{
