			list.Add(new BaseBranchInfo(2003, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Phase2Skill4Cast;
			list.Add(new BaseBranchInfo(2004, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Phase2Skill5Cast;
			list.Add(new BaseBranchInfo(2005, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = Phase2Skill6Cast;
			list.Add(new BaseBranchInfo(2006, default(FP), default(FP), default(FP), null, operateIEnumerator));
			operateIEnumerator = TestCast;
			list.Add(new BaseBranchInfo(9999, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> sequenceDict = new Dictionary<int, List<int>>
			{
				[1] = new List<int> { 1000, 1001, 1002, 1003, 1004, 1005 },
				[2] = new List<int> { 2000, 2001, 2002, 2003, 2004, 2005, 2006 },
				[3] = new List<int> { 9999 }
			};
			InitSequenceBranches(1, sequenceBranches, sequenceDict);
		}

