		private IEnumerator Phase2Skill6Cast()
		{
			if (BaseSummonProbability <= 0)
			{
				WeightInSkill = new int[2] { 1, 1 };
				switch (randomWeight(WeightInSkill))
				{
				case 0:
					GotoCastSkill(Skill_FlyUp);
					break;
				case 1:
					GotoCastSkill(Skill_Dash);
