		private IEnumerator TestCast()
		{
			if (FirstTimeInitial)
			{
				StartCoroutine(CheckBuffAndSetLightDistance());
				FirstTimeInitial = false;
			}
			GotoCastSkill(testSkillId);
			yield return WaitSkillFinish();
		}

		private bool CheckTargetIsNear()
		{
			if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: false) <= FarSkillOutRadius)
			{
				return true;
			}
			return false;
		}

		private bool CheckFlowerAwaken()
		{
			GetAwakenFlowerEntities();
			int count = FlowerList.Count;
			FP fP = 0;
			switch (count)
			{
			case 0:
			case 1:
				fP = BaseSummonProbability + 100;
				break;
			case 2:
				fP = BaseSummonProbability + 80;
				break;
			case 3:
				fP = BaseSummonProbability + 50;
				break;
			case 4:
				fP = BaseSummonProbability + 10;
				break;
			case 5:
			case 6:
				fP = BaseSummonProbability;
				break;
			}
			if (GetRandomValue(1, 100) > 100 - fP)
			{
				return true;
			}
			return false;
		}

		private void PhaseChange(IEvent evt)
		{
			if (_actor.actorHealthInfo.hpPercentage <= HpPercentStage2 && !IsPhase2)
			{
				IsPhase2 = true;
				SwitchSequence(2);
			}
		}

		private void GetAwakenFlowerEntities()
		{
			FlowerList.Clear();
			FlowerList = GetTargetsByLogicTag(LogicTagType._Bool, "Awaken", GetTargetByTeammateIndexes(new List<int> { 1, 2 }), value1: true);
		}

		private void LostControlKillBirds(IEvent evt)
		{
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			ClearActors(GetTargetByTeammateIndexes(new List<int> { 3, 4 }));
			GetAwakenFlowerEntities();
			foreach (AdventureActor flower in FlowerList)
			{
				DirectDamage(flower, iFP.op_Implicit(_actor.actorHealthInfo.hpMax), null, showHud: false);
			}
		}

		private IEnumerator CheckBuffAndSetLightDistance()
		{
			while (true)
			{
				if (!GetLogicTagToggleValue(_actor, "InFlowerAwakenSkill") || _actor.state == ActorState.LostControl)
				{
					List<int> obj = new List<int> { 155109330, 155109340, 155109350, 155109360, 155109370, 155109380, 155109390, 155109400 };
					int num = 0;
					foreach (int item in obj)
					{
						if (GetBuffNum(_actor, item) == 0)
						{
							num++;
							continue;
						}
						break;
					}
					switch (num)
					{
					case 0:
					case 1:
					case 6:
						SetLogicTagFpValue(_actor, "LightDistance", 6.5);
						break;
					case 2:
					case 3:
					case 7:
						SetLogicTagFpValue(_actor, "LightDistance", 11.5);
						break;
					case 4:
					case 5:
						SetLogicTagFpValue(_actor, "LightDistance", 0);
						break;
					}
				}
				yield return WaitTime(0.1);
			}
		}

		private void CommonSummon()
		{
			SummonTeammate(5, GetPlaceHolderPosition("CommonSummonPoint1"), TSVector2.down, 4);
			SummonTeammate(5, GetPlaceHolderPosition("CommonSummonPoint2"), TSVector2.down, 4);
		}
	}
	public class Action_SmallBird : MonsterActionBase
	{
		private static readonly int Skill_Dash = 1551031;

		private static readonly int Skill_FlyUp = 1551032;

		private static readonly string Dash_Message = "CastDashSkill";

		private static readonly string FlyUp_Message = "CastFlyUpSkill";

		private static readonly int testSkillId = 0;

		protected override void SetConfig()
		{
			_monsterAIType = MonsterAIType.SEQUENCE;
			SetLogicTagStringValue(_actor, "SkillMessage", "WaitSkill");
			List<BaseBranchInfo> list = new List<BaseBranchInfo>();
			OperateDelegate operateIEnumerator = SkillCast;
			list.Add(new BaseBranchInfo(1001, default(FP), default(FP), default(FP), null, operateIEnumerator));
			List<BaseBranchInfo> sequenceBranches = list;
			Dictionary<int, List<int>> sequenceDict = new Dictionary<int, List<int>> { [1] = new List<int> { 1001, 1001 } };
			InitSequenceBranches(1, sequenceBranches, sequenceDict);
		}

		private void GotoCastSkill(int ID)
		{
			if (testSkillId != 0)
			{
				ID = testSkillId;
			}
			CastSkill(ID);
		}

		private IEnumerator SkillCast()
		{
			while (true)
			{
				string logicTagStringValue = GetLogicTagStringValue(_actor, "SkillMessage");
				if (logicTagStringValue == Dash_Message)
				{
					GotoCastSkill(Skill_Dash);
					yield return WaitSkillFinish();
				}
				else if (logicTagStringValue == FlyUp_Message)
				{
					GotoCastSkill(Skill_FlyUp);
					yield return WaitSkillFinish();
				}
				else
				{
					yield return null;
				}
			}
		}
	}
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private static readonly int area_tag = CommonHelper.StringToHash("FengNiaoUltraWarning");

		private const int num_dodge = 5;

		private int[] teamIDs = new int[4] { 1, 2, 3, 4 };

		private bool area_finish;

		private bool dodge_finish;

		private bool damadge_finish;

		private int num_dodge_current;

		private bool beHit;

		private bool enterArea;

		private List<int> monsterIds;

		public override void OnStart()
		{
			base.OnStart();
			num_dodge_current = 0;
			beHit = false;
			enterArea = false;
			area_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengNiao_001);
			dodge_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengNiao_002);
			damadge_finish = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FengNiao_003);
			if (!area_finish)
			{
				ModuleController<AdventureModuleController>.Instance.AddEventListener("AREA_EFFECT_ENTER_EXIT", OnAreaEnterOrExit);
			}
			if (!dodge_finish)
			{
				ModuleController<AdventureModuleController>.Instance?.AddEventListener("TRIGGER_PERFECTDODGE", OnTriggerPerfectDodge);
			}
			if (!damadge_finish)
			{
				monsterIds = new List<int>();
				for (int i = 0; i < teamIDs.Length; i++)
				{
					monsterIds.Add(CommonHelper.GetMonsterTeammateId(teamIDs[1], i));
				}
				ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			if (!area_finish)
			{
				ModuleController<AdventureModuleController>.Instance.RemoveEventListener("AREA_EFFECT_ENTER_EXIT", OnAreaEnterOrExit);
			}
			if (!dodge_finish)
			{
				ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("TRIGGER_PERFECTDODGE", OnTriggerPerfectDodge);
			}
			if (!damadge_finish)
			{
				ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			}
		}

		private void OnAreaEnterOrExit(IEvent evt)
		{
			AdventureAreaEnterExitEvent adventureAreaEnterExitEvent = evt as AdventureAreaEnterExitEvent;
			if (_actor != null && adventureAreaEnterExitEvent.triggerCollider?.Entity != null && adventureAreaEnterExitEvent.sender is AreaEffectEntity areaEffectEntity && areaEffectEntity.CheckTag(area_tag) && _player != null && adventureAreaEnterExitEvent.triggerCollider.Entity.Id == _player.Id)
			{
				enterArea = adventureAreaEnterExitEvent.iEnter;
			}
		}

		private void OnTriggerPerfectDodge(IEvent evt)
		{
			if (!((evt as AdventurePerfectDodgeTrigger).actor != _player) && MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel.RegionType == 2)
			{
				num_dodge_current++;
				if (num_dodge_current == 5)
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.FengNiao_002);
				}
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (_actor != null && adventureActorReceiveDamageEvent.to == _player && adventureActorReceiveDamageEvent.from is MonsterAdventureActor monsterAdventureActor && monsterIds != null && monsterIds.Contains(monsterAdventureActor.dataID))
			{
				beHit = true;
			}
		}

		public void OnUpdate()
		{
			if (!area_finish && _actor.logicVariable.GetLogicTagToggle("UltraSkillAchievementReady") && enterArea)
			{
				area_finish = true;
				ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.FengNiao_001);
			}
		}

		protected override void OnActorDied(IEvent e)
		{
			base.OnActorDied(e);
			if (e is AdventureActorDiedEvent adventureActorDiedEvent && adventureActorDiedEvent.actor.Id == _actor.Id && !(adventureActorDiedEvent.killer == null) && adventureActorDiedEvent.killer.Id != _actor.Id && !damadge_finish && !beHit)
			{
				ModuleController<AdventureModuleController>.Instance?.SetAchievementFinish(GameEnum.questCompleteCondClient.FengNiao_003);
			}
		}
	}
	public class SimpleAPI_FengNiao : SkillSimpleBase
	{
		protected IEnumerator FlashBeforeAttackForFengNiao(FP Radius = default(FP), FP InnerRadius = default(FP), FP UpRotation = default(FP), FP GoodShapeAngle = default(FP), FP MaxFlashDistance = default(FP), FP MinFlashDistance = default(FP), bool IsCombo = false)
		{
			ComboInputBuffer.ActionKey[] FlashFront_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._2 };
			ComboInputBuffer.ActionKey[] FlashBack_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._3 };
			FP FlashSpeed = 80;
			int TryTimes = 0;
			TSVector2 ShapePosition = GetEntityPosition(GetAttackTarget());
			TSVector2 FlashPosition = GetPosition();
			DeterministicShape GoodShape = GetShapeData(DeterministicShape.ShapeType.Fan, ShapePosition, default(FP), default(FP), Radius, InnerRadius, GoodShapeAngle, UpRotation);
			if (GetTargetsFromShape(GoodShape, null, includeSelf: true, _actor).Count != 0)
			{
				yield break;
			}
			while (TryTimes <= 20)
			{
				FlashPosition = GetShapeRandomPoint(GoodShape, _actor, isReachable: true);
				if (Distance(FlashPosition, ShapePosition) >= MinFlashDistance && Distance(FlashPosition, ShapePosition) <= MaxFlashDistance)
				{
					break;
				}
				TryTimes++;
				yield return null;
			}
			if (!(FlashPosition == ShapePosition))
			{
				ComboInputBuffer.ActionKey[] keys = ((!(AngleBetween2TSVector(GetForward(), FlashPosition - GetPosition(), signed: false) >= 90)) ? FlashFront_Combo : FlashBack_Combo);
				if (!IsCombo)
				{
					BeginAttack(99, keys, flushInputedKeys: true, forceInterruptAttack: true);
					yield return WaitCombo(ComboAttackType.isAnticipationEnd);
				}
				SetCloseBlockEnable();
				BeginLookAt_NotWait(GetAttackTarget(), 999, 999);
				BeginDash(99, FlashPosition - GetPosition(), FlashSpeed, Distance(FlashPosition, GetPosition()), 999, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
				yield return WaitDashFinish();
				StopWaitLookAt();
				if (!IsCombo)
				{
					CancelAttack();
				}
				SetCloseBlockDisable();
			}
		}

		protected IEnumerator FlashBeforeAttackForFengNiaoToFixedPosition(TSVector2 FixedPosition = default(TSVector2))
		{
			ComboInputBuffer.ActionKey[] array = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._2 };
			ComboInputBuffer.ActionKey[] array2 = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._3 };
			FP FlashSpeed = 50;
			ComboInputBuffer.ActionKey[] keys = ((!(AngleBetween2TSVector(GetForward(), FixedPosition - GetPosition(), signed: false) >= 90)) ? array : array2);
			BeginAttack(99, keys, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			SetCloseBlockEnable();
			BeginLookAt_NotWait(GetAttackTarget(), 999, 999);
			BeginDash(99, FixedPosition - GetPosition(), FlashSpeed, Distance(FixedPosition, GetPosition()), 999, comboWithAttack: true, isAngle: false, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			StopWaitLookAt();
			CancelAttack();
			SetCloseBlockDisable();
		}

		protected IEnumerator SummonBeforeSkillForFengNiao(string SendSkillMessage)
		{
			List<TSVector2> TargetPointOffset = new List<TSVector2>
			{
				new TSVector2(0, 2),
				new TSVector2(1, 1.5),
				new TSVector2(-1, 1.5),
				new TSVector2(-1.6, 0.5),
				new TSVector2(1.6, 0.5),
				new TSVector2(-2, -0.5),
				new TSVector2(2, -0.5)
			};
			List<TSVector2> list = new List<TSVector2>();
			List<LogicEntity> targetByTeammateIndexes = GetTargetByTeammateIndexes(new List<int> { 1, 2 });
			int FlowerBirdCount = 0;
			foreach (LogicEntity item in targetByTeammateIndexes)
			{
				if (GetLogicTagToggleValue(item, "Awaken"))
				{
					FlowerBirdCount++;
					list.Add(GetEntityPosition(item));
				}
			}
			if (list.Count > 0)
			{
				foreach (TSVector2 item2 in list)
				{
					SummonTeammate(3, TransLocalPosToWorldPos(item2, item2, new TSVector2(0, 2)), TSVector2.up);
				}
			}
			SummonTeammate(4, TransLocalPosToWorldPos(GetPosition(), GetForward(), TargetPointOffset[0]), GetForward());
			while (GetTargetsByLogicTag(LogicTagType._Bool, "SpawnComplete", GetTargetByTeammateIndexes(new List<int> { 3, 4 })).Count < FlowerBirdCount + 1)
			{
				yield return null;
			}
			List<LogicEntity> FlowerBird = GetTargetsByLogicTag(LogicTagType._Bool, "SpawnComplete", GetTargetByTeammateIndexes(new List<int> { 3, 4 }));
			int num = 0;
			foreach (LogicEntity item3 in FlowerBird)
			{
				TSVector2 tSVector = TransLocalPosToWorldPos(GetPosition(), GetForward(), TargetPointOffset[num]);
				TSVector2 tSVector2 = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 5));
				SetLogicTagFpValue(item3, "TargetPointX", tSVector.x);
				SetLogicTagFpValue(item3, "TargetPointY", tSVector.y);
				SetLogicTagFpValue(item3, "WatchPointX", tSVector2.x);
				SetLogicTagFpValue(item3, "WatchPointY", tSVector2.y);
				SetLogicTagStringValue(item3, "SkillMessage", SendSkillMessage);
				SetLogicTagToggleValue(item3, "SummonComplete", value: true);
				num++;
			}
			int CheckCount = 0;
			while (CheckCount < FlowerBirdCount + 1)
			{
				CheckCount = 0;
				foreach (LogicEntity item4 in FlowerBird)
				{
					if (GetLogicTagToggleValue(item4, "SpawnComplete"))
					{
						CheckCount++;
					}
				}
				yield return null;
			}
		}

		protected void FlowerShootStart()
		{
			foreach (LogicEntity targetByTeammateIndex in GetTargetByTeammateIndexes(new List<int> { 1, 2 }))
			{
				if (GetLogicTagToggleValue(targetByTeammateIndex, "Awaken"))
				{
					SetLogicTagToggleValue(targetByTeammateIndex, "Shoot", value: true);
				}
			}
		}

		protected IEnumerator WanderActForFengNiao()
		{
			yield return BeginLookAtMonsterTarget(0.25, 999);
			yield return BeginLookAtMonsterTarget(2, 90);
		}
	}
	public class Skill_ContiniousPeck : SimpleAPI_FengNiao
	{
		private static readonly ComboInputBuffer.ActionKey[] ContiniousPeck_Start_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.E };

		private static readonly ComboInputBuffer.ActionKey[] ContiniousPeck_NormalEnd_Combo = new ComboInputBuffer.ActionKey[1];

		private static readonly ComboInputBuffer.ActionKey[] ContiniousPeck_AnotherAttack_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		private static readonly ComboInputBuffer.ActionKey[] ContiniousPeck_Laser_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.C };

		private static readonly FP TraceSpeed = 2;

		private static readonly FP TraceTime = 2;

		private LogicEntity AttackTarget;

		private FP Phase;

		private long LaserLaunch_Collect_HeadFX;

		private long AimFX;

		private long LaserFX;

		private long LaserDecoration1FX;

		private long LaserDecoration2FX;

		private FP Difficulty;

		protected override void OnSkillEnable()
		{
			AttackTarget = GetAttackTarget();
			Phase = GetLogicTagFpValue(_actor, "BattleStage");
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
		}

		protected override void OnSkillDisable()
		{
			StopEffect(LaserFX);
			StopEffect(LaserDecoration1FX);
			StopEffect(LaserDecoration2FX);
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return WaitLookAt(AttackTarget, 0.25, 720);
			BeginAttack(1, ContiniousPeck_Start_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("Dash");
			yield return StartCor(FlashBeforeAttackForFengNiao(3, 2, 30, 360, 12, 1, IsCombo: true));
			yield return WaitLookAt(AttackTarget, 0.03, 9999);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginDashActorForward(1, TraceSpeed, TraceSpeed * TraceTime, 50, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false);
			yield return WaitDashFinish();
			if (Phase == 1)
			{
				BeginAttack(1, ContiniousPeck_NormalEnd_Combo);
				FlowerShootStart();
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
			else if (GetDistanceWithTarget(calcDistanceWithoutEntityRadius: false) <= 6 && Difficulty != 3)
			{
				PlayEffect("YuJingFlash", 1f, 2, GetPosition(), default(FP), 1.2f);
				BeginAttack(1, ContiniousPeck_AnotherAttack_Combo);
				BeginLookAt_NotWait(GetAttackTarget(isUpToDate: true), 0.3, 600);
				yield return WaitCombo(ComboAttackType.isAnticipationEnd);
				BeginDashActorForward(1, TraceSpeed, TraceSpeed * TraceTime, 50, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false);
				yield return WaitDashFinish();
				BeginAttack(1, ContiniousPeck_AnotherAttack_Combo);
				FlowerShootStart();
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
			else
			{
				yield return WaitLookAt(AttackTarget, 0.1, 1800);
				BeginAttack(1, ContiniousPeck_Laser_Combo);
				BeginLookAt_NotWait(AttackTarget, 999, 50);
				LaserLaunch_Collect_HeadFX = PlayEffect("LaserLaunch_Collect_Head_lv1FX");
				yield return WaitCustomEvent("Aimeline");
				Skill_ContiniousPeck skill_ContiniousPeck = this;
				Skill_ContiniousPeck skill_ContiniousPeck2 = this;
				FP rotation = GetRotation();
				skill_ContiniousPeck.AimFX = skill_ContiniousPeck2.PlayEffect("Laser_AimFX", 1f, default(FP), default(TSVector2), rotation);
				yield return WaitCombo(ComboAttackType.isAnticipationEnd);
				yield return StartCor(LaserAttackCor(2, 1));
				CancelAttack();
				FlowerShootStart();
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
		}

		private IEnumerator LaserAttackCor(int AimDurationFrame, int LaserDurationFrame)
		{
			int LaserDurationCount = 0;
			yield return WaitFrame(AimDurationFrame);
			StopEffect(LaserLaunch_Collect_HeadFX);
			StopEffect(AimFX);
			PlayEffect("Laser_ReadyFX");
			StopWaitLookAt();
			yield return WaitFrame(10);
			LaserDecoration1FX = PlayEffect("LaserDecorationFX1");
			yield return WaitFrame(1);
			LaserDecoration2FX = PlayEffect("LaserDecorationFX2");
			yield return WaitFrame(4);
			LaserFX = PlayEffect("LaserFX");
			while (LaserDurationCount < LaserDurationFrame)
			{
				Skill_ContiniousPeck skill_ContiniousPeck = this;
				TSVector2 position = TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 26.7));
				FP width = 1.5;
				FP length = 50;
				FP rotation = GetRotation();
				DeterministicShape shapeData = skill_ContiniousPeck.GetShapeData(DeterministicShape.ShapeType.Rectangle, position, width, length, default(FP), default(FP), default(FP), rotation);
				Skill_ContiniousPeck skill_ContiniousPeck2 = this;
				rotation = 0.5;
				FP hitStrenth = 4;
				HitFeatureData hitFeatureData = skill_ContiniousPeck2.GetHitFeatureData(HitBox.FeatureFlag.Stiff, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, rotation, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, hitStrenth);
				AreaHit_Simple(_actor, shapeData, hitFeatureData, 155100301, 0.5, HitBox.HurtAnimType.Large, "HittedFX_Magic");
				LaserDurationCount++;
				yield return null;
			}
			yield return WaitFrame(LaserDurationFrame);
			StopEffect(LaserFX);
			StopEffect(LaserDecoration1FX);
			StopEffect(LaserDecoration2FX);
			PlayEffect("LaserEndFX");
		}
	}
	public class Skill_Dash : SimpleAPI_FengNiao
	{
		private static readonly ComboInputBuffer.ActionKey[] Dash_Start_Combo = new ComboInputBuffer.ActionKey[2];

		private static readonly ComboInputBuffer.ActionKey[] Dash_Plus_Start_Combo = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.B,
			ComboInputBuffer.ActionKey.B
		};

		private static readonly ComboInputBuffer.ActionKey[] Dash_Plus_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		private static readonly ComboInputBuffer.ActionKey[] Dash_End_Combo = new ComboInputBuffer.ActionKey[1];

		private static readonly FP DashSpeed = 60;

		private static readonly FP DashDistance = 15;

		private LogicEntity AttackTarget;

		private FP Phase;

		private int BirdCount;

		private List<LogicEntity> Bird;

		private int BirdCountIndex;

		protected override void OnSkillEnable()
		{
			AttackTarget = GetAttackTarget();
			Phase = GetLogicTagFpValue(_actor, "BattleStage");
			BirdCountIndex = 0;
			Bird = new List<LogicEntity>();
		}

		protected override void OnSkillDisable()
		{
			StopWaitLookAt();
			Bird.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return WaitLookAt(AttackTarget, 0.25, 720);
			yield return StartCor(FlashBeforeAttackForFengNiao(9, 3, 30, 300, 6, 3));
			yield return WaitLookAt(AttackTarget, 0.1, 1800);
			if (Phase == 1)
			{
				yield return StartCor(DashAttackP1());
			}
			else
			{
				yield return StartCor(DashAttackP2());
			}
			yield return StartCor(WanderActForFengNiao());
		}

		private IEnumerator DashAttackP1()
		{
			BeginAttack(1, Dash_Start_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(AttackTarget, 999, 150);
			yield return WaitTime(0.3);
			StopWaitLookAt();
			Skill_Dash skill_Dash = this;
			TSVector2 position = GetPosition();
			FP rotation = GetRotation();
			skill_Dash.PlayEarlyWarningEffect("DashWarning", 0.75f, default(FP), position, rotation);
			yield return WaitTime(0.7);
			BeginDashActorForward(1, DashSpeed, DashDistance, 0, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private IEnumerator DashAttackP2()
		{
			yield return StartCor(SummonBeforeSkillForFengNiao("CastDashSkill"));
			Bird = GetTargetByTeammateIndexes(new List<int> { 3, 4 });
			BirdCount = Bird.Count;
			BeginAttack(1, Dash_Plus_Start_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			BeginLookAt_NotWait(AttackTarget, 999, 150);
			yield return WaitTime(0.3);
			StopWaitLookAt();
			SmallBirdDashAttack();
			Skill_Dash skill_Dash = this;
			TSVector2 position = GetPosition();
			FP rotation = GetRotation();
			skill_Dash.PlayEarlyWarningEffect("DashWarning", 0.75f, default(FP), position, rotation);
			yield return WaitTime(0.7);
			BeginDashActorForward(1, DashSpeed, DashDistance, 0, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			BeginAttack(3, Dash_Plus_Combo);
			AttackTarget = GetAttackTarget(isUpToDate: true);
			BeginLookAt_NotWait(AttackTarget, 999, 1500);
			yield return WaitTime(0.3);
			StopWaitLookAt();
			Skill_Dash skill_Dash2 = this;
			position = GetPosition();
			rotation = GetRotation();
			skill_Dash2.PlayEarlyWarningEffect("DashWarning", 0.75f, default(FP), position, rotation);
			yield return WaitTime(0.4);
			BeginDashActorForward(1, DashSpeed, DashDistance, 0, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			CancelAttack();
			FlowerShootStart();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void SmallBirdDashAttack()
		{
			FP value = 0;
			while (BirdCountIndex < BirdCount)
			{
				SetLogicTagFpValue(Bird[BirdCountIndex], "AttackTime", value);
				BirdCountIndex++;
				value += (FP)0.25;
			}
		}
	}
	public class Skill_FlowerAwaken : SimpleAPI_FengNiao
	{
		private static readonly ComboInputBuffer.ActionKey[] CallFlowerNormal_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.H };

		private static readonly ComboInputBuffer.ActionKey[] CallFlowerPlus_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.I };

		private FP TmpDistance;

		private TSVector2 ChosenPoint;

		private TSVector2 SelfPosition;

		private ComboInputBuffer.ActionKey[] CallFlower_Combo;

		private FP Phase;

		private FP Difficulty;

		private FP LightDistance;

		private bool IsTwice;

		private List<TSVector2> ChosenPointList;

		protected override void OnSkillEnable()
		{
			ChosenPointList = new List<TSVector2>
			{
				GetPlaceHolderPosition("WakeUpFlowerPoints1"),
				GetPlaceHolderPosition("WakeUpFlowerPoints2"),
				GetPlaceHolderPosition("WakeUpFlowerPoints3"),
				GetPlaceHolderPosition("WakeUpFlowerPoints4"),
				GetPlaceHolderPosition("WakeUpFlowerPoints5")
			};
			Phase = GetLogicTagFpValue(_actor, "BattleStage");
			Difficulty = GetLogicTagFpValue(_actor, "Difficulty");
			SetLogicTagToggleValue(_actor, "InFlowerAwakenSkill", value: true);
			if (Phase == 1)
			{
				CallFlower_Combo = CallFlowerNormal_Combo;
				LightDistance = 11;
			}
			else
			{
				CallFlower_Combo = CallFlowerPlus_Combo;
				LightDistance = 16;
			}
			if (Phase == 2 && Difficulty == 3)
			{
				IsTwice = true;
			}
			else
			{
				IsTwice = false;
			}
		}

		protected override void OnSkillDisable()
		{
			SetLogicTagToggleValue(_actor, "FastRecoverFlower", value: false);
			SetLogicTagToggleValue(_actor, "FlowerAwakening", value: false);
			SetLogicTagToggleValue(_actor, "InFlowerAwakenSkill", value: false);
		}

		protected override IEnumerator DoMainLogic()
		{
			ChooseNearestPoint();
			yield return StartCor(FlashBeforeAttackForFengNiaoToFixedPosition(ChosenPoint));
			BeginAttack(1, CallFlower_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCustomEvent("FastRecover");
			SetLogicTagToggleValue(_actor, "FastRecoverFlower", value: true);
			SetLogicTagToggleValue(_actor, "FlowerAwakening", value: true);
			yield return null;
			SetLogicTagFpValue(_actor, "LightDistance", LightDistance);
			yield return WaitCombo(ComboAttackType.isComboFinish);
			SetLogicTagToggleValue(_actor, "FastRecoverFlower", value: false);
			SetLogicTagToggleValue(_actor, "FlowerAwakening", value: false);
			if (IsTwice)
			{
				ChosenPoint = ChosenPointList[(int)(long)GetRandomValue(0, 4, isInt: true)];
				yield return StartCor(FlashBeforeAttackForFengNiaoToFixedPosition(ChosenPoint));
				BeginAttack(1, CallFlower_Combo, flushInputedKeys: true, forceInterruptAttack: true);
				yield return WaitCustomEvent("FastRecover");
				SetLogicTagToggleValue(_actor, "FastRecoverFlower", value: true);
				SetLogicTagToggleValue(_actor, "FlowerAwakening", value: true);
				yield return null;
				SetLogicTagFpValue(_actor, "LightDistance", LightDistance);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				SetLogicTagToggleValue(_actor, "FastRecoverFlower", value: false);
				SetLogicTagToggleValue(_actor, "FlowerAwakening", value: false);
			}
			if (Difficulty == 1)
			{
				yield return WaitTime(4);
			}
			else
			{
				yield return WaitTime(1.5);
			}
		}

		private void ChooseNearestPoint()
		{
			SelfPosition = GetPosition();
			TmpDistance = 99;
			foreach (TSVector2 chosenPoint in ChosenPointList)
			{
				FP fP = Distance(chosenPoint, SelfPosition);
				if (fP < TmpDistance && fP >= 2)
				{
					ChosenPoint = chosenPoint;
					TmpDistance = fP;
				}
			}
			ChosenPointList.Remove(ChosenPoint);
		}
	}
	public class Skill_Flower_Bomb : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Bomb_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.C };

		private static readonly int BulletAmount = 16;

		private static readonly FP ShootIntervaltime = 0.15;

		private static readonly FP AreaMoveSpeedLv1_2 = 2;

		private static readonly FP AreaMoveSpeedLv3 = 3;

		private long ChargeFX;

		private int BulletCount;

		private TSVector2 ShootPosition;

		private DeterministicShape AttackShape;

		private long AttackShapeAreaID;

		private AreaEffectEntity AttackShapeArea;

		private CoroutineNode MoveAttackAreaCorNode;

		private string AreaEffect_Bomb_Warning;

		private FP Difficulty;

		private FP AreaMoveSpeed;

		private FP AreaMagnification;

		private FP IsMoving;

		private LogicEntity MasterBird;

		protected override void OnSkillEnable()
		{
			BulletCount = 0;
			IsMoving = 0;
			StartCor(CheckUltraSkill());
			AreaEffect_Bomb_Warning = "AreaEffect_Bomb_Warning_S_Lv3";
			AreaMoveSpeed = AreaMoveSpeedLv3;
			AreaMagnification = 1;
		}

		protected override void OnSkillDisable()
		{
			StopEffect(ChargeFX);
			StopAreaEffect(AttackShapeAreaID);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Bomb_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			SetLogicTagToggleValue(_actor, "ActiveHurt", value: true);
			ChargeFX = PlayEffect("ChargeFX");
			yield return WaitTime(0.5);
			ReplaceAnimationGroup();
			AttackShapeAreaID = PlayAreaEffect(AreaEffect_Bomb_Warning, TransLocalPosToWorldPos(GetPosition(), GetForward(), new TSVector2(0, 4)));
			AttackShapeArea = GetAreaEffect(AttackShapeAreaID);
			if (AttackShapeArea == null)
			{
				NovaLogger.Error("蜂鸟花的攻击区域创建失败，技能直接跳过");
				InterruptSkill();
			}
			yield return WaitTime(0.5);
			StartCor(ref MoveAttackAreaCorNode, MoveAttackAreaCor());
			while (BulletCount < BulletAmount)
			{
				Skill_Flower_Bomb skill_Flower_Bomb = this;
				Skill_Flower_Bomb skill_Flower_Bomb2 = this;
				TSVector2 position = TransLocalPosToWorldPos(AttackShapeArea.tsTransform.Position, GetEntityPosition(GetAttackTarget(isUpToDate: true)) - AttackShapeArea.tsTransform.Position, new TSVector2(0, AreaMoveSpeed * 0.03 * IsMoving));
				FP radius = 1.5 * AreaMagnification;
				FP innerRadius = 0;
				skill_Flower_Bomb.AttackShape = skill_Flower_Bomb2.GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), radius, innerRadius);
				ShootPosition = GetShapeRandomPoint(AttackShape, _actor, isReachable: true);
				PlayEffect("BombShootFX", 1f, default(FP), default(TSVector2), default(FP), 1f, actorScale: true);
				FanMultipleShoot("Weapon_ParabolaBird", AdventureWeapon.MultipleShootStyle.FromLeftToRight, alignShoot: false, 0, 1, 0, GetPosition(), 2.4, GetForward(), 0, AimType.Position, BulletDirectionType.BulletToTarget, 1, 1, 0, ShootPosition);
				BulletCount++;
				yield return WaitTime(ShootIntervaltime);
			}
			StopEffect(ChargeFX);
			StopCor(MoveAttackAreaCorNode);
			IsMoving = 0;
			CancelAttack();
			yield return WaitTime(0.5);
			StopAreaEffect(AttackShapeAreaID);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private IEnumerator MoveAttackAreaCor()
		{
			yield return WaitTime(1);
			IsMoving = 1;
			while (true)
			{
				if (Distance(AttackShapeArea.tsTransform.Position, GetEntityPosition(GetAttackTarget(isUpToDate: true))) > 0.2)
				{
					AttackShapeArea.tsTransform.Position += (GetEntityPosition(GetAttackTarget(isUpToDate: true)) - AttackShapeArea.tsTransform.Position).normalized * AreaMoveSpeed / 30;
				}
				yield return null;
			}
		}

		private IEnumerator CheckUltraSkill()
		{
			MasterBird = GetTargetByTeammateIndex(0)[0];
			while (!GetLogicTagToggleValue(MasterBird, "InterruptShootSkill"))
			{
				yield return null;
			}
			InterruptSkill();
		}
	}
