	public class Spawn : AIBase
	{
		public void OnStart()
		{
			int spawnSkillId = (_actor as MonsterAdventureActor).monsterAIInfo.spawnSkillId;
			if (spawnSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(spawnSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
				{
					_actor.Idle();
				});
			}
			else
			{
				_actor.Idle();
			}
		}
	}
