				WaitMoveStatus();
			}
			else
			{
				BeginAttack(1, actionKeys_H, flushInputedKeys: true);
				yield return WaitTime(1.3);
				int num = 40;
				doDash(dis, num);
				yield return WaitDashFinish();
				CancelAttack();
			}
			yield return WaitTime(0.1);
			BeginLookAtCameraDir(DirectionType.Down, 0, 700);
			yield return WaitTime(0.2);
			BeginAttack(2, _actionKeys, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1.2);
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(-9, 5.5));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(-9, -5.5));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(9, 5.5));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(9, -5.5));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(5.5, 9));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(-5.5, 9));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(5.5, -9));
			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(-5.5, -9));
			yield return WaitTime(0.9);
			PlayAreaEffect(ElectricWall, new TSVector2(0, 10));
			PlayAreaEffect(ElectricWall, new TSVector2(0, -10));
			PlayAreaEffect(ElectricWall, new TSVector2(-10, 0), 90);
			PlayAreaEffect(ElectricWall, new TSVector2(10, 0), 90);
			yield return WaitTime(1);
			StartCoroutine(makeRing());
			StartCoroutine(FallenMissles());
			yield return WaitTime(10);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}

		private void doDash(FP dis, FP dash_spd)
		{
			BeginDashActorForward(1, dash_spd, dis, 40, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
		}

		private IEnumerator makeRing()
		{
			for (float skilltime = 8f; skilltime > 0f; skilltime -= 4f)
			{
				PlayAreaEffect(LightRing, GetEntityPosition(_actor));
				yield return WaitTime(4);
			}
		}

		private IEnumerator FallenMissles()
		{
			for (float time = 6f; time > 0f; time -= 1f)
			{
				PlayAreaEffect(FallenMissle, GetEntityPosition(GetAttackTarget()));
				yield return WaitTime(1.0);
			}
		}

