	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private int hitDmgTotle;

		public override void OnStart()
		{
			base.OnStart();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			hitDmgTotle = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.to as PlayerAdventureActor != null)
			{
				hitDmgTotle += adventureActorReceiveDamageEvent.value;
			}
		}

		public override void OnDied(int monsterId)
		{
			if (monsterId == _actor.dataID && hitDmgTotle <= 0 && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.XiaoGaoDa_001))
			{
				ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.XiaoGaoDa_001);
			}
		}
	}
