			FanMultipleShoot(missilebullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 0, 1, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Position, BulletDirectionType.BulletToTarget, 30, 10, 0, new TSVector2(-8.7, -5));
			yield return WaitTime(2);
			FanMultipleShoot(windbullet, AdventureWeapon.MultipleShootStyle.FromCenterToSide, alignShoot: true, 1, 3, 0, _actor.tsTransform.Position, 1, GetEntityForward(_actor), 0, AimType.Default, BulletDirectionType.ActorToBullet, 360, 10, 2);
			yield return WaitTime(2);
