		{
			bool item = false;
			int item2 = 0;
			int item3 = 0;
			switch (alias)
			{
			case "A1":
				item = true;
				item2 = skillId_hand_smashFloor;
				break;
			case "A2":
				item = true;
				item2 = skillId_hand_laser;
				break;
			case "A3":
				item = true;
				item2 = skillId_hand_rocket;
				break;
			case "A4":
				item = true;
				item2 = skillId_hand_rocket_smashFloor;
				break;
			case "B1":
				item2 = skillId_strafe;
				break;
			case "B1L":
				item3 = 1;
				item2 = skillId_strafe;
				break;
			case "B1R":
				item3 = 2;
				item2 = skillId_strafe;
				break;
			case "B2":
				item2 = skillId_laser;
				break;
			case "B3L":
				item3 = 1;
				item2 = skillId_strafe_laser;
				break;
			case "B3R":
				item3 = 2;
				item2 = skillId_strafe_laser;
				break;
			case "D1":
				item2 = skillId_aoe_laser;
				break;
