		protected override void OnClear()
		{
			base.OnClear();
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
			isDashing = false;
			isCharge = false;
			isTimeing = false;
			isLook = false;
			_actor.UnlockHp();
			_actor.buffComponent.RemoveBuffByBuffId(buffId);
			StopCoroutine(ref corTiming);
			StopCoroutine(ref corDashCheck);
			_dodge?.Interrupte();
