		protected override void SetListenEvents()
		{
			InitListenEvent(MonsterEventType.SelfReceiveDamage, active: true, OnReceiveDamage);
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(startKeyIndex1, startKey1, flushInputedKeys: true);
			while (!isCharge)
			{
				yield return null;
			}
			isDashing = true;
			if (_dash == null)
			{
				_dash = new Dash();
			}
			TSVector2 normalized = _actor.tsTransform.Forward.normalized;
			_dash.BeginDash(_actor, normalized, dashSpeed, dashDistance, (FP)12, (System.Action)onDashFin, (System.Action)onDashFin, (System.Action)onDashFin, true, true, false, false, false, false, false, default(FP), true);
			StartCoroutine(ref corDashCheck, DashCheck());
			while (isDashing)
			{
				yield return null;
			}
			StopCoroutine(ref corTiming);
			StopCoroutine(ref corDashCheck);
			isTimeing = false;
			LogicEntity monsterTarget = _actor.monsterTarget;
			if (CommonUtils.CheckTargetIsValid(monsterTarget, 0L))
			{
				FP fP = TSVector2.Distance(monsterTarget.tsTransform.Position, _actor.tsTransform.Position);
				if (fP < stopMinDistance || fP > stopDistance)
				{
					isLook = false;
					_actor.InterruptAttack(force: true);
