			{
				isCharge = true;
				isTimeing = true;
				StartCoroutine(ref corTiming, IenTimeing());
			}
			else if (eventName.Equals(StopTurn04))
			{
				isLook = false;
			}
			else if (eventName.Equals(Dodge01))
			{
				DoDodge();
			}
			else if (eventName.Equals(FreezeHP))
			{
				_actor.LockHpAbs(iFP.op_Implicit(_actor.actorHealthInfo.hp));
			}
			else if (eventName.Equals(RecoveryHP))
			{
				_actor.UnlockHp();
			}
		}

		private void DoDodge()
		{
			LogicEntity monsterTarget = _actor.monsterTarget;
			if (CommonUtils.CheckTargetIsValid(monsterTarget, 0L))
			{
				FP fP = TSVector2.Distance(monsterTarget.tsTransform.Position, _actor.tsTransform.Position);
				if (fP < dodgeDis)
				{
					fP = dodgeDis;
				}
				if (_dodge == null)
				{
					_dodge = new Dodge();
				}
				_dodge.Begin(_actor, _actor.tsTransform.Forward.normalized, dodgeTime, fP, null, comboWithAttack: true);
			}
			else
			{
				InterruptSkill();
			}
		}

		private void OnReceiveDamage(IEvent iEvt)
		{
			if ((iEvt as AdventureActorReceiveDamageEvent).to == _actor && isTimeing)
			{
				PlayFx(fxName, fxSpeed, fxPosY, _actor.tsTransform.Position, _actor.tsTransform.Rotation, null, fxScale, fxPlayerScale);
			}
		}

		private IEnumerator IenTimeing()
		{
			yield return WaitTime(waitTimeing);
			isTimeing = false;
			isDashing = false;
			_actor.InterruptAttack(force: true);
		}

		private IEnumerator DashCheck()
		{
			yield return WaitTime(dashCheckInterval);
			LogicEntity monsterTarget = _actor.monsterTarget;
			if (CommonUtils.CheckTargetIsValid(monsterTarget, 0L))
			{
				if (TSVector2.Distance(monsterTarget.tsTransform.Position, _actor.tsTransform.Position) < stopMinDistance)
				{
					isLook = false;
					isDashing = false;
					_actor.InterruptAttack(force: true);
				}
				else
				{
					StartCoroutine(ref corDashCheck, DashCheck());
				}
			}
			else
			{
				InterruptSkill();
			}
		}

		public void OnUpdate()
		{
			if (isLook)
			{
				LogicEntity monsterTarget = _actor.monsterTarget;
				if (CommonUtils.CheckTargetIsValid(monsterTarget, 0L))
				{
					_actor.LookAt(monsterTarget.tsTransform.Position, 0);
				}
			}
			if (isDashing && _dash != null)
			{
				TSVector2 normalized = _actor.tsTransform.Forward.normalized;
				_dash._direction = normalized;
			}
		}

		protected void onDashFin()
		{
			_dash?.Interrupte();
			isDashing = false;
		}
	}
	public class Skill_StarMoonField_Area_LD : SkillSimpleBase
	{
		private readonly string GroundFx_appear = "Actor/Monster/13041MiNieWa/FX/fx_m13041_loop_skill6_ground";

		private readonly string GroundFx_Disappear = "Actor/Monster/13041MiNieWa/FX/fx_m13041_base_skill6_ground_disappear";

		private readonly string GroundFx_Charge = "Actor/Monster/13041MiNieWa/FX/fx_m13041_loop_skill6_charge";

		private readonly string MineWarning = "Actor/Monster/13041MiNieWa/FX/fx_m13041_base_skill6_ground_warning";

		private readonly string MineATK = "Actor/Monster/13041MiNieWa/FX/fx_m13041_base_skill6_ground_attack";

		private List<long> _Fx = new List<long>();

		private TSVector2 ZeroPOS = new TSVector2(20.5, 85);

		private List<LogicEntity> _entities = new List<LogicEntity>();

		private CoroutineNode MaxRunningTime;

		private CoroutineNode CheckPlayer;

		private CoroutineNode AttackPlayer;

		protected override void OnSkillEnable()
		{
			_Fx.Clear();
		}

		protected override void OnSkillDisable()
		{
			_entities.Clear();
			for (int i = 0; i < _Fx.Count; i++)
			{
				StopEffect(_Fx[i]);
			}
			StopCor(CheckPlayer);
			StopCor(AttackPlayer);
		}

		protected override IEnumerator DoMainLogic()
		{
			MaxRunningTime = StartCor(SkillLimit());
			TSVector2 targetPOS = ZeroPOS;
			_Fx.Add(PlayEffect(GroundFx_Charge, 1f, default(FP), targetPOS));
			yield return WaitTime(2.9);
			CheckPlayer = StartCor(MineArea());
			_Fx.Add(PlayEffect(GroundFx_appear, 1f, default(FP), targetPOS));
			yield return WaitTime(20);
			StopCor(CheckPlayer);
			for (int i = 0; i < _Fx.Count; i++)
			{
				StopEffect(_Fx[i]);
			}
			_Fx.Add(PlayEffect(GroundFx_Disappear, 1f, default(FP), targetPOS));
			yield return WaitTime(3);
			StopCor(MaxRunningTime);
		}

		protected IEnumerator SkillLimit()
		{
			for (int i = 0; i < 25; i++)
			{
				if (GetTargetsByFaction(isFriend: true).Count <= 0)
				{
					InterruptSkill();
					yield return null;
				}
				yield return WaitTime(1);
			}
			InterruptSkill();
			yield return null;
		}

		protected IEnumerator MineArea()
		{
			TSVector2 zeroPOS = ZeroPOS;
			int num = 15;
			int num2 = 6;
			DeterministicShape ShapeData = GetShapeData(DeterministicShape.ShapeType.Circle, zeroPOS, default(FP), default(FP), num, num2);
			for (int i = 0; i < 100; i++)
			{
				_entities.AddRange(GetTargetsFromShape(ShapeData));
				if (_entities.Contains(GetCurrentPlayer()))
				{
					AttackPlayer = StartCor(Mine());
				}
				_entities.Clear();
				yield return WaitTime(0.2);
			}
		}

		protected IEnumerator Mine()
		{
			TSVector2 targetPOS = GetEntityPosition(GetCurrentPlayer());
			PlayEffect(MineWarning, 1f, default(FP), targetPOS);
			yield return WaitTime(1);
			PlayEffect(MineATK, 1f, default(FP), targetPOS);
			int num = 1;
			int num2 = 0;
			DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, targetPOS, default(FP), default(FP), num, num2);
			HitFeatureData hitFeatureData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
			LogicEntity monsterCloner = GetMonsterCloner();
			LogicEntity targetByID = GetTargetByID(long.Parse(GetLogicTagStringValue(monsterCloner, "MiniewaID")));
			AreaHit_Simple(targetByID, shapeData, hitFeatureData, 13041060, 0.3, HitBox.HurtAnimType.Small, "Actor/Monster/13041MiNieWa/FX/fx_13041_hit_skill3");
		}
	}
	public class Skill_StarMoonField_LD : SkillSimpleBase
	{
		private static readonly int DodgeIndex = 0;

		private static readonly string DodgeKey = "Dodge";

		private static readonly int StarMoonIndex = 1;

		private static readonly string StarMoonKey = "StarMoon";

		private static readonly string groundAreaFx = "StarMoonField";

		private static readonly string chargFx = "StarMoonField_Charge";

		private static readonly string disappearFx = "fx_m13041_base_skill6_ground_disappear";

		private List<long> _fx = new List<long>();

		private static readonly int DashIndex = 10;

		protected override void OnSkillEnable()
		{
			SetLogicTagStringValue(_actor, "MiniewaID", GetTargetID(_actor).ToString());
			_fx.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			yield return StartCor(BackPOS0());
			yield return StartCor(StarMoon());
		}

		protected IEnumerator BackPOS0()
		{
			TSVector2 tSVector = new TSVector2(20.5, 86);
			BeginLookAtByPos_NotWait(tSVector, 0.2, 9999);
			BeginAttack(DodgeIndex, DodgeKey, flushInputedKeys: true, forceInterruptAttack: true);
			SetCloseBlockEnable();
			SetBattleOutEnable();
			TSVector2 position = GetPosition();
			TSVector2 direction = tSVector - position;
			FP fP = Distance(position, tSVector);
			FP speed = fP / 0.3;
			BeginDash(DashIndex, direction, speed, fP, 999, comboWithAttack: true, isAngle: true, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
			yield return WaitDashFinish();
			tSVector = new TSVector2(20.5, 85);
			BeginLookAtByPos_NotWait(tSVector, 0.2, 9999);
			SetBattleOutDisable();
			SetCloseBlockDisable();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			yield return null;
		}

		protected IEnumerator StarMoon()
		{
			BeginAttack(StarMoonIndex, StarMoonKey, flushInputedKeys: true, forceInterruptAttack: true);
			UseMonsterCloneActorCastSkill(1304110);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return WaitTime(0.2);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
