	public class Skill_Cut : SkillAdvancedBase
	{
		private readonly ComboInputBuffer.ActionKey _actionKeyStart;

		private readonly FP loopTime = 0;

		private readonly ComboInputBuffer.ActionKey _DodgeStart = ComboInputBuffer.ActionKey.I;

		private CoroutineNode corMain;

		private CoroutineNode corSkill;

		private readonly LookAtTarget _lookAtTarget = new LookAtTarget();

		private readonly AimTarget _aimTarget = new AimTarget();

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			_aimTarget?.Clear();
		}

		private IEnumerator DoMainLogic()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			FP fP = TSVector2.Distance(_actor.tsTransform.Position, activedPlayerActor.tsTransform.Position);
			bool rotateFinish = false;
			if (fP >= 2)
			{
				_actor.EnableImmuneControl();
				_actor.PauseMovementBlock();
				activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				_lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, 3600, delegate
				{
					rotateFinish = true;
				});
				while (!rotateFinish)
				{
					yield return null;
				}
				RequestComboAttack requestComboAttack1 = BeginAttack(_DodgeStart, flushInputedKeys: true);
				while (!requestComboAttack1.isAnticipationEnd)
				{
					yield return null;
				}
				_actor.DisableImmuneControl();
				_actor.ResumeMovementBlock();
			}
			activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			_lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			RequestComboAttack requestComboAttack2 = BeginAttack(_actionKeyStart, flushInputedKeys: true);
			while (!requestComboAttack2.isAnticipationEnd)
			{
				yield return null;
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(loopTime));
			requestComboAttack2 = BeginAttack(_actionKeyStart);
			while (!requestComboAttack2.isComboFinish)
			{
				yield return null;
			}
			_skill?.Clear();
		}
	}
	public class Skill_Cut2 : SkillAdvancedBase
	{
		private readonly ComboInputBuffer.ActionKey _cutStart;

		private readonly ComboInputBuffer.ActionKey _cutEnd;

		private readonly ComboInputBuffer.ActionKey _cut2Start = ComboInputBuffer.ActionKey.B;

		private readonly ComboInputBuffer.ActionKey _cut2End;

		private readonly ComboInputBuffer.ActionKey _DodgeStart = ComboInputBuffer.ActionKey.I;

		private FP cutloopTime = 0;

		private FP cut2loopTime = 0.1;

		private CoroutineNode corMain;

		private CoroutineNode corSkill;

		private readonly LookAtTarget _lookAtTarget = new LookAtTarget();

		private readonly AimTarget _aimTarget = new AimTarget();

		private bool isLoop;

		private RequestComboAttack requestComboAttack;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			StopCoroutine(ref corSkill);
			_aimTarget?.Clear();
		}

		private IEnumerator DoMainLogic()
		{
			isLoop = false;
			StartCoroutine(ref corSkill, SkillAction(_cutStart, _cutEnd, 0, ComboAttackType.isAnticipationEnd));
			while (!isLoop)
			{
				yield return null;
			}
			isLoop = false;
			StartCoroutine(ref corSkill, SkillAction(_cut2Start, _cut2End, 0, ComboAttackType.isComboFinish));
			while (!isLoop)
			{
				yield return null;
			}
			_skill?.Clear();
		}

		private IEnumerator SkillAction(ComboInputBuffer.ActionKey keyStart, ComboInputBuffer.ActionKey keyEnd, FP loopTime, ComboAttackType comboAttackType)
		{
			bool rotateFinish = false;
			LogicEntity target = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			System.Random random = new System.Random();
			if (TSVector2.Distance(_actor.tsTransform.Position, target.tsTransform.Position) > 3 && random.Next(0, 100) > 30)
			{
				_actor.EnableImmuneControl();
				_actor.PauseMovementBlock();
				target = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				_lookAtTarget.BeginLookAt(_actor, target, 0, 3600, delegate
				{
					rotateFinish = true;
				});
				while (!rotateFinish)
				{
					yield return null;
				}
				requestComboAttack = BeginAttack(_DodgeStart, flushInputedKeys: true);
				while (!requestComboAttack.isComboFinish)
				{
					yield return null;
				}
				_actor.DisableImmuneControl();
				_actor.ResumeMovementBlock();
			}
			_lookAtTarget.BeginLookAt(_actor, target, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			requestComboAttack = BeginAttack(keyStart, flushInputedKeys: true);
			while (!requestComboAttack.isAnticipationEnd)
			{
				yield return null;
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(loopTime));
			requestComboAttack = BeginAttack(keyEnd);
			if (comboAttackType != ComboAttackType.isAnticipationEnd)
			{
				if (comboAttackType == ComboAttackType.isRecoveryBegin)
				{
					while (!requestComboAttack.isRecoveryBegin)
					{
						yield return null;
					}
				}
				else
				{
					while (!requestComboAttack.isComboFinish)
					{
						yield return null;
					}
				}
			}
			else
			{
				while (!requestComboAttack.isAnticipationEnd)
				{
					yield return null;
				}
			}
			isLoop = true;
		}
	}
	public class Skill_Dash_Back : SkillAdvancedBase
	{
		private readonly ComboInputBuffer.ActionKey _actionKeyStart = ComboInputBuffer.ActionKey.G;

		private readonly ComboInputBuffer.ActionKey _actionKeyEnd;

		private readonly FP backDistance = 8;

		private readonly FP dashSpeed = 30;

		private CoroutineNode corMain;

		private readonly LookAtTarget _lookAtTarget = new LookAtTarget();

		private readonly AimTarget _aimTarget = new AimTarget();

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			_aimTarget?.Clear();
		}

		private IEnumerator DoMainLogic()
		{
			bool rotateFinish = false;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			_lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			RequestComboAttack requestComboAttack = BeginAttack(_actionKeyStart, flushInputedKeys: true);
			while (!requestComboAttack.isAnticipationEnd)
			{
				yield return null;
			}
			TSVector2 desPos = default(TSVector2);
			if (SearchValidPoint(ref desPos))
			{
				FP fP = backDistance / dashSpeed;
				_actor.Dodge((desPos - _actor.tsTransform.Position).normalized, backDistance, fP, null, null, comboWithAttack: true, canRotate: false);
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(fP));
				BeginAttack(_actionKeyEnd, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, delegate
				{
					_skill?.Clear();
				});
			}
			else
			{
				_skill?.Clear();
			}
		}

		private bool SearchValidPoint(ref TSVector2 desPos)
		{
			desPos = _actor.tsTransform.Position - backDistance * _actor.tsTransform.Forward;
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			FP angleBase = TSVector2.Angle(-_actor.tsTransform.Forward, TSVector2.up);
			desPos = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, backDistance, backDistance, angleBase, 120);
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			desPos = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, backDistance, backDistance, angleBase, 180);
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			desPos = _actor.tsTransform.Position + backDistance * _actor.tsTransform.Forward;
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			desPos = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, backDistance, backDistance, 180, 360);
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			desPos = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, 6, 10, 180, 360);
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			return false;
		}
	}
