	public class Skill_Passtive_AddBuff : SkillAdvancedBase
	{
		private readonly int buffId = 110410210;

		private readonly int hpPercent = 20;

		private readonly int delayTime = 10;

		private int totleDamage;

		private bool isAnysis;

		private FP timer;

		private CoroutineNode _cdCoroutine;

		private CoroutineNode corMain;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
			Clear();
		}

		public void OnStart()
		{
			_actor.EnableLogicUpdate();
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnDamage);
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			StopCoroutine(ref _cdCoroutine);
		}

		protected override void OnActorLostControl(IEvent evt)
		{
		}

		private IEnumerator DoMainLogic()
		{
			AddBuff();
			yield return null;
		}

		private void AddBuff()
		{
			BuffCom logicComponent = _actor.GetLogicComponent<BuffCom>();
			if (!logicComponent.CheckBuffByBuffID(buffId))
			{
				logicComponent?.AddBuff(buffId, _actor);
			}
			isAnysis = true;
		}

		private void OnDamage(IEvent evt)
		{
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Unknown result type (might be due to invalid IL or missing references)
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.to == _actor && isAnysis)
			{
				totleDamage += adventureActorReceiveDamageEvent.value;
				iFP val = _actor.actorHealthInfo.hpMax * hpPercent / 100;
				if (totleDamage >= iFP.op_Implicit(val))
				{
					_actor.GetLogicComponent<BuffCom>()?.RemoveBuffByBuffId(buffId);
					totleDamage = 0;
					timer = delayTime;
					StartCoroutine(ref _cdCoroutine, cdHandler());
					isAnysis = false;
				}
			}
		}

		private IEnumerator cdHandler()
		{
			while (timer > 0)
			{
				timer -= _actor.LogicDeltaTime;
				yield return null;
			}
			StopCoroutine(ref _cdCoroutine);
			AddBuff();
		}
	}
	public class Skill_Passtive_Dodge : SkillAdvancedBase
	{
		private int aiId;

		private int skillCD;

		private int lostCtrTime;

		private int notLostCtrTime;

		private CoroutineNode corMain;

		private FP lostControllerTime;

		private FP controllableTime;

		private FP cd;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			_actor.EnableLogicUpdate();
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
		}

		private IEnumerator DoMainLogic()
		{
			cd = skillCD;
			while (true)
			{
				if (cd <= 0)
				{
					cd = skillCD;
					lostControllerTime = 0;
					controllableTime = 0;
				}
				else if (_actor.isLostControl)
				{
					controllableTime = 0;
					lostControllerTime += _actor.LogicDeltaTime;
					if (lostControllerTime > lostCtrTime)
					{
						_actor.InterruptForceControl();
						AdventureCustomHandleAiBranchEvent adventureCustomHandleAiBranchEvent = AdventureCustomHandleAiBranchEvent.Generate();
						adventureCustomHandleAiBranchEvent.target = _actor;
						adventureCustomHandleAiBranchEvent.eventType = GameEnum.monsterAIBranchFollowEventType.EXECUTE_CERTAIN_ID_AI;
						adventureCustomHandleAiBranchEvent.ids = new List<int> { aiId };
						ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureCustomHandleAiBranchEvent);
					}
				}
				else
				{
					controllableTime += _actor.LogicDeltaTime;
					if (controllableTime > notLostCtrTime)
					{
						lostControllerTime = 0;
					}
				}
				cd -= _actor.LogicDeltaTime;
				yield return null;
			}
		}
	}
