			}, (System.Action)delegate
			{
				dashStatus = DashStatus.DashObstacle;
			}, true, false, true, false, false, false, false, default(FP), true);
			while (!requestComboAttack.isComboFinish)
			{
				yield return null;
			}
			_skill?.Clear();
		}
	}
