			TSVector2 dir = TSVector2.Rotate(_actor.tsTransform.Forward, 45);
			rotateFinish = false;
			_lookAtTarget.BeginLookAtByPos(_actor, _actor.tsTransform.Position + dir.normalized, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			requestComboAttack = BeginAttack(_actionKeyA, flushInputedKeys: true);
			ILRuntimeAPI.SummonMonster(_actor, 0, summonId, _actor.tsTransform.Position, dir, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			while (!requestComboAttack.isComboFinish)
			{
				yield return null;
			}
			rotateFinish = false;
			_lookAtTarget.BeginLookAt(_actor, target, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			dir = TSVector2.Rotate(_actor.tsTransform.Forward, -45);
			rotateFinish = false;
			_lookAtTarget.BeginLookAtByPos(_actor, _actor.tsTransform.Position + dir.normalized, 0, 3600, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			requestComboAttack = BeginAttack(_actionKeyA, flushInputedKeys: true);
			ILRuntimeAPI.SummonMonster(_actor, 0, summonId, _actor.tsTransform.Position, dir, (SummonCfg)null, (string)null, (Action<MonsterAdventureActor>)null);
			while (!requestComboAttack.isComboFinish)
			{
				yield return null;
			}
			_actor.DisableImmuneControl();
			_actor.ResumeMovementBlock();
			_skill?.Clear();
		}
	}
