	public class Skill_Pawl : SkillAdvancedBase
	{
		private readonly ComboInputBuffer.ActionKey keyA;

		private readonly ComboInputBuffer.ActionKey keyB = ComboInputBuffer.ActionKey.D;

		private readonly int buffId = 990031100;

		private readonly string afterAttack = "AfterAttack";

		private readonly string startBuff = "BuffStart";

		private readonly string stopBuff = "BuffEnd";

		private readonly FP rotateSpd = 180;

		private readonly FP moveSpd = 15;

		private readonly TSVector2 offset = new TSVector2(1, 1);

		private CoroutineNode corMain;

		private readonly LookAtTarget lookAtTarget = new LookAtTarget();

		private bool isHit;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			lookAtTarget.Clear();
			isHit = false;
		}

		private IEnumerator DoMainLogic()
		{
			bool rotateFinish = false;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, rotateSpd, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			Skill_Pawl skill_Pawl = this;
			ComboInputBuffer.ActionKey key = keyA;
			System.Action onComboFinish = OnFinish;
			Action<string> action = onCustomEvent;
			skill_Pawl.BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, null, action);
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		protected new void OnReceiveDamage(IEvent evt)
		{
			if ((evt as AdventureActorReceiveDamageEvent).from == _actor)
			{
				isHit = true;
			}
		}

		protected void onCustomEvent(string eventName)
		{
			if (eventName.Equals(afterAttack))
			{
				if (isHit)
				{
					AdventureActor target = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor.GetComponent<AdventureActor>();
					TSVector2 tSVector = ILRuntimeAPI.TransLocalPosToWorldPos(target, offset) - target.tsTransform.Position;
					target.EnterLostControl();
					target.ForceMove(moveSpd, tSVector.magnitude, tSVector.normalized, isCoexist: false, changeForward: false, 40, 3, AdventureActor.MoveType.Normal, AdventureActor.ForceType.Constant_Speed, delegate
					{
						target.ExitLostControl();
					});
					ComboInputBuffer.ActionKey key = keyB;
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnFinish;
					BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
				}
			}
			else if (eventName.Equals(startBuff))
			{
				_actor.buffComponent.AddBuff(buffId, _actor);
			}
			else if (eventName.Equals(stopBuff))
			{
				_actor.buffComponent.RemoveBuffByBuffId(buffId);
			}
		}
	}
