		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			StopCoroutine(ref corShoot);
		}

		private IEnumerator DoMainLogic()
		{
			bool rotateFinish = false;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, rotateSpd, delegate
			{
				rotateFinish = true;
			});
			while (!rotateFinish)
			{
				yield return null;
			}
			Skill_WoodMissile skill_WoodMissile = this;
			ComboInputBuffer.ActionKey key = startKey;
			System.Action onInterrupt = OnInterrupt;
			System.Action onComboFinish = OnFinish;
			Action<string> action = onCustomEvent;
			skill_WoodMissile.BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
		}

		private IEnumerator DoShootLogic()
		{
			FP leftTime = shootInterval;
			int curCount = 0;
			while (curCount < maxCount)
			{
				leftTime -= _actor.LogicDeltaTime;
				if (leftTime <= 0)
				{
					ILRuntimeAPI.CreateSkill(subSkillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false);
					leftTime = shootInterval;
					curCount++;
				}
				yield return null;
			}
		}

		private void onCustomEvent(string eventName)
		{
			if (eventName.Equals(shootEvt))
			{
				StartCoroutine(ref corShoot, DoShootLogic());
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			_skill.Clear();
		}
