	public class Skill_WoodMissile_Missile : SkillAdvancedBase
	{
		private readonly int damageID = 11031031;

		private readonly FP radius = 1;

		private readonly FP innerRadius = 0;

		private readonly string effectWarn = "fx_11031_base_atk_1_warning";

		private readonly string effectStart = "fx_11031_base_atk_1_start";

		private readonly string effectAttack = "fx_11031_base_atk_1_atk";

		private readonly string effectHit = "fx_11031_base_atk_1_hit";

		private readonly PlayFX playFX = new PlayFX();

		private readonly PlayFX playFX_start = new PlayFX();

		private readonly PlayFX playFX_attack = new PlayFX();

		private readonly PlayFX playFX_hit = new PlayFX();

		private CoroutineNode corMain;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				_skill.SetCurrentPhaseExecuteConfig(new SkillPhaseConfig
				{
					skillPhaseFeatureFlag = SkillPhaseFeatureFlag.All,
					skillIds = null
				});
				_skill.SetCurrentPhaseBreakConfig(new SkillPhaseConfig
				{
					skillPhaseFeatureFlag = SkillPhaseFeatureFlag.None,
					skillIds = null
				});
			}
			StartCoroutine(ref corMain, DoMainLogic());
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			playFX.Stop();
			playFX_start.Stop();
			playFX_attack.Stop();
			playFX_hit.Stop();
		}

		private IEnumerator DoMainLogic()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			TSVector2 pos = activedPlayerActor.tsTransform.Position;
			playFX.Play(_actor, _skill, effectWarn, 0, pos, _actor.tsTransform.Forward);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.1f));
			playFX_start.Play(_actor, _skill, effectStart, 0, pos, _actor.tsTransform.Forward);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(1f));
			playFX_attack.Play(_actor, _skill, effectAttack, 0, pos, _actor.tsTransform.Forward);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.1f));
			playFX_hit.Play(_actor, _skill, effectHit, 0, pos, _actor.tsTransform.Forward);
			CommomAreaHitConfig commomAreaHitConfig = new CommomAreaHitConfig();
			commomAreaHitConfig.position = pos;
			commomAreaHitConfig.hitDamageId = damageID;
			ILRuntimeAPI.CircleAreaHit(_actor, commomAreaHitConfig, radius, innerRadius);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(1f));
			_skill?.Clear();
		}
	}
