namespace AIScript.Monster._10501BanShenShu
{
	public class Parallel : AIScript.Monster.Template.Parallel
	{
		private const GameEnum.questCompleteCondClient achievementType_1 = GameEnum.questCompleteCondClient.BanShenShu_001;

		private const int killTeammateIndex_1 = 4;

		private const GameEnum.questCompleteCondClient achievementType_2 = GameEnum.questCompleteCondClient.BanShenShu_002;

		private const int notKillTeammateIndex_2 = 4;

		private const GameEnum.questCompleteCondClient achievementType_3 = GameEnum.questCompleteCondClient.BanShenShu_003;

		private const int checkTeammateIndex_3 = 1;

		private const GameEnum.questCompleteCondClient achievementType_4 = GameEnum.questCompleteCondClient.BanShenShu_004;

		private bool _achievementTypeFinish_1;

		private bool _achievementTypeFinish_2;

		private bool _canFinishAchievementType_2;

		private bool _achievementTypeFinish_3;

		private bool _achievementTypeFinish_4;

		private bool _canFinishAchievementType_4;

		public override void OnStart()
		{
			base.OnStart();
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.BanShenShu_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.BanShenShu_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.BanShenShu_003);
			_achievementTypeFinish_4 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.BanShenShu_004);
			_canFinishAchievementType_2 = true;
			_canFinishAchievementType_4 = true;
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from is MonsterAdventureActor && adventureActorReceiveDamageEvent.to is PlayerAdventureActor && !_achievementTypeFinish_4 && _canFinishAchievementType_4)
			{
				_canFinishAchievementType_4 = adventureActorReceiveDamageEvent.curValue <= 0;
			}
		}

		protected override void OnActorDied(IEvent evt)
		{
			base.OnActorDied(evt);
			AdventureActorDiedEvent adventureActorDiedEvent = evt as AdventureActorDiedEvent;
			if (!(adventureActorDiedEvent.actor is MonsterAdventureActor monsterAdventureActor) || !(adventureActorDiedEvent.killer is PlayerAdventureActor))
			{
				return;
			}
			if (!_achievementTypeFinish_1)
			{
				int teammateIdByIndex = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, 4);
				List<LogicEntity> list = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex);
				if (list != null && list.Count > 0 && list.Contains(monsterAdventureActor))
				{
					_achievementTypeFinish_1 = SetAchievementState(GameEnum.questCompleteCondClient.BanShenShu_001);
				}
			}
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2)
			{
				int teammateIdByIndex2 = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, 4);
				List<LogicEntity> list2 = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex2);
				if (list2 != null && list2.Count > 0)
				{
					_canFinishAchievementType_2 = !list2.Contains(monsterAdventureActor);
				}
			}
			if (monsterAdventureActor == _actor && !_achievementTypeFinish_3)
			{
				int teammateIdByIndex3 = CommonUtils_MonsterAPI.GetTeammateIdByIndex(_actor as MonsterAdventureActor, 1);
				List<LogicEntity> list3 = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(teammateIdByIndex3);
				if (list3 != null && list3.Count > 0)
				{
					_achievementTypeFinish_3 = SetAchievementState(GameEnum.questCompleteCondClient.BanShenShu_003);
				}
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2 && MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel.RegionType == 2)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.BanShenShu_002);
			}
			if (!_achievementTypeFinish_4 && _canFinishAchievementType_4)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.BanShenShu_004);
			}
			_canFinishAchievementType_2 = false;
			_canFinishAchievementType_4 = false;
		}
	}
