		protected IEnumerator Flap_Logic_Unilateral()
		{
			Angle = GetEntityAngle(_actor);
			HitData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
			SelfAngle = GetEntityAngle(_actor);
			TargetAngle = GetEntityAngle(GetCurrentPlayer());
			RelativeAngle = AngleBetween2TSVector(new TSVector2(0, 1) - new TSVector2(0, 0), GetEntityPosition(GetCurrentPlayer()), signed: true);
			FP fxAngle = GetRotation();
			if (RelativeAngle < 0)
			{
				StartCor(FlapAttack_L_Unilateral());
				yield return WaitTime(1);
				StartCor(Warning_L_Unilateral());
				yield return WaitTime(1.2);
				FlapFxIndex = PlayEffect(FlapFx_L, 0.95f, default(FP), FlapPOS_L, fxAngle);
				yield return WaitTime(0.3);
				for (int i = 0; i < 2; i++)
				{
					yield return WaitTime(0.6);
					BeginRotateEffect(FlapFxIndex, 20, 100);
				}
				yield return WaitTime(0.6);
				if (FlapFxIndex != 0L)
				{
					StopEffect(FlapFxIndex);
				}
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
			else
			{
				StartCor(FlapAttack_R_Unilateral());
				yield return WaitTime(1);
				StartCor(Warning_R_Unilateral());
				yield return WaitTime(1.2);
				FlapFxIndex = PlayEffect(FlapFx_R, 0.95f, default(FP), FlapPOS_R, fxAngle);
				yield return WaitTime(0.3);
				for (int i = 0; i < 2; i++)
				{
					yield return WaitTime(0.6);
					BeginRotateEffect(FlapFxIndex, -20, 100);
				}
				yield return WaitTime(0.6);
				if (FlapFxIndex != 0L)
				{
					StopEffect(FlapFxIndex);
				}
				yield return WaitCombo(ComboAttackType.isComboFinish);
			}
		}

		protected IEnumerator TrapArea()
		{
			for (int i = 0; i < 100; i++)
			{
				if (attackSwitch_1)
				{
					for (int j = 0; j < shape01Count; j++)
					{
						shapePOS = GetEntityPosition(GetCurrentPlayer());
						DeterministicShape shapeData = GetShapeData(DeterministicShape.ShapeType.Circle, shapePOS, default(FP), default(FP), 6, 3);
						_shapeChoicePOS.Add(GetShapeRandomPoint(shapeData, GetCurrentPlayer(), isReachable: true));
					}
					for (int k = 0; k < _shapeChoicePOS.Count; k++)
					{
						PlayAreaEffect(SpikeWeedFx, _shapeChoicePOS[k]);
					}
					attackSwitch_1 = false;
					_shapeChoicePOS.Clear();
				}
				else if (attackSwitch_2)
				{
					for (int l = 0; l < shape02Count; l++)
					{
						shapePOS = GetEntityPosition(GetCurrentPlayer());
						DeterministicShape shapeData2 = GetShapeData(DeterministicShape.ShapeType.Circle, shapePOS, default(FP), default(FP), 4, 2);
						_shapeChoicePOS.Add(GetShapeRandomPoint(shapeData2, GetCurrentPlayer(), isReachable: true));
					}
					for (int m = 0; m < _shapeChoicePOS.Count; m++)
					{
						PlayAreaEffect(SpikeWeedFx, _shapeChoicePOS[m]);
					}
					attackSwitch_2 = false;
					_shapeChoicePOS.Clear();
				}
				else if (attackSwitch_3)
				{
					for (int n = 0; n < shape03Count; n++)
					{
						shapePOS = GetEntityPosition(GetCurrentPlayer());
						DeterministicShape shapeData3 = GetShapeData(DeterministicShape.ShapeType.Circle, shapePOS, default(FP), default(FP), 1, 0);
						_shapeChoicePOS.Add(GetShapeRandomPoint(shapeData3, GetCurrentPlayer(), isReachable: true));
					}
					for (int num = 0; num < _shapeChoicePOS.Count; num++)
					{
						PlayAreaEffect(SpikeWeedFx, _shapeChoicePOS[num]);
					}
					attackSwitch_3 = false;
					_shapeChoicePOS.Clear();
				}
				yield return WaitTime(0.3);
			}
			yield return null;
		}
	}
	public class Skill_Flower : SkillSimpleBase
	{
		private static readonly int VineIndex = 0;

		private static readonly string VineAttack = "Vine";

		private static readonly int MonsterID = 4;

		private static readonly List<TSVector2> HandPOS = new List<TSVector2>
		{
			new TSVector2(-2, 3),
			new TSVector2(4, 2)
		};

		private static readonly List<string> FxFlowerLine = new List<string> { "fx_m10501_loop_Skill7_ground_appear_1", "fx_m10501_loop_Skill7_ground_appear_2" };

		private static readonly List<FP> LineAngle = new List<FP> { -130, 135 };

		private static readonly List<TSVector2> SummonPOS = new List<TSVector2>
		{
			new TSVector2(-10, 3),
			new TSVector2(10.5, 3)
		};

		private static List<long> FxLine = new List<long>();

		private static CoroutineNode TimeLimit;

		private static int AttackTimes;

		private static TSVector2 FxPOS;

		private static TSVector2 SelfPOS;

		private static TSVector2 SelfForward;

		protected override void OnSkillEnable()
		{
			AttackTimes = 0;
		}

		protected override void OnSkillDisable()
		{
			AttackTimes = 0;
			StopCor(TimeLimit);
			FxLine.Clear();
			for (int i = 0; i < FxLine.Count; i++)
			{
				StopEffect(FxLine[i]);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			TimeLimit = StartCor(SkillDuration());
			BeginAttack(VineIndex, VineAttack, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return StartCor(SummonFlower());
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopCor(TimeLimit);
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex != 0)
			{
				return;
			}
			AttackTimes++;
			if (AttackTimes == 1)
			{
				CancelAttack();
				for (int i = 0; i < FxLine.Count; i++)
				{
					StopEffect(FxLine[i]);
				}
			}
		}

		protected IEnumerator SkillDuration()
		{
			yield return WaitTime(10);
			CancelAttack();
			for (int i = 0; i < FxLine.Count; i++)
			{
				StopEffect(FxLine[i]);
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
			InterruptSkill();
		}

		protected IEnumerator SummonFlower()
		{
			SelfPOS = GetPosition();
			SelfForward = GetForward();
			for (int i = 0; i < 2; i++)
			{
				FxPOS = TransLocalPosToWorldPos(SelfPOS, SelfForward, HandPOS[i]);
				FxLine.Add(PlayEffect(FxFlowerLine[i], 1f, default(FP), FxPOS, LineAngle[i]));
			}
			yield return WaitTime(0.9);
			for (int j = 0; j < 2; j++)
			{
				SummonTeammate(MonsterID, SummonPOS[j], SelfForward);
			}
			yield return WaitTime(0.5);
		}
	}
	public class Skill_ResidentEffect : SkillSimpleBase
	{
		private readonly FP INTR = 15;

		private CoroutineNode endCondition;

		private readonly string FxAlias = "fx_m10501_loop_Skill5_ground";

		private readonly FP SpawnINTR = 3;

		private readonly int MonsterID01 = 1;

		private readonly int MonsterID02 = 2;

		private readonly int MonsterID03 = 3;

		private TSVector2 OriginPOS = new TSVector2(0, 0);

		private List<long> FxSpawn = new List<long>();

		private List<TSVector2> SpawnPOS = new List<TSVector2>
		{
			new TSVector2(-9, 10.6),
			new TSVector2(9, 10.6),
			new TSVector2(-9.8, -0.45),
			new TSVector2(10.5, -0.45)
		};

		private readonly int flowerCount = 2;

		private static readonly int MonsterID = 4;

		private static readonly List<TSVector2> SummonPOS = new List<TSVector2>
		{
			new TSVector2(-10, 3),
			new TSVector2(10.5, 3)
		};

		private LogicEntity Master;

		private List<int> masterDateIDList = new List<int> { 91050100, 91050101, 91050102 };

		private const int stateID01 = 105010000;

		private const int stateID02 = 105010001;

		private const int stateID03 = 105010002;

		private int stateID;

		private int masterDateID;

		private LogicEntity masterEntity;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			endCondition = StartCor(EndCondition());
			for (int i = 0; i < 500; i++)
			{
				yield return StartCor(Summon());
				yield return WaitTime(INTR);
				yield return StartCor(Flower());
				yield return WaitTime(INTR);
			}
		}

		protected IEnumerator Summon()
		{
			SetLogicTagToggleValue(GetMonsterCloner(), "skillIsRunning", value: true);
			for (int i = 0; i < 4; i++)
			{
				FxSpawn.Add(PlayEffect(FxAlias, 1f, default(FP), SpawnPOS[i], GetTSVectToAngle(OriginPOS - SpawnPOS[i], 0)));
			}
			yield return WaitTime(1);
			for (int j = 0; j < 3; j++)
			{
				switch (j)
				{
				case 0:
				{
					for (int l = 0; l < 4; l++)
					{
						CommonUtils_MonsterAPI.SummonTeammate(GetMonsterCloner() as MonsterAdventureActor, MonsterID03, SpawnPOS[l], OriginPOS - SpawnPOS[l], 10);
					}
					break;
				}
				case 1:
				{
					for (int m = 0; m < 2; m++)
					{
						CommonUtils_MonsterAPI.SummonTeammate(GetMonsterCloner() as MonsterAdventureActor, MonsterID01, SpawnPOS[m], OriginPOS - SpawnPOS[m], 10);
					}
					break;
				}
				default:
				{
					for (int k = 0; k < 2; k++)
					{
						CommonUtils_MonsterAPI.SummonTeammate(GetMonsterCloner() as MonsterAdventureActor, MonsterID02, SpawnPOS[k], OriginPOS - SpawnPOS[k], 10);
					}
					break;
				}
				}
				SetLogicTagToggleValue(masterEntity, "skillIsRunning", value: false);
				yield return WaitTime(SpawnINTR);
			}
			yield return WaitTime(1);
			for (int n = 0; n < FxSpawn.Count; n++)
			{
				StopEffect(FxSpawn[n]);
			}
		}

		protected IEnumerator CheckMasterState()
		{
			GetTargetsByFaction(isFriend: true);
			for (int i = 0; i < 500; i++)
			{
				List<LogicEntity> teammatelist = GetTargetsByFaction(isFriend: true);
				if (teammatelist == null)
				{
					InterruptSkill();
					yield return null;
				}
				yield return WaitTime(1);
				teammatelist.Clear();
			}
		}

		protected IEnumerator Flower()
		{
			for (int i = 0; i < flowerCount; i++)
			{
				CommonUtils_MonsterAPI.SummonTeammate(GetMonsterCloner() as MonsterAdventureActor, MonsterID, SummonPOS[i], default(TSVector2), 10);
			}
			yield return null;
		}

		protected IEnumerator EndCondition()
		{
			AdventureActor master = GetMonsterCloner();
			List<LogicEntity> friendlyEntity = new List<LogicEntity>();
			while (true)
			{
				friendlyEntity.Clear();
				friendlyEntity.AddRange(GetTargetsByFaction(isFriend: true));
				if (!friendlyEntity.Contains(master))
				{
					InterruptSkill();
				}
				yield return WaitTime(0.5);
			}
		}
	}
	public class Skill_Spikeweed : SkillSimpleBase
	{
		private static readonly int ActionIndex = 0;

		private static readonly string AttackAction = "GeneralAttack";

		private static readonly List<TSVector2> WeedPOS = new List<TSVector2>
		{
			new TSVector2(-12, 7.5),
			new TSVector2(-12, -1)
		};

		private List<TSVector2> WeedPOSTemp = new List<TSVector2>();

		private readonly string warningFx = "fx_m10501_loop_SpikeWeed_warning";

		private readonly string warningFx_long = "fx_m10501_loop_Spikeweed_warning_02";

		private readonly string warningFx_short = "fx_m10501_loop_Spikeweed_warning_01";

		private List<long> _warningFx = new List<long>();

		private static CoroutineNode TimeLimit;

		private static int AttackTimes;

		protected override void OnSkillEnable()
		{
			AttackTimes = 0;
		}

		protected override void OnSkillDisable()
		{
			AttackTimes = 0;
			StopCor(TimeLimit);
			WeedPOSTemp.Clear();
			if (_warningFx.Count > 0)
			{
				for (int i = 0; i < _warningFx.Count; i++)
				{
					StopEffect(_warningFx[i]);
				}
			}
			_warningFx.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			TimeLimit = StartCor(SkillDuration());
			BeginAttack(ActionIndex, AttackAction, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			yield return StartCor(SpikeweedAttack());
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			StopCor(TimeLimit);
		}

		protected override void OnComboLoop(int comboIndex)
		{
			if (comboIndex == 0)
			{
				AttackTimes++;
				if (AttackTimes == 1)
				{
					CancelAttack();
				}
			}
		}

		protected IEnumerator SkillDuration()
		{
			yield return WaitTime(10);
			CancelAttack();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			InterruptSkill();
		}

		protected IEnumerator SpikeweedAttack()
		{
			if ((int)(long)GetRandomValue(0, 1.5, isInt: true) == 0)
			{
				for (int i = 0; i < 7; i++)
				{
					WeedPOSTemp.Add(new TSVector2(WeedPOS[0].x + 4 * i, WeedPOS[0].y));
					WeedPOSTemp.Add(new TSVector2(WeedPOS[0].x + 4 * i, WeedPOS[1].y));
				}
			}
			else
			{
				for (int j = 0; j < 7; j++)
				{
					WeedPOSTemp.Add(new TSVector2(WeedPOS[0].x + 4 * j, WeedPOS[0].y - 4.25));
					WeedPOSTemp.Add(new TSVector2(WeedPOS[0].x + 4 * j, WeedPOS[1].y - 4.25));
				}
			}
			_warningFx.Add(PlayEffect(warningFx_long, 0.5f, default(FP), new TSVector2(0, WeedPOSTemp[0].y)));
			_warningFx.Add(PlayEffect(warningFx_short, 0.5f, default(FP), new TSVector2(0, WeedPOSTemp[1].y)));
			yield return WaitTime(1.3);
			for (int k = 0; k < WeedPOSTemp.Count; k++)
			{
				PlayAreaEffect("FSpikeweed_Normal", WeedPOSTemp[k]);
			}
			yield return WaitTime(0.6);
			for (int l = 0; l < _warningFx.Count; l++)
			{
				StopEffect(_warningFx[l]);
			}
			yield return WaitTime(0.1);
		}
	}
