		private FP Length = 30;

		private FP Rotation = 0;

		private List<long> FxList = new List<long>();

		protected override void OnSkillEnable()
		{
			AttackTimes = 0;
		}

		protected override void OnSkillDisable()
		{
			if (masterEntity != null)
			{
				SetLogicTagToggleValue(masterEntity, "skillIsRunning", value: false);
			}
			AttackTimes = 0;
			StopCor(TimeLimit);
			for (int i = 0; i < FxList.Count; i++)
			{
				StopEffect(FxList[i]);
			}
			FxList.Clear();
		}

		protected override IEnumerator DoMainLogic()
		{
			masterEntity = GetMonsterCloner();
			List<BuffEntity> buffFromTarget = GetBuffFromTarget(masterEntity, 0, 105010000);
			stateID = buffFromTarget[0].buffConfig.Id;
			TimeLimit = StartCor(AttackTime());
			SetLogicTagToggleValue(masterEntity, "skillIsRunning", value: true);
			yield return StartCor(Attack());
			StopCor(TimeLimit);
		}

		protected IEnumerator AttackTime()
		{
			List<LogicEntity> list = GetTargetsByFaction(isFriend: true);
			bool flag = true;
			for (int i = 0; i < 15; i++)
			{
				if (list != null && list.Count > 0)
				{
					for (int j = 0; j < list.Count; j++)
					{
						if (list[j] == GetMonsterCloner())
						{
							flag = false;
						}
					}
					if (flag)
					{
						InterruptSkill();
						yield return null;
					}
					yield return WaitTime(1);
					flag = true;
					list.Clear();
					list = GetTargetsByFaction(isFriend: true);
					continue;
				}
				InterruptSkill();
				yield break;
			}
			InterruptSkill();
			yield return null;
		}

		protected IEnumerator Attack()
		{
			HitData = GetHitFeatureData(HitBox.FeatureFlag.None, default(FP), default(FP), UseAtttackForward: false, default(FP), null, null, default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), default(FP), null, null, null, null, 2);
			SelfPOS = GetEntityPosition(masterEntity);
			if ((int)(long)GetRandomValue(0, 2, isInt: true) == 0)
			{
				LeftAttackPOS = TransLocalPosToWorldPos(SelfPOS, GetEntityForward(masterEntity), LeftHitPOS);
				Shape = GetShapeData(DeterministicShape.ShapeType.Rectangle, LeftAttackPOS, Width, Length, default(FP), default(FP), default(FP), Rotation);
				fx_Warning = PlayEffect(Fx_L_Warning, 1f, default(FP), SelfPOS, 90);
				FxList.Add(fx_Warning);
				yield return WaitTime(0.2);
				PlayWwiseSound("mon_10010_general_attack_start");
				yield return WaitTime(0.8);
				fx_Ground = PlayEffect(Fx_L_Ground, 1f, default(FP), SelfPOS, 90);
				FxList.Add(fx_Ground);
				yield return WaitTime(0.2);
				PlayWwiseSound("mon_10010_general_attack_end");
				yield return WaitTime(0.8);
			}
			else
			{
				RightAttackPOS = TransLocalPosToWorldPos(SelfPOS, GetEntityForward(masterEntity), RightHitPOS);
				Shape = GetShapeData(DeterministicShape.ShapeType.Rectangle, RightAttackPOS, Width, Length, default(FP), default(FP), default(FP), Rotation);
				fx_Warning = PlayEffect(Fx_R_Warning, 1f, default(FP), SelfPOS, -90);
				FxList.Add(fx_Warning);
				yield return WaitTime(0.2);
				PlayWwiseSound("mon_10010_general_attack_start");
				yield return WaitTime(0.8);
				fx_Ground = PlayEffect(Fx_R_Ground, 1f, default(FP), SelfPOS, -90);
				FxList.Add(fx_Ground);
				yield return WaitTime(0.2);
				PlayWwiseSound("mon_10010_general_attack_end");
				yield return WaitTime(0.8);
			}
			for (int i = 0; i < 5; i++)
			{
				AreaHit_Simple(_actor, Shape, HitData, 1050130, 1, HitBox.HurtAnimType.Small);
				yield return WaitTime(1.1);
			}
			StopEffect(fx_Warning);
			yield return WaitTime(0.3);
			StopEffect(fx_Ground);
			PlayWwiseSound("mon_10010_general_attack_diappear");
			yield return WaitTime(0.1);
		}
	}
