namespace AIScript.Monster._10017XiChenQi
{
	public class Skill_Draw : SkillAdvancedBase
	{
		protected const int buffId = 9900311;

		protected FP radius = 20;

		protected FP angle = 120;

		protected FP highDrawTime = 0.3;

		protected FP highDrawSpeed = 12;

		protected FP lowDrawTime = 3;

		protected FP lowDrawSpeed = 6;

		protected readonly int moveLevel = 99;

		protected FP strength = 9;

		protected FP attackDistance = 3;

		protected ComboAttack _comboAttack;

		protected CoroutineNode _drawCor;

		protected FP _drawInterval = 0.1f;

		protected List<DeterministicCollider> _result;

		protected List<LogicEntity> _player;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			StopCoroutine(ref _drawCor);
			ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1];
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, null, null, onComboFinish, onInterrupt);
		}

		protected void OnAnticipationEnd()
		{
			_actor.buffComponent?.AddBuff(9900311, _actor);
			StartCoroutine(ref _drawCor, BeginDraw());
		}

		protected IEnumerator BeginDraw()
		{
			FP totalTime = highDrawTime + lowDrawTime;
			FP lastTime = 0;
			bool attackPlayer = false;
			while (lastTime <= totalTime && !attackPlayer)
			{
				FP fP = ((lastTime <= highDrawTime) ? highDrawSpeed : lowDrawSpeed);
				if (_result == null)
				{
					_result = new List<DeterministicCollider>(10);
				}
				else
				{
					_result.Clear();
				}
				if (_player == null)
				{
					_player = new List<LogicEntity>(2);
				}
				else
				{
					_player.Clear();
				}
				if (SceneSingleton<DeterministicCollisionManager>.Instance.CheckFanOverlap(angle, radius, _actor.tsTransform.Position, _actor.tsTransform.Rotation, _result, 256))
				{
					for (int i = 0; i < _result.Count; i++)
					{
						if (!_result[i].TryGetComponent<LogicEntity>(out var component))
						{
							continue;
						}
						PlayerAdventureActor playerAdventureActor = component as PlayerAdventureActor;
						if (playerAdventureActor != null)
						{
							FP fP2 = TSVector2.Distance(_actor.tsTransform.Position, playerAdventureActor.tsTransform.Position);
							attackPlayer = fP2 <= attackDistance;
							if (attackPlayer)
							{
								break;
							}
							_player.Add(playerAdventureActor);
						}
					}
					if (attackPlayer)
					{
						continue;
					}
					if (_player != null && _player.Count > 0)
					{
						FP distance = fP * _drawInterval;
						ILRuntimeAPI.ForceMoveByDistance(_actor, _player, distance, fP, isCoExist: true, isChangeForward: true, moveLevel, strength, isPull: true);
					}
				}
				lastTime += _drawInterval;
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_drawInterval));
			}
			ComboInputBuffer.ActionKey[] actionKeys = ((!attackPlayer) ? new ComboInputBuffer.ActionKey[1] : new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B });
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt);
		}

		protected void OnFinish()
		{
			StopCoroutine(ref _drawCor);
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			StopCoroutine(ref _drawCor);
			_actor.buffComponent?.RemoveBuffByBuffId(9900311);
			_comboAttack?.Clear();
			_comboAttack = null;
		}
	}
	public class Skill_GushOnly : SkillAdvancedBase
	{
		protected FP rotateSpeed = 60;

		protected const string shootEvt = "Shoot";

		protected const string checkEvt = "Listen";

		protected FP interruptDistance = 3;

		protected FP minDistance = 3.5;

		protected FP maxDistance = 15;

		protected FP maxAngle = 130;

		protected FP radius = 2;

		protected readonly string[] bullutPaths = new string[8] { "Weapon_Rubbish_S_1", "Weapon_Rubbish_S_2", "Weapon_Rubbish_S_3", "Weapon_Rubbish_S_4", "Weapon_Rubbish_S_5", "Weapon_Rubbish_L_1", "Weapon_Rubbish_L_2", "Weapon_Rubbish_C_1" };

		protected const int minShootTime = 3;

		protected const int maxShootTime = 6;

		protected int _maxShootTime;

		protected ComboAttack _comboAttack;

		protected int _loopTime;

		protected LookAtTarget _lookAtTarget;

		protected bool _lookAt;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			InitData();
		}

		protected void InitData()
		{
			_maxShootTime = TSRandom.Range(3, 6);
		}

		public void OnStart()
		{
			ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack obj = _comboAttack;
			AdventureActor actor = _actor;
			AdventureSkill skill = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action onAnticipationEnd = OnAnticipationEnd;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboLoop = OnComboLoop;
			System.Action onRecoveryBegin = OnRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboLoop, onComboFinish, onInterrupt, onCustomEvent);
		}

		public void OnUpdate()
		{
			if (!_lookAt)
			{
				return;
			}
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (activedPlayerActor != null)
			{
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				_lookAtTarget.BeginLookAt(_actor, activedPlayerActor, 0, rotateSpeed, null);
			}
		}

		protected void OnAnticipationEnd()
		{
			_loopTime = 0;
			_lookAt = true;
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "Shoot"))
			{
				Shoot();
			}
			else if (string.Equals(eventName, "Listen"))
			{
				LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				if (activedPlayerActor != null && TSVector2.Distance(_actor.tsTransform.Position, activedPlayerActor.tsTransform.Position) <= interruptDistance)
				{
					_comboAttack.InterruptAttack();
				}
			}
		}

		protected void Shoot()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			FP angle = _actor.tsTransform.Forward.GetAngle();
			TSVector2 center;
			if (activedPlayerActor == null)
			{
				center = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, minDistance, maxDistance, angle, maxAngle);
			}
			else
			{
				FP fP = TSVector2.Angle(activedPlayerActor.tsTransform.Position - _actor.tsTransform.Position, _actor.tsTransform.Forward);
				FP fP2 = TSVector2.Distance(activedPlayerActor.tsTransform.Position, _actor.tsTransform.Position);
				center = ((!(fP2 >= minDistance) || !(fP2 <= maxDistance) || !(fP <= maxAngle / 2)) ? TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, minDistance, maxDistance, angle, maxAngle) : activedPlayerActor.tsTransform.Position);
			}
			TSVector2 tSVector = TrueSyncExtensions.RandomPointInsideRing(center, 0, radius);
			int num = TSRandom.Range(0, bullutPaths.Length - 1);
			string bulletAlias = bullutPaths[num];
			AdventureActor actor = _actor;
			TSVector2 position = _actor.tsTransform.Position;
			TSVector2 targetPosition = tSVector;
			ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), position, default(FP), targetPosition, null, AimType.Position, BulletDirectionType.BulletToTarget);
		}

		protected void OnComboLoop()
		{
			_loopTime++;
			if (_loopTime >= _maxShootTime)
			{
				_comboAttack.CancelAttack();
			}
		}

		protected void OnRecoveryBegin()
		{
			_lookAt = false;
			_lookAtTarget?.StopLookAt();
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			_lookAt = false;
			_lookAtTarget?.StopLookAt();
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_loopTime = 0;
			_lookAt = false;
			_comboAttack?.Clear();
			_comboAttack = null;
			_lookAtTarget?.Clear();
			_lookAtTarget = null;
		}
	}
