namespace AIScript.Monster._10012FanRongZhiShiTi
{
	public class Parallel_Achievement : AIBase
	{
		private int dashCount = 5;

		private int hitDmgTotle;

		private int dashHitCount;

		private static int evt_DashEnd = CommonHelper.StringToHash("DashEnd");

		public void OnEnable()
		{
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			hitDmgTotle = 0;
			dashHitCount = 0;
		}

		public void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.to as PlayerAdventureActor != null)
			{
				hitDmgTotle += adventureActorReceiveDamageEvent.value;
			}
		}

		private void OnCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && adventureActorCustomEvent.eventHashCode == evt_DashEnd && adventureActorCustomEvent.boolParam)
			{
				dashHitCount++;
				if (dashHitCount >= dashCount && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FanRonShiTi_002))
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.FanRonShiTi_002);
				}
			}
		}

		protected virtual void OnActorDied(IEvent e)
		{
			if (e is AdventureActorDiedEvent adventureActorDiedEvent && adventureActorDiedEvent.actor.dataID == _actor.dataID)
			{
				if (dashHitCount == 0 && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FanRonShiTi_001))
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.FanRonShiTi_001);
				}
				if (hitDmgTotle <= 0 && !ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.FanRonShiTi_004))
				{
					ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(GameEnum.questCompleteCondClient.FanRonShiTi_004);
				}
			}
		}
	}
	public class Skill_BreakDefence : SkillAdvancedBase
	{
		private readonly ComboInputBuffer.ActionKey startKey = ComboInputBuffer.ActionKey.H;

		private readonly ComboInputBuffer.ActionKey endKey = ComboInputBuffer.ActionKey._1;

		private readonly FP waitTime = 4;

		private readonly string BeginSuperArmor = "BeginSuperArmor";

		private readonly string EndSuperArmor = "EndSuperArmor";

		private CoroutineNode corMain;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_actor.EnableImmuneControl();
			_actor.StopImmuneControlCueEffect();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			_actor.buffComponent.RemoveBuffByBuffId(1001224);
			_actor.DisableImmuneControl();
		}

		private IEnumerator DoMainLogic()
		{
			Skill_BreakDefence skill_BreakDefence = this;
			ComboInputBuffer.ActionKey key = startKey;
			System.Action onComboFinish = OnFinish;
			RequestComboAttack req = skill_BreakDefence.BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish);
			while (!req.isAnticipationEnd)
			{
				yield return null;
			}
			_actor.buffComponent.AddBuff(1001224, _actor);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(waitTime));
			_actor.buffComponent.RemoveBuffByBuffId(1001224);
			Skill_BreakDefence skill_BreakDefence2 = this;
			ComboInputBuffer.ActionKey key2 = endKey;
			onComboFinish = OnFinish;
			System.Action onInterrupt = OnFinish;
			skill_BreakDefence2.BeginAttack(key2, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		protected void onCustomEvent(string eventName)
		{
			if (eventName.Equals(BeginSuperArmor))
			{
				_actor.buffComponent.AddBuff(9900311, _actor);
			}
			else if (eventName.Equals(EndSuperArmor))
			{
				_actor.buffComponent.RemoveBuffByBuffId(9900311);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}
	}
	public class Skill_Linger : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] Walk = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.W };

		private TSVector2 PosRandom01;

		private TSVector2 PosRandom02;

		private FP TimesEnd;

		private FP PointY;

		protected override void OnSkillEnable()
		{
			TimesEnd = 0;
		}

		protected override void OnSkillDisable()
		{
			CancelAim();
			StopMove();
			CancelBezierPathMove();
		}

		protected override IEnumerator DoMainLogic()
		{
			FP CharacterAngle = CalcAngleBetweenSelfAndAttackTarget(isSingleAngle: true);
			if (Distance(GetPosition(), new TSVector2(0, 0)) > 7)
			{
				StartCor(TimeCal());
				while (TimesEnd != 1)
				{
					if (CharacterAngle >= 0 && CharacterAngle <= 180)
					{
						PointY = 1;
					}
					else
					{
						PointY = -1;
					}
					BeginBezierPathMove(1, new TSVector2(0, 0), 0.5, PointY, comboWithAttack: false, default(FP), AdventureActor.MovementMode.Walk, 40, 20f);
					AimAtTarget(GetCurrentPlayer(), 60f);
					yield return WaitBezierPathMoveFinish();
				}
				yield break;
			}
			if ((CharacterAngle > 120 || CharacterAngle < -120) && Distance(GetPosition(), GetEntityPosition(GetCurrentPlayer())) > 6)
			{
				StartCor(TimeCal());
				while (TimesEnd != 1)
				{
					PosRandom01 = GetEntityPosition(GetCurrentPlayer());
					if (CharacterAngle > 120 && CharacterAngle <= 180)
					{
						PointY = 1;
					}
					else
					{
						PointY = -1;
					}
					BeginBezierPathMove(1, PosRandom01, 0.5, PointY, comboWithAttack: false, default(FP), AdventureActor.MovementMode.Walk, 40, 20f);
					AimAtPosition(PosRandom01, 60f);
					yield return WaitBezierPathMoveFinish();
				}
				yield break;
			}
			StartCor(TimeCal());
			while (TimesEnd != 1)
			{
				Skill_Linger skill_Linger = this;
				TSVector2 entityPosition = GetEntityPosition(GetCurrentPlayer());
				FP radius = 10;
				FP innerRadius = 6;
				DeterministicShape shapeData = skill_Linger.GetShapeData(DeterministicShape.ShapeType.Circle, entityPosition, default(FP), default(FP), radius, innerRadius);
				int num = 0;
				PosRandom02 = GetShapeRandomPoint(shapeData, GetCurrentPlayer(), isReachable: true);
				while (Distance(PosRandom02, GetPosition()) < 6 && num < 5)
				{
					PosRandom02 = GetShapeRandomPoint(shapeData, GetCurrentPlayer(), isReachable: true);
					num++;
				}
				MoveToPosition(PosRandom02, 1, AdventureActor.MovementMode.Walk, 3f);
				AimAtTarget(GetCurrentPlayer(), 60f);
				yield return WaitMoveStatus();
			}
		}

		protected IEnumerator TimeCal()
		{
			int Timesint = 0;
			while (Timesint <= 2)
			{
				Timesint++;
				yield return WaitFrame(30);
			}
			TimesEnd = 1;
		}
	}
	public class Skill_Spawn : SkillSimpleBase
	{
		protected readonly ComboInputBuffer.ActionKey[] Attack1 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.Y,
			ComboInputBuffer.ActionKey._0
		};

		protected readonly ComboInputBuffer.ActionKey[] Attack2 = new ComboInputBuffer.ActionKey[2]
		{
			ComboInputBuffer.ActionKey.Y,
			ComboInputBuffer.ActionKey._1
		};

		protected readonly FP disWithPlayer = 15;

		protected TSVector2 TargetPosition;

		protected override void OnSkillEnable()
		{
			SetBattleOutEnable();
			AddBuffToTarget(_actor, 990020140);
			SetSuperArmorEnable();
			SetLockToughnessEnable();
			SetUnparalleledEnable();
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Attack1, flushInputedKeys: true, forceInterruptAttack: true);
			LogicEntity attackTarget = GetAttackTarget(isUpToDate: true);
			if (attackTarget != null)
			{
				TargetPosition = GetEntityPosition(attackTarget);
			}
			while (Distance(TargetPosition, GetPosition()) >= disWithPlayer)
			{
				yield return WaitFrame(3);
				attackTarget = GetAttackTarget(isUpToDate: true);
				if (attackTarget != null)
				{
					TargetPosition = GetEntityPosition(attackTarget);
				}
			}
			SetBattleOutDisable();
			ShowCenterHpBar();
			BeginAttack(1, Attack2, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitFrame(30);
			SetSuperArmorDisable();
			SetLockToughnessDisable();
			SetUnparalleledDisable();
			RemoveBuffFromTarget(_actor, 990020140);
			yield return WaitCombo(ComboAttackType.isComboFinish);
		}
	}
	public class Skill_Spawn_Vampire : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Attack_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.Z };

		private readonly string fx_Path = "FX/ActorCommon/fx_common_base_monster_in_ground";

		private readonly string fx_Path2 = "FX/ActorCommon/fx_common_base_monster_in";

		private readonly string fx_Path3 = "FX/Warning/fx_common_base_Earth_YuJing_circular_10";

		private readonly string fx_Path4 = "FX/Warning/fx_common_base_Earth_YuJing_circular_10_end";

		private PlayFX _playFx;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}

		protected override IEnumerator DoMainLogic()
		{
			SetHideOutEnable();
			SetHideModelEnable();
			_playFx = new PlayFX();
			Quaternion rotation = Quaternion.Euler(0f, 0f - (float)_actor.tsTransform.Rotation, 0f);
			_playFx.Play(_actor, fx_Path, 1f, _actor.transform.position, rotation);
			_playFx.Play(_actor, fx_Path3, 1f, _actor.transform.position, rotation);
			yield return WaitTime(0.15);
			_playFx.Play(_actor, fx_Path2, 1f, _actor.transform.position, rotation);
			yield return WaitTime(0.85);
			_playFx.Play(_actor, fx_Path4, 1f, _actor.transform.position, rotation);
			ShowCenterHpBar();
			SetHideOutDisable();
			SetHideModelDisable();
			yield return WaitTime(0.1);
		}
	}
