			if (HomeDistance >= 4)
			{
				SetCloseBlockEnable();
				BeginAttack(1, FireAttack01, flushInputedKeys: true, forceInterruptAttack: true);
				yield return WaitFrame(10);
				BeginLookAtByPos(new TSVector2(0, 0), 0.5, 360, 0);
