		{
			FP fP = CalcAngleBetweenSelfAndAttackTarget(isSingleAngle: true) - 30;
			SelfPos = GetPosition() + TSVector2.Rotate(new TSVector2(0, 2.5f), _actor.tsTransform.Rotation);
