		private void Charge_NoTurn()
		{
			BeginDashActorForward(1, 15, 4, 0, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
		}

