	public class Skill_RunAway_API : SkillSimpleBase
	{
		private readonly FP _rotateSpeed = 130;

		private readonly FP _duration = 0.8;

		protected override IEnumerator DoMainLogic()
		{
			yield return WaitTime(0.1);
