			base.OnStart();
			InitAchievementData();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void InitAchievementData()
		{
			_achievementTypeFinish_1 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.JiaMianYeZhu_001);
			_achievementTypeFinish_2 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.JiaMianYeZhu_002);
			_achievementTypeFinish_3 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.JiaMianYeZhu_003);
			_achievementTypeFinish_4 = ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, GameEnum.questCompleteCondClient.JiaMianYeZhu_004);
			_canFinishAchievementType_2 = true;
			_checkStartTime_3 = -1;
			_hitTimes_3 = 0;
			_canFinishAchievementType_4 = true;
		}

		private void OnCastSkill(IEvent evt)
		{
			AdventureActorCastSkillEvent adventureActorCastSkillEvent = evt as AdventureActorCastSkillEvent;
			if (adventureActorCastSkillEvent.sender as MonsterAdventureActor == _actor && !_achievementTypeFinish_3 && checkSkillId_3.Contains(adventureActorCastSkillEvent.skillEventInfo.skillId))
			{
				_checkStartTime_3 = _actor.LogicTime;
				_hitTimes_3 = 0;
			}
		}

		private void OnCastSkillEnd(IEvent evt)
		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = evt as AdventureActorCastSkillEndEvent;
			if (adventureActorCastSkillEndEvent.sender as MonsterAdventureActor == _actor && !_achievementTypeFinish_1 && checkSkillId_1.Contains(adventureActorCastSkillEndEvent.skillEventInfo.skillId) && _actor.logicVariable.GetLogicTagToggle("ThousandDashInterrupt"))
			{
				_achievementTypeFinish_1 = SetAchievementState(GameEnum.questCompleteCondClient.JiaMianYeZhu_001);
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.from is MonsterAdventureActor) || !(adventureActorReceiveDamageEvent.to is PlayerAdventureActor))
			{
				return;
			}
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2)
			{
				_canFinishAchievementType_2 = !CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, checkHitTag_2);
			}
			if (!_achievementTypeFinish_3 && _checkStartTime_3 >= 0 && _checkStartTime_3 + checkTime_3 > _actor.LogicTime && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, checkHitTag_3))
			{
				_hitTimes_3++;
				if (_hitTimes_3 >= 3)
				{
					_achievementTypeFinish_3 = SetAchievementState(GameEnum.questCompleteCondClient.JiaMianYeZhu_003);
				}
			}
			if (!_achievementTypeFinish_4 && _canFinishAchievementType_4)
			{
				_canFinishAchievementType_4 = adventureActorReceiveDamageEvent.curValue <= 0;
			}
		}

		private bool SetAchievementState(GameEnum.questCompleteCondClient achievementType)
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType))
			{
				return true;
			}
			ModuleController<AdventureModuleController>.Instance.SetAchievementFinish(achievementType);
			return ModuleController<AdventureModuleController>.Instance.CheckAchievementFinished(_actor, achievementType);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			if (!_achievementTypeFinish_2 && _canFinishAchievementType_2 && MonoSingleton<GameController>.Instance.levelLoadParam != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel != null && MonoSingleton<GameController>.Instance.levelLoadParam.regionBossLevel.RegionType == 2)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.JiaMianYeZhu_002);
			}
			if (!_achievementTypeFinish_4 && _canFinishAchievementType_4)
			{
				SetAchievementState(GameEnum.questCompleteCondClient.JiaMianYeZhu_004);
			}
			_canFinishAchievementType_2 = false;
			_checkStartTime_3 = -1;
			_hitTimes_3 = 0;
			_canFinishAchievementType_4 = false;
		}
	}
	public class Skill_Angry : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Angry_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.L };

		private static readonly int SummonAmount = 2;

		private static readonly FP SummonMinDis = 3;

		private static readonly FP SummonMaxDis = 6;

		private int SummonCount;

		private TSVector2 SummonPosition;

		private DeterministicShape SummonShape;

		private FP AngryTimes;

		private bool IsAngrySuccess;

		protected override void OnSkillEnable()
		{
			IsAngrySuccess = false;
			SummonCount = 0;
			TSVector2 position = GetPosition();
			FP summonMaxDis = SummonMaxDis;
			FP summonMinDis = SummonMinDis;
			SummonShape = GetShapeData(DeterministicShape.ShapeType.Circle, position, default(FP), default(FP), summonMaxDis, summonMinDis);
		}

		protected override void OnSkillDisable()
		{
			if (IsAngrySuccess)
			{
				AngryTimes = GetLogicTagFpValue(_actor, "AngryTimes");
				SetLogicTagFpValue(_actor, "AngryTimes", AngryTimes + 1);
			}
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, Angry_Combo, flushInputedKeys: true, forceInterruptAttack: true);
			yield return WaitTime(1);
			while (SummonCount < SummonAmount)
			{
				SummonPosition = GetShapeRandomPoint(SummonShape, _actor, isReachable: true);
				SummonTeammate(1, SummonPosition, GetForward());
				SummonCount++;
			}
			yield return WaitCombo(ComboAttackType.isComboFinish);
			AddBuffToTarget(_actor, 100050110);
			SetLogicTagFpValue(_actor, "AngryBuffStartTime", _actor.LogicTime);
			IsAngrySuccess = true;
		}
	}
