					WaitLookAt_NoWait(GetAttackTarget(isUpToDate: true), 1, BrakeDashTurnSpeed);
				}
				BeginDashActorForward(2, BrakeDashSpeed, BrakeDashDistance, 0, comboWithAttack: true, CanTrace, notChangeForward: true, triggerObstacleStop: false, triggerEnemyStop: false, triggerFriendStop: false);
				yield return WaitDashFinish();
				Skill_Dash_Lv3 skill_Dash_Lv3 = this;
				position = GetPosition();
				rotation = GetRotation();
				skill_Dash_Lv3.PlayEarlyWarningEffect("DashWarning", 1f, default(FP), position, rotation);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				StopWaitLookAt();
				DashTimesCount++;
			}
		}

		private void GetDashDistance()
		{
			if (CheckTargetIsValid(GetAttackTarget()))
			{
				DashDistance = Distance(GetPosition(), GetEntityPosition(GetAttackTarget())) + DashDistanceExtra;
			}
			else
			{
				DashDistance = DashDistanceNoTarget;
			}
		}
	}
	public class Skill_Impact : SkillSimpleBase
	{
		private static readonly ComboInputBuffer.ActionKey[] Ready_Combo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.T };

		private static readonly ComboInputBuffer.ActionKey[] Attack_Combo_Normal = new ComboInputBuffer.ActionKey[1];

		private static readonly ComboInputBuffer.ActionKey[] Attack_Combo_Fast = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.G };

