namespace AIScript.Monster._10003ShuZhuangShu
{
	public class Parallel1003 : AIScript.Monster.Template.Parallel
	{
		protected readonly string effectPath1 = "fx_10003_base_skill3_shootdown";

		protected readonly string effectPath2 = "fx_10003_base_skill3_bullet_ground_start_FixedRogueLikeStageOne";

		protected readonly string effectPath3 = "fx_10003_loop_skill3_bullet_ground_FixedRogueLikeStageOne";

		protected readonly string effectPath4 = "fx_10003_base_skill3_bullet_ground_end_FixedRogueLikeStageOne";

		protected readonly int hitDamageId = 10003161;

		private CoroutineNode corPlayFx;

		private CoroutineNode hit;

		protected readonly List<PlayFX> _playFXs = new List<PlayFX>(4);

		protected List<PlayFX> _playFXsCache = new List<PlayFX>();

		protected int _step;

		protected int _sfp;

		protected readonly List<TSVector2> pointLs = new List<TSVector2>(4);

		public override void OnDisable()
		{
			base.OnDisable();
			StopCoroutine(ref corPlayFx);
			StopCoroutine(ref hit);
		}

		public void OnUpdate()
		{
			if (_actor.logicVariable.GetLogicTagToggle("beiginS"))
			{
				_actor.logicVariable.ToggleLogicTag("beiginS", value: false);
				StartCoroutine(ref hit, Shoot());
			}
		}

		protected IEnumerator Shoot()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(1f));
			pointLs.Clear();
			LogicEntity target = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (target != null)
			{
				TSVector2 tSVector = target.tsTransform.Position + new TSVector2(-3, 3);
				if (_actor.QueryPositionReachable(tSVector))
				{
					pointLs.Add(tSVector);
				}
				tSVector = target.tsTransform.Position + new TSVector2(3, 3);
				if (_actor.QueryPositionReachable(tSVector))
				{
					pointLs.Add(tSVector);
				}
				tSVector = target.tsTransform.Position + new TSVector2(3, -3);
				if (_actor.QueryPositionReachable(tSVector))
				{
					pointLs.Add(tSVector);
				}
				tSVector = target.tsTransform.Position + new TSVector2(-3, -3);
				if (_actor.QueryPositionReachable(tSVector))
				{
					pointLs.Add(tSVector);
				}
			}
			for (int i = 0; i < _playFXs.Count; i++)
			{
				_playFXs[i]?.Stop(dontPlaySubFX: true);
			}
			_playFXs.Clear();
			for (int j = 0; j < pointLs.Count; j++)
			{
				PlayFX playFX = new PlayFX();
				playFX.Play(_actor, null, effectPath1, 0, pointLs[j], _actor.tsTransform.Forward, null, 1f, 1.5f);
				_playFXs.Add(playFX);
			}
			if (_playFXs.Count <= 0)
			{
				yield break;
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.3f));
			for (int k = 0; k < _playFXs.Count; k++)
			{
				_playFXs[k].Stop();
				_playFXs[k].Play(_actor, null, effectPath2, 0, pointLs[k], default(TSVector2));
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.5f));
			for (int l = 0; l < _playFXs.Count; l++)
			{
				_playFXs[l].Stop();
				_playFXs[l].Play(_actor, null, effectPath3, 0, pointLs[l], default(TSVector2));
			}
			int frame = 0;
			while (frame < 90)
			{
				if (frame < 60)
				{
					int num = -1;
					for (int m = 0; m < pointLs.Count; m++)
					{
						if (TSVector2.DistanceSquared(pointLs[m], target.tsTransform.Position) < 9)
						{
							_playFXs[m]?.Stop();
							_playFXs[m]?.Play(_actor, null, effectPath4, 0, pointLs[m], default(TSVector2));
							CoroutineNode coroutineNode = null;
							StartCoroutine(ref coroutineNode, CirlceAreaHit(pointLs[m]));
							num = m;
						}
					}
					if (num >= 0)
					{
						pointLs.RemoveAt(num);
						_playFXs.RemoveAt(num);
					}
				}
				frame++;
				yield return null;
			}
			for (int n = 0; n < pointLs.Count; n++)
			{
				_playFXs[n]?.Stop();
				_playFXs[n]?.Play(_actor, null, effectPath4, 0, pointLs[n], default(TSVector2));
				CoroutineNode coroutineNode2 = null;
				StartCoroutine(ref coroutineNode2, CirlceAreaHit(pointLs[n]));
			}
		}

		private IEnumerator CirlceAreaHit(TSVector2 position)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.53f));
			CommomAreaHitConfig commomAreaHitConfig = new CommomAreaHitConfig();
			commomAreaHitConfig.position = position;
			commomAreaHitConfig.hitDamageId = hitDamageId;
			ILRuntimeAPI.CircleAreaHit(_actor, commomAreaHitConfig, 3, 0);
		}
	}
	public class Skill_Charger_Daily : SkillSimpleBase
	{
		private readonly ComboInputBuffer.ActionKey[] _ChargerCombo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.B };

		private readonly ComboInputBuffer.ActionKey[] _AttackCombo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._0 };

		private readonly ComboInputBuffer.ActionKey[] _JumpCombo = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._1 };

		private readonly FP StopDistance = 3;

		private readonly float Inr = 0.2f;

		private readonly float InrTime = 2f;

		private readonly FP TurnTime = 1;

		private readonly FP Speed = 15;

		private FP SpaceBetween;

		protected override void OnSkillEnable()
		{
		}

		protected override void OnSkillDisable()
		{
		}

		protected override IEnumerator DoMainLogic()
		{
			BeginAttack(1, _ChargerCombo);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			BeginTrace(GetAttackTarget(), 3, -1, 99);
			for (float i = Inr; i < InrTime; i += Inr)
			{
				SpaceBetween = Distance(GetPosition(), GetEntityPosition(GetAttackTarget()));
				if (GetAttackTarget() == null || SpaceBetween <= StopDistance)
				{
					CancelAttack();
					yield return WaitCombo(ComboAttackType.isRecoveryBegin);
					BeginAttack(3, _AttackCombo, flushInputedKeys: true, forceInterruptAttack: true);
					StopTrace();
					yield return WaitCombo(ComboAttackType.isComboFinish);
					InterruptSkill();
				}
				yield return WaitTime(Inr);
			}
			CancelAttack();
			yield return WaitTime(0.3);
			StopTrace();
			yield return WaitCombo(ComboAttackType.isComboFinish);
			BeginAttack(4, _JumpCombo, flushInputedKeys: true);
			BeginLookAt(GetAttackTarget(), TurnTime, 720);
			yield return WaitCombo(ComboAttackType.isAnticipationEnd);
			StopLookAt();
			SpaceBetween = Distance(GetPosition(), GetEntityPosition(GetAttackTarget()));
			if (SpaceBetween / Speed > 0.5f)
			{
				SpaceBetween = 0.5f * Speed;
				BeginDashActorForward(4, Speed, SpaceBetween, 360, comboWithAttack: true);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				InterruptSkill();
			}
			else
			{
				BeginDashActorForward(4, Speed, SpaceBetween, 360, comboWithAttack: true);
				yield return WaitCombo(ComboAttackType.isComboFinish);
				InterruptSkill();
			}
			yield return WaitTime(1);
		}
	}
