	public class Skill_NormalAttack : SkillAdvancedBase
	{
		protected readonly string selfFx = "fx_10003_base_skill2_start_s";

		protected readonly string eventName1 = "Move";

		protected readonly string eventName2 = "MoveEnd";

		protected FP speed = 4;

		protected FP distance = 1.5;

		protected ComboAttack _comboAttack;

		protected Dash _dash;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				SetSkillPhaseConfig(SkillPhaseFeatureFlag.None, null, SkillPhaseFeatureFlag.None, null);
				_actor.PlayFX(selfFx);
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[3]
				{
					ComboInputBuffer.ActionKey.E,
					ComboInputBuffer.ActionKey.E,
					ComboInputBuffer.ActionKey.E
				};
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				int skillId = ((_skill != null) ? _skill.skillId : 0);
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				Action<string> onCustomEvent = OnCustomEvent;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
			}
		}

		protected void OnCustomEvent(string eventName)
		{
			if (eventName.Equals(eventName1))
			{
				TSVector2 normalized = _actor.tsTransform.Forward.normalized;
				if (_dash == null)
				{
					_dash = new Dash();
				}
				_dash.BeginDash(_actor, normalized, speed, distance, (FP)0, (System.Action)null, (System.Action)null, (System.Action)null, true, false, false, true, true, true, false, default(FP), true);
			}
			else if (eventName.Equals(eventName2))
			{
				_dash?.Interrupte();
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			_skill.Clear();
		}
	}
