			if (comboIndex == 1 && eventName == custom_Dash)
			{
				BeginDashActorForward(1, 8, 2, 30, comboWithAttack: true);
			}
			else if (comboIndex == 2 && eventName == custom_EndDash)
			{
				BeginDashActorForward(2, 8, 2, 30, comboWithAttack: true);
