	public class Action : AIBase
	{
		protected SkillPool _skillPool;

		protected TraceTarget _traceTarget;

		protected CoroutineNode _checkQualifiedSkillCoroutine;

		public void OnDisable()
		{
			_skillPool = null;
			if (_traceTarget != null)
			{
				_traceTarget.Clear();
				_traceTarget = null;
			}
		}

		public void OnStart()
		{
			if (_skillPool == null)
			{
				_skillPool = new SkillPool();
				List<SkillVariable> list = new List<SkillVariable>();
				SkillVariable item = new SkillVariable(1000100, 1, 0, 2, 5, immBondage: false, _actor.LogicTime);
				list.Add(item);
				item = new SkillVariable(9999999, 1, 0, 2, 2, immBondage: false, _actor.LogicTime);
				list.Add(item);
				_skillPool.Init(_actor, list, 0.1);
				_checkQualifiedSkillCoroutine = _actor.StartLogicCoroutine(CheckQualifiedSkill());
			}
			else
			{
				_actor.StartLogicCoroutine(WaitAndCheckQualifiedSkill(0.5f));
			}
		}

		private IEnumerator WaitAndCheckQualifiedSkill(FP seconds)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(seconds));
			_checkQualifiedSkillCoroutine = _actor.StartLogicCoroutine(CheckQualifiedSkill());
		}

		private IEnumerator CheckQualifiedSkill()
		{
			while (true)
			{
				string text = _actor.logicVariable?.GetLogicTagStringValue("Target");
				LogicEntity logicEntity = null;
				if (text != "none")
				{
					CommonUtils.TryParseStringParamToInt(text, out var intValue);
					logicEntity = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(intValue);
					if (logicEntity == null)
					{
						logicEntity = ModuleController<AdventureModuleController>.Instance.QueryPlayerEntityByID(intValue);
					}
				}
				if (logicEntity == null)
				{
					break;
				}
				SkillVariable qualifiedSkill = _skillPool.CheckQualifiedSkill(_actor.LogicTime);
				if (qualifiedSkill == null)
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_skillPool.checkInterval));
					continue;
				}
				if (_traceTarget == null)
				{
					_traceTarget = new TraceTarget();
				}
				bool traceFinish = false;
				bool skillFinish = false;
				_traceTarget.BeginTrace(_actor, logicEntity, qualifiedSkill.releaseDistance, -1, qualifiedSkill.trackTime, delegate
				{
					qualifiedSkill.ResetExpireTime(_actor.LogicTime);
					ILRuntimeAPI.CreateSkill(qualifiedSkill.id, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, delegate
					{
						skillFinish = true;
					});
					traceFinish = true;
				}, delegate(bool isdie, bool isInterrupt)
				{
					if (!isdie)
					{
						qualifiedSkill.ResetExpireTime(_actor.LogicTime);
					}
					traceFinish = true;
					skillFinish = true;
				});
				while (!traceFinish)
				{
					yield return null;
				}
				while (!skillFinish)
				{
					yield return null;
				}
			}
			_actor.Idle();
		}

		public void OnStop()
		{
			_traceTarget?.Clear();
			if (_checkQualifiedSkillCoroutine != null)
			{
				_actor.StopLogicCoroutine(_checkQualifiedSkillCoroutine);
				_checkQualifiedSkillCoroutine = null;
			}
		}
	}
	public class Skill_SimpleAttack : SkillAdvancedBase
	{
		protected CoroutineNode _actionCoroutine;

		protected CoroutineNode _dashCoroutine;

		protected CoroutineNode _finishCoroutine;

		protected LookAtTarget _lookAtTarget;

		protected ComboAttack _comboAttack;

		protected Dash _dash;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			_lookAtTarget?.Clear();
			_dash?.Clear();
			if (_actionCoroutine != null)
			{
				_actor.StopLogicCoroutine(_actionCoroutine);
				_actionCoroutine = null;
			}
			if (_dashCoroutine != null)
			{
				_actor.StopLogicCoroutine(_dashCoroutine);
				_dashCoroutine = null;
			}
			if (_finishCoroutine != null)
			{
				_actor.StopLogicCoroutine(_finishCoroutine);
				_finishCoroutine = null;
			}
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			_actionCoroutine = _actor.StartLogicCoroutine(Action());
		}

		private IEnumerator Action()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.1));
			string text = _actor.logicVariable?.GetLogicTagStringValue("Target");
			LogicEntity logicEntity = null;
			if (text != "none")
			{
				CommonUtils.TryParseStringParamToInt(text, out var intValue);
				logicEntity = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(intValue);
				if (logicEntity == null)
				{
					logicEntity = ModuleController<AdventureModuleController>.Instance.QueryPlayerEntityByID(intValue);
				}
			}
			if (logicEntity != null)
			{
				if (_lookAtTarget == null)
				{
					_lookAtTarget = new LookAtTarget();
				}
				bool lookAtFinish = false;
				_lookAtTarget.BeginLookAt(_actor, logicEntity, 0, 180, delegate
				{
					lookAtFinish = true;
				});
				while (!lookAtFinish)
				{
					yield return null;
				}
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				bool attackFinish = false;
				ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };
				_comboAttack.BeginAttack(_actor, _skill, actionKeys, flushInputedKeys: true, (_skill != null) ? _skill.skillId : 0, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, delegate
				{
					attackFinish = true;
					_finishCoroutine = _actor.StartLogicCoroutine(Finish(0.5));
				});
				_dashCoroutine = _actor.StartLogicCoroutine(Dash());
				while (!attackFinish)
				{
					yield return null;
				}
			}
			else
			{
				_skill.Clear();
			}
		}

		private IEnumerator Dash()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(1));
			if (_dash == null)
			{
				_dash = new Dash();
			}
			_dash.BeginDash(_actor, _actor.tsTransform.Forward, (FP)5, (FP)2, (FP)1, (System.Action)null, (System.Action)null, (System.Action)null, true, false, false, true, true, true, false, default(FP), true);
		}
	}
}
