		{
			LogicEntity entity = null;
			ILRuntimeAPI.SearchByRange(_actor, radius, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					_actor.SearchEntitySortByDistance(result);
					entity = result[0];
				}
			}, isConfront, onlyAlive: true, includeSelf);
			return entity;
