		public static bool CheckTargetIsValid(LogicEntity target, long targetId = 0L, bool ingoreSearchedImmunity = false)
		{
			if (target == null)
			{
				return false;
			}
			if (targetId != 0L && target.Id != targetId)
			{
				return false;
			}
			if (!(target as AdventureActor).actorHealthInfo.isAlive)
			{
				return false;
