		}

		public static bool CheckAndSetDodgeCrossObstacleMode(AdventureActor actor, float realDodgeDistance, float crossDodgeAdditionDistance, float crossDodgeKeepAwayNavmeshEdgeDistance, bool CrossObstacle = false)
		{
			bool result = false;
			if (!actor.dodgeCrossObstacle)
			{
				return false;
			}
			TSVector2 origin = actor.tsTransform.Position;
			TSVector2 direction = actor.tsTransform.Forward;
			if (actor is PlayerAdventureActor)
			{
				direction = (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() ? SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() : actor.tsTransform.Forward);
			}
			if (CrossObstacle)
			{
				result = SceneSingleton<DeterministicCollisionManager>.Instance.Raycast(ref origin, ref direction, out var _, realDodgeDistance, 4096);
			}
			TSVector2 tSVector = origin + direction * realDodgeDistance;
			if (actor.QueryPositionWalkable(tSVector) && actor.QueryPositionReachable(tSVector))
			{
				actor.crossObstacleMode = true;
				actor.crossObstacleModeSpeedMultiply = 1;
				return result;
			}
			TSVector2 tSVector2 = tSVector + direction * crossDodgeAdditionDistance;
			if (actor.QueryPositionWalkable(tSVector2) && actor.QueryPositionReachable(tSVector2))
			{
				if (actor.LinecastNavmeshGraph(tSVector2, tSVector, out var linecastHitPoint, offset: false, actor.tsTransform.PositionY, actor.tsTransform.PositionY))
				{
					FP fP = TSVector2.Distance(linecastHitPoint, tSVector);
					FP crossObstacleModeSpeedMultiply = (realDodgeDistance + fP + crossDodgeKeepAwayNavmeshEdgeDistance) / realDodgeDistance;
					actor.crossObstacleMode = true;
					actor.crossObstacleModeSpeedMultiply = crossObstacleModeSpeedMultiply;
					return true;
				}
				return false;
			}
			return false;
		}

		public static bool CheckAndSetCrossObstacleMode(AdventureActor actor, float realMoveDistance, float crossMoveAdditionDistance, float crossMoveKeepAwayNavmeshEdgeDistance, bool CrossObstacle = false)
		{
			return CheckAndSetDodgeCrossObstacleMode(actor, realMoveDistance, crossMoveAdditionDistance, crossMoveKeepAwayNavmeshEdgeDistance, CrossObstacle);
		}

