		public void ExecuteFollowEvent(MonsterActionBranch branchInfo)
		{
			_forceExecuteBranchId = 0;
			ExecuteFollowEvent((GameEnum.monsterAIBranchFollowEventType)branchInfo.FollowEventType1, branchInfo.FollowEventParam1, branchInfo.Id);
			ExecuteFollowEvent((GameEnum.monsterAIBranchFollowEventType)branchInfo.FollowEventType2, branchInfo.FollowEventParam2, branchInfo.Id);
			ExecuteFollowEvent((GameEnum.monsterAIBranchFollowEventType)branchInfo.FollowEventType3, branchInfo.FollowEventParam3, branchInfo.Id);
		}

		protected void ExecuteFollowEvent(GameEnum.monsterAIBranchFollowEventType eventType, string param, int branchId)
		{
			if (eventType == GameEnum.monsterAIBranchFollowEventType.NONE)
			{
				return;
			}
			List<int> list = new List<int>();
			string[] array = param.Split(',');
			for (int i = 0; i < array.Length; i++)
			{
				if (!CommonUtils.TryParseStringParamToInt(array[i], out var intValue))
				{
					NovaLogger.Error($"ai branch follow event param convert error，branch id:{branchId}, param:{param}");
				}
				else
				{
					list.Add(intValue);
				}
			}
			if (list.Count > 0)
			{
				ExecuteCustomEvent(eventType, list);
			}
		}

		public void ExecuteCustomEvent(GameEnum.monsterAIBranchFollowEventType eventType, List<int> ids)
		{
			switch (eventType)
			{
			case GameEnum.monsterAIBranchFollowEventType.DEACTIVE_CERTAIN_ID_AI:
			{
				for (int num3 = 0; num3 < ids.Count; num3++)
				{
					DeActiveBranchById(ids[num3]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.ACTIVE_CERTAIN_ID_AI:
			{
				for (int m = 0; m < ids.Count; m++)
				{
					ActiveBranchById(ids[m]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.DEACTIVE_CERTAIN_GROUPID_AI:
			{
				for (int num = 0; num < ids.Count; num++)
				{
					DectiveBranchByGroupId(ids[num]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.ACTIVE_CERTAIN_GROUPID_AI:
			{
				for (int k = 0; k < ids.Count; k++)
				{
					ActiveBranchByGroupId(ids[k]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.EXECUTE_CERTAIN_ID_AI:
				_executeImmediateBranchId = ids[0];
				break;
			case GameEnum.monsterAIBranchFollowEventType.CLOSE_CERTAIN_ID_AI:
			{
				for (int num2 = 0; num2 < ids.Count; num2++)
				{
					CloseBranchById(ids[num2]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.CLOSE_CERTAIN_GROUPID_AI:
			{
				for (int n = 0; n < ids.Count; n++)
				{
					CloseBranchByGroupId(ids[n]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.OPEN_CERTAIN_ID_AI:
			{
				for (int l = 0; l < ids.Count; l++)
				{
					OpenBranchById(ids[l]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.OPEN_CERTAIN_GROUPID_AI:
			{
				for (int j = 0; j < ids.Count; j++)
				{
					OpenBranchByGroupId(ids[j]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.FORCE_EXECUTE_CERTAIN_ID_AI:
				_forceExecuteBranchId = ids[0];
				break;
			case GameEnum.monsterAIBranchFollowEventType.CERTAIN_ID_AI_BEGIN_CD:
			{
				for (int i = 0; i < ids.Count; i++)
				{
					BeginCDById(ids[i]);
				}
				break;
			}
			case GameEnum.monsterAIBranchFollowEventType.CERTAIN_ID_AI_CLEAR_CASTSKILLTIME:
				ClearBranchCastSkillTimes(ids[0]);
				break;
			case GameEnum.monsterAIBranchFollowEventType.CERTAIN_ID_GROUP_CLEAR_CASTSKILLTIME:
				ClearBranchCastSkillTimes(0, ids[0]);
				break;
			}
		}

		protected void ActiveBranchById(int id)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.Id == id)
				{
					if (!branchInfo.closed)
					{
						branchInfo.actived = true;
					}
					break;
				}
			}
		}

		protected void DeActiveBranchById(int id)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.Id == id)
				{
					if (!branchInfo.closed)
					{
						branchInfo.actived = false;
					}
					break;
				}
			}
		}

		protected void ActiveBranchByGroupId(int groupId)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (!branchInfo.closed && branchInfo.baseInfo.GroupId == groupId)
				{
					branchInfo.actived = true;
				}
			}
		}

		protected void DectiveBranchByGroupId(int groupId)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (!branchInfo.closed && branchInfo.baseInfo.GroupId == groupId)
				{
					branchInfo.actived = false;
				}
			}
		}

		protected void CloseBranchById(int id)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.Id == id)
				{
					branchInfo.closed = true;
					break;
				}
			}
		}

		protected void OpenBranchById(int id)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.Id == id)
				{
					branchInfo.closed = false;
					break;
				}
			}
		}

		protected void CloseBranchByGroupId(int groupId)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.GroupId == groupId)
				{
					branchInfo.closed = true;
				}
			}
		}

		protected void OpenBranchByGroupId(int groupId)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.GroupId == groupId)
				{
					branchInfo.ResetRandomAiCd();
					branchInfo.closed = false;
				}
			}
		}

		protected void BeginCDById(int id)
		{
			foreach (BranchInfo branchInfo in _branchInfos)
			{
				if (branchInfo.baseInfo.Id == id)
				{
					branchInfo.ResetAiCdExpireTime(_actor.LogicTime);
					break;
				}
			}
		}
	}
	public class BranchInfo
	{
		public readonly MonsterActionBranch baseInfo;

		public FP aiCdExpireTime;

		public FP skillCdExpireTime;

		public bool immBondage;

		public int weightStartIndex;

		public int weightEndIndex;

		public bool actived;

		public bool closed;

		public bool isRunning;

		private AdventureActor actor;

		public BranchInfo(MonsterActionBranch monsterActionBranch, FP currentTime, AdventureActor _actor)
		{
			immBondage = false;
			baseInfo = monsterActionBranch;
			actor = _actor;
			ResetRandomAiCd();
			actived = baseInfo.Activate;
		}

		public void ResetRandomAiCd()
		{
			if (!(actor == null))
			{
				FP fP = 0;
				if (baseInfo.InitialCDPool.Count > 0)
				{
					int index = TSRandom.Range(0, baseInfo.InitialCDPool.Count);
					fP = baseInfo.InitialCDPool[index] * GameDataController.IntFloatPrecisionFP;
				}
				aiCdExpireTime = actor.LogicTime + fP;
			}
		}

		public void ResetAiCdExpireTime(FP currentTime)
		{
			if (actor is MonsterAdventureActor monsterAdventureActor)
			{
				if (baseInfo.FixedCD)
				{
					aiCdExpireTime = currentTime + baseInfo.CD * GameDataController.IntFloatPrecisionFP * monsterAdventureActor.aiBranchCDRatio;
				}
				else
				{
					aiCdExpireTime = currentTime + baseInfo.CD * GameDataController.IntFloatPrecisionFP;
				}
			}
			else if (actor is TrapAdventureActor)
			{
				if (baseInfo.FixedCD)
				{
					aiCdExpireTime = currentTime + baseInfo.CD * GameDataController.IntFloatPrecisionFP * 1;
				}
				else
				{
					aiCdExpireTime = currentTime + baseInfo.CD * GameDataController.IntFloatPrecisionFP;
				}
			}
		}

		public void ClearAiCdExpireTime(FP currentTime)
		{
			if (baseInfo.FixedCD)
			{
				aiCdExpireTime = currentTime;
			}
		}

		public void SetSkillCdExpireTime(FP cd, FP currentTime)
		{
			skillCdExpireTime = cd + currentTime;
		}
	}
