	public class SkillPool
	{
		protected AdventureActor _actor;

		protected List<SkillVariable> _skillVariables;

		protected FP _checkInterval;

		public FP checkInterval => _checkInterval;

		public void Init(AdventureActor actor, List<SkillVariable> skillVariables, FP checkInterval)
		{
			_actor = actor;
			_skillVariables = skillVariables;
			_checkInterval = checkInterval;
		}

		public SkillVariable CheckQualifiedSkill(FP currentTime)
		{
			if (_skillVariables == null || _skillVariables.Count == 0)
			{
				return null;
			}
			for (int i = 0; i < _skillVariables.Count; i++)
			{
				SkillVariable skillVariable = _skillVariables[i];
				FP fP = skillVariable.cdExpireTime - currentTime;
				if (fP < 0f)
				{
					fP = 0f;
				}
				if (!(fP > 0f) && (skillVariable.ConditionFunc == null || skillVariable.ConditionFunc()) && (skillVariable.immBondage || !(_actor != null) || !_actor.isBondage))
				{
					return skillVariable;
				}
			}
			return null;
		}

		public SkillVariable GetSkill(int skillId)
		{
			if (_skillVariables == null || _skillVariables.Count == 0)
			{
				return null;
			}
			for (int i = 0; i < _skillVariables.Count; i++)
			{
				if (_skillVariables[i].id == skillId)
				{
					return _skillVariables[i];
				}
			}
			return null;
		}
	}
	public class SkillVariable
	{
		public readonly int id;

		public FP cdMax;

		public FP cdInit;

		public FP releaseDistance;

		public FP trackTime;

		public readonly bool immBondage;

		public FP cdExpireTime;

		private Func<bool> _conditionFunc;

		public Func<bool> ConditionFunc => _conditionFunc;

		public SkillVariable(int id, FP cdMax, FP cdInit, FP releaseDistance, FP trackTime, bool immBondage, FP currentTime, Func<bool> conditionFunc = null)
		{
			this.id = id;
			this.cdMax = cdMax;
			this.cdInit = cdInit;
			this.releaseDistance = releaseDistance;
			this.trackTime = trackTime;
			this.immBondage = immBondage;
			cdExpireTime = currentTime + cdInit;
			if (conditionFunc != null)
			{
				_conditionFunc = conditionFunc;
			}
		}

		public void SetCondition(Func<bool> conditionFunc)
		{
			_conditionFunc = conditionFunc;
		}

		public void ResetExpireTime(FP currentTime)
		{
			cdExpireTime = currentTime + cdMax;
		}

		public void ClearExpireTime()
		{
			cdExpireTime = 0;
		}
	}
