	public class Skill_Bullet_Summon
	{
		private AdventureActor _actor;

		private AdventureSkill _skill;

		private string _customEventName;

		private int _search_inner_radius;

		private int _search_outer_radius;

		private int _summon_count = 3;

		private string _bullet_alias;

		private string _bullet_tag;

		private bool _alreadyShoot;

		private int _bulletCount;

		private FP _forceShootTime = 3;

		private CoroutineNode _waitForForceShootCoroutine;

		public void OnStart(AdventureActor actor, ComboAttack comboAttack, ComboInputBuffer.ActionKey[] actionKeys, AdventureSkill skill, string customEventName, int summonCount, string bulletAlias, string bulletTag, int searchInnerRadius, int searchOuterRadius, FP forceShootTime = default(FP))
		{
			_actor = actor;
			_skill = skill;
			_customEventName = customEventName;
			_summon_count = summonCount;
			_bullet_alias = bulletAlias;
			_bullet_tag = bulletTag;
			_search_inner_radius = searchInnerRadius;
			_search_outer_radius = searchOuterRadius;
			if (forceShootTime != default(FP) && forceShootTime > 0)
			{
				_forceShootTime = forceShootTime;
			}
			int skillId = ((skill != null) ? skill.skillId : 0);
			System.Action onInterrupt = Interrupt;
			System.Action onComboFinish = Finish;
			Action<string> onCustomEvent = OnCustomEvent;
			comboAttack.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
			_waitForForceShootCoroutine = _actor.StartLogicCoroutine(ForceShoot(_forceShootTime));
		}

		public void OnClear()
		{
			_alreadyShoot = false;
			_bulletCount = 0;
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			if (_waitForForceShootCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForForceShootCoroutine);
				_waitForForceShootCoroutine = null;
			}
		}

		private void OnCustomEvent(string eventName)
		{
			if (eventName.Equals(_customEventName) && !_alreadyShoot)
			{
				ShootBehaviour();
			}
		}

		private void ShootBehaviour()
		{
			_alreadyShoot = true;
			int num = 360 / _summon_count;
			TSVector2 tSVector = _actor.tsTransform.Forward;
			Shoot(tSVector);
			for (int i = 1; i < _summon_count; i++)
			{
				tSVector = TSVector2.Rotate(tSVector, num);
				Shoot(tSVector);
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("BULLET_FINISH", OnBulletFinish);
			if (_bulletCount == 0)
			{
				_skill.Clear();
			}
		}

		protected void OnBulletFinish(IEvent evt)
		{
			AdventureBulletFinishEvent adventureBulletFinishEvent = evt as AdventureBulletFinishEvent;
			if (!(adventureBulletFinishEvent.owner == null) && !(adventureBulletFinishEvent.owner != _actor) && string.Equals(adventureBulletFinishEvent.tag, _bullet_tag))
			{
				_bulletCount--;
				if (_bulletCount == 0)
				{
					_skill.Clear();
				}
			}
		}

		private void Shoot(TSVector2 direction)
		{
			TSVector2 position = _actor.tsTransform.Position;
			int num = TSRandom.Range(_search_inner_radius, _search_outer_radius);
			TSVector2 tSVector = position + direction * num;
			if (!_actor.QueryPositionReachable(tSVector))
			{
				tSVector = GetRandomPoint(position);
			}
			if (position != tSVector)
			{
				string bullet_alias = _bullet_alias;
				AdventureActor actor = _actor;
				TSVector2 targetPosition = tSVector;
				if (ILRuntimeAPI.Shoot(bullet_alias, actor, default(FP), position, default(FP), targetPosition, null, AimType.Position, BulletDirectionType.BulletToTarget) != null)
				{
					_bulletCount++;
				}
			}
		}

		private TSVector2 GetRandomPoint(TSVector2 position)
		{
			DeterministicShape deterministicCircleShape = CommonUtils.GetDeterministicCircleShape(_search_outer_radius, _search_inner_radius, position);
			return ILRuntimeAPI.GetRandomPointInShape(_actor, deterministicCircleShape);
		}

		private void Interrupt()
		{
			if (!_alreadyShoot)
			{
				ShootBehaviour();
			}
		}

		private void Finish()
		{
			if (!_alreadyShoot)
			{
				ShootBehaviour();
			}
		}

		private IEnumerator ForceShoot(FP forceShootTime)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(forceShootTime));
			if (!_alreadyShoot)
			{
				ShootBehaviour();
			}
		}
	}
	public class Skill_Dash
	{
		private LookAtTarget _lookAtTarget;

		private ComboAttack _comboAttack;

		private Dash _dash;

		private bool _anticipationEnd;

		private AdventureSkill _skill;

		private AdventureActor _actor;

		private FP _rotateSpeed;

		private string _eventNameStartLookAt;

		private string _eventNameEndLookAt;

		private FP _dashDistance;

		private FP _dashSpeed;

		private bool _stopWhenContactActor;

		public void OnEnable(AdventureActor actor, AdventureSkill skill, ComboInputBuffer.ActionKey[] actionKeys, FP rotateSpeed, string eventNameStartLookAt, string eventNameEndLookAt, FP dashDistance, bool absSpeed, FP dashSpeedOrMultiple, bool stopWhenContactActor)
		{
			_actor = actor;
			_skill = skill;
			_rotateSpeed = rotateSpeed;
			_eventNameStartLookAt = eventNameStartLookAt;
			_eventNameEndLookAt = eventNameEndLookAt;
			_dashDistance = dashDistance;
			_dashSpeed = dashSpeedOrMultiple;
			_stopWhenContactActor = stopWhenContactActor;
			if (!absSpeed)
			{
				_dashSpeed = actor.actorInfo.runSpeed * dashSpeedOrMultiple;
			}
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack comboAttack = _comboAttack;
			int skillId = ((skill != null) ? _skill.skillId : 0);
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onComboFinish = OnComboFinishOrInterrupt;
			System.Action onInterrupt = OnComboFinishOrInterrupt;
			comboAttack.BeginAttack(actor, skill, actionKeys, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnAnticipationEnd()
		{
			_anticipationEnd = true;
			_lookAtTarget?.StopLookAt();
			if (_dash == null)
			{
				_dash = new Dash();
			}
			_dash.BeginDashActorForward(_actor, _dashSpeed, _dashDistance, 0, triggerEnemyStop: _stopWhenContactActor, finishCallback: DashFinish, finishByActorCallback: DashFinish, finishByObstacleCallback: DashFinish, comboWithAttack: true, isAngle: false, notChangeForward: false, triggerObstacleStop: true, triggerFriendStop: false);
		}

		private void DashFinish()
		{
			_comboAttack?.CancelAttack();
		}

		private void OnComboFinishOrInterrupt()
		{
			_skill.Clear();
		}

		private void OnCustomEvent(string eventName)
		{
			if (eventName.Equals(_eventNameStartLookAt))
			{
				if (!_anticipationEnd)
				{
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAt(_actor, SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, 999, _rotateSpeed, null);
				}
			}
			else if (eventName.Equals(_eventNameEndLookAt))
			{
				_lookAtTarget?.StopLookAt();
			}
		}

		public void OnDisable()
		{
			_comboAttack?.Clear();
			_lookAtTarget?.Clear();
			_dash?.Clear();
			_anticipationEnd = false;
			_skill = null;
			_actor = null;
		}
	}
	public class Skill_Free
	{
		protected AdventureActor _actor;

		private AdventureSkill skill;

		private DeterministicShape _shape;

		protected CoroutineNode _waitCoroutine;

		protected LookAtTarget _lookAtTarget;

		protected FP maxTime;

		public void _onStart(AdventureActor actor, bool _playerCenter, FP _radius, FP _innerRadius, FP _angle, FP _rotation, FP _maxTime, AdventureSkill _skill, bool useLineRotate = false)
		{
			_actor = actor;
			_shape.shapeType = DeterministicShape.ShapeType.Fan;
			_shape.angle = _angle;
			_shape.radius = _radius;
			_shape.innerRadius = _innerRadius;
			skill = _skill;
			maxTime = _maxTime;
			_actor.logicVariable?.ToggleLogicTag("ExecutingCanBreakSkill", value: true);
			if (_playerCenter)
			{
				LogicEntity monsterTarget = _actor.monsterTarget;
				if (monsterTarget == null)
				{
					skill.Clear();
					return;
				}
				_shape.position = monsterTarget.tsTransform.Position;
				if (!useLineRotate)
				{
					_shape.rotation = monsterTarget.tsTransform.Rotation360 + _rotation;
				}
				else
				{
					_shape.rotation = (_actor.tsTransform.Position - monsterTarget.tsTransform.Position).GetAngle() + _rotation;
				}
			}
			else
			{
				_shape.position = _actor.tsTransform.Position;
				if (!useLineRotate)
				{
					_shape.rotation = _actor.tsTransform.Rotation360 + _rotation;
				}
				else
				{
					LogicEntity monsterTarget2 = _actor.monsterTarget;
					if (monsterTarget2 == null)
					{
						skill.Clear();
						return;
					}
					_shape.rotation = (monsterTarget2.tsTransform.Position - _actor.tsTransform.Position).GetAngle() + _rotation;
				}
			}
			toRandomPoint();
			_waitCoroutine = _actor.StartLogicCoroutine(waitCoroutine());
		}

		public void clear()
		{
			_actor.logicVariable?.ToggleLogicTag("ExecutingCanBreakSkill", value: false);
			if (_waitCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitCoroutine);
				_waitCoroutine = null;
			}
			_lookAtTarget?.Clear();
		}

		protected void toRandomPoint()
		{
			TSVector2 targetPosition = _actor.RandomActorReachablePointInsideShape(_shape);
			_actor.MoveTo(targetPosition, 0.1, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
			{
				LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				if (activedPlayerActor != null)
				{
					if (_lookAtTarget == null)
					{
						_lookAtTarget = new LookAtTarget();
					}
					_lookAtTarget.BeginLookAtByPos(_actor, activedPlayerActor.tsTransform.Position, 0, 0, delegate
					{
						skill.Clear();
					});
				}
			});
		}

		private IEnumerator waitCoroutine()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(maxTime));
			skill.Clear();
		}
	}
	public class Skill_LightingChain
	{
		private readonly int _hitDamageId;

		private readonly string _hitFxPath;

		private readonly int _hitDamageId_for_secend;

		private readonly string _hitFxPath_for_secend;

		private readonly FP _doubleHitInterval;

		private readonly FP _linkHitInterval;

		private readonly FP _linkCheckRange;

		private readonly int _maxLinkTime;

		private readonly FP _maxCoolingTime;

		private readonly FP _executeRate;

		private readonly AdventureActor _actor;

		private int _linkTimes;

		private CoroutineNode _waitForDoubleHitCoroutine;

		private CoroutineNode _waitForLinkHitCoroutine;

		private readonly List<LogicEntity> _ridList = new List<LogicEntity>();

		private FP _coolingTime;

		private CoroutineNode _cdCoroutine;

		public Skill_LightingChain(AdventureActor from, int hitDamageId, string hitFxPath, int hitDamageIdForSecond, string hitFxPathForSecond, FP doubleHitInterval, FP linkHitInterval, FP linkCheckRange, int maxLinkTime, FP maxCoolingTime, FP executeRate)
		{
			_hitDamageId = hitDamageId;
			_hitFxPath = hitFxPath;
			_hitDamageId_for_secend = hitDamageIdForSecond;
			_hitFxPath_for_secend = hitFxPathForSecond;
			_doubleHitInterval = doubleHitInterval;
			_doubleHitInterval = doubleHitInterval;
			_linkHitInterval = linkHitInterval;
			_linkCheckRange = linkCheckRange;
			_maxLinkTime = maxLinkTime;
			_maxCoolingTime = maxCoolingTime;
			_executeRate = executeRate;
			_actor = from;
		}

		public void Start(AdventureActor target, bool doubleHit = true)
		{
			if (!(_coolingTime > 0) && !(TSRandom.value > _executeRate))
			{
				_coolingTime = _maxCoolingTime;
				_cdCoroutine = _actor.StartLogicCoroutine(CdHandler());
				if (doubleHit)
				{
					_waitForDoubleHitCoroutine = _actor.StartLogicCoroutine(WaitForDoubleHit(target));
				}
				else
				{
					ExtraHit(target, firstCheck: true);
				}
			}
		}

		private IEnumerator CdHandler()
		{
			while (_coolingTime > 0)
			{
				_coolingTime -= _actor.LogicDeltaTime;
				yield return null;
			}
		}

		private IEnumerator WaitForDoubleHit(AdventureActor target)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_doubleHitInterval));
			if (target != null && target.actorHealthInfo.isAlive)
			{
				ILRuntimeAPI.HitActor(_actor, target, _hitDamageId_for_secend, (string)null, _hitFxPath_for_secend, true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
				ExtraHit(target, firstCheck: true);
			}
			else
			{
				OnFinish();
			}
		}

		private void ExtraHit(AdventureActor target, bool firstCheck = false)
		{
			if (_linkTimes >= _maxLinkTime)
			{
				OnFinish();
				return;
			}
			if (firstCheck)
			{
				_ridList.Add(_actor);
			}
			_ridList.Add(target);
			ILRuntimeAPI.SearchByRange(target, _linkCheckRange, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					for (int i = 0; i < _ridList.Count; i++)
					{
						if (result.Contains(_ridList[i]))
						{
							result.Remove(_ridList[i]);
						}
					}
				}
				if (result.Count == 0)
				{
					OnFinish();
				}
				else
				{
					LogicEntity logicEntity = result[0];
					_actor.hitBox.hurtEffectSource = target.gameObject;
					ILRuntimeAPI.HitActor(_actor, logicEntity as AdventureActor, _hitDamageId, (string)null, _hitFxPath, true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
					_actor.hitBox.hurtEffectSource = null;
					_linkTimes++;
					_waitForLinkHitCoroutine = _actor.StartLogicCoroutine(WaitForLinkHit(logicEntity as AdventureActor));
				}
			});
		}

		private IEnumerator WaitForLinkHit(AdventureActor target)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_linkHitInterval));
			ExtraHit(target);
		}

		public void OnFinish()
		{
			if (_waitForDoubleHitCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForDoubleHitCoroutine);
				_waitForDoubleHitCoroutine = null;
			}
			if (_waitForLinkHitCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForLinkHitCoroutine);
				_waitForLinkHitCoroutine = null;
			}
			_ridList.Clear();
			_linkTimes = 0;
		}

		public void Clear()
		{
			if (_cdCoroutine != null)
			{
				_actor.StopLogicCoroutine(_cdCoroutine);
				_cdCoroutine = null;
			}
			_coolingTime = 0;
		}
	}
	public class Skill_Rush
	{
		private AdventureSkill _skill;

		private AdventureActor _actor;

		private FP _interruptTime;

		private bool _useSpecialRushEnd;

		private ComboInputBuffer.ActionKey[] _actionKeys_SpecialRushEnd;

		private string _endRushLogicTagEventName;

		private ComboAttack _comboAttack;

		private bool _beginStop;

		private FP _continueTime;

		private bool _isIndependent;

		public void OnEnable(AdventureActor actor, AdventureSkill skill, ComboInputBuffer.ActionKey[] actionKeys_Rush, ComboInputBuffer.ActionKey[] actionKeys_Rush_Independent, FP interruptTime, bool useSpecialRushEnd, ComboInputBuffer.ActionKey[] actionKeys_SpecialRushEnd = null, string endRushLogicTagEventName = "")
		{
			_actor = actor;
			_skill = skill;
			_interruptTime = interruptTime;
			_useSpecialRushEnd = useSpecialRushEnd;
			_actionKeys_SpecialRushEnd = actionKeys_SpecialRushEnd;
			_endRushLogicTagEventName = endRushLogicTagEventName;
			_isIndependent = false;
			((PlayerAdventureActor)_actor).dodgeButtonHold = true;
			ComboInputBuffer.ActionKey[] array = actionKeys_Rush;
			if (!_actor.actorSkillManage.HaveDodgeSkill())
			{
				_isIndependent = true;
				array = actionKeys_Rush_Independent;
			}
			_actor.FastSpeedMode(isRunFast: true);
			_continueTime = 0;
			_beginStop = false;
			_actor.CancelAiming();
			_actor?.logicVariable.ToggleLogicTag("IsRush", value: true);
			_actor?.animatorController.SetBool(AdventureActor.AnimationParameterNames.rushCombo, value: true);
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack comboAttack = _comboAttack;
			AdventureActor actor2 = _actor;
			AdventureSkill skill2 = _skill;
			ComboInputBuffer.ActionKey[] actionKeys = array;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			bool isIndependent = _isIndependent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnFinish;
			Action<string> onCustomEvent = OnCustomEvent;
			comboAttack.BeginAttack(actor2, skill2, actionKeys, isIndependent, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent, null, fadeOutAnim: true, null, keyPerfectMatch: true);
		}

		public void OnDisable()
		{
			_comboAttack?.Clear();
			_actor.FastSpeedMode(isRunFast: false);
			((PlayerAdventureActor)_actor).dodgeButtonHold = false;
			_actor?.logicVariable.ToggleLogicTag("IsRush", value: false);
			_actor?.animatorController.SetBool(AdventureActor.AnimationParameterNames.rushCombo, value: false);
			_actor = null;
			_skill = null;
			_actionKeys_SpecialRushEnd = null;
		}

		public void OnUpdate()
		{
			_continueTime += _actor.LogicDeltaTime;
			if (((PlayerAdventureActor)_actor).dodgeButtonHold || _beginStop)
			{
				return;
			}
			_beginStop = true;
			if (_continueTime < _interruptTime)
			{
				if (_useSpecialRushEnd && _actionKeys_SpecialRushEnd != null)
				{
					ComboAttack comboAttack = _comboAttack;
					AdventureActor actor = _actor;
					AdventureSkill skill = _skill;
					ComboInputBuffer.ActionKey[] actionKeys_SpecialRushEnd = _actionKeys_SpecialRushEnd;
					int skillId = ((_skill != null) ? _skill.skillId : 0);
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnFinish;
					Action<string> onCustomEvent = OnCustomEvent;
					comboAttack.BeginAttack(actor, skill, actionKeys_SpecialRushEnd, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
				}
				else
				{
					_comboAttack.InterruptAttack();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_comboAttack.InterruptAttack();
			}
			else if (_actor.attackTarget != null)
			{
				if (_actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAimRange(_actor))
				{
					_comboAttack.InterruptAttack();
				}
				else
				{
					_comboAttack.CancelAttack();
				}
			}
			else
			{
				_comboAttack.CancelAttack();
			}
			_actor?.FastSpeedMode(isRunFast: false);
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnCustomEvent(string eventName)
		{
			if (eventName.Equals(_endRushLogicTagEventName))
			{
				_actor?.logicVariable.ToggleLogicTag("IsRush", value: false);
			}
		}
	}
	public class Skill_TransitionRush
	{
		private AdventureSkill _skill;

		private AdventureActor _actor;

		private ComboAttack _comboAttack;

		private FP _continueTime;

		private FP _duration;

		private bool _canceled;

		public void OnEnable(AdventureActor actor, AdventureSkill skill, ComboInputBuffer.ActionKey[] actionKeys_transitionRush, FP duration)
		{
			_actor = actor;
			_skill = skill;
			_duration = duration;
			if (_comboAttack == null)
			{
				_comboAttack = new ComboAttack();
			}
			ComboAttack comboAttack = _comboAttack;
			AdventureActor actor2 = _actor;
			AdventureSkill skill2 = _skill;
			int skillId = ((_skill != null) ? _skill.skillId : 0);
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnFinish;
			comboAttack.BeginAttack(actor2, skill2, actionKeys_transitionRush, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt);
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		public void OnUpdate()
		{
			if (!_canceled)
			{
				_continueTime += _actor.LogicDeltaTime;
				if (_continueTime >= _duration)
				{
					_canceled = true;
					_comboAttack.InterruptAttack();
				}
				if (!_canceled && !SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput())
				{
					_canceled = true;
					_comboAttack.InterruptAttack();
				}
			}
		}

		public void OnDisable()
		{
			_continueTime = 0;
			_canceled = false;
			_comboAttack?.Clear();
			_actor = null;
			_skill = null;
		}
	}
	public class Skill_Wander
	{
		private FP _skillDuration = 10;

		private FP _moveTime = 2;

		private FP _moveCd = 0.5;

		private FP _nearDistance = 4;

		private FP _farDistance = 8;

		private FP _angle = 30;

		private FP _rotation = 30;

		private float _aimSpeed = 30f;

		private float _changeAngle = 60f;

		private float _newAimSpeed = 180f;

		private AdventureActor _actor;

		private AdventureSkill _skill;

		private DeterministicShape _shape;

		private int step;

		private bool isStepChange;

		private FP stepWalkTime;

		private FP waitTime;

		private FP rotateCD;

		public void clear()
		{
			_actor.logicVariable?.ToggleLogicTag("ExecutingCanBreakSkill", value: false);
			_actor.StandBy((System.Action)null);
			_actor.CancelAiming();
			_actor = null;
			_skill = null;
		}

		public void _onStart(AdventureActor actor, FP skillDuration, FP moveTime, FP moveCd, FP nearDistance, FP farDistance, FP angle, FP rotation, float aimSpeed, float changeAngle, float newAimSpeed, AdventureSkill skill)
		{
			_actor = actor;
			_skill = skill;
			_skillDuration = skillDuration;
			_moveTime = moveTime;
			_moveCd = moveCd;
			_farDistance = farDistance * farDistance;
			_angle = angle;
			_rotation = rotation;
			_aimSpeed = aimSpeed;
			_changeAngle = changeAngle;
			_newAimSpeed = newAimSpeed;
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			stepWalkTime = moveTime;
			_actor.logicVariable?.ToggleLogicTag("ExecutingCanBreakSkill", value: true);
			if (_actor != null && activedPlayerActor != null)
			{
				_shape.shapeType = DeterministicShape.ShapeType.Fan;
				_shape.angle = _angle;
				_shape.radius = farDistance;
				_nearDistance = _actor.actorInfo.walkSpeed * 2;
				_nearDistance = ((_nearDistance < nearDistance) ? _nearDistance : nearDistance);
				_shape.innerRadius = _nearDistance;
				_nearDistance *= _nearDistance;
				_actor.AimAtTarget(activedPlayerActor, _aimSpeed, -1);
				step = 0;
			}
			FP fP = TSVector2.DistanceSquared(activedPlayerActor.tsTransform.Position, _actor.tsTransform.Position);
			if (fP < _nearDistance)
			{
				step = 1;
			}
			else if (fP < _farDistance)
			{
				step = 2;
			}
			else
			{
				step = 3;
			}
		}

		protected void toRandomPoint()
		{
			TSVector2 targetPosition = _actor.RandomActorReachablePointInsideShape(_shape);
			_actor.MoveTo(targetPosition, 0.1, enableNavigation: true, AdventureActor.MovementMode.Walk, delegate
			{
				if (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor != null)
				{
					stepWalkTime = _moveTime;
				}
			});
		}

		private bool isAngleMax()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (activedPlayerActor == null)
			{
				return false;
			}
			return TSVector2.Angle(_actor.tsTransform.Forward, _actor.tsTransform.Position - activedPlayerActor.tsTransform.Position) > _changeAngle;
		}

		public void OnUpdate()
		{
			if (_actor == null || _skill == null)
			{
				return;
			}
			_skillDuration -= _actor.LogicDeltaTime;
			stepWalkTime += _actor.LogicDeltaTime;
			waitTime -= _actor.LogicDeltaTime;
			rotateCD -= _actor.LogicDeltaTime;
			if (_skillDuration < 0)
			{
				_skill.Clear();
				return;
			}
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			if (activedPlayerActor == null)
			{
				return;
			}
			if (rotateCD <= 0 && isAngleMax())
			{
				_actor.CancelAiming();
				_actor.AimAtTarget(activedPlayerActor, _newAimSpeed, -1);
				rotateCD = 0.5;
			}
			if (stepWalkTime <= _moveTime)
			{
				return;
			}
			FP fP = TSVector2.DistanceSquared(activedPlayerActor.tsTransform.Position, _actor.tsTransform.Position);
			if ((fP < _nearDistance) & (stepWalkTime > _moveTime))
			{
				if (step == 1)
				{
					isStepChange = false;
				}
				else
				{
					isStepChange = true;
				}
				waitTime = _moveCd;
				stepWalkTime = 0;
				step = 1;
				TSVector2 normalized = (_actor.tsTransform.Position - activedPlayerActor.tsTransform.Position).normalized;
				_actor.Move(normalized);
			}
			else if ((fP < _farDistance) & (stepWalkTime > _moveTime))
			{
				if (step == 2)
				{
					isStepChange = false;
				}
				else
				{
					isStepChange = true;
				}
				waitTime = _moveCd;
				stepWalkTime = 0;
				step = 2;
				_shape.position = activedPlayerActor.tsTransform.Position;
				FP angle = (_actor.tsTransform.Position - activedPlayerActor.tsTransform.Position).GetAngle();
				if (TSRandom.Range(0, 10) <= 5)
				{
					_shape.rotation = angle + _rotation;
				}
				else
				{
					_shape.rotation = angle - _rotation;
				}
				toRandomPoint();
			}
			else
			{
				if (step == 3)
				{
					isStepChange = false;
				}
				else
				{
					isStepChange = true;
				}
				waitTime = _moveCd;
				stepWalkTime = 0;
				step = 3;
				TSVector2 normalized2 = (activedPlayerActor.tsTransform.Position - _actor.tsTransform.Position).normalized;
				_actor.Move(normalized2);
			}
		}
	}
}
namespace AIScript.Level
{
	public class LevelManager : AIBase
	{
		public void LoadLevelController()
		{
			AdventureLevelController adventureLevelController = null;
			switch (ModuleController<AdventureModuleController>.Instance.levelType)
			{
			case GameEnum.worldLevelType.Mainline:
			case GameEnum.worldLevelType.Branchline:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<MainlineLevelController>();
				break;
			case GameEnum.worldLevelType.RegionBoss:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<RegionBossLevelController>();
				break;
			case GameEnum.worldLevelType.TravelerDuel:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<TravelerduelController>();
				break;
			case GameEnum.worldLevelType.DailyInstance:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<DailyInstanceLevelController>();
				break;
			case GameEnum.worldLevelType.InfinityTower:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<InfinityTowerLevelController>();
				break;
			case GameEnum.worldLevelType.EquipmentInstance:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<EquipmentInstanceLevelController>();
				break;
			case GameEnum.worldLevelType.VampireInstance:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<VampireInstanceLevelController>();
				break;
			case GameEnum.worldLevelType.ScoreBoss:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<ScoreBossLevelController>();
				MonoSingleton<GameController>.Instance.uploadDamageData = true;
				ModuleController<AdventureModuleController>.Instance.StartRecord(MonoSingleton<GameController>.Instance.levelLoadParam.dmgRecordId, Recorders.Types.LevelType.Scoreboss);
				break;
			case GameEnum.worldLevelType.SkillInstance:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<SkillInstanceLevelController>();
				break;
			case GameEnum.worldLevelType.WeeklyCopies:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<WeeklyCopiesLevelController>();
				break;
			case GameEnum.worldLevelType.ActivityLevels:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<ActivityLevelsInstanceController>();
				break;
			case GameEnum.worldLevelType.TowerDefense:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<TowerDefenseLevelController>();
				break;
			case GameEnum.worldLevelType.BrickBreaker:
				adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<BrickBreakerController>();
				break;
			case GameEnum.worldLevelType.Dynamic:
				switch ((HotfixEnum.dynamicLevelType)ModuleController<AdventureModuleController>.Instance.levelLoadParams.dynamicLevelType)
				{
				case HotfixEnum.dynamicLevelType.JointDrill:
					adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<JointDrillLevelController>();
					break;
				case HotfixEnum.dynamicLevelType.Trial:
					adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<TrialLevelController>();
					break;
				case HotfixEnum.dynamicLevelType.Tutorial:
					adventureLevelController = ModuleController<AdventureModuleController>.Instance.controllerContent?.AddComponent<TutorialLevelController>();
					break;
				}
				MonoSingleton<GameController>.Instance.uploadDamageData = true;
				ModuleController<AdventureModuleController>.Instance.StartRecord(MonoSingleton<GameController>.Instance.levelLoadParam.dmgRecordId, Recorders.Types.LevelType.JointDrill1);
				break;
			}
			if (adventureLevelController != null)
			{
				ModuleController<AdventureModuleController>.Instance.levelInstance = adventureLevelController;
			}
		}
	}
}
namespace AIScript.DynamicLevel
{
	public class JointDrillLevelController : AdventureLevelController
	{
		protected new AdventureModuleLevelLoadParams levelLoadParams;

		protected JointDrillLevel levelData;

		protected JointDrillFloor floorData;

		protected new GameObject configPrefab;

		protected bool isStartTime;

		protected FP timeing = 0;

		protected float totalTime;

		protected int levelTotalTime;

		protected const string ZoomFreezeKey = "ZoomFreeze";

		protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

		protected float _zoomFreeze;

		protected float _zoomDurationTime;

		protected bool isSettlement;

		protected new List<PlayerSpawnPointGizmo> playerSpawnPoints = new List<PlayerSpawnPointGizmo>();

		protected new PlayerSpawnPointGizmo playerSpawnPointGizmo;

		protected long bossId;

		protected float hpLessThanValue;

		protected int damageValue;

		protected Dictionary<int, int> charDamageValue = new Dictionary<int, int>();

		private Coroutine corSettlement;

		public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
		{
			base.Load(param, callback);
			levelLoadParams = ModuleController<AdventureModuleController>.Instance?.levelLoadParams;
			levelData = Singleton<HotfixDataController>.Instance.GetJointDrillLevel(CommonHelper.ParseStringParamToInt(levelLoadParams.id));
			levelLoadParams.monsterLevel = levelData.Difficulty;
			int num = CommonHelper.ParseStringParamToInt(levelLoadParams.enterDynamicLevelParams[0]);
			totalTime = (float)CommonHelper.ParseStringParamToInt(levelLoadParams.enterDynamicLevelParams[2]) / 1000f;
			timeing = totalTime % 1f;
			foreach (KeyValuePair<int, JointDrillFloor> jointDrillFloorDatum in Singleton<HotfixDataController>.Instance.JointDrillFloorData)
			{
				if (jointDrillFloorDatum.Value.FloorId == levelData.FloorId && jointDrillFloorDatum.Value.BattleLvs == num)
				{
					floorData = jointDrillFloorDatum.Value;
				}
			}
			if (floorData != null)
			{
				scenePath = "Assets/AssetBundles/" + floorData.SceneName;
				MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string levelSceneName, int process)
				{
					LevelLoadProcessUpdate(levelSceneName, process);
					return true;
				});
				musicName = floorData.BGM;
				leaveMusicEvent = floorData.LeaveTriggerEvent;
			}
			SceneSingleton<AdventureIndicatorController>.Instance.SetupDefaultBlobIndicators();
		}

		protected override void LevelLoadComplete(string sceneName)
		{
			ILRuntimeAPI.LoadConfigPrefab(scenePath, floorData.ConfigPrefabName);
			base.LevelLoadComplete(sceneName);
			string[] array = sceneName.Split('/');
			sceneName = array[array.Length - 1];
			GameObject[] rootGameObjects = SceneManager.GetSceneByName(sceneName).GetRootGameObjects();
			foreach (GameObject gameObject in rootGameObjects)
			{
				if (gameObject.name == "==== Navigation ====")
				{
					HandleNavigation(gameObject, sceneName);
				}
			}
		}

		public override bool HasTimelinePerformance()
		{
			int num;
			if (floorData != null)
			{
				num = ((!string.IsNullOrEmpty(floorData.IntroCutscene)) ? 1 : 0);
				if (num != 0)
				{
					timelineName = floorData.IntroCutscene;
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
		{
			base.PlayTimelinePerformance(delegate
			{
				callback?.Invoke();
				MonoSingleton<LuaManager>.Instance.FireEvent("CloseJumpOverTimeLine");
				MonoSingleton<LuaManager>.Instance.FireEvent("TimeLineFinishBattleDashboardVisible", a1: true);
			}, needLimitPlayTimes);
		}

		public override void LevelStart(System.Action callback = null)
		{
			damageValue = 0;
			levelTotalTime = levelData.BattleTime;
			isStartTime = false;
			isSettlement = false;
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("LEVEL_START_TIMING", StartTiming);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("MONSTER_SPAWN", MonsterSpawn);
			Singleton<EventDispatchManager>.Instance?.AddEventListener("JointDrill_Level_GiveUp", GiveUpLevel);
			Singleton<EventDispatchManager>.Instance?.AddEventListener("JointDrill_Level_TimeOut", TimeOutLevel);
			if (floorData.BattleLvsToggle == 1)
			{
				hpLessThanValue = CommonHelper.ParseStringParamToFloat(floorData.BattleLvsToggleParam1);
				ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_HP_CHANGED", OnHpChange);
			}
			playerSpawnPointGizmo?.LevelStart();
			base.LevelStart(callback);
			callback?.Invoke();
		}

		public override void UpdateLogic(FP logicDeltaTime)
		{
			base.UpdateLogic(logicDeltaTime);
			if (isStartTime)
			{
				timeing += logicDeltaTime;
				totalTime += logicDeltaTime.AsFloat();
				MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_Gameplay_Time", totalTime);
				if (totalTime >= (float)levelTotalTime)
				{
					LevelStateChangedCall(GameEnum.levelState.Failed);
				}
			}
		}

		public override void InitSpawnPoints()
		{
			base.InitSpawnPoints();
			playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
			if (playerSpawnPoints == null || playerSpawnPoints.Count == 0)
			{
				Debug.LogError("关卡中没有配置玩家出生点!");
				return;
			}
			if (null == this.playerSpawnPointGizmo)
			{
				for (int i = 0; i < playerSpawnPoints.Count; i++)
				{
					PlayerSpawnPointGizmo playerSpawnPointGizmo = playerSpawnPoints[i];
					if (string.IsNullOrEmpty(playerSpawnPointGizmo.spawnPointID))
					{
						this.playerSpawnPointGizmo = playerSpawnPointGizmo;
						break;
					}
				}
			}
			if (null == this.playerSpawnPointGizmo)
			{
				Debug.LogError("总力战 没有找到合适的角色出生点!");
				return;
			}
			this.playerSpawnPointGizmo.Initialize(0, 0);
			this.playerSpawnPointGizmo.EnableSpawnLogic();
			this.playerSpawnPointGizmo.ExecuteSpawnLogic();
			if (!base.isViewSceneMode)
			{
				ILRuntimeAPI.HandleSpawnGizmos();
			}
		}

		public override void LevelEnd()
		{
			base.LevelEnd();
			isStartTime = false;
			if (corSettlement != null)
			{
				StopCoroutine(corSettlement);
				corSettlement = null;
			}
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("LEVEL_START_TIMING", StartTiming);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DECLARE_DIED", MonsterDeclareDeath);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("MONSTER_SPAWN", MonsterSpawn);
			Singleton<EventDispatchManager>.Instance?.RemoveEventListener("JointDrill_Level_GiveUp", GiveUpLevel);
			Singleton<EventDispatchManager>.Instance?.RemoveEventListener("JointDrill_Level_TimeOut", TimeOutLevel);
			if (floorData.BattleLvsToggle == 1)
			{
				ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_HP_CHANGED", OnHpChange);
			}
			playerSpawnPoints.Clear();
			playerSpawnPointGizmo?.LevelEnd();
			playerSpawnPointGizmo = null;
			charDamageValue.Clear();
		}

		private void OnPlayerDied(IEvent ievent)
		{
			LevelStateChangedCall(GameEnum.levelState.Failed);
		}

		private void StartTiming(IEvent evt)
		{
			isStartTime = true;
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_StartTiming");
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_Gameplay_Time", (int)totalTime);
		}

		public void MonsterDeclareDeath(IEvent evt)
		{
			if (((AdventureMonsterDeclareDiedEvent)evt).epicType == GameEnum.monsterEpicType.JOINTDRILLBOSS)
			{
				LevelStateChangedCall(GameEnum.levelState.Success);
			}
		}

		private void MonsterSpawn(IEvent evt)
		{
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			AdventureMonsterSpawnedEvent adventureMonsterSpawnedEvent = (AdventureMonsterSpawnedEvent)evt;
			if (adventureMonsterSpawnedEvent != null)
			{
				MonsterAdventureActor monsterAdventureActor = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(adventureMonsterSpawnedEvent.id) as MonsterAdventureActor;
				if (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.JOINTDRILLBOSS)
				{
					bossId = monsterAdventureActor.Id;
					monsterAdventureActor.monsterInfo.maxEnergy = floorData.MaxEnergyValue;
					MonoSingleton<LuaManager>.Instance.FireEvent<long, iFP, iFP>("JointDrill_MonsterSpawn", bossId, monsterAdventureActor.actorHealthInfo.hp, monsterAdventureActor.actorHealthInfo.hpMax);
				}
			}
		}

		private void OnHpChange(IEvent iEvt)
		{
			if (iEvt is AdventureActorHpChangedEvent adventureActorHpChangedEvent)
			{
				AdventureActor adventureActor = adventureActorHpChangedEvent.sender as AdventureActor;
				if (adventureActor.Id == bossId && adventureActor.actorHealthInfo.hpPercentage <= hpLessThanValue)
				{
					GetDamageValue();
					MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_CharDamageValue", charDamageValue);
					MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_BattleLvsToggle", floorData.BattleLvs, totalTime, damageValue);
				}
			}
		}

		protected void LevelStateChangedCall(GameEnum.levelState levelState)
		{
			if (!isSettlement)
			{
				isStartTime = false;
				isSettlement = true;
				MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_StopTime");
				if (levelState == GameEnum.levelState.Success)
				{
					corSettlement = StartCoroutine(CorSettlement((float)floorData.DungeonDelay / 10000f));
					return;
				}
				CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
				CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
				ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
			}
			void Action()
			{
				GetDamageValue();
				MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_CharDamageValue", charDamageValue);
				MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_Result", (int)levelState, totalTime, damageValue);
				LevelStateChanged(levelState);
			}
		}

		private IEnumerator CorSettlement(float delayTime)
		{
			yield return new WaitForSecondsRealtime(delayTime);
			GetDamageValue();
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_CharDamageValue", charDamageValue);
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_Result", 2, totalTime, damageValue);
			LevelStateChanged(GameEnum.levelState.Success);
		}

		private void GiveUpLevel(IEvent ievent)
		{
			GetDamageValue();
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_CharDamageValue", charDamageValue);
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_DamageValue", damageValue);
		}

		private void TimeOutLevel(IEvent ievent)
		{
			GetDamageValue();
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_CharDamageValue", charDamageValue);
			MonoSingleton<LuaManager>.Instance.FireEvent("JointDrill_DamageValue", damageValue);
		}

		private void GetDamageValue()
		{
			for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
			{
				PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i];
				if (playerAdventureActor != null)
				{
					int dataID = playerAdventureActor.dataID;
					int actorDamageInfo = ModuleController<AdventureModuleController>.Instance.GetActorDamageInfo(dataID, true);
					charDamageValue[dataID] = actorDamageInfo;
					damageValue += actorDamageInfo;
				}
			}
		}
	}
