	public class TowerSkillInfo
	{
		public int skillId;

		public FP curSkillEnergy;

		public FP maxSkillEnergy;

		public FP curTime;

		public bool autoCd;

		public Func<bool> CheckCondition;

		public bool isFull => curSkillEnergy >= maxSkillEnergy;

		public TowerSkillInfo(int skillId, FP maxSkillEnergy)
		{
			this.skillId = skillId;
			this.maxSkillEnergy = maxSkillEnergy;
			curSkillEnergy = 0;
			curTime = 0;
		}

		public void Clear()
		{
			curTime = 0;
			curSkillEnergy = 0;
		}
	}
	public class TowerCharacterSkillCom : LogicComponent
	{
		private FP recoveryRatio;

		private Dictionary<int, TowerSkillInfo> dicSkill = new Dictionary<int, TowerSkillInfo>();

		public TowerDefenseCharacterActor owner => (TowerDefenseCharacterActor)base.Entity;

		public void LogicActive()
		{
			recoveryRatio = 1;
			foreach (KeyValuePair<int, TowerSkillInfo> item in dicSkill)
			{
				ResetEnergy(item.Key, auto: true);
			}
		}

		public override void OnActive()
		{
			base.OnActive();
		}

		public override void OnDeactive()
		{
			base.OnDeactive();
		}

		public void RegisterAllSkill(List<TowerSkillInfo> skillInfos)
		{
			for (int i = 0; i < skillInfos.Count; i++)
			{
				TowerSkillInfo towerSkillInfo = skillInfos[i];
				towerSkillInfo.Clear();
				dicSkill.Add(towerSkillInfo.skillId, towerSkillInfo);
			}
		}

		public void UnRegisterAllSkill()
		{
			dicSkill.Clear();
		}

		public void OnLogicUpdate(FP deltaTime)
		{
			foreach (TowerSkillInfo value in dicSkill.Values)
			{
				if (!value.isFull && value.autoCd)
				{
					FP val = value.curSkillEnergy + owner.LogicDeltaTime * recoveryRatio;
					FP maxSkillEnergy = value.maxSkillEnergy;
					value.curSkillEnergy = TSMath.Min(val, maxSkillEnergy);
				}
			}
		}

		public bool CheckFull(int skillId)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				return value.isFull;
			}
			return false;
		}

		public bool HasCastSkill()
		{
			foreach (TowerSkillInfo value in dicSkill.Values)
			{
				if (value.isFull)
				{
					if (value.CheckCondition == null)
					{
						return owner.attackTarget != null;
					}
					if (value.CheckCondition())
					{
						return true;
					}
				}
			}
			return false;
		}

		public bool GetAllCastSkill(ref List<TowerSkillInfo> skillInfos)
		{
			skillInfos.Clear();
			foreach (TowerSkillInfo value in dicSkill.Values)
			{
				if (!value.isFull)
				{
					continue;
				}
				if (value.CheckCondition != null)
				{
					if (value.CheckCondition())
					{
						skillInfos.Add(value);
					}
				}
				else if (owner.attackTarget != null)
				{
					skillInfos.Add(value);
				}
			}
			return skillInfos.Count > 0;
		}

		public void ResetEnergy(int skillId, bool auto)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				value.Clear();
				value.autoCd = auto;
				SyncLua(skillId, value, auto);
			}
		}

		public void BeginEnergy(int skillId)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				value.autoCd = true;
				SyncLua(skillId, value, value.autoCd);
			}
		}

		public void ModifyEnergyByAbs(int skillId, FP energy)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				value.curSkillEnergy += energy;
				value.curSkillEnergy = TSMath.Min(value.curSkillEnergy, value.maxSkillEnergy);
				SyncLua(skillId, value, value.autoCd);
			}
		}

		public void ModifyEnergyByPercent(int skillId, FP percent)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				value.curSkillEnergy += value.maxSkillEnergy * percent / 100f;
				value.curSkillEnergy = TSMath.Min(value.curSkillEnergy, value.maxSkillEnergy);
				SyncLua(skillId, value, value.autoCd);
			}
		}

		public void AddRecoveryEnergyRatio(int skillId, int radio)
		{
			if (dicSkill.TryGetValue(skillId, out var value))
			{
				recoveryRatio += (FP)((float)radio / 100f);
				SyncLua(skillId, value, value.autoCd);
			}
		}

		private void SyncLua(int skillId, TowerSkillInfo skillInfo, bool auto)
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("ResetEnergy", owner.Id, owner.dataID, skillId, skillInfo.curSkillEnergy / recoveryRatio, skillInfo.maxSkillEnergy / recoveryRatio, auto);
		}
	}
	public class TowerDefenseCharacterActor : DynamicActor
	{
		private static string spawnAIPath = "AIScript.Monster.TowerDefense.TowerCharacterSpawn";

		private static string deathAIPath = "AIScript.Monster.TowerDefense.TowerCharacterDeath";

		public FP SearchRange;

		public HotfixEnum.characterSearchTargetTypeTowerDefense SearchType;

		public int deathSkillId;

		public int spawnSkillId;

		public int normalSkillId;

		public int mainSkillId;

		public FP maxEnergy;

		public bool beginEnergyOnCast;

		public TowerCharacterSkillCom skillMgr;

		private bool isActive;

		private List<LogicEntity> entities = new List<LogicEntity>();

		private LogicEntity lastTarget;

		private TowerMonsterInfo lastCom;

		public bool IsActive => isActive;

		protected override void OnInit()
		{
			base.OnInit();
			skillMgr = AddOrGetLogicComponent<TowerCharacterSkillCom>();
		}

		public void LoadData(TowerDefenseCharacter data, MonsterSkin skin)
		{
			base.dataID = data.Id;
			base.skinID = skin.Id;
			normalSkillId = data.NormalAtkId;
			mainSkillId = data.SkillId;
			maxEnergy = data.SkillCd * GameDataController.IntFloatPrecisionFP;
			beginEnergyOnCast = data.CdStartTime;
			actorScaleInfo.originModelScale = skin.ModelScale * GameDataController.IntFloatPrecisionFP;
			actorScaleInfo.modelScale = actorScaleInfo.originModelScale;
			ActorInfo obj = actorInfo;
			int factionID = (actorInfo.originFactionID = data.Faction);
			obj.factionID = factionID;
			actorInfo.moveAcceleration = 99999;
			actorInfo.moveRotationSpeed = 10;
			SearchRange = data.SearchRadius * GameDataController.IntFloatPrecisionFP;
			SetAttrInfo(data.Templete);
			SetSearchInfo((HotfixEnum.characterSearchTargetTypeTowerDefense)data.SearchTargetType);
			SetupPrimeFSM(data.AIId);
			LoadModel((float)base.dtCollider.Radius, (float)base.dtCollider.ColliderHeight);
			base.attackFSM.SetRootMotionScale(actorScaleInfo.modelScale);
			base.isDead = false;
			base.isDeclareDead = false;
		}

		private bool SetAttrInfo(int templeteId, int percent = 100)
		{
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_008d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0096: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
			_ = ModuleController<AdventureModuleController>.Instance.levelLoadParams;
			MonsterValueTempleteAdjust monsterValueTempleteAdjust = Singleton<GameDataController>.Instance.GetMonsterValueTempleteAdjust(templeteId);
			if (monsterValueTempleteAdjust == null)
			{
				Debug.LogError($"Tower templeteInfo adjust config not exist, Templete:{templeteId} ");
				return false;
			}
			SetElementType(monsterValueTempleteAdjust.EET, monsterValueTempleteAdjust.WeakEET);
			long num = (long)monsterValueTempleteAdjust.TemplateId * 1000L + 10 + 1;
			MonsterValueTemplete monsterValueTemplete = Singleton<GameDataController>.Instance.GetMonsterValueTemplete(num);
			if (monsterValueTemplete == null)
			{
				Debug.LogError($"找不到怪物模板数据，ID：{num}");
				return false;
			}
			iFP val = percent / iFP.op_Implicit(100);
			actorHealthInfo.SetOriginAttributeData(monsterValueTemplete, monsterValueTempleteAdjust, iFP.op_Implicit(val));
			actorInfo.SetOriginAttributeData(monsterValueTemplete, monsterValueTempleteAdjust, iFP.op_Implicit(val));
			actorElementInfo.SetOriginAttributeData(monsterValueTemplete, monsterValueTempleteAdjust, iFP.op_Implicit(val));
			return true;
		}

		private void SetElementType(int elementType, IList<int> weakElementType)
		{
			actorElementInfo.originElementType = (GameEnum.elementType)elementType;
			actorElementInfo.elementType = actorElementInfo.originElementType;
		}

		private void SetSearchInfo(HotfixEnum.characterSearchTargetTypeTowerDefense searchType)
		{
			SearchType = searchType;
		}

		public override void SetupPrimeFSM(int aiId)
		{
			if (_primeFSM == null)
			{
				TowerDefenceCharacterAI towerDefenceCharacterAI = Singleton<HotfixDataController>.Instance.GetTowerDefenceCharacterAI(aiId);
				if (towerDefenceCharacterAI != null)
				{
					_comboGroupPath = towerDefenceCharacterAI.ComboGroupPath;
					deathSkillId = towerDefenceCharacterAI.DieSkillId;
					spawnSkillId = towerDefenceCharacterAI.SpawnShowSkillId;
					_primeFSM = new ActorPrimeFSM(base.gameObject);
					_nullState = new ActorNullState();
					_primeFSM.RegistState(_nullState);
					_spawnState = new ActorSpawnState();
					_primeFSM.RegistState(_spawnState, spawnAIPath);
					_actionState = new ActorActionState();
					_primeFSM.RegistState(_actionState, towerDefenceCharacterAI.ActionAIPath);
					_deathState = new TowerCharacterDeathState();
					_primeFSM.RegistState(_deathState, deathAIPath);
					InitParallelAI(towerDefenceCharacterAI.ParallelAIPath);
				}
				base.SetupPrimeFSM(aiId);
			}
		}

		public void LogicActive()
		{
			SceneSingleton<DeterministicCollisionManager>.Instance.UnRegisterCollider(base.dtCollider, ignoreLock: true);
			SceneSingleton<DeterministicCollisionManager>.Instance.RegisterCollider(base.dtCollider, ignoreLock: true);
			isActive = true;
			((AdventureActor)this).EnableMovementAgent(false);
			skillMgr.LogicActive();
			lastTarget = null;
			lastCom = null;
		}

		protected override void OnActive()
		{
			base.OnActive();
		}

		protected override void OnDeactive()
		{
			base.OnDeactive();
			isActive = false;
			entities.Clear();
		}

		public override void LevelStart()
		{
			EnableLogicUpdate();
			Spawn();
			DisableMovementAgent();
		}

		public override void LevelEnd()
		{
		}

		protected override void OnLogicUpdate()
		{
			if (isActive)
			{
				if (!base.isDead)
				{
					skillMgr.OnLogicUpdate(base.LogicDeltaTime);
					_primeFSM.OnUpdate();
					UpdateParallelAI();
					buffComponent.LogicUpdate(base.LogicDeltaTime);
					effectManage?.LogicUpdate(base.LogicDeltaTime);
					updateTime();
				}
				base.attackFSM.OnUpdate();
				base.movementFSM.OnUpdate();
				CheckBrokenLineBulletBack();
			}
		}

		public void Despawn()
		{
			OnShow(show: false);
			base.ActiveSelf = false;
		}

		public LogicEntity SearchTarget()
		{
			if (SearchType == HotfixEnum.characterSearchTargetTypeTowerDefense.NORMAL)
			{
				CommonUtils.SearchNearTargetsByCircleInTD(this, base.tsTransform.Position, SearchRange, entities, isConfront: true);
				if (entities.Count > 0)
				{
					TowerMonsterInfo towerMonsterInfo = null;
					int num = 0;
					bool flag = false;
					for (int i = 0; i < entities.Count; i++)
					{
						TowerMonsterInfo logicComponent = entities[i].GetLogicComponent<TowerMonsterInfo>();
						if (logicComponent != null && logicComponent.CanSelect(this))
						{
							if (lastTarget != null && lastTarget.Id == entities[i].Id)
							{
								flag = true;
							}
							if (num > logicComponent.leftRouteLen || towerMonsterInfo == null)
							{
								num = logicComponent.leftRouteLen;
								towerMonsterInfo = logicComponent;
							}
						}
					}
					if (flag && num >= lastCom.leftRouteLen)
					{
						return lastTarget;
					}
					lastTarget = towerMonsterInfo.Entity;
					lastCom = towerMonsterInfo;
					return towerMonsterInfo.Entity;
				}
			}
			return null;
		}

		protected override void ReleaseVisual()
		{
			base.ReleaseVisual();
			InitializeTransparentFade();
		}

		protected override void SetupVisualComponents(float visibleRadius, float visibleHeight)
		{
			base.SetupVisualComponents(visibleRadius, visibleHeight);
			base.visualControl.SetupBasicActorVisualComponents(visibleRadius, visibleHeight);
			base.visualControl.materialController.MaterialsSetStencilMode(200, RendererMaterialStackComponent.StencilMode.Replace, setToOriginMaterial: true);
			base.visualControl.ResetRenderLayer();
			InitializeTransparentFade();
		}
	}
	public class TowerMonsterInfo : LogicComponent
	{
		public int leftRouteLen { get; set; }

		public bool CanSelect(AdventureActor target)
		{
			return (base.Entity as MonsterAdventureActor).IsSearchableByEnemy(target);
