	public class TowerDefenseLevelController : AdventureLevelController
	{
		private new AdventureModuleLevelLoadParams levelLoadParams;

		private TowerDefenseFloor floorData;

		private new GameObject configPrefab;

		private TowerDefensePrefabData prefabData;

		private TowerDefenseMapData mapData;

		private TowerDefenseGameplayBase gameplay;

		private bool enableMainCameraPhysicsRaycaster;

		private List<int> selRoles;

		private int itemID;

		public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
		{
			MonoSingleton<GameController>.Instance.teamConfig = null;
			base.Load(param, callback);
			levelLoadParams = ModuleController<AdventureModuleController>.Instance?.levelLoadParams;
			floorData = Singleton<HotfixDataController>.Instance.GetTowerDefenseFloor(int.Parse(levelLoadParams.id));
			if (floorData == null)
			{
				Debug.LogError("塔防FloorId出错：" + levelLoadParams.id);
				return;
			}
			levelLoadParams.dynamicBGM = floorData.BGM;
			levelLoadParams.dynamicSceneName = floorData.SceneName;
			levelLoadParams.dynamicLeaveMusicEvent = floorData.LeaveTriggerEvent;
			string[] enterDynamicLevelParams = levelLoadParams.enterDynamicLevelParams;
			if (enterDynamicLevelParams != null && enterDynamicLevelParams.Length >= 2)
			{
				itemID = int.Parse(enterDynamicLevelParams[0]);
				string[] array = enterDynamicLevelParams[1].Split(',');
				if (array != null && array.Length != 0)
				{
					selRoles = new List<int>();
					for (int i = 0; i < array.Length; i++)
					{
						selRoles.Add(int.Parse(array[i]));
					}
				}
			}
			scenePath = "Assets/AssetBundles/" + floorData.SceneName;
			MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string levelSceneName, int process)
			{
				LevelLoadProcessUpdate(levelSceneName, process);
				return true;
			});
			MonoSingleton<GameCameraStackManager>.Instance.autoVerticalToHorizontalFieldOfView = true;
		}

		protected override void LevelLoadComplete(string sceneName)
		{
			base.LevelLoadComplete(sceneName);
			string[] array = scenePath.Split('/');
			Scene sceneByName = SceneManager.GetSceneByName(array[array.Length - 1]);
			string text = scenePath + "/" + floorData.ConfigPrefabName + ".prefab";
			GameObject gameObject = MonoSingleton<SceneLoaderController>.Instance.LoadAsset(scenePath, text, typeof(GameObject)) as GameObject;
			if (gameObject != null)
			{
				configPrefab = UnityEngine.Object.Instantiate(gameObject, Vector3.zero, Quaternion.identity);
				configPrefab.transform.localScale = Vector3.one;
				configPrefab.name = floorData.ConfigPrefabName;
				SceneManager.MoveGameObjectToScene(configPrefab, sceneByName);
			}
			if (null == configPrefab)
			{
				Debug.LogError("策划配置预制体加载失败：" + text);
				return;
			}
			TowerDefensePrefabData component = configPrefab.GetComponent<TowerDefensePrefabData>();
			if (null == component)
			{
				Debug.LogError("策划配置预制体没有塔防数据组件：" + floorData.ConfigPrefabName);
				return;
			}
			mapData = component.mapData;
			if (null == mapData)
			{
				Debug.LogError("策划配置预制体没有塔防数据：" + floorData.ConfigPrefabName);
			}
			else
			{
				gameplay = CreateGameplayInstance(floorData.LevelScript);
			}
		}

		private TowerDefenseGameplayBase CreateGameplayInstance(string path)
		{
			LocalTypeCache localTypeCache = MonoSingleton<HybridCLRManager>.Instance.LoadLocalTypes(path);
			if (localTypeCache == null)
			{
				return null;
			}
			return Activator.CreateInstance(localTypeCache.type) as TowerDefenseGameplayBase;
		}

		public override void LevelStart(System.Action callback = null)
		{
			base.LevelStart(callback);
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			if (floorData.MemberNum <= 0)
			{
				list.AddRange(floorData.TeamGroup.ToList());
				int initPlayerNum = floorData.InitPlayerNum;
				if (initPlayerNum > 0)
				{
					List<int> list3 = floorData.InitPlayers.ToList();
					if (list3.Count < initPlayerNum)
					{
						list2.AddRange(list3);
						for (int i = 0; i < list3.Count; i++)
						{
							list.Remove(list3[i]);
						}
						int num = initPlayerNum - list3.Count;
						for (int j = 0; j < num; j++)
						{
							int index = TSRandom.Range(0, list.Count);
							list2.Add(list[index]);
							list.RemoveAt(index);
						}
					}
					else
					{
						for (int k = 0; k < initPlayerNum; k++)
						{
							int index2 = TSRandom.Range(0, list3.Count);
							int item = list3[index2];
							list2.Add(item);
							list3.RemoveAt(index2);
							list.Remove(item);
						}
					}
				}
			}
			else if (selRoles != null && selRoles.Count > 0)
			{
				list = selRoles;
				for (int l = 0; l < floorData.InitPlayerNum; l++)
				{
					if (list.Count == 0)
					{
						break;
					}
					int index3 = TSRandom.Range(0, list.Count);
					list2.Add(list[index3]);
					list.RemoveAt(index3);
				}
			}
			List<int> list4 = new List<int>();
			foreach (TowerDefenseTeamExp value in Singleton<HotfixDataController>.Instance.TowerDefenseTeamExpData.Values)
			{
				if (value.FloorId == floorData.Id)
				{
					list4.Add(value.Exp);
				}
			}
			TowerDefenseItem towerDefenseItem = Singleton<HotfixDataController>.Instance.GetTowerDefenseItem(floorData.ItemID);
			if (towerDefenseItem != null)
			{
				gameplay.InitItems(towerDefenseItem.Id, towerDefenseItem.Amount, towerDefenseItem.Cd, towerDefenseItem.Script);
			}
			gameplay.InitExpInfo((float)floorData.UpgradeSpeed * (float)GameDataController.IntFloatPrecisionFP, list4.ToArray());
			gameplay.InitLevelInfo(floorData.Durability, floorData.MonsterNum);
			gameplay.InitRoles(list, list2);
			gameplay.InitMapData(mapData);
			gameplay.InitGameplay();
			MonoSingleton<WwiseAudioManager>.Instance.SetAudioListenerPos(Vector3.zero, Vector3.zero);
			if (gameplay != null)
			{
				if (!MonoSingleton<GameCameraStackManager>.Instance.mainCameraPhysicsRaycasterEnabled)
				{
					enableMainCameraPhysicsRaycaster = true;
					MonoSingleton<GameCameraStackManager>.Instance.EnableMainCameraPhysicsRaycaster();
				}
				gameplay.OnLevelStart();
			}
		}

		public override void UpdateLogic(FP logicDeltaTime)
		{
			base.UpdateLogic(logicDeltaTime);
			gameplay?.OnUpdateLogic();
		}

		public override bool HasTimelinePerformance()
		{
			int num;
			if (floorData != null)
			{
				num = ((!string.IsNullOrEmpty(floorData.IntroCutscene)) ? 1 : 0);
				if (num != 0)
				{
					timelineName = floorData.IntroCutscene;
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		public override void PlayTimelinePerformance(System.Action callback = null, bool needLimitPlayTimes = true)
		{
			base.PlayTimelinePerformance(delegate
			{
				callback?.Invoke();
			}, needLimitPlayTimes: false);
		}

		public override void LevelEnd()
		{
			base.LevelEnd();
			gameplay?.OnLevelEnd();
			gameplay = null;
			if (enableMainCameraPhysicsRaycaster)
			{
				MonoSingleton<GameCameraStackManager>.Instance.DisableMainCameraPhysicsRaycaster();
			}
			enableMainCameraPhysicsRaycaster = false;
			prefabData = null;
			mapData = null;
			if (null != configPrefab)
			{
				UnityEngine.Object.Destroy(configPrefab);
				configPrefab = null;
			}
			floorData = null;
			levelLoadParams = null;
			MonoSingleton<GameCameraStackManager>.Instance.autoVerticalToHorizontalFieldOfView = false;
			itemID = 0;
			selRoles?.Clear();
			selRoles = null;
		}
	}
	public class TrialLevelController : TaskTypeLevelController
	{
		protected TrialFloor _floorData;

		private List<PlayerSpawnPointGizmo> _playerSpawnPoints = new List<PlayerSpawnPointGizmo>();

		private PlayerSpawnPointGizmo _playerSpawnPointGizmo;

		private TrialLevelProcessBase _process;

		protected bool isStartTime;

		protected FP timing;

		protected FP levelTime;

		protected bool isSettlement;

		protected const string ZoomFreezeKey = "ZoomFreeze";

		protected const string ZoomDurationTimeKey = "ZoomInDurationTime";

		protected float _zoomFreeze;

		protected float _zoomDurationTime;

		public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
		{
			base.Load(param, callback);
			if (levelLoadParams != null)
			{
				_floorData = Singleton<HotfixDataController>.Instance.GetTrialFloor(CommonHelper.ParseStringParamToInt(levelLoadParams.id));
			}
			if (_floorData != null)
			{
				InitTask(_floorData.QuestFlow, triggerFirstTask: true);
				InitProcess((HotfixEnum.TrialSectType)_floorData.TrialSectType, _floorData.TrialChar);
				scenePath = "Assets/AssetBundles/" + _floorData.SceneName;
				MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string levelSceneName, int process)
				{
					LevelLoadProcessUpdate(levelSceneName, process);
					return true;
				});
				musicName = _floorData.BGM;
				leaveMusicEvent = _floorData.LeaveTriggerEvent;
			}
		}

		protected override void LevelLoadComplete(string sceneName)
		{
			ILRuntimeAPI.LoadConfigPrefab(scenePath, _floorData.ConfigPrefabName);
			base.LevelLoadComplete(sceneName);
		}

		public override void LevelStart(System.Action callback = null)
		{
			timing = 0;
			levelTime = 0;
			isStartTime = true;
			isSettlement = false;
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_LEVEL_ON_TELEPORTER_TRIGGERED", TaskSettlement);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
			_process?.OnLevelStart();
			_playerSpawnPointGizmo?.LevelStart();
			base.LevelStart(callback);
		}

		public override void UpdateLogic(FP logicDeltaTime)
		{
			base.UpdateLogic(logicDeltaTime);
			_process?.OnUpdateLogic(logicDeltaTime);
			if (isStartTime)
			{
				levelTime += logicDeltaTime;
				timing += logicDeltaTime;
				if (timing >= 1)
				{
					MonoSingleton<LuaManager>.Instance.FireEvent("Trial_Time", (int)(long)levelTime);
					timing -= (FP)1;
				}
			}
		}

		public override void InitSpawnPoints()
		{
			base.InitSpawnPoints();
			_playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
			if (_playerSpawnPoints == null || _playerSpawnPoints.Count == 0)
			{
				NovaLogger.Error("关卡中没有配置玩家出生点!");
				return;
			}
			if (null == _playerSpawnPointGizmo)
			{
				for (int i = 0; i < _playerSpawnPoints.Count; i++)
				{
					PlayerSpawnPointGizmo playerSpawnPointGizmo = _playerSpawnPoints[i];
					if (string.IsNullOrEmpty(playerSpawnPointGizmo.spawnPointID))
					{
						_playerSpawnPointGizmo = playerSpawnPointGizmo;
						break;
					}
				}
			}
			if (null == _playerSpawnPointGizmo)
			{
				NovaLogger.Error("试玩关没有找到合适的角色出生点!");
				return;
			}
			_playerSpawnPointGizmo.Initialize(0, 0);
			_playerSpawnPointGizmo.EnableSpawnLogic();
			_playerSpawnPointGizmo.ExecuteSpawnLogic();
			if (!base.isViewSceneMode)
			{
				ILRuntimeAPI.HandleSpawnGizmos();
			}
		}

		protected override void OnTaskTargetSuccess(int taskId, int taskTargetId, bool isLasTaskTarget = false)
		{
			base.OnTaskTargetSuccess(taskId, taskTargetId, isLasTaskTarget);
			_process?.OnTaskTargetSuccess(taskId, taskTargetId, isLasTaskTarget);
		}

		protected override void OnTaskFinish(int taskId, bool isLastTask = false)
		{
			base.OnTaskFinish(taskId, isLastTask);
			_process?.OnTaskFinish(taskId, isLastTask);
			if (!isLastTask)
			{
				TriggerNextTask();
			}
		}

		public override void LevelEnd()
		{
			base.LevelEnd();
			_process?.OnLevelEnd();
			_process = null;
			isStartTime = false;
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_LEVEL_ON_TELEPORTER_TRIGGERED", TaskSettlement);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_PLAYER_DIED", OnPlayerDied);
			_playerSpawnPoints.Clear();
			_playerSpawnPointGizmo?.LevelEnd();
			_playerSpawnPointGizmo = null;
		}

		protected void TaskSettlement(IEvent evt)
		{
			object data = ((GeneralEvent)evt).data;
			if (data != null)
			{
				AdventureLevelTeleporter.NextLevelData obj = (AdventureLevelTeleporter.NextLevelData)data;
				isStartTime = false;
				if (obj.levelSuccess)
				{
					LevelStateChangedCall(GameEnum.levelState.Success);
				}
			}
		}

		private void OnPlayerDied(IEvent ievent)
		{
			LevelStateChangedCall(GameEnum.levelState.Failed);
		}

		protected void LevelStateChangedCall(GameEnum.levelState levelState)
		{
			if (!isSettlement)
			{
				isStartTime = false;
				isSettlement = true;
				MonoSingleton<LuaManager>.Instance.FireEvent("TrialGameEnd", levelTime.AsFloat());
				CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomFreeze").Value, out _zoomFreeze);
				CommonHelper.TryParseStringParamToFloat(Singleton<GameDataController>.Instance.GetConfig("ZoomInDurationTime").Value, out _zoomDurationTime);
				ModuleController<AdventureModuleController>.Instance.FreezeFrame(_zoomFreeze, _zoomDurationTime, Action);
			}
			void Action()
			{
				LevelStateChanged(levelState);
			}
		}

		private void InitProcess(HotfixEnum.TrialSectType processType, int id)
		{
			switch (processType)
			{
			case HotfixEnum.TrialSectType.MainSect1:
				if (id == 144)
				{
					_process = new TrialLevelProcess_144_Main1();
				}
				if (id == 134)
				{
					_process = new TrialLevelProcess_134_Main1();
				}
				if (id == 119)
				{
					_process = new TrialLevelProcess_119_Main1();
				}
				if (id == 155)
				{
					_process = new TrialLevelProcess_155_Main1();
				}
				break;
			case HotfixEnum.TrialSectType.MainSect2:
				if (id == 144)
				{
					_process = new TrialLevelProcess_144_Main2();
				}
				if (id == 134)
				{
					_process = new TrialLevelProcess_134_Main2();
				}
				if (id == 119)
				{
					_process = new TrialLevelProcess_119_Main2();
				}
				if (id == 155)
				{
					_process = new TrialLevelProcess_155_Main2();
				}
				break;
			case HotfixEnum.TrialSectType.SupSect1:
				if (id == 144)
				{
					_process = new TrialLevelProcess_144_Sup1();
				}
				if (id == 134)
				{
					_process = new TrialLevelProcess_134_Sup1();
				}
				if (id == 119)
				{
					_process = new TrialLevelProcess_119_Sup1();
				}
				if (id == 155)
				{
					_process = new TrialLevelProcess_155_Sup1();
				}
				break;
			case HotfixEnum.TrialSectType.SupSect2:
				if (id == 144)
				{
					_process = new TrialLevelProcess_144_Sup1();
				}
				if (id == 134)
				{
					_process = new TrialLevelProcess_134_Sup1();
				}
				if (id == 119)
				{
					_process = new TrialLevelProcess_119_Sup2();
				}
				if (id == 155)
				{
					_process = new TrialLevelProcess_155_Sup2();
				}
				break;
			}
			if (_process == null)
			{
				NovaLogger.Error("未实例化试玩关卡流程");
			}
		}
	}
	public class TrialLevelProcessBase
	{
		protected int taskProcess;

		private readonly FP drop_Cd = 5;

		private TSVector2 drop_pos = new TSVector2(12, 0);

		private readonly int dropId = 119;

		private long drop_energyId;

		protected UIGameSystemSetup.TimeLinePlayType timeLinePlayType;

		private readonly List<CoroutineNode> corList = new List<CoroutineNode>();

		protected PlayerAdventureActor main_actor => SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor;

		public virtual void OnLevelStart()
		{
			timeLinePlayType = Singleton<UIGameSystemSetup>.Instance.PlayType;
			Singleton<UIGameSystemSetup>.Instance.PlayType = UIGameSystemSetup.TimeLinePlayType.everyTime;
			taskProcess = 1;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BATTLE_ROOM_WAVE_MONSTER_CLEARED", RoomWaveMonsterCleared);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("LEVEL_ON_TELEPORTER_TRIGGER_RUN", TriggerTeleportRun);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("DROP_EFFECT_FINISH", OnDropFinish);
		}

		public virtual void OnUpdateLogic(FP deltaTime)
		{
		}

		public virtual void OnTaskTargetSuccess(int taskId, int taskTargetId, bool isLasTaskTarget = false)
		{
		}

		public virtual void OnTaskFinish(int taskId, bool isLastTask = false)
		{
			taskProcess++;
		}

		protected virtual void OnRoomWaveMonsterCleared(AdventureLevelRoomWaveMonsterClearedEvent ievent)
		{
		}

		protected virtual void OnTriggerTeleportRun(AdventureTriggerTeleportRunEvent ievent)
		{
			AdventureModuleHelper.SetSemiAutoBattleMode(enable: false);
		}

		public virtual void OnLevelEnd()
		{
			Singleton<UIGameSystemSetup>.Instance.PlayType = timeLinePlayType;
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("BATTLE_ROOM_WAVE_MONSTER_CLEARED", RoomWaveMonsterCleared);
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("LEVEL_ON_TELEPORTER_TRIGGER_RUN", TriggerTeleportRun);
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("DROP_EFFECT_FINISH", OnDropFinish);
			List<CoroutineNode> list = corList;
			if (list != null && list.Count > 0)
			{
				for (int num = corList.Count - 1; num > -1; num--)
				{
					StopLogicCoroutine(corList[num]);
				}
				corList.Clear();
			}
		}

		protected void SendTaskProcessToServer()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("Trial_QuestComplete");
		}

		protected void OpenTeleporters(string teleporterName)
		{
			List<AdventureLevelTeleporter> teleporters = ModuleController<AdventureModuleController>.Instance.GetTeleporters(teleporterName, -1, -1);
			for (int i = 0; i < teleporters.Count; i++)
			{
				teleporters[i].Active(active: true);
			}
		}

		protected void RoomWaveMonsterCleared(IEvent ievent)
		{
			if (ievent != null)
			{
				AdventureLevelRoomWaveMonsterClearedEvent adventureLevelRoomWaveMonsterClearedEvent = (AdventureLevelRoomWaveMonsterClearedEvent)ievent;
				if (adventureLevelRoomWaveMonsterClearedEvent != null)
				{
					OnRoomWaveMonsterCleared(adventureLevelRoomWaveMonsterClearedEvent);
				}
			}
		}

		protected void TriggerTeleportRun(IEvent ievent)
		{
			if (ievent != null)
			{
				AdventureTriggerTeleportRunEvent adventureTriggerTeleportRunEvent = (AdventureTriggerTeleportRunEvent)ievent;
				if (adventureTriggerTeleportRunEvent != null)
				{
					OnTriggerTeleportRun(adventureTriggerTeleportRunEvent);
				}
			}
		}

		protected void DropItemEnegy()
		{
			if (dropId > 0)
			{
				drop_energyId = SceneSingleton<DropsManager>.Instance.PlayDropsByDropId(main_actor, dropId, drop_pos);
			}
		}

		private void OnDropFinish(IEvent evt)
		{
			AdventureDropFinishEvent obj = evt as AdventureDropFinishEvent;
			long entityID = obj.entityID;
			if (obj.isPickUp && entityID == drop_energyId)
			{
				StartLogicCoroutine(DropEnumerator());
			}
		}

		private IEnumerator DropEnumerator()
		{
			FP waitTime = drop_Cd;
			while (waitTime > 0)
			{
				waitTime -= LockStepManager.deltaTime;
				yield return null;
			}
			DropItemEnegy();
		}

		protected void ActiveMonsterSpawnWave(string waveName)
		{
			List<BaseSpawnPointGizmo> waves = ModuleController<AdventureModuleController>.Instance.GetWaves(waveName);
			if (waves == null || waves.Count <= 0)
			{
				return;
			}
			foreach (BaseSpawnPointGizmo item in waves)
			{
				if (item.isSpawnEnabled)
				{
					item.ReEnableSpawnLogic();
				}
				else
				{
					item.EnableSpawnLogic();
				}
			}
		}

		protected void KillMonsterSpawnWave(string waveName)
		{
			List<BaseSpawnPointGizmo> waves = ModuleController<AdventureModuleController>.Instance.GetWaves(waveName);
			if (waves == null || waves.Count <= 0)
			{
				return;
			}
			foreach (BaseSpawnPointGizmo item in waves)
			{
				item.KillAllSummoners();
			}
		}

		protected int GetMonsterCountSpawnWave(string waveName)
		{
			List<BaseSpawnPointGizmo> waves = ModuleController<AdventureModuleController>.Instance.GetWaves(waveName);
			int num = 0;
			if (waves != null && waves.Count > 0)
			{
				foreach (BaseSpawnPointGizmo item in waves)
				{
					num += item.RemindMonsterCount();
				}
			}
			return num;
		}

		protected CoroutineNode StartLogicCoroutine(IEnumerator routine, bool runImmediately = false)
		{
			CoroutineNode coroutineNode = SceneSingleton<AdventurePlayerController>.Instance.StartLogicCoroutine(routine, runImmediately);
			corList.Add(coroutineNode);
			return coroutineNode;
		}

		protected void StopLogicCoroutine(CoroutineNode coroutine)
		{
			if (coroutine != null)
			{
				if (corList.Contains(coroutine))
				{
					corList.Remove(coroutine);
				}
				SceneSingleton<AdventurePlayerController>.Instance.StopLogicCoroutine(coroutine);
			}
		}

		protected IEnumerator WaitTime(FP time)
		{
			FP waitTime = time;
			while (waitTime > 0)
			{
				waitTime -= LockStepManager.deltaTime;
				yield return null;
			}
		}
	}
