	public class TutorialLevelController : TaskTypeLevelController
	{
		public const string TutorialSettlementDelayTimeKey = "TutorialSettlementDelayTime";

		private TutorialLevelFloor _floorData;

		private List<PlayerSpawnPointGizmo> _playerSpawnPoints = new List<PlayerSpawnPointGizmo>();

		private PlayerSpawnPointGizmo _playerSpawnPointGizmo;

		private TutorialLevelProcessBase _process;

		private bool _isLevelFinish;

		private FP _delaySettlementTime;

		public override void Load(AdventureModuleLevelLoadParams param = null, System.Action callback = null)
		{
			base.Load(param, callback);
			if (levelLoadParams != null)
			{
				_floorData = Singleton<HotfixDataController>.Instance.GetTutorialLevelFloor(CommonHelper.ParseStringParamToInt(levelLoadParams.id));
			}
			if (_floorData != null)
			{
				InitTask(_floorData.QuestFlow);
				InitProcess((HotfixEnum.TutorialLevelProcessType)_floorData.ScriptType);
				scenePath = "Assets/AssetBundles/" + _floorData.SceneName;
				MonoSingleton<SceneLoaderController>.Instance.LoadSceneAsync(scenePath, LoadSceneMode.Additive, LocalPhysicsMode.None, delegate(string levelSceneName, int process)
				{
					LevelLoadProcessUpdate(levelSceneName, process);
					return true;
				});
				musicName = _floorData.BGM;
				leaveMusicEvent = _floorData.LeaveTriggerEvent;
			}
		}

		private void InitProcess(HotfixEnum.TutorialLevelProcessType processType)
		{
			switch (processType)
			{
			case HotfixEnum.TutorialLevelProcessType.Test:
				_process = new TutorialLevelProcess_Test();
				break;
			case HotfixEnum.TutorialLevelProcessType.BasicOperation:
				_process = new TutorialLevelProcess_BasicOperation();
				break;
			case HotfixEnum.TutorialLevelProcessType.MoveOperation:
				_process = new TutorialLevelProcess_MoveOperation();
				break;
			case HotfixEnum.TutorialLevelProcessType.SupportOperation:
				_process = new TutorialLevelProcess_SupportOperation();
				break;
			case HotfixEnum.TutorialLevelProcessType.MarkMechanism:
				_process = new TutorialLevelProcess_MarkMechanism();
				break;
			case HotfixEnum.TutorialLevelProcessType.ElementMechanism:
				_process = new TutorialLevelProcess_ElementMechanism();
				break;
			case HotfixEnum.TutorialLevelProcessType.StarTowerCardMechanism:
				_process = new TutorialLevelProcess_StarTowerCardMechanism();
				break;
			case HotfixEnum.TutorialLevelProcessType.StarTowerNoteMechanism:
				_process = new TutorialLevelProcess_StarTowerNoteMechanism();
				break;
			case HotfixEnum.TutorialLevelProcessType.MonsterToughnessMechanism:
				_process = new TutorialLevelProcess_MonsterToughnessMechanism();
				break;
			}
			if (_process != null)
			{
				_process.Init(base.TriggerNextTask);
			}
			else
			{
				NovaLogger.Error("未实例化教学关卡流程");
			}
		}

		protected override void LevelLoadComplete(string sceneName)
		{
			ILRuntimeAPI.LoadConfigPrefab(scenePath, _floorData.ConfigPrefabName);
			base.LevelLoadComplete(sceneName);
		}

		public override void LevelStart(System.Action callback = null)
		{
			_process?.OnLevelStart();
			_playerSpawnPointGizmo?.LevelStart();
			_delaySettlementTime = 0;
			Nova.Client.Config config = Singleton<GameDataController>.Instance.GetConfig("TutorialSettlementDelayTime");
			if (config != null)
			{
				_delaySettlementTime = FP.FromFloat(CommonHelper.ParseStringParamToFloat(config.Value));
			}
			_isLevelFinish = false;
			base.LevelStart(callback);
		}

		public override void UpdateLogic(FP logicDeltaTime)
		{
			base.UpdateLogic(logicDeltaTime);
			_process?.OnUpdateLogic(logicDeltaTime);
			if (_isLevelFinish)
			{
				if (_delaySettlementTime >= 0)
				{
					_delaySettlementTime -= logicDeltaTime;
				}
				else
				{
					Settlement();
				}
			}
		}

		public override void InitSpawnPoints()
		{
			base.InitSpawnPoints();
			_playerSpawnPoints = UnityEngine.Object.FindObjectsOfType<PlayerSpawnPointGizmo>().ToList();
			if (_playerSpawnPoints == null || _playerSpawnPoints.Count == 0)
			{
				Debug.LogError("关卡中没有配置玩家出生点!");
				return;
			}
			if (null == _playerSpawnPointGizmo)
			{
				for (int i = 0; i < _playerSpawnPoints.Count; i++)
				{
					PlayerSpawnPointGizmo playerSpawnPointGizmo = _playerSpawnPoints[i];
					if (string.IsNullOrEmpty(playerSpawnPointGizmo.spawnPointID))
					{
						_playerSpawnPointGizmo = playerSpawnPointGizmo;
						break;
					}
				}
			}
			if (null == _playerSpawnPointGizmo)
			{
				Debug.LogError("教学关没有找到合适的角色出生点!");
				return;
			}
			_playerSpawnPointGizmo.Initialize(0, 0);
			_playerSpawnPointGizmo.EnableSpawnLogic();
			_playerSpawnPointGizmo.ExecuteSpawnLogic();
			if (!base.isViewSceneMode)
			{
				ILRuntimeAPI.HandleSpawnGizmos();
			}
		}

		protected override void OnTaskTargetSuccess(int taskId, int taskTargetId, bool isLasTaskTarget = false)
		{
			base.OnTaskTargetSuccess(taskId, taskTargetId, isLasTaskTarget);
			_process?.OnTaskTargetSuccess(taskId, taskTargetId, isLasTaskTarget);
		}

		protected override void OnTaskFinish(int taskId, bool isLastTask = false)
		{
			base.OnTaskFinish(taskId, isLastTask);
			_process?.OnTaskFinish(taskId, isLastTask);
			if (isLastTask)
			{
				_isLevelFinish = true;
			}
		}

		protected override void OnTriggerNextTask(int taskId)
		{
			base.OnTriggerNextTask(taskId);
			_process?.OnTriggerNextTask(taskId);
		}

		private void Settlement()
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("TutorialLevelSuccess");
		}

		public override void LevelEnd()
		{
			base.LevelEnd();
			_process?.OnLevelEnd();
			_process = null;
			_playerSpawnPoints.Clear();
			_playerSpawnPointGizmo?.LevelEnd();
			_playerSpawnPointGizmo = null;
		}
	}
	public class TutorialLevelProcessBase
	{
		protected System.Action _triggerNextTask;

		protected PlayerAdventureActor _actor;

		protected int _subProcessIndex;

		private List<CoroutineNode> _waitTimeCorList;

		private bool _triggerNextTaskWithTutorialCard;

		private int _currentTutorialCardId;

		private const int buffId_ImmunityDead = 911210100;

		public void Init(System.Action triggerNextTask)
		{
			_triggerNextTask = triggerNextTask;
		}

		public virtual void OnLevelStart()
		{
			_actor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
			_actor?.buffComponent.AddBuff(911210100, _actor);
			_subProcessIndex = 0;
			_triggerNextTaskWithTutorialCard = false;
			_currentTutorialCardId = 0;
			Singleton<EventDispatchManager>.Instance.AddEventListener("Tutorial_CloseCard", OnTutorialCardClose);
			Singleton<EventDispatchManager>.Instance.AddEventListener("Tutorial_GuideEnd", OnGuideEnd);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BATTLE_ROOM_WAVE_MONSTER_CLEARED", RoomWaveMonsterCleared);
		}

		protected void TriggerNextTask(int tutorialCardId = 0, bool isLevelStart = false)
		{
			if (tutorialCardId > 0)
			{
				_triggerNextTaskWithTutorialCard = true;
				OpenTutorialCard(tutorialCardId, isLevelStart);
			}
			else
			{
				_triggerNextTask?.Invoke();
			}
		}

		protected void StartWaitTime(FP time, System.Action onFinish = null)
		{
			if (_waitTimeCorList == null)
			{
				_waitTimeCorList = new List<CoroutineNode>(3);
			}
			_waitTimeCorList.Add(StartLogicCoroutine(WaitTime(time, onFinish)));
		}

		protected void StopWaitTime(CoroutineNode waitTimeCor)
		{
			if (waitTimeCor != null)
			{
				List<CoroutineNode> waitTimeCorList = _waitTimeCorList;
				if (waitTimeCorList != null && waitTimeCorList.Count > 0 && _waitTimeCorList.Remove(waitTimeCor))
				{
					StopLogicCoroutine(waitTimeCor);
				}
			}
		}

		protected void EnableButtonControl(string buttonName, bool isEnable)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("EnableBtnControl", buttonName, isEnable);
		}

		protected void AddRoomBuff(int buffId)
		{
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.AddBuff(buffId, actorL);
			}
		}

		protected void UpdateOperationTips(string tipsKey)
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("UpdateOperationTips", tipsKey);
		}

		protected void OpenTutorialCard(int tutorialCardId, bool isLevelStart = false)
		{
			_currentTutorialCardId = tutorialCardId;
			MonoSingleton<LuaManager>.Instance?.FireEvent("OpenTutorialCard", tutorialCardId, isLevelStart);
		}

		protected void ShowTutorialButtonHint(string buttonName, bool isShow)
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("ShowTutorialButtonHint", buttonName, isShow);
		}

		protected void TriggerGuide(int guideId)
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("Trigger_Guide_Index", guideId);
		}

		protected bool TriggerPerkSelect(List<int> perkIdList)
		{
			if (perkIdList != null && perkIdList.Count > 0)
			{
				MonoSingleton<LuaManager>.Instance.FireEvent("TutorialPotentialSelect", perkIdList);
				return true;
			}
			return false;
		}

		public virtual void OnUpdateLogic(FP deltaTime)
		{
		}

		private void OnTutorialCardClose(IEvent _)
		{
			if (_currentTutorialCardId > 0)
			{
				if (_triggerNextTaskWithTutorialCard)
				{
					_triggerNextTask?.Invoke();
				}
				OnTutorialCardClose(_currentTutorialCardId);
				_currentTutorialCardId = 0;
			}
		}

		protected virtual void OnTutorialCardClose(int tutorialCardId)
		{
		}

		private void OnGuideEnd(IEvent evt)
		{
			if (evt is GeneralEvent generalEvent)
			{
				CommonHelper.TryParseStringParamToInt((generalEvent.data as LuaTable)[1].ToString(), out var intValue);
				if (intValue > 0)
				{
					OnGuideEnd(intValue);
				}
			}
		}

		protected virtual void OnGuideEnd(int guideId)
		{
		}

		private void RoomWaveMonsterCleared(IEvent evt)
		{
			if (evt is AdventureLevelRoomWaveMonsterClearedEvent waveClearEvent)
			{
				OnRoomWaveMonsterCleared(waveClearEvent);
			}
		}

		protected virtual void OnRoomWaveMonsterCleared(AdventureLevelRoomWaveMonsterClearedEvent waveClearEvent)
		{
		}

		public virtual void OnTriggerNextTask(int taskId)
		{
			_subProcessIndex++;
			_triggerNextTaskWithTutorialCard = false;
		}

		public virtual void OnTaskTargetSuccess(int taskId, int taskTargetId, bool isLasTaskTarget = false)
		{
		}

		public virtual void OnTaskFinish(int taskId, bool isLastTask = false)
		{
		}

		public virtual void OnLevelEnd()
		{
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("BATTLE_ROOM_WAVE_MONSTER_CLEARED", RoomWaveMonsterCleared);
			Singleton<EventDispatchManager>.Instance?.RemoveEventListener("Tutorial_CloseCard", OnTutorialCardClose);
			Singleton<EventDispatchManager>.Instance?.RemoveEventListener("Tutorial_GuideEnd", OnGuideEnd);
			List<CoroutineNode> waitTimeCorList = _waitTimeCorList;
			if (waitTimeCorList != null && waitTimeCorList.Count > 0)
			{
				foreach (CoroutineNode waitTimeCor in _waitTimeCorList)
				{
					StopLogicCoroutine(waitTimeCor);
				}
				_waitTimeCorList.Clear();
			}
			_triggerNextTask = null;
			_actor = null;
		}

		protected void ActiveMonsterSpawnWave(string waveName)
		{
			List<BaseSpawnPointGizmo> waves = ModuleController<AdventureModuleController>.Instance.GetWaves(waveName);
			if (waves.Count <= 0)
			{
				return;
			}
			foreach (BaseSpawnPointGizmo item in waves)
			{
				if (item.isSpawnEnabled)
				{
					item.ReEnableSpawnLogic();
				}
				else
				{
					item.EnableSpawnLogic();
				}
			}
		}

		protected CoroutineNode StartLogicCoroutine(IEnumerator routine, bool runImmediately = false)
		{
			return SceneSingleton<AdventurePlayerController>.Instance.StartLogicCoroutine(routine, runImmediately);
		}

		protected void StopLogicCoroutine(CoroutineNode coroutine)
		{
			SceneSingleton<AdventurePlayerController>.Instance.StopLogicCoroutine(coroutine);
		}

		protected IEnumerator WaitTime(FP time, System.Action onFinish = null)
		{
			FP waitTime = time;
			while (waitTime > 0)
			{
				waitTime -= LockStepManager.deltaTime;
				yield return null;
			}
			onFinish?.Invoke();
		}
	}
	public class TutorialLevelProcess_BasicOperation : TutorialLevelProcessBase
	{
		private readonly int buffId_Room = 911210110;

		private readonly Dictionary<int, string> operationTipsDic = new Dictionary<int, string>
		{
			[1210101] = "Tutorial_Attack",
			[1210102] = "Tutorial_Skill",
			[1210103] = "Tutorial_Charge",
			[1210104] = "Tutorial_UltraSkill",
			[1210105] = "Tutorial_GuideEnd"
		};

		private readonly Dictionary<int, FP> waitTimeDic = new Dictionary<int, FP>
		{
			[1210101] = 2.5,
			[1210102] = 2.5,
			[1210103] = 0,
			[1210104] = 0
		};

		private readonly int tutorialCardId_NormalAttack = 300105;

		private readonly string monsterSpawnWave_NormalAttack_1 = "Wave_1_1";

		private readonly string monsterSpawnWave_NormalAttack_2 = "Wave_1_2";

		private readonly int tutorialCardId_Skill = 300106;

		private readonly string monsterSpawnWave_Skill = "Wave_2_1";

		private readonly int tutorialCardId_Charge = 300107;

		private readonly int buffId_Charge = 911210120;

		private readonly string monsterSpawnWave_Charge = "Wave_3_1";

		private readonly int buffId_UltraSkill = 911210130;

		public override void OnLevelStart()
		{
			base.OnLevelStart();
			EnableButtonControl("ActorSwitch1", isEnable: false);
			EnableButtonControl("ActorSwitch2", isEnable: false);
			EnableButtonControl("SwitchWithUltra1", isEnable: false);
			EnableButtonControl("SwitchWithUltra2", isEnable: false);
			AddRoomBuff(buffId_Room);
			StartWaitTime(0.5, delegate
			{
				TriggerNextTask(tutorialCardId_NormalAttack, isLevelStart: true);
			});
		}

		public override void OnTriggerNextTask(int taskId)
		{
			base.OnTriggerNextTask(taskId);
			if (operationTipsDic.TryGetValue(taskId, out var value))
			{
				UpdateOperationTips(value);
			}
			switch (_subProcessIndex)
			{
			case 1:
				ActiveMonsterSpawnWave(monsterSpawnWave_NormalAttack_1);
				break;
			case 2:
				ActiveMonsterSpawnWave(monsterSpawnWave_Skill);
				ShowTutorialButtonHint("Fire2", isShow: true);
				break;
			case 3:
				_actor?.buffComponent.AddBuff(buffId_Charge, _actor);
				ActiveMonsterSpawnWave(monsterSpawnWave_Charge);
				break;
			case 4:
				_actor?.buffComponent.AddBuff(buffId_UltraSkill, _actor);
				ShowTutorialButtonHint("Fire4", isShow: true);
				break;
			case 5:
				StartWaitTime(2, delegate
				{
					AdventureInteractiveIDTrigger adventureInteractiveIDTrigger = AdventureInteractiveIDTrigger.Generate();
					adventureInteractiveIDTrigger.interactiveID = "TutorialEnd";
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureInteractiveIDTrigger);
				});
				break;
			}
		}

		protected override void OnRoomWaveMonsterCleared(AdventureLevelRoomWaveMonsterClearedEvent waveClearEvent)
		{
			base.OnRoomWaveMonsterCleared(waveClearEvent);
			if (_subProcessIndex == 1 && string.Equals(waveClearEvent.wave, monsterSpawnWave_NormalAttack_1))
			{
				ActiveMonsterSpawnWave(monsterSpawnWave_NormalAttack_2);
			}
		}

		public override void OnTaskFinish(int taskId, bool isLastTask = false)
		{
			base.OnTaskFinish(taskId, isLastTask);
			int tutorialCardId = 0;
			switch (_subProcessIndex)
			{
			case 1:
				tutorialCardId = tutorialCardId_Skill;
				break;
			case 2:
				ShowTutorialButtonHint("Fire2", isShow: false);
				tutorialCardId = tutorialCardId_Charge;
				break;
			case 4:
				ShowTutorialButtonHint("Fire4", isShow: false);
				break;
			}
			if (!isLastTask && waitTimeDic.TryGetValue(taskId, out var value))
			{
				StartWaitTime(value, delegate
				{
					TriggerNextTask(tutorialCardId);
				});
			}
			else
			{
				TriggerNextTask(tutorialCardId);
			}
		}

		public override void OnLevelEnd()
		{
			base.OnLevelEnd();
		}
	}
