		private readonly FP angle = 30;

		private readonly int proB_damageId = 986493;

		private readonly int proC_damageId = 986494;

		public override void OnEnable()
		{
			base.OnEnable();
		}

		public override void OnDisable()
		{
			base.OnDisable();
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd) && OnExcute())
			{
				TriggerTheme();
			}
		}

		private bool OnExcute()
		{
			LogicEntity logicEntity = CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius);
			if (logicEntity == null)
			{
				return false;
			}
			string fxAlias = normalPath_Pierce;
			int hitId = normal_damageId;
			if (base.CanExcuteA)
			{
				fxAlias = proaPath_Pierce;
				hitId = proA_damageId;
			}
			if (base.CanExcuteB)
			{
				hitId = proB_damageId;
			}
			if (base.CanExcuteC)
			{
				hitId = proC_damageId;
			}
			TSVector2 normalized = (logicEntity.tsTransform.Position - base._actor.tsTransform.Position).normalized;
			FP rotation = normalized.GetAngle();
			PlayAreaEffect(fxAlias, base._actor.tsTransform.Position, hitId, rotation);
			if (base.CanExcuteB)
			{
				rotation = TSVector2.Rotate(normalized, angle).GetAngle();
				PlayAreaEffect(fxAlias, base._actor.tsTransform.Position, hitId, rotation);
				rotation = TSVector2.Rotate(normalized, -angle).GetAngle();
				PlayAreaEffect(fxAlias, base._actor.tsTransform.Position, hitId, rotation);
			}
			return true;
