	public class FateCard_EarthSpike : BaseFateCardTheme
	{
		private readonly FP cd = 2;

		private readonly string areaEeffct_Earth = "FateCard_EarthSpike";

		private readonly int normal_damageId = 986401;

		private readonly FP radius = 2.2;

		private readonly FP bron_delay = 0.35;

		private readonly int proA_damageId = 986402;

		private readonly string prob_areaEeffct_Earth = "FateCard_EarthSpike_B";

		private readonly string areaEeffct_Earth_Boom = "FateCard_EarthSpike_B_1";

		private readonly FP bron_booom_delay = 0.5;

		private readonly int proB_damageId = 986404;

		private readonly int proC_damageId = 986405;

		private readonly int proC_damageId_1 = 986406;

		private List<TSVector2> sVector2s = new List<TSVector2>(4);

		private readonly List<CoroutineNode> corList = new List<CoroutineNode>();

		public override void OnEnable()
		{
			base.OnEnable();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			foreach (CoroutineNode cor in corList)
			{
				StopLogicCoroutine(cor);
			}
			corList.Clear();
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd) && ShowEarthSpike())
			{
				TriggerTheme();
			}
		}

		private void GetAreaPos(FP _distance, TSVector2 _pos)
		{
			sVector2s.Clear();
			int num = TSRandom.Range(0, 90);
			for (int i = 0; i <= 3; i++)
			{
				int num2 = 90 * i + num;
				TSVector2 item = _pos + TSVector2.Rotate(TSVector2.one, num2).normalized * _distance;
				sVector2s.Add(item);
			}
		}

		private bool ShowEarthSpike()
		{
			LogicEntity attackTarget = base._actor.attackTarget;
			attackTarget = attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, 10);
			if (attackTarget == null)
			{
				return false;
			}
			PlayAreaEffect(base.CanExcuteB ? prob_areaEeffct_Earth : areaEeffct_Earth, attackTarget.tsTransform.Position, base.CanExcuteC ? proC_damageId : normal_damageId);
			if (base.CanExcuteA)
			{
				CoroutineNode item = StartLogicCoroutine(Show_ProA(attackTarget.tsTransform.Position));
				corList.Add(item);
			}
			if (base.CanExcuteB)
			{
				CoroutineNode item2 = StartLogicCoroutine(Show_ProB(attackTarget.tsTransform.Position));
				corList.Add(item2);
			}
			return true;
		}

		private IEnumerator Show_ProA(TSVector2 pos)
		{
			yield return StartLogicCoroutine(base._actor.WaitForSeconds(bron_delay));
			GetAreaPos(radius, pos);
			for (int i = 0; i < sVector2s.Count; i++)
			{
				PlayAreaEffect(base.CanExcuteB ? prob_areaEeffct_Earth : areaEeffct_Earth, sVector2s[i], proA_damageId);
			}
			yield return StartLogicCoroutine(base._actor.WaitForSeconds(bron_delay));
			GetAreaPos(radius * 2, pos);
			for (int j = 0; j < sVector2s.Count; j++)
			{
				PlayAreaEffect(base.CanExcuteB ? prob_areaEeffct_Earth : areaEeffct_Earth, sVector2s[j], proA_damageId);
			}
		}

		private IEnumerator Show_ProB(TSVector2 pos)
		{
			int hitId = proB_damageId;
			if (base.CanExcuteC)
			{
				hitId = proC_damageId_1;
			}
			yield return StartLogicCoroutine(base._actor.WaitForSeconds(bron_booom_delay));
			PlayAreaEffect(areaEeffct_Earth_Boom, pos, hitId);
			if (base.CanExcuteA)
			{
				yield return StartLogicCoroutine(base._actor.WaitForSeconds(bron_delay));
				GetAreaPos(radius, pos);
				for (int i = 0; i < sVector2s.Count; i++)
				{
					PlayAreaEffect(areaEeffct_Earth_Boom, sVector2s[i], hitId);
				}
				yield return StartLogicCoroutine(base._actor.WaitForSeconds(bron_delay));
				GetAreaPos(radius * 2, pos);
				for (int j = 0; j < sVector2s.Count; j++)
				{
					PlayAreaEffect(areaEeffct_Earth_Boom, sVector2s[j], hitId);
				}
			}
		}
	}
	public class FateCard_FallingStone : BaseFateCardTheme
	{
		private const string bulletPath = "FateCard_FallingStone";

		private const int hitDamageId = 986161;

		private readonly FP cd = 3;

		private const string triggerFxPath = "fire_trigger_s";

		private const string bulletTag = "FallingStone";

		private readonly FP targetSearchRange = 10;

		private const int hitDamageId_1_enhance = 986162;

		private readonly int replaceCount = 2;

		private readonly string bulletPath_intensive1 = "FateCard_FallingStone_16";

		private const string bulletPath_instensive2_timeBoom = "FateCard_FallingStone_17";

		private const string shootCountKey = "fallingStoneShootCount";

		public override void OnEnable()
		{
			base.OnEnable();
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				Shoot(986161, 986162);
				TriggerTheme();
			}
		}

		private void Shoot(int hitDamageId, int hitDamageIdEnhance)
		{
			LogicEntity shootTarget = GetShootTarget();
			if (!(shootTarget == null))
			{
				AddKey("fallingStoneShootCount");
				CommonUtils.PlayOneOffFx(base._actor, "fire_trigger_s");
				(bool, string) tuple = GetBulletPath();
				bool item = tuple.Item1;
				string item2 = tuple.Item2;
				AdventureActor actor = base._actor;
				TSVector2 position = shootTarget.tsTransform.Position;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(item2, actor, default(FP), default(TSVector2), default(FP), position, null, AimType.Position);
				adventureBulletBase.hitBox.hitDamageId = ((!item) ? hitDamageId : hitDamageIdEnhance);
				adventureBulletBase.useOwnerActorInfo = true;
			}
		}

		protected override void OnBulletFinish(AdventureBulletFinishEvent _evt)
		{
			if (_evt != null && _evt.tag == "FallingStone" && base.CanExcuteB)
			{
				ILRuntimeAPI.Shoot("FateCard_FallingStone_17", base._actor, default(FP), _evt.bulletPosition, 1, _evt.bulletPosition, null, AimType.Position);
			}
		}

		private (bool, string) GetBulletPath()
		{
			bool item = false;
			string item2 = "FateCard_FallingStone";
			if (base.CanExcuteA && GetKeyCount("fallingStoneShootCount") == replaceCount + 1)
			{
				ClearKey("fallingStoneShootCount");
				item2 = bulletPath_intensive1;
				item = true;
			}
			return (item, item2);
		}

		private LogicEntity GetShootTarget()
		{
			if (base._actor.attackTarget != null)
			{
				return base._actor.attackTarget;
			}
			LogicEntity target = null;
			ILRuntimeAPI.SearchByRange(base._actor, targetSearchRange, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					base._actor.SearchEntitySortByDistance(result);
					target = result[0];
				}
			}, isConfront: true);
			return target;
		}
	}
	public class FateCard_FireRing : BaseFateCardTheme
	{
		private const string triggerFxPath = "fire_trigger_s";

		private readonly FP duration = 1;

		private const int hitDamageId = 986101;

		private readonly FP cd = 1.5;

		private const string fxPath = "fire_firering_6m_1s_01";

		private readonly int fireRingDamageTag = CommonHelper.StringToHash("fireRing");

		private readonly FP initInnerRadius = 0.3;

		private readonly FP radius = 1;

		private readonly FP diffuseSpeed = 0.48;

		private readonly FP diffuseInterval = 0.08;

		private readonly FP attackInterval = 0.2;

		private readonly int hitId_2p = 986102;

		private const string fxPath_bom6 = "fire_firering_6m_q2";

		private const string fxPath_ProB = "fire_firering_6m_1s_13";

		private readonly int attriId_13 = 440;

		private string _fireRingPrefabName;

		private GameObject _prefab_FireRing;

		private List<long> _perk2pTriggers;

		private Dictionary<string, GameObject> _fxPrefabDic;

		public override void OnEnable()
		{
			base.OnEnable();
			_fireRingPrefabName = $"FireRing_{base._actor.dataID}";
			_perk2pTriggers = new List<long>(10);
			_fxPrefabDic = new Dictionary<string, GameObject>(4);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("AREA_EFFECT_DIFFUSE", OnDiffuseEvent);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("AREA_EFFECT_DIFFUSE", OnDiffuseEvent);
			_perk2pTriggers.Clear();
			_perk2pTriggers = null;
			_fxPrefabDic.Clear();
			_fxPrefabDic = null;
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				PlayFireRing(986101);
				TriggerTheme();
			}
		}

		private void PlayFireRing(int hitDamageId)
		{
			CommonUtils.PlayOneOffFx(base._actor, "fire_trigger_s");
			GameObject fireRingPrefab = GetFireRingPrefab(iFollow: false);
			ILRuntimeAPI.PlayAreaEffect(base._actor, fireRingPrefab, base._actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
			{
				entity.ActiveSelf = true;
				if (base.CanExcuteA)
				{
					_perk2pTriggers.Add(entity.Id);
				}
				FP fP = duration;
				string text = "fire_firering_6m_1s_01";
				if (base.CanExcuteB)
				{
					fP = duration * 2;
					text = "fire_firering_6m_1s_13";
				}
				entity.duration = fP;
				if (_fxPrefabDic.TryGetValue(text, out var value))
				{
					entity.fx = value;
				}
				else
				{
					GameObject fxByAlias = ModuleController<AdventureModuleController>.Instance.GetFxByAlias(base._actor, text, forceUseCommonConfig: true);
					_fxPrefabDic.Add(text, fxByAlias);
					entity.fx = fxByAlias;
				}
				AreaEffect_AttackComponent logicComponent = entity.GetLogicComponent<AreaEffect_AttackComponent>();
				if (logicComponent != null)
				{
					logicComponent.hitDamageId = hitDamageId;
					if (base.CanExcuteB)
					{
						logicComponent.delayClearHittedRecord = true;
						logicComponent.clearHittedRecordDelayTime = fP * 0.5f;
					}
					else
					{
						logicComponent.delayClearHittedRecord = false;
					}
				}
				AreaEffect_DiffuseComponent logicComponent2 = entity.GetLogicComponent<AreaEffect_DiffuseComponent>();
				if (logicComponent2 != null)
				{
					logicComponent2.maxDiffuseTime = fP;
					if (base.CanExcuteB)
					{
						logicComponent2.changeSpeed = true;
						logicComponent2.delay_Change = fP * 0.5f;
						logicComponent2.speed_Change = -diffuseSpeed;
					}
					else
					{
						logicComponent2.changeSpeed = false;
					}
				}
			});
		}

		private void OnDiffuseEvent(IEvent evt)
		{
			AdventureAreaEffectDiffuseEvent adventureAreaEffectDiffuseEvent = evt as AdventureAreaEffectDiffuseEvent;
			if (adventureAreaEffectDiffuseEvent.iDiffuseMax && _perk2pTriggers.Contains(adventureAreaEffectDiffuseEvent.entityID))
			{
				string fxAlias = "fire_firering_6m_q2";
				PlayFX playFX = new PlayFX();
				TSVector2 position = new TSVector2(adventureAreaEffectDiffuseEvent.pos.x, adventureAreaEffectDiffuseEvent.pos.z);
				playFX.Play(base._actor, null, fxAlias, adventureAreaEffectDiffuseEvent.pos.y, position, base._actor.tsTransform.Forward);
				playFX.Clear();
				CommomAreaHitConfig commomAreaHitConfig = new CommomAreaHitConfig();
				commomAreaHitConfig.position = position;
				commomAreaHitConfig.hitDamageId = hitId_2p;
				ILRuntimeAPI.CircleAreaHit(base._actor, commomAreaHitConfig, adventureAreaEffectDiffuseEvent.hitBoxRadius, 0);
				_perk2pTriggers.Remove(adventureAreaEffectDiffuseEvent.entityID);
			}
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent _evt)
		{
			base.OnBeforeHit(_evt);
			if (_evt.from as AdventureActor != null && CommonUtils.CheckHitByTag(_evt.hitDamageTag, fireRingDamageTag))
			{
				_ = _evt.to;
				if (base.CanExcuteB)
				{
					AdventureActor.AddFromAttr(attriId_13, base._actor);
				}
			}
		}

		private GameObject GetFireRingPrefab(bool iFollow)
		{
			if (_prefab_FireRing == null)
			{
				SpawnPool spawnPool = PoolManager.Pools["Effect"];
				if (spawnPool != null)
				{
					_prefab_FireRing = spawnPool.GetPrefabGo(_fireRingPrefabName);
				}
				if (_prefab_FireRing == null)
				{
					_prefab_FireRing = new GameObject(_fireRingPrefabName);
					_prefab_FireRing.SetActive(value: false);
					AreaEffectEntity entity = InitAreaEntity(_prefab_FireRing);
					InitAttackComponent(entity);
					InitDiffuseComponent(entity);
					if (iFollow)
					{
						InitFollowComponent(entity);
					}
				}
			}
			return _prefab_FireRing;
		}

		private AreaEffectEntity InitAreaEntity(GameObject prefab)
		{
			AreaEffectEntity areaEffectEntity = prefab.AddOrGetComponent<AreaEffectEntity>();
			areaEffectEntity.hitBoxShape = HitBox.Shape.Circle;
			areaEffectEntity.hitBoxInnerRadius = initInnerRadius;
			areaEffectEntity.hitBoxRadius = radius + initInnerRadius;
			areaEffectEntity.UpdateColliderShape();
			return areaEffectEntity;
		}

		private void InitAttackComponent(AreaEffectEntity entity)
		{
			AreaEffect_AttackComponent areaEffect_AttackComponent = entity.AddOrGetMonoLogicComponent<AreaEffect_AttackComponent>();
			areaEffect_AttackComponent.hitDelay = 0;
			areaEffect_AttackComponent.hitInterval = attackInterval;
			areaEffect_AttackComponent.damageImmuneDuration = duration;
		}

		private void InitDiffuseComponent(AreaEffectEntity entity)
		{
			AreaEffect_DiffuseComponent areaEffect_DiffuseComponent = entity.AddOrGetMonoLogicComponent<AreaEffect_DiffuseComponent>();
			areaEffect_DiffuseComponent.interval = diffuseInterval;
			areaEffect_DiffuseComponent.speed = diffuseSpeed;
			areaEffect_DiffuseComponent.radiusTogether = true;
			areaEffect_DiffuseComponent.innerRadiusDiffuseType = AreaEffect_DiffuseComponent.InnerRadiusDiffuseType.SameSpeed;
		}

		private void InitFollowComponent(AreaEffectEntity entity)
		{
			AreaEffect_FollowComponent areaEffect_FollowComponent = entity.AddOrGetMonoLogicComponent<AreaEffect_FollowComponent>();
			areaEffect_FollowComponent.targetType = AreaEffect_FollowComponent.FollowTargetType.Owner;
			areaEffect_FollowComponent.isSlowMove = false;
		}
	}
