						{
							result.RemoveAt(num);
							break;
						}
					}
				}
				if (result.Count > 0)
				{
					int num2 = num_14;
					num2 = ((num2 >= result.Count) ? result.Count : num2);
					for (int i = 0; i < num2; i++)
					{
						MonsterAdventureActor monsterAdventureActor = result[i] as MonsterAdventureActor;
						if (monsterAdventureActor != null)
						{
