				bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, fireTag2);
				if ((num || flag) && base.CanExcuteA && TSRandom.Range(0, 100) <= prob_11 && monsterAdventureActor != null)
				{
					monsterAdventureActor.buffComponent.AddBuff(buff_11, base._actor);
