	public class FateCard_LightingChain : BaseFateCardTheme
	{
		private readonly int damageId = 986281;

		private readonly FP cd = 2;

		private const string triggerFxPath = "light_trigger_s";

		private readonly FP targetSearchRange = 15;

		private readonly string hitFxPath = "light_lightning_01";

		private const int baseBounceTime = 2;

		private readonly FP linkCheckRange = 8;

		private readonly FP linkHitInterval = 0.2;

		private static readonly int attackTag = CommonHelper.StringToHash("lightingChain");

		private FP pro_14 = 80;

		private int dmg_14 = 986282;

		private FP radius_14 = 10;

		private FP interval_14 = 0.5;

		private FP time_14 = 3;

		private readonly string hitFx_14 = "light_lightning_01";

		private string hitFxPath_strong = "light_lightning_15";

		private int buff_15 = 986281;

		private int count_15 = 1;

		private string tagCastCount = "CastCount_Chain";

		private List<CoroutineNode> corList = new List<CoroutineNode>();

		private Dictionary<int, int> dicCount = new Dictionary<int, int>();

		private bool canLinkOnSelf;

		public override void OnEnable()
		{
			base.OnEnable();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			foreach (CoroutineNode cor in corList)
			{
				base._actor.StopLogicCoroutine(cor);
			}
			corList.Clear();
			ClearKey(tagCastCount);
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				Shoot(damageId, 1);
				TriggerTheme();
			}
		}

		private void Shoot(int hitDamageId, int perkSlotIndex, LogicEntity target = null)
		{
			if (target == null)
			{
				target = GetShootTarget();
			}
			if (!(target == null))
			{
				CommonUtils.PlayOneOffFx(base._actor, "light_trigger_s");
				internalShoot(target, hitDamageId, perkSlotIndex);
			}
		}

		private LogicEntity GetShootTarget()
		{
			if (base._actor.attackTarget != null)
			{
				return base._actor.attackTarget;
			}
			LogicEntity target = null;
			ILRuntimeAPI.SearchByRange(base._actor, targetSearchRange, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					base._actor.SearchEntitySortByDistance(result);
					target = result[0];
				}
			}, isConfront: true);
			return target;
		}

		private void internalShoot(LogicEntity target, int damageId, int perkSlotIndex)
		{
			AddKey(tagCastCount);
			string hitFx = hitFxPath;
			if (base.CanExcuteB)
			{
				hitFx = hitFxPath_strong;
			}
			CoroutineNode item = StartLogicCoroutine(LoopLinkHit(target, damageId, hitFx));
			corList.Add(item);
		}

		private IEnumerator LoopLinkHit(LogicEntity firstTarget, int damageId, string hitFx)
		{
			int linkCount = GetMaxBounceTime();
			int curLink = 0;
			List<LogicEntity> temHitList = new List<LogicEntity>();
			LogicEntity lastTaget = null;
			while (curLink < linkCount)
			{
				if (curLink == 0)
				{
					int uniqueAttackId = SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId();
					dicCount.Add(uniqueAttackId, curLink);
					internalHit(base._actor, firstTarget, damageId, hitFx, uniqueAttackId);
					dicCount.Remove(uniqueAttackId);
					curLink++;
					temHitList.Add(firstTarget);
					lastTaget = firstTarget;
				}
				else
				{
					ILRuntimeAPI.SearchByRange(lastTaget as AdventureActor, linkCheckRange, delegate(List<LogicEntity> result)
					{
						if (result.Count > 0)
						{
							if (!canLinkOnSelf && result.Contains(base._actor))
							{
								result.Remove(base._actor);
							}
							for (int i = 0; i < temHitList.Count; i++)
							{
								if (result.Contains(temHitList[i]))
								{
									result.Remove(temHitList[i]);
								}
							}
						}
						if (result.Count == 0)
						{
							curLink = linkCount;
						}
						else
						{
							lastTaget.SearchEntitySortByDistance(result);
							LogicEntity logicEntity = result[0];
							int uniqueAttackId2 = SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId();
							dicCount.Add(uniqueAttackId2, curLink);
							internalHit(lastTaget, logicEntity, damageId, hitFx, uniqueAttackId2);
							dicCount.Remove(uniqueAttackId2);
							temHitList.Add(logicEntity);
							lastTaget = logicEntity;
							curLink++;
						}
					});
				}
				yield return linkHitInterval;
			}
		}

		private void internalHit(LogicEntity from, LogicEntity target, int damageId, string hitFxPath, int uniqueAtkId = 0)
		{
			AdventureActor actor = base._actor;
			AdventureActor obj = target as AdventureActor;
			GameObject gameObject = from.gameObject;
			ILRuntimeAPI.HitActor(actor, obj, damageId, (string)null, hitFxPath, true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, uniqueAtkId, gameObject);
		}

		private int GetMaxBounceTime()
		{
			int num = 3;
			if (base.CanExcuteB)
			{
				num += count_15;
			}
			return num;
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent evt)
		{
			base.OnBeforeHit(evt);
			CommonUtils.CheckHitByTag(evt.hitDamageTag, attackTag);
		}

		protected override void OnHitPre(AdventureActorReceiveDamageBeforeSettlementEvent evt)
		{
			base.OnHitPre(evt);
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (CommonUtils.CheckHitByTag(evt.hitDamageTag, attackTag))
			{
				if (base.CanExcuteB)
				{
					Singleton<BuffManager>.Instance.AddBufftoGroup(buff_15, base._actor);
				}
				if (base.CanExcuteA && monsterAdventureActor != null && TSRandom.Range(0, 100) < pro_14)
				{
					CoroutineNode item = StartLogicCoroutine(SpecialHit(monsterAdventureActor, hitFx_14, time_14, dmg_14, radius_14, interval_14));
					corList.Add(item);
				}
			}
		}

		private IEnumerator SpecialHit(AdventureActor to, string hitFx, FP time, int damageId, FP radius, FP interval)
		{
			FP curTime = 0;
			List<LogicEntity> targets = new List<LogicEntity>();
			while (curTime < time)
			{
				CommonUtils.SearchNearTargetsByCircle(to, radius, isConfront: false, includeSelf: false, targets);
				for (int i = 0; i < targets.Count; i++)
				{
					internalHit(to, targets[i], damageId, hitFx);
				}
				curTime += interval;
				yield return interval;
			}
		}
	}
	public class FateCard_LightingGhost : BaseFateCardTheme
	{
		private readonly int damageId = 986311;

		private readonly FP cd = 2;

		private const int maxCount = 3;

		private readonly FP triggerStateTime = 5;

		private readonly FP triggerInterval = 0.5;

		private const string lightingGhostPrefabPath = "FateCard_LightingGhost";

		private const string triggerFxPath = "light_ghost_charge";

		private readonly Dictionary<int, TSVector> positionDic = new Dictionary<int, TSVector>
		{
			[1] = new TSVector(-0.6, 1.6, -0.7),
			[2] = new TSVector(0.5, 2.1, -0.5),
			[3] = new TSVector(0.78, 1, -0.3),
			[4] = new TSVector(-1, 1.4, 0),
			[5] = new TSVector(-0.4, 1, -1),
			[6] = new TSVector(0.4, 1.4, -1)
		};

		private static readonly int damageTag_LightingGhost = CommonHelper.StringToHash("LightingGhost");

		private const int hitDamageId_11 = 986312;

		private const string hitFxPath_11 = "light_ghost_lighting_11";

		private const string hittedFxPath_11 = "";

		private readonly FP hitRaidus_11 = 2;

		private const int minHitTimes_11 = 0;

		private const int maxHitTimes_11 = 3;

		private readonly FP hitInterval_11 = 1;

		private const int addMaxCount_Task3 = 1;

		private readonly FP hitInterval_Task3 = 0.5;

		private readonly FP searchTargetRadius_Task3 = 8;

		private const int hitDamageId_Task3 = 986313;

		private const string hitFxPath_Task3 = "light_ghost_lightning_18";

		private bool _inTriggerState;

		private Dictionary<int, LightingGhostEntity> _lightingGhostDic;

		private int _currentMaxCount;

		private CoroutineNode _triggerStateCor;

		private Dictionary<string, GameObject> _lightingGhostPrefabDic;

		private CommomAreaHitConfig _areaHitConfig;

		private CoroutineNode _intervalHitCor;

		public override void OnEnable()
		{
			base.OnEnable();
			_currentMaxCount = 3;
			if (base.CanExcuteB)
			{
				_currentMaxCount++;
			}
			if (base.CanExcuteB)
			{
				_intervalHitCor = StartLogicCoroutine(IntervalHit_ProB());
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("SPECIAL_ENTITY_FINISH", OnSpecialEntityFinish);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			if (_lightingGhostDic != null)
			{
				List<int> list = _lightingGhostDic.Keys.ToList();
				for (int i = 0; i < list.Count; i++)
				{
					int key = list[i];
					_lightingGhostDic[key]?.Finish();
				}
				_lightingGhostDic.Clear();
			}
			if (_triggerStateCor != null)
			{
				StopLogicCoroutine(_triggerStateCor);
			}
			_triggerStateCor = null;
			if (_intervalHitCor != null)
			{
				StopLogicCoroutine(_intervalHitCor);
				_intervalHitCor = null;
			}
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("SPECIAL_ENTITY_FINISH", OnSpecialEntityFinish);
		}

		protected override void OnTrigger()
		{
			if (!_inTriggerState && CheckTimeout(cd) && GenerateLightingGhost(damageId))
			{
				TriggerTheme();
			}
		}

		private bool GenerateLightingGhost(int hitDamageId, bool dontEnterTriggerState = false)
		{
			if (_inTriggerState)
			{
				return false;
			}
			if (_lightingGhostDic == null)
			{
				_lightingGhostDic = new Dictionary<int, LightingGhostEntity>(5);
			}
			else if (!dontEnterTriggerState && _lightingGhostDic.Count >= _currentMaxCount)
			{
				EnterTriggerState();
				return false;
			}
			string text = "FateCard_LightingGhost";
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			GameObject lightingGhostPrefab = GetLightingGhostPrefab(text);
			if (lightingGhostPrefab == null)
			{
				return false;
			}
			int nextLightingGhostIndex = GetNextLightingGhostIndex();
			if (!positionDic.TryGetValue(nextLightingGhostIndex, out var value))
			{
				NovaLogger.Error($"电鬼位置偏移未配置,槽位索引:{nextLightingGhostIndex}");
			}
			TSVector jVector = base._actor.tsTransform.Position3D + value;
			LightingGhostEntity lightingGhostEntity = SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(base._actor, lightingGhostPrefab, jVector.ToVector(), base._actor.transform.rotation) as LightingGhostEntity;
			if (lightingGhostEntity == null)
			{
				return false;
			}
			if (!string.IsNullOrEmpty("light_ghost_charge"))
			{
				CommonUtils.PlayOneOffFx(base._actor, "light_ghost_charge");
			}
			lightingGhostEntity.offset = value;
			lightingGhostEntity.hitDamageId = hitDamageId;
			_lightingGhostDic.Add(nextLightingGhostIndex, lightingGhostEntity);
			if (!dontEnterTriggerState && _lightingGhostDic.Count >= _currentMaxCount)
			{
				EnterTriggerState();
			}
			return true;
		}

		protected override void OnHitPost(AdventureActorReceiveDamageEvent _evt)
		{
			base.OnHitPost(_evt);
			MonsterAdventureActor monsterAdventureActor = _evt.to as MonsterAdventureActor;
			AdventureActor actor = _evt.from as AdventureActor;
			if (monsterAdventureActor != null && CommonUtils.CheckHitByTag(_evt.hitDamageTag, damageTag_LightingGhost) && base.CanExcuteA)
			{
				StartLogicCoroutine(AreaHit_Perk11(actor, monsterAdventureActor));
			}
		}

		private IEnumerator AreaHit_Perk11(AdventureActor actor, AdventureActor target)
		{
			int totalHitTimes = TSRandom.Range(0, 4);
			int hitTimes = 0;
			TSVector2 position = target.tsTransform.Position;
			long targetId = target.Id;
			while (hitTimes < totalHitTimes)
			{
				if (_areaHitConfig == null)
				{
					_areaHitConfig = new CommomAreaHitConfig();
				}
				_areaHitConfig.position = position;
				_areaHitConfig.fxAlias = "light_ghost_lighting_11";
				_areaHitConfig.hitDamageId = 986312;
				_areaHitConfig.hittedEffectAlias = "";
				_areaHitConfig.damageImmuneDuration = -1;
				ILRuntimeAPI.CircleAreaHit(actor, _areaHitConfig, hitRaidus_11, 0);
				hitTimes++;
				FP interval = hitInterval_11;
				while (interval > 0)
				{
					if (target.Id == targetId && !target.IsDead())
					{
						position = target.tsTransform.Position;
					}
					interval -= base.LogicDeltaTime;
					yield return null;
				}
			}
		}

		private IEnumerator SingleHit_PerkTask3(int index)
		{
			FP hitInterval = 0;
			while (_lightingGhostDic != null && _lightingGhostDic.ContainsKey(index))
			{
				LightingGhostEntity lightingGhost = _lightingGhostDic[index];
				if (lightingGhost.InTriggerState)
				{
					break;
				}
				if (hitInterval > 0)
				{
					hitInterval -= base.LogicDeltaTime;
				}
				else
				{
					ILRuntimeAPI.SearchByRangeAndPosition(base._actor, lightingGhost.tsTransform.Position, searchTargetRadius_Task3, delegate(List<LogicEntity> result)
					{
						if (result.Count > 0)
						{
							AdventureActor actor = base._actor;
							AdventureActor obj = result[TSRandom.Range(0, result.Count)] as AdventureActor;
							GameObject gameObject = lightingGhost.gameObject;
							ILRuntimeAPI.HitActor(actor, obj, 986313, (string)null, "light_ghost_lightning_18", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, gameObject);
							hitInterval = hitInterval_Task3;
						}
						else
						{
							hitInterval = 0;
						}
					}, isConfront: true);
				}
				yield return null;
			}
		}

		private IEnumerator IntervalHit_ProB()
		{
			FP hitInterval = hitInterval_Task3;
			while (true)
			{
				if (_lightingGhostDic != null && _lightingGhostDic.Count > 0 && !_inTriggerState)
				{
					if (hitInterval > 0)
					{
						hitInterval -= base.LogicDeltaTime;
					}
					else
					{
						ILRuntimeAPI.SearchByRangeAndPosition(base._actor, base._actor.tsTransform.Position, searchTargetRadius_Task3, delegate(List<LogicEntity> result)
						{
							if (result.Count > 0)
							{
								AdventureActor adventureActor = result[TSRandom.Range(0, result.Count)] as AdventureActor;
								for (int i = 0; i < _lightingGhostDic.Count; i++)
								{
									ILRuntimeAPI.HitActor(base._actor, adventureActor, 986313, (string)null, "light_ghost_lightning_18", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, _lightingGhostDic.Values.ToList()[i].gameObject);
								}
								hitInterval = hitInterval_Task3;
							}
							else
							{
								hitInterval = 0;
							}
						}, isConfront: true);
					}
				}
				yield return null;
			}
		}

		private void OnSpecialEntityFinish(IEvent evt)
		{
			LightingGhostEntity lightingGhostEntity = (evt as SpecialEntityFinishEvent).entity as LightingGhostEntity;
			if (!(lightingGhostEntity == null))
			{
				FinishLightingGhost(lightingGhostEntity.Id);
			}
		}

		private void FinishLightingGhost(long entityId)
		{
			if (_lightingGhostDic == null)
			{
				return;
			}
			int num = -1;
			foreach (int key in _lightingGhostDic.Keys)
			{
				LightingGhostEntity lightingGhostEntity = _lightingGhostDic[key];
				if (lightingGhostEntity != null && lightingGhostEntity.Id == entityId)
				{
					num = key;
					break;
				}
			}
			if (num > 0)
			{
				_lightingGhostDic.Remove(num);
			}
		}

		private int GetNextLightingGhostIndex()
		{
			int num = 1;
			for (int i = 0; i < _lightingGhostDic.Count; i++)
			{
				if (!_lightingGhostDic.ContainsKey(num))
				{
					break;
				}
				num++;
			}
			return num;
		}

		private GameObject GetLightingGhostPrefab(string path)
		{
			if (_lightingGhostPrefabDic == null)
			{
				_lightingGhostPrefabDic = new Dictionary<string, GameObject>(3);
			}
			if (!_lightingGhostPrefabDic.ContainsKey(path))
			{
				GameObject bulletByAlias = ModuleController<AdventureModuleController>.Instance.GetBulletByAlias(base._actor, path, forceUseCommonConfig: true);
				_lightingGhostPrefabDic.Add(path, bulletByAlias);
			}
			return _lightingGhostPrefabDic[path];
		}

		private void EnterTriggerState()
		{
			if (_triggerStateCor != null)
			{
				StopLogicCoroutine(_triggerStateCor);
			}
			_triggerStateCor = StartLogicCoroutine(TriggerStateLogic());
		}

		private IEnumerator TriggerStateLogic()
		{
			_inTriggerState = true;
			FP duration = triggerStateTime;
			FP interval = 0;
			while (duration > 0 && GetAttackLightingGhostCount() > 0)
			{
				if (!(interval > 0))
				{
					interval = ((!TriggerAttackLightingGhost()) ? ((FP)0) : triggerInterval);
				}
				else
				{
					interval -= base.LogicDeltaTime;
				}
				duration -= base.LogicDeltaTime;
				yield return null;
			}
			_inTriggerState = false;
		}

		private int GetAttackLightingGhostCount()
		{
			if (_lightingGhostDic == null)
			{
				return 0;
			}
			int num = 0;
			foreach (LightingGhostEntity value in _lightingGhostDic.Values)
			{
				if (value.type == LightingGhostEntity.LightingGhostType.Normal || value.type == LightingGhostEntity.LightingGhostType.Strengthen)
				{
					num++;
				}
			}
			return num;
		}

		private bool TriggerAttackLightingGhost()
		{
			if (_lightingGhostDic == null)
			{
				return false;
			}
			foreach (LightingGhostEntity value in _lightingGhostDic.Values)
			{
				if ((value.type == LightingGhostEntity.LightingGhostType.Normal || value.type == LightingGhostEntity.LightingGhostType.Strengthen) && !value.InTriggerState)
				{
					return value.TryTrigger();
				}
			}
			return false;
		}
	}
	public class FateCard_Shark : BaseFateCardTheme
	{
		private readonly string sharkBullut = "FateCard_Shark_Bullet_base";

		private readonly int damageId = 986221;

		private readonly FP cd = 3;

		private readonly FP circleRadius = 15;

		private const string triggerFxPath = "";

		private static readonly int bullutTag = CommonHelper.StringToHash("Shark");

		private static readonly int hitTag_shark = CommonHelper.StringToHash("Shark");

		private static readonly int hitTag_shark_strong = CommonHelper.StringToHash("Shark_Strong");

		private FP baseDelayTime = 0.5;

		private int count_18 = 2;

		private string bullut_18 = "FateCard_Shark_Bullet_18";

		private int hitDmgId_18 = 986222;

		private int buff_18 = 4011;

		private string drop_16 = "FateCard_Shark_Drop_16";

		private int hitDmgId_16 = 986223;

		private readonly int interval_16 = 3;

		private int shootCount;

		private readonly List<CoroutineNode> corList = new List<CoroutineNode>();

		private HashSet<long> dropHash_16 = new HashSet<long>();

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("DROP_EFFECT_FINISH", OnDropFinish);
			if (base.CanExcuteB)
			{
				CoroutineNode item = StartLogicCoroutine(IntervalDrop());
				corList.Add(item);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("DROP_EFFECT_FINISH", OnDropFinish);
			foreach (CoroutineNode cor in corList)
			{
				base._actor.StopLogicCoroutine(cor);
			}
			corList.Clear();
			shootCount = 0;
			dropHash_16.Clear();
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				Shoot(sharkBullut, base._actor.attackTarget, damageId);
				TriggerTheme();
			}
		}

		private void Shoot(string bullut, LogicEntity target, int hitDamageId)
		{
			target = ((target != null) ? target : CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius));
			if (!(target == null))
			{
				CommonUtils.PlayOneOffFx(base._actor, "");
				string bullut2 = GetBullut();
				AdventureActor actor = base._actor;
				FP heightCenter = base._actor.dtCollider.HeightCenter;
				LogicEntity target2 = target;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bullut2, actor, default(FP), default(TSVector2), heightCenter, default(TSVector2), target2, AimType.Target, BulletDirectionType.BulletToTarget);
				adventureBulletBase.hitBox.hitDamageId = hitDamageId;
				if (base.CanExcuteA && string.Equals(bullut2, bullut_18))
				{
					adventureBulletBase.hitBox.hitDamageId = hitDmgId_18;
				}
				FixBullutInfo(adventureBulletBase, adventureBulletBase.hitBox.hitDamageId);
				RefreshCount(bullut2);
			}
		}

		private IEnumerator IntervalDrop()
		{
			int rawTime = interval_16;
			FP curTime = 0;
			while (true)
			{
				if (curTime < 0)
				{
					long num = ILRuntimeAPI.PlayDrop(base._actor, drop_16);
					if (num > 0)
					{
						dropHash_16.Add(num);
					}
					curTime = rawTime;
				}
				curTime -= base.LogicDeltaTime;
				yield return null;
			}
		}

		private void OnDropFinish(IEvent evt)
		{
			AdventureDropFinishEvent obj = evt as AdventureDropFinishEvent;
			long entityID = obj.entityID;
			if (!obj.isPickUp || !base.CanExcuteB || !dropHash_16.Contains(entityID))
			{
				return;
			}
			LogicEntity logicEntity = ((base._actor.attackTarget != null) ? base._actor.attackTarget : CommonUtils.SearchNearTargetByCircle(base._actor, circleRadius));
			if (logicEntity != null)
			{
				string bullut = GetBullut();
				AdventureActor actor = base._actor;
				TSVector2 position = logicEntity.tsTransform.Position;
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bullut, actor, default(FP), default(TSVector2), default(FP), position, null, AimType.Position, BulletDirectionType.BulletToTarget);
				if (base.CanExcuteA && string.Equals(bullut, bullut_18))
				{
					adventureBulletBase.ResetHitID(hitDmgId_18);
				}
				else
				{
					adventureBulletBase.hitBox.hitDamageId = hitDmgId_16;
				}
				RefreshCount(bullut);
			}
			dropHash_16.Remove(entityID);
		}

		protected override void OnHitPre(AdventureActorReceiveDamageBeforeSettlementEvent evt)
		{
			base.OnHitPre(evt);
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (monsterAdventureActor != null)
			{
				bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark);
				bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_shark_strong);
				if ((num || flag) && base.CanExcuteA && flag)
				{
					monsterAdventureActor.buffComponent.AddBuff(buff_18, base._actor);
				}
			}
		}

		private void FixBullutInfo(AdventureBulletBase bullCom, int finalHitDmgId)
		{
			bullCom.temphitDmgId = finalHitDmgId;
			bullCom.hitBox.hitDamageId = 986224;
			bullCom.ModifyBulletTag(bullutTag);
		}

		protected override void OnNoDmgHit(AdventureActorNoDamageEvent evt)
		{
			base.OnNoDmgHit(evt);
			if (evt.weapon != null && evt.weapon.CheckBulletTag(bullutTag))
			{
				CoroutineNode item = StartLogicCoroutine(DelayHit(evt.to, evt.weapon.temphitDmgId), runImmediately: true);
				corList.Add(item);
			}
		}

		private IEnumerator DelayHit(LogicEntity to, int hitDmgId)
		{
			yield return baseDelayTime;
			ILRuntimeAPI.HitActor(base._actor, to as AdventureActor, hitDmgId, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
		}

		private void RefreshCount(string tempBullut)
		{
			if (base.CanExcuteA && string.Equals(tempBullut, sharkBullut))
			{
				shootCount++;
			}
		}

		private string GetBullut()
		{
			if (base.CanExcuteA && shootCount >= count_18)
			{
				shootCount = 0;
				return bullut_18;
			}
			return sharkBullut;
		}
	}
	public class FateCard_WhirlWind : BaseFateCardTheme
	{
		private readonly string commonWindArea = "FateCard_WhirlWind";

		private readonly FP commonCenterDis = 1.5;

		private readonly int hitDamageId = 986041;

		private readonly FP cd = 1.5;

		private readonly string commonWindArea_Diffuse = "FateCard_WhirlWind_q1";

		private readonly int hitDamageId_2 = 986043;

		private readonly string smallWindArea_Arc = "FateCard_WhirlWind_small_q2";

		private readonly int samllDamageId_ProB = 986042;

		private readonly int smallWindArea_count = 5;

		private readonly int samllDamageId_ProC = 986044;

		private List<long> allWindLogicId = new List<long>();

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
			allWindLogicId.Clear();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
		}

		protected override void OnTrigger()
		{
			if (!CheckTimeout(cd))
			{
				return;
			}
			LogicEntity logicEntity = CommonUtils.SearchNearTargetByCircle(base._actor, 99);
			if (!(logicEntity == null))
			{
				int damageId = hitDamageId;
				if (base.CanExcuteA)
				{
					damageId = hitDamageId_2;
				}
				ChooseAreaEffect(commonWindArea, logicEntity, isMove: true, damageId, commonCenterDis);
				TriggerTheme();
			}
		}

		private void ChooseAreaEffect(string bulletPath, LogicEntity to, bool isMove = true, int damageId = 0, FP cDis = default(FP))
		{
			string areaEffect = bulletPath;
			bool isDiffuse = false;
			FP cDisMax = 0;
			FP cGrowth = 0;
			FP cInterval = 0;
			if (base.CanExcuteA)
			{
				isDiffuse = true;
				areaEffect = commonWindArea_Diffuse;
			}
			PlayHit(areaEffect, to, isMove, isSuper: false, damageId, isDiffuse, cDis, cDisMax, cGrowth, cInterval);
		}

		private void PlayHit(string areaEffect, LogicEntity to, bool isMove, bool isSuper, int damageId, bool isDiffuse, FP cDis, FP cDisMax, FP cGrowth, FP cInterval)
		{
			FP angle = (to.tsTransform.Position - base._actor.tsTransform.Position).normalized.GetAngle();
			TSVector2 tSVector = base._actor.tsTransform.Position;
			if (!isMove)
			{
				DeterministicShape shape = new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Circle,
					angle = 360,
					radius = 2,
					position = to.tsTransform.Position
				};
				tSVector = base._actor.RandomActorReachablePointInsideShape(shape);
			}
			long num = ILRuntimeAPI.PlayAreaEffect(base._actor, areaEffect, tSVector, angle, (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
			{
				entity.duration = 3;
				AreaEffect_MoveComponent logicComponent = entity.GetLogicComponent<AreaEffect_MoveComponent>();
				if (logicComponent != null)
				{
					logicComponent.speed = 5;
				}
				AreaEffect_PullComponent logicComponent2 = entity.GetLogicComponent<AreaEffect_PullComponent>();
				if (logicComponent2 != null)
				{
					logicComponent2.strength = 0;
				}
				AreaEffect_AttackComponent logicComponent3 = entity.GetLogicComponent<AreaEffect_AttackComponent>();
				if (logicComponent3 != null)
				{
					logicComponent3.hitInterval = 0.5;
					if (damageId != 0)
					{
						logicComponent3.hitDamageId = damageId;
					}
				}
				if (!isMove && logicComponent != null)
				{
					logicComponent.speed = 0;
				}
			}, (AdventureActor)null);
			if (num != 0L)
			{
				allWindLogicId.Add(num);
			}
		}

		private void PlaySmallHit(LogicEntity wind)
		{
			TSVector2 position = wind.tsTransform.Position;
			for (int i = 0; i < smallWindArea_count; i++)
			{
				FP fP = 0;
				fP = wind.tsTransform.Forward.GetAngle() + i * 90 + TSRandom.Range(-30, 30);
				ILRuntimeAPI.PlayAreaEffect(base._actor, smallWindArea_Arc, position, fP, (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
				{
					entity.GetLogicComponent<AreaEffect_AttackComponent>().hitDamageId = (base.CanExcuteC ? samllDamageId_ProC : samllDamageId_ProB);
				}, (AdventureActor)null);
			}
		}

		private void OnAreaEffectFinish(IEvent evt)
		{
			if (evt is AdventureAreaEffectFinishEvent { entityID: var entityID } adventureAreaEffectFinishEvent && base.CanExcuteB && allWindLogicId.Contains(entityID))
			{
				PlaySmallHit(adventureAreaEffectFinishEvent.sender as LogicEntity);
			}
		}
	}
	public class FateCard_WindBlade : BaseFateCardTheme
	{
		private const string windBladePath = "FateCard_windBlade";

		private const string triggerFxPath = "wind_trigger_s";

		private const int windBladeDefaultReboundCount = 3;

		private const int windBladeDefaultShootCount = 3;

		private readonly FP shootDelay = 0.4f;

		private readonly FP cd = 3;

		private const int hitDamageId = 986011;

		private const string whiteWindBladeBulltKey = "WindBladeWhite";

		private readonly FP whiteWindBladeBulltSearchTargetRadius = 15;

		private const string triggerFx_Pro = "wind_fengren_bird_end_14";

		private readonly string scatteringDartsPath_Pro = "FateCard_windBlade_White_3";

		private readonly FP rate_ProA = 0.3;

		private readonly FP rate_ProB = 0.3;

		private GameObject _scatteringDartsPrefab;

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("BULLET_BORN", OnBulletBorn);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("WINDBLADE_REBOUND", OnWindBladeRebound);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_BORN", OnBulletBorn);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("WINDBLADE_REBOUND", OnWindBladeRebound);
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				ShootWindBlade();
				TriggerTheme();
			}
		}

		private void ShootWindBlade()
		{
			CommonUtils.PlayOneOffFx(base._actor, "wind_trigger_s");
			StartLogicCoroutine(CurShootWindBlade(3, 986011, 3));
		}

		private IEnumerator CurShootWindBlade(int shootCount, int hitDamageId, int reboundTime)
		{
			for (int i = 0; i < shootCount; i++)
			{
				TSVector2 dirction = base._actor.tsTransform.Forward;
				if (base._actor.attackTarget != null)
				{
					dirction = (base._actor.attackTarget.tsTransform.Position - base._actor.tsTransform.Position).normalized;
				}
				AdventureWindBlade adventureWindBlade = ILRuntimeAPI.Shoot("FateCard_windBlade", base._actor, base._actor.tsTransform.Position, dirction) as AdventureWindBlade;
				if (adventureWindBlade != null)
				{
					adventureWindBlade.hitDamageId = hitDamageId;
					adventureWindBlade.reboundCount = reboundTime;
					adventureWindBlade.damageImmuneDuration = -1;
					adventureWindBlade.reboundToPlayer = base.CanExcuteA;
				}
				else
				{
					NovaLogger.Error("释放的飞行道具非风刃");
				}
				yield return base._actor.StartLogicCoroutine(base._actor.WaitForSeconds(shootDelay));
			}
		}

		private void OnWindBladeRebound(IEvent evt)
		{
			if (!(evt is WindBladeReboundEvent windBladeReboundEvent))
			{
				return;
			}
			if (base.CanExcuteA && windBladeReboundEvent.reboundWithPlayer && TSRandom.Range(0f, 1f) <= rate_ProA)
			{
				CommonUtils.PlayOneOffFx(base._actor, "wind_fengren_bird_end_14");
				if (_scatteringDartsPrefab == null)
				{
					_scatteringDartsPrefab = ModuleController<AdventureModuleController>.Instance.GetBulletByAlias(base._actor, scatteringDartsPath_Pro, forceUseCommonConfig: true);
				}
				SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(base._actor, _scatteringDartsPrefab, windBladeReboundEvent.windBlade.transform.position, Quaternion.identity);
			}
			if (base.CanExcuteB && !windBladeReboundEvent.reboundWithPlayer && TSRandom.Range(0f, 1f) <= rate_ProB)
			{
				CommonUtils.PlayOneOffFx(base._actor, "wind_fengren_bird_end_14");
				if (_scatteringDartsPrefab == null)
				{
					_scatteringDartsPrefab = ModuleController<AdventureModuleController>.Instance.GetBulletByAlias(base._actor, scatteringDartsPath_Pro, forceUseCommonConfig: true);
				}
				SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(base._actor, _scatteringDartsPrefab, windBladeReboundEvent.windBlade.transform.position, Quaternion.identity);
			}
		}

		private void OnBulletBorn(IEvent evt)
		{
			AdventureBulletBornEvent adventureBulletBornEvent = evt as AdventureBulletBornEvent;
			if (adventureBulletBornEvent.owner is PlayerAdventureActor && adventureBulletBornEvent.tag.Equals("WindBladeWhite"))
			{
				AdventureBezierBullet adventureBezierBullet = adventureBulletBornEvent.sender as AdventureBezierBullet;
				if (adventureBezierBullet != null)
				{
					LogicEntity target = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, whiteWindBladeBulltSearchTargetRadius);
					adventureBezierBullet.target = target;
				}
			}
		}
	}
	public class FateCard_WindEagle : BaseFateCardTheme
	{
		private const int hitDamageId = 986071;

		private readonly FP cd = 3;

		private readonly FP searchTargetRadius = 7;

		private readonly FP duration_AreaEffect = 1.45;

		private readonly FP hitDelay = 0.4;

		private readonly FP hitTimes_Base = 3;

		private const string areaEffectPath_Base = "FateCard_WindEagle";

		private const string fxPath_AreaTrigger = "wind_sickleweasel_atk_1";

		private static readonly int damageTag_WindEagle = CommonHelper.StringToHash("WindEagle");

		private readonly FP hitRadius_14 = 1.5;

		private const int hitDamageId_14 = 986072;

		private const string hitFxPath_14 = "wind_sickleweasel_14_lv1";

		private const string hittedFxPath_14 = "hit_wind_magic";

		private const string areaEffectPath_Base_Task_2 = "FateCard_WindEagle_17";

		private readonly FP duration_AreaEffect_B = 2.2;

		private readonly FP hitDelay_Task_2 = 1.95;

		private const int hitDamageId_Task_2 = 986073;

		private const string hittedFxPath_Task_2 = "hit_wind_magic";

		private readonly FP pullMoveSpeed_Task_2 = 10;

		private const int pullMoveLevel_Task_2 = 99;

		private readonly FP pullStrenth_Task_2 = 4;

		private static readonly int damageTag_Task_2 = CommonHelper.StringToHash("WindEagle_Task_2");

		private readonly Dictionary<int, int> additionalAttrIdDic_Task_2 = new Dictionary<int, int>
		{
			[0] = 50,
			[1] = 50,
			[2] = 50,
			[3] = 45,
			[4] = 40,
			[5] = 35,
			[6] = 30,
			[7] = 20,
			[8] = 10,
			[9] = 0
		};

		private PlayFX _playFX;

		private CommomAreaHitConfig _areaHitConfig;

		private HashSet<long> _triggerSet_14;

		private List<FP> _pullDistanceList;

		public override void OnEnable()
		{
			base.OnEnable();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_triggerSet_14?.Clear();
		}

		protected override void OnTrigger()
		{
			if (CheckTimeout(cd))
			{
				GenerateWindEagle(986071);
				TriggerTheme();
			}
		}

		private bool GenerateWindEagle(int hitDamageId)
		{
			LogicEntity target = base._actor.attackTarget ?? CommonUtils.SearchNearTargetByCircle(base._actor, searchTargetRadius);
			if (target == null)
			{
				return false;
			}
			string windEaglgPrefabPath = GetWindEaglgPrefabPath();
			if (ILRuntimeAPI.PlayAreaEffect(base._actor, windEaglgPrefabPath, target.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity areaEffect)
			{
				if (areaEffect != null)
				{
					FP fP = (areaEffect.duration = (base.CanExcuteB ? duration_AreaEffect_B : duration_AreaEffect));
					AreaEffect_AttackComponent logicComponent = areaEffect.GetLogicComponent<AreaEffect_AttackComponent>();
					if (logicComponent != null)
					{
						logicComponent.hitDamageId = hitDamageId;
						logicComponent.hitDelay = hitDelay;
						logicComponent.damageImmuneDuration = -1;
						FP fP2 = fP - hitDelay;
						if (hitTimes_Base > 0)
						{
							logicComponent.hitInterval = fP2 / hitTimes_Base;
						}
						else
						{
							NovaLogger.Error("风鹰基础攻击次数配置有误");
						}
					}
					if (base.CanExcuteB)
					{
						StartLogicCoroutine(AreaHit_PerkTask2(base._actor, target.tsTransform.Position, areaEffect.hitBoxRadius));
					}
				}
			}, (AdventureActor)null) <= 0)
			{
				return false;
			}
			string text = "wind_sickleweasel_atk_1";
			if (!string.IsNullOrEmpty(text))
			{
				if (_playFX == null)
				{
					_playFX = new PlayFX();
				}
				else
				{
					_playFX.Clear();
				}
				_playFX.Play(base._actor, null, text, default(FP), target.tsTransform.Position, default(TSVector2));
				_playFX.Clear();
			}
			return true;
		}

		protected override void OnHitPost(AdventureActorReceiveDamageEvent _evt)
		{
			base.OnHitPost(_evt);
			MonsterAdventureActor monsterAdventureActor = _evt.to as MonsterAdventureActor;
			if (monsterAdventureActor != null && CommonUtils.CheckHitByTag(_evt.hitDamageTag, damageTag_WindEagle) && base.CanExcuteA)
			{
				if (_triggerSet_14 == null)
				{
					_triggerSet_14 = new HashSet<long>();
				}
				_triggerSet_14.Add(monsterAdventureActor.Id);
			}
		}

		protected override void OnBeforeHit(AdventureActorReceiveDamageBeforeHitEvent _evt)
		{
			base.OnBeforeHit(_evt);
			MonsterAdventureActor monsterAdventureActor = _evt.to as MonsterAdventureActor;
			if (!(monsterAdventureActor != null) || !base.CanExcuteB || !CommonUtils.CheckHitByTag(_evt.hitDamageTag, damageTag_Task_2))
			{
				return;
			}
			FP hpPercentage = monsterAdventureActor.actorHealthInfo.hpPercentage;
			if (hpPercentage < 100)
			{
				int key = TSMath.FloorToInt(hpPercentage * 10);
				if (additionalAttrIdDic_Task_2.TryGetValue(key, out var value) && value > 0)
				{
					AdventureActor.AddFromAttr(value, base._actor);
				}
			}
		}

		protected override void OnMonsterKilled(AdventureActorReceiveDamageEvent _evt)
		{
			base.OnMonsterKilled(_evt);
			MonsterAdventureActor monsterAdventureActor = _evt.to as MonsterAdventureActor;
			if (base.CanExcuteA)
			{
				HashSet<long> triggerSet_ = _triggerSet_14;
				if (triggerSet_ != null && triggerSet_.Remove(monsterAdventureActor.Id))
				{
					AreaHit_Perk14(monsterAdventureActor.tsTransform.Position);
				}
			}
		}

		private IEnumerator AreaHit_PerkTask2(AdventureActor actor, TSVector2 position, FP hitRadius)
		{
			yield return hitDelay_Task_2;
			if (_areaHitConfig == null)
			{
				_areaHitConfig = new CommomAreaHitConfig();
			}
			_areaHitConfig.position = position;
			_areaHitConfig.hitDamageId = 986073;
			_areaHitConfig.hittedEffectAlias = "hit_wind_magic";
			ILRuntimeAPI.CircleAreaHit(actor, _areaHitConfig, hitRadius, 0);
			ILRuntimeAPI.SearchByRangeAndPosition(base._actor, position, hitRadius, delegate(List<LogicEntity> targets)
			{
				if (targets != null && targets.Count > 0)
				{
					if (_pullDistanceList == null)
					{
						_pullDistanceList = new List<FP>(5);
					}
					else
					{
						_pullDistanceList.Clear();
					}
					for (int i = 0; i < targets.Count; i++)
					{
						_pullDistanceList.Add(TSVector2.Distance(targets[i].tsTransform.Position, position));
					}
					ILRuntimeAPI.ForceMoveToPosition(position, targets, pullMoveSpeed_Task_2, _pullDistanceList, isCoExist: true, isChangeForward: true, 99, pullStrenth_Task_2);
				}
			}, isConfront: true);
		}

		private void AreaHit_Perk14(TSVector2 position)
		{
			if (_areaHitConfig == null)
			{
				_areaHitConfig = new CommomAreaHitConfig();
			}
			_areaHitConfig.fxAlias = "wind_sickleweasel_14_lv1";
			_areaHitConfig.position = position;
			_areaHitConfig.hitDamageId = 986072;
			_areaHitConfig.hittedEffectAlias = "hit_wind_magic";
			ILRuntimeAPI.CircleAreaHit(base._actor, _areaHitConfig, hitRadius_14, 0);
		}

		private string GetWindEaglgPrefabPath()
		{
			if (!base.CanExcuteB)
			{
				return "FateCard_WindEagle";
			}
			return "FateCard_WindEagle_17";
		}
	}
