	public class Disc_213016 : DiscScriptBase
	{
		private const int discId = 213016;

		private List<int> skillId_s1 = new List<int> { 4019000, 4019001, 4019002, 4019003, 4019004 };

		private List<int> buff_s1v1_1 = new List<int> { 4019000, 4019001, 4019002, 4019003, 4019004 };

		private List<int> buff_s1v1_2 = new List<int> { 4019005, 4019005, 4019005, 4019005, 4019005 };

		private List<int> count_s1v1 = new List<int> { 6, 6, 6, 6, 6 };

		private FP invteral_s1v1 = 0.5;

		private int count_s1v2 = 4019000;

		private int shield_s1v2 = 4019006;

		private int cd_s1v2 = 4019001;

		private List<int> skillId_s2 = new List<int> { 40191, 40191, 40191, 40191, 40191 };

		private int buff_s2 = 4019100;

		private int count_s2 = 4019101;

		private CoroutineNode corAddBuff;

		private int _count_s1v2;

		private FP _cd_s1v2;

		private int _count_s2;

		private int lv_s1;

		private int lv_s2;

		private int stage_s1;

		private PlayerAdventureActor mainCtr => SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;

		protected override void OnDiscEnable()
		{
			base.OnDiscEnable();
			_count_s1v2 = 0;
			_count_s2 = 0;
			_cd_s1v2 = 0;
			(int, int) discInfo = GetDiscInfo(213016, skillId_s1);
			stage_s1 = discInfo.Item1;
			lv_s1 = discInfo.Item2;
			lv_s2 = GetDiscInfo(213016, skillId_s2).Item2;
			if (lv_s1 < 1)
			{
				return;
			}
			StartCoroutine(ref corAddBuff, DoAddBuff());
			for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
			{
				PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i];
				if (playerAdventureActor.actorElementInfo.elementType == GameEnum.elementType.FE)
				{
					playerAdventureActor.buffComponent.AddBuff(buff_s1v1_1[stage_s1], playerAdventureActor);
				}
			}
		}

		protected override void OnDiscDisable()
		{
			base.OnDiscDisable();
			StopCoroutine(ref corAddBuff);
		}

		protected override void OnReceiveDamage(AdventureActorReceiveDamageEvent evt)
		{
			PlayerAdventureActor playerAdventureActor = evt.from as PlayerAdventureActor;
			MonsterAdventureActor monsterAdventureActor = evt.to as MonsterAdventureActor;
			if (playerAdventureActor == null || monsterAdventureActor == null || !evt.isKill || playerAdventureActor.actorElementInfo.elementType != GameEnum.elementType.FE)
			{
				return;
			}
			if (lv_s1 >= 2)
			{
				int num = CommonUtils.GetScriptValue(_actor, count_s1v2).AsInt();
				int num2 = CommonUtils.GetScriptValue(_actor, cd_s1v2).AsInt();
				if (++_count_s1v2 >= num && (playerAdventureActor.LogicTime - _cd_s1v2 >= num2 || _cd_s1v2 <= 0))
				{
					mainCtr.actorShield.AddShield(shield_s1v2, mainCtr);
					_cd_s1v2 = playerAdventureActor.LogicTime;
					_count_s1v2 = 0;
				}
			}
			if (lv_s2 > 0)
			{
				int num3 = CommonUtils.GetScriptValue(_actor, count_s2).AsInt();
				if (++_count_s2 >= num3)
				{
					Singleton<BuffManager>.Instance.AddBufftoGroup(buff_s2, playerAdventureActor);
					_count_s2 = 0;
				}
			}
		}

		private IEnumerator DoAddBuff()
		{
			int buffId = buff_s1v1_2[stage_s1];
			int count = count_s1v1[stage_s1];
			while (true)
			{
				if (ModuleController<AdventureModuleController>.Instance.monsterActors.Count >= count)
				{
					for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
					{
						PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i];
						if (playerAdventureActor.actorElementInfo.elementType == GameEnum.elementType.FE)
						{
							playerAdventureActor.buffComponent.AddBuff(buffId, playerAdventureActor);
						}
					}
				}
				yield return _actor.WaitTime(invteral_s1v1);
			}
		}
	}
	public class Disc_213017 : DiscScriptBase
	{
		private const int discId = 213017;

		private static readonly List<int> skillIds_1 = new List<int> { 3017000, 3017001, 3017002, 3017003, 3017004 };

		private static readonly List<int> buffIdList_1_1 = new List<int> { 4020000, 4020001, 4020002, 4020003, 4020004 };

		private static readonly List<int> hitDamageIdList_1_1 = new List<int> { 4020005, 4020005, 4020005, 4020005, 4020005 };

		private static readonly FP searchRadius_1_1 = 6;

		private const string hittedFx_1_1 = "FX/Perk/fx_perk_base_light_lightning_01";

		private static readonly FP hitRadius_1_3 = 2.5;

		private const string hitFx_1_3 = "FX/Perk/fx_perk_base_light_lightning_01";

		private int _discSkillLevel_1;

		private int _discSkillStage_1;

		private CommomAreaHitConfig _areaHitConfig;

		protected override void OnDiscEnable()
		{
			base.OnDiscEnable();
			(_discSkillStage_1, _discSkillLevel_1) = GetDiscInfo(213017, skillIds_1);
			if (_discSkillLevel_1 <= 0)
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				if (CheckActorIsLE(actorL))
				{
					actorL.buffComponent.AddBuff(buffIdList_1_1[_discSkillStage_1], actorL);
				}
			}
		}

		protected override void OnMainPlayerActorCastSkill(PlayerAdventureActor actor, AdventureActorCastSkillEvent castSkillEvent)
		{
			base.OnMainPlayerActorCastSkill(actor, castSkillEvent);
			if (castSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.A && _discSkillLevel_1 > 0 && CheckActorIsLE(actor))
			{
				Hit();
			}
		}

		protected override void OnPerfectDodge(AdventurePerfectDodgeTrigger evt)
		{
			base.OnPerfectDodge(evt);
			if (_discSkillLevel_1 > 1 && CheckActorIsLE(evt.actor as PlayerAdventureActor))
			{
				Hit();
			}
		}

		private void Hit()
		{
			if (_discSkillLevel_1 <= 0)
			{
				return;
			}
			MonsterAdventureActor target = null;
			ILRuntimeAPI.SearchByRange(_actor, searchRadius_1_1, delegate(List<LogicEntity> result)
			{
				if (result.Count > 0)
				{
					target = result[TSRandom.Range(0, result.Count)] as MonsterAdventureActor;
				}
			}, isConfront: true);
			if (!(target != null))
			{
				return;
			}
			if (_discSkillLevel_1 > 2)
			{
				if (_areaHitConfig == null)
				{
					_areaHitConfig = new CommomAreaHitConfig
					{
						fxAlias = "FX/Perk/fx_perk_base_light_lightning_01",
						hitDamageId = hitDamageIdList_1_1[_discSkillStage_1],
						damageImmuneDuration = -1
					};
				}
				_areaHitConfig.position = target.tsTransform.Position;
				ILRuntimeAPI.CircleAreaHit(_actor, _areaHitConfig, hitRadius_1_3, 0);
			}
			else
			{
				ILRuntimeAPI.HitActor(_actor, (AdventureActor)target, hitDamageIdList_1_1[_discSkillStage_1], "FX/Perk/fx_perk_base_light_lightning_01", (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
			}
		}

		private bool CheckActorIsLE(PlayerAdventureActor actor, bool checkAssit = false, bool isAssist = false)
		{
			if (actor == null)
			{
				return false;
			}
			if (actor.actorElementInfo.elementType == GameEnum.elementType.LE)
			{
				if (checkAssit)
				{
					return actor.isAssist == isAssist;
				}
				return true;
			}
			return false;
		}

		protected override void OnDiscDisable()
		{
			base.OnDiscDisable();
			_discSkillLevel_1 = 0;
			_discSkillStage_1 = 0;
		}
	}
	public class Disc_213018 : DiscScriptBase
	{
		private const int discId = 213018;

		private List<int> skillId_s1 = new List<int> { 3018000, 3018001, 3018002, 3018003, 3018004 };

		private const int num_sc = 4021000;

		private const int power_sc = 4021001;

		private const int cd_sc = 4021002;

		private List<int> skillId_s2 = new List<int> { 40211, 0, 0, 0, 0 };

		private const int onceID = 4021100;

		private const int onceID2 = 4021101;

		private int skill1_level;

		private int skill2_level;

		private FP power_value;

		private FP cd_value;

		private int num_value;

		private int currntNum;

		private readonly Dictionary<long, FP> _personTriggerTimeDic = new Dictionary<long, FP>(20);

		public bool CheckPersonCd(long uid, FP Cd)
		{
			if (Cd <= 0 || Cd == default(FP))
			{
				return true;
			}
			bool result = false;
			if (_personTriggerTimeDic.TryGetValue(uid, out var value))
			{
				if (_actor.LogicTime - value > Cd)
				{
					result = true;
					_personTriggerTimeDic[uid] = _actor.LogicTime;
				}
			}
			else
			{
				_personTriggerTimeDic.Add(uid, _actor.LogicTime);
				result = true;
			}
			return result;
		}

		protected override void OnDiscEnable()
		{
			base.OnDiscEnable();
			skill1_level = GetDiscSkillv(213018, skillId_s1);
			skill2_level = GetDiscSkillv(213018, skillId_s2);
			if (skill1_level > 0)
			{
				currntNum = 0;
				power_value = CommonUtils.GetScriptValue(_actor, 4021001);
				cd_value = CommonUtils.GetScriptValue(_actor, 4021002);
				num_value = CommonUtils.GetScriptValue(_actor, 4021000).AsInt();
			}
		}

		protected override void OnDiscDisable()
		{
			base.OnDiscDisable();
		}

		protected override void OnPlayerActorKill(PlayerAdventureActor actor, MonsterAdventureActor target, AdventureActorDiedEvent diedEvent)
		{
			base.OnPlayerActorKill(actor, target, diedEvent);
			if (skill1_level >= 2 && actor.actorElementInfo.elementType == GameEnum.elementType.WE)
			{
				currntNum++;
				if (currntNum >= num_value && CheckPersonCd(actor.Id, cd_value))
				{
					currntNum = 0;
					actor.playerSkillCd.AddEnergy(power_value);
				}
			}
		}

		protected override void OnBeforePlayerActorHit(PlayerAdventureActor actor, MonsterAdventureActor target, AdventureActorReceiveDamageBeforeHitEvent damageEvent)
		{
			base.OnBeforePlayerActorHit(actor, target, damageEvent);
			if (skill2_level >= 1 && actor.actorElementInfo.elementType == GameEnum.elementType.WE && target != null && target.actorHealthInfo.hpPercentage >= 0.999)
			{
				AdventureActor.AddFromAttr(4021100, actor);
				if (damageEvent.skillSlotType == GameEnum.skillSlotType.D)
				{
					AdventureActor.AddFromAttr(4021101, actor);
				}
			}
		}
	}
