		private bool TriggerMaskInneral(MonsterAdventureActor monster)
		{
			if (CommonUtils.CheckElementMark(CommonDefine.Earth, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				monster.buffComponent.RemoveBuffByTag(CommonDefine.Earth);
				ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_Mask, monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				CommonUtils.TriggerElementMarkEvent(CommonDefine.Earth, GameEnum.AdventureActorElementTriggerType.EarthElementTriggerType, _actor, monster, tipsKey_TriggerMark);
				return true;
			}
			return false;
		}

