			_ = evt.from;
			if (isSelf && GetPerk(perkId_4) && CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_P4) && curCount_4 < count_4)
			{
				curCount_4++;
				ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_4_B, monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
