		public override void OnHitPost(AdventureActorReceiveDamageEvent evt, MonsterAdventureActor monster, bool isSelf)
		{
			base.OnHitPost(evt, monster, isSelf);
			AdventureActor adventureActor = evt.from as AdventureActor;
			if (!isSelf)
			{
				return;
			}
			bool num = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_Normal);
			bool flag = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_MS);
			bool flag2 = CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_Ultra);
			if (num)
			{
				if (GetPerk(perkId_6))
				{
					_actor.buffComponent.AddBuff(buff_6, _actor);
				}
			}
			else if (flag)
			{
				if (GetPerk(perkId_9))
				{
					monster.buffComponent.AddBuff(buff_9, _actor);
				}
			}
			else if (flag2 && GetPerk(perkId_11))
			{
				TriggerMask(adventureActor, monster);
			}
		}

		public override void OnTriggerMasked(AdventureActor actor)
		{
			if (GetPerk(perkId_11))
			{
				actor.buffComponent.AddBuff(buff_11, _actor);
			}
			if (GetPerk(perkId_13) && _actor.logicVariable.GetLogicTagToggle("InCrystal") && extralTime < maxExtend_13)
			{
				extralTime += extendTime_13;
			}
		}

		public override void OnCustomEvent(AdventureActorCustomEvent evt)
		{
			if (evt.eventHashCode == summonEvt)
			{
				long uid = ++uuid;
				dicMonsterGroup.Add(uid, new List<MonsterAdventureActor>());
				dicLinkFx.Add(uid, new List<PlayFX>());
				FP angle = _actor.tsTransform.Forward.GetAngle();
				int num = (GetPerk(perkId_2) ? (summonCount + count_2) : summonCount);
				for (int i = 0; i < num; i++)
				{
					TSVector2 tSVector = TrueSyncExtensions.RandomPointInsideFan(_actor.tsTransform.Position, innerRange_trace, outerRange_trace, angle, angleRange);
					ILRuntimeAPI.SummonMonster(_actor, 0, summonId, tSVector, _actor.tsTransform.Forward, summonCfg, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor entity)
					{
						dicMonsterGroup[uid].Add(entity);
						dicMonsterIdToUid.Add(entity.Id, uid);
					});
				}
				if (GetPerk(perkId_2))
				{
					Link(uid);
					CoroutineNode value = StartCoroutine(HitActor(uid));
					dicCor.Add(uid, value);
				}
			}
			else
			{
				if (evt.eventHashCode != castLaser)
				{
					return;
				}
				string alias = (GetPerk(515901) ? laserPath_1 : laserPath);
				GameObject fXByAlias = _actor.comboGroup.relatedResourceConfig.GetFXByAlias(alias);
				LaserEntity crystal = SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(_actor, fXByAlias, _actor.transform.position, Quaternion.identity) as LaserEntity;
				bool p5 = GetPerk(perkId_5);
				bool p7 = GetPerk(perkId_7);
				if (!(p5 || p7))
				{
					return;
				}
				crystal.SetColliderState(enable: true);
				crystal.OnCollisionEnter = delegate(LogicEntity other)
				{
					if (other is AdventureBulletBase adventureBulletBase && adventureBulletBase.BulletHashCode == bulletTag)
					{
						if (p5)
						{
							adventureBulletBase.AddAdditionalAttr(once_5);
						}
						if (p7)
						{
							FP fP = 0;
							if (dicLeftTime.TryGetValue(crystal.Id, out var value2))
							{
								fP = TSMath.Min(maxTime_7 - value2, addTime_7);
								dicLeftTime[crystal.Id] = value2 + fP;
							}
							else
							{
								fP = addTime_7;
								dicLeftTime.Add(crystal.Id, addTime_7);
							}
							crystal.AddLeftTime(fP);
						}
					}
				};
				crystal.OnBeforeFinish = delegate
				{
					if (p7)
					{
						dicLeftTime.Remove(crystal.Id);
					}
				};
			}
		}

		public override void OnMonsterDied(AdventureMonsterDiedEvent evt)
		{
			if (evt.summonId == _actor.Id && dicMonsterIdToUid.TryGetValue(evt.id, out var value))
			{
				UnLink(value);
				dicMonsterIdToUid.Remove(evt.id);
				if (dicCor.TryGetValue(value, out var value2))
				{
					StopCoroutine(value2);
