			bulletList.Add(adventureBulletBase);
			for (int i = 1; i <= 6; i++)
			{
				FP degrees = startAngle + (i - 1) * 60;
				TSVector2 tSVector2 = TSVector2.Rotate(TSVector2.up, degrees);
				_ = tSVector + tSVector2 * radius;
				adventureBulletBase = ILRuntimeAPI.ShootByDirection(hashRandom.Contains(i) ? bulletKey_B : bulletKey_A, _actor, radius, tSVector2, tSVector, 3);
				adventureBulletBase.weaponTag = $"{i}";
				bulletList.Add(adventureBulletBase);
			}
			while (!castAll)
			{
				yield return null;
			}
			if (!GetPerk(515923))
			{
				yield break;
			}
			IEnumerable<KeyValuePair<int, AreaEffectEntity>> enumerable = dicArea.Where((KeyValuePair<int, AreaEffectEntity> keyValuePair) => hashRandom.Contains(keyValuePair.Key));
			dirtyHash.Clear();
			foreach (KeyValuePair<int, AreaEffectEntity> item5 in enumerable)
			{
				if (item5.Key == 0)
				{
					for (int num = 1; num < 7; num++)
					{
						DoDirty(0, num);
					}
					continue;
				}
				int key = item5.Key;
				int num2 = 6;
				int to = (key - 1 + num2) % num2;
				int to2 = (key + 1) % num2;
				int to3 = 0;
				DoDirty(key, to);
				DoDirty(key, to2);
				DoDirty(key, to3);
			}
		}

		private void DoDirty(int from, int to)
