					entity.ModifyLeftTime(leftTime_24);
				}
				allAreas.Add(entity.Id);
				dicArea.Add(to, entity);
			}, (AdventureActor)null);
			dirtyHash.Add(to);
		}

		private (int first, int second, int third) Random3()
		{
			List<int> list = new List<int> { 0, 1, 2, 3, 4, 5, 6 };
			int index = TSRandom.instance.Next(0, list.Count);
			int num = list[index];
			list.RemoveAt(num);
			int num2 = list[TSRandom.instance.Next(0, list.Count)];
			list.RemoveAt(num2);
			int num3 = list[TSRandom.instance.Next(0, list.Count)];
			list.RemoveAt(num3);
			return (first: num, second: num2, third: num3);
		}

