namespace AIScript.Character._15801
{
	public class ActionScript : ActorActionBase
	{
		private CoroutineNode _transformLogicCor;

		private AimTarget _aimTarget;

		private bool _inTransformState;

		private CoroutineNode _perkLogicCor_P43;

		protected bool InTransformState
		{
			get
			{
				return _inTransformState;
			}
			set
			{
				if (value != _inTransformState)
				{
					_inTransformState = value;
					_actor.logicVariable.ToggleLogicTag("IsTransfromState", _inTransformState);
				}
			}
		}

		public override void OnStart()
		{
			base.OnStart();
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			_aimTarget.Clear();
			InTransformState = false;
		}

		public virtual void OnUpdate()
		{
		}

		public override void OnStop()
		{
			base.OnStop();
			_aimTarget.Cancel();
			_aimTarget.Clear();
			InTransformState = false;
			if (_transformLogicCor != null)
			{
				_actor.StopLogicCoroutine(_transformLogicCor);
			}
			_transformLogicCor = null;
			if (_perkLogicCor_P43 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P43);
			}
			_perkLogicCor_P43 = null;
		}

		protected bool BeginTransfrom(System.Action finishCallBack = null)
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate(bool success)
			{
				TransfromFinish(success);
				finishCallBack?.Invoke();
			}))
			{
				_actor.DisableCastDodge();
				_actor.EnableForbiddenRush();
				_actor.DisableCastUltra();
				_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, 15810001);
				_playerSkillCd.BindSkillIdToButton(ActionKey.B, 15834001);
				InTransformState = true;
				return true;
			}
			return false;
		}

		private void TransfromFinish(bool success)
		{
			if (success)
			{
				OnTransfromFinish();
				if (_transformLogicCor != null)
				{
					_actor.StopLogicCoroutine(_transformLogicCor);
				}
				_transformLogicCor = _actor.StartLogicCoroutine(TransformLogic());
			}
		}

		protected virtual void OnTransfromFinish()
		{
		}

		private bool BeginReturn()
		{
			if (ILRuntimeAPI.CreateSkill(15834002, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, ReturnFinish))
			{
				_actor.EnableCastDodge();
				_actor.DisableForbiddenRush();
				_actor.EnableCastUltra();
				_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, 15810001);
				_playerSkillCd.BindSkillIdToButton(ActionKey.B, GetDefaultSkillId());
				return true;
			}
			return false;
		}

		protected virtual int GetDefaultSkillId()
		{
			return 0;
		}

		private void ReturnFinish(bool success)
		{
			if (success)
			{
				InTransformState = false;
				OnReturnFinish();
			}
		}

		protected virtual void OnReturnFinish()
		{
		}

		private IEnumerator TransformLogic()
		{
			FP duratrionTime = Config.durationTime_Transform;
			_actor.actorShield.AddShield(15840001, _actor);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515843, out var _))
			{
				if (_perkLogicCor_P43 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P43);
				}
				_perkLogicCor_P43 = _actor.StartLogicCoroutine(PerkLogic_P43(), runImmediately: true);
			}
			while (duratrionTime > 0)
			{
				OnTransformUpdate();
				duratrionTime -= _actor.LogicDeltaTime;
				yield return null;
			}
			while (!BeginReturn())
			{
				yield return null;
			}
			_actor.actorShield.RemoveShieldByShieldID(15840001);
			_transformLogicCor = null;
		}

		private IEnumerator PerkLogic_P43()
		{
			FP interval = Config.interval_AddBuff_P43;
			while (_transformLogicCor != null && !_transformLogicCor.finished)
			{
				interval -= _actor.LogicDeltaTime;
				if (interval <= 0)
				{
					foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
					{
						actorL.buffComponent.AddBuff(15843011, _actor);
					}
					interval += Config.interval_AddBuff_P43;
				}
				yield return null;
			}
			foreach (PlayerAdventureActor actorL2 in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL2.buffComponent.RemoveBuffByBuffId(15843011);
			}
			_perkLogicCor_P43 = null;
		}

		protected virtual void OnTransformUpdate()
		{
			_actor.attackTarget = GetTransformAttackTarget();
			if (_actor.attackTarget == null || base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack)
			{
				if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget.Cancel();
				}
				return;
			}
			FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
			if (fP < CommonUtils.GetAimRange(_actor))
			{
				if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget)
				{
					_aimTarget.Aim(_actor, (AdventureActor)_actor.attackTarget, default(TSVector2), playStartAnim: true);
				}
				if (fP <= CommonUtils.GetAttackRange(_actor) && _actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
				}
			}
			else if (_actor.aimMode != AdventureActor.AimMode.Forward)
			{
				_aimTarget.Cancel();
			}
		}

		protected virtual LogicEntity GetTransformAttackTarget()
		{
			return _actor.attackTarget;
		}
	}
	public class ParallelScript : ParallelBase
	{
		protected List<int> _damageTag_TriggerFireMark;

		protected List<int> _damageTag_AddFireMark;

		private CommomAreaHitConfig _areaHitConfig_FireMark;

		private HitBox.HitBoxFeatureData _featureData_FireMark;

		public override void OnEnable()
		{
			base.OnEnable();
			if (_damageTag_AddFireMark == null)
			{
				_damageTag_AddFireMark = new List<int>();
			}
			else
			{
				_damageTag_AddFireMark.Clear();
			}
			_damageTag_AddFireMark.Add(Config.damageTag_AddFireMark);
			if (_damageTag_TriggerFireMark == null)
			{
				_damageTag_TriggerFireMark = new List<int>();
			}
			else
			{
				_damageTag_TriggerFireMark.Clear();
			}
			_damageTag_TriggerFireMark.Add(Config.damageTag_TriggerFireMark);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnCastSkillEnd(IEvent evt)
		{
			if (evt is AdventureActorCastSkillEndEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEndEvent && sender == _actor)
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515842, out var _) && adventureActorCastSkillEndEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B)
				{
					_actor.buffComponent.RemoveBuffByBuffId(15842011);
				}
				OnSelfCastSkillEnd(adventureActorCastSkillEndEvent);
			}
		}

		protected virtual void OnSelfCastSkillEnd(AdventureActorCastSkillEndEvent skillEndEvent)
		{
		}

		private void OnReceiveAttack(IEvent evt)
		{
			if (evt is AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent && adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor)
			{
				OnSelfAttacked(adventureActorReceiveAttackEvent);
			}
		}

		protected virtual void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent && adventureActorReceiveDamageBeforeHitEvent.from == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor)
			{
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			if (!(evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent) || !(adventureActorReceiveDamageEvent.from == _actor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monsterAdventureActor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515842, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_P42))
			{
				_actor.buffComponent.AddBuff(15842011, _actor);
			}
			OnSelfDamaged(adventureActorReceiveDamageEvent);
			List<int> damageTag_AddFireMark = _damageTag_AddFireMark;
			if (damageTag_AddFireMark != null && damageTag_AddFireMark.Count > 0)
			{
				foreach (int item in _damageTag_AddFireMark)
				{
					if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, item))
					{
						monsterAdventureActor.buffComponent.AddBuff(1011, _actor);
						break;
					}
				}
			}
			if (CheckCanTriggerFireMark(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag))
			{
				TriggerFireMark(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag);
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerFireMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (_damageTag_TriggerFireMark == null || _damageTag_TriggerFireMark.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Fire, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				for (int i = 0; i < _damageTag_TriggerFireMark.Count; i++)
				{
					int hitTag = _damageTag_TriggerFireMark[i];
					if (CommonUtils.CheckHitByTag(hitDamageTag, hitTag))
					{
						return true;
					}
				}
			}
			return false;
		}

		private void TriggerFireMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (_featureData_FireMark == null)
			{
				_featureData_FireMark = new HitBox.HitBoxFeatureData
				{
					StiffDuration = Config.stiffDuration_FireMark,
					hitStrenth = Config.hitStrenth_FireMark
				};
			}
			if (_areaHitConfig_FireMark == null)
			{
				_areaHitConfig_FireMark = new CommomAreaHitConfig
				{
					fxAlias = "fx_common_base_FireTag_Trigger_2",
					hittedEffectAlias = "",
					hitDamageId = 158000001,
					hitFlags = HitBox.FeatureFlag.Stiff,
					hitFeatureData = _featureData_FireMark,
					damageImmuneDuration = -1
				};
			}
			_areaHitConfig_FireMark.position = monster.tsTransform.Position;
			ILRuntimeAPI.CircleAreaHit(_actor, _areaHitConfig_FireMark, Config.hitRadius_FireMark, 0);
			monster.buffComponent.RemoveBuffByTag(CommonDefine.Fire);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.Fire, GameEnum.AdventureActorElementTriggerType.FireElementTriggerType2, _actor, monster, "FireMark_Trigger_Effect_01");
			OnTriggerFireMark(hitDamageTag);
		}

		protected virtual void OnTriggerFireMark(IList<int> hitDamageTag)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastSkillEnd);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			ComboInputBuffer.ActionKey[] comboKeys_Dodge = Config.comboKeys_Dodge;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboKeys_Dodge, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, Config.duration_Dodge, Config.distance_Dodge, null, comboWithAttack: true);
		}

		public void OnUpdate()
		{
			if (!(_actor.attackTarget == null) && (!((PlayerAdventureActor)_actor).dodgeButtonHold || _actor.forbiddenRush))
			{
				SkillPhaseConfig currentPhaseBreakConfig = _skill.GetCurrentPhaseBreakConfig();
				if (currentPhaseBreakConfig != null && (currentPhaseBreakConfig.skillPhaseFeatureFlag & SkillPhaseFeatureFlag.Normal) != SkillPhaseFeatureFlag.None && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
				{
					base.comboAttack.InterruptAttack();
				}
			}
		}

		private void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private int _stage;

		private string _comboTag;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_stage = _actor.logicVariable.GetLogicTagValue("NormalAttackStage").AsInt();
			_comboTag = ((_stage < Config.comboTagList_NormalAttack.Count) ? Config.comboTagList_NormalAttack[_stage] : null);
		}

		public void OnStart()
		{
			if (string.IsNullOrEmpty(_comboTag))
			{
				NovaLogger.Error($"该普攻段数未配置,普攻段数:{_stage}");
				OnFinish();
				return;
			}
			string comboTag = _comboTag;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt);
		}

		private void OnAnticipationEnd()
		{
			int num = _stage + 1;
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", (num < Config.comboTagList_NormalAttack.Count) ? num : 0);
		}

		public void OnUpdate()
		{
			LockDirection();
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_stage = 0;
			_comboTag = null;
		}
	}
