	public class ActionScript_Summoned : AIBase
	{
		protected PlayerAdventureActor _summoner;

		protected bool _enableTrace;

		private TraceTarget _traceTarget;

		private FP _checkTraceInterval;

		private bool _forceTrace;

		public virtual void OnStart()
		{
			MonsterSummonInfo logicComponent = _actor.GetLogicComponent<MonsterSummonInfo>();
			if (logicComponent != null)
			{
				_summoner = logicComponent.SummonActor as PlayerAdventureActor;
			}
			_enableTrace = false;
			_forceTrace = false;
			_checkTraceInterval = 0;
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		protected bool HavePersonalPerk(int perkId, out int perkLevel)
		{
			perkLevel = 0;
			if (_summoner == null)
			{
				return false;
			}
			return CommonUtils.HavePersonalPerk(_summoner.dataID, perkId, out perkLevel);
		}

		public virtual void OnUpdate()
		{
			_actor.attackTarget = GetAttackTarget();
			if (_enableTrace)
			{
				if (_checkTraceInterval > 0)
				{
					_checkTraceInterval -= _actor.LogicDeltaTime;
				}
				else if (CheckTrace())
				{
					_checkTraceInterval = Config.interval_CheckTrace_Summoned;
				}
			}
			if (CanNormalAttack() && NormalAttack())
			{
				_traceTarget?.CancelTrace();
			}
		}

		private LogicEntity GetAttackTarget()
		{
			PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
			if (playerAdventureActor != null && playerAdventureActor.attackTarget != null)
			{
				return playerAdventureActor.attackTarget;
			}
			return _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: false);
		}

		private bool CheckTrace()
		{
			if (_forceTrace)
			{
				return false;
			}
			if (_traceTarget == null)
			{
				_traceTarget = new TraceTarget();
			}
			if (_actor.actorSkillManage.HaveRunningSkill())
			{
				_traceTarget.CancelTrace();
				return false;
			}
			(LogicEntity target, FP stopDistance, bool forceTrace) traceInfo = GetTraceInfo();
			LogicEntity item = traceInfo.target;
			FP item2 = traceInfo.stopDistance;
			bool item3 = traceInfo.forceTrace;
			_forceTrace = item3;
			if (item != null)
			{
				_traceTarget.BeginTrace(_actor, item, item2, -1, -1, null, null, NavAgentTypeNames.NavigationUpdateQualityLevel.MedQualityNavigationUpdate, AdventureActor.MovementMode.Run, delegate
				{
					_forceTrace = false;
				});
				return true;
			}
			return false;
		}

		private (LogicEntity target, FP stopDistance, bool forceTrace) GetTraceInfo()
		{
			FP fP = _actor.DistanceWithRadius(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor);
			if (fP > Config.distance_ForceTrace_Summoned)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config.distance_StopTrace_ForPlayer_Summoned, forceTrace: true);
			}
			if (_actor.attackTarget != null)
			{
				if (_actor.DistanceWithRadius(_actor.attackTarget) > _actor.actorSearchTargetInfo.attackRange)
				{
					return (target: _actor.attackTarget, stopDistance: _actor.actorSearchTargetInfo.attackRange, forceTrace: false);
				}
			}
			else if (fP > Config.distance_StopTrace_ForPlayer_Summoned)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config.distance_StopTrace_ForPlayer_Summoned, forceTrace: false);
			}
			return (target: null, stopDistance: 0, forceTrace: false);
		}

		protected virtual bool CanNormalAttack()
		{
			if (_forceTrace)
			{
				return false;
			}
			if (_actor.attackTarget == null)
			{
				return false;
			}
			return _actor.DistanceWithRadius(_actor.attackTarget) <= GetAttackRange();
		}

		protected virtual FP GetAttackRange()
		{
			return 0;
		}

		protected virtual bool NormalAttack()
		{
			return false;
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && adventureActorCustomEvent.eventHashCode == Config_MainControl.eventHashCode_SummonedCoordinateAttack)
			{
				OnReceiveCoordinateAttackEvent();
			}
		}

		protected virtual void OnReceiveCoordinateAttackEvent()
		{
		}

		public virtual void OnStop()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			_enableTrace = false;
			_forceTrace = false;
			_checkTraceInterval = 0;
			_traceTarget?.CancelTrace();
			_traceTarget?.Clear();
		}
	}
	public class ParallelScript_Summoned : AIBase
	{
		protected PlayerAdventureActor _summoner;

		public virtual void OnEnable()
		{
			MonsterSummonInfo logicComponent = _actor.GetLogicComponent<MonsterSummonInfo>();
			if (logicComponent != null)
			{
				_summoner = logicComponent.SummonActor as PlayerAdventureActor;
			}
			_actor.EnableUnparalleled();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnBattleReady(IEvent _)
		{
			OnBattleReady();
		}

		protected virtual void OnBattleReady()
		{
		}

		private void OnGetBuff(IEvent evt)
		{
			if (evt is AdventureActorGetBuff { sender: PlayerAdventureActor sender } adventureActorGetBuff && sender == _summoner)
			{
				OnSummonerGetBuff(adventureActorGetBuff);
			}
		}

		protected virtual void OnSummonerGetBuff(AdventureActorGetBuff getBuffEvent)
		{
		}

		private void OnRemoveBuff(IEvent evt)
		{
			if (evt is AdventureActorRemoveBuff { sender: PlayerAdventureActor sender } adventureActorRemoveBuff && sender == _summoner)
			{
				OnSummonerRemoveBuff(adventureActorRemoveBuff);
			}
		}

		protected virtual void OnSummonerRemoveBuff(AdventureActorRemoveBuff removeBuffEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent && adventureActorReceiveDamageBeforeHitEvent.from == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor)
			{
				OnSelfBeforeHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnSelfBeforeHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent && adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor)
			{
				OnSelfDamaged(adventureActorReceiveDamageEvent);
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		protected void DestroySelf()
		{
			if (_actor.state == ActorState.Spawn)
			{
				_actor.StartLogicCoroutine(WaitForDestroySelf());
			}
			else
			{
				_actor.DestroySelf();
			}
		}

		private IEnumerator WaitForDestroySelf()
		{
			while (_actor.state == ActorState.Spawn)
			{
				yield return null;
			}
			_actor.DestroySelf();
		}

		protected bool HavePersonalPerk(int perkId, out int perkLevel)
		{
			perkLevel = 0;
			if (_summoner == null)
			{
				return false;
			}
			return CommonUtils.HavePersonalPerk(_summoner.dataID, perkId, out perkLevel);
		}

		public virtual void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			_actor.DisableUnparalleled();
			AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
			adventureActorCustomEvent.sender = _summoner;
			adventureActorCustomEvent.eventHashCode = Config.eventHashCode_SummonedLifeCycleFinish;
			AdventureActorCustomEvent adventureActorCustomEvent2 = adventureActorCustomEvent;
			if (adventureActorCustomEvent2.tsVector2ParamList == null)
			{
				adventureActorCustomEvent2.tsVector2ParamList = new List<TSVector2>();
			}
			adventureActorCustomEvent.tsVector2ParamList.Clear();
			adventureActorCustomEvent.tsVector2ParamList.Add(_actor.tsTransform.Position);
			adventureActorCustomEvent.tsVector2ParamList.Add(_actor.tsTransform.Forward);
			adventureActorCustomEvent.tsVector2ParamList.Add(new TSVector2(_actor.dataID, _actor.Id));
			_summoner.DispatchEvent(adventureActorCustomEvent);
		}
	}
