	public class ActionScript_MainControl : ActionScript
	{
		private FP _holdTime_NormalAttackStage;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515813, out var _))
			{
				_playerSkillCd.SetSkillTotalSection(ActionKey.A, _playerSkillCd.GetSkillCD(ActionKey.A).originalTotalSectionAmount + 1);
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.A);
			}
			_holdTime_NormalAttackStage = 0;
		}

		protected override int GetDefaultSkillId()
		{
			return 15831000;
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		protected override void OnButtonDPress()
		{
			BeginTransfrom();
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			if (!base.InTransformState)
			{
				_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
				if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
				{
					ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
				}
				if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
				{
					_holdTime_NormalAttackStage = 0;
					return;
				}
				if (_holdTime_NormalAttackStage < Config.holdTime_NormalAttackStage)
				{
					_holdTime_NormalAttackStage += _actor.LogicDeltaTime;
					return;
				}
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
				_holdTime_NormalAttackStage = 0;
			}
		}

		protected override LogicEntity GetTransformAttackTarget()
		{
			return _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private SummonedController_MainControl _summonedController;

		public override void OnEnable()
		{
			base.OnEnable();
			_summonedController = new SummonedController_MainControl(_actor as PlayerAdventureActor);
			_summonedController.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515812, out var _))
			{
				_actor.buffComponent.AddBuff(15812011, _actor);
				_damageTag_TriggerFireMark.Add(Config_MainControl.damageTag_AddTriggerMark_P12);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515809, out var _) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P9))
			{
				AdventureActor.AddFromAttr(0, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515804, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P4) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(15804011))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_15801_Main_Skill_P04_Boom", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515808, out perkLevel) && damageEvent.isCrit && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P8))
			{
				_actor.buffComponent.AddBuff(15808011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515810, out perkLevel) && damageEvent.isKill && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P10))
			{
				_actor.buffComponent.AddBuff(15810011, _actor);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_summonedController.OnDisable();
			_summonedController = null;
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private CommomAreaHitConfig _hitConfig;

		private FP _hitAngle;

		private FP _hitRadius;

		private FP _hitInnerRadius;

		private bool _addMoraleSuccess;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (_hitConfig == null)
			{
				_hitConfig = new CommomAreaHitConfig
				{
					hitFeatureData = new HitBox.HitBoxFeatureData
					{
						KnockOutForce = Config_MainControl.airBorneForce_Skill,
						StiffDuration = Config_MainControl.stiffDuration_Skill,
						hitStrenth = Config_MainControl.hitStrenth_Skill
					},
					hittedEffectAlias = "fx_15801_hit_Lash"
				};
			}
			_addMoraleSuccess = false;
			DefaultLookAt();
		}

		public void OnStart()
		{
			string text = "158_Main_Skill";
			_hitConfig.hitDamageId = 158310001;
			_hitAngle = Config_MainControl.hitAngle_Skill;
			_hitRadius = Config_MainControl.hitRadius_Skill;
			_hitInnerRadius = Config_MainControl.hitInnerRadius_Skill;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515803, out var perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515809, out perkLevel))
				{
					text = "158_Main_Skill_P03P09";
					_hitConfig.hitDamageId = 158503001;
					_hitAngle = Config_MainControl.hitAngle_Skill_P3_P9;
					_hitRadius = Config_MainControl.hitRadius_Skill_P3_P9;
					_hitInnerRadius = Config_MainControl.hitInnerRadius_Skill_P3_P9;
				}
				else
				{
					text = "158_Main_Skill_P03";
					_hitConfig.hitDamageId = 158503001;
					_hitAngle = Config_MainControl.hitAngle_Skill_P3;
					_hitRadius = Config_MainControl.hitRadius_Skill_P3;
					_hitInnerRadius = Config_MainControl.hitInnerRadius_Skill_P3;
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 515809, out perkLevel))
			{
				text = "158_Main_Skill_P09";
				_hitConfig.hitDamageId = 158310001;
				_hitAngle = Config_MainControl.hitAngle_Skill_P9;
				_hitRadius = Config_MainControl.hitRadius_Skill_P9;
				_hitInnerRadius = Config_MainControl.hitInnerRadius_Skill_P9;
			}
			string actionTag = text;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "158_Main_Skill_Hurt"))
			{
				Hit();
			}
			else if (string.Equals(eventName, "158_Main_Skill_Hurt_Fly"))
			{
				Hit(withAirBorne: true);
			}
		}

		private void Hit(bool withAirBorne = false)
		{
			_hitConfig.hitFlags = (withAirBorne ? (HitBox.FeatureFlag.AirBorne | HitBox.FeatureFlag.Stiff) : HitBox.FeatureFlag.Stiff);
			_hitConfig.position = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_MainControl.hitOffset_Skill;
			_hitConfig.direction = _actor.tsTransform.Forward;
			ILRuntimeAPI.FanAreaHit(_actor, _hitConfig, _hitAngle, _hitRadius, _hitInnerRadius);
			if (_addMoraleSuccess)
			{
				return;
			}
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			foreach (LogicEntity item in ILRuntimeAPI.GetTargetsFromShape(new DeterministicShape
			{
				shapeType = DeterministicShape.ShapeType.Fan,
				innerRadius = _hitInnerRadius,
				radius = _hitRadius,
				angle = _hitAngle,
				position = _hitConfig.position,
				rotation = _hitConfig.direction.GetAngle()
			}))
			{
				if (!ActorHelper.IsPlayerSummoned(item, ref playerAdventureActor) || !(playerAdventureActor == _actor))
				{
					continue;
				}
				MonsterAdventureActor monsterAdventureActor = item as MonsterAdventureActor;
				if ((monsterAdventureActor.dataID == 15831011 || monsterAdventureActor.dataID == 15831021) && monsterAdventureActor.state != ActorState.Death)
				{
					for (int i = 0; i < 1; i++)
					{
						_actor.buffComponent.AddBuff(15800002, _actor);
					}
					_addMoraleSuccess = true;
					break;
				}
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_addMoraleSuccess = false;
		}
	}
	public class ParallelScript_Summoned_MainControl : ParallelScript_Summoned
	{
		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
		}

		private void OnReceiveAttack(IEvent evt)
		{
			if (evt is AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent && adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor monsterAdventureActor && HavePersonalPerk(515804, out var _))
			{
				monsterAdventureActor.buffComponent.AddBuff(15804011, _summoner);
			}
		}

		protected override void OnSelfBeforeHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnSelfBeforeHit(beforeHitEvent);
			if (HavePersonalPerk(515807, out var _) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P7))
			{
				int num = _actor.logicVariable.GetLogicTagValue("ToySummonedCount").AsInt();
				if (_summoner.logicVariable.GetLogicTagToggle("IsTransfromState"))
				{
					num++;
				}
				if (num > 0)
				{
					AdventureActor.AddFromAttr(15807011, _summoner, num);
				}
			}
		}

		protected void AddMorale(int count)
		{
			if (!(_summoner == null) && count > 0 && _actor.state != ActorState.Death)
			{
				_summoner.buffComponent.AddBuffNum(15800002, count, _summoner);
			}
		}

		protected void RemoveMorale(int count)
		{
			if (!(_summoner == null) && count > 0 && _actor.state != ActorState.Death)
			{
				_summoner.buffComponent.RemoveBuffByBuffId(15800002, count);
			}
		}

		protected virtual bool HaveMoraleLogic()
		{
			return false;
		}

		protected override void OnSummonerGetBuff(AdventureActorGetBuff getBuffEvent)
		{
			base.OnSummonerGetBuff(getBuffEvent);
			if (getBuffEvent.eventInfo.buffId == 15800002 && HaveMoraleLogic())
			{
				_actor.buffComponent.AddBuff(15800001, _actor);
				OnMoraleChange(isAdd: true);
			}
		}

		protected override void OnSummonerRemoveBuff(AdventureActorRemoveBuff removeBuffEvent)
		{
			base.OnSummonerRemoveBuff(removeBuffEvent);
			if (removeBuffEvent.eventInfo.buffId == 15800002 && HaveMoraleLogic())
			{
				_actor.buffComponent.RemoveBuffByBuffId(15800001, 1);
				OnMoraleChange();
			}
		}

		protected virtual void OnMoraleChange(bool isAdd = false)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
		}
	}
	public class ActionScript_Casemate_MainControl : ActionScript_Summoned
	{
		private FP _normalAttackInterval;

		public override void OnStart()
		{
			base.OnStart();
			_enableTrace = false;
			_normalAttackInterval = 0;
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			if (_normalAttackInterval > 0)
			{
				_normalAttackInterval -= _actor.LogicDeltaTime;
			}
		}

		protected override FP GetAttackRange()
		{
			return Config_MainControl.attackRange_Casemate;
		}

		protected override bool CanNormalAttack()
		{
			if (_normalAttackInterval > 0)
			{
				return false;
			}
			return base.CanNormalAttack();
		}

		protected override bool NormalAttack()
		{
			if (ILRuntimeAPI.CreateSkill(15831041, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false))
			{
				_normalAttackInterval = Config_MainControl.useInterval_NormalAttack_Casemate;
				return true;
			}
			return false;
		}

		public override void OnStop()
		{
			base.OnStop();
			_enableTrace = false;
			_normalAttackInterval = 0;
		}
	}
