	public class SummonedController_MainControl
	{
		private PlayerAdventureActor _actor;

		private MonsterAdventureActor _soldier;

		private MonsterAdventureActor _warrior;

		private MonsterAdventureActor _queen;

		private FP _lastTriggerTime_P2;

		private FP _lastTriggerTime_P11;

		public SummonedController_MainControl(PlayerAdventureActor actor)
		{
			_actor = actor;
		}

		public void OnEnable()
		{
			Init();
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDied);
		}

		private void Init()
		{
			bool.TryParse(_actor.GetLocalData("SummonedIsWarrior"), out var result);
			if (result)
			{
				SummonWarrior(_actor.tsTransform.Position, _actor.tsTransform.Forward);
			}
			else
			{
				SummoneSoldier(_actor.tsTransform.Position, _actor.tsTransform.Forward);
			}
		}

		private void SummoneSoldier(TSVector2 position, TSVector2 direction, bool isReturn = false)
		{
			if (!(_soldier != null))
			{
				_actor.logicVariable.ToggleLogicTag("SoldierReturn", isReturn);
				TSVector2 tSVector = ((position != _actor.tsTransform.Position) ? position : ILRuntimeAPI.GetRandomPointInShape(_actor, new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Circle,
					innerRadius = _actor.GetRadius(),
					radius = Config_MainControl.defaultSummonRadius_Soldier,
					position = _actor.tsTransform.Position
				}));
				ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15831011, tSVector, direction, Config_MainControl.summonCfg_Soldier, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
				{
					_soldier = monster;
				});
				UpdateToyCount(1);
			}
		}

		private void SummonWarrior(TSVector2 position, TSVector2 direction, bool isPromotion = false)
		{
			if (!(_warrior != null))
			{
				TSVector2 tSVector = ((position != _actor.tsTransform.Position) ? position : ILRuntimeAPI.GetRandomPointInShape(_actor, new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Circle,
					innerRadius = _actor.GetRadius(),
					radius = Config_MainControl.defaultSummonRadius_Warrior,
					position = _actor.tsTransform.Position
				}));
				ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15831021, tSVector, direction, Config_MainControl.summonCfg_Warrior, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
				{
					_warrior = monster;
				});
				UpdateToyCount(1);
			}
		}

		private void SummonQueen()
		{
			if (!(_queen != null))
			{
				TSVector2 randomPointInShape = ILRuntimeAPI.GetRandomPointInShape(_actor, new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Circle,
					innerRadius = _actor.GetRadius(),
					radius = Config_MainControl.summonRadius_Queen,
					position = _actor.tsTransform.Position
				});
				ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15831031, randomPointInShape, _actor.tsTransform.Forward, Config_MainControl.summonCfg_Queen, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
				{
					_queen = monster;
				});
				UpdateToyCount(1);
			}
		}

		private void SummonCasemate()
		{
			TSVector2 randomPointInShape = ILRuntimeAPI.GetRandomPointInShape(_actor, new DeterministicShape
			{
				shapeType = DeterministicShape.ShapeType.Circle,
				innerRadius = _actor.GetRadius(),
				radius = Config_MainControl.summonRadius_Casemate,
				position = _actor.tsTransform.Position
			});
			ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15831041, randomPointInShape, _actor.tsTransform.Forward, Config_MainControl.summonCfg_Casemate, (string)null, (Action<MonsterAdventureActor>)null);
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (!(evt is AdventureActorCustomEvent adventureActorCustomEvent))
			{
				return;
			}
			if (adventureActorCustomEvent.eventHashCode == Config.eventHashCode_SummonedLifeCycleFinish)
			{
				TSVector2 position = _actor.tsTransform.Position;
				TSVector2 direction = _actor.tsTransform.Forward;
				int num = 0;
				if (adventureActorCustomEvent.tsVector2ParamList.Count >= 3)
				{
					position = adventureActorCustomEvent.tsVector2ParamList[0];
					direction = adventureActorCustomEvent.tsVector2ParamList[1];
					num = adventureActorCustomEvent.tsVector2ParamList[2].x.AsInt();
				}
				switch (num)
				{
				case 15831011:
					SummonWarrior(position, direction, isPromotion: true);
					break;
				case 15831021:
					SummoneSoldier(position, direction, isReturn: true);
					break;
				}
			}
			else if (adventureActorCustomEvent.eventHashCode == Config_MainControl.eventHashCode_QueenBeginNormalAttack)
			{
				if (_soldier != null)
				{
					SendCoordinateAttackSignal(_soldier);
				}
				else if (_warrior != null)
				{
					SendCoordinateAttackSignal(_warrior);
				}
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent && adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor && CommonUtils.HavePersonalPerk(_actor.dataID, 515811, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P11) && (_lastTriggerTime_P11 <= 0 || _actor.LogicTime - _lastTriggerTime_P11 > CommonUtils.GetScriptValue(_actor, 15811012)) && TSRandom.Range(0f, 100f) <= CommonUtils.GetScriptValue(_actor, 15811011))
			{
				SummonCasemate();
				_lastTriggerTime_P11 = _actor.LogicTime;
			}
		}

		private void OnCastSkill(IEvent evt)
		{
			if (!(evt is AdventureActorCastSkillEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEvent) || !(sender == _actor) || adventureActorCastSkillEvent.skillEventInfo.skillSlotType != GameEnum.skillSlotType.B)
			{
				return;
			}
			if (_soldier != null)
			{
				SendCoordinateAttackSignal(_soldier);
			}
			else if (_warrior != null)
			{
				SendCoordinateAttackSignal(_warrior);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515802, out var _))
			{
				if (_queen != null)
				{
					SendCoordinateAttackSignal(_queen);
				}
				else if (_lastTriggerTime_P2 <= 0 || _actor.LogicTime - _lastTriggerTime_P2 > CommonUtils.GetScriptValue(_actor, 15802011))
				{
					SummonQueen();
					_actor.buffComponent.AddBuffNum(15800002, 2, _actor);
					_lastTriggerTime_P2 = _actor.LogicTime;
				}
			}
		}

		private void SendCoordinateAttackSignal(MonsterAdventureActor summoned)
		{
			if (!(summoned == null) && summoned.state == ActorState.Action)
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = Config_MainControl.eventHashCode_SummonedCoordinateAttack;
				summoned.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void OnMonsterDied(IEvent evt)
		{
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			if (evt is AdventureMonsterDiedEvent { sender: MonsterAdventureActor sender } && ActorHelper.IsPlayerSummoned((LogicEntity)sender, ref playerAdventureActor) && playerAdventureActor == _actor)
			{
				if (sender == _soldier)
				{
					_soldier = null;
					UpdateToyCount(-1);
				}
				else if (sender == _warrior)
				{
					_warrior = null;
					UpdateToyCount(-1);
				}
				else if (sender == _queen)
				{
					_queen = null;
					UpdateToyCount(-1);
				}
			}
		}

		private void UpdateToyCount(int changeCount)
		{
			if (changeCount != 0)
			{
				int num = _actor.logicVariable.GetLogicTagValue("ToySummonedCount").AsInt();
				num += changeCount;
				num = ((num >= 0) ? num : 0);
				_actor.logicVariable.SetLogicTagValue("ToySummonedCount", num);
			}
		}

		public void OnDisable()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
