	public class ActionScript_Support : ActionScript
	{
		private TraceTarget _traceTarget;

		private FP _checkTraceInterval;

		private bool _forceTrace;

		public override void OnStart()
		{
			base.OnStart();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515831, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(15831011, _actor);
				}
			}
			_forceTrace = false;
		}

		protected override int GetDefaultSkillId()
		{
			return 15832000;
		}

		protected override void OnCastSkill()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnSkillFinish);
		}

		private void OnSkillFinish(bool _)
		{
			if (!(_actor.logicVariable.GetLogicTagValue("RemainingSkillShootTimes") <= 0))
			{
				ILRuntimeAPI.SummonMonster(_actor, 0, 15832031, _actor.tsTransform.Position, _actor.tsTransform.Forward, Config_Support.summonCfg_Casemate, (string)null, (Action<MonsterAdventureActor>)null);
			}
		}

		protected override void OnCastUltimate()
		{
			if (BeginTransfrom(delegate
			{
				((PlayerAdventureActor)_actor).isAssistAIFinish = true;
			}) && CommonUtils.HavePersonalPerk(_actor.dataID, 515832, out var _))
			{
				_actor.buffComponent.AddBuff(15832011, _actor);
			}
		}

		protected override void OnTransfromFinish()
		{
			base.OnTransfromFinish();
			((PlayerAdventureActor)_actor).isResidentAssist = true;
		}

		protected override void OnTransformUpdate()
		{
			base.OnTransformUpdate();
			if (_checkTraceInterval > 0)
			{
				_checkTraceInterval -= _actor.LogicDeltaTime;
			}
			else if (CheckTrace())
			{
				_checkTraceInterval = Config_Support.interval_CheckTrace_Transfrom;
			}
		}

		protected override LogicEntity GetTransformAttackTarget()
		{
			return CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
		}

		private bool CheckTrace()
		{
			if (_forceTrace)
			{
				return false;
			}
			if (_traceTarget == null)
			{
				_traceTarget = new TraceTarget();
			}
			if (_actor.actorSkillManage.HaveRunningSkill())
			{
				_traceTarget.CancelTrace();
				return false;
			}
			(LogicEntity target, FP stopDistance, bool forceTrace) traceInfo = GetTraceInfo();
			LogicEntity item = traceInfo.target;
			FP item2 = traceInfo.stopDistance;
			bool item3 = traceInfo.forceTrace;
			_forceTrace = item3;
			if (item != null)
			{
				_traceTarget.BeginTrace(_actor, item, item2, -1, -1, null, null, NavAgentTypeNames.NavigationUpdateQualityLevel.MedQualityNavigationUpdate, AdventureActor.MovementMode.Run, OnTraceFinish);
				return true;
			}
			return false;
		}

		private (LogicEntity target, FP stopDistance, bool forceTrace) GetTraceInfo()
		{
			FP fP = _actor.DistanceWithRadius(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor);
			if (fP > Config_Support.distance_ForceTrace_Transfrom)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config_Support.distance_StopTrace_ForPlayer_Transfrom, forceTrace: true);
			}
			if (_actor.attackTarget != null)
			{
				if (_actor.DistanceWithRadius(_actor.attackTarget) > CommonUtils.GetAttackRange(_actor))
				{
					return (target: _actor.attackTarget, stopDistance: CommonUtils.GetAttackRange(_actor), forceTrace: false);
				}
			}
			else if (fP > Config_Support.distance_StopTrace_ForPlayer_Transfrom)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config_Support.distance_StopTrace_ForPlayer_Transfrom, forceTrace: false);
			}
			return (target: null, stopDistance: 0, forceTrace: false);
		}

		private void OnTraceFinish()
		{
			_forceTrace = false;
		}

		protected override void OnReturnFinish()
		{
			base.OnReturnFinish();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515832, out var _))
			{
				_actor.buffComponent.RemoveBuffByBuffId(15832011);
			}
			((PlayerAdventureActor)_actor).isResidentAssist = false;
		}

		public override void OnStop()
		{
			base.OnStop();
			_traceTarget?.CancelTrace();
			_traceTarget?.Clear();
			_forceTrace = false;
		}
	}
	public class ParallelScript_Support : ParallelScript
	{
		private SummonedController_Support _summonedController;

		public override void OnEnable()
		{
			base.OnEnable();
			_summonedController = new SummonedController_Support(_actor as PlayerAdventureActor);
			_summonedController.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515832, out var perkLevel))
			{
				_damageTag_AddFireMark.Add(Config_Support.damageTag_AddFireMark_P32);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515833, out perkLevel))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.FE)
					{
						actorL.buffComponent.AddBuff(15833011, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
		}

		private void OnBulletFinish(IEvent evt)
		{
			if (!(evt is AdventureBulletFinishEvent adventureBulletFinishEvent) || !(adventureBulletFinishEvent.owner == _actor))
			{
				return;
			}
			AdventureBulletBase adventureBulletBase = adventureBulletFinishEvent.sender as AdventureBulletBase;
			if (!adventureBulletBase.CheckBulletTag(Config_Support.bulletTag_Skill) || adventureBulletFinishEvent.finishReason == BulletFinishReason.Timeout)
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515821, out var perkLevel))
			{
				string text = "AreaEffect_15801_Support_Skill_Cannon_Boom_P21_Fire";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515822, out perkLevel))
				{
					text = "AreaEffect_15801_Support_Skill_Cannon_Boom_P21P22_BigFire";
				}
				ILRuntimeAPI.PlayAreaEffect(_actor, text, adventureBulletBase.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			_summonedController.OnSkillBulletFinish(adventureBulletFinishEvent);
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor target = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515825, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P25))
			{
				AdventureActor.AddFromAttr(15825001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515827, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P27) && !CommonUtils.CheckElementMark(CommonDefine.Fire, target))
			{
				AdventureActor.AddFromAttr(15827001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515822, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P22))
			{
				monsterAdventureActor.buffComponent.AddBuff(15822011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515826, out perkLevel) && damageEvent.isCrit && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P26))
			{
				_actor.buffComponent.AddBuff(15826011, _actor);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			_summonedController.OnDisable();
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		private int _totalShootTimes;

		private int _shootTimes;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_totalShootTimes = 4;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515825, out var _))
			{
				_totalShootTimes += 2;
			}
			_shootTimes = 0;
		}

		public void OnStart()
		{
			Attack();
		}

		private void Attack()
		{
			DefaultLookAt();
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("158_Support_Skill", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
		}

		private void OnActivationEnd()
		{
			TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_Support.shootPositionOffset_Skill.x + _actor.tsTransform.Forward * Config_Support.shootPositionOffset_Skill.z;
			FP y = Config_Support.shootPositionOffset_Skill.y;
			string text = "Bullet_15801_Summon_Attack_Cannon_Support_Shoot";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515822, out var _))
			{
				text = "Bullet_15801_Summon_Attack_Cannon_Support_Shoot_P22_Big";
			}
			string bulletAlias = text;
			AdventureActor actor = _actor;
			LogicEntity attackTarget = _actor.attackTarget;
			ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), position, y, default(TSVector2), attackTarget, AimType.Target, BulletDirectionType.BulletToTarget);
			_shootTimes++;
		}

		private void OnFinish()
		{
			if (_shootTimes < _totalShootTimes)
			{
				Attack();
			}
			else
			{
				_skill.Clear();
			}
		}

		private void OnInterrupt()
		{
			_skill.Clear();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			if (_shootTimes < _totalShootTimes)
			{
				_actor.logicVariable.SetLogicTagValue("RemainingSkillShootTimes", _totalShootTimes - _shootTimes);
			}
			else
			{
				_actor.logicVariable.SetLogicTagValue("RemainingSkillShootTimes", 0);
			}
			_shootTimes = 0;
		}
	}
	public class ActionScript_Summoned_Support : ActionScript_Summoned
	{
		private bool _canUseSkill;

		private FP _useSkillInterval;

		private long _areaEffectId_P28;

		private CoroutineNode _perkLogic_P29;

		public override void OnStart()
		{
			base.OnStart();
			if (HavePersonalPerk(515824, out var perkLevel))
			{
				_canUseSkill = true;
			}
			if (HavePersonalPerk(515828, out perkLevel))
			{
				_areaEffectId_P28 = ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_15801_Support_Skill_P28_Summon_BuffEachOther", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			if (HavePersonalPerk(515829, out perkLevel))
			{
				_perkLogic_P29 = _actor.StartLogicCoroutine(PerkLogic_P29());
			}
			_useSkillInterval = GetUseSkillInterval();
		}

		private IEnumerator PerkLogic_P29()
		{
			FP interval = Config_Support.interval_AddBuff_P29;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent.AddBuff(15829011, _actor);
					int buffNumByID = _actor.buffComponent.GetBuffNumByID(15829011);
					if (Config_Support.modelScaleDic_P29.TryGetValue(buffNumByID, out var value))
					{
						FP fP = 1 + value * 0.01f;
						FP originModelScale = _actor.actorScaleInfo.originModelScale;
						_actor.actorScaleInfo.modelScale = originModelScale * fP;
					}
					interval += Config_Support.interval_AddBuff_P29;
				}
				yield return null;
			}
		}

		protected virtual FP GetUseSkillInterval()
		{
			return 0;
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			if (_canUseSkill)
			{
				if (_useSkillInterval > 0)
				{
					_useSkillInterval -= _actor.LogicDeltaTime;
				}
				else if (CastSkill())
				{
					_useSkillInterval += GetUseSkillInterval();
				}
			}
		}

		private bool CastSkill()
		{
			if (_actor.attackTarget == null)
			{
				return false;
			}
			if (_actor.movementState != ActorState.StandBy)
			{
				return false;
			}
			if (_actor.DistanceWithRadius(_actor.attackTarget) > CommonUtils.GetAttackRange(_actor))
			{
				return false;
			}
			if (ILRuntimeAPI.CreateSkill(GetSkillId(), _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false))
			{
				return true;
			}
			return false;
		}

		protected virtual int GetSkillId()
		{
			return 0;
		}

		public override void OnStop()
		{
			base.OnStop();
			_canUseSkill = false;
			if (_areaEffectId_P28 > 0)
			{
				ILRuntimeAPI.StopAreaEffect(_areaEffectId_P28);
			}
			_areaEffectId_P28 = 0L;
			if (_perkLogic_P29 != null)
			{
				_actor.StopLogicCoroutine(_perkLogic_P29);
			}
			_perkLogic_P29 = null;
		}
	}
	public class ParallelScript_Summoned_Support : ParallelScript_Summoned
	{
