	public class SummonedController_Support
	{
		private PlayerAdventureActor _actor;

		private List<MonsterAdventureActor> _soldierList;

		private MonsterAdventureActor _warrior;

		private long _lastSoldierId_P23;

		public SummonedController_Support(PlayerAdventureActor actor)
		{
			_actor = actor;
		}

		public void OnEnable()
		{
			_lastSoldierId_P23 = 0L;
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDied);
		}

		public void OnSkillBulletFinish(AdventureBulletFinishEvent bulletFinishEvent)
		{
			AdventureBulletBase adventureBulletBase = bulletFinishEvent.sender as AdventureBulletBase;
			if (adventureBulletBase.CheckBulletTag(Config_Support.bulletTag_Skill))
			{
				SummoneSoldier(adventureBulletBase.tsTransform.Position);
			}
		}

		private void SummoneSoldier(TSVector2 position)
		{
			if (!_actor.QueryPositionWalkable(position))
			{
				_actor.QueryClosestPositionWalkable(position, out position);
			}
			TSVector2 tSVector = _actor.tsTransform.Forward;
			if (_actor.attackTarget != null)
			{
				tSVector = (_actor.attackTarget.tsTransform.Position - position).normalized;
			}
			Config_Support.summonCfg_Soldier.leftTime = Config_Support.leftTime_Soldier;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515829, out var _))
			{
				Config_Support.summonCfg_Soldier.leftTime = Config_Support.leftTime_Soldier_P29;
			}
			ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15832011, position, tSVector, Config_Support.summonCfg_Soldier, (string)null, (Action<MonsterAdventureActor>)OnSummoneSoldierFinish);
		}

		private void OnSummoneSoldierFinish(MonsterAdventureActor soldier)
		{
			if (_soldierList == null)
			{
				_soldierList = new List<MonsterAdventureActor>();
			}
			_soldierList.Add(soldier);
			if (_soldierList.Count < 4)
			{
				return;
			}
			_soldierList.Sort((MonsterAdventureActor x, MonsterAdventureActor y) => x.monsterSummonInfo.leftTime.CompareTo(y.monsterSummonInfo.leftTime));
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515823, out var _))
			{
				MonsterAdventureActor monsterAdventureActor = _soldierList.Last();
				monsterAdventureActor.logicVariable.ToggleLogicTag("IsAbsorbDeath_Soldier", value: true);
				_lastSoldierId_P23 = monsterAdventureActor.Id;
				{
					foreach (MonsterAdventureActor soldier2 in _soldierList)
					{
						AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
						adventureActorCustomEvent.sender = soldier2;
						adventureActorCustomEvent.eventHashCode = Config_Support.eventHashCode_SummonedDestroySelf;
						soldier2.DispatchEvent(adventureActorCustomEvent);
					}
					return;
				}
			}
			MonsterAdventureActor monsterAdventureActor2 = _soldierList.First();
			AdventureActorCustomEvent adventureActorCustomEvent2 = AdventureActorCustomEvent.Generate();
			adventureActorCustomEvent2.sender = monsterAdventureActor2;
			adventureActorCustomEvent2.eventHashCode = Config_Support.eventHashCode_SummonedDestroySelf;
			monsterAdventureActor2.DispatchEvent(adventureActorCustomEvent2);
		}

		private void SummoneWarrior(TSVector2 position)
		{
			TSVector2 tSVector = _actor.tsTransform.Forward;
			if (_actor.attackTarget != null)
			{
				tSVector = (_actor.attackTarget.tsTransform.Position - position).normalized;
			}
			Config_Support.summonCfg_Warrior.leftTime = Config_Support.leftTime_Warrior;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515829, out var _))
			{
				Config_Support.summonCfg_Warrior.leftTime = Config_Support.leftTime_Warrior_P29;
			}
			ILRuntimeAPI.SummonMonster((AdventureActor)_actor, 0, 15832021, position, tSVector, Config_Support.summonCfg_Warrior, (string)null, (Action<MonsterAdventureActor>)OnSummoneWarriorFinish);
		}

		private void OnSummoneWarriorFinish(MonsterAdventureActor warrior)
		{
			if (_warrior != null)
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = _warrior;
				adventureActorCustomEvent.eventHashCode = Config_Support.eventHashCode_SummonedDestroySelf;
				_warrior.DispatchEvent(adventureActorCustomEvent);
			}
			_warrior = warrior;
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && adventureActorCustomEvent.eventHashCode == Config.eventHashCode_SummonedLifeCycleFinish)
			{
				TSVector2 position = _actor.tsTransform.Position;
				int num = 0;
				long num2 = 0L;
				if (adventureActorCustomEvent.tsVector2ParamList.Count >= 3)
				{
					position = adventureActorCustomEvent.tsVector2ParamList[0];
					num = adventureActorCustomEvent.tsVector2ParamList[2].x.AsInt();
					num2 = adventureActorCustomEvent.tsVector2ParamList[2].y.AsLong();
				}
				if (num == 15832011 && CommonUtils.HavePersonalPerk(_actor.dataID, 515823, out var _) && _lastSoldierId_P23 > 0 && _lastSoldierId_P23 == num2)
				{
					SummoneWarrior(position);
					_lastSoldierId_P23 = 0L;
				}
			}
		}

		private void OnMonsterDied(IEvent evt)
		{
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			if (evt is AdventureMonsterDiedEvent { sender: MonsterAdventureActor sender } && ActorHelper.IsPlayerSummoned((LogicEntity)sender, ref playerAdventureActor) && playerAdventureActor == _actor)
			{
				if (sender.dataID == 15832011)
				{
					_soldierList.Remove(sender);
				}
				else if (sender.dataID == 15832021)
				{
					_warrior = null;
				}
			}
		}

		public void OnDisable()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDied);
			_lastSoldierId_P23 = 0L;
			_actor = null;
		}
	}
	public class ActionScript_Warrior_Support : ActionScript_Summoned_Support
	{
		private CoroutineNode _perkLogic_P23;

		public override void OnStart()
		{
			base.OnStart();
			if (HavePersonalPerk(515829, out var _))
			{
				_perkLogic_P23 = _actor.StartLogicCoroutine(PerkLogic_P23());
			}
		}

		private IEnumerator PerkLogic_P23()
		{
			FP interval = Config_Support.interval_AddBuff_P23;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent.AddBuff(15823011, _actor);
					interval += Config_Support.interval_AddBuff_P23;
				}
				yield return null;
			}
		}

		protected override FP GetAttackRange()
		{
			return Config_Support.attackRange_Warrior;
		}

		protected override FP GetUseSkillInterval()
		{
			return Config_Support.useInterval_NormalAttack_Warrior;
		}

		protected override int GetSkillId()
		{
			return 15896003;
		}

		public override void OnStop()
		{
			base.OnStop();
			if (_perkLogic_P23 != null)
			{
				_actor.StopLogicCoroutine(_perkLogic_P23);
			}
			_perkLogic_P23 = null;
		}
	}
