				if (currentPhaseBreakConfig != null && (currentPhaseBreakConfig.skillPhaseFeatureFlag & SkillPhaseFeatureFlag.Normal) != SkillPhaseFeatureFlag.None && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
				{
