	public class ActionScript_MainControl : ActionScript
	{
		private AimTarget _aimTarget;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			else
			{
				_aimTarget.Clear();
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515604, out var _))
			{
				_actor.shootBehaviour.reloadAnimClipIndex = 0;
			}
			else
			{
				_actor.shootBehaviour.reloadAnimClipIndex = -1;
			}
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.End);
		}

		protected override void OnButtonDPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		public override void OnUpdate()
		{
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Ultimate))
			{
				return;
			}
			if (_actor.attackTarget == null || _actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill2 | SkillPhaseFeatureFlag.Dodge) || base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack)
			{
				if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget.Cancel();
				}
				return;
			}
			FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
			if (fP < CommonUtils.GetAimRange(_actor))
			{
				if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget)
				{
					_aimTarget.Aim(_actor, (AdventureActor)_actor.attackTarget, default(TSVector2), playStartAnim: true);
				}
				if (fP <= CommonUtils.GetAttackRange(_actor) && _actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && _actor.ammoInfo.ammoCount > 0)
				{
					ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
				}
			}
			else if (_actor.aimMode != AdventureActor.AimMode.Forward)
			{
				_aimTarget.Cancel();
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_aimTarget.Cancel();
			_aimTarget.Clear();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private int _summonedCount;

		private bool _isSkillInCD;

		private FP _lastTriggerTime_P8;

		public override void OnEnable()
		{
			base.OnEnable();
			_summonedCount = 0;
			_isSkillInCD = false;
			int num = ((PlayerAdventureActor)_actor).playerSkillCd.GetSkillCD(ActionKey.A).originalTotalSectionAmount;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515611, out var perkLevel))
			{
				num++;
			}
			((PlayerAdventureActor)_actor).playerSkillCd.SetSkillTotalSection(ActionKey.A, num);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515612, out perkLevel))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.SE)
					{
						actorL.buffComponent.AddBuff(15612011, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_NODAMAGE", OnReceiveNoDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_BEGIN_RELOAD", OnBeginReload);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_END_RELOAD", OnEndReload);
		}

		public override void OnUpdate()
		{
			UpdateSummonedCount(_actor.logicVariable.GetLogicTagValue("SummonedCount").AsInt());
			UpdateSkillCDState(((PlayerAdventureActor)_actor).playerSkillCd.GetSkillCD(ActionKey.B).currentResumeTime > 0);
		}

		private void UpdateSummonedCount(int summonedCount)
		{
			if (_summonedCount == summonedCount)
			{
				return;
			}
			_summonedCount = summonedCount;
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 515606, out var _))
			{
				return;
			}
			if (_summonedCount > 0)
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (!actorL.buffComponent.CheckBuffByBuffID(15606011))
					{
						actorL.buffComponent.AddBuff(15606011, _actor);
					}
				}
				return;
			}
			foreach (PlayerAdventureActor actorL2 in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL2.buffComponent.RemoveBuffByBuffId(15606011);
			}
		}

		private void UpdateSkillCDState(bool isSkillInCD)
		{
			if (_isSkillInCD == isSkillInCD)
			{
				return;
			}
			_isSkillInCD = isSkillInCD;
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 515610, out var _))
			{
				return;
			}
			if (_isSkillInCD)
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(15610011, _actor);
				}
				return;
			}
			foreach (PlayerAdventureActor actorL2 in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL2.buffComponent.RemoveBuffByBuffId(15610011);
			}
		}

		private void OnReceiveNoDamage(IEvent evt)
		{
			AdventureActorNoDamageEvent adventureActorNoDamageEvent = evt as AdventureActorNoDamageEvent;
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			if (ActorHelper.IsPlayerSummoned(adventureActorNoDamageEvent.from, ref playerAdventureActor) && playerAdventureActor == _actor && Config_MainControl.hitDamageIdMapping.TryGetValue(adventureActorNoDamageEvent.hitDamageConfigId, out var value))
			{
				AdventureActor adventureActor = adventureActorNoDamageEvent.to as AdventureActor;
				AdventureActor actor = _actor;
				int num = value;
				int uniqueAttackId = adventureActorNoDamageEvent.uniqueAttackId;
				ILRuntimeAPI.HitActor(actor, adventureActor, num, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.None, uniqueAttackId, (GameObject)null);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515605, out var _) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P5))
			{
				AdventureActor.AddFromAttr(15605001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515601, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P1))
			{
				monsterAdventureActor.buffComponent.AddBuff(15601011, _actor);
			}
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 515608, out perkLevel))
			{
				return;
			}
			FP scriptValue = CommonUtils.GetScriptValue(_actor, 15608012);
			if ((_lastTriggerTime_P8 <= 0 || _actor.LogicTime - _lastTriggerTime_P8 > scriptValue) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P8))
			{
				FP scriptValue2 = CommonUtils.GetScriptValue(_actor, 15608011);
				if (TSRandom.Range(0f, 100f) <= scriptValue2)
				{
					TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_MainControl.shootOffset_P8;
					ILRuntimeAPI.ShootByDirection("Bullet_156_P8_Egg", _actor, default(FP), _actor.tsTransform.Forward, position, Config_MainControl.shootPositionY_P8);
					_lastTriggerTime_P8 = _actor.LogicTime;
				}
			}
		}

		private void OnBeginReload(IEvent evt)
		{
			if (!(evt is AdventureActorBeginReload adventureActorBeginReload) || !(adventureActorBeginReload.sender as AdventureActor == _actor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515607, out var perkLevel))
			{
				_actor.buffComponent.AddBuff(15607011, _actor);
			}
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 515609, out perkLevel))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				if (actorL.isAssist)
				{
					actorL.buffComponent.AddBuff(15609011, _actor);
				}
			}
		}

		private void OnEndReload(IEvent evt)
		{
			if (evt is AdventureActorEndReload adventureActorEndReload && adventureActorEndReload.sender as AdventureActor == _actor && CommonUtils.HavePersonalPerk(_actor.dataID, 515604, out var _))
			{
				ILRuntimeAPI.CreateSkill(15631004, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_NODAMAGE", OnReceiveNoDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_BEGIN_RELOAD", OnBeginReload);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_END_RELOAD", OnEndReload);
			_summonedCount = 0;
			_isSkillInCD = false;
		}
	}
	public class SkillScript_AfterReload_MainControl : SkillAdvancedBase
	{
		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("P4_Reload", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.AddBuff(15604011, _actor);
			}
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515613, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(15613011, _actor);
				}
			}
			DefaultLookAt();
		}

		public void OnStart()
		{
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("Skill_Mian_CallPenguinDoll", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (!string.Equals(eventName, "CallPenguinDoll"))
			{
				return;
			}
			TSVector2 result = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_MainControl.summonOffset_Skill;
			if (!_actor.QueryPositionWalkable(result))
			{
				_actor.QueryClosestPositionWalkable(result, out result);
			}
			ILRuntimeAPI.SummonMonster(_actor, 0, 15600011, result, _actor.tsTransform.Forward, Config_MainControl.summonCfg_Summon, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515601, out var _))
				{
					monster.actorScaleInfo.modelScale = Config_MainControl.modelScale_Summoned_P1;
					monster.buffComponent.AddBuff(15601021, _actor);
				}
				else
				{
					monster.actorScaleInfo.modelScale = monster.actorScaleInfo.originModelScale;
				}
			});
		}

