	public class ActionScript_Support : ActionScript
	{
		private int _nextRaffleTimes;

		private CoroutineNode _raffleIntervalCor;

		private bool _teleportForBattleReady;

		private List<Config_Support.RaffleCombinationType> _raffleResultList;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
		}

		public override void OnStart()
		{
			base.OnStart();
			int num = _actor.logicVariable.GetLogicTagValue("InitNextRaffleTimes").AsInt();
			if (num > 0)
			{
				_actor.logicVariable.SetLogicTagValue("InitNextRaffleTimes", 0);
				_nextRaffleTimes = num;
				BeginRaffle(strollFirst: true);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515631, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.SE)
					{
						actorL.buffComponent.AddBuff(15631011, _actor);
					}
				}
			}
			_teleportForBattleReady = false;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
		}

		protected override void OnCastSkill()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnSkillFinish))
			{
				ForceStopRaffleLogic();
				_nextRaffleTimes = 1;
			}
		}

		protected override void OnCastUltimate()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnUlrtaSkillFinish))
			{
				_actor.StandBy((System.Action)null);
				if (_raffleIntervalCor != null)
				{
					_actor.StopLogicCoroutine(_raffleIntervalCor);
				}
				_raffleIntervalCor = null;
				_actor.buffComponent.RemoveBuffByBuffId(15691014);
			}
		}

		private void OnSkillFinish(bool success)
		{
			((PlayerAdventureActor)_actor).isAssistAIFinish = true;
			if (success)
			{
				BeginRaffle();
			}
		}

		private void OnUlrtaSkillFinish(bool success)
		{
			((PlayerAdventureActor)_actor).isAssistAIFinish = true;
			if (_nextRaffleTimes > 0)
			{
				BeginRaffle(strollFirst: true);
			}
		}

		private void BeginRaffle(bool strollFirst = false)
		{
			((PlayerAdventureActor)_actor).isResidentAssist = true;
			_actor.buffComponent.AddBuff(15691014, _actor);
			if (strollFirst)
			{
				_raffleIntervalCor = _actor.StartLogicCoroutine(RaffleInterval());
			}
			else
			{
				Raffle(_nextRaffleTimes == 5);
			}
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			_actor.attackTarget = CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
		}

		private void Raffle(bool isLastRaffle)
		{
			if (!((PlayerAdventureActor)_actor).isAssistAIFinish)
			{
				return;
			}
			_nextRaffleTimes++;
			List<FP> list = Config_Support.raffleRateList;
			Config_Support.RaffleCombinationType raffleCombinationType = (Config_Support.RaffleCombinationType)258;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515622, out var perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515623, out perkLevel))
				{
					list = Config_Support.raffleRateList_P22_P23;
					raffleCombinationType = (Config_Support.RaffleCombinationType)258;
				}
				else
				{
					list = Config_Support.raffleRateList_P22;
					raffleCombinationType = Config_Support.RaffleCombinationType.AAA;
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 515623, out perkLevel))
			{
				list = Config_Support.raffleRateList_P23;
				raffleCombinationType = Config_Support.RaffleCombinationType.BBB;
			}
			FP maxValue = 0;
			foreach (FP item2 in list)
			{
				maxValue += item2;
			}
			FP fP = TSRandom.Range(0, maxValue);
			int num = 0;
			FP fP2 = 0;
			for (int i = 0; i < list.Count; i++)
			{
				fP2 += list[i];
				if (fP <= fP2)
				{
					num = i;
					break;
				}
			}
			int index = TSMath.Clamp(num, 0, Config_Support.raffleResultGroupList.Count - 1).AsInt();
			List<Config_Support.RaffleCombinationType> list2 = Config_Support.raffleResultGroupList[index];
			Config_Support.RaffleCombinationType item = list2[TSRandom.Range(0, list2.Count)];
			if (_raffleResultList == null)
			{
				_raffleResultList = new List<Config_Support.RaffleCombinationType>();
			}
			Config_Support.RaffleCombinationType raffleCombinationType2 = Config_Support.RaffleCombinationType.None;
			if (_raffleResultList.Count > 0)
			{
				raffleCombinationType2 = _raffleResultList.Last();
			}
			if (isLastRaffle)
			{
				bool flag = true;
				for (int j = 0; j < _raffleResultList.Count; j++)
				{
					if ((_raffleResultList[j] & raffleCombinationType) != Config_Support.RaffleCombinationType.None)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					if (raffleCombinationType == (Config_Support.RaffleCombinationType)258)
					{
						raffleCombinationType = ((TSRandom.Range(0f, 100f) > 50) ? Config_Support.RaffleCombinationType.AAA : Config_Support.RaffleCombinationType.BBB);
					}
					_raffleResultList.Add(raffleCombinationType);
				}
				else
				{
					_raffleResultList.Add(item);
				}
			}
			else
			{
				_raffleResultList.Add(item);
			}
			Config_Support.RaffleCombinationType raffleCombinationType3 = _raffleResultList.Last();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515632, out perkLevel))
			{
				_actor.buffComponent.AddBuff(15632011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515633, out perkLevel) && (raffleCombinationType2 == Config_Support.RaffleCombinationType.AAA || raffleCombinationType2 == Config_Support.RaffleCombinationType.BBB) && (raffleCombinationType3 == Config_Support.RaffleCombinationType.AAA || raffleCombinationType3 == Config_Support.RaffleCombinationType.BBB))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(15633011, _actor);
				}
			}
			_actor.logicVariable.SetLogicTagValue("RaffleCombinationType", (int)raffleCombinationType3);
			ILRuntimeAPI.CreateSkill(15632001, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnRaffleSkillFinish);
		}

		private void OnRaffleSkillFinish(bool success)
		{
			if (!((PlayerAdventureActor)_actor).isAssistAIFinish)
			{
				return;
			}
			if (success)
			{
				Config_Support.RaffleCombinationType raffleCombinationType = _raffleResultList.Last();
				if (Config_Support.raffleResultSkillIdDic.TryGetValue(raffleCombinationType, out var skillId) && skillId > 0)
				{
					int perkLevel;
					switch (raffleCombinationType)
					{
					case Config_Support.RaffleCombinationType.AAA:
					case Config_Support.RaffleCombinationType.AAB:
					case Config_Support.RaffleCombinationType.ABA:
					case Config_Support.RaffleCombinationType.BAA:
					{
						int buffID2 = 15691011;
						if (CommonUtils.HavePersonalPerk(_actor.dataID, 515621, out perkLevel))
						{
							buffID2 = 15621011;
						}
						foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
						{
							actorL.buffComponent.AddBuff(buffID2, _actor);
						}
						break;
					}
					case Config_Support.RaffleCombinationType.ABB:
					case Config_Support.RaffleCombinationType.BAB:
					case Config_Support.RaffleCombinationType.BBA:
					case Config_Support.RaffleCombinationType.BBB:
					{
						int buffID = 15691012;
						if (CommonUtils.HavePersonalPerk(_actor.dataID, 515624, out perkLevel))
						{
							buffID = 15624011;
						}
						foreach (PlayerAdventureActor actorL2 in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
						{
							actorL2.buffComponent.AddBuff(buffID, _actor);
						}
						break;
					}
					}
					ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
					{
						if (CommonUtils.HavePersonalPerk(_actor.dataID, 515626, out var perkLevel2) && skillId == 15632003)
						{
							ILRuntimeAPI.CreateSkill(15632005, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
							{
								OnRaffleFinish(_: true);
							});
							(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as AdventureActor).buffComponent.AddBuff(15626011, _actor);
						}
						else if (CommonUtils.HavePersonalPerk(_actor.dataID, 515629, out perkLevel2) && skillId == 15632002)
						{
							ILRuntimeAPI.CreateSkill(15632004, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
							{
								OnRaffleFinish(_: true);
							});
							(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as AdventureActor).buffComponent.AddBuff(15629011, _actor);
						}
						else
						{
							OnRaffleFinish(_: true);
						}
					});
					return;
				}
			}
			OnRaffleFinish(_: false);
		}

		private void OnRaffleFinish(bool _)
		{
			if (((PlayerAdventureActor)_actor).isAssistAIFinish)
			{
				if (_nextRaffleTimes <= 5)
				{
					_raffleIntervalCor = _actor.StartLogicCoroutine(RaffleInterval());
					return;
				}
				_nextRaffleTimes = 0;
				_actor.buffComponent.RemoveBuffByBuffId(15691014);
				((PlayerAdventureActor)_actor).isResidentAssist = false;
			}
		}

		private IEnumerator RaffleInterval()
		{
			FP interval = Config_Support.interval_UseRaffleSkill;
			FP idleTime = 0;
			while (interval > 0)
			{
				if (_teleportForBattleReady)
				{
					Teleport();
					_teleportForBattleReady = false;
				}
				else
				{
					LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
					FP fP = _actor.DistanceWithRadius(activedPlayerActor);
					if (fP > Config_Support.maxDistanceWithPlayer_Stroll)
					{
						Teleport();
					}
					else if (_actor.movementState == ActorState.StandBy)
					{
						if (fP < Config_Support.randomRadius_Stroll && idleTime <= 0)
						{
							idleTime = Config_Support.idleTime_BetweenStroll;
						}
						idleTime -= _actor.LogicDeltaTime;
						if (idleTime <= 0)
						{
							BeginStroll();
						}
					}
				}
				interval -= _actor.LogicDeltaTime;
				yield return null;
			}
			_actor.StandBy((System.Action)null);
			Raffle(_nextRaffleTimes == 5);
		}

		private void Teleport()
		{
			_actor.StandBy((System.Action)null);
			TSVector2 randomTargetPosition = GetRandomTargetPosition();
			_actor.Teleport(randomTargetPosition);
			BeginStroll();
		}

		private void BeginStroll()
		{
			TSVector2 randomTargetPosition = GetRandomTargetPosition();
			_actor.MoveTo(randomTargetPosition, 0.1, enableNavigation: true);
		}

		private TSVector2 GetRandomTargetPosition()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			TSVector2 result = ILRuntimeAPI.GetRandomPointInShape(_actor, new DeterministicShape
			{
				shapeType = DeterministicShape.ShapeType.Circle,
				position = activedPlayerActor.tsTransform.Position,
				innerRadius = activedPlayerActor.GetRadius(),
				radius = Config_Support.randomRadius_Stroll
			});
			if (!_actor.QueryPositionWalkable(result))
			{
				_actor.QueryClosestPositionWalkable(result, out result);
			}
			return result;
		}

		private void ForceStopRaffleLogic()
		{
			_actor.StandBy((System.Action)null);
			if (_raffleIntervalCor != null)
			{
				_actor.StopLogicCoroutine(_raffleIntervalCor);
			}
			_raffleIntervalCor = null;
			_teleportForBattleReady = false;
			_raffleResultList?.Clear();
			_nextRaffleTimes = 0;
			_actor.buffComponent.RemoveBuffByBuffId(15691014);
			((PlayerAdventureActor)_actor).isResidentAssist = false;
		}

		private void OnBattleReady(IEvent _)
		{
			_teleportForBattleReady = true;
		}

		public override void OnStop()
		{
			base.OnStop();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515631, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.SE)
					{
						actorL.buffComponent.RemoveBuffByBuffId(15631011);
					}
				}
			}
			((PlayerAdventureActor)_actor).SetLocalData("NextRaffleTimes", _nextRaffleTimes.ToString());
			ForceStopRaffleLogic();
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ForceStopRaffleLogic();
		}
	}
	public class ParallelScript_Support : ParallelScript
	{
		private int _triggerTimes_P25;

		private CoroutineNode _triggerCDCor_P25;

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("PLAYER_SPAWN_COMPLETE", OnPlayerSpawnComplete);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
		}

		private void OnPlayerSpawnComplete(IEvent _)
		{
			_actor.logicVariable.SetLogicTagValue("InitNextRaffleTimes", 0);
			string localData = ((PlayerAdventureActor)_actor).GetLocalData("NextRaffleTimes");
			if (!string.IsNullOrEmpty(localData) && int.TryParse(localData, out var result) && result > 0 && result <= 5)
			{
				_actor.logicVariable.SetLogicTagValue("InitNextRaffleTimes", result);
				SceneSingleton<AdventurePlayerController>.Instance.ActiveActor(_actor as PlayerAdventureActor);
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515625, out var _) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P25))
			{
				if (_triggerTimes_P25 < CommonUtils.GetScriptValue(_actor, 15625012))
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_156_P25_ShotBoom", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
					_triggerTimes_P25++;
				}
				if (_triggerCDCor_P25 == null)
				{
					_triggerCDCor_P25 = _actor.StartLogicCoroutine(PerkLogic_P25());
				}
			}
		}

		private IEnumerator PerkLogic_P25()
		{
			FP scriptValue = CommonUtils.GetScriptValue(_actor, 15625011);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(scriptValue));
			_triggerTimes_P25 = 0;
			_triggerCDCor_P25 = null;
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515630, out var _) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P30))
			{
				AdventureActor.AddFromAttr(15630001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515628, out var _) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P28))
			{
				monsterAdventureActor.buffComponent.AddBuff(15628011, _actor);
			}
		}

		private void OnBulletFinish(IEvent evt)
		{
			if (!(evt is AdventureBulletFinishEvent adventureBulletFinishEvent) || !(adventureBulletFinishEvent.owner == _actor))
			{
				return;
			}
			AdventureBulletBase adventureBulletBase = adventureBulletFinishEvent.sender as AdventureBulletBase;
			if (adventureBulletFinishEvent.bulletHashCode == Config_Support.bulletTag_Sculpture)
			{
				string text = "AreaEffect_156_Sup_Skill_PenguinStatue";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515621, out var perkLevel))
				{
					text = ((!CommonUtils.HavePersonalPerk(_actor.dataID, 515622, out perkLevel)) ? "AreaEffect_156_Sup_Skill_PenguinStatue_P21" : "AreaEffect_156_Sup_Skill_PenguinStatue_P22P21");
				}
				else if (CommonUtils.HavePersonalPerk(_actor.dataID, 515622, out perkLevel))
				{
					text = "AreaEffect_156_Sup_Skill_PenguinStatue_P22";
				}
				ILRuntimeAPI.PlayAreaEffect(_actor, text, adventureBulletFinishEvent.bulletPosition, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			else if (adventureBulletFinishEvent.bulletHashCode == Config_Support.bulletTag_HeartArrow)
			{
				_actor.StartLogicCoroutine(HeartArrowLogic(adventureBulletBase.target, adventureBulletBase.tsTransform.Position));
			}
		}

		private IEnumerator HeartArrowLogic(LogicEntity target, TSVector2 position)
		{
			if (target == null)
			{
				NovaLogger.Error("爱心箭追踪子弹不存在目标!");
				yield break;
			}
			PlayFX playFX = new PlayFX();
			int perkLevel;
			if (_actor.IsFriendlyWith(target))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515623, out perkLevel))
				{
					List<LogicEntity> list = ILRuntimeAPI.SearchByRangeAndPosition(_actor, position, Config_Support.searchRadius_P23, null, isConfront: true);
					if (list != null && list.Count > 0)
					{
						AdventureActor adventureActor = target as AdventureActor;
						LogicEntity logicEntity = ((!(adventureActor.attackTarget != null) || !list.Contains(adventureActor.attackTarget)) ? ILRuntimeAPI.GetTargetNearOrFar(adventureActor, iNear: true, list) : adventureActor.attackTarget);
						TSVector2 normalized = (logicEntity.tsTransform.Position - position).normalized;
						AdventureActor actor = _actor;
						FP shootPositionY_HeartArrow = Config_Support.shootPositionY_HeartArrow;
						LogicEntity target2 = logicEntity;
						ILRuntimeAPI.ShootByDirection("Bullet_156_Sup_Skill_HeartArrow", actor, default(FP), normalized, position, shootPositionY_HeartArrow, default(TSVector2), target2);
					}
				}
				playFX.Play(_actor, null, "Actor/Character/15601/FX/fx_15601_base_HeartArrowEffect", default(FP), target.tsTransform.Position, default(TSVector2));
				playFX.fxInstance.Bind(target.gameObject);
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.delayTime_TakeEffect_HeartArrow));
				int buffID = 15691013;
				string text = "AreaEffect_156_Sup_Skill_HeartArrowBoom";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515624, out perkLevel))
				{
					text = "AreaEffect_156_Sup_Skill_HeartArrowBoom_P24";
				}
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515630, out perkLevel))
				{
					buffID = 15630011;
				}
				((AdventureActor)target).buffComponent.AddBuff(buffID, _actor);
				ILRuntimeAPI.PlayAreaEffect(_actor, text, target.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			else
			{
				playFX.Play(_actor, null, "Actor/Character/15601/FX/fx_15601_base_HeartArrowEffect", default(FP), target.tsTransform.Position, default(TSVector2));
				playFX.fxInstance.Bind(target.gameObject);
				FP delayTime = Config_Support.delayTime_TakeEffect_HeartArrow;
				while (!target.IsDead() && delayTime > 0)
				{
					delayTime -= _actor.LogicDeltaTime;
					yield return null;
				}
				string text2 = "AreaEffect_156_Sup_Skill_HeartArrowBoom";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515624, out perkLevel))
				{
					text2 = "AreaEffect_156_Sup_Skill_HeartArrowBoom_P24";
				}
				ILRuntimeAPI.PlayAreaEffect(_actor, text2, target.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private void OnAreaEffectFinish(IEvent evt)
		{
			if (evt is AdventureAreaEffectFinishEvent adventureAreaEffectFinishEvent && adventureAreaEffectFinishEvent.owner == _actor)
			{
				AreaEffectEntity areaEffect = ILRuntimeAPI.GetAreaEffect(adventureAreaEffectFinishEvent.entityID);
				if (areaEffect.CheckTag(Config_Support.areaEffectTag_Sculpture) && CommonUtils.HavePersonalPerk(_actor.dataID, 515627, out var _))
				{
					_actor.StartLogicCoroutine(PerkLogic_P27(areaEffect.tsTransform.Position));
				}
			}
		}

		private IEnumerator PerkLogic_P27(TSVector2 position)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.delayTime_GenerateAreaEffect_P27));
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_156_P27_PenguinStatueBoom", position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("PLAYER_SPAWN_COMPLETE", OnPlayerSpawnComplete);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
			if (_triggerCDCor_P25 != null)
			{
				_actor.StopLogicCoroutine(_triggerCDCor_P25);
			}
			_triggerCDCor_P25 = null;
		}
	}
