			if (GetPerk(515501) && CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_Boom_1))
			{
				if (_actor.LogicTime - _delayTime_1 > delayTime_1)
				{
					monster.buffComponent.AddBuff(buffId_1, _actor);
