					ILRuntimeAPI.HitActor(_actor, (AdventureActor)monster, 155310101, "fx_15501_Base_Skill_Mail_Summon_1_boom", (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
					_delayTime_1 = _actor.LogicTime;
				}
