			if (GetPerk(515502) && CommonUtils.CheckHitByTag(evt.hitDamageTag, hitTag_Boom_2))
			{
				if (_actor.LogicTime - _delayTime_2 > delayTime_2)
				{
					monster.buffComponent.AddBuff(buffId_2, _actor);
