			if (evt.skillEventInfo.skillSlotType != GameEnum.skillSlotType.B)
			{
				return;
			}
			if (GetPerk(515521))
			{
				summonCfg_MW.attrPercent = summonInherit_M;
				summonCfg_MW.leftTime = summonLeftTime_MW;
				for (int i = 0; i < count_21; i++)
				{
