		public override void OnCustomEvent(AdventureActorCustomEvent evt)
		{
			if (evt.eventHashCode == shootEvt)
			{
				TSVector2 tSVector = TrueSyncExtensions.RandomPointInsideRing(mainCtrActor.tsTransform.Position, radius_enter, radius_enter);
				TSVector2 normalized = (mainCtrActor.tsTransform.Position - tSVector).normalized;
				FP speed = 0;
				if (mainCtrActor.attackTarget != null)
				{
					normalized = (mainCtrActor.attackTarget.tsTransform.Position - tSVector).normalized;
				}
				if (evt.intParam % 2 != 0)
				{
					speed = ILRuntimeAPI.ShootByDirection(GetPerk(515524) ? bullet_W_24 : bullet_W, _actor, default(FP), normalized, tSVector).velocitySpeed;
					TSVector2 position = tSVector + TSVector2.Rotate(normalized, 90) * offset_W;
					ILRuntimeAPI.ShootByDirection(bullet_MW_1, _actor, default(FP), normalized, position);
					TSVector2 position2 = tSVector + TSVector2.Rotate(normalized, -90) * offset_W;
					ILRuntimeAPI.ShootByDirection(bullet_MW_2, _actor, default(FP), normalized, position2);
				}
				else if (evt.intParam % 2 == 0)
				{
					speed = ILRuntimeAPI.ShootByDirection(GetPerk(515524) ? bullet_B_24 : bullet_B, _actor, default(FP), normalized, tSVector).velocitySpeed;
					TSVector2 position3 = tSVector + TSVector2.Rotate(normalized, 90) * offset_B_1;
					ILRuntimeAPI.ShootByDirection(bullet_MB_1, _actor, default(FP), normalized, position3);
					TSVector2 position4 = tSVector + TSVector2.Rotate(normalized, -90) * offset_B_2;
					ILRuntimeAPI.ShootByDirection(bullet_MB_2, _actor, default(FP), normalized, position4);
					CoroutineNode item = StartCoroutine(DoBomb(tSVector, normalized));
					corList.Add(item);
				}
				if (GetPerk(515524))
				{
					CoroutineNode item2 = StartCoroutine(DoAreaEffect(tSVector, normalized, speed));
					corList.Add(item2);
				}
			}
			else if (evt.eventHashCode == dieEvt)
			{
				summonCount--;
			}
		}

		private IEnumerator DoBomb(TSVector2 shootPos, TSVector2 shootDir)
		{
			yield return _actor.WaitTime(delay);
			int count = 0;
			while (count < bombCount)
			{
				string text = areaEffect_base;
				TSVector2 tSVector = TSVector2.Rotate(shootDir, 90);
				TSVector2 position = shootPos + shootDir * interval_disX / 2 + shootDir * interval_disX * count + tSVector * interval_disY;
				shape.angle = tSVector.GetAngle();
				shape.position = position;
				TSVector2 tSVector2 = _actor.RandomActorReachablePointInsideShape(shape);
				ILRuntimeAPI.PlayAreaEffect(_actor, text, tSVector2, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				TSVector2 tSVector3 = TSVector2.Rotate(shootDir, -90);
				TSVector2 position2 = shootPos + shootDir * interval_disX / 2 + shootDir * interval_disX * count + tSVector3 * interval_disY;
				shape.angle = tSVector3.GetAngle();
				shape.position = position2;
				tSVector2 = _actor.RandomActorReachablePointInsideShape(shape);
				ILRuntimeAPI.PlayAreaEffect(_actor, text, tSVector2, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				count++;
				yield return _actor.WaitTime(interval_time);
			}
		}

		private IEnumerator DoAreaEffect(TSVector2 startPos, TSVector2 shootDir, FP speed)
		{
			string areaEffect = areaEffect_24;
			FP interval = interval_24;
			FP curLen = 0;
			int count = 0;
			while (curLen < totleLength_24)
			{
				curLen += speed * _actor.LogicDeltaTime;
				if (curLen >= count * interval)
				{
					count++;
					long item = ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect, startPos + curLen * shootDir, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
					entityIds.Add(item);
					positions.Add(startPos + curLen * shootDir);
				}
				yield return null;
			}
		}

		public override void OnTriggerMasked(AdventureActor actor)
		{
			if (GetPerk(515527))
			{
				_actor.buffComponent.AddBuff(buff_27, actor);
			}
			if (GetPerk(515532))
			{
				_actor.buffComponent.AddBuff(buff_32, actor);
			}
		}

		private IEnumerator DoAddBuff()
		{
			while (true)
			{
				_actor.buffComponent.AddBuff(buff_30, _actor);
				yield return _actor.WaitTime(interval_30);
			}
		}

		private void SummonMW(int index)
		{
			TSVector2 tSVector = mainCtrActor.tsTransform.TransformLocalPointToWorldSpace(spawnOffset_W_21[index]);
			ILRuntimeAPI.SummonMonster(_actor, 0, summonId_MW, tSVector, _actor.tsTransform.Forward, summonCfg_MW, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
			{
				monster.logicVariable.ToggleLogicTag("isLeft", index % 2 == 0);
				summonCount++;
			});
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey actionKey = ComboInputBuffer.ActionKey.D;

		private readonly FP duration = 0.3;

		private readonly FP distance = 0.01;

		protected Dodge _dodge;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			base.comboAttack?.Clear();
		}

		private void DoMainLogic()
		{
			_actor.PlayFX("fx_10501_base_skill1_1_shadow");
			ComboInputBuffer.ActionKey key = actionKey;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, duration, distance, null, comboWithAttack: true);
		}

		protected void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ActorTryCastSkill actorTryCastSkill = ActorTryCastSkill.Generate();
					actorTryCastSkill.sender = _actor;
					actorTryCastSkill.skillId = specialSkillId;
					actorTryCastSkill.isInterruptAttack = false;
					actorTryCastSkill.flag = SkillPhaseFeatureFlag.Skill2;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(actorTryCastSkill);
					OnFinish();
				}
			}
		}

		protected void OnFinish()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}
	}
