	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private const string actionKey1 = "155_Ultra_TL";

		private const string actionKey2 = "155_Ultra_NoTL";

		private string evt_hideIdle = "";

		private string evt_showIdle = "";

		private string areaEffect = "AreaEffect_15501_Ultra";

		private const string starFxPath = "fx_15501_loop_Ultra_UI";

		private readonly FP shootInterval = 0.1;

		private readonly FP shootTime = 4;

		private readonly FP endTime = 4;

		private readonly FP speed = 8f;

		private readonly FP beginShoot = 0.2;

		private readonly FP srcInnerRadius = 0.7;

		private readonly FP srcOuterRadius = 0.9;

		private readonly FP desInnerRadius = 0;

		private readonly FP desOuterRadius = 4;

		private const float offsetNearClip = -2f;

		private const float offsetNearClip2 = 0.1f;

		private const float fxScale = 1f;

		private const int moveAare = 20;

		private readonly FP radius = 15;

		private int showOrHideIdleEvt = CommonHelper.StringToHash("showOrHideIdleEvt");

		private const int perkId_43 = 515543;

		private FP shootInterval_43 = 0.08;

		private CoroutineNode corMain;

		private CoroutineNode corShoot;

		private CoroutineNode corFollow;

		private TrueSyncTransform objActor;

		private PlayTimeline _playTimeline = new PlayTimeline();

		private TSVector2 center = new TSVector2(Screen.width / 2, Screen.height / 2);

		private PlayFX playFX = new PlayFX();

		private PlayFX playStartFX = new PlayFX();

		private PlayFX playEndFX = new PlayFX();

		private AdventureCustomCameraControlHandler adventureCustomCameraControlHandler;

		private List<AdventureFXPlayer> adventureFXPlayerList = new List<AdventureFXPlayer>();

		private string actionKey;

		private bool outControll;

		private bool isAssist;

		private TSVector2 lastTargetPos;

		private LogicEntity target;

		private long areaEffectId;

		private FP jumpDis = 3;

		private FP jumpHeight = 20;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			isAssist = (_actor as PlayerAdventureActor).isAssist;
			if (isAssist)
			{
				outControll = true;
			}
			else
			{
				outControll = false;
			}
			_actor.EnableInvincible();
			_actor.EnableSearchedImmunity();
			_actor.EnableCloseBlock();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: false);
			_playTimeline.Play(_actor, delegate
			{
				actionKey = "155_Ultra_TL";
				MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: true);
				StartCoroutine(ref corMain, DoMainLogic(hasTimeline: true));
			}, delegate
			{
				actionKey = "155_Ultra_NoTL";
				MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: true);
				StartCoroutine(ref corMain, DoMainLogic(hasTimeline: false));
			});
		}

		public void OnStop()
		{
			Debug.Log("OnStop");
			Clear();
		}

		public void OnUpdate()
		{
			DoUpdateLogic();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			StopCoroutine(ref corShoot);
			StopCoroutine(ref corFollow);
			ExitControl();
			_actor.DisableInvincible();
			_actor.DisableSearchedImmunity();
			_actor.DisableCloseBlock();
		}

		private IEnumerator DoMainLogic(bool hasTimeline)
		{
			SkillScript_Ultra skillScript_Ultra = this;
			string actionTag = actionKey;
			Action<string> action = onCustomEvent;
			System.Action onComboFinish = OnFinishOrInterrupt;
			System.Action onInterrupt = OnFinishOrInterrupt;
			RequestComboAttack req = skillScript_Ultra.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
			if (!hasTimeline)
			{
				while (!req.isAnticipationEnd)
				{
					yield return null;
				}
			}
			target = SeachTarget();
			if (!outControll)
			{
				EnterControl();
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(beginShoot));
			_ = _actor.LogicTime;
			StartCoroutine(ref corShoot, Shoot());
			FP seconds = endTime;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(seconds));
			playStartFX.Stop();
			_actor.CancelAttack();
		}

		private void EnterControl()
		{
			ModuleController<AdventureModuleController>.Instance.ActivePlayerCameraTrigger("UltraVmTiriggger_Gizmo");
			adventureCustomCameraControlHandler = ModuleController<AdventureModuleController>.Instance.CurCameraTriggerGizmo.CustomCameraControlHandlers[0];
			UnityEngine.Transform vmPlayer = adventureCustomCameraControlHandler.vmPlayer;
			objActor = vmPlayer.GetComponent<TrueSyncTransform>();
			objActor.Init();
			objActor.transformSyncEnabled = true;
			bool raycastHit;
			if (target != null)
			{
				if (_actor.QueryPositionReachable(target.tsTransform.Position))
				{
					objActor.Position = target.tsTransform.Position;
					objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
				}
				else
				{
					LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
					objActor.Position = activedPlayerActor.tsTransform.Position;
					objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
				}
			}
			else
			{
				LogicEntity activedPlayerActor2 = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				objActor.Position = activedPlayerActor2.tsTransform.Position;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
			playStartFX.Play(_actor, _skill, "fx_15501_loop_Ultra_UI", 0, TSVector2.zero, _actor.tsTransform.Forward);
		}

		private void ExitControl()
		{
			if (outControll)
			{
				return;
			}
			foreach (AdventureFXPlayer adventureFXPlayer in adventureFXPlayerList)
			{
				if (adventureFXPlayer.isPlaying)
				{
					adventureFXPlayer.Stop();
				}
			}
			playStartFX.Stop();
			playEndFX.Stop();
			ILRuntimeAPI.StopAreaEffect(areaEffectId);
			ModuleController<AdventureModuleController>.Instance.DeactivePlayerCameraTrigger("UltraVmTiriggger_Gizmo");
		}

		private IEnumerator Shoot()
		{
			adventureFXPlayerList.Clear();
			FP escapeTime = 0;
			lastTargetPos = TSVector2.zero;
			FP totleShootTime = shootTime;
			FP _shootInterval = (GetPerk(515543) ? shootInterval_43 : shootInterval);
			_ = _actor.LogicTime;
			FP curInterval = 0;
			while (escapeTime < totleShootTime)
			{
				if (curInterval >= _shootInterval || curInterval <= 0)
				{
					if (curInterval >= _shootInterval)
					{
						curInterval -= _shootInterval;
					}
					_ = Vector3.zero;
					_ = TSVector2.zero;
					TSVector2 tSVector2;
					Vector3 position;
					if (!outControll)
					{
						TSVector2 tSVector = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
						while (tSVector.y > Screen.height || tSVector.y < 0)
						{
							tSVector = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
						}
						position = new Vector3((float)tSVector.x, (float)tSVector.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + -2f);
						Vector3 position2 = new Vector3((float)tSVector.x, (float)tSVector.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + 0.1f);
						position = MonoSingleton<GameCameraStackManager>.Instance.mainCamera.ScreenToWorldPoint(position);
						MonoSingleton<GameCameraStackManager>.Instance.mainCamera.ScreenToWorldPoint(position2);
						tSVector2 = TrueSyncExtensions.RandomPointInsideRing(objActor.Position, desInnerRadius, desOuterRadius);
						lastTargetPos = objActor.Position;
					}
					else
					{
						TSVector2 tSVector3 = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
						while (tSVector3.y > Screen.height || tSVector3.y < 0)
						{
							tSVector3 = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
						}
						position = new Vector3((float)tSVector3.x, (float)tSVector3.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + -2f);
						position = MonoSingleton<GameCameraStackManager>.Instance.mainCamera.ScreenToWorldPoint(position);
						if (lastTargetPos == TSVector2.zero)
						{
							lastTargetPos = ((target != null) ? target.tsTransform.Position : _actor.tsTransform.Position);
						}
						tSVector2 = TrueSyncExtensions.RandomPointInsideRing(lastTargetPos, desInnerRadius, desOuterRadius);
					}
					new TSVector2(position.x, position.z);
					TSVector2 tSVector4 = tSVector2;
					ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect, tSVector4, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
				yield return null;
				escapeTime += _actor.LogicDeltaTime;
				curInterval += _actor.LogicDeltaTime;
			}
		}

		private void DoUpdateLogic()
		{
			TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (!(movementInputDirection != TSVector2.zero) || !objActor)
			{
				return;
			}
			FP logicDeltaTime = _actor.LogicDeltaTime;
			TSVector2 tSVector = new TSVector2(movementInputDirection.x * speed * logicDeltaTime, movementInputDirection.y * speed * logicDeltaTime);
			TSVector2 point = objActor.Position + tSVector;
			if (TSVector2.Distance(_actor.tsTransform.Position, point) > 20)
			{
				return;
			}
			bool raycastHit;
			if (_actor.QueryPositionReachable(point) || _actor.QueryPositionWalkable(point))
			{
				objActor.Position += tSVector;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
				return;
			}
			_ = objActor.Position;
			if ((bool)SceneSingleton<DeterministicCollisionManager>.Instance.CheckPointInterior(ref point, 4096))
			{
				if (Physics.Raycast(new Vector3(point.x.AsFloat(), 100f, point.y.AsFloat()), Vector3.down, out var hitInfo, 200f, 2048, QueryTriggerInteraction.Ignore) && hitInfo.point.y - objActor.Position.y < jumpHeight)
				{
					objActor.Position += tSVector;
					objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
				}
				return;
			}
			TSVector2 point2 = objActor.Position + movementInputDirection * jumpDis;
			if (_actor.QueryPositionWalkable(point2) || (bool)SceneSingleton<DeterministicCollisionManager>.Instance.CheckPointInterior(ref point2, 4096))
			{
				objActor.Position += tSVector;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
		}

		private void OnFinishOrInterrupt()
		{
			_skill?.Clear();
		}

		private LogicEntity SeachTarget()
		{
			if (_actor.attackTarget != null)
			{
				return _actor.attackTarget;
			}
			return CommonUtils.SearchNearTargetByCircle(_actor, radius);
		}

		private void onCustomEvent(string evt)
		{
			if (evt.Equals(evt_hideIdle))
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = showOrHideIdleEvt;
				adventureActorCustomEvent.boolParam = false;
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
			else if (evt.Equals(evt_showIdle))
			{
				AdventureActorCustomEvent adventureActorCustomEvent2 = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent2.boolParam = true;
				adventureActorCustomEvent2.eventHashCode = showOrHideIdleEvt;
				_actor.DispatchEvent(adventureActorCustomEvent2);
			}
		}
	}
	public class IState_UAV
	{
		private fsmStatus fsmStatus;

		public AdventureActor _actor;

		public AdventureActor _summoner;

		public AimTarget _aimTarget;

		public PlayFX playFx_Rush = new PlayFX();

		public PlayFX playFx_Rush2 = new PlayFX();

		public PlayFX playFx_Idle = new PlayFX();

		public PlayFX playFx_Idle2 = new PlayFX();

		public PlayFX playFx_Relax = new PlayFX();

		public PlayFX playFx_Relax2 = new PlayFX();

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public void Init(AdventureActor actor, AdventureActor summoner, AimTarget aimTarget, PlayFX playRush = null, PlayFX playRush2 = null, PlayFX playIdle = null, PlayFX playIdle2 = null, PlayFX playRelax = null, PlayFX playRelax2 = null)
		{
			_actor = actor;
			_summoner = summoner;
			_aimTarget = aimTarget;
			playFx_Rush = playRush;
			playFx_Rush2 = playRush2;
			playFx_Idle = playIdle;
			playFx_Idle2 = playIdle2;
			playFx_Relax = playRelax;
			playFx_Relax2 = playRelax2;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
		}

		public virtual void ForceExit(bool keepAim = false)
		{
		}

		protected void StartCoroutine(ref CoroutineNode coroutineNode, IEnumerator enumerator)
		{
			if (!(_actor == null))
			{
				if (coroutineNode != null)
				{
					_actor.StopLogicCoroutine(coroutineNode);
				}
				coroutineNode = _actor.StartLogicCoroutine(enumerator, runImmediately: true);
			}
		}

		protected void StopCoroutine(ref CoroutineNode coroutineNode)
		{
			if (!(_actor == null))
			{
				if (coroutineNode != null)
				{
					_actor.StopLogicCoroutine(coroutineNode);
				}
				coroutineNode = null;
			}
		}

		protected TSVector2 GetRandomPos()
		{
			bool flag = Config_L.uavAtkB_dataId == _actor.dataID;
			TSVector2 tSVector = _summoner.tsTransform.TransformLocalPointToWorldSpace(flag ? Config_L.leftLocalPos : Config_L.rightLocalPos);
			if (_actor.QueryPositionReachable(tSVector))
			{
				return tSVector;
			}
			if (_actor.LinecastNavmeshGraph(_summoner.tsTransform.Position, tSVector, out var linecastHitPoint))
			{
				return linecastHitPoint;
			}
			return _actor.RandomActorReachablePointInsideLine(_summoner.tsTransform.Position, flag ? _summoner.tsTransform.Left : _summoner.tsTransform.Right, Config_L.leftLocalPos.magnitude);
		}
	}
	public class RelaxState_L : IState_UAV
	{
		private CoroutineNode corMain;

		private CoroutineNode corExit;

		private FP timer;

		public override void Enter()
		{
			base.Enter();
			StartCoroutine(ref corMain, DoMainLogic());
		}

		public override void Exit()
		{
			base.Exit();
			StopCoroutine(ref corMain);
			StopCoroutine(ref corExit);
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				playFx_Idle.Stop();
				playFx_Relax.Stop();
			}
			else
			{
				playFx_Idle2.Stop();
				playFx_Relax2.Stop();
			}
		}

		public override void ForceExit(bool keepAim = false)
		{
			Exit();
		}

		public void NormalExit()
		{
			Exit();
		}

		private IEnumerator DoMainLogic()
		{
			timer = 0;
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				if (!playFx_Idle.isPlaying)
				{
					playFx_Idle.Play(_summoner, Config_L.effectIdle_B, 1f, _summoner.transform.position, _summoner.transform.rotation);
				}
			}
			else if (!playFx_Idle2.isPlaying)
			{
				playFx_Idle2.Play(_summoner, Config_L.effectIdle_W, 1f, _summoner.transform.position, _summoner.transform.rotation);
			}
			bool finish = false;
			string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyHide_B_Rush : Config_L.keyHide_W_Rush);
			_actor.PlayComboByKey(actionTag, delegate
			{
				finish = true;
			}, delegate
			{
				finish = true;
			});
			yield return _actor.WaitTime(Config_L.hideTime);
			_actor.Hide();
		}

		public override void Update()
		{
			base.Update();
			if (_actor.monsterTarget != null)
			{
				NormalExit();
				return;
			}
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero || ModuleController<AdventureModuleController>.Instance.SemiAutoBattle)
			{
				StopRelaxAnimation();
				timer = 0;
			}
			timer += _actor.LogicDeltaTime;
			if (timer > Config_L.Interval_Relax_first)
			{
				timer = 0;
				PlayRelaxAnimation();
			}
		}

		private void PlayRelaxAnimation()
		{
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				playFx_Idle.Stop();
				if (!playFx_Relax.isPlaying)
				{
					playFx_Relax.Play(_summoner, Config_L.effectRelax_B, 1f, _summoner.transform.position, _summoner.transform.rotation);
					return;
				}
				playFx_Relax.Stop();
				playFx_Relax.Play(_summoner, Config_L.effectRelax_B, 1f, _summoner.transform.position, _summoner.transform.rotation);
			}
			else
			{
				playFx_Idle2.Stop();
				if (!playFx_Relax2.isPlaying)
				{
					playFx_Relax2.Play(_summoner, Config_L.effectRelax_W, 1f, _summoner.transform.position, _summoner.transform.rotation);
					return;
				}
				playFx_Relax2.Stop();
				playFx_Relax2.Play(_summoner, Config_L.effectRelax_W, 1f, _summoner.transform.position, _summoner.transform.rotation);
			}
		}

		private void StopRelaxAnimation()
		{
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				if (!playFx_Idle.isPlaying)
				{
					playFx_Idle.Play(_summoner, Config_L.effectIdle_B, 1f, _summoner.transform.position, _summoner.transform.rotation);
				}
				playFx_Relax.Stop();
			}
			else
			{
				if (!playFx_Idle2.isPlaying)
				{
					playFx_Idle2.Play(_summoner, Config_L.effectIdle_W, 1f, _summoner.transform.position, _summoner.transform.rotation);
				}
				playFx_Relax2.Stop();
			}
		}

		public void ForceExitBySkill()
		{
			StartCoroutine(ref corExit, DoExitLogic());
		}

		private IEnumerator DoExitLogic()
		{
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				playFx_Idle.Stop();
				playFx_Relax.Stop();
			}
			else
			{
				playFx_Idle2.Stop();
				playFx_Relax2.Stop();
			}
			TSVector2 randomPos = GetRandomPos();
			_actor.Teleport(randomPos);
			_actor.LookAtDir(_summoner.tsTransform.Forward, 0);
			_actor.Visible();
			bool finish = false;
			string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyShow_B_Rush : Config_L.keyShow_W_Rush);
			_actor.PlayComboByKey(actionTag, delegate
			{
				finish = true;
			}, delegate
			{
				finish = true;
			});
			while (!finish)
			{
				yield return null;
			}
			Exit();
		}
	}
	public class TraceState_L : IState_UAV
	{
		private FP moveStop = 0.1;

		public TSVector2 randomPos;

		public LogicEntity target;

		private TSVector2 lastTargetPos;

		private TSVector2 targetPos;

		public bool isTeleport;

		private CoroutineNode corMain;

		private PlayFX playFx_Move = new PlayFX();

		public override void Enter()
		{
			base.Enter();
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				_summoner.logicVariable.ToggleLogicTag("trace_b", value: true);
			}
			else
			{
				_summoner.logicVariable.ToggleLogicTag("trace_w", value: true);
			}
			StartCoroutine(ref corMain, DoMainLogic());
		}

		public override void Exit()
		{
			base.Exit();
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				_summoner.logicVariable.ToggleLogicTag("trace_b", value: false);
			}
			else
			{
				_summoner.logicVariable.ToggleLogicTag("trace_w", value: false);
			}
			StopCoroutine(ref corMain);
			playFx_Move.Stop();
		}

		private IEnumerator DoMainLogic()
		{
			if (isTeleport)
			{
				TSVector2 targetPos = GetRandomPos();
				bool finish = false;
				string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyHide_B : Config_L.keyHide_W);
				_actor.PlayComboByKey(actionTag, delegate
				{
					finish = true;
				}, delegate
				{
					finish = true;
				});
				yield return _actor.WaitTime(Config_L.hideTime);
				_actor.Hide();
				_actor.Teleport(targetPos);
				_actor.Visible();
				finish = false;
				string actionTag2 = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyShow_B : Config_L.keyShow_W);
				_actor.PlayComboByKey(actionTag2, delegate
				{
					finish = true;
				}, delegate
				{
					finish = true;
				});
				while (!finish)
				{
					yield return null;
				}
				isTeleport = false;
			}
			else
			{
				isTeleport = false;
			}
		}

		public override void Update()
		{
			base.Update();
			if (!isTeleport)
			{
				if (target != null)
				{
					targetPos = GetRandomPos();
					lastTargetPos = targetPos;
				}
				else
				{
					targetPos = lastTargetPos;
				}
				_actor.MoveTo(targetPos, moveStop, enableNavigation: true, AdventureActor.MovementMode.Run, delegate
				{
					Exit();
				});
				if (!playFx_Move.isPlaying)
				{
					playFx_Move.Play(_actor, Config_L.effectMove, 1f, _actor.transform.position, _actor.transform.rotation);
				}
			}
		}

		public override void ForceExit(bool keepAim = false)
		{
			_actor.InterruptAttack(force: true);
			_actor.StandBy((System.Action)null);
			Exit();
		}
	}
	public class RushState_L : IState_UAV
	{
		public TSVector2 localPos;

		public LogicEntity target;

		private CoroutineNode corMain;

		private CoroutineNode corExit;

		public override void Enter()
		{
			base.Enter();
			StartCoroutine(ref corMain, DoMainLogic());
		}

		public override void Exit()
		{
			base.Exit();
			StopCoroutine(ref corMain);
			StopCoroutine(ref corExit);
		}

		public override void ForceExit(bool keepAim = false)
		{
			StartCoroutine(ref corExit, DoExitLogic());
		}

		private IEnumerator DoMainLogic()
		{
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				playFx_Idle.Stop();
				if (!playFx_Rush.isPlaying)
				{
					playFx_Rush.Play(_summoner, Config_L.effectRush_B, 1f, _summoner.transform.position, _summoner.transform.rotation);
				}
			}
			else
			{
				playFx_Idle2.Stop();
				if (!playFx_Rush2.isPlaying)
				{
					playFx_Rush2.Play(_summoner, Config_L.effectRush_W, 1f, _summoner.transform.position, _summoner.transform.rotation);
				}
			}
			if (!_actor.isHide)
			{
				bool finish = false;
				bool interrupt = false;
				string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyHide_B_Rush : Config_L.keyHide_W_Rush);
				_actor.PlayComboByKey(actionTag, delegate
				{
					finish = true;
				}, delegate
				{
					interrupt = true;
				});
				yield return _actor.WaitTime(Config_L.hideTime);
				if (!interrupt)
				{
					_actor.Hide();
				}
			}
		}

		private IEnumerator DoExitLogic()
		{
			if (_actor.dataID == Config_L.uavAtkB_dataId)
			{
				playFx_Rush.Stop();
			}
			else
			{
				playFx_Rush2.Stop();
			}
			TSVector2 randomPos = GetRandomPos();
			_actor.Teleport(randomPos);
			_actor.LookAtDir(_summoner.tsTransform.Forward, 0);
			_actor.Visible();
			bool finish = false;
			string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyShow_B_Rush : Config_L.keyShow_W_Rush);
			_actor.InterruptAttack(force: true);
			_actor.PlayComboByKey(actionTag, delegate
			{
				finish = true;
			}, delegate
			{
				finish = true;
			});
			while (!finish)
			{
				yield return null;
			}
			Exit();
		}
	}
	public class BattleState_L : IState_UAV
	{
		public bool CanCast;

		public int skillId;

		private bool forceInterrupt;

