			Exit();
		}

		public override void Exit()
		{
			StopCoroutine(ref corMain);
			base.Exit();
			playFx_Atk.Stop();
		}

		private IEnumerator DoMainLogic()
		{
			playFx_Atk.Play(_actor, Config_L.effectAtk, 1f, _actor.transform.position, _actor.transform.rotation);
			if (TSVector2.Distance(_actor.tsTransform.Position, _summoner.tsTransform.Position) > Config_L.blinkRange)
			{
				TSVector2 targetPos = GetRandomPos();
				bool finish = false;
				string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyHide_B : Config_L.keyHide_W);
				_actor.PlayComboByKey(actionTag, delegate
				{
					finish = true;
				}, delegate
				{
					finish = true;
				});
				yield return _actor.WaitTime(Config_L.hideTime);
				_actor.Hide();
				_actor.Teleport(targetPos);
				_actor.Visible();
				finish = false;
				string actionTag2 = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyShow_B : Config_L.keyShow_W);
				_actor.PlayComboByKey(actionTag2, delegate
				{
					finish = true;
				}, delegate
				{
					finish = true;
				});
				while (!finish)
				{
					yield return null;
				}
			}
			CanCast = ILRuntimeAPI.CreateSkill(skillId, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
			{
				Exit();
			});
		}
	}
	public class BattleIdleState_L : IState_UAV
	{
		private CoroutineNode corMain;

		public override void Enter()
		{
			base.Enter();
			StartCoroutine(ref corMain, DoMainLogic());
		}

		public override void Exit()
		{
			base.Exit();
			StopCoroutine(ref corMain);
		}

		public override void ForceExit(bool keepAim = false)
		{
			if (!keepAim)
			{
				_aimTarget.Cancel();
			}
			Exit();
		}

		private IEnumerator DoMainLogic()
		{
			if (_actor.isHide)
			{
				TSVector2 randomPos = GetRandomPos();
				_actor.Teleport(randomPos);
				_actor.Visible();
				bool finish = false;
				string actionTag = ((_actor.dataID == Config_L.uavAtkB_dataId) ? Config_L.keyShow_B : Config_L.keyShow_W);
				_actor.PlayComboByKey(actionTag, delegate
				{
					finish = true;
				}, delegate
				{
					finish = true;
				});
				while (!finish)
				{
					yield return null;
				}
			}
			_aimTarget.Aim(_actor, _actor.monsterTarget as AdventureActor);
		}

		public override void Update()
		{
			if (_actor.monsterTarget == null)
			{
				_aimTarget.Cancel();
				Exit();
			}
			else if (_summoner != null && TSVector2.Distance(_actor.tsTransform.Position, _summoner.tsTransform.Position) > Config_L.trace_first)
			{
				_aimTarget.Cancel();
				Exit();
			}
		}
	}
