	public class ParallelScript : ParallelBase
	{
		private FP _lastTriggerTime_P42;

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnGetBuff(IEvent evt)
		{
			if (evt is AdventureActorGetBuff adventureActorGetBuff && adventureActorGetBuff.from is PlayerAdventureActor && adventureActorGetBuff.eventInfo.buffTags.Contains(CommonDefine.Light) && ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 4))
			{
				_actor.buffComponent.AddBuff(15096411, _actor);
			}
		}

		private void OnReceiveAttack(IEvent evt)
		{
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			if (adventureActorReceiveAttackEvent.from is PlayerAdventureActor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor && adventureActorReceiveAttackEvent.from == _actor)
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515043, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveAttackEvent.hitDamageTag, Config.damageTag_Trigger_P43))
				{
					_actor.buffComponent.AddBuff(15043011, _actor);
				}
				OnSelfAttacked(adventureActorReceiveAttackEvent);
			}
		}

		protected virtual void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from is PlayerAdventureActor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor monsterAdventureActor && adventureActorReceiveDamageBeforeHitEvent.from == _actor)
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515042, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_Trigger_P42) && (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE || monsterAdventureActor.IsBossMonster()))
				{
					AdventureActor.AddFromAttr(15042001, _actor);
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 5) && (monsterAdventureActor.IsBossMonster() || monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE))
				{
					AdventureActor.AddFromAttr(15096511, _actor);
				}
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.from is PlayerAdventureActor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monsterAdventureActor) || !(adventureActorReceiveDamageEvent.from == _actor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515042, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_P42) && (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE || monsterAdventureActor.IsBossMonster()))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 15042012);
				if (_lastTriggerTime_P42 <= 0 || _actor.LogicTime - _lastTriggerTime_P42 > scriptValue)
				{
					FP scriptValue2 = CommonUtils.GetScriptValue(_actor, 15042011);
					((PlayerAdventureActor)_actor)?.playerSkillCd?.AddEnergy(scriptValue2);
					_lastTriggerTime_P42 = _actor.LogicTime;
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 1))
			{
				_actor.buffComponent.AddBuff(15096111, _actor);
			}
			OnSelfDamaged(adventureActorReceiveDamageEvent);
			if (CheckCanTriggerLightMark(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag))
			{
				TriggerLightMark(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag);
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null || hitDamageTag.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.LightMark1, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				if (CommonUtils.CheckHitByTag(hitDamageTag, Config.damageTag_TriggerLightMark))
				{
					return true;
				}
				if (CommonUtils.CheckHitByTag(hitDamageTag, Config.damageTag_RateTriggerLightMark))
				{
					return TSRandom.Range(0f, 100f) <= CommonUtils.GetScriptValue(_actor, 0);
				}
			}
			return false;
		}

		private void TriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			monster.buffComponent.RemoveBuffByTag(CommonDefine.LightMark1);
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_150_LightTag_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.LightMark1, GameEnum.AdventureActorElementTriggerType.LightElementTriggerType1, _actor, monster, "LightMark_Trigger_Effect_02");
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 2))
			{
				_actor.buffComponent.AddBuff(15096211, _actor);
			}
			OnTriggerLightMark(hitDamageTag, monster);
		}

		protected virtual void OnTriggerLightMark(IList<int> hitDamageTag, MonsterAdventureActor target)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			ComboInputBuffer.ActionKey[] comboKeys_Dodge = Config.comboKeys_Dodge;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboKeys_Dodge, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, Config.duration_Dodge, Config.distance_Dodge, null, comboWithAttack: true);
		}

		private void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private int _stage;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			UpdateRootMotionState();
			_stage = _actor.logicVariable.GetLogicTagValue("NormalAttackStage").AsInt();
		}

		public void OnStart()
		{
			string text = ((_stage < Config.comboTagList_NormalAttack.Count) ? Config.comboTagList_NormalAttack[_stage] : null);
			if (string.IsNullOrEmpty(text))
			{
				NovaLogger.Error($"该普攻段数未配置ComboTag, 普攻段数:{_stage}");
				OnFinish();
				return;
			}
			LogicEntity attackTarget = _actor.attackTarget;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(text, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, attackTarget, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt);
		}

		private void OnAnticipationEnd()
		{
			int num = _stage + 1;
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", (num < Config.comboTagList_NormalAttack.Count) ? num : 0);
		}

		public void OnUpdate()
		{
			UpdateRootMotionState();
			LockDirection();
		}

		private void UpdateRootMotionState()
		{
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_actor.movementFSM.runtimeIgonreRootMotion = true;
			}
			else
			{
				_actor.movementFSM.runtimeIgonreRootMotion = false;
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.movementFSM.runtimeIgonreRootMotion = false;
			_stage = 0;
		}
	}
	public class SkillScript_Rush : SkillAdvancedBase
	{
		private Skill_Rush _skillRush;

		private bool _triggerPerk_P11;

		private PlayFX _chargeFX_P11;

		private FP _chargeTime_P11;

		private PlayFX _chargeFinishFX_P11;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (_skillRush == null)
			{
				_skillRush = new Skill_Rush();
			}
			_skillRush.OnEnable(_actor, _skill, Config.comboKeys_Rush, Config.comboKeys_Rush_Independent, Config.interruptTime_Rush, useSpecialRushEnd: false, Config.comboKeys_SpecialRushEnd);
			_triggerPerk_P11 = false;
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 515011, out var _))
			{
				return;
			}
			FP logicTagValue = _actor.logicVariable.GetLogicTagValue("LastTriggerTime_P11");
			if (logicTagValue <= 0 || _actor.LogicTime - logicTagValue > CommonUtils.GetScriptValue(_actor, 15011011))
			{
				_triggerPerk_P11 = true;
				if (_chargeFX_P11 == null)
				{
					_chargeFX_P11 = new PlayFX();
				}
				_chargeFX_P11.Play(_actor, _skill, "fx_15001_loop_Rush_P11_Charge", default(FP), _actor.tsTransform.Position, default(TSVector2));
			}
		}

		public void OnUpdate()
		{
			_skillRush?.OnUpdate();
			if (!_triggerPerk_P11)
			{
				return;
			}
			_chargeTime_P11 += _actor.LogicDeltaTime;
			if (_chargeTime_P11 >= Config_MainControl.chargeTime_P11)
			{
				if (_chargeFinishFX_P11 == null)
				{
					_chargeFinishFX_P11 = new PlayFX();
				}
				else if (_chargeFinishFX_P11.fxInstance == null)
				{
					_chargeFinishFX_P11.Play(_actor, _skill, "fx_15001_loop_Rush_P11_Charge_end", default(FP), _actor.tsTransform.Position, default(TSVector2));
				}
			}
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_skillRush?.OnDisable();
			if (_triggerPerk_P11 && _chargeTime_P11 >= Config_MainControl.chargeTime_P11)
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_150_Main_Skill_P11_Boom", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				_actor.logicVariable.SetLogicTagValue("LastTriggerTime_P11", _actor.LogicTime);
			}
			_triggerPerk_P11 = false;
			_chargeTime_P11 = 0;
			_chargeFX_P11?.Stop();
			_chargeFX_P11?.Clear();
			_chargeFinishFX_P11?.Stop();
			_chargeFinishFX_P11?.Clear();
		}
	}
	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private PlayTimeline _playTimeline;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 3))
			{
				_actor.buffComponent.AddBuff(15096311, _actor);
			}
			_actor.EnableInvincible();
			_actor.EnableSuperArmor();
			_actor.EnableImmuneControl();
			DefaultLookAt();
		}

		public void OnStart()
		{
			if (_playTimeline == null)
			{
				_playTimeline = new PlayTimeline();
			}
			_playTimeline.Play(_actor, OnPlayTimeLineFinish, OnNotPlayTimeLine);
		}

		private void OnPlayTimeLineFinish()
		{
			string actionTag = "150_Ultra_TL";
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnNotPlayTimeLine()
		{
			string actionTag = "150_Ultra_NoTL";
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "150_Ultra_Attack"))
			{
				GenerateAttackAreaEffect();
			}
		}

		private void GenerateAttackAreaEffect()
		{
			TSVector2 tSVector = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config.offset_AreaEffect_UltraSkill;
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_150_Ultra", tSVector, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515041, out var _))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_150_Ultra_P41", tSVector, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.DisableInvincible();
			_actor.DisableSuperArmor();
			_actor.DisableImmuneControl();
		}
	}
