	public class ActionScript_MainControl : ActionScript
	{
		private FP _delayNormalAttackStageDelay;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
			_actor.logicVariable.ToggleLogicTag("HoldingKeyB", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable.ToggleLogicTag("HoldingKeyB", value: false);
		}

		protected override void OnButtonDPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			}
			else if (_delayNormalAttackStageDelay > 0)
			{
				_delayNormalAttackStageDelay -= _actor.LogicDeltaTime;
			}
			else
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private HitBox.HitBoxFeatureData _hitBoxFeatureData_P2;

		private int _triggerCount_P9;

		private CoroutineNode _resetTriggerCountCor_P9;

		private HashSet<long> _hittedBossSet_P13;

		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REMOVE_BUFF", OnBuffRemove);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515008, out var perkLevel) && CommonUtils.CheckElementMark(CommonDefine.LightMark1, monsterAdventureActor) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_MainControl.damageTag_TriggerBuff_P8))
			{
				_actor.buffComponent.AddBuff(15008011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515013, out perkLevel) && monsterAdventureActor.IsBossMonster())
			{
				if (_hittedBossSet_P13 == null)
				{
					_hittedBossSet_P13 = new HashSet<long>();
				}
				if (_hittedBossSet_P13.Add(monsterAdventureActor.Id))
				{
					_actor.buffComponent.AddBuff(15013011, _actor);
				}
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515004, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P4))
			{
				int num = _actor.logicVariable.GetLogicTagValue("AdditionalAttrCount_P4").AsInt();
				if (num > 0)
				{
					AdventureActor.AddFromAttr(15004011, _actor, num);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515007, out perkLevel))
			{
				int buffNumByID = monsterAdventureActor.buffComponent.GetBuffNumByID(15007011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(15007001, _actor, buffNumByID);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515008, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_TriggerStrength_P8))
			{
				int num2 = _actor.logicVariable.GetLogicTagValue("AdditionalAttrCount_P8").AsInt();
				if (num2 > 0)
				{
					AdventureActor.AddFromAttr(15008001, _actor, num2);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515010, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_TriggerStrength_P10))
			{
				int buffNumByID2 = monsterAdventureActor.buffComponent.GetBuffNumByID(15010011);
				if (buffNumByID2 > 0)
				{
					AdventureActor.AddFromAttr(15010001, _actor, buffNumByID2);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515002, out var perkLevel))
			{
				if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_TriggerDamage_P2) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(15002011))
				{
					if (_hitBoxFeatureData_P2 == null)
					{
						_hitBoxFeatureData_P2 = new HitBox.HitBoxFeatureData
						{
							buffIdsForTarget = new List<int> { 15002012 }
						};
					}
					ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 150310201, "fx_15001_Hit_Electric", (string)null, false, HitBox.FeatureFlag.AddBuffForTarget, _hitBoxFeatureData_P2, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
					if (TryTriggerElectricityExplosion_P2(monsterAdventureActor, onlyCheckStrength: true))
					{
						monsterAdventureActor.buffComponent.RemoveBuffByBuffId(15002011);
					}
				}
				if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_TriggerThunder_P2))
				{
					monsterAdventureActor.buffComponent.AddBuff(15002011, _actor);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515007, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P7))
			{
				monsterAdventureActor.buffComponent.AddBuff(15007011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515010, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_TriggerBuff_P10))
			{
				monsterAdventureActor.buffComponent.AddBuff(15010011, _actor);
			}
		}

		protected override void OnTriggerLightMark(IList<int> hitDamageTag, MonsterAdventureActor target)
		{
			base.OnTriggerLightMark(hitDamageTag, target);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515009, out var perkLevel) && CommonUtils.CheckHitByTag(hitDamageTag, Config_MainControl.damageTag_Trigger_P9) && !target.IsDead() && _triggerCount_P9 < 3)
			{
				_actor.StartLogicCoroutine(PerkLogic_P9(target));
				_triggerCount_P9++;
				if (_resetTriggerCountCor_P9 == null)
				{
					_resetTriggerCountCor_P9 = _actor.StartLogicCoroutine(ResetTriggerCount_P9());
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515012, out perkLevel) && CommonUtils.CheckHitByTag(hitDamageTag, Config_MainControl.damageTag_Trigger_P12))
			{
				_actor.buffComponent.AddBuff(15012011, _actor);
			}
		}

		private void OnBuffRemove(IEvent evt)
		{
			AdventureActorRemoveBuff adventureActorRemoveBuff = evt as AdventureActorRemoveBuff;
			if (adventureActorRemoveBuff.sender as AdventureActor is MonsterAdventureActor monster && CommonUtils.HavePersonalPerk(_actor.dataID, 515002, out var _) && adventureActorRemoveBuff.eventInfo.buffId == 15002011)
			{
				TryTriggerElectricityExplosion_P2(monster);
			}
		}

		private void OnActorDied(IEvent evt)
		{
			if ((evt as AdventureActorDiedEvent).actor is MonsterAdventureActor monsterAdventureActor && CommonUtils.HavePersonalPerk(_actor.dataID, 515002, out var _) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(15002011))
			{
				TryTriggerElectricityExplosion_P2(monsterAdventureActor);
			}
		}

		private bool TryTriggerElectricityExplosion_P2(MonsterAdventureActor monster, bool onlyCheckStrength = false)
		{
			int buffNumByID = monster.buffComponent.GetBuffNumByID(15002012);
			if (buffNumByID <= 0)
			{
				return false;
			}
			if (onlyCheckStrength && buffNumByID < 20)
			{
				return false;
			}
			monster.buffComponent.RemoveBuffByBuffId(15002012);
			string text = ((buffNumByID >= 20) ? "AreaEffect_150_Main_Skill_P02_Boom_Big" : "AreaEffect_150_Main_Skill_P02_Boom_Small");
			ILRuntimeAPI.PlayAreaEffect(_actor, text, monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			return true;
		}

		private IEnumerator PerkLogic_P9(AdventureActor target)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_MainControl.firstHitDelay_P9));
			int hitDamageId = 150310901;
			HashSet<long> hittedSet = new HashSet<long>();
			ILRuntimeAPI.HitActor(_actor, target, hitDamageId, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
			hittedSet.Add(target.Id);
			for (int i = 0; i < 4; i++)
			{
				bool canNextLink = true;
				ILRuntimeAPI.SearchByRangeAndPosition(_actor, target.tsTransform.Position, Config_MainControl.searchRadius_P9, delegate(List<LogicEntity> result)
				{
					if (result.Count > 0)
					{
						canNextLink = false;
						for (int j = 0; j < result.Count; j++)
						{
							if (hittedSet.Add(result[j].Id))
							{
								AdventureActor adventureActor = result[j] as AdventureActor;
								AdventureActor actor = _actor;
								int num = hitDamageId;
								GameObject gameObject = target.gameObject;
								ILRuntimeAPI.HitActor(actor, adventureActor, num, (string)null, "fx_15001_bullet_Main_Skill_P09_LightningChain", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, gameObject);
								target = adventureActor;
								canNextLink = true;
								break;
							}
						}
					}
					else
					{
						canNextLink = false;
					}
				}, isConfront: true);
				if (canNextLink)
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_MainControl.linkInterval_P9));
					continue;
				}
				break;
			}
		}

		private IEnumerator ResetTriggerCount_P9()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(1));
			_triggerCount_P9 = 0;
			_resetTriggerCountCor_P9 = null;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnBuffRemove);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			_triggerCount_P9 = 0;
			if (_resetTriggerCountCor_P9 != null)
			{
				_actor.StopLogicCoroutine(_resetTriggerCountCor_P9);
			}
			_resetTriggerCountCor_P9 = null;
			_hittedBossSet_P13?.Clear();
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private Queue<string> _sweepComboTagQueue;

		private AimTarget _aimTarget;

		private FP _maxRotateSpeed;

		private FP _maxRotateTime;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (_sweepComboTagQueue == null)
			{
				_sweepComboTagQueue = new Queue<string>();
			}
			else
			{
				_sweepComboTagQueue.Clear();
			}
			DefaultLookAt();
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			else
			{
				_aimTarget.Cancel();
			}
			_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515003, out var perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515006, out perkLevel))
				{
					for (int i = 0; i < Config_MainControl.comboTagList_Skill_Sweep_P3_P6.Count; i++)
					{
						_sweepComboTagQueue.Enqueue(Config_MainControl.comboTagList_Skill_Sweep_P3_P6[i]);
					}
				}
				else
				{
					for (int j = 0; j < Config_MainControl.comboTagList_Skill_Sweep_P3.Count; j++)
					{
						_sweepComboTagQueue.Enqueue(Config_MainControl.comboTagList_Skill_Sweep_P3[j]);
					}
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 515006, out perkLevel))
			{
				_sweepComboTagQueue.Enqueue("150_Main_Skill_P06_A1");
			}
			else
			{
				_sweepComboTagQueue.Enqueue("150_Main_Skill_A1");
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515008, out perkLevel))
			{
				_actor.logicVariable.SetLogicTagValue("AdditionalAttrCount_P8", _actor.buffComponent.GetBuffNumByID(15008011));
				_actor.buffComponent.RemoveBuffByBuffId(15008011);
			}
			_maxRotateSpeed = 0;
			_maxRotateTime = 0;
		}

		public void OnStart()
		{
			SweepAttack();
		}

		private void SweepAttack()
		{
			if (_sweepComboTagQueue.Count > 0)
			{
				if (_actor.attackTarget != null)
				{
					_actor.tsTransform.Forward = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				}
				string actionTag = _sweepComboTagQueue.Dequeue();
				System.Action onActivationEnd = OnSweepActivationEnd;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 515004, out var _))
				{
					_actor.buffComponent.AddBuff(15004011, _actor);
				}
			}
			else
			{
				OnFinish();
			}
		}

		private void OnSweepActivationEnd()
		{
			if (_sweepComboTagQueue.Count > 0 && _actor.logicVariable.GetLogicTagToggle("HoldingKeyB"))
			{
				SweepAttack();
			}
			else
			{
				ShootLaser();
			}
		}

		private void ShootLaser()
		{
			_maxRotateSpeed = 0;
			_maxRotateTime = 0;
			string text = "150_Main_Skill_B1";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515003, out var perkLevel))
			{
				int index = Config_MainControl.comboTagList_Skill_Sweep_P3.Count - _sweepComboTagQueue.Count - 1;
				text = Config_MainControl.comboTagList_Skill_Laser_P3[index];
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515004, out perkLevel))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(15004011);
				_actor.buffComponent.RemoveBuffByBuffId(15004011);
				_actor.logicVariable.SetLogicTagValue("AdditionalAttrCount_P4", buffNumByID);
				if (buffNumByID >= 3)
				{
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 515003, out perkLevel))
					{
						int index2 = Config_MainControl.comboTagList_Skill_Sweep_P3.Count - _sweepComboTagQueue.Count - 1;
						text = Config_MainControl.comboTagList_Skill_Laser_P3_P4[index2];
					}
					else
					{
						text = "150_Main_Skill_2_C1";
					}
					_maxRotateSpeed = Config_MainControl.rotateSpeed_P4;
					_maxRotateTime = Config_MainControl.laserLoopTime_MaxBuff_P4;
					_actor.buffComponent.AddBuff(15004012, _actor);
				}
			}
			if (_actor.attackTarget != null)
			{
				_actor.tsTransform.Forward = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
			}
			string actionTag = text;
			Action<string> onCustomEvent = OnLaserCustomEvent;
			System.Action onRecoveryBegin = OnLaserRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent);
		}

		public void OnUpdate()
		{
			if (_maxRotateTime > 0)
			{
				TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (movementInputDirection != TSVector2.zero)
				{
					FP fP = TSVector2.SignedAngle(_actor.tsTransform.Forward, movementInputDirection);
					FP fP2 = _maxRotateSpeed * _actor.LogicDeltaTime;
					FP degrees = ((TSMath.Abs(fP) < fP2) ? fP : (fP2 * TSMath.Sign(fP)));
					_actor.tsTransform.Forward = TSVector2.Rotate(_actor.tsTransform.Forward, degrees);
				}
				_maxRotateTime -= _actor.LogicDeltaTime;
				if (_maxRotateTime <= 0)
				{
					base.comboAttack.CancelAttack();
				}
			}
		}

		private void OnLaserCustomEvent(string eventName)
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515001, out var _) && string.Equals(eventName, "ElectricGrid_Start"))
			{
				TSVector2 tSVector = ((_actor.attackTarget != null) ? _actor.attackTarget.tsTransform.Position : _actor.tsTransform.Position);
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_150_Main_Skill_P01_ElectricGrid", tSVector, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private void OnLaserRecoveryBegin()
		{
			_actor.buffComponent.RemoveBuffByBuffId(15004012);
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.buffComponent.RemoveBuffByBuffId(15004012);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 515005, out var _))
			{
				_actor.buffComponent.AddBuff(15005011, _actor);
			}
			_actor.logicVariable.SetLogicTagValue("AdditionalAttrCount_P4", 0);
			_actor.logicVariable.SetLogicTagValue("AdditionalAttrCount_P8", 0);
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			_maxRotateSpeed = 0;
			_maxRotateTime = 0;
			_sweepComboTagQueue?.Clear();
		}
	}
	public class ActionScript_Support : ActionScript
	{
