	public class ActionScript_MainControl : ActionScript
	{
		private FP _holdTime_NormalAttackStage;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_holdTime_NormalAttackStage = 0;
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		protected override void OnButtonDPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				_holdTime_NormalAttackStage = 0;
				return;
			}
			if (_holdTime_NormalAttackStage < Config.holdTime_NormalAttackStage)
			{
				_holdTime_NormalAttackStage += _actor.LogicDeltaTime;
				return;
			}
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			_holdTime_NormalAttackStage = 0;
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		public static DeterministicShape rightShape;

		public static DeterministicShape leftShape;

		public static FP delayTime;

		public static TSVector2 acPos;

		public static float _rotation;

		public static Vector3 _scale;

		public static TSVector2 _target;

		public override void OnEnable()
		{
			base.OnEnable();
			Config_MainControl.linkNum = 2;
			if (GetPerk(514903))
			{
				Config_MainControl.linkNum = 4;
			}
			Config_MainControl.linkRange = Config_MainControl.link_range;
			if (GetPerk(514912))
			{
				Config_MainControl.linkRange = 9.8f;
			}
			if (GetPerk(514911))
			{
				PlayerSkillCd playerSkillCd = (_actor as PlayerAdventureActor).playerSkillCd;
				SkillInfo skillCD = playerSkillCd.GetSkillCD(ActionKey.A);
				playerSkillCd.SetSkillTotalSection(ActionKey.A, skillCD.totalSectionAmount + 1, forceMaxSection: true);
			}
			if (!GetPerk(514913))
			{
				return;
			}
			for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
			{
				if (SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i].actorElementInfo.elementType == GameEnum.elementType.SE)
				{
					_actor.buffComponent.AddBuff(14913011, _actor);
				}
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
		}

		protected override void OnCastSkill(PlayerAdventureActor actor, AdventureActorCastSkillEvent skiillEvet)
		{
			base.OnCastSkill(actor, skiillEvet);
			if (skiillEvet != null && skiillEvet.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B && actor.isAssist && GetPerk(514909))
			{
				_actor.buffComponent.AddBuff(14909011, _actor);
			}
		}

		protected override void OnBeforeHitEvent(AdventureActorReceiveDamageBeforeHitEvent evt)
		{
			base.OnBeforeHitEvent(evt);
			if (evt.from == _actor && evt.to is MonsterAdventureActor monsterAdventureActor)
			{
				if (GetPerk(514906) && monsterAdventureActor.monsterToughnessInfo.isToughnessBroken && CommonUtils.CheckHitByTag(evt.hitDamageTag, Config.damageTag_NormalAtk))
				{
					AdventureActor.AddFromAttr(14906001, _actor);
				}
				if (GetPerk(514908) && monsterAdventureActor.buffComponent.CheckBuffByBuffTag(Config_MainControl.slowBuff_tag))
				{
					AdventureActor.AddFromAttr(14908001, _actor);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			if (GetPerk(514905) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config.damageTag_NormalAtk))
			{
				_actor.buffComponent.AddBuff(14905011, _actor);
			}
		}

		public TSVector2 TransformPoint(Vector2 localPoint)
		{
			TSVector2 tSVector = new TSVector2(localPoint.x * _scale.x, localPoint.y * _scale.z);
			float f = _rotation * ((float)Math.PI / 180f);
			float num = Mathf.Cos(f);
			float num2 = Mathf.Sin(f);
			return new TSVector2(tSVector.x * num - tSVector.y * num2, tSVector.x * num2 + tSVector.y * num) + acPos;
		}

		protected override void LogicUpdate()
		{
			base.LogicUpdate();
			Config_MainControl.mainConcTime -= _actor.LogicDeltaTime;
			if (Config_MainControl.mainConcTime > 0 && !_actor.buffComponent.CheckBuffByBuffID(14900001))
			{
				_actor.buffComponent.AddBuff(14900001, _actor);
			}
			else if (Config_MainControl.mainConcTime < 0 && _actor.buffComponent.CheckBuffByBuffID(14900001))
			{
				_actor.buffComponent.RemoveBuffByBuffId(14900001);
			}
			if (GetPerk(514901))
			{
				if (Config_MainControl.mainConcTime > 0 && !_actor.buffComponent.CheckBuffByBuffID(14901011))
				{
					_actor.buffComponent.AddBuff(14901011, _actor);
				}
				else if (Config_MainControl.mainConcTime < 0 && _actor.buffComponent.CheckBuffByBuffID(14901011))
				{
					_actor.buffComponent.RemoveBuffByBuffId(14901011);
				}
			}
			if (!(delayTime > 0))
			{
				return;
			}
			delayTime -= _actor.LogicDeltaTime;
			if (!(delayTime <= 0))
			{
				return;
			}
			int count = ILRuntimeAPI.GetMonstersFromShape(_actor, rightShape).Count;
			int count2 = ILRuntimeAPI.GetMonstersFromShape(_actor, leftShape).Count;
			Vector2 localPoint = Config_MainControl.L_pos;
			if (count > count2)
			{
				localPoint = Config_MainControl.R_pos;
			}
			else if (count == count2 && count2 + count - 1 < 2)
			{
				localPoint = Config_MainControl.Single_pos;
			}
			else if (count == count2 && count2 + count - 1 >= 2)
			{
				localPoint = Config_MainControl.M_pos;
			}
			long num = (long)_actor.logicVariable.GetLogicTagValue("summonId");
			if (num != 0L)
			{
				LogicEntity logicEntity = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(num);
				if (logicEntity != null)
				{
					(logicEntity as AdventureActor).DestroySelf();
				}
			}
			FP leftTime = Config_MainControl.lifeTime;
			if (GetPerk(514910))
			{
				leftTime = Config_MainControl.time_10;
			}
			SummonCfg summonCfg = new SummonCfg
			{
				summonFollowType = SummonFollowType.NotFollow,
				summonAttrType = SummonAttrType.InheritByInitialSnapshot,
				summonRelation = SummonRelation.Coexisted,
				attrPercent = 100,
				leftTime = leftTime,
				retainWhenCrossLevel = false,
				useSummonHit = true
			};
			TSVector2 tSVector = _target - acPos;
			TSVector2 position = TransformPoint(localPoint);
			_actor.QueryClosestPositionWalkable(position, out var result);
			ILRuntimeAPI.SummonMonster(_actor, 0, 14900011, result, tSVector, summonCfg, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
			{
				_actor.logicVariable.SetLogicTagValue("summonId", monster.Id);
			});
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt(useInputDirectionFirst: true, useSemiAutoBattleMode: true);
			_actor.EnableSuperArmor();
		}

		public void OnStart()
		{
			ParallelScript_MainControl.delayTime = 0;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("149_Skill_Main", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string evt)
		{
			if (string.Equals(evt, "149_Summon_IronMaiden"))
			{
				ParallelScript_MainControl.delayTime = Config_MainControl.summonDelay;
				ParallelScript_MainControl.rightShape = new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Fan,
					position = _actor.tsTransform.Position,
					angle = Config_MainControl.summonAngle / 2,
					rotation = _actor.tsTransform.Right.GetAngle(),
					innerRadius = 0,
					radius = _actor.actorSearchTargetInfo.hearRange
				};
				ParallelScript_MainControl.leftShape = new DeterministicShape
				{
					shapeType = DeterministicShape.ShapeType.Fan,
					position = _actor.tsTransform.Position,
					angle = Config_MainControl.summonAngle / 2,
					rotation = _actor.tsTransform.Left.GetAngle(),
					innerRadius = 0,
					radius = _actor.actorSearchTargetInfo.hearRange
				};
				ParallelScript_MainControl.acPos = _actor.tsTransform.Position;
				ParallelScript_MainControl._rotation = (float)_actor.tsTransform.Rotation;
