namespace AIScript.Character._14701
{
	public class Action : ActorActionBase
	{
		private int normalPhaseCount = 3;

		private int resetNormal = CommonHelper.StringToHash("ResetNormal");

		private PlayerSkillCd _skillManage;

		private ActorSearchTarget actorSearchInfo;

		private IState curState;

		private NormalAttackState normalAttackState = new NormalAttackState();

		private SkillState skillState;

		private List<SkillState> skillList;

		private AimTarget _aimTarget = new AimTarget();

		private int curNormalPhase;

		private int curSkillIndex;

		protected override void OnActionEnable()
		{
			_skillManage = _actor.GetLogicComponent<PlayerSkillCd>();
			actorSearchInfo = _actor.GetLogicComponent<ActorSearchTarget>();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			normalAttackState.Init(_actor, _skillManage, _aimTarget);
			skillList = new List<SkillState>(2)
			{
				new SkillState(),
				new SkillState()
			};
			skillList[0].Init(_actor, _skillManage, _aimTarget);
			skillList[1].Init(_actor, _skillManage, _aimTarget);
			curNormalPhase = 0;
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			Clear();
		}

		public override void OnStart()
		{
			base.OnStart();
			DoMainLogic();
		}

		public void OnUpdate()
		{
			MainLoop();
		}

		public override void OnStop()
		{
			base.OnStop();
			Clear();
		}

		private void Clear()
		{
			_aimTarget.Cancel();
			_actor.movementMode = AdventureActor.MovementMode.Run;
		}

		protected override void OnButtonAPress()
		{
			CastSkill(ActionKey.A, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			CastSkill(ActionKey.B, SkillPhaseFeatureFlag.Skill1);
			_actor.logicVariable.ToggleLogicTag("HoldingKeyD", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable?.ToggleLogicTag("HoldingKeyD", value: false);
		}

		protected override void OnButtonDPress()
		{
			CastSkill(ActionKey.D, SkillPhaseFeatureFlag.Ultimate);
		}

		protected override bool CastIndependentRushSkill()
		{
			return CastSkill(ActionKey.C, SkillPhaseFeatureFlag.Skill2, 0, isInterruptAttack: true, isRushJoinDodge: false);
		}

		private void OnTrCastSkill(IEvent _evt)
		{
			ActorTryCastSkill actorTryCastSkill = _evt as ActorTryCastSkill;
			if (actorTryCastSkill.sender as AdventureActor == _actor)
			{
				CastSkill(ActionKey.None, actorTryCastSkill.flag, actorTryCastSkill.skillId, actorTryCastSkill.isInterruptAttack);
			}
		}

		private bool CastSkill(ActionKey key, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int skillId = 0, bool isInterruptAttack = true, bool isRushJoinDodge = true)
		{
			skillState = SkillPop();
			skillState.SetSkill(key, skillPhaseFeatureFlag, skillId, isInterruptAttack, ingoreCDAndEnergy: false, isRushJoinDodge);
			skillState.Enter();
			if (skillState.CanCast)
			{
				if (key == ActionKey.D || key == ActionKey.None)
				{
					ResetNormalPharse();
				}
				curState?.Exit();
				curState = skillState;
			}
			return skillState.CanCast;
		}

		private void DoMainLogic()
		{
		}

		private void MainLoop()
		{
			_actor.attackTarget = actorSearchInfo.GetLockingConfrontActor(useInputDirection: true);
			curState?.Update();
			if (curState == null || curState.IsEnd)
			{
				curState = GetNextState();
				curState?.Enter();
			}
		}

		private IState GetNextState()
		{
			if (_actor.attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
				bool isObstacleBetweenActorAndTargetAndPreventNormalAttack = base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack;
				bool flag = fP <= CommonUtils.GetAimRange(_actor);
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					if (isObstacleBetweenActorAndTargetAndPreventNormalAttack || !flag)
					{
						_aimTarget.Cancel();
					}
				}
				else if (flag && !(_actor as PlayerAdventureActor).dodgeButtonHold && !isObstacleBetweenActorAndTargetAndPreventNormalAttack)
				{
					_aimTarget.Aim(_actor, _actor.attackTarget as AdventureActor);
				}
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && CommonUtils.GetAttackRange(_actor) > fP)
				{
					curNormalPhase = curNormalPhase % normalPhaseCount + 1;
					_actor.logicVariable.SetLogicTagValue("curNormalPhase", curNormalPhase);
					return normalAttackState;
				}
			}
			else if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
			{
				_aimTarget.Cancel();
			}
			ResetNormalPharse();
			return null;
		}

		private void ResetNormalPharse()
		{
			curNormalPhase = 0;
		}

		private SkillState SkillPop()
		{
			SkillState obj = skillList[curSkillIndex];
			obj.SetSkill(ActionKey.None, SkillPhaseFeatureFlag.None, 0, isInterruptAttack: false);
			curSkillIndex = ++curSkillIndex % 2;
			return obj;
		}

		private void OnCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && adventureActorCustomEvent.eventHashCode == resetNormal)
			{
				ResetNormalPharse();
			}
		}
	}
	public enum fsmStatus
	{
		Enter,
		Exit
	}
	public class IState
	{
		private fsmStatus fsmStatus;

		public AdventureActor _actor;

		public PlayerSkillCd _skillManage;

		public AimTarget _aimTarget;

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public void Init(AdventureActor actor, PlayerSkillCd skillManager, AimTarget aimTarget)
		{
			_actor = actor;
			_skillManage = skillManager;
			_aimTarget = aimTarget;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
		}

		public LogicEntity GetAttackTarget()
		{
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				return CommonUtils.GetAssistantAttackTarget(_actor);
			}
			return _actor.attackTarget;
		}
	}
	public class NormalAttackState : IState
	{
		public override void Enter()
		{
			base.Enter();
			if (!ILRuntimeAPI.CreateSkill(_skillManage.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
			{
				Exit();
			}))
			{
				Exit();
			}
		}

		public override void Update()
		{
			base.Update();
			LogicEntity attackTarget = GetAttackTarget();
			FP fP = _actor.DistanceWithRadius(attackTarget);
			if (attackTarget != null && CommonUtils.GetAttackRange(_actor) > fP && _actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
			{
				_actor.InterruptAttack(force: true);
			}
		}
	}
	public class SkillState : IState
	{
		public ActionKey actionKey;

		public SkillPhaseFeatureFlag skillPhaseFeatureFlag;

		public bool CanCast;

		public int specialSkill;

		public bool isInterruptAttack;

		public bool isRushJoinDodge;

		public bool ingoreCDAndEnergy;

		public override void Enter()
		{
			base.Enter();
			SkillCountdownTiming skillCountdownTiming = SkillCountdownTiming.Start;
			int skillId = ((specialSkill == 0) ? _skillManage.GetCurrentBindSkillId(actionKey) : specialSkill);
			AdventureActor actor = _actor;
			SkillPhaseFeatureFlag skillCastBehaviourType = skillPhaseFeatureFlag;
			SkillCountdownTiming countdownTiming = skillCountdownTiming;
			CanCast = ILRuntimeAPI.CreateSkill(skillId, actor, skillCastBehaviourType, SkillLauncherType.Character, isInterruptAttack, isBreakable: false, countdownTiming, delegate
			{
				Exit();
			}, null, ingoreCDAndEnergy: false, isRushJoinDodge);
		}

		public override void Update()
		{
			base.Update();
			LogicEntity attackTarget = GetAttackTarget();
			FP fP = _actor.DistanceWithRadius(attackTarget);
			if (attackTarget != null && CommonUtils.GetAttackRange(_actor) > fP && _actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
			{
				_actor.InterruptAttack(force: true);
			}
		}

		public void SetSkill(ActionKey actionKey, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int specialSkill, bool isInterruptAttack, bool ingoreCDAndEnergy = false, bool isRushJoinDodge = true)
		{
			this.actionKey = actionKey;
			this.specialSkill = specialSkill;
			this.skillPhaseFeatureFlag = skillPhaseFeatureFlag;
			this.isInterruptAttack = isInterruptAttack;
			this.ingoreCDAndEnergy = ingoreCDAndEnergy;
			this.isRushJoinDodge = isRushJoinDodge;
		}
	}
