			int curCount = 0;
			while (!(bulletKuwu == null) && curCount < count_23)
			{
				shape.length = 0.1;
				shape.width = 5;
				shape.position = bulletKuwu.tsTransform.Position + bulletKuwu.tsTransform.Forward * bulletKuwu.velocitySpeed * 1;
				shape.rotation = bulletKuwu.tsTransform.Rotation;
