		private IEnumerator OnCastAreaEffect(MonsterAdventureActor monster)
		{
			FP fP = radius_22 + monster.GetRadius();
			TSVector2 tSVector = -(monster.tsTransform.Position - _actor.tsTransform.Position).normalized;
			TSVector2 tSVector2 = TrueSyncExtensions.RandomPointInsideFan(monster.tsTransform.Position, fP, fP, tSVector.GetAngle(), 180);
			TSVector2 normalized = (monster.tsTransform.Position - tSVector2).normalized;
			TSVector2 targetPosition2 = TrueSyncExtensions.RandomPointInsideFan(monster.tsTransform.Position, fP, fP, tSVector.GetAngle(), 180);
			TSVector2 dir2 = (monster.tsTransform.Position - targetPosition2).normalized;
			TSVector2 targetPosition3 = TrueSyncExtensions.RandomPointInsideFan(monster.tsTransform.Position, fP, fP, tSVector.GetAngle(), 180);
			TSVector2 dir3 = (monster.tsTransform.Position - targetPosition3).normalized;
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_22_1, tSVector2, normalized.GetAngle(), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return _actor.WaitTime(interval_22);
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_22_2, targetPosition2, dir2.GetAngle(), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			yield return _actor.WaitTime(interval_22);
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_22_3, targetPosition3, dir3.GetAngle(), (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}
	}
