	public class ParallelScript : ParallelBase
	{
		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_NODAMAGE", OnReceiveNoDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
		}

		private void OnCastSkill(IEvent evt)
		{
			AdventureActorCastSkillEvent adventureActorCastSkillEvent = evt as AdventureActorCastSkillEvent;
			if (adventureActorCastSkillEvent.sender as AdventureActor == _actor && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B)
			{
				OnSelfCastSkill(adventureActorCastSkillEvent);
			}
		}

		protected virtual void OnSelfCastSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
		}

		private void OnReceiveAttack(IEvent evt)
		{
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			PlayerAdventureActor playerAdventureActor2 = default(PlayerAdventureActor);
			if (adventureActorReceiveAttackEvent.from is PlayerAdventureActor playerAdventureActor && playerAdventureActor == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor)
			{
				OnSelfAttacked(adventureActorReceiveAttackEvent);
			}
			else if (ActorHelper.IsPlayerSummoned(adventureActorReceiveAttackEvent.from, ref playerAdventureActor2) && playerAdventureActor2 == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor)
			{
				OnSelfSummonedAttacked(adventureActorReceiveAttackEvent);
			}
			else if (adventureActorReceiveAttackEvent.to is PlayerAdventureActor playerAdventureActor3 && playerAdventureActor3 == _actor)
			{
				OnSelfBeAttacked(adventureActorReceiveAttackEvent);
			}
		}

		protected virtual void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		protected virtual void OnSelfSummonedAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		protected virtual void OnSelfBeAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		private void OnReceiveNoDamage(IEvent evt)
		{
			AdventureActorNoDamageEvent adventureActorNoDamageEvent = evt as AdventureActorNoDamageEvent;
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			if (ActorHelper.IsPlayerSummoned(adventureActorNoDamageEvent.from, ref playerAdventureActor) && playerAdventureActor == _actor && Config.hitDamageIdMapping.TryGetValue(adventureActorNoDamageEvent.hitDamageConfigId, out var value))
			{
				AdventureActor adventureActor = adventureActorNoDamageEvent.to as AdventureActor;
				AdventureActor actor = _actor;
				int num = value;
				int uniqueAttackId = adventureActorNoDamageEvent.uniqueAttackId;
				ILRuntimeAPI.HitActor(actor, adventureActor, num, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.None, uniqueAttackId, (GameObject)null);
			}
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from is PlayerAdventureActor playerAdventureActor && playerAdventureActor == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor monsterAdventureActor)
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514441, out var perkLevel) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_Trigger_P41))
				{
					AdventureActor.AddFromAttr(14441001, _actor);
				}
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514443, out perkLevel) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_Trigger_P43) && (monsterAdventureActor.isFrozen || monsterAdventureActor.buffComponent.CheckBuffByBuffTag(Config.buffTag_Cold)))
				{
					AdventureActor.AddFromAttr(14443001, _actor);
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 5) && (monsterAdventureActor.IsBossMonster() || monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE))
				{
					AdventureActor.AddFromAttr(14496511, _actor);
				}
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from is PlayerAdventureActor playerAdventureActor && playerAdventureActor == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor monster)
			{
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 3) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_D3))
				{
					_actor.buffComponent.AddBuff(14496311, _actor);
				}
				OnSelfDamaged(adventureActorReceiveDamageEvent);
				if (CheckCanTriggerWaterMark(monster, adventureActorReceiveDamageEvent.hitDamageTag))
				{
					TriggerWaterMark(monster, adventureActorReceiveDamageEvent.hitDamageTag);
				}
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerWaterMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Water, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster) && CommonUtils.CheckHitByTag(hitDamageTag, Config.damageTag_TriggerWaterMark))
			{
				return true;
			}
			return false;
		}

		private void TriggerWaterMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (!(monster == null))
			{
				monster.buffComponent?.RemoveBuffByTag(CommonDefine.Water);
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_144_WaterTag1_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				HandleColdBuff(monster);
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514441, out var _) && CommonUtils.CheckHitByTag(hitDamageTag, Config.damageTag_Trigger_P41) && TSRandom.Range(0f, 100f) <= CommonUtils.GetScriptValue(_actor, 14441011))
				{
					HandleColdBuff(monster);
				}
				CommonUtils.TriggerElementMarkEvent(CommonDefine.Water, GameEnum.AdventureActorElementTriggerType.WaterElementTriggerType1, _actor, monster, "WaterMark_Trigger_Effect_05");
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 2))
				{
					_actor.buffComponent.AddBuff(14496211, _actor);
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 4))
				{
					_actor.buffComponent.AddBuff(14496411, _actor);
				}
				OnTriggerWarterMark(monster, hitDamageTag);
			}
		}

		private void HandleColdBuff(MonsterAdventureActor monster)
		{
			monster.buffComponent?.AddBuff(4021, _actor);
			if (monster.buffComponent.GetBuffNum(0, 0, Config.buffTag_Cold) >= 3)
			{
				monster.buffComponent.RemoveBuffByTag(Config.buffTag_Cold);
				monster.buffComponent.AddBuff(4100, _actor);
			}
		}

		protected virtual void OnTriggerWarterMark(MonsterAdventureActor target, IList<int> hitDamageTag)
		{
		}

		private void OnActorDied(IEvent evt)
		{
			AdventureActorDiedEvent adventureActorDiedEvent = evt as AdventureActorDiedEvent;
			if (adventureActorDiedEvent.actor is MonsterAdventureActor)
			{
				if (adventureActorDiedEvent.killer is PlayerAdventureActor playerAdventureActor && playerAdventureActor == _actor)
				{
					OnKillTarget(adventureActorDiedEvent);
				}
				OnMonsterDied(adventureActorDiedEvent);
			}
		}

		protected virtual void OnKillTarget(AdventureActorDiedEvent diedEvent)
		{
		}

		protected virtual void OnMonsterDied(AdventureActorDiedEvent diedEvent)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_NODAMAGE", OnReceiveNoDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514411, out var _))
			{
				_actor.EnableDodgeCrossObstacle();
				_actor.buffComponent.AddBuff(14411011, _actor);
			}
		}

		public void OnStart()
		{
			CommonUtils.CheckAndSetDodgeCrossObstacleMode(_actor, Config.realDistance_Dodge, Config.crossAdditionDistance_Dodge, Config.crossKeepAwayNavmeshEdgeDistance_Dodge);
			ComboInputBuffer.ActionKey[] comboKeys_Dodge = Config.comboKeys_Dodge;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboKeys_Dodge, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, Config.duration_Dodge, Config.distance_Dodge, null, comboWithAttack: true);
		}

		private void OnActivationEnd()
		{
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() && Config.transitionRushSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(Config.transitionRushSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
				OnFinish();
			}
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514405, out var perkLevel))
			{
				int num = 5;
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", num);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514411, out perkLevel))
			{
				_actor.DisableDodgeCrossObstacle();
			}
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private int _stage;

		private List<string> _curComboTagList;

		private string _comboTag;

		private bool _canLockTarget;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_stage = (int)(long)_actor.logicVariable.GetLogicTagValue("NormalAttackStage");
			if (_stage < 0)
			{
				NovaLogger.Error($"非法的普攻段数:{_stage}");
				OnFinish();
				return;
			}
			_curComboTagList = Config.comboTagList_NormalAttack;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514401, out var _) && _actor.buffComponent.CheckBuffByBuffID(14401011))
			{
				_curComboTagList = Config_MainControl.comboTagList_NormalAttack_P1;
			}
			_comboTag = ((_stage < _curComboTagList.Count) ? _curComboTagList[_stage] : null);
			_canLockTarget = true;
		}

		public void OnStart()
		{
			if (string.IsNullOrEmpty(_comboTag))
			{
				NovaLogger.Error($"该普攻段数未配置,普攻段数:{_stage}");
				OnFinish();
				return;
			}
			string comboTag = _comboTag;
			LogicEntity attackTarget = _actor.attackTarget;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: true, attackTarget, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnAnticipationEnd()
		{
			int num = _stage + 1;
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", (num < _curComboTagList.Count) ? num : 0);
		}

		public void OnUpdate()
		{
			LockDirection(_canLockTarget ? default(TSVector2) : _actor.tsTransform.Forward);
		}

		private void OnCustomEvent(string eventName)
		{
			int perkLevel;
			if (string.Equals(eventName, "144_S"))
			{
				_canLockTarget = false;
			}
			else if (string.Equals(eventName, "144_AtkInvincibleAdd"))
			{
				_actor.buffComponent.AddBuff(14400001, _actor);
			}
			else if (string.Equals(eventName, "144_AtkInvincibleRemove"))
			{
				_actor.buffComponent.RemoveBuffByBuffId(14400001);
			}
			else if (string.Equals(eventName, "144_Shadow_Atk") && CommonUtils.HavePersonalPerk(_actor.dataID, 514402, out perkLevel) && _actor.buffComponent.CheckBuffByBuffID(14401011))
			{
				TSVector2 tSVector = Config_MainControl.summonOffset_P2[TSRandom.Range(0, Config_MainControl.summonOffset_P2.Count)];
				TSVector2 tSVector2 = _actor.tsTransform.Position + _actor.tsTransform.Left * tSVector.x + _actor.tsTransform.Forward * tSVector.y;
				TSVector2 tSVector3 = _actor.tsTransform.Forward;
				if (_actor.attackTarget != null)
				{
					tSVector3 = (_actor.attackTarget.tsTransform.Position - tSVector2).normalized;
				}
				ILRuntimeAPI.SummonMonster(_actor, 0, 14401111, tSVector2, tSVector3, Config.summonCfg_Summon, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor summoned)
				{
					summoned.logicVariable.SetLogicTagValue("DelayUseSkillTime_Summon", Config_MainControl.summonedDelayUseSkillTime_P2);
					summoned.logicVariable.SetLogicTagStringValue("SkillComboTag_Summon", _comboTag);
					summoned.attackTarget = _actor.attackTarget;
					summoned.logicVariable.ToggleLogicTag("SummonFinish_Summon", value: true);
				});
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.buffComponent.RemoveBuffByBuffId(14400001);
			_stage = 0;
			_comboTag = null;
		}
	}
	public class SkillScript_Rush : SkillAdvancedBase
	{
		private Skill_Rush _skillRush;

		protected override void OnSkillEnable()
