	public class SkillScript_Summon : SkillAdvancedBase
	{
		private string _comboTag;

		private bool _closeBlock;

		private bool _openCrossObstacleMode;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_comboTag = _actor.logicVariable.GetLogicTagStringValue("SkillComboTag_Summon");
			_closeBlock = _actor.logicVariable.GetLogicTagToggle("CloseBlock_Summon");
			_openCrossObstacleMode = _actor.logicVariable.GetLogicTagToggle("OpenCrossObstacleMode_Summon");
			if (_closeBlock)
			{
				_actor.EnableCloseBlock();
			}
			if (_openCrossObstacleMode)
			{
				CommonUtils.EnableCrossObstacleMode(_actor);
			}
		}

		public void OnStart()
		{
			if (string.IsNullOrEmpty(_comboTag))
			{
				OnFinish();
				return;
			}
			if (_openCrossObstacleMode)
			{
				CommonUtils.CheckAndSetCrossObstacleMode(_actor, Config_MainControl.realMoveDistance_Skill, Config_MainControl.crossAdditionDistance_Skill, Config_MainControl.crossKeepAwayNavmeshEdgeDistance_Skill);
			}
			string comboTag = _comboTag;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			if (_closeBlock)
			{
				_actor.DisableCloseBlock();
			}
			if (_openCrossObstacleMode)
			{
				CommonUtils.DisableCrossObstacleMode(_actor);
				CommonUtils.ClearCrossObstacleMode(_actor);
			}
			_comboTag = null;
			_closeBlock = false;
			_openCrossObstacleMode = false;
		}
	}
	public class SpawnScript_Summon : AIBase
	{
		private PlayFX _playFX;

		private CoroutineNode _spawnLogicCor;

		public void OnStart()
		{
			_actor.Hide();
			_spawnLogicCor = _actor.StartLogicCoroutine(SpawnLogic(), runImmediately: true);
		}

		private IEnumerator SpawnLogic()
		{
			while (!_actor.logicVariable.GetLogicTagToggle("SummonFinish_Summon"))
			{
				yield return null;
			}
			string logicTagStringValue = _actor.logicVariable.GetLogicTagStringValue("SpawnFx_Summon");
			if (!string.IsNullOrEmpty(logicTagStringValue))
			{
				if (_playFX == null)
				{
					_playFX = new PlayFX();
				}
				else
				{
					_playFX.Clear();
				}
				_playFX.Play(_actor, null, logicTagStringValue, default(FP), _actor.tsTransform.Position, default(TSVector2));
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.1f));
			}
			_actor.Visible();
			_actor.Action();
		}

		public void OnStop()
		{
			if (_spawnLogicCor == null)
			{
				_actor.StopLogicCoroutine(_spawnLogicCor);
			}
			_spawnLogicCor = null;
		}
	}
