	public class ParallelScript_Support : ParallelScript
	{
		private int _killCount_P28;

		private HashSet<long> _attackDamageUniqueIdSet_P29;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514433, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.WE)
					{
						_actor.buffComponent.AddBuff(14433011, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REMOVE_BUFF", OnBuffRemoved);
		}

		private void OnBuffRemoved(IEvent evt)
		{
			AdventureActorRemoveBuff adventureActorRemoveBuff = evt as AdventureActorRemoveBuff;
			if (adventureActorRemoveBuff.sender as AdventureActor is MonsterAdventureActor monsterAdventureActor && CommonUtils.HavePersonalPerk(_actor.dataID, 514424, out var _) && adventureActorRemoveBuff.eventInfo.buffId == 14424011)
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14401_B2P24_DelayFlash", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		protected override void OnSelfCastSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
			base.OnSelfCastSkill(castSkillEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514428, out var perkLevel))
			{
				_killCount_P28 = 0;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514429, out perkLevel))
			{
				_attackDamageUniqueIdSet_P29?.Clear();
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514429, out var _) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P29))
			{
				if (_attackDamageUniqueIdSet_P29 == null)
				{
					_attackDamageUniqueIdSet_P29 = new HashSet<long>();
				}
				_attackDamageUniqueIdSet_P29.Add(attackEvent.uniqueAttackId);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514421, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P21))
			{
				AdventureActor.AddFromAttr(14421011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514422, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P22))
			{
				AdventureActor.AddFromAttr(14422011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514425, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P25))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(14425011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(14425002, _actor, buffNumByID);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514426, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P26))
			{
				int num = _actor.logicVariable.GetLogicTagValue("SkillAttackTimes").AsInt();
				if (num > 0)
				{
					AdventureActor.AddFromAttr(14426002, _actor, num);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514428, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P28))
			{
				AdventureActor.AddFromAttr(14428001, _actor);
				if (_killCount_P28 > 0)
				{
					AdventureActor.AddFromAttr(14428002, _actor, _killCount_P28);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514429, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P29) && _attackDamageUniqueIdSet_P29 != null && _attackDamageUniqueIdSet_P29.Count > 0)
			{
				AdventureActor.AddFromAttr(14429001, _actor, _attackDamageUniqueIdSet_P29.Count);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514430, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P30))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 14430011);
				if (monsterAdventureActor.actorHealthInfo.hpPercentage * 100 < scriptValue)
				{
					AdventureActor.AddFromAttr(14430001, _actor);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514431, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P31))
			{
				AdventureActor.AddFromAttr(14431001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514424, out var _) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P24))
			{
				if (monsterAdventureActor.buffComponent.CheckBuffByBuffID(14424011))
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14401_B2P24_DelayFlash", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
				monsterAdventureActor.buffComponent.AddBuff(14424011, _actor);
			}
		}

		protected override void OnKillTarget(AdventureActorDiedEvent diedEvent)
		{
			base.OnKillTarget(diedEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514428, out var _))
			{
				_killCount_P28++;
			}
		}

		protected override void OnMonsterDied(AdventureActorDiedEvent diedEvent)
		{
			base.OnMonsterDied(diedEvent);
			MonsterAdventureActor monsterAdventureActor = diedEvent.actor as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514424, out var _) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(14424011))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14401_B2P24_DelayFlash", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private void Clear()
		{
			_killCount_P28 = 0;
			_attackDamageUniqueIdSet_P29?.Clear();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnBuffRemoved);
			Clear();
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		private int _totalAttackTimes;

		private int _attackTimes;

		private bool _beforeAttackActivation;

		private string _attackAreaEffectKey;

		private PlayFX _playFX;

		private CoroutineNode _attackIntervalCor;

		private CoroutineNode _summonCor;

		private bool _canTrigger_P22;

		private CoroutineNode _perkLogicCor_P23;

		private FP _lastTriggerTime_P25;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_attackTimes = 0;
			_totalAttackTimes = 3;
			_beforeAttackActivation = false;
			_attackAreaEffectKey = null;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514421, out var perkLevel))
			{
				_totalAttackTimes += 2;
			}
			_actor.logicVariable.SetLogicTagValue("SkillAttackTimes", 0);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514423, out perkLevel))
			{
				_perkLogicCor_P23 = _actor.StartLogicCoroutine(PerkLogic_P23());
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514427, out perkLevel))
			{
				_totalAttackTimes++;
			}
			UpdateAttackTarget();
			DefaultLookAt();
		}

		public void OnStart()
		{
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("144_B2_Start", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, delegate
			{
				Attack();
			});
			_actor.ReplaceAnimationGroup();
			_summonCor = _actor.StartLogicCoroutine(Summon());
		}

		private void UpdateAttackTarget()
		{
			if (!CheckTargetIegal())
			{
				_actor.attackTarget = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor?.attackTarget;
				if (!CheckTargetIegal())
				{
					_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: false, dontLostTarget: false, sortByAngle: true);
				}
			}
		}

		private bool CheckTargetIegal()
		{
			if (_actor.attackTarget == null)
			{
				return false;
			}
			if (_actor.attackTarget.IsDead())
			{
				return false;
			}
			if (_actor.attackTarget.IsSearchedImmunity())
			{
				return false;
			}
			return _actor.DistanceWithRadius(_actor.attackTarget) <= _actor.actorSearchTargetInfo.hearAttackRange;
		}

		private IEnumerator Summon()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.delayTime_Summon_Skill));
			for (int i = 0; i < 3; i++)
			{
				TSVector2 tSVector = Config_Support.summonOffsetList_Skill[TSRandom.Range(0, Config_Support.summonOffsetList_Skill.Count)];
				TSVector2 result = _actor.tsTransform.Position + _actor.tsTransform.Left * tSVector.x + _actor.tsTransform.Forward * tSVector.y;
				if (!_actor.QueryPositionWalkable(result))
				{
					_actor.QueryClosestPositionWalkable(result, out result);
				}
				TSVector2 tSVector2 = ((_actor.attackTarget != null) ? (_actor.attackTarget.tsTransform.Position - result).normalized : _actor.tsTransform.Forward);
				ILRuntimeAPI.SummonMonster(_actor, 0, 14401111, result, tSVector2, Config.summonCfg_Summon, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor summoned)
				{
					summoned.logicVariable.SetLogicTagStringValue("SpawnFx_Summon", "fx_14401_base_B2_Skill_chuxian");
					summoned.logicVariable.SetLogicTagValue("DelayUseSkillTime_Summon", Config_Support.summonedDelayUseSkillTime_Skill);
					summoned.logicVariable.SetLogicTagStringValue("SkillComboTag_Summon", "144_B2_Shadow_Atk");
					summoned.logicVariable.ToggleLogicTag("CloseBlock_Summon", value: true);
					summoned.attackTarget = _actor.attackTarget;
					summoned.logicVariable.ToggleLogicTag("SummonFinish_Summon", value: true);
				});
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.summonInterval_Skill));
			}
		}

		private void Attack(bool interruptAttack = false)
		{
			_attackTimes++;
			_beforeAttackActivation = true;
			_canTrigger_P22 = false;
			_attackAreaEffectKey = "AreaEffect_14401_B2_Skill_MomentarySlash";
			UpdateAttackTarget();
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onActivationEnd = OnAttackActivationEnd;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("144_B2_Attack", flushInputedKeys: true, interruptAttack, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onInterrupt, onCustomEvent, onActivationEnd);
			int num = _actor.logicVariable.GetLogicTagValue("SkillAttackTimes").AsInt();
			_actor.logicVariable.SetLogicTagValue("SkillAttackTimes", num + 1);
			if (_attackTimes < _totalAttackTimes)
			{
				if (_attackIntervalCor != null)
				{
					_actor.StopLogicCoroutine(_attackIntervalCor);
				}
				_attackIntervalCor = _actor.StartLogicCoroutine(AttackInterval());
			}
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "144_B2_Atmos"))
			{
				if (_playFX == null || !_playFX.isPlaying)
				{
					_playFX = new PlayFX();
					_playFX.Play(_actor, _skill, "fx_14401_base_B2_Skill_badao", default(FP), _actor.tsTransform.Position, default(TSVector2));
				}
			}
			else if (string.Equals(eventName, "144_B2_MomentarySlash"))
			{
				if (!string.IsNullOrEmpty(_attackAreaEffectKey))
				{
					TSVector2 position = _actor.tsTransform.Position;
					if (_actor.attackTarget != null)
					{
						position = _actor.attackTarget.tsTransform.Position;
					}
					else if (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor is PlayerAdventureActor playerAdventureActor && playerAdventureActor.attackTarget != null)
					{
						position = playerAdventureActor.attackTarget.tsTransform.Position;
					}
					else
					{
						position += _actor.tsTransform.Forward * Config_Support.areaEffectOffset_NoTarget_Skill;
					}
					ILRuntimeAPI.PlayAreaEffect(_actor, _attackAreaEffectKey, position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
			}
			else if (string.Equals(eventName, "144_B2_AtmosClear"))
			{
				_playFX?.Stop();
				_playFX?.Clear();
			}
		}

		private void OnAttackActivationEnd()
		{
			_beforeAttackActivation = false;
			if (_canTrigger_P22)
			{
				_attackAreaEffectKey = "AreaEffect_14401_B2P22_Skill_MomentarySlash";
				if (_attackTimes >= _totalAttackTimes)
				{
					Action<string> onCustomEvent = OnCustomEvent;
					System.Action onActivationEnd = EndAttack;
					System.Action onInterrupt = OnInterrupt;
					BeginAttack("144_B2_Attack", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onInterrupt, onCustomEvent, onActivationEnd);
				}
				else
				{
					Action<string> onCustomEvent = OnCustomEvent;
					System.Action onInterrupt = OnInterrupt;
					BeginAttack("144_B2_Attack", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onInterrupt, onCustomEvent);
				}
				int num = _actor.logicVariable.GetLogicTagValue("SkillAttackTimes").AsInt();
				_actor.logicVariable.SetLogicTagValue("SkillAttackTimes", num + 1);
				_canTrigger_P22 = false;
			}
			else if (_attackTimes >= _totalAttackTimes)
			{
				EndAttack();
			}
		}

		private IEnumerator AttackInterval()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.attackInterval_Skill));
			Attack(interruptAttack: true);
		}

		protected override void OnReceiveDamage(IEvent evt)
		{
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.from == _actor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514422, out var perkLevel) && _beforeAttackActivation && !_canTrigger_P22)
			{
				_canTrigger_P22 = adventureActorReceiveDamageEvent.isCrit && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P22);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514425, out perkLevel))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 14425011);
				if ((_lastTriggerTime_P25 <= 0 || _actor.LogicTime - _lastTriggerTime_P25 > scriptValue) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P25))
				{
					_actor.buffComponent.AddBuff(14425011, _actor);
					_lastTriggerTime_P25 = _actor.LogicTime;
				}
			}
		}

		private void EndAttack()
		{
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("144_B2_Connect", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
			_actor.ResumeAnimationGroup();
		}

		private IEnumerator PerkLogic_P23()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.summonDelay_P23));
			for (int groupIndex = 0; groupIndex < 3; groupIndex++)
			{
				for (int memberIndex = 0; memberIndex < 2; memberIndex++)
				{
					AdventureActor adventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as AdventureActor;
					if (adventureActor != null)
					{
						TSVector2 tSVector = adventureActor.tsTransform.Position + adventureActor.tsTransform.Forward * Config_Support.summoneOffset_NoTarget_P23;
						TSVector2 tSVector2 = adventureActor.tsTransform.Forward;
						LogicEntity target = adventureActor.attackTarget ?? ILRuntimeAPI.GetTargetNearByRange(adventureActor, Config_Support.searchRadius_NoTarget_P23);
						if (target != null)
						{
							FP radius = target.GetRadius();
							DeterministicShape shape = new DeterministicShape
							{
								shapeType = DeterministicShape.ShapeType.Fan,
								position = target.tsTransform.Position,
								rotation = target.tsTransform.Rotation,
								innerRadius = radius + Config_Support.summonInnerRadius_P23,
								radius = radius + Config_Support.summonOuterRadius_P23,
								angle = Config_Support.summonAngle_P23
							};
							tSVector = ILRuntimeAPI.GetRandomPointInShape(_actor, shape);
							tSVector2 = (target.tsTransform.Position - tSVector).normalized;
						}
						ILRuntimeAPI.SummonMonster(_actor, 0, 14401111, tSVector, tSVector2, Config.summonCfg_Summon, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor summoned)
						{
							summoned.logicVariable.SetLogicTagStringValue("SpawnFx_Summon", "fx_14401_base_B2_Skill_chuxian");
							summoned.logicVariable.SetLogicTagValue("DelayUseSkillTime_Summon", Config_Support.summonedDelayUseSkillTime_Skill);
							summoned.logicVariable.SetLogicTagStringValue("SkillComboTag_Summon", "144_B2P23_Shadow_Atk");
							summoned.logicVariable.ToggleLogicTag("CloseBlock_Summon", value: true);
							summoned.attackTarget = target;
							summoned.logicVariable.ToggleLogicTag("SummonFinish_Summon", value: true);
						});
					}
					if (memberIndex + 1 < 2)
					{
						yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.summonInterval_EveryMember_P23));
					}
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.summonInterval_EveryGroup_P23));
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_attackAreaEffectKey = null;
			_playFX?.Stop();
			_playFX?.Clear();
			if (_summonCor != null)
			{
				_actor.StopLogicCoroutine(_summonCor);
			}
			_summonCor = null;
			if (_attackIntervalCor != null)
			{
				_actor.StopLogicCoroutine(_attackIntervalCor);
			}
			_attackIntervalCor = null;
			if (_perkLogicCor_P23 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P23);
			}
			_perkLogicCor_P23 = null;
			_actor.buffComponent.RemoveBuffByBuffId(14425011);
			_lastTriggerTime_P25 = 0;
			_actor.ResumeAnimationGroup();
			_attackTimes = 0;
		}
	}
}
namespace AIScript.Character._14301
