	public class ParallelScript : ParallelBase
	{
		public override void OnEnable()
		{
			base.OnEnable();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnReceiveAttack(IEvent evt)
		{
			if (evt is AdventureActorReceiveAttackEvent { from: PlayerAdventureActor playerAdventureActor } adventureActorReceiveAttackEvent && playerAdventureActor == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor)
			{
				OnSelfAttack(adventureActorReceiveAttackEvent);
			}
		}

		protected virtual void OnSelfAttack(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			if (evt is AdventureActorReceiveDamageBeforeHitEvent { from: PlayerAdventureActor playerAdventureActor } adventureActorReceiveDamageBeforeHitEvent && playerAdventureActor == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor)
			{
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from is PlayerAdventureActor playerAdventureActor && playerAdventureActor == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor monster)
			{
				OnSelfDamaged(adventureActorReceiveDamageEvent);
				if (CheckCanTriggerWindMark(monster, adventureActorReceiveDamageEvent.hitDamageTag))
				{
					TriggerWindMark(monster, adventureActorReceiveDamageEvent.hitDamageTag);
				}
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerWindMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null || hitDamageTag.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Wind, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster) && CommonUtils.CheckHitByTag(hitDamageTag, Config.damageTag_TriggerWindMark))
			{
				return true;
			}
			return false;
		}

		private void TriggerWindMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_143_WindTagTrigger_QiXuan", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			monster.buffComponent.RemoveBuffByTag(CommonDefine.Wind);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.Wind, GameEnum.AdventureActorElementTriggerType.WindElementTriggerType1, _actor, monster, "WindMark_Trigger_Effect_04");
			OnTriggerWindMark(hitDamageTag);
		}

		protected virtual void OnTriggerWindMark(IList<int> hitDamageTag)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514311, out var perkLevel))
			{
				_actor.buffComponent.AddBuff(14311011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514313, out perkLevel))
			{
				_actor.EnableDodgeCrossObstacle();
				_actor.buffComponent.AddBuff(14313011, _actor);
			}
		}

		public void OnStart()
		{
			CommonUtils.CheckAndSetDodgeCrossObstacleMode(_actor, Config.realDistance_Dodge, Config.crossAdditionDistance_Dodge, Config.crossKeepAwayNavmeshEdgeDistance_Dodge);
			ComboInputBuffer.ActionKey[] comboKeys_Dodge = Config.comboKeys_Dodge;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboKeys_Dodge, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, Config.duration_Dodge, Config.distance_Dodge, null, comboWithAttack: true);
		}

		private void OnActivationEnd()
		{
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() && Config.transitionRushSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(Config.transitionRushSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
				OnFinish();
			}
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514313, out var _))
			{
				_actor.DisableDodgeCrossObstacle();
			}
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private string _normalAttackStageTag;

		private int _nextNormalAttackStage;

		private AimTarget _aimTarget;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			string comboTag = GetComboTag(out _normalAttackStageTag, out _nextNormalAttackStage);
			if (string.IsNullOrEmpty(comboTag))
			{
				_skill.Clear();
				return;
			}
			System.Action onAnticipationEnd = OnAnticipationEnd;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt, onCustomEvent);
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = string.Equals(_normalAttackStageTag, "NormalAttackStage_Range");
			if (string.Equals(_normalAttackStageTag, "NormalAttackStage_Melee"))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage_Range", 0);
			}
			else
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage_Melee", 0);
			}
		}

		private string GetComboTag(out string normalAttackStageTag, out int nextNormalAttackStage)
		{
			List<string> list = Config.comboTagList_NormalAttack_Melee;
			normalAttackStageTag = "NormalAttackStage_Melee";
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) > Config.distance_SwitchAttackMode)
			{
				list = Config.comboTagList_NormalAttack_Range;
				normalAttackStageTag = "NormalAttackStage_Range";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514310, out var _))
				{
					list = Config_MainControl.comboTagList_NormalAttack_Range_P10;
				}
			}
			int num = _actor.logicVariable.GetLogicTagValue(normalAttackStageTag).AsInt();
			num = TSMath.Clamp(num, 0, list.Count - 1).AsInt();
			nextNormalAttackStage = num + 1;
			nextNormalAttackStage = ((nextNormalAttackStage < list.Count) ? nextNormalAttackStage : 0);
			return list[num];
		}

		public void OnUpdate()
		{
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			TSVector2 tSVector = _actor.tsTransform.Forward;
			if (_actor.attackTarget != null)
			{
				tSVector = _actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position;
			}
			tSVector.Normalize();
			if (_actor.aimMode != AdventureActor.AimMode.LockDirection)
			{
				_aimTarget.Aim(_actor, null, tSVector);
			}
			else
			{
				_actor.tsTransform.Forward = tSVector;
			}
		}

		private void OnAnticipationEnd()
		{
			if (!string.IsNullOrEmpty(_normalAttackStageTag) && _nextNormalAttackStage >= 0)
			{
				_actor.logicVariable.SetLogicTagValue(_normalAttackStageTag, _nextNormalAttackStage);
			}
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "143NrmAtkP1") && CommonUtils.HavePersonalPerk(_actor.dataID, 514301, out var _) && _actor.buffComponent.CheckBuffByBuffID(14301011))
			{
				TSVector2 item = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_MainControl.tornadoOffset_P1;
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = Config_MainControl.eventHashCode_GenerateTornado_MainControl;
				if (adventureActorCustomEvent.tsVector2ParamList != null)
				{
					adventureActorCustomEvent.tsVector2ParamList.Add(item);
				}
				else
				{
					adventureActorCustomEvent.tsVector2ParamList = new List<TSVector2> { item };
				}
				if (adventureActorCustomEvent.stringParamList != null)
				{
					adventureActorCustomEvent.stringParamList.Add("AreaEffect_143_P1P2_LongJuanFeng");
				}
				else
				{
					adventureActorCustomEvent.stringParamList = new List<string> { "AreaEffect_143_P1P2_LongJuanFeng" };
				}
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = false;
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			_normalAttackStageTag = null;
			_nextNormalAttackStage = 0;
		}
	}
	public class SkillScript_Rush : SkillAdvancedBase
	{
		private Skill_Rush _skillRush;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
