	public class ActionScript_MainControl : ActionScript
	{
		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514311, out var _))
			{
				SkillInfo skillCD = _playerSkillCd.GetSkillCD(ActionKey.A);
				if (skillCD != null)
				{
					_playerSkillCd.SetSkillTotalSection(ActionKey.A, skillCD.totalSectionAmount + 1, forceMaxSection: true);
				}
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.A);
			}
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				ResetNormalAttackStage();
			}
			_actor.logicVariable.ToggleLogicTag("HoldingKeyB", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable.ToggleLogicTag("HoldingKeyB", value: false);
		}

		protected override void OnButtonDPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				ResetNormalAttackStage();
			}
		}

		public override void OnUpdate()
		{
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			if (_actor.movementState != ActorState.StandBy && _actor.movementState != ActorState.Dodge && !_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				ResetNormalAttackStage();
			}
			base.OnUpdate();
		}

		private void ResetNormalAttackStage()
		{
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage_Melee", 0);
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage_Range", 0);
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ResetNormalAttackStage();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private FP _lastTriggerTime_P9;

		public override void OnEnable()
		{
			base.OnEnable();
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("AREA_EFFECT_BEGIN", OnAreaEffectBegin);
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor bEntity = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514303, out var perkLevel) && _actor.DistanceWithRadius(bEntity) > Config.distance_SwitchAttackMode)
			{
				AdventureActor.AddFromAttr(14303011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514304, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P4))
			{
				AdventureActor.AddFromAttr(14304011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514305, out perkLevel) && _actor.DistanceWithRadius(bEntity) <= Config.distance_SwitchAttackMode)
			{
				AdventureActor.AddFromAttr(14305001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514306, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P6))
			{
				AdventureActor.AddFromAttr(14306001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514308, out perkLevel))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(14308011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(14308001, _actor, buffNumByID);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514307, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P7))
			{
				_actor.buffComponent.AddBuff(14307011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514309, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P9))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 14309011);
				if (_lastTriggerTime_P9 <= 0 || _actor.LogicTime - _lastTriggerTime_P9 > scriptValue)
				{
					_actor.buffComponent.AddBuff(14309011, _actor);
					_lastTriggerTime_P9 = _actor.LogicTime;
				}
			}
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			AdventureActorCustomEvent adventureActorCustomEvent = evt as AdventureActorCustomEvent;
			if (adventureActorCustomEvent.eventHashCode != Config_MainControl.eventHashCode_GenerateTornado_MainControl)
			{
				return;
			}
			string text = ((adventureActorCustomEvent.stringParamList != null && adventureActorCustomEvent.stringParamList.Count > 0) ? adventureActorCustomEvent.stringParamList[0] : null);
			if (string.IsNullOrEmpty(text) || adventureActorCustomEvent.tsVector2ParamList == null || adventureActorCustomEvent.tsVector2ParamList.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < adventureActorCustomEvent.tsVector2ParamList.Count; i++)
			{
				TSVector2 tSVector = adventureActorCustomEvent.tsVector2ParamList[i];
				TSVector2 tSVector2 = _actor.tsTransform.Forward;
				if (_actor.attackTarget != null)
				{
					tSVector2 = _actor.attackTarget.tsTransform.Position - tSVector;
				}
				ILRuntimeAPI.PlayAreaEffect(_actor, text, tSVector, tSVector2.GetAngle(), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514301, out var perkLevel))
				{
					_actor.buffComponent.AddBuff(14301012, _actor);
				}
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514302, out perkLevel))
				{
					_actor.buffComponent.AddBuff(14302011, _actor);
				}
			}
		}

		private void OnAreaEffectBegin(IEvent evt)
		{
			AdventureAreaEffectBeginEvent adventureAreaEffectBeginEvent = evt as AdventureAreaEffectBeginEvent;
			if (!(adventureAreaEffectBeginEvent.owner == _actor))
			{
				return;
			}
			AreaEffectEntity areaEffectEntity = adventureAreaEffectBeginEvent.sender as AreaEffectEntity;
			if (!areaEffectEntity.CheckTag(Config_MainControl.areaEffectTag_Trigger_P12))
			{
				return;
			}
			AreaEffect_AttackComponent areaEffectComponent = areaEffectEntity.GetAreaEffectComponent<AreaEffect_AttackComponent>();
			if (!(areaEffectComponent != null))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514312, out var _))
			{
				areaEffectComponent.blockBullet = true;
				if (areaEffectComponent.blockBulletCriteriaInfo != null)
				{
					areaEffectComponent.blockBulletCriteriaInfo.operationType = TargetFilterCriteriaInfo.OperationType.And;
					if (areaEffectComponent.blockBulletCriteriaInfo.filterCriteriaList == null)
					{
						areaEffectComponent.blockBulletCriteriaInfo.filterCriteriaList = new List<TargetFilterCriteriaInfo.TargetFilterCriteria>(1);
					}
					else
					{
						areaEffectComponent.blockBulletCriteriaInfo.filterCriteriaList.Clear();
					}
					areaEffectComponent.blockBulletCriteriaInfo.filterCriteriaList.Add(new TargetFilterCriteriaInfo.TargetFilterCriteria
					{
						targetType = TargetFilterCriteriaInfo.TargetTypeMapping.Enemy
					});
				}
				else
				{
					areaEffectComponent.blockBulletCriteriaInfo = new TargetFilterCriteriaInfo
					{
						operationType = TargetFilterCriteriaInfo.OperationType.And,
						filterCriteriaList = new List<TargetFilterCriteriaInfo.TargetFilterCriteria>
						{
							new TargetFilterCriteriaInfo.TargetFilterCriteria
							{
								targetType = TargetFilterCriteriaInfo.TargetTypeMapping.Enemy
							}
						}
					};
				}
				areaEffectComponent.blockFinishFx = _actor.comboGroup.relatedResourceConfig.GetFXByAlias("");
			}
			else
			{
				areaEffectComponent.blockBullet = false;
				areaEffectComponent.blockBulletCriteriaInfo = null;
				areaEffectComponent.blockFinishFx = null;
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_BEGIN", OnAreaEffectBegin);
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private AimTarget _aimTarget;

		private List<TSVector2> _shootVectorList;

		private int _loopTimes;

		private PlayerSkillCd _playerSkillCd;

		private int _shootIndex;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt();
			if (_shootVectorList == null)
			{
				InitShootVector();
			}
			_playerSkillCd = _actor.GetLogicComponent<PlayerSkillCd>();
			_loopTimes = 0;
			_shootIndex = 0;
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			else
			{
				_aimTarget.Cancel();
			}
			_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514308, out var _))
			{
				_actor.buffComponent.AddBuff(14308011, _actor);
			}
		}

		private void InitShootVector()
		{
			_shootVectorList = new List<TSVector2>();
			int num = 60;
			TSVector2 tSVector = TSVector2.Rotate(_actor.tsTransform.Forward, -Config_MainControl.startAngeleOffset_Skill).normalized * Config_MainControl.shootRadius_Skill;
			for (int i = 0; i < 6; i++)
			{
				int num2 = -num * i;
				if (num2 != 0)
				{
					_shootVectorList.Add(TSVector2.Rotate(tSVector, num2));
				}
				else
				{
					_shootVectorList.Add(tSVector);
				}
			}
		}

		public void OnStart()
		{
			string text = "Skill_Mian_SheZhan";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514305, out var _))
			{
				text = "Skill_Mian_SheZhan_P5";
			}
			string actionTag = text;
			System.Action onComboLoop = OnComboLoop;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, null, fadeOutAnim: false, onComboLoop);
		}

		private void OnComboLoop()
		{
			_loopTimes++;
			if (_actor.logicVariable.GetLogicTagToggle("HoldingKeyB") && _playerSkillCd.GetSkillSection(_skill.skillId) > 0)
			{
				if (_loopTimes > 1)
				{
					_playerSkillCd.ReduceSkillSection(_skill.skillId);
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 514308, out var _))
					{
						_actor.buffComponent.AddBuff(14308011, _actor);
					}
				}
			}
			else
			{
				base.comboAttack?.CancelAttack();
			}
		}

		private void OnCustomEvent(string eventName)
		{
			int perkLevel;
			if (string.Equals(eventName, "143SkillMainShot"))
			{
				if (_shootVectorList.Count <= 0)
				{
					return;
				}
				int num = _shootVectorList.Count - 1;
				_shootIndex = TSMath.Clamp(_shootIndex, 0, num).AsInt();
				TSVector2 tSVector = _actor.tsTransform.Position + _shootVectorList[_shootIndex];
				TSVector2 normalized = _shootVectorList[_shootIndex].normalized;
				if (_actor.attackTarget != null)
				{
					normalized = (_actor.attackTarget.tsTransform.Position - tSVector).normalized;
				}
				Shoot(tSVector, normalized);
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514304, out perkLevel))
				{
					int num2 = _shootIndex;
					if (_shootVectorList.Count > 1)
					{
						int num3 = _shootVectorList.Count / 2;
						num2 += num3;
						num2 = ((num2 > num) ? (num2 - 2 * num3) : num2);
					}
					TSVector2 tSVector2 = _actor.tsTransform.Position + _shootVectorList[num2];
					TSVector2 normalized2 = _shootVectorList[num2].normalized;
					if (_actor.attackTarget != null)
					{
						normalized2 = (_actor.attackTarget.tsTransform.Position - tSVector2).normalized;
					}
					Shoot(tSVector2, normalized2);
				}
				_shootIndex++;
				_shootIndex = ((_shootIndex <= num) ? _shootIndex : 0);
			}
			else if (string.Equals(eventName, "143SkillMainP2") && CommonUtils.HavePersonalPerk(_actor.dataID, 514302, out perkLevel))
			{
				TSVector2 item = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_MainControl.tornadoOffsetLeft_P2.x + _actor.tsTransform.Forward * Config_MainControl.tornadoOffsetLeft_P2.y;
				TSVector2 item2 = _actor.tsTransform.Position + _actor.tsTransform.Right * Config_MainControl.tornadoOffsetRight_P2.x + _actor.tsTransform.Forward * Config_MainControl.tornadoOffsetRight_P2.y;
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = Config_MainControl.eventHashCode_GenerateTornado_MainControl;
				if (adventureActorCustomEvent.tsVector2ParamList != null)
				{
					adventureActorCustomEvent.tsVector2ParamList.Add(item);
					adventureActorCustomEvent.tsVector2ParamList.Add(item2);
				}
				else
				{
					adventureActorCustomEvent.tsVector2ParamList = new List<TSVector2> { item, item2 };
				}
				if (adventureActorCustomEvent.stringParamList != null)
				{
					adventureActorCustomEvent.stringParamList.Add("AreaEffect_143_P1P2_LongJuanFeng");
				}
				else
				{
					adventureActorCustomEvent.stringParamList = new List<string> { "AreaEffect_143_P1P2_LongJuanFeng" };
				}
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void Shoot(TSVector2 shootPosition, TSVector2 shootDirection)
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514303, out var _))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_143_SkillMain_P3_JiGuang", shootPosition, shootDirection.GetAngle(), (Action<AreaEffectEntity>)delegate(AreaEffectEntity areaEffect)
				{
					areaEffect.tsTransform.PositionY += Config_MainControl.shootPositionY_Skill;
				}, (AdventureActor)null);
			}
			else
			{
				ILRuntimeAPI.ShootByDirection("Bullet_143_SkillMain_Base", _actor, default(FP), shootDirection, shootPosition, Config_MainControl.shootPositionY_Skill);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514301, out var perkLevel))
			{
				_actor.buffComponent.AddBuff(14301011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514309, out perkLevel))
			{
				_actor.buffComponent.RemoveBuffByBuffId(14309011);
			}
			_loopTimes = 0;
			_shootIndex = 0;
		}
	}
