	public class ActionScript_MainControl : ActionScript
	{
		private FP _delayNormalAttackStageDelay;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514113, out var _))
			{
				_playerSkillCd.SetSkillTotalSection(ActionKey.A, _playerSkillCd.GetSkillCD(ActionKey.A).originalTotalSectionAmount + 1);
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.A);
			}
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.End))
			{
				ResetNormalAttackStage();
			}
		}

		protected override void OnButtonDPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				ResetNormalAttackStage();
			}
		}

		public void OnUpdate()
		{
			if (!_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill1))
			{
				_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			}
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			}
			else if (_delayNormalAttackStageDelay > 0)
			{
				_delayNormalAttackStageDelay -= _actor.LogicDeltaTime;
			}
			else
			{
				ResetNormalAttackStage();
			}
		}

		private void ResetNormalAttackStage()
		{
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private CoroutineNode _perkLogicCor_P13;

		private FP _buffTime_P13;

		private int _triggerTimes_P13;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514103, out var perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 514108, out perkLevel))
				{
					_buffId_Ink = 14108012;
				}
				else
				{
					_buffId_Ink = 14103011;
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 514108, out perkLevel))
			{
				_buffId_Ink = 14108011;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514105, out perkLevel))
			{
				_buffIdDic_Burn = Config_MainControl.buffIdDic_Burn_P5;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514111, out perkLevel))
			{
				_damageTag_TriggerFireMark?.Add(Config_MainControl.damageTag_TriggerFireMark_P11);
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnDied);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
		}

		private void OnCastSkill(IEvent evt)
		{
			if (evt is AdventureActorCastSkillEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEvent && sender == _actor && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B && CommonUtils.HavePersonalPerk(_actor.dataID, 514113, out var _))
			{
				if (_perkLogicCor_P13 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P13);
				}
				_perkLogicCor_P13 = _actor.StartLogicCoroutine(PerkLogic_P13(), runImmediately: true);
			}
		}

		private IEnumerator PerkLogic_P13()
		{
			_actor.buffComponent.AddBuff(14113011, _actor);
			_buffTime_P13 = Config_MainControl.buffTime_P13;
			_triggerTimes_P13 = 0;
			while (_buffTime_P13 > 0)
			{
				_buffTime_P13 -= _actor.LogicDeltaTime;
				yield return null;
			}
			_actor.buffComponent.RemoveBuffByBuffId(14113011);
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514101, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P1))
			{
				AdventureActor.AddFromAttr(14101011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514104, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P4))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(14104011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(14104011, _actor, buffNumByID);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514109, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P9))
			{
				monsterAdventureActor.buffComponent.AddBuff(14109011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514113, out perkLevel) && damageEvent.isCrit && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_TriggerAddBuffTime_P13) && _triggerTimes_P13 < 3)
			{
				_buffTime_P13 += Config_MainControl.addBuffTime_P13;
				_triggerTimes_P13++;
			}
		}

		protected override void TriggerBurn(MonsterAdventureActor monster)
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514103, out var _) && monster.buffComponent.GetBuffNum(0, 0, Config.buffTag_Ink) >= 4)
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14101_Main_Skill_P03_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				monster.buffComponent.RemoveBuffByTag(Config.buffTag_Ink);
				_actor.buffComponent.AddBuff(14103012, _actor);
			}
			else
			{
				base.TriggerBurn(monster);
			}
		}

		protected override void OnTriggerBurn(MonsterAdventureActor monster)
		{
			base.OnTriggerBurn(monster);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514109, out var _) && monster.buffComponent.CheckBuffByBuffID(14109011))
			{
				monster.buffComponent.AddBuff(14109012, _actor);
			}
		}

		protected override void OnTriggerFireMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			base.OnTriggerFireMark(monster, hitDamageTag);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514111, out var perkLevel))
			{
				_actor.buffComponent.AddBuff(14111011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514112, out perkLevel))
			{
				monster.buffComponent.AddBuff(14112011, _actor);
			}
		}

		private void OnDied(IEvent evt)
		{
			if (evt is AdventureActorDiedEvent { actor: MonsterAdventureActor actor } && CommonUtils.HavePersonalPerk(_actor.dataID, 514106, out var _) && actor.buffComponent.CheckBuffByBuffTag(Config.buffTag_Burn))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14101_Main_Skill_P06_FirePit", actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			if (_perkLogicCor_P13 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P13);
			}
			_perkLogicCor_P13 = null;
			_buffTime_P13 = 0;
			_triggerTimes_P13 = 0;
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private bool _searchAndAim;

		private bool _inLoopStage;

		private FP _searchUseInputDirectionInterval;

		private FP _loopTime;

		private AimTarget _aimTarget;

		private CoroutineNode _perkLogic_P2;

		private CoroutineNode _perkLogic_P4;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_searchAndAim = true;
			_inLoopStage = false;
			_loopTime = 0;
			_actor.buffComponent.AddBuff(14193011, _actor);
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true, dontLostTarget: true);
			_searchUseInputDirectionInterval = Config_MainControl.interval_searchTargetUseInputDirection;
			AimDirection(forceLookAtTarget: true);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514110, out var _))
			{
				_actor.actorShield.AddShield(14110001, _actor);
			}
		}

		public void OnStart()
		{
			string text = "141_Main_Skill";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514104, out var perkLevel))
			{
				text = ((!CommonUtils.HavePersonalPerk(_actor.dataID, 514109, out perkLevel)) ? "141_Main_Skill_P04" : "141_Main_Skill_P04P09");
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 514109, out perkLevel))
			{
				text = "141_Main_Skill_P09";
			}
			string actionTag = text;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onRecoveryBegin = OnRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt);
		}

		private void OnAnticipationEnd()
		{
			_inLoopStage = true;
			_loopTime = Config_MainControl.loopTime_Skill;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514101, out var perkLevel))
			{
				_loopTime += Config_MainControl.addSkillLoopTime_P1;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514102, out perkLevel))
			{
				_perkLogic_P2 = _actor.StartLogicCoroutine(PerkLogic_P2(), runImmediately: true);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514104, out perkLevel))
			{
				_perkLogic_P4 = _actor.StartLogicCoroutine(PerkLogic_P4(), runImmediately: true);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514107, out perkLevel))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(14107011, _actor);
				}
			}
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintStart", _skill.skillId, _loopTime.AsFloat(), a3: true);
		}

		private IEnumerator PerkLogic_P2()
		{
			FP interval = Config_MainControl.addInterval_SuperpositionBuff_P2;
			while (true)
			{
				interval -= _actor.LogicDeltaTime;
				if (interval <= 0)
				{
					if (_actor.buffComponent.CheckBuffByBuffID(14102012))
					{
						if (_actor.buffComponent.GetBuffNumByID(14102013) < 60)
						{
							_actor.buffComponent.AddBuff(14102013, _actor);
						}
					}
					else
					{
						_actor.buffComponent.AddBuff(14102011, _actor);
						if (_actor.buffComponent.GetBuffNumByID(14102011) >= 60)
						{
							_actor.logicVariable.SetLogicTagValue("NormalAttackStage_Special_P2", 0);
							_actor.buffComponent.RemoveBuffByBuffId(14102011);
							_actor.buffComponent.AddBuff(14102012, _actor);
							for (int i = 0; i < 60; i++)
							{
								_actor.buffComponent.AddBuff(14102013, _actor);
							}
						}
					}
					interval += Config_MainControl.addInterval_SuperpositionBuff_P2;
				}
				yield return null;
			}
		}

		private IEnumerator PerkLogic_P4()
		{
			for (int i = 0; i < 4; i++)
			{
				_actor.buffComponent.AddBuff(14104011, _actor);
			}
			FP interval = Config_MainControl.reduceBuffInterval_P4;
			while (true)
			{
				interval -= _actor.LogicDeltaTime;
				if (interval <= 0)
				{
					_actor.buffComponent.RemoveBuffByBuffId(14104011, 1);
					if (_actor.buffComponent.GetBuffNumByID(14104011) <= 0)
					{
						break;
					}
					interval += Config_MainControl.reduceBuffInterval_P4;
				}
				yield return null;
			}
		}

		public void OnUpdate()
		{
			if (_searchAndAim)
			{
				if (_searchUseInputDirectionInterval > 0)
				{
					_searchUseInputDirectionInterval -= _actor.LogicDeltaTime;
					if (!CommonUtils.CheckTargetIsValid(_actor.attackTarget, 0L))
					{
						_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: false, dontLostTarget: true);
					}
				}
				else
				{
					_searchUseInputDirectionInterval = Config_MainControl.interval_searchTargetUseInputDirection;
					bool useInputDirection = _actor.actorSearchTargetInfo.GetEnterVisionAlertActors(useInputDirection: true).Count > 0;
					_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection, dontLostTarget: true);
				}
				AimDirection();
			}
			if (_inLoopStage)
			{
				if (_loopTime > 0)
				{
					_loopTime -= _actor.LogicDeltaTime;
				}
				else
				{
					base.comboAttack.CancelAttack();
				}
			}
		}

		private void AimDirection(bool forceLookAtTarget = false)
		{
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			if (_actor.aimMode != AdventureActor.AimMode.LockDirection)
			{
				_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
			}
			TSVector2 tSVector;
			if (_actor.attackTarget != null)
			{
				tSVector = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				if (forceLookAtTarget)
				{
					_actor.tsTransform.Forward = tSVector;
					return;
				}
			}
			else
			{
				tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			}
			if (!(tSVector == TSVector2.zero) && !(tSVector == _actor.tsTransform.Forward))
			{
				FP fP = TSVector2.SignedAngle(_actor.tsTransform.Forward, tSVector);
				FP fP2 = Config_MainControl.maxRotateSpeed_Skill * _actor.LogicDeltaTime;
				fP = ((TSMath.Abs(fP) < fP2) ? fP : (fP2 * TSMath.Sign(fP)));
				tSVector = TSVector2.Rotate(_actor.tsTransform.Forward, fP);
				_actor.tsTransform.Forward = tSVector;
			}
		}

		private void OnRecoveryBegin()
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _skill.skillId);
			_aimTarget?.Cancel();
			_searchAndAim = false;
			_inLoopStage = false;
			_loopTime = 0;
			ClearPerkLogic();
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		private void ClearPerkLogic()
		{
			if (_perkLogic_P2 != null)
			{
				_actor.StopLogicCoroutine(_perkLogic_P2);
			}
			_perkLogic_P2 = null;
			if (_perkLogic_P4 != null)
			{
				_actor.StopLogicCoroutine(_perkLogic_P4);
			}
			_perkLogic_P4 = null;
			_actor.buffComponent.RemoveBuffByBuffId(14104011);
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.RemoveBuffByBuffId(14107011);
			}
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.buffComponent.RemoveBuffByBuffId(14193011);
			ClearPerkLogic();
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _skill.skillId);
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
		}
	}
