	public class ParallelScript_Support : ParallelScript
	{
		private HashSet<long> _triggerSet_P32;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514133, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					if (actorL.actorElementInfo.elementType == GameEnum.elementType.FE)
					{
						actorL.buffComponent.AddBuff(14133011, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
		}

		protected override void OnUltraSkillLogicFinish()
		{
			base.OnUltraSkillLogicFinish();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514132, out var _))
			{
				_triggerSet_P32?.Clear();
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 514132, out var _) || !CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P32))
			{
				return;
			}
			monsterAdventureActor.buffComponent.AddBuff(1011, _actor);
			if (_triggerSet_P32 == null)
			{
				_triggerSet_P32 = new HashSet<long>();
			}
			if (!_triggerSet_P32.Add(monsterAdventureActor.Id))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.AddBuff(14132011, _actor);
			}
		}

		private void OnBulletFinish(IEvent evt)
		{
			if (evt is AdventureBulletFinishEvent adventureBulletFinishEvent && adventureBulletFinishEvent.owner == _actor && CommonUtils.HavePersonalPerk(_actor.dataID, 514123, out var _))
			{
				AdventureBulletBase adventureBulletBase = adventureBulletFinishEvent.sender as AdventureBulletBase;
				if (adventureBulletBase != null && adventureBulletBase.CheckBulletTag(Config_Support.bulletTag_AddBuff_P23) && adventureBulletBase.target != null)
				{
					AdventureActor adventureActor = adventureBulletBase.target as AdventureActor;
					adventureActor?.buffComponent.AddBuff(14123011, _actor);
					new PlayFX().Play(adventureActor, null, "fx_14101_base_Support_Skill_Summon_Strengthen", default(FP), adventureActor.tsTransform.Position, default(TSVector2));
				}
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			_triggerSet_P32?.Clear();
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		private bool _inLoopStage;

		private FP _loopTime;

		private int _triggerLogicIndex;

		private bool _triggerBattleReady;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_inLoopStage = false;
			_loopTime = 0;
			_triggerLogicIndex = 0;
			_triggerBattleReady = false;
			ClearSummonBullet();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
		}

		public void OnStart()
		{
			PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
			if (playerAdventureActor.attackTarget != null)
			{
				_actor.LookAt(playerAdventureActor.attackTarget.tsTransform.Position, 0f);
			}
			else
			{
				_actor.LookAtDir(playerAdventureActor.tsTransform.Forward, 0f);
			}
			System.Action onAnticipationEnd = OnAnticipationEnd;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onRecoveryBegin = OnRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("141_Support_Skill", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnAnticipationEnd()
		{
			_inLoopStage = true;
			_loopTime = Config_Support.loopTime_Skill;
		}

		public void OnUpdate()
		{
			if (_inLoopStage)
			{
				if (_triggerBattleReady || _loopTime <= 0)
				{
					base.comboAttack.CancelAttack();
				}
				else
				{
					_loopTime -= _actor.LogicDeltaTime;
				}
			}
		}

		private void OnBattleReady(IEvent _)
		{
			_triggerBattleReady = true;
			ClearSummonBullet();
		}

		private void ClearSummonBullet()
		{
			List<AdventureBulletBase> list = new List<AdventureBulletBase>();
			_actor.QueryOwnedAliveBullets(list);
			foreach (AdventureBulletBase item in list)
			{
				if (item.CheckBulletTag(Config_Support.bulletTag_Summoned_Skill))
				{
					item.Finish(cancel: true);
				}
			}
		}

		private void OnRecoveryBegin()
		{
			_inLoopStage = false;
			_loopTime = 0;
		}

		private void OnCustomEvent(string eventName)
		{
			if (!string.Equals(eventName, "141_Summon"))
			{
				return;
			}
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514123, out var perkLevel))
			{
				if (_triggerLogicIndex > 0)
				{
					ShootAddBuffBulletToTiger();
				}
				else
				{
					ShootSummonedTigerBullet(assistantAttackTarget);
				}
			}
			else
			{
				ShootSummonedDragonBullet(assistantAttackTarget);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 514121, out perkLevel))
			{
				ShootSummonedDragonBullet(assistantAttackTarget);
			}
			_triggerLogicIndex++;
		}

		private void ShootSummonedDragonBullet(LogicEntity target)
		{
			TSVector2 position = _actor.tsTransform.Position;
			if (target != null)
			{
				TSVector2 normalized = (target.tsTransform.Position - _actor.tsTransform.Position).normalized;
				FP fP = TSVector2.Distance(_actor.tsTransform.Position, target.tsTransform.Position);
				position += fP * normalized / 2;
			}
			DeterministicShape shape = new DeterministicShape
			{
				shapeType = DeterministicShape.ShapeType.Circle,
				innerRadius = 0,
				radius = Config_Support.randomRadius_Summoned_Skill,
				position = position
			};
			TSVector2 randomPointInShape = ILRuntimeAPI.GetRandomPointInShape(_actor, shape);
			TSVector2 position2 = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_Support.shootOffset_Skill.x + _actor.tsTransform.Forward * Config_Support.shootOffset_Skill.y;
			ILRuntimeAPI.Shoot("Bullet_14101_Support_Skill_Throw", _actor, default(FP), position2, Config_Support.shootPositionY_Skill, randomPointInShape, null, AimType.Position, BulletDirectionType.BulletToTarget);
		}

		private void ShootSummonedTigerBullet(LogicEntity target)
		{
			TSVector2 result = _actor.tsTransform.Position;
			if (target != null)
			{
				TSVector2 normalized = (target.tsTransform.Position - _actor.tsTransform.Position).normalized;
				FP fP = TSVector2.Distance(_actor.tsTransform.Position, target.tsTransform.Position);
				result += fP * normalized / 2 + Config_Support.offset_Summoned_P23 * normalized;
			}
			else
			{
				result += _actor.tsTransform.Forward * Config_Support.offset_Summoned_NoTarget_P23;
			}
			if (!_actor.QueryPositionWalkable(result))
			{
				_actor.QueryClosestPositionWalkable(result, out result);
			}
			TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_Support.shootOffset_Skill.x + _actor.tsTransform.Forward * Config_Support.shootOffset_Skill.y;
			ILRuntimeAPI.Shoot("Bullet_14101_Support_Skill_Throw_P23_Tiger", _actor, default(FP), position, Config_Support.shootPositionY_Skill, result, null, AimType.Position, BulletDirectionType.BulletToTarget);
		}

		private void ShootAddBuffBulletToTiger()
		{
			List<LogicEntity> list = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntitiesByDataID(14102111);
			if (list != null && list.Count > 0)
			{
				TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_Support.shootOffset_Skill.x + _actor.tsTransform.Forward * Config_Support.shootOffset_Skill.y;
				for (int i = 0; i < list.Count; i++)
				{
					AdventureActor actor = _actor;
					FP shootPositionY_Skill = Config_Support.shootPositionY_Skill;
					LogicEntity target = list[i];
					ILRuntimeAPI.Shoot("Bullet_14101_Support_Skill_Throw_P23_Buff", actor, default(FP), position, shootPositionY_Skill, default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				}
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			if (_triggerBattleReady)
			{
				((PlayerAdventureActor)_actor).playerSkillCd.ResetSkillCD(ActionKey.B);
			}
			_inLoopStage = false;
			_loopTime = 0;
			_triggerLogicIndex = 0;
			_triggerBattleReady = false;
		}
	}
	public class ActionScript_Summoned : AIBase
	{
		protected enum SummonedType
		{
			None,
			Dragon,
			Tiger
		}

		protected PlayerAdventureActor _summoner;

		protected SummonedType _summonedType;

		private CoroutineNode _perkLogicCor_P22;

		private PlayFX _playFX_P22;

		private long _areaEffectId_P24;

		private long _areaEffectId_P27;

		public virtual void OnEnable()
		{
			MonsterSummonInfo logicComponent = _actor.GetLogicComponent<MonsterSummonInfo>();
			if (logicComponent != null)
			{
				_summoner = logicComponent.SummonActor as PlayerAdventureActor;
			}
			_areaEffectId_P24 = 0L;
			_areaEffectId_P27 = 0L;
		}

		protected bool HavePersonalPerk(int perkId)
		{
			if (_summoner == null)
			{
				return false;
			}
			int perkLevel;
			return CommonUtils.HavePersonalPerk(_summoner.dataID, perkId, out perkLevel);
		}

		public virtual void OnStart()
		{
			_actor.monsterTarget = null;
			if (HavePersonalPerk(514122))
			{
				if (_perkLogicCor_P22 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P22);
				}
				_perkLogicCor_P22 = _actor.StartLogicCoroutine(PerkLogic_P22());
			}
			if (HavePersonalPerk(514124) && _actor.logicVariable.GetLogicTagToggle("IsFirstSummoned"))
			{
				_areaEffectId_P24 = _summonedType switch
				{
					SummonedType.Dragon => ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14101_Summon_Snake_P24_FireCoat", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null), 
					SummonedType.Tiger => ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14101_Summon_Tiger_P24_FireCoat", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null), 
					_ => 0L, 
				};
			}
			if (HavePersonalPerk(514127))
			{
				_areaEffectId_P27 = ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_14101_Summon_P27_Defense", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnActorCastSkill);
		}

		private IEnumerator PerkLogic_P22()
		{
			if (_playFX_P22 == null)
			{
				_playFX_P22 = new PlayFX();
			}
			else
			{
				_playFX_P22.Clear();
			}
			while (_summoner.logicVariable.GetLogicTagValue("SummonedCount").AsInt() < 2)
			{
				yield return null;
			}
			_actor.buffComponent.AddBuff(14122011, _summoner);
			switch (_summonedType)
			{
			case SummonedType.Dragon:
				_playFX_P22.Play(_actor, null, "fx_14101_Buff_Support_Skill_P22_Summon_1_Exciting", default(FP), _actor.tsTransform.Position, default(TSVector2));
				break;
			case SummonedType.Tiger:
				_playFX_P22.Play(_actor, null, "fx_14101_Buff_Support_Skill_P22_Summon_1_Exciting", default(FP), _actor.tsTransform.Position, default(TSVector2));
				break;
			}
			FP time = Config_Support.scaleChangeTime_P22;
			FP scaleChangeMutli = Config_Support.scaleMutli_P22 - _actor.actorScaleInfo.modelScale;
			while (time > 0)
			{
				_actor.actorScaleInfo.modelScale += scaleChangeMutli * _actor.LogicDeltaTime;
				time -= _actor.LogicDeltaTime;
				yield return null;
			}
		}

		public virtual void OnUpdate()
		{
		}

		private void OnActorCastSkill(IEvent evt)
		{
			AdventureActorCastSkillEvent adventureActorCastSkillEvent = evt as AdventureActorCastSkillEvent;
			if (adventureActorCastSkillEvent.sender as AdventureActor is PlayerAdventureActor playerAdventureActor && playerAdventureActor == SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B)
			{
				OnMainPlayerActorCastSkill();
			}
		}

		protected virtual void OnMainPlayerActorCastSkill()
		{
		}

		public virtual void OnStop()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnActorCastSkill);
			if (_perkLogicCor_P22 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P22);
			}
			_perkLogicCor_P22 = null;
			if (_areaEffectId_P24 > 0)
			{
				ILRuntimeAPI.StopAreaEffect(_areaEffectId_P24);
			}
			_areaEffectId_P24 = 0L;
			if (_areaEffectId_P27 > 0)
			{
				ILRuntimeAPI.StopAreaEffect(_areaEffectId_P27);
			}
			_areaEffectId_P27 = 0L;
		}

		public virtual void OnDisable()
		{
			_summoner = null;
		}
	}
	public class ParallelScript_Summoned : AIBase
	{
		protected PlayerAdventureActor _summoner;

		private bool _isValid;

		private CoroutineNode _perkLogicCor_P28;

		private FP _lastTriggerTime_P29;

		private bool IsValid
		{
			get
			{
				return _isValid;
			}
			set
			{
				if (value == _isValid)
				{
					return;
				}
				_isValid = value;
				if (_summoner != null)
				{
					int num = _summoner.logicVariable.GetLogicTagValue("SummonedCount").AsInt();
					if (_isValid)
					{
						num++;
						_actor.logicVariable.ToggleLogicTag("IsFirstSummoned", num == 1);
					}
					else
					{
						num--;
						_actor.logicVariable.ToggleLogicTag("IsFirstSummoned", value: false);
					}
					_summoner.logicVariable.SetLogicTagValue("SummonedCount", num);
				}
			}
		}

		public virtual void OnEnable()
		{
			MonsterSummonInfo logicComponent = _actor.GetLogicComponent<MonsterSummonInfo>();
			if (logicComponent != null)
			{
				_summoner = logicComponent.SummonActor as PlayerAdventureActor;
			}
			IsValid = true;
			_actor.EnableUnparalleled();
			_actor.EnableCloseBlock();
			if (HavePersonalPerk(514121))
			{
				_actor.buffComponent.AddBuff(14121011, _summoner);
			}
			if (HavePersonalPerk(514125))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent.AddBuff(14125011, _summoner);
				}
			}
			if (HavePersonalPerk(514128))
			{
				_perkLogicCor_P28 = _actor.StartLogicCoroutine(PerkLogic_P28());
			}
			if (HavePersonalPerk(514131))
			{
				_actor.buffComponent.AddBuff(14131011, _summoner);
			}
			_lastTriggerTime_P29 = 0;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
		}

		protected bool HavePersonalPerk(int perkId)
		{
			if (_summoner == null)
			{
				return false;
			}
			int perkLevel;
			return CommonUtils.HavePersonalPerk(_summoner.dataID, perkId, out perkLevel);
		}

		private IEnumerator PerkLogic_P28()
		{
			FP interval = Config_Support.addBuffInterval_P28;
			while (IsValid)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent.AddBuff(14128011, _summoner);
					interval = Config_Support.addBuffInterval_P28;
				}
				yield return null;
			}
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor bEntity && HavePersonalPerk(514130) && _actor.DistanceWithRadius(bEntity) <= Config_Support.triggerRadius_P30)
			{
				AdventureActor.AddFromAttr(14130001, _summoner);
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.from == _actor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monsterAdventureActor) || !HavePersonalPerk(514129) || (!(_lastTriggerTime_P29 <= 0) && !(_actor.LogicTime - _lastTriggerTime_P29 > Config_Support.triggerCD_P29)))
			{
				return;
			}
			ILRuntimeAPI.SearchByRangeAndPosition(_summoner, monsterAdventureActor.tsTransform.Position, Config_Support.triggerRadius_P29, delegate(List<LogicEntity> result)
			{
				ILRuntimeAPI.SearchActorFriend(_summoner, result);
				if (result.Count > 0)
				{
					foreach (AdventureActor item in result)
					{
						item.buffComponent.AddBuff(14129011, _summoner);
					}
				}
			});
			_lastTriggerTime_P29 = _actor.LogicTime;
		}

		private void OnCastSkill(IEvent evt)
		{
			if (evt is AdventureActorCastSkillEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEvent && sender == _summoner && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B)
			{
				DestroySelf();
			}
		}

		private void OnBattleReady(IEvent evt)
		{
			DestroySelf();
		}

		private void DestroySelf()
		{
			if (_actor.state == ActorState.Spawn)
			{
				_actor.StartLogicCoroutine(WaitForDestroySelf());
			}
			else
			{
				_actor.DestroySelf();
			}
			IsValid = false;
		}

		private IEnumerator WaitForDestroySelf()
		{
			while (_actor.state == ActorState.Spawn)
			{
				yield return null;
			}
			_actor.DestroySelf();
		}

		public virtual void OnDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			IsValid = false;
			_actor.DisableUnparalleled();
			_actor.DisableCloseBlock();
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.RemoveBuffByBuffId(14125011, 1);
			}
			if (_perkLogicCor_P28 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P28);
			}
			_perkLogicCor_P28 = null;
			_lastTriggerTime_P29 = 0;
		}
	}
	public class ActionScript_Dragon : ActionScript_Summoned
	{
		private FP _useShootSkillInterval;

		private FP _useStrengthShootSkillCD;

		public override void OnEnable()
		{
			base.OnEnable();
			_summonedType = SummonedType.Dragon;
			_useShootSkillInterval = 0;
			_useStrengthShootSkillCD = 0;
		}

		public override void OnUpdate()
		{
			base.OnUpdate();
			PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
			if (playerAdventureActor.attackTarget != null)
			{
				_actor.monsterTarget = playerAdventureActor.attackTarget;
			}
			else if (!CommonUtils.CheckTargetIsValid(_actor.monsterTarget, 0L))
			{
				_actor.monsterTarget = null;
			}
			if (_useShootSkillInterval <= 0)
			{
				if (_actor.monsterTarget != null)
				{
					_useShootSkillInterval = Config_Support.useShootSkillInterval_Dragon;
					ILRuntimeAPI.CreateSkill(14132012, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
				}
			}
			else
			{
				_useShootSkillInterval -= _actor.LogicDeltaTime;
			}
			if (_useStrengthShootSkillCD > 0)
			{
				_useStrengthShootSkillCD -= _actor.LogicDeltaTime;
			}
		}

		protected override void OnMainPlayerActorCastSkill()
		{
			base.OnMainPlayerActorCastSkill();
			if (HavePersonalPerk(514126) && _useStrengthShootSkillCD <= 0 && ILRuntimeAPI.CreateSkill(14132013, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false))
			{
				_useStrengthShootSkillCD = Config_Support.useStrengthShootSkillCD_Dragon;
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			_useShootSkillInterval = 0;
			_useStrengthShootSkillCD = 0;
		}
	}
