			bulletList.Clear();
			_actor.QueryOwnedAliveBullets(bulletList);
			foreach (AdventureBulletBase bullet in bulletList)
			{
				if (bullet.bulletTag.Equals(bulletTag_NoTrace))
				{
					bullet.Kill();
