					string bulletAlias2 = bullet_summon;
					AdventureActor actor2 = _actor;
					TSVector2 targetPosition = tSVector;
					AdventureBezierBullet obj2 = ILRuntimeAPI.Shoot(bulletAlias2, actor2, default(FP), default(TSVector2), default(FP), targetPosition, null, AimType.Position, BulletDirectionType.BulletToTarget) as AdventureBezierBullet;
					obj2.isTraceable = false;
					obj2.bulletTag = bulletTag_NoTrace;
				}
			}
		}

		public override void OnSummonSpawned(AdventureMonsterSummonerSpawnedEvent evt)
