		public override void OnMonsterDied(AdventureMonsterDiedEvent evt)
		{
			base.OnMonsterDied(evt);
			if (evt.monsterID == summonId)
			{
				if (monsterIds.Contains(evt.id))
				{
					monsterIds.Remove(evt.id);
				}
				if (GetPerkLv(513506, out var lv))
