	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private PlayTimeline _playTimeline;

		private int _maxAttackLoopRound;

		private int _attackLoopRound;

		private Dash _dash;

		private CoroutineNode _perkLogicCor_P43;

		private CoroutineNode _destinyLogicCor_2;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_actor.EnableInvincible();
			_actor.EnableSuperArmor();
			_actor.EnableImmuneControl();
			_attackLoopRound = 0;
			_maxAttackLoopRound = 2;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513442, out var perkLevel))
			{
				_maxAttackLoopRound += 2;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513443, out perkLevel))
			{
				if (_perkLogicCor_P43 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P43);
				}
				_perkLogicCor_P43 = _actor.StartLogicCoroutine(PerkLogic_43());
			}
			DefaultLookAt();
		}

		private IEnumerator PerkLogic_43()
		{
			_actor.buffComponent.AddBuffNum(13443011, 6, _actor);
			FP interval = Config.removeBuffInterval_P43;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					if (_actor.buffComponent.GetBuffNumByID(13443011) <= 1)
					{
						break;
					}
					_actor.buffComponent.RemoveBuffByBuffId(13443011, 1);
					interval = Config.removeBuffInterval_P43;
				}
				yield return null;
			}
		}

		public void OnStart()
		{
			if (_playTimeline == null)
			{
				_playTimeline = new PlayTimeline();
			}
			_playTimeline.Play(_actor, OnPlayTimeLineFinish, OnNotPlayTimeLine);
		}

		private void OnPlayTimeLineFinish()
		{
			System.Action onComboLoop = OnComboLoop;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("134_Ultra_TL", flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, null, fadeOutAnim: false, onComboLoop);
		}

		private void OnNotPlayTimeLine()
		{
			System.Action onComboLoop = OnComboLoop;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("134_Ultra_NoTL", flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, null, fadeOutAnim: false, onComboLoop);
		}

		private void OnComboLoop()
		{
			_attackLoopRound++;
			if (_attackLoopRound >= _maxAttackLoopRound)
			{
				base.comboAttack.CancelAttack();
			}
		}

		private void OnCustomEvent(string eventName)
		{
			if (!string.Equals(eventName, "134_Ultra_Hurt"))
			{
				return;
			}
			LogicEntity attackTarget = GetAttackTarget();
			FP fP = Config.maxDashDistance_UltraSkill;
			if (attackTarget != null)
			{
				_actor.LookAt(attackTarget.tsTransform.Position, 0);
				fP = TSMath.Clamp(_actor.DistanceWithRadius(attackTarget), Config.minDashDistance_UltraSkill, Config.maxDashDistance_UltraSkill);
			}
			else
			{
				TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (movementInputDirection != TSVector2.zero)
				{
					_actor.LookAtDir(movementInputDirection, 0);
				}
			}
			if (_dash == null)
			{
				_dash = new Dash();
			}
			else
			{
				_dash.Interrupte();
			}
			_actor.PauseMovementBlock();
			_dash.BeginDash(_actor, _actor.tsTransform.Forward, Config.dashSpeed_UltraSkill, fP, default(FP), (System.Action)OnDashFinish, (System.Action)null, (System.Action)null, true, false, false, false, true, false, false, default(FP), true);
		}

		private IEnumerator DestinyLogic_2()
		{
			FP interval = Config.shootInterval_D2;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor;
					AdventureActor adventureActor = (playerAdventureActor.attackTarget ?? ILRuntimeAPI.GetTargetNearByRange(playerAdventureActor, Config.searchTargetRadius_D2)) as AdventureActor;
					if (adventureActor != null)
					{
						DeterministicShape shape = new DeterministicShape
						{
							shapeType = DeterministicShape.ShapeType.Circle,
							innerRadius = Config.randomShootPointInnerRadius_D2,
							radius = Config.randomShootPointOuterRadius_D2,
							position = adventureActor.tsTransform.Position
						};
						TSVector2 randomPointInShape = ILRuntimeAPI.GetRandomPointInShape(adventureActor, shape, isReachable: false);
						TSVector2 normalized = (adventureActor.tsTransform.Position - randomPointInShape).normalized;
						ILRuntimeAPI.ShootByDirection("Bullet_13401_Ultra_T2", _actor, default(FP), normalized, randomPointInShape);
					}
					interval = Config.shootInterval_D2;
				}
				yield return null;
			}
		}

		private void OnDashFinish()
		{
			_actor.ResumeMovementBlock();
		}

		private LogicEntity GetAttackTarget()
		{
			if (((PlayerAdventureActor)_actor).isAssist)
			{
				return CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
			}
			return _actor.attackTarget;
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513441, out var _))
			{
				_actor.buffComponent.RemoveBuffByBuffId(13441011);
			}
			if (_perkLogicCor_P43 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P43);
			}
			_perkLogicCor_P43 = null;
			_actor.buffComponent.RemoveBuffByBuffId(13443011);
			if (_destinyLogicCor_2 != null)
			{
				_actor.StopLogicCoroutine(_destinyLogicCor_2);
			}
			_destinyLogicCor_2 = null;
			_actor.DisableInvincible();
			_actor.DisableSuperArmor();
			_actor.DisableImmuneControl();
			_actor.ResumeMovementBlock();
		}
	}
