	public class ActionScript_MainControl : ActionScript
	{
		private FP _delayNormalAttackStageDelay;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513403, out var perkLevel))
			{
				_playerSkillCd.BindSkillIdToButton(ActionKey.B, 13431030);
			}
			else
			{
				_playerSkillCd.BindSkillIdToButton(ActionKey.B, 13431000);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513404, out perkLevel))
			{
				if (base.AmmoCount <= 0)
				{
					_actor.buffComponent.AddBuff(13404011, _actor);
				}
				else
				{
					_actor.buffComponent.RemoveBuffByBuffId(13404011);
				}
			}
		}

		protected override int GetAmmoCountMax()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513401, out var _))
			{
				return 9;
			}
			return base.GetAmmoCountMax();
		}

		protected override void OnAmmoCountChange()
		{
			base.OnAmmoCountChange();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513404, out var _))
			{
				if (base.AmmoCount <= 0)
				{
					_actor.buffComponent.AddBuff(13404011, _actor);
				}
				else
				{
					_actor.buffComponent.RemoveBuffByBuffId(13404011);
				}
			}
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		protected override void OnButtonDPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		public void OnUpdate()
		{
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget != null && _actor.movementState != ActorState.Dash && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			base.AmmoCount = _actor.ammoInfo.GetAmmoCount(GameEnum.AmmoType.Main);
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			}
			else if (_delayNormalAttackStageDelay > 0)
			{
				_delayNormalAttackStageDelay -= _actor.LogicDeltaTime;
			}
			else
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private HitBox.HitBoxFeatureData _featureData_P3;

		private CoroutineNode _perkLogicCor_P10;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513405, out var perkLevel))
			{
				_damageTag_TriggerFireMark.Add(Config_MainControl.damageTag_TriggerFireMark_P5);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513410, out perkLevel))
			{
				if (_perkLogicCor_P10 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P10);
				}
				_perkLogicCor_P10 = _actor.StartLogicCoroutine(PerkLogic_10());
			}
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 513411, out perkLevel))
			{
				return;
			}
			bool flag = true;
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				if (actorL.actorElementInfo.elementType != GameEnum.elementType.FE)
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				_actor.buffComponent.AddBuff(13411011, _actor);
			}
		}

		private IEnumerator PerkLogic_10()
		{
			FP interval = Config_MainControl.addBuffInterval_P10;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent?.AddBuff(13410011, _actor);
					interval = Config_MainControl.addBuffInterval_P10;
				}
				yield return null;
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 513403, out var _))
			{
				return;
			}
			if (CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_MainControl.damageTag_Skill))
			{
				monsterAdventureActor.buffComponent.AddBuff(13403011, _actor);
			}
			if (CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config.damageTag_NormalAttack) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(13403011))
			{
				if (_featureData_P3 == null)
				{
					_featureData_P3 = new HitBox.HitBoxFeatureData
					{
						StiffDuration = Config_MainControl.stiffDuration_P3,
						hitStrenth = Config_MainControl.hitStrenth_P3
					};
				}
				ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 134503001, "fx_13401_hit_Main_Skill_P03_Hurt", (string)null, false, HitBox.FeatureFlag.Stiff, _featureData_P3, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513405, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config.damageTag_FireMark))
			{
				AdventureActor.AddFromAttr(13405001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513413, out perkLevel))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 13413011);
				if (monsterAdventureActor.actorHealthInfo.hpPercentage < scriptValue * 0.01)
				{
					AdventureActor.AddFromAttr(13413001, _actor);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513409, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P9) && monsterAdventureActor.actorHealthInfo.isAlive)
			{
				int count = Config_MainControl.buffIdList_P9.Count;
				int num = Config_MainControl.buffIdList_P9[count - 1];
				bool flag = true;
				for (int i = 0; i < count - 1; i++)
				{
					int buffID = Config_MainControl.buffIdList_P9[i];
					if (monsterAdventureActor.buffComponent.CheckBuffByBuffID(buffID))
					{
						int num2 = Config_MainControl.buffIdList_P9[i + 1];
						monsterAdventureActor.buffComponent.RemoveBuffByBuffId(buffID);
						monsterAdventureActor.buffComponent.AddBuff(num2, _actor);
						if (num2 == num)
						{
							_actor.StartLogicCoroutine(PerkLogic_9(monsterAdventureActor, num), runImmediately: true);
						}
						flag = false;
						break;
					}
				}
				if (flag && !monsterAdventureActor.buffComponent.CheckBuffByBuffID(num))
				{
					monsterAdventureActor.buffComponent.AddBuff(Config_MainControl.buffIdList_P9[0], _actor);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513412, out perkLevel) && damageEvent.isCrit && (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE || monsterAdventureActor.IsBossMonster()))
			{
				_actor.buffComponent.AddBuff(13412011, _actor);
			}
		}

		private IEnumerator PerkLogic_9(MonsterAdventureActor monster, int lastBuffId)
		{
			long monsterId = monster.Id;
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_MainControl.hitDelay_P9));
			if (CommonUtils.CheckTargetIsValid(monster, monsterId, ingoreSearchedImmunity: true))
			{
				long areaEffectId = ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_13401_Main_Skill_P09_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				while (ILRuntimeAPI.CheckAreaEffectAlive(areaEffectId))
				{
					yield return null;
				}
				monster.buffComponent.RemoveBuffByBuffId(lastBuffId);
			}
		}

		private void Clear()
		{
			if (_perkLogicCor_P10 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P10);
			}
			_perkLogicCor_P10 = null;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			Clear();
		}
	}
