	public class ParallelScript_Support : ParallelScript
	{
		private ActorState _actorState;

		private CoroutineNode _perkLogicCor_P27;

		private ActorState ActorState
		{
			get
			{
				return _actorState;
			}
			set
			{
				if (_actorState != value)
				{
					_actorState = value;
					if (_actorState == ActorState.Idle)
					{
						OnSelfExit();
					}
					else if (_actorState == ActorState.Action)
					{
						OnSelfEnter();
					}
				}
			}
		}

		public override void OnEnable()
		{
			base.OnEnable();
			if (!CommonUtils.HavePersonalPerk(_actor.dataID, 513433, out var _))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				if (actorL.actorElementInfo.elementType == GameEnum.elementType.FE)
				{
					actorL.buffComponent.AddBuff(13433011, _actor);
				}
			}
		}

		public void OnUpdate()
		{
			ActorState = _actor.state;
		}

		private void OnSelfEnter()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513427, out var _))
			{
				if (_perkLogicCor_P27 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P27);
				}
				_perkLogicCor_P27 = null;
			}
		}

		private void OnSelfExit()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513427, out var _))
			{
				if (_perkLogicCor_P27 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P27);
				}
				_perkLogicCor_P27 = _actor.StartLogicCoroutine(PerkLogic_27());
			}
		}

		private IEnumerator PerkLogic_27()
		{
			FP interval = Config_Support.addBuffInterval_P27;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent.AddBuff(13427011, _actor);
					interval = Config_Support.addBuffInterval_P27;
				}
				yield return null;
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513425, out var perkLevel) && _actor.buffComponent.CheckBuffByBuffID(13425011))
			{
				AdventureActor.AddFromAttr(13425001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513429, out perkLevel))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(13429011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(13429001, _actor, buffNumByID);
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513431, out perkLevel) && (monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE || monsterAdventureActor.IsBossMonster()))
			{
				AdventureActor.AddFromAttr(13431001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513428, out var perkLevel) && !damageEvent.isKill && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P28))
			{
				ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 134528001, "fx_13401_hit_Normal", (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513432, out perkLevel) && damageEvent.isKill && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Skill))
			{
				_actor.buffComponent.AddBuff(13432011, _actor);
			}
		}

		private void Clear()
		{
			ActorState = ActorState.Null;
			if (_perkLogicCor_P27 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P27);
			}
			_perkLogicCor_P27 = null;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			Clear();
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		private LogicEntity _target;

		private long _targetId;

		private Dash _dash;

		private int _maxAttackRound;

		private int _attackRound;

		private int _additionalAttrCount_P24;

		private CoroutineNode _perkLogicCor_P24;

		private CoroutineNode _perkLogicCor_P29;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_target = null;
			_targetId = 0L;
			_attackRound = 0;
			_additionalAttrCount_P24 = 0;
			_maxAttackRound = ((!CommonUtils.HavePersonalPerk(_actor.dataID, 513423, out var perkLevel)) ? 1 : 2);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513424, out perkLevel))
			{
				if (_perkLogicCor_P24 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P24);
				}
				_perkLogicCor_P24 = _actor.StartLogicCoroutine(PerkLogic_24());
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513429, out perkLevel))
			{
				if (_perkLogicCor_P29 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P29);
				}
				_perkLogicCor_P29 = _actor.StartLogicCoroutine(PerkLogic_29());
			}
			DefaultLookAt();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
		}

		private IEnumerator PerkLogic_24()
		{
			FP interval = Config_Support.addAdditionalAttrInterval_P24;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513430, out var _))
			{
				interval = Config_Support.addAdditionalAttrInterval_P24_P30;
			}
			FP leftTime = interval;
			while (true)
			{
				if (leftTime > 0)
				{
					leftTime -= _actor.LogicDeltaTime;
				}
				else
				{
					_additionalAttrCount_P24++;
					leftTime = interval;
				}
				yield return null;
			}
		}

		private IEnumerator PerkLogic_29()
		{
			FP interval = Config_Support.addBuffInterval_P29;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent.AddBuff(13429011, _actor);
					interval = Config_Support.addBuffInterval_P29;
				}
				yield return null;
			}
		}

		public void OnStart()
		{
			BeginDash();
		}

		private void UpdateTarget(bool activeActorTargetFirst = true, bool forceUpdate = true)
		{
			if (!(_target != null) || !CommonUtils.CheckTargetIsValid(_target, _targetId) || forceUpdate)
			{
				_target = CommonUtils.GetAssistantAttackTarget(_actor, activeActorTargetFirst);
				_targetId = ((_target != null) ? _target.Id : 0);
			}
		}

		private void BeginDash()
		{
			_attackRound++;
			UpdateTarget();
			FP fP = Config_Support.maxDistance_Skill_Dash;
			if (_target != null)
			{
				_actor.LookAt(_target.tsTransform.Position, 0);
				fP = TSMath.Clamp(_actor.DistanceWithRadius(_target), 0, Config_Support.maxDistance_Skill_Dash);
				fP -= Config_Support.reduceDistance_Skill_Dash_HaveTarget;
			}
			string rushComboTag = GetRushComboTag();
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onActivationEnd = OnRushActivationEnd;
			System.Action onComboFinish = OnSkillFinish;
			System.Action onInterrupt = OnSkillInterrupt;
			BeginAttack(rushComboTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd);
			if (fP > 0)
			{
				_actor.PauseMovementBlock();
				if (_dash == null)
				{
					_dash = new Dash();
				}
				else
				{
					_dash?.Clear();
				}
				_dash.BeginDash(_actor, _actor.tsTransform.Forward, Config_Support.speed_Skill_Dash, fP, default(FP), (System.Action)OnDashFinish, (System.Action)null, (System.Action)null, true, false, false, false, false, false, false, default(FP), true);
			}
		}

		private string GetRushComboTag()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513426, out var perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 513423, out perkLevel) && CommonUtils.HavePersonalPerk(_actor.dataID, 513424, out perkLevel))
				{
					return "134_Support_Rush_P26P23P24";
				}
				return "134_Support_Rush_P26";
			}
			return "134_Support_Rush";
		}

		private void OnDashFinish()
		{
			_actor.ResumeMovementBlock();
		}

		private void OnRushActivationEnd()
		{
			Attack();
		}

		private void Attack()
		{
			_dash?.Interrupte();
			UpdateTarget(activeActorTargetFirst: false, forceUpdate: false);
			if (_target != null)
			{
				_actor.LookAt(_target.tsTransform.Position, 0);
			}
			string attackComboTag = GetAttackComboTag();
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onActivationEnd = OnAttackActivationEnd;
			System.Action onComboFinish = OnSkillFinish;
			System.Action onInterrupt = OnSkillInterrupt;
			BeginAttack(attackComboTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd);
		}

		private string GetAttackComboTag()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513421, out var perkLevel))
			{
				return "134_Support_Hurt_P21";
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513430, out perkLevel))
			{
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 513424, out perkLevel))
				{
					if (!CommonUtils.HavePersonalPerk(_actor.dataID, 513423, out perkLevel))
					{
						return "134_Support_Hurt_P24P30";
					}
					return "134_Support_Hurt_P24P30P23";
				}
				return "134_Support_Hurt_P30";
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513424, out perkLevel))
			{
				if (!CommonUtils.HavePersonalPerk(_actor.dataID, 513423, out perkLevel))
				{
					return "134_Support_Hurt_P24";
				}
				return "134_Support_Hurt_P24P23";
			}
			return "134_Support_Hurt";
		}

		private void OnAttackActivationEnd()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 513423, out var perkLevel) && _attackRound < _maxAttackRound)
			{
				BeginDash();
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 513422, out perkLevel) && _attackRound >= _maxAttackRound)
			{
				Action<string> onCustomEvent = OnCustomEvent;
				System.Action onComboFinish = OnSkillFinish;
				System.Action onInterrupt = OnSkillInterrupt;
				BeginAttack("134_Support_End_P22", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
			}
		}

		private void OnCustomEvent(string eventName)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (!(adventureActorReceiveDamageBeforeHitEvent.from != _actor) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config_Support.damageTag_Skill))
			{
