			if (adventureAreaEnterExitEvent.iEnter)
			{
				if (!flowerAreas.Contains(areaEffectEntity))
				{
					flowerAreas.Add(areaEffectEntity);
				}
				list_p24.Add(monsterAdventureActor.Id);
				if (GetPerk(perk_28) && list_p24.Count >= num_28)
				{
					SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor.buffComponent.AddBuff(13352811, _actor);
				}
			}
			else
			{
				if (flowerAreas.Contains(areaEffectEntity))
				{
					flowerAreas.Remove(areaEffectEntity);
				}
				list_p24.Remove(adventureAreaEnterExitEvent.triggerCollider.Entity.Id);
				if (GetPerk(perk_28) && list_p24.Count < num_28)
				{
					SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor.buffComponent.RemoveBuffByBuffId(13352811);
