				if (GetPerk(perk_28))
				{
					SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor.buffComponent.RemoveBuffByBuffId(13352811);
				}
				if (GetPerk(perk_30) && areaEffectEntity.CheckTag(flowerEffectTag_F))
