			{
				_damageTagList_TriggerLightMark = new List<int>(5);
			}
			else
			{
				_damageTagList_TriggerLightMark.Clear();
			}
			_damageTagList_TriggerLightMark.Add(damageTag_TriggerLightMark);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513201, out var perkLevel))
			{
				_damageTagList_TriggerLightMark.Add(damageTag_P1);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513210, out perkLevel))
			{
				_damageTagList_TriggerLightMark.Add(damageTag_P10);
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
		}

		private void OnCastSkill(IEvent evt)
		{
			if (!(evt is AdventureActorCastSkillEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEvent))
			{
				return;
			}
			int perkLevel;
			if (sender == _actor && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B)
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513212, out perkLevel))
				{
					FP scriptValue = CommonUtils.GetScriptValue(_actor, 13212011);
					if (_triggerTime_P12 <= 0 || _actor.LogicTime - _triggerTime_P12 > scriptValue)
					{
						_actor.buffComponent?.AddBuff(13212011, _actor);
						_triggerTime_P12 = _actor.LogicTime;
					}
				}
			}
			else if (sender != _actor && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.B && ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513213, out perkLevel))
			{
				_actor.buffComponent?.AddBuff(13213011, _actor);
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (!CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, damageTag_Skill_Stage1))
			{
				return;
			}
			int perkLevel;
			if (CommonUtils.CheckElementMark(CommonDefine.LightMark1, monsterAdventureActor))
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513202, out perkLevel))
				{
					_actor.logicVariable.ToggleLogicTag("CanTriggerPerk_2", value: true);
				}
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513203, out perkLevel))
				{
					monsterAdventureActor.buffComponent?.AddBuff(13203011, _actor);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513208, out perkLevel))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_132_Main_S1_Burst_P08_Stun", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		protected override void OnSelfBeforeHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnSelfBeforeHit(beforeHitEvent);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513202, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_Trigger_P2))
			{
				AdventureActor.AddFromAttr(13202011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513203, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_Trigger_P3))
			{
				AdventureActor.AddFromAttr(13203011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513204, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_P4))
			{
				AdventureActor.AddFromAttr(13204011, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513211, out var _) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P11))
			{
				monsterAdventureActor.buffComponent?.AddBuff(13211011, _actor);
			}
		}

		protected override void TryTriggerLightMark(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.TryTriggerLightMark(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			bool flag = false;
			if (_damageTagList_TriggerLightMark != null && _damageTagList_TriggerLightMark.Count > 0)
			{
				for (int i = 0; i < damageEvent.hitDamageTag.Count; i++)
				{
					int item = damageEvent.hitDamageTag[i];
					if (_damageTagList_TriggerLightMark.Contains(item))
					{
						flag = true;
						break;
					}
				}
			}
			if (flag)
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_132_LightTag_Boom", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				monsterAdventureActor.buffComponent?.RemoveBuffByTag(CommonDefine.Light);
				CommonUtils.TriggerElementMarkEvent(CommonDefine.Light, GameEnum.AdventureActorElementTriggerType.LightElementTriggerType1, _actor, monsterAdventureActor, "LightMark_Trigger_Effect_02");
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			_damageTagList_TriggerLightMark?.Clear();
		}
	}
	public class SkillScript_Skill_Base_MainControl : SkillAdvancedBase
	{
		private static readonly int damageTag_Skill = CommonHelper.StringToHash("132_Main_Skill_Hurt");

		private static readonly int EventHashCode_SkillEnterRecovery = CommonHelper.StringToHash("13201_MainControl_Skill_EnterRecovery");

		private static readonly int EventHashCode_SkillHit = CommonHelper.StringToHash("13201_Skill_Hit");

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			UpdateRootMotionState();
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() == TSVector2.zero)
			{
				if (!(_actor.attackTarget != null))
				{
					_ = _actor.tsTransform.Forward;
				}
				else
				{
					_ = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				}
			}
			DefaultLookAt();
		}

		public void OnStart()
		{
			string actionTag = GetActionTag();
			if (string.IsNullOrEmpty(actionTag))
			{
				OnFinish();
				return;
			}
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onRecoveryBegin = OnRecoveryBegin;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt);
			OnComboBegin();
		}

		protected virtual string GetActionTag()
		{
			return string.Empty;
		}

		protected virtual void OnComboBegin()
		{
		}

		protected virtual void OnAnticipationEnd()
		{
		}

		public virtual void OnUpdate()
		{
			UpdateRootMotionState();
			LockDirection();
		}

		private void UpdateRootMotionState()
		{
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_actor.movementFSM.runtimeIgonreRootMotion = true;
			}
			else
			{
				_actor.movementFSM.runtimeIgonreRootMotion = false;
			}
		}

		protected override void OnReceiveAttack(IEvent evt)
		{
			base.OnReceiveAttack(evt);
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			if (adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor && CommonUtils.CheckHitByTag(adventureActorReceiveAttackEvent.hitDamageTag, damageTag_Skill))
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = this;
				adventureActorCustomEvent.actor = _actor;
				adventureActorCustomEvent.eventHashCode = EventHashCode_SkillHit;
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void OnRecoveryBegin()
		{
			AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
			adventureActorCustomEvent.sender = this;
			adventureActorCustomEvent.actor = _actor;
			adventureActorCustomEvent.eventHashCode = EventHashCode_SkillEnterRecovery;
			_actor.DispatchEvent(adventureActorCustomEvent);
		}

		protected bool HavePersonalPerk(int perkId)
		{
			int perkLevel;
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out perkLevel);
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.movementFSM.runtimeIgonreRootMotion = false;
			_actor.logicVariable.SetLogicTagValue("LastSkillFinishTime_MainControl", _actor.LogicTime);
		}
	}
	public class SkillScript_NormalAttack_MainControl : SkillAdvancedBase
	{
		private static readonly List<string> actionTagList = new List<string> { "132_Attack_1", "132_Attack_2", "132_Attack_3", "132_Attack_4", "132_Attack_5" };

		private static readonly int damageTag_NormalAttack = CommonHelper.StringToHash("132_NormalAttack");

		private static readonly int EventHashCode_NormalAttackHit = CommonHelper.StringToHash("13201_Normal_Attack_Hit");

		private int _stage;

		private bool _isHit;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			UpdateRootMotionState();
			_stage = (int)(long)_actor.logicVariable.GetLogicTagValue("NormalAttackStage");
			_isHit = false;
		}

		public void OnStart()
		{
			string text = ((_stage < actionTagList.Count) ? actionTagList[_stage] : null);
			if (string.IsNullOrEmpty(text))
			{
				NovaLogger.Error($"该普攻段数未配置ActionTag, 普攻段数:{_stage}");
				OnFinish();
				return;
			}
			LogicEntity attackTarget = _actor.attackTarget;
			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(text, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, attackTarget, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt);
		}

		private void OnAnticipationEnd()
		{
			int num = _stage + 1;
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", (num < actionTagList.Count) ? num : 0);
		}

		public void OnUpdate()
		{
			UpdateRootMotionState();
			LockDirection();
		}

		private void UpdateRootMotionState()
		{
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_actor.movementFSM.runtimeIgonreRootMotion = true;
			}
			else
			{
				_actor.movementFSM.runtimeIgonreRootMotion = false;
			}
		}

		protected override void OnReceiveAttack(IEvent evt)
		{
			base.OnReceiveAttack(evt);
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			if (adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor && !_isHit && CommonUtils.CheckHitByTag(adventureActorReceiveAttackEvent.hitDamageTag, damageTag_NormalAttack))
			{
				_isHit = true;
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = this;
				adventureActorCustomEvent.actor = _actor;
				adventureActorCustomEvent.eventHashCode = EventHashCode_NormalAttackHit;
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.movementFSM.runtimeIgonreRootMotion = false;
			_stage = 0;
			_isHit = false;
		}
	}
