	public class StarBuffController
	{
		private const int buffId = 13295011;

		private static readonly FP duration = 3;

		private AdventureActor _actor;

		private long _targetId;

		private AdventureActor _target;

		private int _maxBuffCount;

		private FP _duration;

		private Action<AdventureActor> _reduceCountCallBack;

		public StarBuffController(AdventureActor actor)
		{
			_actor = actor;
			_maxBuffCount = 0;
			_duration = duration;
		}

		public void Init(AdventureActor target, int maxBuffCount, Action<AdventureActor> reduceCountCallBack)
		{
			_target = target;
			_targetId = target.Id;
			_maxBuffCount = maxBuffCount;
			_reduceCountCallBack = reduceCountCallBack;
		}

		public void AddBuff(int addBuffCount)
		{
			if (addBuffCount <= 0 || !IsValid())
			{
				return;
			}
			for (int i = 0; i < addBuffCount; i++)
			{
				if (GetBuffCount() >= _maxBuffCount)
				{
					break;
				}
				_target.buffComponent.AddBuff(13295011, _actor);
			}
		}

		public void Update(FP deltaTime)
		{
			if (!IsValid())
			{
				return;
			}
			if (GetBuffCount() > 0)
			{
				if (_duration > 0)
				{
					_duration -= deltaTime;
					return;
				}
				_duration = duration;
				_target.buffComponent.RemoveBuffByBuffId(13295011, 1);
				_reduceCountCallBack?.Invoke(_target);
			}
			else
			{
				_duration = duration;
			}
		}

		public int GetBuffCount()
		{
			if (!IsValid())
			{
				return 0;
			}
			return _target.buffComponent.GetBuffNumByID(13295011);
		}

		public long GetTargetId()
		{
			return _targetId;
		}

		private bool IsValid()
		{
			if (_actor == null)
			{
				return false;
			}
			return CommonUtils.CheckTargetIsValid(_target, _targetId, ingoreSearchedImmunity: true);
		}

		public void Clear()
		{
			_targetId = 0L;
			_target = null;
			_reduceCountCallBack = null;
		}
	}
	public class ParallelScript_Support : ParallelScript
	{
		private static readonly int damageTag_Skill = CommonHelper.StringToHash("132_Support_Hurt");

		private const int addStarBuffCount = 2;

		private const string areaEffectKey_Explosion = "AreaEffect_132_Support_StarBurst";

		private static readonly int areaEffectTag_Explosion = CommonHelper.StringToHash("132_Support_StarBurst");

		private static readonly int damageTag_Explosion = CommonHelper.StringToHash("132_Support_StarBoom");

		private const int perkId_21 = 513221;

		private const int addStarBuffCount_P21 = 13221011;

		private static readonly int damageTag_P21 = CommonHelper.StringToHash("132_Support_SectorStar");

		private const int additionalAttrId_P21 = 13221011;

		private const int perkId_22 = 513222;

