			if (!(adventureActorCastSkillEvent.sender as PlayerAdventureActor != _actor) && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.D)
			{
				_addCount_P43 = 0;
			}
		}

		private void OnBulletBorn(IEvent evt)
		{
			AdventureBulletBornEvent adventureBulletBornEvent = evt as AdventureBulletBornEvent;
			if (adventureBulletBornEvent.owner == _actor && adventureBulletBornEvent.bulletHashCode == bulletTag_D2)
			{
				_ = adventureBulletBornEvent.sender as AdventureWeapon != null;
			}
		}

		private void OnAreaEffectFinish(IEvent evt)
		{
			AdventureAreaEffectFinishEvent adventureAreaEffectFinishEvent = evt as AdventureAreaEffectFinishEvent;
			if (adventureAreaEffectFinishEvent.owner == _actor)
			{
				_ = adventureAreaEffectFinishEvent.durationEnd;
			}
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (!(adventureActorReceiveDamageBeforeHitEvent.from is PlayerAdventureActor) || !(adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor))
			{
				return;
			}
			if (adventureActorReceiveDamageBeforeHitEvent.from == _actor)
			{
				if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, damageTag_PenetratingArrow))
				{
					int num = _actor.DistanceWithRadius(adventureActorReceiveDamageBeforeHitEvent.to).AsInt();
					if (num > 0)
					{
						int num2 = num;
						num2 = ((num2 > 20) ? 20 : num2);
						if (num2 > 0)
						{
							AdventureActor.AddFromAttr(13091001, _actor, num2);
						}
					}
				}
				if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, damageTag_Ultra))
				{
					if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513041, out var perkLevel))
					{
						AdventureActor.AddFromAttr(13041001, _actor);
					}
					if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513043, out perkLevel) && _addCount_P43 > 0)
					{
						AdventureActor.AddFromAttr(13043001, _actor, _addCount_P43);
					}
				}
				OnSelfBeforeHit(adventureActorReceiveDamageBeforeHitEvent);
			}
			OnPlayerBeforeHit(adventureActorReceiveDamageBeforeHitEvent);
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.from == _actor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor))
			{
				return;
			}
			MonsterAdventureActor monsterAdventureActor = adventureActorReceiveDamageEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513043, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, damageTag_Ultra))
			{
				int num = CommonUtils.GetScriptValue(_actor, 13043013).AsInt();
				if (monsterAdventureActor.isFrozen && _addCount_P43 < num)
				{
					FP scriptValue = CommonUtils.GetScriptValue(_actor, 13043011);
					List<AreaEffectEntity> areaEffectByTag = ILRuntimeAPI.GetAreaEffectByTag(areaEffectTag_Ultra);
					for (int i = 0; i < areaEffectByTag.Count; i++)
					{
						areaEffectByTag[i]?.AddLeftTime(scriptValue);
					}
					_addCount_P43++;
				}
			}
			OnSelfDamaged(adventureActorReceiveDamageEvent);
			if (CheckCanTriggerWaterCorrosion(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag))
			{
				TriggerWaterCorrosion(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag);
			}
		}

		private bool CheckCanTriggerWaterCorrosion(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (_damageTag_TriggerWaterCorrosion == null || _damageTag_TriggerWaterCorrosion.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Water, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				for (int i = 0; i < _damageTag_TriggerWaterCorrosion.Count; i++)
				{
					int hitTag = _damageTag_TriggerWaterCorrosion[i];
					if (CommonUtils.CheckHitByTag(hitDamageTag, hitTag))
					{
						return true;
					}
				}
			}
			return false;
		}

		private void TriggerWaterCorrosion(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			monster.buffComponent.RemoveBuffByTag(CommonDefine.Water);
			monster.buffComponent.AddBuff(4021, _actor);
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_130_WaterTag1_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			if (monster.buffComponent.GetBuffNum(0, 0, tag_Cold) >= 3)
			{
				monster.buffComponent.RemoveBuffByTag(tag_Cold);
				monster.buffComponent.AddBuff(4100, _actor);
			}
			OnTriggerWaterCorrosion(monster, hitDamageTag);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.Water, GameEnum.AdventureActorElementTriggerType.WaterElementTriggerType1, _actor, monster, "WaterMark_Trigger_Effect_05");
		}

		protected virtual void OnSelfBeforeHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		protected virtual void OnPlayerBeforeHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		protected virtual void OnTriggerWaterCorrosion(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
		}

		private void Clear()
		{
			_normalAttackBulletDic_D2?.Clear();
			_addCount_P43 = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_BORN", OnBulletBorn);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			Clear();
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
