					ILRuntimeAPI.ShootByDirection("Bullet_130_B1_Attack_P05", _actor, default(FP), shootDir, tSVector, slotNode.transform.position.y);
					num2++;
					num2 = ((num2 < shootSlotList_P5.Count) ? num2 : 0);
				}
				_actor.buffComponent.RemoveBuffByBuffId(13005011);
			}
		}

		public virtual void OnUpdate()
