			{
				string text = GetAreaEffectPath();
				TSVector2 tSVector = ((_actor.attackTarget != null) ? _actor.attackTarget.tsTransform.Position : (_actor.tsTransform.Position + _actor.tsTransform.Forward * offset_NoTarget));
				if (!string.IsNullOrEmpty(text))
				{
					AdventureActor actor = _actor;
					Action<AreaEffectEntity> action = OnMainAreaEffectBeforSetup;
