		private void OnMainAreaEffectBeforSetup(AreaEffectEntity areaEffect)
		{
			AreaEffect_BuffComponent logicComponent = areaEffect.GetLogicComponent<AreaEffect_BuffComponent>();
			if (logicComponent != null)
			{
				if (logicComponent.addBuffIdList == null)
				{
					logicComponent.addBuffIdList = new List<int>();
				}
				else
				{
					logicComponent.addBuffIdList.Clear();
				}
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513042, out var _))
				{
					logicComponent.addBuffIdList.Add(13042011);
					logicComponent.addInterval = addBuffInterval_42;
					logicComponent.addCriteriaInfo = new TargetFilterCriteriaInfo
					{
						filterCriteriaList = new List<TargetFilterCriteriaInfo.TargetFilterCriteria>
						{
							new TargetFilterCriteriaInfo.TargetFilterCriteria
							{
								targetType = TargetFilterCriteriaInfo.TargetTypeMapping.Friend
							}
						}
					};
					logicComponent.executeImmediately = true;
				}
				else
				{
					logicComponent.addInterval = 0;
					logicComponent.executeImmediately = false;
				}
			}
		}

