		protected override void OnCustomEvent(string eventName)
		{
			base.OnCustomEvent(eventName);
			if (string.Equals(eventName, "StartIceRain"))
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = this;
				adventureActorCustomEvent.actor = _actor;
				adventureActorCustomEvent.eventName = "StartIceRain";
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513023, out var perkLevel) && string.Equals(eventName, "B2P23_Shoot"))
			{
				FP fP = _actor.logicVariable.GetLogicTagValue("TriggerRate_P23");
				if (fP <= 0)
				{
					fP = CommonUtils.GetScriptValue(_actor, 13023011);
				}
				if (TSRandom.Range(0f, 100f) <= fP)
				{
					if (!string.IsNullOrEmpty("Bullet_130_B2P23_Attack"))
					{
						if (_bulletDirList_23 == null)
						{
							_bulletDirList_23 = new List<TSVector2>(7);
						}
						else
						{
							_bulletDirList_23.Clear();
						}
						for (int i = 1; i <= 4; i++)
						{
							_bulletDirList_23.Add(TSVector2.Rotate(_actor.tsTransform.Forward, includedAngle_23 * i).normalized);
							_bulletDirList_23.Add(TSVector2.Rotate(_actor.tsTransform.Forward, -includedAngle_23 * i).normalized);
						}
						TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Left * shootOffset_23.x + _actor.tsTransform.Forward * shootOffset_23.z;
						for (int j = 0; j < _bulletDirList_23.Count; j++)
						{
							ILRuntimeAPI.ShootByDirection("Bullet_130_B2P23_Attack", _actor, default(FP), _bulletDirList_23[j], position, shootOffset_23.y);
						}
					}
					fP = CommonUtils.GetScriptValue(_actor, 13023011);
				}
				else
				{
					fP += CommonUtils.GetScriptValue(_actor, 13023012);
				}
				_actor.logicVariable.SetLogicTagValue("TriggerRate_P23", fP);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 513024, out perkLevel) && string.Equals(eventName, "B2P30_Shoot") && _actor.attackTarget != null)
			{
				ILRuntimeAPI.SearchByRangeAndPosition(_actor, _actor.attackTarget.tsTransform.Position, searchRadius_24, OnSearchTargetFinish_24, isConfront: true);
			}
		}

		private void OnSearchTargetFinish_24(List<LogicEntity> targets)
		{
			if (targets == null || targets.Count <= 0)
			{
				return;
			}
			TSVector2 position = _actor.tsTransform.Position + _actor.tsTransform.Left * shootOffset_24.x + _actor.tsTransform.Forward * shootOffset_24.z;
			if (targets.Count == 1)
			{
				LogicEntity logicEntity = targets[0];
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_2", _actor, default(FP), position, shootOffset_24.y, logicEntity.tsTransform.Position, logicEntity, AimType.Target, BulletDirectionType.BulletToTarget);
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_4", _actor, default(FP), position, shootOffset_24.y, logicEntity.tsTransform.Position, logicEntity, AimType.Target, BulletDirectionType.BulletToTarget);
			}
			else if (targets.Count == 2)
			{
				LogicEntity logicEntity2 = targets[0];
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_1", _actor, default(FP), position, shootOffset_24.y, logicEntity2.tsTransform.Position, logicEntity2, AimType.Target, BulletDirectionType.BulletToTarget);
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_2", _actor, default(FP), position, shootOffset_24.y, logicEntity2.tsTransform.Position, logicEntity2, AimType.Target, BulletDirectionType.BulletToTarget);
				logicEntity2 = targets[1];
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_4", _actor, default(FP), position, shootOffset_24.y, logicEntity2.tsTransform.Position, logicEntity2, AimType.Target, BulletDirectionType.BulletToTarget);
				ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_5", _actor, default(FP), position, shootOffset_24.y, logicEntity2.tsTransform.Position, logicEntity2, AimType.Target, BulletDirectionType.BulletToTarget);
			}
			else
			{
				if (targets.Count < 3)
				{
					return;
				}
				LogicEntity logicEntity3 = (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor)?.attackTarget;
				if (logicEntity3 != null && targets.Remove(logicEntity3))
				{
					targets.Insert(0, logicEntity3);
				}
				int num = 5;
				while (num > 0)
				{
					for (int i = 0; i < targets.Count; i++)
					{
						if (num <= 0)
						{
							break;
						}
						LogicEntity logicEntity4 = targets[i];
						switch (TSRandom.Range(0, 5))
						{
						case 0:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_1", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						case 1:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_2", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						case 2:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_3", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						case 3:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_4", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						case 4:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_5", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						default:
							ILRuntimeAPI.Shoot("Bullet_130_B2P30_Attack_3", _actor, default(FP), position, shootOffset_24.y, logicEntity4.tsTransform.Position, logicEntity4, AimType.Target, BulletDirectionType.BulletToTarget);
							break;
						}
						num--;
					}
				}
			}
		}

		protected override void OnReceiveDamage(IEvent evt)
		{
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
