		public bool CheckCd(int perkId, FP Cd)
		{
			if (Cd <= 0)
			{
				return true;
			}
			bool result = false;
			if (perkCd.TryGetValue(perkId, out var value))
			{
				if (_actor.LogicTime - value > Cd)
				{
					result = true;
					perkCd[perkId] = _actor.LogicTime;
				}
			}
			else
			{
				perkCd.Add(perkId, _actor.LogicTime);
				result = true;
			}
			return result;
		}

