	public class SkillScript_Support : SkillAdvancedBase
	{
		private string key_base = "127_B2_Skill";

		private string evt_water = "127WaterArea";

		private FP loopTime = 6.4;

		private const int perkId_23 = 512723;

		private FP loopTime_23 = 10.4;

		private int shieldEvent = CommonHelper.StringToHash("127SupportAddShield");

		private int castAreaEvent = CommonHelper.StringToHash("CastArea");

		private CoroutineNode corMain;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			StopCoroutine(ref corMain);
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		private void SkillFinish()
		{
			_skill?.Clear();
		}

		private void SkillInterrupt()
		{
			_skill?.Clear();
		}

		private IEnumerator DoMainLogic()
		{
			int lv;
			bool perkLv = GetPerkLv(512723, out lv);
			string actionTag = key_base;
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			if (assistantAttackTarget != null)
			{
				_actor.LookAt(assistantAttackTarget.tsTransform.Position, 0);
			}
			SkillScript_Support skillScript_Support = this;
			Action<string> action = onCustomEvent;
			System.Action onComboFinish = SkillFinish;
			System.Action onInterrupt = SkillInterrupt;
			skillScript_Support.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
			yield return _actor.WaitTime(perkLv ? loopTime_23 : loopTime);
			_actor.CancelAttack();
		}

		private void onCustomEvent(string evt)
		{
			if (evt.Equals(evt_water))
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = shieldEvent;
				_actor.DispatchEvent(adventureActorCustomEvent);
				adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventHashCode = castAreaEvent;
				_actor.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private string key_1 = "127_Ultra_TL";

		private string key_2 = "127_Ultra_NoTL";

		private string bullut_base = "Bullet_127_Ultra_Branch";

		private string evt_shoot = "127BranchBullet";

		private string evt_area = "127WaterArea";

		private string evt_lookAt = "127_LookAtTarget";

		private FP shootOffset = 7.8;

		private FP visionAttackRng = 18;

		private FP hearAttackRng = 18;

		private const int perkId_41 = 512741;

		private const int buff_41_1 = 12754111;

		private const int buff_41_2 = 12754112;

		private PlayerAdventureActor mainCtrActor;

		private CoroutineNode corMain;

		private CoroutineNode corSupport;

		private string actionKey;

		private PlayTimeline _playTimeline = new PlayTimeline();

		private FP orgVisionAttackRng;

		private FP orgHearAttackRng;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_actor.EnableInvincible();
			mainCtrActor = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor;
			orgVisionAttackRng = _actor.actorSearchTargetInfo.visionRange;
			orgHearAttackRng = _actor.actorSearchTargetInfo.hearRange;
			_actor.actorSearchTargetInfo.visionRange = visionAttackRng;
			_actor.actorSearchTargetInfo.hearRange = hearAttackRng;
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.DisableInvincible();
			_actor.actorSearchTargetInfo.visionRange = orgVisionAttackRng;
			_actor.actorSearchTargetInfo.hearRange = orgHearAttackRng;
			StopCoroutine(ref corMain);
			StopCoroutine(ref corSupport);
		}

		public void OnStart()
		{
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				DoSupportSkill();
			}
			else
			{
				DoMainSkill();
			}
		}

		protected void onFinishOrInterrupt()
		{
			_skill.Clear();
		}

		private void DoMainSkill()
		{
			_playTimeline.Play(_actor, delegate
			{
				ParseKey(timeline: true);
				StartCoroutine(ref corMain, DoMainLogic());
			}, delegate
			{
				ParseKey(timeline: false);
				StartCoroutine(ref corMain, DoMainLogic());
			});
		}

		private void ParseKey(bool timeline)
		{
			actionKey = (timeline ? key_1 : key_2);
		}

		private IEnumerator DoMainLogic()
		{
			SkillScript_Ultra skillScript_Ultra = this;
			string actionTag = actionKey;
			Action<string> action = onCustomEvent;
			System.Action onComboFinish = onFinishOrInterrupt;
			System.Action onInterrupt = onFinishOrInterrupt;
			skillScript_Ultra.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
			yield break;
		}

		private void DoSupportSkill()
		{
			_playTimeline.Play(_actor, delegate
			{
				ParseKey(timeline: true);
				StartCoroutine(ref corSupport, DoSupportLogic());
			}, delegate
			{
				ParseKey(timeline: false);
				StartCoroutine(ref corSupport, DoSupportLogic());
			});
		}

		private IEnumerator DoSupportLogic()
		{
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			SkillScript_Ultra skillScript_Ultra = this;
			string actionTag = actionKey;
			Action<string> action = onCustomEvent;
			System.Action onInterrupt = onFinishOrInterrupt;
			System.Action onComboFinish = onFinishOrInterrupt;
			skillScript_Ultra.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, assistantAttackTarget, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
			yield break;
		}

		private void onCustomEvent(string eventName)
		{
			if (eventName.Equals(evt_shoot))
			{
				Shoot(_actor.tsTransform.Left);
				Shoot(_actor.tsTransform.Right);
			}
			else if (eventName.Equals(evt_lookAt) && _actor.attackTarget != null)
			{
				_actor.LookAt(_actor.attackTarget.tsTransform.Position, 0);
			}
		}

		private void Shoot(TSVector2 shootDir)
		{
			WeaponFeatureBuffTrigger component = ILRuntimeAPI.ShootByDirection(bullut_base, _actor, 0, shootDir, _actor.tsTransform.Position + _actor.tsTransform.Forward * shootOffset).GetComponent<WeaponFeatureBuffTrigger>();
			if (component != null)
			{
				component.buffConfigs.Clear();
				if (GetPerkLv(512741, out var _))
				{
					BuffConfig buffConfig = new BuffConfig();
					buffConfig.buffList = new List<int> { 12754111 };
					buffConfig.isRemove = false;
					buffConfig.buffTargetType = TargetType.Enemy;
					component.buffConfigs.Add(buffConfig);
					buffConfig = new BuffConfig();
					buffConfig.buffList = new List<int> { 12754112 };
					buffConfig.isRemove = false;
					buffConfig.buffTargetType = TargetType.Friend;
					component.buffConfigs.Add(buffConfig);
				}
			}
		}

		private bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
}
namespace AIScript.Character._12601
{
	public class Action : ActorActionBase
	{
		private readonly int normalPhaseCount = 3;

		private PlayerSkillCd _skillManage;

		private ActorSearchTarget actorSearchInfo;

		private IState curState;

		private NormalAttackState normalAttackState = new NormalAttackState();

		private SkillState skillState;

		private AimTarget _aimTarget = new AimTarget();

		private int curNormalPhase;

		protected override void OnActionEnable()
		{
			_skillManage = _actor.GetLogicComponent<PlayerSkillCd>();
			actorSearchInfo = _actor.GetLogicComponent<ActorSearchTarget>();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			normalAttackState.Init(_actor, _skillManage, _aimTarget);
			curNormalPhase = 0;
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			Clear();
		}

		public override void OnStart()
		{
			base.OnStart();
			DoMainLogic();
		}

		public void OnUpdate()
		{
			MainLoop();
		}

		public override void OnStop()
		{
			base.OnStop();
			Clear();
		}

		private void Clear()
		{
			_aimTarget.Cancel();
			_actor.movementMode = AdventureActor.MovementMode.Run;
		}

		protected override void OnButtonAPress()
		{
			CastSkill(ActionKey.A, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			CastSkill(ActionKey.B, SkillPhaseFeatureFlag.Skill1);
			_actor.logicVariable.ToggleLogicTag("HoldingKeyD", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable?.ToggleLogicTag("HoldingKeyD", value: false);
		}

		protected override bool CastIndependentRushSkill()
		{
			return CastSkill(ActionKey.C, SkillPhaseFeatureFlag.Skill2, 0, isInterruptAttack: true, isRushJoinDodge: false);
		}

		protected override void OnButtonDPress()
		{
			CastSkill(ActionKey.D, SkillPhaseFeatureFlag.Ultimate);
		}

		private void OnTrCastSkill(IEvent _evt)
		{
			ActorTryCastSkill actorTryCastSkill = _evt as ActorTryCastSkill;
			if (actorTryCastSkill.sender as AdventureActor == _actor)
			{
				CastSkill(ActionKey.None, actorTryCastSkill.flag, actorTryCastSkill.skillId, actorTryCastSkill.isInterruptAttack);
			}
		}

		private bool CastSkill(ActionKey key, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int skillId = 0, bool isInterruptAttack = true, bool isRushJoinDodge = true)
		{
			skillState = new SkillState();
			skillState.Init(_actor, _skillManage, _aimTarget);
			skillState.actionKey = key;
			skillState.specialSkill = skillId;
			skillState.skillPhaseFeatureFlag = skillPhaseFeatureFlag;
			skillState.isInterruptAttack = isInterruptAttack;
			skillState.isRushJoinDodge = isRushJoinDodge;
			skillState.Enter();
			if (skillState.CanCast)
			{
				if (key == ActionKey.D || key == ActionKey.None)
				{
					ResetNormalPharse();
				}
				curState?.Exit();
				curState = skillState;
			}
			return skillState.CanCast;
		}

		private void DoMainLogic()
		{
		}

		private void MainLoop()
		{
			if (curState == null || !curState.isInUltimate)
			{
				_actor.attackTarget = actorSearchInfo.GetLockingConfrontActor(useInputDirection: true);
			}
			curState?.Update();
			if (curState == null || curState.IsEnd)
			{
				curState = GetNextState();
				curState?.Enter();
			}
		}

		private IState GetNextState()
		{
			if (_actor.attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
				bool isObstacleBetweenActorAndTargetAndPreventNormalAttack = base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack;
				bool flag = fP <= CommonUtils.GetAimRange(_actor);
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					if (isObstacleBetweenActorAndTargetAndPreventNormalAttack || !flag)
					{
						_aimTarget.Cancel();
					}
				}
				else if (flag && !(_actor as PlayerAdventureActor).dodgeButtonHold && !isObstacleBetweenActorAndTargetAndPreventNormalAttack)
				{
					_aimTarget.Aim(_actor, _actor.attackTarget as AdventureActor);
				}
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && CommonUtils.GetAttackRange(_actor) > fP)
				{
					curNormalPhase = curNormalPhase % normalPhaseCount + 1;
					_actor.logicVariable.SetLogicTagValue("curNormalPhase", curNormalPhase);
					return normalAttackState;
				}
			}
			else if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
			{
				_aimTarget.Cancel();
			}
			ResetNormalPharse();
			return null;
		}

		private void ResetNormalPharse()
		{
			curNormalPhase = 0;
		}
	}
	public enum fsmStatus
	{
		Enter,
		Exit
	}
	public class IState
	{
		private fsmStatus fsmStatus;

		public AdventureActor _actor;

		public PlayerSkillCd _skillManage;

		public AimTarget _aimTarget;

		public bool isInUltimate;

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public void Init(AdventureActor actor, PlayerSkillCd skillManager, AimTarget aimTarget)
		{
			_actor = actor;
			_skillManage = skillManager;
			_aimTarget = aimTarget;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
		}

		public LogicEntity GetAttackTarget()
		{
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				return CommonUtils.GetAssistantAttackTarget(_actor);
			}
			return _actor.attackTarget;
		}
	}
	public class NormalAttackState : IState
	{
		public override void Enter()
		{
			base.Enter();
			if (!ILRuntimeAPI.CreateSkill(_skillManage.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
			{
				Exit();
			}))
			{
				Exit();
			}
		}

		public override void Update()
		{
			base.Update();
			if (GetAttackTarget() != null && _actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
			{
				_actor.InterruptAttack(force: true);
			}
		}
	}
	public class SkillState : IState
	{
		public ActionKey actionKey;

		public SkillPhaseFeatureFlag skillPhaseFeatureFlag;

		public bool CanCast;

		public int specialSkill;

		public bool isInterruptAttack;

		public bool isRushJoinDodge;

		public override void Enter()
		{
			base.Enter();
			SkillCountdownTiming skillCountdownTiming = SkillCountdownTiming.Start;
			int currentBindSkillId;
			if (specialSkill != 0)
			{
				currentBindSkillId = specialSkill;
			}
			else
			{
				currentBindSkillId = _skillManage.GetCurrentBindSkillId(actionKey);
				if (actionKey == ActionKey.B)
				{
					skillCountdownTiming = SkillCountdownTiming.End;
				}
				if (actionKey == ActionKey.D)
				{
					isInUltimate = true;
				}
			}
			if (currentBindSkillId == 12631001 && _actor.attackFSM.isPlayingCombo)
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.eventName = "126_B1_HatReturn";
				_actor.DispatchEvent(adventureActorCustomEvent);
				AdventureActorCustomEvent adventureActorCustomEvent2 = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent2.eventName = "Stop_B_S2";
				_actor.DispatchEvent(adventureActorCustomEvent2);
				return;
			}
			int skillId = currentBindSkillId;
			AdventureActor actor = _actor;
			SkillPhaseFeatureFlag skillCastBehaviourType = skillPhaseFeatureFlag;
			SkillCountdownTiming countdownTiming = skillCountdownTiming;
			CanCast = ILRuntimeAPI.CreateSkill(skillId, actor, skillCastBehaviourType, SkillLauncherType.Character, isInterruptAttack, isBreakable: false, countdownTiming, delegate
			{
				Exit();
				isInUltimate = false;
			}, null, ingoreCDAndEnergy: false, isRushJoinDodge);
		}

		public override void Update()
		{
			base.Update();
			if (GetAttackTarget() != null && _actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
			{
				_actor.InterruptAttack(force: true);
			}
		}
	}
