		private void OnSearchTargetFinish(List<LogicEntity> targets)
		{
			if (targets == null || targets.Count <= 0)
			{
				for (int i = 0; i < ShootButtleCount; i++)
				{
					ILRuntimeAPI.Shoot(bullut_flameButter_Base[i], position: _actor.tsTransform.Position + _actor.tsTransform.Left * shootOffset.x + _actor.tsTransform.Forward * shootOffset.z, targetPosition: _actor.tsTransform.Position + _actor.tsTransform.Forward * searchRadius, actor: _actor, range: default(FP), positionY: shootOffset.y, target: null, aimType: AimType.Position, bulletDirectionType: BulletDirectionType.BulletToTarget);
				}
			}
			else
			{
				if (bullut_flameButter_Base.Count <= 0)
				{
					return;
				}
				if (_targets == null)
				{
					_targets = new List<LogicEntity>(10);
				}
				else
				{
					_targets.Clear();
				}
				targets.Sort((LogicEntity x, LogicEntity y) => (!(TSVector2.Distance(x.tsTransform.Position, _actor.tsTransform.Position) < TSVector2.Distance(y.tsTransform.Position, _actor.tsTransform.Position))) ? 1 : (-1));
				bool flag = false;
				if (_actor.attackTarget != null)
				{
					for (int num = 0; num < targets.Count; num++)
					{
						if (targets[num].Id == _actor.attackTarget.Id)
						{
							_targets.Add(targets[num]);
							flag = true;
							break;
						}
					}
					for (int num2 = 0; num2 < targets.Count; num2++)
					{
						if (targets[num2].Id != _actor.attackTarget.Id)
						{
							_targets.Add(targets[num2]);
						}
					}
				}
				else
				{
					_targets.AddRange(targets);
				}
				int num3 = 0;
				int num4 = 0;
				bool flag2 = false;
				while (true)
				{
					LogicEntity logicEntity = _targets[num4] ?? _targets[0];
					string bulletAlias = bullut_flameButter_Base[num3];
					string text = "126_Split_" + logicEntity.Id;
					if (!baseButtleAimMonsterTag.ContainsKey(logicEntity.Id))
					{
						baseButtleAimMonsterTag.Add(logicEntity.Id, text);
					}
					ILRuntimeAPI.Shoot(position: _actor.tsTransform.Position + _actor.tsTransform.Left * shootOffset.x + _actor.tsTransform.Forward * shootOffset.z, bulletAlias: bulletAlias, actor: _actor, range: default(FP), positionY: shootOffset.y, targetPosition: logicEntity.tsTransform.Position, target: logicEntity, aimType: AimType.Target, bulletDirectionType: BulletDirectionType.BulletToTarget).bulletTag = text;
					num3++;
					if (num3 >= ShootButtleCount)
					{
						break;
					}
					if (flag2)
					{
						if (flag)
						{
							num4 = 0;
							continue;
						}
						num4++;
						num4 = ((num4 < _targets.Count) ? num4 : 0);
						continue;
					}
					num4++;
					if (num4 >= _targets.Count)
					{
						flag2 = true;
						num4 = 0;
					}
				}
			}
		}

		private void OnSearchTargetFinish_Prek30(List<LogicEntity> targets)
		{
			if (targets == null || targets.Count <= 0 || bullut_flameButter_Prek30.Count <= 0)
			{
				return;
			}
			if (_targets_Prek30 == null)
			{
				_targets_Prek30 = new List<LogicEntity>(10);
			}
			else
			{
				_targets_Prek30.Clear();
			}
			targets.Sort((LogicEntity x, LogicEntity y) => (!(TSVector2.Distance(x.tsTransform.Position, _actor.tsTransform.Position) < TSVector2.Distance(y.tsTransform.Position, _actor.tsTransform.Position))) ? 1 : (-1));
			bool lockAttackTarget = false;
			if (mainCtrActor.attackTarget != null)
			{
				for (int num = 0; num < targets.Count; num++)
				{
					if (targets[num].Id == mainCtrActor.attackTarget.Id)
					{
						_targets_Prek30.Add(targets[num]);
						lockAttackTarget = true;
						break;
					}
				}
				for (int num2 = 0; num2 < targets.Count; num2++)
				{
					if (targets[num2].Id != mainCtrActor.attackTarget.Id)
					{
						_targets_Prek30.Add(targets[num2]);
					}
				}
			}
			else
			{
				_targets_Prek30.AddRange(targets);
			}
			int shootCount = ashButterflyCount;
			if (GetPerkLv(perkId_23, out var _))
			{
				shootCount = ashButterfly_P23_Count;
			}
			if (CorShootPrek30 != null)
			{
				_actor.StopLogicCoroutine(CorShootPrek30);
				CorShootPrek30 = null;
			}
			CorShootPrek30 = _actor.StartLogicCoroutine(Shoot_Prep30(shootCount, lockAttackTarget));
		}

		private IEnumerator Shoot_Prep30(int shootCount, bool lockAttackTarget)
		{
			int bulletIndex = 0;
			int targetIndex = 0;
			bool firstRoundFinish = false;
			while (true)
			{
				LogicEntity logicEntity = _targets_Prek30[targetIndex] ?? _targets_Prek30[0];
				ILRuntimeAPI.Shoot(bullut_flameButter_Prek30[bulletIndex], position: mainCtrActor.tsTransform.Position + mainCtrActor.tsTransform.Left * shootOffset_30.x + mainCtrActor.tsTransform.Forward * shootOffset_30.z, actor: _actor, range: default(FP), positionY: shootOffset_30.y, targetPosition: logicEntity.tsTransform.Position, target: logicEntity, aimType: AimType.Target, bulletDirectionType: BulletDirectionType.BulletToTarget);
				bulletIndex++;
				if (bulletIndex >= shootCount)
				{
					break;
				}
				if (firstRoundFinish)
				{
					if (lockAttackTarget)
					{
						targetIndex = 0;
					}
					else
					{
						targetIndex++;
						targetIndex = ((targetIndex < _targets_Prek30.Count) ? targetIndex : 0);
					}
				}
				else
				{
					targetIndex++;
					if (targetIndex >= _targets_Prek30.Count)
					{
						firstRoundFinish = true;
						targetIndex = 0;
					}
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(perkId_30_ShootInterval));
			}
		}

		protected override void OnBulletFinish(AdventureBulletFinishEvent _evt)
		{
			base.OnBulletFinish(_evt);
			if (!(_evt.owner is PlayerAdventureActor))
			{
				return;
			}
			string tag = _evt.tag;
			if (!tag.Contains("126_Split_"))
			{
				return;
			}
			long num = 0L;
			foreach (KeyValuePair<long, string> item in baseButtleAimMonsterTag)
			{
				if (item.Value == tag)
				{
					num = item.Key;
					break;
				}
			}
			if (num != 0L)
			{
				baseButtleAimMonsterTag.Remove(num);
			}
		}

		protected override void OnMonsterDeath(MonsterAdventureActor monster)
		{
			base.OnMonsterDeath(monster);
			if (baseButtleKillMonster.Contains(monster.Id) || ((!monster.buffComponent || !monster.buffComponent.CheckBuffByBuffID(flameTotemBuffId)) && !baseButtleAimMonsterTag.ContainsKey(monster.Id)))
			{
				return;
			}
			if (baseButtleAimMonsterTag.ContainsKey(monster.Id))
			{
				baseButtleAimMonsterTag.Remove(monster.Id);
			}
			baseButtleKillMonster.Add(monster.Id);
			List<LogicEntity> list = MonsterDeathGetTarget(monster.tsTransform.Position, monster.Id);
			if (list.Count > 0)
			{
				string text = "126_Split_" + list[0].Id;
				if (!baseButtleAimMonsterTag.ContainsKey(list[0].Id))
				{
					baseButtleAimMonsterTag.Add(list[0].Id, text);
				}
				ILRuntimeAPI.Shoot(bullut_flameButter_KillMonster, _actor, default(FP), monster.tsTransform.Position, 1.5, list[0].tsTransform.Position, list[0], AimType.Target, BulletDirectionType.BulletToTarget).bulletTag = text;
			}
			else
			{
				CoroutineNode item = _actor.StartLogicCoroutine(MonsterKilledGetTarget(monster.transform.position, monster.tsTransform.Position, monster.Id));
				corGetTargetList.Add(item);
			}
		}

		private IEnumerator MonsterKilledGetTarget(Vector3 fxPos, TSVector2 pos, long id)
		{
			PlayFX _playFX = new PlayFX();
			_playFX.Play(spawnPosition: new Vector3(fxPos.x, 0.5f, fxPos.z), actor: _actor, fxAlias: fx_KillMonster_Name, playbackSpeed: 1f, spawnRotation: Quaternion.identity);
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.2));
			for (int getCount = 0; getCount < 14; getCount++)
			{
				List<LogicEntity> list = MonsterDeathGetTarget(pos, id);
				if (list.Count > 0)
				{
					_playFX.Stop();
					string text = "126_Split_" + list[0].Id;
					if (!baseButtleAimMonsterTag.ContainsKey(list[0].Id))
					{
						baseButtleAimMonsterTag.Add(list[0].Id, text);
					}
					ILRuntimeAPI.Shoot(bullut_flameButter_KillMonster, _actor, default(FP), pos, 1.5, list[0].tsTransform.Position, list[0], AimType.Target, BulletDirectionType.BulletToTarget).bulletTag = text;
					yield break;
				}
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0.2));
			}
			_playFX.Stop();
		}

		public List<LogicEntity> MonsterDeathGetTarget(TSVector2 pos, long id)
		{
			DeterministicShape deterministicCircleShape = CommonUtils.GetDeterministicCircleShape(searchRadius, 0, pos);
			List<LogicEntity> monstersFromShape = ILRuntimeAPI.GetMonstersFromShape(_actor, deterministicCircleShape);
			if (monstersFromShape.Count > 0)
			{
				for (int num = monstersFromShape.Count - 1; num >= 0; num--)
				{
					LogicEntity logicEntity = monstersFromShape[num];
					AdventureActor component = logicEntity.GetComponent<AdventureActor>();
					if (logicEntity.Id == id || (component != null && (!component.actorHealthInfo.isAlive || component.state == ActorState.Spawn || component.state == ActorState.Death || logicEntity.IsSearchedImmunity())))
					{
						monstersFromShape.RemoveAt(num);
					}
				}
				if (monstersFromShape.Count > 0)
				{
					monstersFromShape.Sort((LogicEntity x, LogicEntity y) => (!(TSVector2.Distance(x.tsTransform.Position, pos) < TSVector2.Distance(y.tsTransform.Position, pos))) ? 1 : (-1));
				}
			}
			return monstersFromShape;
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey actionKey = ComboInputBuffer.ActionKey.D;

		private readonly FP duration = 0.3;

		private readonly FP distance = 0.01;

		private readonly int _transitionRushSkillId;

		protected Dodge _dodge;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			base.comboAttack?.Clear();
		}

		private void DoMainLogic()
		{
			_actor.PlayFX("fx_10501_base_skill1_1_shadow");
			ComboInputBuffer.ActionKey key = actionKey;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, duration, distance, null, comboWithAttack: true);
		}

		protected void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ActorTryCastSkill actorTryCastSkill = ActorTryCastSkill.Generate();
					actorTryCastSkill.sender = _actor;
					actorTryCastSkill.skillId = specialSkillId;
					actorTryCastSkill.isInterruptAttack = false;
					actorTryCastSkill.flag = SkillPhaseFeatureFlag.Skill2;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(actorTryCastSkill);
					OnFinish();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() && _transitionRushSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(_transitionRushSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
				OnFinish();
			}
		}

		protected void OnFinish()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}
	}
