namespace AIScript.Character._12501
{
	public class ActionScript : ActorActionBase
	{
		private CoroutineNode _berserkCor;

		private int _buffId_BerserkTiming;

		private int _timingBuffCount_EnterBerserk;

		private FP _reduceTimingBuffInterval;

		private FP _delayNormalAttackStageDelay;

		protected bool InBerserkState
		{
			get
			{
				if (((PlayerAdventureActor)_actor).status == ActorStatus.Special)
				{
					return ((PlayerAdventureActor)_actor).specialStatusTime > 0;
				}
				return false;
			}
		}

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			_buffId_BerserkTiming = 12500002;
			_timingBuffCount_EnterBerserk = 20;
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			AdventureActorCustomEvent adventureActorCustomEvent = evt as AdventureActorCustomEvent;
			if (!(adventureActorCustomEvent.actor != _actor) && adventureActorCustomEvent.eventHashCode == Config.eventHashCode_EnterBerserk)
			{
				EnterBerserk(_timingBuffCount_EnterBerserk);
			}
		}

		protected void EnterBerserk(int timingBuffCount)
		{
			for (int i = 0; i < timingBuffCount; i++)
			{
				_actor.buffComponent?.AddBuff(_buffId_BerserkTiming, _actor);
			}
			_reduceTimingBuffInterval = Config.interval_ReduceTimingBuffCount;
			if (_berserkCor == null)
			{
				_berserkCor = _actor.StartLogicCoroutine(BerserkState());
			}
		}

		private IEnumerator BerserkState()
		{
			((PlayerAdventureActor)_actor).status = ActorStatus.Special;
			((PlayerAdventureActor)_actor).specialStatusTime = _actor.buffComponent.GetBuffNumByID(_buffId_BerserkTiming);
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			_actor.buffComponent?.AddBuff(12594001, _actor);
			OnEnterBerserk();
			while (((PlayerAdventureActor)_actor).specialStatusTime > 0)
			{
				if (!_actor.logicVariable.GetLogicTagToggle("LockBerserkDuration"))
				{
					if (_reduceTimingBuffInterval > 0)
					{
						_reduceTimingBuffInterval -= _actor.LogicDeltaTime;
					}
					else
					{
						_actor.buffComponent?.RemoveBuffByBuffId(_buffId_BerserkTiming, 1);
						((PlayerAdventureActor)_actor).specialStatusTime = _actor.buffComponent.GetBuffNumByID(_buffId_BerserkTiming);
						_reduceTimingBuffInterval = Config.interval_ReduceTimingBuffCount;
					}
				}
				yield return null;
			}
			_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			_actor.buffComponent?.RemoveBuffByBuffId(12594001);
			OnExitBerserk();
			((PlayerAdventureActor)_actor).status = ActorStatus.Default;
			((PlayerAdventureActor)_actor).specialStatusTime = 0;
			while (!ILRuntimeAPI.CreateSkill(12500002, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: false, isBreakable: false, SkillCountdownTiming.Start, OnExitBerserkSkillFinish))
			{
				yield return null;
			}
			_berserkCor = null;
		}

		protected void AddBerserkTime(int timingBuffCount)
		{
			if (InBerserkState && _berserkCor != null)
			{
				for (int i = 0; i < timingBuffCount; i++)
				{
					_actor.buffComponent?.AddBuff(_buffId_BerserkTiming, _actor);
				}
			}
		}

		public virtual void OnUpdate()
		{
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Normal))
			{
				_delayNormalAttackStageDelay = Config.delay_ResetNormalAttackStage;
			}
			else if (_delayNormalAttackStageDelay > 0)
			{
				_delayNormalAttackStageDelay -= _actor.LogicDeltaTime;
			}
			else
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		protected virtual void OnExitBerserkSkillFinish(bool success)
		{
		}

		protected void ForceExitBerserkState()
		{
			(_actor as PlayerAdventureActor).status = ActorStatus.Default;
			(_actor as PlayerAdventureActor).specialStatusTime = 0;
			if (_berserkCor != null)
			{
				_actor.StopLogicCoroutine(_berserkCor);
			}
			_berserkCor = null;
		}

		protected virtual void OnEnterBerserk()
		{
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 4))
			{
				_actor.buffComponent.AddBuff(12596411, _actor);
			}
		}

		protected virtual void OnExitBerserk()
		{
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512541, out var _))
			{
				_actor.buffComponent?.RemoveBuffByBuffId(12541011);
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 4))
			{
				_actor.buffComponent.RemoveBuffByBuffId(12596411);
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			if (_berserkCor != null)
			{
				_actor.StopLogicCoroutine(_berserkCor);
			}
			_berserkCor = null;
		}
	}
	public class ParallelScript : ParallelBase
	{
		protected List<int> _damageTag_TriggerWaterCorrosion;

		public override void OnEnable()
		{
			base.OnEnable();
			if (_damageTag_TriggerWaterCorrosion == null)
			{
				_damageTag_TriggerWaterCorrosion = new List<int>();
			}
			else
			{
				_damageTag_TriggerWaterCorrosion.Clear();
			}
			_damageTag_TriggerWaterCorrosion.Add(Config.damageTag_TriggerWaterCorrosion);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnReceiveAttack(IEvent evt)
		{
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			if (adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor)
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512541, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveAttackEvent.hitDamageTag, Config.damageTag_Trigger_P41))
				{
					_actor.buffComponent?.AddBuff(12541011, _actor);
				}
				OnSelfAttacked(adventureActorReceiveAttackEvent);
			}
		}

		protected virtual void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (!(adventureActorReceiveDamageBeforeHitEvent.from == _actor) || !(adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor monsterAdventureActor))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512541, out var perkLevel) && (_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(12541011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(12541001, _actor, buffNumByID);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512543, out perkLevel) && (monsterAdventureActor.IsBossMonster() || monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE) && (monsterAdventureActor.CheckTag(Config.tag_Cold) || monsterAdventureActor.isFrozen) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_TriggerB_P43))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 12543011);
				if (TSRandom.Range(0f, 100f) <= scriptValue)
				{
					AdventureActor.AddFromAttr(12543001, _actor);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 5) && (monsterAdventureActor.IsBossMonster() || monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE))
			{
				AdventureActor.AddFromAttr(12596511, _actor);
			}
			OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor monsterAdventureActor)
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512543, out var _))
				{
					if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_TriggerA_P43))
					{
						monsterAdventureActor.buffComponent?.AddBuff(4100, _actor);
					}
					if (_actor.buffComponent.CheckBuffByBuffID(12543011) && monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.NORMAL && monsterAdventureActor.isFrozen && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_TriggerB_P43))
					{
						FP scriptValue = CommonUtils.GetScriptValue(_actor, 12543011);
						if (TSRandom.Range(0f, 100f) <= scriptValue)
						{
							monsterAdventureActor.buffComponent?.RemoveBuffByTag(Config.buffTag_Frozen);
							monsterAdventureActor.Kill(_actor);
						}
					}
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 1) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_D1))
				{
					monsterAdventureActor.buffComponent.AddBuff(12596111, _actor);
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 2) && (monsterAdventureActor.CheckTag(Config.tag_Cold) || monsterAdventureActor.isFrozen))
				{
					_actor.buffComponent.AddBuff(12596211, _actor);
				}
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 3) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_D3))
				{
					monsterAdventureActor.buffComponent.AddBuff(12596311, _actor);
				}
				OnSelfDamaged(adventureActorReceiveDamageEvent);
				if (CheckCanTriggerWaterCorrosion(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag))
				{
					TriggerWaterCorrosion(monsterAdventureActor);
				}
			}
			else if (adventureActorReceiveDamageEvent.to == _actor)
			{
				OnSelfReceiveDamage(adventureActorReceiveDamageEvent);
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		protected virtual void OnSelfReceiveDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerWaterCorrosion(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (_damageTag_TriggerWaterCorrosion == null || _damageTag_TriggerWaterCorrosion.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Water, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				for (int i = 0; i < _damageTag_TriggerWaterCorrosion.Count; i++)
				{
					int hitTag = _damageTag_TriggerWaterCorrosion[i];
					if (CommonUtils.CheckHitByTag(hitDamageTag, hitTag))
					{
						return true;
					}
				}
			}
			return false;
		}

		private void TriggerWaterCorrosion(MonsterAdventureActor monster)
		{
			if (!(monster == null))
			{
				monster.buffComponent?.RemoveBuffByTag(CommonDefine.Water);
				monster.buffComponent?.AddBuff(4021, _actor);
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_125_WaterTag1_Boom", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				if (monster.buffComponent.GetBuffNum(0, 0, Config.buffTag_Cold) >= 3)
				{
					monster.buffComponent.RemoveBuffByTag(Config.buffTag_Cold);
					monster.buffComponent.AddBuff(4100, _actor);
				}
				OnTriggerWaterCorrosion();
				CommonUtils.TriggerElementMarkEvent(CommonDefine.Water, GameEnum.AdventureActorElementTriggerType.WaterElementTriggerType1, _actor, monster, "WaterMark_Trigger_Effect_05");
			}
		}

		protected virtual void OnTriggerWaterCorrosion()
		{
		}

		private void Clear()
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_ATTACK", OnReceiveAttack);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			Clear();
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		public void OnStart()
		{
			ComboInputBuffer.ActionKey[] array = Config.comboKeys_Normal;
			FP duration = Config.duration_Normal;
			FP distance = Config.distance_Normal;
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if ((_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				if (_actor.attackTarget != null)
				{
					TSVector2 normalized = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
					FP fP = TSVector2.Angle(normalized, tSVector);
					FP fP2 = _actor.DistanceWithRadius(_actor.attackTarget);
					if (fP < Config.angle_CanUseAttackDodge * 0.5f && fP2 > Config.minDistance_CanUseAttackDodge && fP2 < Config.maxDistance_CanUseAttackDodge)
					{
						tSVector = normalized;
						_actor.LookAt(tSVector, 0);
						array = Config.comboKeys_Berserk_Attack;
						duration = Config.duration_Berserk_Attack;
						distance = ((fP2 <= Config.maxDistance_Berserk_Attack) ? fP2 : Config.maxDistance_Berserk_Attack);
					}
					else
					{
						array = Config.comboKeys_Berserk_Slide;
						duration = Config.duration_Berserk_Slide;
						distance = Config.distance_Berserk_Slide;
					}
				}
				else
				{
					array = Config.comboKeys_Berserk_Slide;
					duration = Config.duration_Berserk_Slide;
					distance = Config.distance_Berserk_Slide;
				}
			}
			ComboInputBuffer.ActionKey[] keys = array;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(keys, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, duration, distance, null, comboWithAttack: true);
		}

		protected void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() && Config.transitionRushSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(Config.transitionRushSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
				OnFinish();
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_ExitBerserk : SkillAdvancedBase
