	public class ActionScript_MainControl : ActionScript
	{
		private int _triggerTimes_P11;

		private FP _lastTriggerTime_P13;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512513, out var _))
			{
				_playerSkillCd.BindSkillIdToButton(ActionKey.A, 12520002);
			}
			if (((PlayerAdventureActor)_actor).status == ActorStatus.Special)
			{
				FP specialStatusTime = ((PlayerAdventureActor)_actor).specialStatusTime;
				if (specialStatusTime > 0)
				{
					_actor.ReplaceAnimationGroup();
					EnterBerserk((int)(long)specialStatusTime);
				}
				else
				{
					((PlayerAdventureActor)_actor).status = ActorStatus.Default;
				}
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ELEMENT_MARK_TRIGGER", OnTriggerElementMark);
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		protected override void OnButtonBPress()
		{
			_actor.logicVariable.ToggleLogicTag("OnButtonBPress", value: true);
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.End))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable.ToggleLogicTag("OnButtonBPress", value: false);
		}

		protected override void OnButtonDPress()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				_actor.logicVariable.SetLogicTagValue("NormalAttackStage", 0);
			}
		}

		public override void OnUpdate()
		{
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget != null && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
			base.OnUpdate();
		}

		protected override void OnEnterBerserk()
		{
			base.OnEnterBerserk();
			_triggerTimes_P11 = 0;
		}

		private void OnTriggerElementMark(IEvent evt)
		{
			if (!(evt is AdventureElementMarkTriggerEvent adventureElementMarkTriggerEvent) || !(adventureElementMarkTriggerEvent.triggerActor == _actor))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512511, out var perkLevel) && _triggerTimes_P11 < CommonUtils.GetScriptValue(_actor, 12511002) && base.InBerserkState)
			{
				int timingBuffCount = CommonUtils.GetScriptValue(_actor, 12511001).AsInt();
				AddBerserkTime(timingBuffCount);
				_triggerTimes_P11++;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512513, out perkLevel))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 12513012);
				if (_lastTriggerTime_P13 <= 0 || _actor.LogicTime - _lastTriggerTime_P13 > scriptValue)
				{
					_playerSkillCd.AddEnergy(CommonUtils.GetScriptValue(_actor, 12513001));
					_lastTriggerTime_P13 = _actor.LogicTime;
				}
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ELEMENT_MARK_TRIGGER", OnTriggerElementMark);
			_triggerTimes_P11 = 0;
			_lastTriggerTime_P13 = 0;
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private FP _lastResetSkillTime_P8;

		public override void OnEnable()
		{
			base.OnEnable();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512512, out var _))
			{
				_damageTag_TriggerWaterCorrosion?.Add(Config_MainControl.damageTag_TriggerWaterCorrosion_P12);
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512506, out var perkLevel))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(12506011);
				if (buffNumByID > 0)
				{
					if (CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_A_P6))
					{
						AdventureActor.AddFromAttr(12506001, _actor, buffNumByID);
					}
					if (CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_B_P6))
					{
						AdventureActor.AddFromAttr(12506002, _actor, buffNumByID);
					}
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512508, out perkLevel) && (monsterAdventureActor.IsBossMonster() || monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.ELITE) && (monsterAdventureActor.CheckTag(Config.tag_Cold) || monsterAdventureActor.isFrozen) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P8))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 12508011);
				if (TSRandom.Range(0f, 100f) <= scriptValue)
				{
					AdventureActor.AddFromAttr(12508001, _actor);
				}
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512508, out var _) && monsterAdventureActor.monsterInfo.epicType == GameEnum.monsterEpicType.NORMAL && monsterAdventureActor.isFrozen && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P8))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 12508011);
				if (TSRandom.Range(0f, 100f) <= scriptValue)
				{
					monsterAdventureActor.buffComponent?.RemoveBuffByTag(Config.buffTag_Frozen);
					monsterAdventureActor.Kill(_actor);
				}
			}
		}

		protected override void OnTriggerWaterCorrosion()
		{
			base.OnTriggerWaterCorrosion();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512512, out var _))
			{
				_actor.buffComponent.AddBuff(12512011, _actor);
			}
		}

		private void Clear()
		{
			_lastResetSkillTime_P8 = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			Clear();
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private bool _havePerk_P1;

		private bool _havePerk_P2;

		private bool _havePerk_P3;

		private bool _havePerk_P4;

		private bool _canCharge;

		private string _comboTag_Attack;

		private int _minLoopTimes_Attack;

		private int _chargeAddLoopTimes;

		private int _maxLoopTimes_Attack;

		private bool _isRunLoop;

		private bool _inCharge;

		private Dictionary<int, PlayFX> _chargeFxDic;

		private int _chargeStage;

		private FP _chargeInterval;

		private AimTarget _aimTarget;

		private int _attackLoopTimes;

		private int _curAttackLoopTimes;

		private FP _reduceCD_P2;

		private HashSet<int> _hittedSet_P4;

		private CoroutineNode _perkLogicCor_P10;

		private int _additionalAttrCount_P10;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_havePerk_P1 = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512501, out var perkLevel);
			_havePerk_P2 = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512502, out perkLevel);
			_havePerk_P3 = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512503, out perkLevel);
			_havePerk_P4 = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512504, out perkLevel);
			_canCharge = !_havePerk_P2;
			_comboTag_Attack = "125_Main_Skill_WhirlWind";
			if (_havePerk_P2)
			{
				_comboTag_Attack = (_havePerk_P4 ? "125_Main_Skill_P02P04_WhirlWind" : "125_Main_Skill_P02_WhirlWind");
			}
			else if (_havePerk_P4)
			{
				_comboTag_Attack = (_havePerk_P2 ? "125_Main_Skill_P02P04_WhirlWind" : "125_Main_Skill_P04_WhirlWind");
			}
			_minLoopTimes_Attack = (_havePerk_P3 ? 4 : 2);
			_chargeAddLoopTimes = (_havePerk_P3 ? 4 : 2);
			_maxLoopTimes_Attack = (_havePerk_P3 ? 12 : 6);
			_inCharge = false;
			_attackLoopTimes = _minLoopTimes_Attack;
			_curAttackLoopTimes = 0;
			_chargeInterval = Config_MainControl.chargeInterval_Skill;
			if (_havePerk_P4)
			{
				_actor.EnableImmuneControl();
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512506, out perkLevel))
			{
				_actor.buffComponent?.AddBuff(12506011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512507, out perkLevel) && (_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				_actor.buffComponent.AddBuff(12507011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512542, out perkLevel) && (_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				_actor.buffComponent.AddBuff(12542011, _actor);
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
		}

		public void OnStart()
		{
			if (_canCharge)
			{
				System.Action onActivationEnd = OnChargeActivationEnd;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack("125_Main_Charge_Start", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			}
			else
			{
				Attack();
			}
		}

		private void OnChargeActivationEnd()
		{
			if (_actor.logicVariable.GetLogicTagToggle("OnButtonBPress"))
			{
				_inCharge = true;
				_chargeStage = 1;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack("125_Main_Charge_Idle_Loop", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
				_isRunLoop = false;
				FP fP = 0;
				if (_chargeAddLoopTimes > 0)
				{
					fP = (_maxLoopTimes_Attack - _minLoopTimes_Attack) / _chargeAddLoopTimes * Config_MainControl.chargeInterval_Skill;
				}
				if (fP > 0)
				{
					MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintStart", _skill.skillId, fP.AsFloat());
				}
			}
			else
			{
				Attack();
			}
		}

		public void OnUpdate()
		{
			if (!_inCharge)
			{
				return;
			}
			if (_actor.logicVariable.GetLogicTagToggle("OnButtonBPress"))
			{
				bool flag = SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput();
				if (_isRunLoop != flag)
				{
					_isRunLoop = flag;
					string actionTag = (flag ? "125_Main_Charge_Run_Loop" : "125_Main_Charge_Idle_Loop");
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
				}
				if (_chargeInterval > 0)
				{
					_chargeInterval -= _actor.LogicDeltaTime;
					return;
				}
				_attackLoopTimes += _chargeAddLoopTimes;
				_attackLoopTimes = ((_attackLoopTimes > _maxLoopTimes_Attack) ? _maxLoopTimes_Attack : _attackLoopTimes);
				_actor.buffComponent?.AddBuff(12593001, _actor);
				PlayChargeFx();
				_chargeInterval = Config_MainControl.chargeInterval_Skill;
				_chargeStage++;
			}
			else
			{
				ChargeFinish();
			}
		}

		private void PlayChargeFx()
		{
			if (_chargeStage > 0 && Config_MainControl.chargeFxKeyDic_Skill.TryGetValue(_chargeStage, out var value) && !string.IsNullOrEmpty(value))
			{
				if (_chargeFxDic == null)
				{
					_chargeFxDic = new Dictionary<int, PlayFX>();
				}
				if (!_chargeFxDic.ContainsKey(_chargeStage))
				{
					_chargeFxDic.Add(_chargeStage, new PlayFX());
				}
				PlayFX playFX = _chargeFxDic[_chargeStage];
				playFX.Stop(dontPlaySubFX: true);
				playFX.Clear();
				playFX.Play(_actor, _skill, value, 0, _actor.tsTransform.Position, TSVector2.zero);
			}
		}

		private void ChargeFinish()
		{
			_inCharge = false;
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _skill.skillId);
			_actor.buffComponent?.RemoveBuffByBuffId(12593001);
			Attack();
		}

		private void Attack()
		{
			StopChargeFx();
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
			string comboTag_Attack = _comboTag_Attack;
			System.Action onAnticipationEnd = OnAttackAnticipationEnd;
			System.Action onComboLoop = OnAttackLoop;
			System.Action onRecoveryBegin = OnAttackRecoveryBegin;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboTag_Attack, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, onCustomEvent, null, fadeOutAnim: false, onComboLoop);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512510, out var _))
			{
				if (_perkLogicCor_P10 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P10);
				}
				_perkLogicCor_P10 = _actor.StartLogicCoroutine(PerkLogic_P10(), runImmediately: true);
			}
		}

		private void StopChargeFx(bool stopSubFx = false)
		{
			if (_chargeFxDic == null || _chargeFxDic.Count <= 0)
			{
				return;
			}
			foreach (PlayFX value in _chargeFxDic.Values)
			{
				value?.Stop(stopSubFx);
				value?.Clear();
			}
		}

		private IEnumerator PerkLogic_P10()
		{
			_actor.logicVariable.ToggleLogicTag("LockBerserkDuration", value: true);
			_additionalAttrCount_P10 = 0;
			FP checkInterval = Config_MainControl.increaseInterval_P10;
			while (true)
			{
				if (checkInterval > 0)
				{
					checkInterval -= _actor.LogicDeltaTime;
				}
				else
				{
					_additionalAttrCount_P10++;
					checkInterval = Config_MainControl.increaseInterval_P10;
				}
				yield return null;
			}
		}

		private void OnAttackAnticipationEnd()
		{
			FP fP = _attackLoopTimes * Config_MainControl.singleLoopTime_Skill_Attack;
			if (fP > 0)
			{
				MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintStart", _skill.skillId, fP.AsFloat(), a3: true);
			}
		}

		private void OnAttackLoop()
		{
			_curAttackLoopTimes++;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512509, out var _))
			{
				string text = (_havePerk_P4 ? "AreaEffect_125_Main_P04P09_Axe" : "AreaEffect_125_Main_P09_Axe");
				if (_curAttackLoopTimes % 2 == 0)
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, text, _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
			}
			if (_curAttackLoopTimes >= _attackLoopTimes)
			{
				base.comboAttack?.CancelAttack();
			}
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "Add_IceFog") && _havePerk_P1)
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_125_B2P22_IceFog", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		private void OnAttackRecoveryBegin()
		{
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _skill.skillId);
			_aimTarget?.Cancel();
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (!(adventureActorReceiveDamageBeforeHitEvent.from == _actor) || !(adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor))
			{
				return;
			}
			if (_havePerk_P3 && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config_MainControl.damageTag_P3))
			{
				AdventureActor.AddFromAttr(12503011, _actor);
			}
			if (_havePerk_P4 && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config_MainControl.damageTag_P4))
			{
				int num = ((_hittedSet_P4 != null) ? _hittedSet_P4.Count : 0);
				int num2 = CommonUtils.GetScriptValue(_actor, 12504011).AsInt();
				num = ((num < num2) ? num : num2);
				if (num > 0)
				{
					AdventureActor.AddFromAttr(12504011, _actor, num);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512510, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config_MainControl.damageTag_P10))
			{
				int num3 = CommonUtils.GetScriptValue(_actor, 12510011).AsInt();
				int num4 = ((_additionalAttrCount_P10 < num3) ? _additionalAttrCount_P10 : num3);
				if (num4 > 0)
				{
					AdventureActor.AddFromAttr(12510001, _actor, num4);
				}
			}
		}

		protected override void OnReceiveAttack(IEvent evt)
		{
			base.OnReceiveAttack(evt);
			AdventureActorReceiveAttackEvent adventureActorReceiveAttackEvent = evt as AdventureActorReceiveAttackEvent;
			if (adventureActorReceiveAttackEvent.from == _actor && adventureActorReceiveAttackEvent.to is MonsterAdventureActor && _havePerk_P2 && CommonUtils.CheckHitByTag(adventureActorReceiveAttackEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P2))
			{
				_reduceCD_P2 += Config_MainControl.reduceCd_P2;
				_reduceCD_P2 = ((_reduceCD_P2 > Config_MainControl.maxReduceCd_P2) ? Config_MainControl.maxReduceCd_P2 : _reduceCD_P2);
			}
		}

		protected override void OnReceiveDamage(IEvent evt)
		{
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor && _havePerk_P4 && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P4))
			{
				if (_hittedSet_P4 == null)
				{
					_hittedSet_P4 = new HashSet<int>();
				}
				_hittedSet_P4.Add(adventureActorReceiveDamageEvent.uniqueAttackId);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		private void Clear()
		{
			_isRunLoop = false;
			_havePerk_P1 = false;
			_havePerk_P2 = false;
			_havePerk_P3 = false;
			_havePerk_P4 = false;
			_curAttackLoopTimes = 0;
			_reduceCD_P2 = 0;
			_hittedSet_P4?.Clear();
			if (_perkLogicCor_P10 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P10);
			}
			_perkLogicCor_P10 = null;
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			StopChargeFx();
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			if (_havePerk_P2 && _reduceCD_P2 > 0)
			{
				(_actor as PlayerAdventureActor).playerSkillCd.ModifyResumeTimeAbs(-_reduceCD_P2, ActionKey.B);
			}
			if (_havePerk_P4)
			{
				_actor.DisableImmuneControl();
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512505, out var _))
			{
				_actor.buffComponent.AddBuff(12505001, _actor);
			}
			_actor.buffComponent?.RemoveBuffByBuffId(12593001);
			_actor.logicVariable.ToggleLogicTag("LockBerserkDuration", value: false);
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _skill.skillId);
			Clear();
		}
	}
	public class ActionScript_Support : ActionScript
	{
		private TraceTarget _traceTarget;

		private FP _checkTraceInterval;

		private bool _forceTrace;

		private CoroutineNode _perkLoigcCor_P29;

		public override void OnStart()
		{
			base.OnStart();
			_forceTrace = false;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512529, out var _))
			{
				if (_perkLoigcCor_P29 != null)
				{
					_actor.StopLogicCoroutine(_perkLoigcCor_P29);
				}
				_perkLoigcCor_P29 = _actor.StartLogicCoroutine(PerkLogic_P29());
			}
		}

		private IEnumerator PerkLogic_P29()
		{
			FP interval = Config_Support.addBuffInterval_P29;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					_actor.buffComponent?.AddBuff(12529011, _actor);
					interval = Config_Support.addBuffInterval_P29;
				}
				yield return null;
			}
		}

		protected override void OnCastSkill()
		{
			if (!ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.End, OnSkillFinish))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512523, out var perkLevel))
			{
				_actor.buffComponent?.AddBuff(12523011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512530, out perkLevel) && base.InBerserkState)
			{
				int timingBuffCount = CommonUtils.GetScriptValue(_actor, 12530011).AsInt();
				AddBerserkTime(timingBuffCount);
				_actor.buffComponent?.AddBuff(12530011, _actor);
			}
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512533, out perkLevel))
			{
				return;
			}
			FP scriptValue = CommonUtils.GetScriptValue(_actor, 12533001);
			if (!(TSRandom.Range(0f, 100f) <= scriptValue))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.AddBuff(12533011, _actor);
			}
		}

		protected override void OnCastUltimate()
		{
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnUltraSkillFinish))
			{
				((PlayerAdventureActor)_actor).isResidentAssist = true;
				_actor.attackTarget = GetAttackTarget(activeActorTargetFirst: true);
			}
		}

		private void OnSkillFinish(bool _)
		{
			((PlayerAdventureActor)_actor).isAssistAIFinish = true;
		}

		private void OnUltraSkillFinish(bool success)
		{
			((PlayerAdventureActor)_actor).isAssistAIFinish = true;
			if (base.InBerserkState)
			{
				((PlayerAdventureActor)_actor).isResidentAssist = true;
			}
		}

		protected override void OnExitBerserkSkillFinish(bool success)
		{
			base.OnExitBerserkSkillFinish(success);
			if (success)
			{
				((PlayerAdventureActor)_actor).isResidentAssist = false;
			}
		}

		public override void OnUpdate()
		{
			if (base.InBerserkState)
			{
				_actor.attackTarget = GetAttackTarget();
				if (_checkTraceInterval > 0)
				{
					_checkTraceInterval -= _actor.LogicDeltaTime;
				}
				else if (CheckTrace())
				{
					_checkTraceInterval = Config_Support.interval_CheckTrace;
				}
				if (CanNormalAttack() && ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
				{
					_traceTarget?.CancelTrace();
				}
				base.OnUpdate();
			}
			else
			{
				base.OnUpdate();
			}
		}

		private LogicEntity GetAttackTarget(bool activeActorTargetFirst = false)
		{
			if (_forceTrace)
			{
				return null;
			}
			return CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst);
		}

		private bool CanNormalAttack()
		{
			if (_forceTrace)
			{
				return false;
			}
			if (_actor.attackTarget == null)
			{
				return false;
			}
			return _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor);
		}

		private bool CheckTrace()
		{
			if (_forceTrace)
			{
				return false;
			}
			if (_traceTarget == null)
			{
				_traceTarget = new TraceTarget();
			}
			if (_actor.actorSkillManage.HaveRunningSkill())
			{
				_traceTarget.CancelTrace();
				return false;
			}
			(LogicEntity target, FP stopDistance, bool forceTrace) traceInfo = GetTraceInfo();
			LogicEntity item = traceInfo.target;
			FP item2 = traceInfo.stopDistance;
			bool item3 = traceInfo.forceTrace;
			_forceTrace = item3;
			if (item != null)
			{
				_traceTarget.BeginTrace(_actor, item, item2, -1, -1, null, null, NavAgentTypeNames.NavigationUpdateQualityLevel.MedQualityNavigationUpdate, AdventureActor.MovementMode.Run, OnTraceFinish);
				return true;
			}
			return false;
		}

		private (LogicEntity target, FP stopDistance, bool forceTrace) GetTraceInfo()
		{
			FP fP = _actor.DistanceWithRadius(SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor);
			if (fP > Config_Support.distance_ForceTrace)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config_Support.distance_StopTrace_ForPlayer, forceTrace: true);
			}
			if (_actor.attackTarget != null)
			{
				if (_actor.DistanceWithRadius(_actor.attackTarget) > CommonUtils.GetAttackRange(_actor))
				{
					return (target: _actor.attackTarget, stopDistance: CommonUtils.GetAttackRange(_actor), forceTrace: false);
				}
			}
			else if (fP > Config_Support.distance_StopTrace_ForPlayer)
			{
				return (target: SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor, stopDistance: Config_Support.distance_StopTrace_ForPlayer, forceTrace: false);
			}
			return (target: null, stopDistance: 0, forceTrace: false);
		}

		private void OnTraceFinish()
		{
			_forceTrace = false;
		}

		protected override void OnExitBerserk()
		{
			base.OnExitBerserk();
			_traceTarget?.CancelTrace();
			_traceTarget?.Clear();
		}

		public override void OnStop()
		{
			base.OnStop();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512529, out var _))
			{
				_actor.buffComponent.RemoveBuffByBuffId(12529011);
			}
			Clear();
		}

		private void Clear()
		{
			if (_perkLoigcCor_P29 != null)
			{
				_actor.StopLogicCoroutine(_perkLoigcCor_P29);
			}
			_perkLoigcCor_P29 = null;
			_traceTarget?.CancelTrace();
			_traceTarget?.Clear();
			_checkTraceInterval = 0;
			_forceTrace = false;
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			ForceExitBerserkState();
			((PlayerAdventureActor)_actor).isResidentAssist = false;
		}
	}
	public class IceFlower
	{
		private AdventureActor _actor;

		private PlayFX _playFX;

		private CommomAreaHitConfig _areaHitConfig;

		private CoroutineNode _explosionCor;

		private string _fxKey;

		private int _hitDamageId_Blossom;

		private int _hitDamageId_Explosion;

		private FP _hitRadius_Blossom;

		private FP _hitRadius_Explosion;

		public bool IsRunning { get; private set; }

		public TSVector2 Position => _areaHitConfig.position;

		public IceFlower(AdventureActor actor)
		{
			_actor = actor;
			_areaHitConfig = new CommomAreaHitConfig
			{
				damageImmuneDuration = -1,
				hitFlags = (HitBox.FeatureFlag.Stiff | HitBox.FeatureFlag.AddBuffForTarget),
				hitFeatureData = Config_Support.hitBoxFeatureData_IceFlower,
				hittedEffectAlias = "fx_12501_hit_Ice"
			};
		}

		public void Blossom(TSVector2 position, int blossomHitDamageId, int explosionHitDamageId, int delayExplosionFrame = 0, int blossomUniqueAttackId = 0, int explosionUniqueAttackId = 0)
		{
			IsRunning = true;
			_fxKey = "fx_12501_loop_B1_Skill_IceFlower";
			_hitDamageId_Blossom = blossomHitDamageId;
			_hitDamageId_Explosion = explosionHitDamageId;
			_hitRadius_Blossom = Config_Support.hitRaidus_IceFlower_Blossom;
			_hitRadius_Explosion = Config_Support.hitRaidus_IceFlower_Explosion;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512521, out var _))
			{
				_fxKey = "fx_12501_loop_B1_Skill_IceFlower_Rage";
				_hitRadius_Blossom = Config_Support.hitRaidus_IceFlower_Blossom_P21;
				_hitRadius_Explosion = Config_Support.hitRaidus_IceFlower_Explosion_P21;
			}
			_areaHitConfig.position = position;
			blossomUniqueAttackId = ((blossomUniqueAttackId > 0) ? blossomUniqueAttackId : SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId());
			explosionUniqueAttackId = ((explosionUniqueAttackId > 0) ? explosionUniqueAttackId : SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId());
			if (_playFX == null)
			{
				_playFX = new PlayFX();
			}
			else
			{
				_playFX.Clear();
			}
			_playFX.Play(_actor, null, _fxKey, default(FP), position, default(TSVector2));
			CircleAreaHit(_hitDamageId_Blossom, blossomUniqueAttackId, _hitRadius_Blossom);
			if (_explosionCor != null)
			{
				_actor.StopLogicCoroutine(_explosionCor);
			}
			_explosionCor = _actor.StartLogicCoroutine(ExplosionLogic(delayExplosionFrame, explosionUniqueAttackId));
		}

		private IEnumerator ExplosionLogic(int delayExplosionFrame, int uniqueAttackId)
		{
			if (delayExplosionFrame > 0)
			{
				yield return delayExplosionFrame;
			}
			int leftFrame = 30;
			int delayHitFrame = 4;
			_playFX?.Stop();
			bool hitted = false;
			while (leftFrame > 0)
			{
				if (delayHitFrame > 0)
				{
					delayHitFrame--;
				}
				else if (!hitted)
				{
					CircleAreaHit(_hitDamageId_Explosion, uniqueAttackId, _hitRadius_Explosion);
					hitted = true;
				}
				leftFrame--;
				yield return null;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512527, out var perkLevel))
			{
				string text = "AreaEffect_125_Main_P27_IceFlower";
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512521, out perkLevel))
				{
					text = "AreaEffect_125_Main_P27P21_IceFlower_Large";
				}
				ILRuntimeAPI.PlayAreaEffect(_actor, text, _areaHitConfig.position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			IsRunning = false;
		}

		public void Clear()
		{
			IsRunning = false;
			_playFX?.Stop(dontPlaySubFX: true);
			_playFX?.Clear();
			if (_explosionCor != null)
			{
				_actor.StopLogicCoroutine(_explosionCor);
			}
			_explosionCor = null;
		}

		private void CircleAreaHit(int hitDamageId, int uniqueAttackId, FP radius)
		{
			_areaHitConfig.hitDamageId = hitDamageId;
			_areaHitConfig.uniqueAttackId = ((uniqueAttackId > 0) ? uniqueAttackId : (-1));
			ILRuntimeAPI.CircleAreaHit(_actor, _areaHitConfig, radius, 0);
		}
	}
	public class ParallelScript_Support : ParallelScript
	{
		private List<IceFlower> _runningIceFlowerList;

		private FP _lastTriggerTime_P24;

		private FP _lastTriggerTime_P28;

		private Queue<IceFlower> _iceFlowerPool;

		public override void OnEnable()
		{
			base.OnEnable();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512531, out var _))
			{
				bool flag = true;
				for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
				{
					if (SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i].actorElementInfo.elementType != GameEnum.elementType.WE)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					for (int j = 0; j < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; j++)
					{
						SceneSingleton<AdventurePlayerController>.Instance.ActorLs[j].buffComponent?.AddBuff(12531011, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		public void OnUpdate()
		{
			if (_runningIceFlowerList == null || _runningIceFlowerList.Count <= 0)
			{
				return;
			}
			for (int num = _runningIceFlowerList.Count - 1; num >= 0; num--)
			{
				if (!_runningIceFlowerList[num].IsRunning)
				{
					RecycleIceFlower(_runningIceFlowerList[num]);
					_runningIceFlowerList.RemoveAt(num);
				}
			}
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			AdventureActorCustomEvent adventureActorCustomEvent = evt as AdventureActorCustomEvent;
			if (!(adventureActorCustomEvent.actor != _actor) && adventureActorCustomEvent.eventHashCode == Config_Support.eventHashCode_BeginGenIceFlower)
			{
				_actor.StartLogicCoroutine(SkillLogic(), runImmediately: true);
			}
		}

		private IEnumerator SkillLogic()
		{
			string fxAlias = "fx_12501_base_B1_Skill_IceFlower_Trail_Rage";
			int totalFlowerCount_OnceLine = 6;
			FP distance_BetweenTwoFlower = Config_Support.distance_BetweenTwoFlower;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512522, out var _))
			{
				fxAlias = "fx_12501_base_B1_Skill_IceFlower_Trail_Rage";
				totalFlowerCount_OnceLine = 8;
				distance_BetweenTwoFlower = Config_Support.distance_BetweenTwoFlower_P22;
			}
			TSVector2 startPosition = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_Support.offset_FirstIceFlower;
			List<TSVector2> iceFlowerLineDirList = new List<TSVector2>(4);
			TSVector2 forward = _actor.tsTransform.Forward;
			int num = 3;
			if (num > 1)
			{
				Config_Support.includedAngleDic_IceFlowerLine.TryGetValue(num, out var value);
				if (value <= 0)
				{
					NovaLogger.Error($"冰花夹角配置有误,条数:{num}");
				}
				FP fP = value * (num - 1) * 0.5f;
				for (int i = 0; i < num; i++)
				{
					iceFlowerLineDirList.Add(TSVector2.Rotate(forward, -fP + value * i).normalized);
				}
			}
			else
			{
				iceFlowerLineDirList.Add(forward);
			}
			for (int j = 0; j < iceFlowerLineDirList.Count; j++)
			{
				PlayFX playFX = new PlayFX();
				playFX.Play(_actor, null, fxAlias, default(FP), startPosition, iceFlowerLineDirList[j]);
				playFX.Clear();
			}
			int uniqueAttackId_Blossom = SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId();
			int uniqueAttackId_Explosion = SceneSingleton<AdventurePlayerController>.Instance.GetUniqueAttackId();
			int delayExplosionFrame = totalFlowerCount_OnceLine * 3 + 15;
			GenerateIceFlower(startPosition, 125320001, 125320002, delayExplosionFrame, uniqueAttackId_Blossom, uniqueAttackId_Explosion);
			for (int flowerIndex_Line = 1; flowerIndex_Line < totalFlowerCount_OnceLine; flowerIndex_Line++)
			{
				yield return 3;
				delayExplosionFrame -= 3;
				for (int k = 0; k < iceFlowerLineDirList.Count; k++)
				{
					TSVector2 position = startPosition + distance_BetweenTwoFlower * iceFlowerLineDirList[k] * flowerIndex_Line;
					GenerateIceFlower(position, 125320001, 125320002, delayExplosionFrame, uniqueAttackId_Blossom, uniqueAttackId_Explosion);
				}
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512523, out var perkLevel) && _actor.buffComponent.CheckBuffByBuffID(12523011) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P23) && TSRandom.Range(0f, 100f) <= Config_Support.triggerRate_P23)
			{
				_actor.StartLogicCoroutine(PerkLogic_P23(monsterAdventureActor));
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512524, out perkLevel) && (_lastTriggerTime_P24 <= 0 || _actor.LogicTime - _lastTriggerTime_P24 > Config_Support.triggerCD_P24) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P24) && (monsterAdventureActor.CheckTag(Config.tag_Cold) || monsterAdventureActor.isFrozen))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_125_Main_P24_IceAOE", monsterAdventureActor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				_lastTriggerTime_P24 = _actor.LogicTime;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512525, out perkLevel) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P25))
			{
				monsterAdventureActor.buffComponent?.AddBuff(12525001, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512528, out perkLevel) && (_lastTriggerTime_P28 <= 0 || _actor.LogicTime - _lastTriggerTime_P28 > Config_Support.triggerCD_P28) && (monsterAdventureActor.CheckTag(Config.tag_Cold) || monsterAdventureActor.isFrozen) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P28))
			{
				_actor.buffComponent?.AddBuff(12528011, _actor);
				_lastTriggerTime_P28 = _actor.LogicTime;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512532, out perkLevel) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, Config_Support.damageTag_Trigger_P32))
			{
				monsterAdventureActor.buffComponent?.AddBuff(4011, _actor);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512521, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_P21))
			{
				AdventureActor.AddFromAttr(12521011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512522, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_P22))
			{
				AdventureActor.AddFromAttr(12522011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512526, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_P26))
			{
				int buffNumByID = monsterAdventureActor.buffComponent.GetBuffNumByID(12526011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(12526001, _actor, buffNumByID);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512532, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_Support.damageTag_Trigger_P32))
			{
				AdventureActor.AddFromAttr(12532001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512526, out var _) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P26))
			{
				monsterAdventureActor.buffComponent?.AddBuff(12526011, _actor);
			}
		}

		private IEnumerator PerkLogic_P23(MonsterAdventureActor target)
		{
			FP delayTime = Config_Support.delayGenerateTime_IceFlower_P23;
			TSVector2 position = target.tsTransform.Position;
			long targetId = target.Id;
			while (delayTime > 0)
			{
				if (CommonUtils.CheckTargetIsValid(target, targetId))
				{
					position = target.tsTransform.Position;
				}
				delayTime -= _actor.LogicDeltaTime;
				yield return null;
			}
			GenerateIceFlower(position, 125322301, 125322302, 30);
		}

		private void GenerateIceFlower(TSVector2 position, int blossomHitDamageId, int explosionHitDamageId, int delayExplosionFrame = 0, int blossomUniqueAttackId = 0, int explosionUniqueAttackId = 0)
		{
			IceFlower iceFlower = GetIceFlower();
			iceFlower.Blossom(position, blossomHitDamageId, explosionHitDamageId, delayExplosionFrame, blossomUniqueAttackId, explosionUniqueAttackId);
			if (_runningIceFlowerList == null)
			{
				_runningIceFlowerList = new List<IceFlower>();
			}
			_runningIceFlowerList.Add(iceFlower);
		}

		private void Clear()
		{
			if (_runningIceFlowerList != null && _runningIceFlowerList.Count > 0)
			{
				for (int num = _runningIceFlowerList.Count - 1; num >= 0; num--)
				{
					RecycleIceFlower(_runningIceFlowerList[num]);
				}
				_runningIceFlowerList.Clear();
			}
			_lastTriggerTime_P24 = 0;
			_lastTriggerTime_P28 = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			Clear();
		}

		private IceFlower GetIceFlower()
		{
			if (_iceFlowerPool != null && _iceFlowerPool.Count > 0)
			{
				return _iceFlowerPool.Dequeue();
			}
			return new IceFlower(_actor);
		}

		private void RecycleIceFlower(IceFlower iceFlower)
		{
			if (iceFlower != null)
			{
				iceFlower.Clear();
				if (_iceFlowerPool == null)
				{
					_iceFlowerPool = new Queue<IceFlower>();
				}
				_iceFlowerPool.Enqueue(iceFlower);
			}
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 512542, out var _) && (_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				_actor.buffComponent.AddBuff(12542011, _actor);
			}
		}

		public void OnStart()
		{
			string actionTag = ((((PlayerAdventureActor)_actor).status == ActorStatus.Special) ? "B2_Skill_Rage" : "B2_Skill");
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = Interrupt;
			BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "Start_Hurt"))
			{
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = this;
				adventureActorCustomEvent.actor = _actor;
				adventureActorCustomEvent.eventHashCode = Config_Support.eventHashCode_BeginGenIceFlower;
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventureActorCustomEvent);
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void Interrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}
	}
