		public void OnUpdate()
		{
			lastTime_06 -= _actor.LogicDeltaTime;
			if (GetPerk(512006) && mainWeapCount > 0 && lastTime_06 < 0)
			{
				lastTime_06 = 0.25;
				ILRuntimeAPI.SearchByRange(_actor, dis_06, delegate(List<LogicEntity> monsters)
				{
					if (monsters != null && monsters.Count > 0)
					{
						for (int i = 0; i < monsters.Count; i++)
						{
							MonsterAdventureActor monsterAdventureActor = monsters[i] as MonsterAdventureActor;
							if (monsterAdventureActor != null)
							{
								monsterAdventureActor.buffComponent.AddBuff(12006012, _actor);
							}
						}
					}
				}, isConfront: true);
			}
			if (bigSupportWeapon != null)
			{
				int num = (bigSupWeaponRotateIndex + 1) * 360;
				if (FP.Abs(bigSupportWeapon.GetAngel()) > num)
				{
					bigSupWeaponRotateIndex++;
					if (GetPerk(512030))
					{
						SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor.buffComponent.AddBuff(12030011, _actor);
					}
					if (GetPerk(512024))
					{
						AdventureActor actor = _actor;
						TSVector2 position = SceneSingleton<AdventurePlayerController>.Instance.ActivedPlayerActor.tsTransform.Position;
						AdventureActor actor2 = _actor;
						ILRuntimeAPI.PlayAreaEffect(actor, "AreaEffect_12001_B2P24_Wreath", position, default(FP), (Action<AreaEffectEntity>)null, actor2);
					}
				}
			}
			if (delayBullets.Count <= 0)
			{
				return;
			}
			foreach (FP key in delayBullets.Keys)
			{
				if (key + delay_time < _actor.LogicTime)
				{
					if (!copy_buleltsID.Contains(delayBullets[key].Id))
					{
						int length = delayBullets[key].name.IndexOf('(');
						string bulletAlias = delayBullets[key].name.Substring(0, length);
						AdventureActor actor3 = _actor;
						FP range = 0;
						TSVector2 shootDir = delayBulletDir[key];
						TSVector2 position2 = delayBulletPos[key];
						FP positionY = 1.8;
						Action<LogicEntity> onInit = OnBulletInit;
						ILRuntimeAPI.ShootByDirection(bulletAlias, actor3, range, shootDir, position2, positionY, default(TSVector2), null, AimType.Default, null, onInit);
					}
					else
					{
						copy_buleltsID.Remove(delayBullets[key].Id);
					}
					delayBulletPos.Remove(key);
					delayBulletDir.Remove(key);
					delayBullets.Remove(key);
					break;
				}
			}
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		protected readonly FP _dodgeDuration = 0.4;

		protected readonly FP _dodgeDistance = 0.01;

		protected readonly ComboInputBuffer.ActionKey[] _actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };

		protected ComboAttack _comboAttack;

		protected Dodge _dodge;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			_dodge?.Interrupte();
			Parallel.dodgeSkill = false;
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				Parallel.dodgeSkill = true;
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				ComboInputBuffer.ActionKey[] actionKeys = _actionKeys;
				int skillId = _skill.skillId;
				System.Action onActivationEnd = OnActivationEnd;
				System.Action onRecoveryBegin = OnRecoveryBegin;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: true, autoLookAtTarget: true, null, null, default(TSVector2), null, onRecoveryBegin, null, onComboFinish, onInterrupt, null, onActivationEnd);
				if (_dodge == null)
				{
					_dodge = new Dodge();
				}
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					_actor.CancelAiming();
				}
				TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (tSVector == TSVector2.zero)
				{
					tSVector = _actor.tsTransform.Forward.normalized;
				}
				_dodge.Begin(_actor, tSVector, _dodgeDuration, _dodgeDistance, null, comboWithAttack: true);
			}
		}

