		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = evt as AdventureActorCastSkillEndEvent;
			if (!(_actor == null) && adventureActorCastSkillEndEvent.sender == _actor && adventureActorCastSkillEndEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.NORMAL)
