		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.DisableInvincible();
			_playTimeline.Clear();
			if (_areaEffectID > 0)
			{
				ILRuntimeAPI.StopAreaEffect(_areaEffectID);
			}
			_actor.buffComponent.RemoveBuffByBuffId(buffId_Base_1);
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_actor.EnableInvincible();
			_currentLoopCount = 0;
			_totalLoopCount = loopCount;
			_areaEffectID = 0L;
			_actor.buffComponent.AddBuff(buffId_Base_1, _actor);
		}

		public virtual void OnStart()
		{
			if (_skill != null)
			{
				if (_playTimeline == null)
				{
					_playTimeline = new PlayTimeline();
				}
				_playTimeline.Play(_actor, delegate
				{
					string actionTag = actionTag_withTimeline;
					System.Action onAnticipationEnd = OnAnticipationEnd;
					System.Action onRecoveryBegin = OnRecoverBegin;
					System.Action onComboLoop = OnComboLoop;
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
				}, delegate
				{
					string actionTag = actionTag_noTimeline;
					System.Action onAnticipationEnd = OnAnticipationEnd;
					System.Action onRecoveryBegin = OnRecoverBegin;
					System.Action onComboLoop = OnComboLoop;
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
				});
			}
		}

		private void OnAnticipationEnd()
		{
			string text = areaEffect_pull;
			_areaEffectID = ILRuntimeAPI.PlayAreaEffect(_actor, text, _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}

		private void OnRecoverBegin()
		{
			if (_areaEffectID > 0)
			{
				ILRuntimeAPI.StopAreaEffect(_areaEffectID);
				_areaEffectID = 0L;
			}
		}

		private void OnComboLoop()
		{
			_currentLoopCount++;
			if (_currentLoopCount >= _totalLoopCount)
			{
				base.comboAttack.CancelAttack();
			}
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}
	}
