	public class Parallel : AIBase
	{
		protected readonly int _certainBuffId = 11801;

		protected CoroutineNode _waitForPullEndCoroutine;

		protected readonly List<LogicEntity> targets = new List<LogicEntity>();

		protected readonly List<PlayFX> _fxs = new List<PlayFX>();

		public virtual void OnDisable()
		{
			if (_waitForPullEndCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForPullEndCoroutine);
				_waitForPullEndCoroutine = null;
			}
			targets.Clear();
			ClearBuffAndEffect();
		}

		public void OnUpdate()
		{
			if (_actor.logicVariable.GetLogicTagToggle("playEffect"))
			{
				_actor.logicVariable.ToggleLogicTag("playEffect", value: false);
				AddEffect();
			}
			if (_actor.logicVariable.GetLogicTagToggle("removeBuffAndEffect"))
			{
				_actor.logicVariable.ToggleLogicTag("removeBuffAndEffect", value: false);
				ClearBuffAndEffect();
			}
			if (_actor.logicVariable.GetLogicTagToggle("WaitForPullEnd"))
			{
				_actor.logicVariable.ToggleLogicTag("WaitForPullEnd", value: false);
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("PullDuration");
				if (_waitForPullEndCoroutine != null)
				{
					_actor.StopLogicCoroutine(_waitForPullEndCoroutine);
					_waitForPullEndCoroutine = null;
				}
				_waitForPullEndCoroutine = _actor.StartLogicCoroutine(WaitForPullEnd(logicTagValue));
			}
		}

		protected virtual IEnumerator WaitForPullEnd(FP duration)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(duration));
			ClearBuffAndEffect();
		}

		protected void ClearBuffAndEffect()
		{
			targets.Clear();
			for (int i = 0; i < ModuleController<AdventureModuleController>.Instance.monsterActors.Count; i++)
			{
				MonsterAdventureActor monsterAdventureActor = ModuleController<AdventureModuleController>.Instance.monsterActors[i] as MonsterAdventureActor;
				if (monsterAdventureActor.buffComponent.CheckBuffByBuffID(_certainBuffId))
				{
					monsterAdventureActor.GetComponent<AdventureActor>()?.buffComponent.RemoveBuffByBuffId(_certainBuffId);
					targets.Add(monsterAdventureActor);
				}
			}
			for (int j = 0; j < _fxs.Count; j++)
			{
				_fxs[j].Stop();
				_fxs[j].Clear();
			}
			_fxs.Clear();
		}

		protected void AddEffect()
		{
			for (int i = 0; i < ModuleController<AdventureModuleController>.Instance.monsterActors.Count; i++)
			{
				MonsterAdventureActor monsterAdventureActor = ModuleController<AdventureModuleController>.Instance.monsterActors[i] as MonsterAdventureActor;
				if (monsterAdventureActor.buffComponent.CheckBuffByBuffID(_certainBuffId))
				{
					PlayFX playFX = new PlayFX();
					playFX.Play(_actor, null, "fx_11801_loop_line_skill1_01", FP.Zero, TSVector2.zero, TSVector2.zero, null, 1f, 1f, actorScale: false, null, monsterAdventureActor.gameObject.transform);
					_fxs.Add(playFX);
				}
			}
		}
	}
	public class Parallel_Branch1 : Parallel
	{
		protected readonly int _certainBuffId1 = 11803;

		protected readonly int _dizzyBuffId = 11812;

		protected readonly int _pullCount = 3;

		protected FP _pullInterval = 3;

		protected FP _moveSpeed = 10;

		protected readonly int _moveLevel = 99;

		protected FP _strength = 4;

		protected CoroutineNode _pullCoroutine;

		protected int _currentPullCount;

		public override void OnDisable()
		{
			base.OnDisable();
			if (_pullCoroutine != null)
			{
				_actor.StopLogicCoroutine(_pullCoroutine);
				_pullCoroutine = null;
			}
			_currentPullCount = 0;
		}

		protected override IEnumerator WaitForPullEnd(FP duration)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(duration));
			ClearBuffAndEffect();
			if (_pullCoroutine != null)
			{
				_actor.StopLogicCoroutine(_pullCoroutine);
				_pullCoroutine = null;
				for (int i = 0; i < targets.Count; i++)
				{
					targets[i].GetComponent<AdventureActor>().buffComponent.RemoveBuffByBuffId(_certainBuffId1);
				}
			}
			for (int j = 0; j < targets.Count; j++)
			{
				targets[j].GetComponent<AdventureActor>().buffComponent.AddBuff(_certainBuffId1, _actor);
			}
			_currentPullCount = 0;
			_pullCoroutine = _actor.StartLogicCoroutine(Pull());
		}

		protected IEnumerator Pull()
		{
			List<LogicEntity> validTargets = new List<LogicEntity>();
			while (_currentPullCount < _pullCount)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_pullInterval));
				validTargets.Clear();
				for (int i = 0; i < targets.Count; i++)
				{
					if (targets[i].GetComponent<AdventureActor>().actorHealthInfo.isAlive)
					{
						validTargets.Add(targets[i]);
					}
				}
				if (validTargets.Count > 1)
				{
					_actor.SearchEntitySortByDistance(validTargets);
					List<AdventureActor> list = new List<AdventureActor>();
					List<FP> list2 = new List<FP>();
					AdventureActor component;
					if (validTargets.Count == 2)
					{
						component = validTargets[0].GetComponent<AdventureActor>();
						AdventureActor component2 = validTargets[1].GetComponent<AdventureActor>();
						list.Add(component2);
						FP item = ILRuntimeAPI.CalcDistanceBetweenTwoActor(component, component2);
						list2.Add(item);
					}
					else
					{
						int index = validTargets.Count / 2;
						component = validTargets[index].GetComponent<AdventureActor>();
						for (int j = 0; j < validTargets.Count; j++)
						{
							LogicEntity logicEntity = validTargets[j];
							if (!(logicEntity == component))
							{
								AdventureActor component3 = logicEntity.GetComponent<AdventureActor>();
								list.Add(component3);
								FP item2 = ILRuntimeAPI.CalcDistanceBetweenTwoActor(component, component3);
								list2.Add(item2);
							}
						}
					}
					ILRuntimeAPI.ForceMove(component, list, _moveSpeed, list2, isCoExist: true, isChangeForward: true, _moveLevel, _strength);
					foreach (LogicEntity item3 in validTargets)
					{
						item3.GetComponent<AdventureActor>()?.buffComponent?.AddBuff(_dizzyBuffId, _actor);
					}
				}
				_currentPullCount++;
			}
			for (int k = 0; k < targets.Count; k++)
			{
				validTargets[k].GetComponent<AdventureActor>().buffComponent.RemoveBuffByBuffId(_certainBuffId1);
			}
			_pullCoroutine = null;
		}
	}
