			{
				CommonUtils.TriggerElementMarkEvent(CommonDefine.LightMark1, GameEnum.AdventureActorElementTriggerType.LightElementTriggerType1, _actor, _monster, "LightMark_Trigger_Effect_02");
			}
		}

		public void OnUpdate()
		{
			dazhaoHitTime -= _actor.LogicDeltaTime;
			dazhaoDuration -= _actor.LogicDeltaTime;
			duration_p4_t -= _actor.LogicDeltaTime;
			hitInterval_p4_t -= _actor.LogicDeltaTime;
			hitInterval_p5_t -= _actor.LogicDeltaTime;
			if (dazhaoDuration > 0 && dazhaoHitTime <= 0)
			{
				dazhaoHitTime = hitPreD;
			}
			if (_actor.logicVariable.GetLogicTagToggle("117DazhaoKaishi"))
			{
				dazhaoHitTime = hitPreD;
				dazhaoDuration = hit_Duration;
				_actor.logicVariable.ToggleLogicTag("117DazhaoKaishi", value: false);
			}
			if (dazhaoHitTime >= hitPreD)
			{
				OnUltraSkillHit();
			}
			if (_actor.logicVariable.GetLogicTagToggle("117p4SkillTrigger"))
			{
				_actor.PlayFX("fx_11701_loop_perk9_Current");
				if (playFx == null)
				{
					playFx = new PlayFX();
				}
				else
				{
					playFx.Stop();
				}
				playFx.Play(_actor, null, "fx_11701_loop_perk9_Current", 0, _actor.tsTransform.Position, TSVector2.zero);
				canTriP4 = true;
				duration_p4_t = duration_p4;
				_actor.logicVariable.ToggleLogicTag("117p4SkillTrigger", value: false);
			}
			if (duration_p4_t > 0)
			{
				if (hitInterval_p4_t <= 0)
				{
					hitInterval_p4_t = hitInterval_p4;
				}
			}
			else if (canTriP4)
			{
				canTriP4 = false;
				playFx.Stop();
			}
			if (hitInterval_p4_t >= hitInterval_p4)
			{
				OnMainSkillHit();
			}
			if (canTriP5 && hitInterval_p5_t <= 0)
			{
				canTriP5 = false;
				OnShootBullet();
			}
			if (!canTriP8 && GetPerk(511708) && CheckPerkCd(511708L, CommonUtils.GetScriptValue(_actor, 11708011)))
			{
				_actor.buffComponent.AddBuff(11708011, _actor);
				canTriP8 = true;
			}
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private ComboAttack _comboAttack;

		private Dash _dash;

		private CoroutineNode _waitForCoroutine;

		private readonly FP speed = 2;

		private readonly FP distance = 1.2;

		private readonly FP _angleLimit = 12;

		private readonly FP _waitTime = 0.3;

		private readonly ComboInputBuffer.ActionKey[] _actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			if (_dash != null)
			{
				_dash.Clear();
				_dash = null;
			}
			if (_waitForCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForCoroutine);
				_waitForCoroutine = null;
			}
			_actor.DisableInvincible();
			_actor.ResumeMovementBlock();
			_actor.DisableImmuneControl();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				SetSkillPhaseConfig(SkillPhaseFeatureFlag.Skill1 | SkillPhaseFeatureFlag.Ultimate, null, SkillPhaseFeatureFlag.Ultimate, null);
				TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (movementInputDirection != TSVector2.zero)
				{
					_actor.ForceChangeDirection(movementInputDirection);
				}
				_waitForCoroutine = _actor.StartLogicCoroutine(WaitForCoroutine());
				_actor.PauseMovementBlock();
				_actor.EnableImmuneControl();
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				ComboInputBuffer.ActionKey[] actionKeys = _actionKeys;
				int skillId = ((_skill != null) ? _skill.skillId : 0);
				System.Action onActivationEnd = OnActivationEnd;
				System.Action onRecoveryBegin = OnRecoveryBegin;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, onRecoveryBegin, null, onComboFinish, onInterrupt, null, onActivationEnd);
				ToDash();
			}
		}

		protected IEnumerator WaitForCoroutine()
		{
			_actor.EnableInvincible();
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_waitTime));
			_actor.DisableInvincible();
			_waitForCoroutine = null;
		}

		protected void ToDash()
		{
			if (_dash == null)
			{
				_dash = new Dash();
			}
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			_dash.BeginDash(_actor, tSVector, speed, distance, _angleLimit, (System.Action)null, (System.Action)null, (System.Action)null, true, true, false, false, false, false, false, default(FP), true);
		}

		protected void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
		}

		protected void OnRecoveryBegin()
		{
			_actor.DisableInvincible();
			_actor.ResumeMovementBlock();
			_actor.DisableImmuneControl();
		}

		protected void OnFinish()
		{
			_dash?.Interrupte();
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		public void OnUpdate()
		{
			if (_actor.movementState == ActorState.Dash && _dash != null)
			{
				TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (tSVector == TSVector2.zero)
				{
					tSVector = _actor.tsTransform.Forward.normalized;
				}
				_dash._direction = tSVector;
			}
		}
	}
