	public class ParallelScript : ParallelBase
	{
		protected List<int> _damageTag_TriggerLandMark;

		private int _triggerTimes_D3;

		public override void OnEnable()
		{
			base.OnEnable();
			if (_damageTag_TriggerLandMark == null)
			{
				_damageTag_TriggerLandMark = new List<int>();
			}
			else
			{
				_damageTag_TriggerLandMark.Clear();
			}
			_damageTag_TriggerLandMark.Add(Config.damageTag_TriggerLandMark);
			_triggerTimes_D3 = 0;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
		}

		private void OnBeforeHit(IEvent evt)
		{
			if (!(evt is AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent) || !(adventureActorReceiveDamageBeforeHitEvent.from is PlayerAdventureActor) || !(adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor target) || !(adventureActorReceiveDamageBeforeHitEvent.from == _actor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511641, out var perkLevel) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_Trigger_P41))
			{
				AdventureActor.AddFromAttr(11641001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511642, out perkLevel) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, Config.damageTag_Trigger_P42))
			{
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("UltraSkillHitTimes");
				if (logicTagValue > 0)
				{
					FP scriptValue = CommonUtils.GetScriptValue(_actor, 11642011);
					AdventureActor.AddFromAttr(11642001, _actor, TSMath.Clamp(logicTagValue, 1, scriptValue).AsInt());
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 4) && CommonUtils.CheckElementMark(CommonDefine.EarthMark1, target))
			{
				AdventureActor.AddFromAttr(11696411, _actor);
			}
			OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			if (!(evt is AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent) || !(adventureActorReceiveDamageEvent.from is PlayerAdventureActor) || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monster))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 3) && adventureActorReceiveDamageEvent.skillSlotType == GameEnum.skillSlotType.D)
			{
				_triggerTimes_D3++;
				if (_triggerTimes_D3 >= 20)
				{
					foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
					{
						actorL.buffComponent.AddBuff(11696311, _actor);
					}
					_triggerTimes_D3 = 0;
				}
			}
			if (!(adventureActorReceiveDamageEvent.from == _actor))
			{
				return;
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511642, out var _) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_P42))
			{
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("UltraSkillHitTimes");
				_actor.logicVariable.SetLogicTagValue("UltraSkillHitTimes", logicTagValue + 1);
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 1) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_D1))
			{
				foreach (PlayerAdventureActor actorL2 in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL2.buffComponent.AddBuff(11696111, _actor);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 5) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, Config.damageTag_Trigger_D5))
			{
				_actor.buffComponent.AddBuff(11696511, _actor);
			}
			OnSelfDamaged(adventureActorReceiveDamageEvent);
			if (CheckCanTriggerLandMark(monster, adventureActorReceiveDamageEvent.hitDamageTag, adventureActorReceiveDamageEvent.weapon))
			{
				TriggerLandMark(monster, adventureActorReceiveDamageEvent.hitDamageTag);
			}
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		private bool CheckCanTriggerLandMark(MonsterAdventureActor monster, IList<int> hitDamageTag, AdventureWeapon hitWeapon)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (_damageTag_TriggerLandMark == null || _damageTag_TriggerLandMark.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.EarthMark1, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				for (int i = 0; i < _damageTag_TriggerLandMark.Count; i++)
				{
					int hitTag = _damageTag_TriggerLandMark[i];
					if (CommonUtils.CheckHitByTag(hitDamageTag, hitTag))
					{
						return true;
					}
				}
				return CheckWeaponCanTriggerLandMark(hitWeapon);
			}
			return false;
		}

		protected virtual bool CheckWeaponCanTriggerLandMark(AdventureWeapon hitWeapon)
		{
			return false;
		}

		private void TriggerLandMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_11601_LandTag1_Stone", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			monster.buffComponent.RemoveBuffByTag(CommonDefine.EarthMark1);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.EarthMark1, GameEnum.AdventureActorElementTriggerType.EarthElementTriggerType, _actor, monster, "LandMark_Trigger_Effect_02");
			OnTriggerLandMark(monster, hitDamageTag);
		}

		protected virtual void OnTriggerLandMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
		}

		private void OnElementMarkTrigger(IEvent evt)
		{
			if (evt is AdventureElementMarkTriggerEvent { elementType: GameEnum.elementType.SE } adventureElementMarkTriggerEvent)
			{
				if (ModuleController<AdventureModuleController>.Instance.CheckActorActiveTalentLevel(_actor.dataID, 2))
				{
					_actor.buffComponent.AddBuff(11696211, _actor);
				}
				OnLandMarkTrigger(adventureElementMarkTriggerEvent.triggerActor, adventureElementMarkTriggerEvent.markActor);
			}
		}

		protected virtual void OnLandMarkTrigger(AdventureActor triggerActor, AdventureActor markActor)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		private Dodge _dodge;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511611, out var _))
			{
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("LastTriggerTime_P11");
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 11611011);
				if (logicTagValue <= 0 || _actor.LogicTime - logicTagValue > scriptValue)
				{
					_actor.buffComponent.AddBuff(11611011, _actor);
					_actor.logicVariable.SetLogicTagValue("LastTriggerTime_P11", _actor.LogicTime);
				}
			}
		}

		public void OnStart()
		{
			ComboInputBuffer.ActionKey[] comboKeys_Dodge = Config.comboKeys_Dodge;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(comboKeys_Dodge, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, Config.duration_Dodge, Config.distance_Dodge, null, comboWithAttack: true);
		}

		public void OnUpdate()
		{
			if (!(_actor.attackTarget == null) && (!((PlayerAdventureActor)_actor).dodgeButtonHold || _actor.forbiddenRush))
			{
				SkillPhaseConfig currentPhaseBreakConfig = _skill.GetCurrentPhaseBreakConfig();
				if (currentPhaseBreakConfig != null && (currentPhaseBreakConfig.skillPhaseFeatureFlag & SkillPhaseFeatureFlag.Normal) != SkillPhaseFeatureFlag.None && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
				{
					base.comboAttack.InterruptAttack();
				}
			}
		}

		private void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
		}

		private void OnFinish()
		{
			_skill?.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_dodge?.Interrupte();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private List<TSVector2> _shootDirectionList;

		private bool _isStrength;

		private bool _triggerPerk_P3;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_isStrength = _actor.buffComponent.CheckBuffByBuffTag(Config_MainControl.buffTag_Strength_Skill);
			_triggerPerk_P3 = false;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511603, out var _))
			{
				_triggerPerk_P3 = _actor.logicVariable.GetLogicTagValue("TriggerBulletCount_P3").AsInt() >= 12;
			}
		}

		public void OnStart()
		{
			string text = (_isStrength ? "Shoot_Strength" : "Shoot");
			if (_triggerPerk_P3)
			{
				text = (_isStrength ? "Shoot_Perk03" : "Shoot_Perk03");
			}
			if (_actor.attackTarget != null)
			{
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("LastUseSpecialCombo_NormalAttack");
				if ((logicTagValue <= 0 || _actor.LogicTime - logicTagValue > Config.interval_UseSpecialCombo_NormalAttack) && _actor.DistanceWithRadius(_actor.attackTarget) < Config.distance_UseSpecialCombo_NormalAttack)
				{
					text = "Melee";
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 511612, out var _))
					{
						text = "Melee_Strengthed";
					}
					_actor.logicVariable.SetLogicTagValue("LastUseSpecialCombo_NormalAttack", _actor.LogicTime);
				}
			}
			string actionTag = text;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "116_Event_NormalAtk_Shoot"))
			{
				Shoot();
			}
		}

		private void Shoot()
		{
			TSVector2 position;
			FP y;
			if (_triggerPerk_P3)
			{
				position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_MainControl.shootPositionOffset_NormalAttack_P3.x + _actor.tsTransform.Forward * Config_MainControl.shootPositionOffset_NormalAttack_P3.z;
				y = Config_MainControl.shootPositionOffset_NormalAttack_P3.y;
				if (_isStrength)
				{
					position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_MainControl.shootPositionOffset_NormalAttack_Strength_P3.x + _actor.tsTransform.Forward * Config_MainControl.shootPositionOffset_NormalAttack_Strength_P3.z;
					y = Config_MainControl.shootPositionOffset_NormalAttack_Strength_P3.y;
				}
				ILRuntimeAPI.ShootByDirection("Bullet_11601_NormalBullet_Perk03", _actor, default(FP), _actor.tsTransform.Forward, position, y);
				_actor.logicVariable.SetLogicTagValue("TriggerBulletCount_P3", 0);
				return;
			}
			int num = 2;
			FP fP = Config.shootIncludedAngle_NormalAttack;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511604, out var perkLevel))
			{
				num += 2;
				fP = Config_MainControl.shootIncludedAngle_NormalAttack_P4;
			}
			if (num <= 0)
			{
				return;
			}
			position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config.shootPositionOffset_NormalAttack.x + _actor.tsTransform.Forward * Config.shootPositionOffset_NormalAttack.z;
			y = Config.shootPositionOffset_NormalAttack.y;
			if (_isStrength)
			{
				position = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_MainControl.shootPositionOffset_NormalAttack_Strength.x + _actor.tsTransform.Forward * Config_MainControl.shootPositionOffset_NormalAttack_Strength.z;
				y = Config_MainControl.shootPositionOffset_NormalAttack_Strength.y;
			}
			string bulletAlias = (_isStrength ? "Bullet_11601_NormalBullet_MainSkill" : "Bullet_11601_NormalBullet");
			if (_shootDirectionList == null)
			{
				_shootDirectionList = new List<TSVector2>();
			}
			else
			{
				_shootDirectionList.Clear();
			}
			if (num > 1)
			{
				FP fP2 = (num - 1) * fP;
				TSVector2 v = TSVector2.Rotate(_actor.tsTransform.Forward, -fP2 * 0.5f);
				for (int i = 0; i < num; i++)
				{
					_shootDirectionList.Add(TSVector2.Rotate(v, fP * i));
				}
			}
			else
			{
				_shootDirectionList.Add(_actor.tsTransform.Forward);
			}
			for (int j = 0; j < _shootDirectionList.Count; j++)
			{
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.ShootByDirection(bulletAlias, _actor, default(FP), _shootDirectionList[j], position, y);
				if (adventureBulletBase != null)
				{
					if (_isStrength)
					{
						adventureBulletBase.AddSubTag(Config_MainControl.bulletSubTag_IsStrength);
					}
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 511608, out perkLevel))
					{
						adventureBulletBase.ModifyWeaponScaleByMulti(1 + Config_MainControl.addBulletScale_P8 * 0.01f);
					}
				}
			}
			if (!_isStrength)
			{
				_actor.ammoInfo?.RefreshAmmoCost(-num);
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_isStrength = false;
		}
	}
