	public class ActionScript_MainControl : ActionScript
	{
		private AimTarget _aimTarget;

		private PlayFX _playFX_HaveAmmo;

		private bool _haveAmmo;

		private bool HaveAmmo
		{
			get
			{
				return _haveAmmo;
			}
			set
			{
				if (_haveAmmo == value)
				{
					return;
				}
				_haveAmmo = value;
				if (_haveAmmo)
				{
					if (_playFX_HaveAmmo == null)
					{
						_playFX_HaveAmmo = new PlayFX();
					}
					else
					{
						_playFX_HaveAmmo.Stop();
					}
					_playFX_HaveAmmo.Play(_actor, null, "fx_11601_loop_Attack_LongRange_Charged", default(FP), _actor.tsTransform.Position, default(TSVector2));
				}
				else
				{
					_playFX_HaveAmmo?.Stop();
				}
			}
		}

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			else
			{
				_aimTarget.Clear();
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511611, out var _))
			{
				_playerSkillCd.SetSkillTotalSection(ActionKey.A, _playerSkillCd.GetSkillCD(ActionKey.A).originalTotalSectionAmount + 1);
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.A);
			}
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		protected override void OnButtonDPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		public override void OnUpdate()
		{
			HaveAmmo = _actor.ammoInfo.ammoCount > 0;
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.attackTarget == null || _actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill2 | SkillPhaseFeatureFlag.Dodge) || base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack)
			{
				if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget?.Cancel();
				}
				return;
			}
			FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
			if (fP < CommonUtils.GetAimRange(_actor))
			{
				if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget)
				{
					_aimTarget.Aim(_actor, (AdventureActor)_actor.attackTarget, default(TSVector2), playStartAnim: true);
				}
				if (fP <= CommonUtils.GetAttackRange(_actor) && _actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && HaveAmmo)
				{
					ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
				}
			}
			else if (_actor.aimMode != AdventureActor.AimMode.Forward)
			{
				_aimTarget?.Cancel();
			}
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			_playFX_HaveAmmo?.Stop();
			_playFX_HaveAmmo?.Clear();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private List<MonsterAdventureActor> _summonedList_P2;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511613, out var _))
			{
				_damageTag_TriggerLandMark?.Add(Config_MainControl.damageTag_TriggerLandMark_P13);
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_BORN", OnBulletBorn);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("BATTLE_MONSTER_SUMMONER_SPAWNED", OnSummonedSpawned);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDied);
		}

		private void OnGetBuff(IEvent evt)
		{
			if (evt is AdventureActorGetBuff adventureActorGetBuff && adventureActorGetBuff.eventInfo.buffTags.Contains(Config_MainControl.buffTag_Strength_Skill))
			{
				FP leftTime = adventureActorGetBuff.buff.LeftTime;
				int currentBindSkillId = ((PlayerAdventureActor)_actor).playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal);
				MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", currentBindSkillId);
				MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintStart", currentBindSkillId, leftTime.AsFloat(), a3: true);
			}
		}

		private void OnRemoveBuff(IEvent evt)
		{
			if (evt is AdventureActorRemoveBuff adventureActorRemoveBuff && adventureActorRemoveBuff.eventInfo.buffTags.Contains(Config_MainControl.buffTag_Strength_Skill))
			{
				int currentBindSkillId = ((PlayerAdventureActor)_actor).playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal);
				MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", currentBindSkillId);
			}
		}

		private void OnBulletBorn(IEvent evt)
		{
			if (evt is AdventureBulletBornEvent adventureBulletBornEvent && adventureBulletBornEvent.owner == _actor)
			{
				AdventureBulletBase adventureBulletBase = adventureBulletBornEvent.sender as AdventureBulletBase;
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511603, out var _) && adventureBulletBase.CheckBulletTag(Config_MainControl.bulletTag_Trigger_P3))
				{
					FP logicTagValue = _actor.logicVariable.GetLogicTagValue("TriggerBulletCount_P3");
					_actor.logicVariable.SetLogicTagValue("TriggerBulletCount_P3", logicTagValue + 1);
				}
			}
		}

		private void OnBulletFinish(IEvent evt)
		{
			if (!(evt is AdventureBulletFinishEvent adventureBulletFinishEvent) || !(adventureBulletFinishEvent.owner == _actor))
			{
				return;
			}
			AdventureBulletBase adventureBulletBase = adventureBulletFinishEvent.sender as AdventureBulletBase;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511602, out var _) && adventureBulletBase.CheckBulletTag(Config_MainControl.bulletTag_Summoned_P2))
			{
				TSVector2 tSVector = adventureBulletBase.tsTransform.Forward;
				if (_actor.attackTarget != null)
				{
					tSVector = (_actor.attackTarget.tsTransform.Position - adventureBulletBase.tsTransform.Position).normalized;
				}
				ILRuntimeAPI.SummonMonster(_actor, 0, 11601111, adventureBulletBase.tsTransform.Position, tSVector, Config_MainControl.summonCfg_Summon_P2, (string)null, (Action<MonsterAdventureActor>)null);
			}
		}

		private void OnSummonedSpawned(IEvent evt)
		{
			if (!(evt is AdventureMonsterSummonerSpawnedEvent adventureMonsterSummonerSpawnedEvent) || adventureMonsterSummonerSpawnedEvent.summonerId != _actor.Id || !CommonUtils.HavePersonalPerk(_actor.dataID, 511602, out var perkLevel))
			{
				return;
			}
			int num = 2;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511607, out perkLevel))
			{
				num = 3;
			}
			if (adventureMonsterSummonerSpawnedEvent.dataId != 11601111 || num <= 0)
			{
				return;
			}
			if (_summonedList_P2 == null)
			{
				_summonedList_P2 = new List<MonsterAdventureActor>();
			}
			if (_summonedList_P2.Count >= num)
			{
				_summonedList_P2.Sort((MonsterAdventureActor x, MonsterAdventureActor y) => x.monsterSummonInfo.leftTime.CompareTo(y.monsterSummonInfo.leftTime));
				MonsterAdventureActor monsterAdventureActor = _summonedList_P2.First();
				AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
				adventureActorCustomEvent.sender = monsterAdventureActor;
				adventureActorCustomEvent.eventHashCode = Config_MainControl.eventHashCode_Summoned_DestroySelf_P2;
				monsterAdventureActor.DispatchEvent(adventureActorCustomEvent);
				_summonedList_P2.Remove(monsterAdventureActor);
			}
			MonsterAdventureActor item = ModuleController<AdventureModuleController>.Instance.QueryMonsterEntityByID(adventureMonsterSummonerSpawnedEvent.id) as MonsterAdventureActor;
			_summonedList_P2.Add(item);
		}

		private void OnMonsterDied(IEvent evt)
		{
			PlayerAdventureActor playerAdventureActor = default(PlayerAdventureActor);
			if (evt is AdventureMonsterDiedEvent { sender: MonsterAdventureActor sender } && ActorHelper.IsPlayerSummoned((LogicEntity)sender, ref playerAdventureActor) && playerAdventureActor == _actor && sender.dataID == 11601111 && _summonedList_P2 != null && _summonedList_P2.Count > 0)
			{
				_summonedList_P2.Remove(sender);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511606, out var perkLevel) && monsterAdventureActor.buffComponent.GetBuffNum(0, 0, Config_MainControl.buffTag_ReduceSpeed_Skill_P6) >= 3)
			{
				AdventureActor.AddFromAttr(11606001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511609, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, Config_MainControl.damageTag_Trigger_P9))
			{
				AdventureActor.AddFromAttr(11609001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511612, out perkLevel) && _actor.DistanceWithRadius(monsterAdventureActor) > Config_MainControl.addDamageDistance_P12)
			{
				AdventureActor.AddFromAttr(11612001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_MainControl.damageTag_Bullet_Skill))
			{
				int buffID = 11690012;
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511606, out var _))
				{
					buffID = 11606011;
				}
				monsterAdventureActor.buffComponent.AddBuff(buffID, _actor);
			}
		}

		protected override bool CheckWeaponCanTriggerLandMark(AdventureWeapon hitWeapon)
		{
			if (hitWeapon is AdventureBulletBase adventureBulletBase && adventureBulletBase.CheckSubTag(Config_MainControl.bulletSubTag_IsStrength))
			{
				return true;
			}
			return false;
		}

		protected override void OnTriggerLandMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			base.OnTriggerLandMark(monster, hitDamageTag);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511613, out var _) && CommonUtils.CheckHitByTag(hitDamageTag, Config_MainControl.damageTag_TriggerLandMark_P13))
			{
				_actor.buffComponent.AddBuff(11613011, _actor);
			}
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_BORN", OnBulletBorn);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BATTLE_MONSTER_SUMMONER_SPAWNED", OnSummonedSpawned);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_MONSTER_DIED", OnMonsterDied);
			int? a = ((PlayerAdventureActor)_actor)?.playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal);
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", a);
			_summonedList_P2?.Clear();
		}
	}
	public class SkillScript_Skill_MainControl : SkillAdvancedBase
	{
		private List<TSVector2> _shootDirectionList;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt();
		}

		public void OnStart()
		{
			string text = "B1_Skill";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511601, out var _))
			{
				text = "B1_Skill_Perk1";
			}
			string actionTag = text;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		public void OnUpdate()
		{
			LockDirection();
		}

		private void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "116_MainSkill_Shoot"))
			{
				Shoot();
			}
			else if (string.Equals(eventName, "116_MainSkill_StrengthShoot"))
			{
				_actor.buffComponent.RemoveBuffByTag(Config_MainControl.buffTag_Strength_Skill);
				int buffID = 11690011;
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511610, out var _))
				{
					buffID = 11610011;
				}
				_actor.buffComponent.AddBuff(buffID, _actor);
				_actor.ammoInfo.ammoCount = _actor.ammoInfo.ammoCountMax;
			}
		}

		private void Shoot()
		{
			TSVector2 tSVector = _actor.tsTransform.Position + _actor.tsTransform.Left * Config_MainControl.shootPositionOffset_Skill.x + _actor.tsTransform.Forward * Config_MainControl.shootPositionOffset_Skill.z;
			FP y = Config_MainControl.shootPositionOffset_Skill.y;
			string bulletAlias = "Bullet_11601_MainSkill_Seed";
			int num = 1;
			FP fP = 0;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511601, out var perkLevel))
			{
				bulletAlias = "Bullet_11601_MainSkill_Seed_Perk01";
				num = 2;
				fP = Config_MainControl.totalAngle_Shoot_Skill_P1;
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511607, out perkLevel))
				{
					FP scriptValue = CommonUtils.GetScriptValue(_actor, 11607011);
					if (TSRandom.Range(0f, 100f) <= scriptValue)
					{
						num++;
						fP = Config_MainControl.totalAngle_Shoot_Skill_P1_P7;
					}
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511607, out perkLevel))
			{
				FP scriptValue2 = CommonUtils.GetScriptValue(_actor, 11607011);
				if (TSRandom.Range(0f, 100f) <= scriptValue2)
				{
					num++;
					fP = Config_MainControl.totalAngle_Shoot_Skill_P7;
				}
			}
			if (num <= 0)
			{
				return;
			}
			if (_shootDirectionList == null)
			{
				_shootDirectionList = new List<TSVector2>();
			}
			else
			{
				_shootDirectionList.Clear();
			}
			if (num > 1)
			{
				FP fP2 = fP / (num - 1);
				TSVector2 v = TSVector2.Rotate(_actor.tsTransform.Forward, -fP * 0.5f);
				for (int i = 0; i < num; i++)
				{
					_shootDirectionList.Add(TSVector2.Rotate(v, fP2 * i));
				}
			}
			else
			{
				_shootDirectionList.Add(_actor.tsTransform.Forward);
			}
			FP fP3 = Config_MainControl.maxShootDistance_Skill;
			if (_actor.attackTarget != null)
			{
				fP3 = TSMath.Clamp(TSVector2.Distance(tSVector, _actor.attackTarget.tsTransform.Position) - _actor.attackTarget.GetRadius(), Config_MainControl.minShootDistance_Skill, Config_MainControl.maxShootDistance_Skill);
			}
			for (int j = 0; j < _shootDirectionList.Count; j++)
			{
				TSVector2 result = tSVector + _shootDirectionList[j] * fP3;
				if (!_actor.QueryPositionWalkable(result))
				{
					_actor.QueryClosestPositionWalkable(result, out result);
				}
				AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bulletAlias, _actor, default(FP), tSVector, y, result, null, AimType.Position, BulletDirectionType.BulletToTarget);
				if (adventureBulletBase != null && CommonUtils.HavePersonalPerk(_actor.dataID, 511605, out perkLevel))
				{
					adventureBulletBase.ModifyWeaponScaleByMulti(1 + Config_MainControl.addBulletScale_P5 * 0.01f);
				}
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}
	}
	public class ActionScript_Summoned : AIBase
	{
		private FP _useSkillInterval;

		public void OnEnable()
		{
		}

		public void OnStart()
		{
			_useSkillInterval = 0;
			_actor.monsterTarget = null;
		}

		public void OnUpdate()
		{
			_actor.monsterTarget = GetAttackTarget();
			if (_useSkillInterval > 0)
			{
				_useSkillInterval -= _actor.LogicDeltaTime;
				return;
			}
			ILRuntimeAPI.CreateSkill(11601121, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Monster, isInterruptAttack: true, isBreakable: false);
			_useSkillInterval = Config_MainControl.useSkillInterval_Summoned_P2;
		}

		private LogicEntity GetAttackTarget()
		{
			FP currentAttackRange = _actor.actorSearchTargetInfo.GetCurrentAttackRange();
			List<LogicEntity> list = ILRuntimeAPI.SearchByRange(_actor, currentAttackRange, null, isConfront: true);
			if (list != null && list.Count > 0)
			{
				LogicEntity logicEntity = (SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor as PlayerAdventureActor)?.attackTarget;
				if (logicEntity != null && list.Contains(logicEntity))
				{
					return logicEntity;
				}
				return ILRuntimeAPI.GetTargetNearOrFar(_actor, iNear: true, list);
			}
			return null;
		}

		public void OnStop()
		{
			_useSkillInterval = 0;
			_actor.monsterTarget = null;
		}

		public void OnDisable()
		{
		}
	}
	public class ParallelScript_Summoned : AIBase
	{
		private PlayFX _playFX;

		public void OnEnable()
		{
			if (_playFX == null)
			{
				_playFX = new PlayFX();
			}
			else
			{
				_playFX.Clear();
			}
			_playFX.Play(_actor, null, "fx_11601_loop_Skill_Main_PeaShooter_born", default(FP), _actor.tsTransform.Position, default(TSVector2));
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_DIED", OnDied);
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent && adventureActorCustomEvent.eventHashCode == Config_MainControl.eventHashCode_Summoned_DestroySelf_P2)
			{
				DestroySelf();
			}
		}

		private void OnBattleReady(IEvent evt)
		{
			DestroySelf();
		}

		private void DestroySelf()
		{
			if (_actor.state == ActorState.Spawn)
			{
				_actor.StartLogicCoroutine(WaitForDestroySelf());
			}
			else
			{
				_actor.DestroySelf();
			}
		}

		private IEnumerator WaitForDestroySelf()
		{
			while (_actor.state == ActorState.Spawn)
			{
				yield return null;
			}
			_actor.DestroySelf();
		}

		private void OnDied(IEvent evt)
		{
			if (evt is AdventureActorDiedEvent adventureActorDiedEvent && adventureActorDiedEvent.actor == _actor)
			{
				_playFX?.Stop();
				_playFX?.Clear();
			}
		}

		public void OnDisable()
		{
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_BATTLE_READY_MSG", OnBattleReady);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnDied);
			_actor.DisablePenetrate();
			_playFX?.Stop();
			_playFX?.Clear();
		}
	}
