		{
			if (_actor.monsterTarget != null)
			{
				_actor.LookAt(_actor.monsterTarget.tsTransform.Position, 0);
			}
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("116_PeaShooter_Atk", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
