			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			int perkLevel;
			if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_AddSeedBuff_Skill))
			{
				int buffID = 11691011;
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511623, out perkLevel))
				{
					buffID = 11623011;
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 511629, out perkLevel))
					{
						monsterAdventureActor.buffComponent.AddBuff(11629012, _actor);
					}
				}
				else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511629, out perkLevel))
				{
					monsterAdventureActor.buffComponent.AddBuff(11629011, _actor);
				}
				monsterAdventureActor.buffComponent.AddBuff(buffID, _actor);
			}
			if (CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_SeedExplosion_Skill))
			{
				if (_receiveExplosionDamageDic == null)
				{
					_receiveExplosionDamageDic = new Dictionary<long, int>();
				}
				if (_receiveExplosionDamageDic.TryGetValue(monsterAdventureActor.Id, out var value))
				{
					_receiveExplosionDamageDic[monsterAdventureActor.Id] = value + 1;
				}
				else
				{
					_receiveExplosionDamageDic.Add(monsterAdventureActor.Id, 1);
				}
				if (_receiveExplosionDamageCDCorDic == null)
				{
					_receiveExplosionDamageCDCorDic = new Dictionary<long, CoroutineNode>();
				}
				if (_receiveExplosionDamageDic[monsterAdventureActor.Id] >= 6)
				{
					monsterAdventureActor.buffComponent.AddBuff(11691013, _actor);
					_receiveExplosionDamageDic[monsterAdventureActor.Id] = 0;
					if (_receiveExplosionDamageCDCorDic.TryGetValue(monsterAdventureActor.Id, out var value2))
					{
						_actor.StopLogicCoroutine(value2);
						_receiveExplosionDamageCDCorDic.Remove(monsterAdventureActor.Id);
					}
				}
				else if (!_receiveExplosionDamageCDCorDic.ContainsKey(monsterAdventureActor.Id))
				{
					_receiveExplosionDamageCDCorDic.Add(monsterAdventureActor.Id, _actor.StartLogicCoroutine(ReceiveExplosionCD(monsterAdventureActor.Id)));
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511623, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P23))
			{
				monsterAdventureActor.buffComponent.AddBuff(6011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511626, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P26))
			{
				monsterAdventureActor.buffComponent.AddBuff(11626011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511631, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P31))
			{
				monsterAdventureActor.buffComponent.AddBuff(6011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511624, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, Config_Support.damageTag_Trigger_P24) && monsterAdventureActor.buffComponent.CheckBuffByBuffTag(Config_Support.buffTag_Seed_Skill))
			{
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("TriggerExplosionTimes_P24");
				if (logicTagValue < 10 && TriggerSeedExplosion(monsterAdventureActor))
				{
					_actor.logicVariable.SetLogicTagValue("TriggerExplosionTimes_P24", logicTagValue + 1);
				}
			}
		}

		private IEnumerator ReceiveExplosionCD(long monsterId)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.unitTime_TriggerSeedExplosion_Skill));
			if (_receiveExplosionDamageDic.ContainsKey(monsterId))
			{
				_receiveExplosionDamageDic[monsterId] = 0;
			}
			_receiveExplosionDamageCDCorDic.Remove(monsterId);
		}

		protected override void OnLandMarkTrigger(AdventureActor triggerActor, AdventureActor markActor)
		{
			base.OnLandMarkTrigger(triggerActor, markActor);
			if (markActor.buffComponent.CheckBuffByBuffTag(Config_Support.buffTag_Seed_Skill))
			{
				TriggerSeedExplosion(markActor);
			}
		}

		private bool TriggerSeedExplosion(AdventureActor target)
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511624, out var perkLevel))
			{
				if (target.buffComponent.CheckBuffByBuffID(11691014))
				{
					return false;
				}
				target.buffComponent.AddBuff(11691014, _actor);
			}
			FP explosionScale = 1;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511624, out perkLevel))
			{
				explosionScale = 1 + Config_Support.addAreaEffectScale_P24 * 0.01f;
			}
			PlayFX playFX = new PlayFX();
			playFX.Play(_actor, null, "fx_11601_base_Skill_Sup_seed_bomb_explosion", default(FP), target.tsTransform.Position, default(TSVector2), null, 1f, explosionScale.AsFloat());
			playFX.fxInstance.Bind(target.gameObject, target.gameObject);
			ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_11601_Skill_Sup_AttachSeedBoom", target.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity areaEffect)
			{
				areaEffect.ModifyScale(explosionScale);
			}, (AdventureActor)null);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511630, out perkLevel))
			{
				List<LogicEntity> list = ILRuntimeAPI.SearchByRangeAndPosition(_actor, target.tsTransform.Position, Config_Support.searchRadius_P30, null, isConfront: true, onlyAlive: true, includeSelf: false, (LogicEntity entity) => entity != target);
				if (list.Count > 0)
				{
					LogicEntity logicEntity = list[TSRandom.Range(0, list.Count)];
					TSVector2 normalized = (logicEntity.tsTransform.Position - target.tsTransform.Position).normalized;
					TSVector2 position = target.tsTransform.Position + TSVector2.Rotate(normalized, 90) * Config_Support.shootOffset_P30.x + normalized * (target.GetRadius() + Config_Support.shootOffset_P30.z);
					FP y = Config_Support.shootOffset_P30.y;
					ILRuntimeAPI.Shoot("Bullet_11601_Skill_Sup_Seed_Perk30", _actor, default(FP), position, y, logicEntity.tsTransform.Position, null, AimType.Position, BulletDirectionType.BulletToTarget);
				}
			}
			return true;
		}

		private void Clear()
		{
			_receiveExplosionDamageDic?.Clear();
			if (_receiveExplosionDamageCDCorDic == null || _receiveExplosionDamageCDCorDic.Count <= 0)
			{
				return;
			}
			foreach (CoroutineNode value in _receiveExplosionDamageCDCorDic.Values)
			{
				_actor.StopLogicCoroutine(value);
			}
			_receiveExplosionDamageCDCorDic.Clear();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			Clear();
		}
	}
	public class SkillScript_Skill_Support : SkillAdvancedBase
	{
		private CoroutineNode _perkLogicCor_P21;

		private CoroutineNode _perkLogicCor_P25;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511625, out var _))
			{
				_actor.buffComponent.RemoveBuffByBuffId(11625011);
				if (_perkLogicCor_P25 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P25);
				}
				_perkLogicCor_P25 = _actor.StartLogicCoroutine(PerkLogic_P25());
			}
		}

		public void OnStart()
		{
			_actor.logicVariable.SetLogicTagValue("TriggerExplosionTimes_P24", 0);
			DefaultLookAt();
			string text = "B2_Skill";
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511622, out var _))
			{
				text = "B2_Skill_Perk22";
			}
			string actionTag = text;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		private void OnCustomEvent(string eventName)
		{
			if (!string.Equals(eventName, "SupSkill_SeedRain"))
			{
				return;
			}
			TSVector2 tSVector = _actor.tsTransform.Position + _actor.tsTransform.Forward * Config_Support.generateDistance_NoTarget_Skill;
			if (_actor.attackTarget != null)
			{
				tSVector = _actor.attackTarget.tsTransform.Position;
			}
			string text = "AreaEffect_11601_Skill_Sup_Seed";
			int additionalAttrId = 0;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511621, out var perkLevel) && _actor.logicVariable.GetLogicTagToggle("TriggerPerk_P21"))
			{
				text = "AreaEffect_11601_Skill_Sup_Seed";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511622, out perkLevel))
				{
					text = "AreaEffect_11601_Skill_Sup_Seed_Perk22";
					if (CommonUtils.HavePersonalPerk(_actor.dataID, 511627, out perkLevel))
					{
						text = "AreaEffect_11601_Skill_Sup_Seed_Perk22_Perk27";
					}
				}
				else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511627, out perkLevel))
				{
					text = "AreaEffect_11601_Skill_Sup_Seed_Perk27";
				}
				additionalAttrId = 11621001;
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511622, out perkLevel))
			{
				text = "AreaEffect_11601_Skill_Sup_Seed_Perk22";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511627, out perkLevel))
				{
					text = "AreaEffect_11601_Skill_Sup_Seed_Perk22_Perk27";
				}
			}
			else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511627, out perkLevel))
			{
				text = "AreaEffect_11601_Skill_Sup_Seed_Perk27";
			}
			ILRuntimeAPI.PlayAreaEffect(_actor, text, tSVector, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity areaEffect)
			{
				if (additionalAttrId > 0)
				{
					areaEffect.AddAdditionalAttr(additionalAttrId);
				}
			}, (AdventureActor)null);
		}

		private IEnumerator PerkLogic_P21()
		{
			if (Config_Support.useSkillInterval_P21 > 0)
			{
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(Config_Support.useSkillInterval_P21));
			}
			OnStart();
		}

		private IEnumerator PerkLogic_P25()
		{
			FP interval = Config_Support.addBuffInterval_P25;
			while (true)
			{
				interval -= _actor.LogicDeltaTime;
				if (interval <= 0)
				{
					interval += Config_Support.addBuffInterval_P25;
					_actor.buffComponent.AddBuff(11625011, _actor);
				}
				yield return null;
			}
		}

		protected void OnFinish()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511621, out var _))
			{
				if (!_actor.logicVariable.GetLogicTagToggle("TriggerPerk_P21"))
				{
					_actor.logicVariable.ToggleLogicTag("TriggerPerk_P21", value: true);
					if (_perkLogicCor_P21 != null)
					{
						_actor.StopLogicCoroutine(_perkLogicCor_P21);
					}
					_perkLogicCor_P21 = _actor.StartLogicCoroutine(PerkLogic_P21());
				}
				else
				{
					_skill.Clear();
				}
			}
			else
			{
				_skill.Clear();
			}
		}

		protected void OnInterrupt()
		{
			_skill.Clear();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.logicVariable.ToggleLogicTag("TriggerPerk_P21", value: false);
			if (_perkLogicCor_P21 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P21);
			}
			_perkLogicCor_P21 = null;
			if (_perkLogicCor_P25 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P25);
			}
			_perkLogicCor_P25 = null;
		}
	}
}
namespace AIScript.Character._11501
{
	public class ActionScript : ActorActionBase
	{
		protected enum SkillType
		{
			NormalAttack,
			Dodge,
			Skill,
			Ultra
		}

		protected const int skillId_NormalAttack_Default = 11510000;

		protected const int perkId_41 = 511541;

		protected const int buffId_P41 = 11541011;

		protected const int perkId_42 = 511542;

		protected static readonly int damageTag_P42 = CommonHelper.StringToHash("115_Ultra");

		protected const int additionalAttrId_P42 = 11542001;

		protected const int perkId_43 = 511543;

		protected const int buffId_P43 = 11543011;

		protected List<SkillType> _runningSkillTypes;

		protected static readonly List<AnimationSlotConfigComponent.SlotType> allSlotTypes = new List<AnimationSlotConfigComponent.SlotType>
		{
			AnimationSlotConfigComponent.SlotType.Extra_1,
			AnimationSlotConfigComponent.SlotType.Extra_2,
			AnimationSlotConfigComponent.SlotType.Extra_3,
			AnimationSlotConfigComponent.SlotType.Extra_4
		};

		private CoroutineNode _deformationStatusCor;

		protected AimTarget _aimTarget;

		private LogicEntity _lockAttackTarget;

		private long _lockAttackTargetId;

		protected CoroutineNode DeformationStatusCor
		{
			get
			{
				return _deformationStatusCor;
			}
			set
			{
				if (_deformationStatusCor != value)
				{
					_deformationStatusCor = value;
				}
			}
		}

		protected bool InDeformationStatus
		{
			get
			{
				if (((PlayerAdventureActor)_actor).status == ActorStatus.Special)
				{
					return ((PlayerAdventureActor)_actor).specialStatusTime > 0;
				}
				return false;
			}
		}

		protected LogicEntity LockAttackTarget
		{
			get
			{
				return _lockAttackTarget;
			}
			set
			{
				_lockAttackTarget = value;
				_lockAttackTargetId = ((_lockAttackTarget != null) ? _lockAttackTarget.Id : 0);
			}
		}

		protected long LockAttackTargetId => _lockAttackTargetId;

		protected override void OnActionEnable()
		{
			if (_runningSkillTypes == null)
			{
				_runningSkillTypes = new List<SkillType>(5);
			}
			else
			{
				_runningSkillTypes.Clear();
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
		}

		public override void OnStart()
		{
			base.OnStart();
			_actor.logicVariable.SetLogicTagValue("SkillNormalAttackStage", 1);
		}

		public virtual void OnUpdate()
		{
			if (DeformationStatusCor != null || _runningSkillTypes.Contains(SkillType.Ultra))
			{
				return;
			}
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (!CanAimTarget())
			{
				if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget?.Cancel();
				}
				return;
			}
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget)
			{
				_aimTarget.Aim(_actor, (AdventureActor)_actor.attackTarget);
			}
			if (_actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor) && _actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
			{
				_runningSkillTypes.Add(SkillType.NormalAttack);
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnNormalAttackFinish);
			}
		}

		private bool CanAimTarget()
		{
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill2 | SkillPhaseFeatureFlag.Dodge) || base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack)
			{
				return false;
			}
			return _actor.attackTarget != null;
		}

		protected void OnNormalAttackFinish(bool success)
		{
			_runningSkillTypes.Remove(SkillType.NormalAttack);
			OnActorSkillFinish(SkillType.NormalAttack, success);
		}

		protected void OnDodgeFinish(bool success)
		{
			_runningSkillTypes.Remove(SkillType.Dodge);
			OnActorSkillFinish(SkillType.Dodge, success);
		}

		protected void OnSkillFinish(bool success)
		{
			_runningSkillTypes.Remove(SkillType.Skill);
			OnActorSkillFinish(SkillType.Skill, success);
		}

		protected void OnUltraSkillFinish(bool success)
		{
			_runningSkillTypes.Remove(SkillType.Ultra);
			if (success)
			{
				_playerSkillCd.ResetSkillCD(ActionKey.B);
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511541, out var perkLevel))
				{
					_actor.logicVariable.ToggleLogicTag("CanTrigger_P41", value: true);
				}
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out perkLevel))
				{
					_actor.logicVariable.ToggleLogicTag("CanTrigger_P42", value: false);
				}
			}
			OnActorSkillFinish(SkillType.Ultra, success);
		}

		protected virtual void OnActorSkillFinish(SkillType skillType, bool success)
		{
		}

		protected virtual void ForceStopDeformationStatusCor()
		{
			if (DeformationStatusCor != null)
			{
				_actor.StopLogicCoroutine(DeformationStatusCor);
				DeformationStatusCor = null;
				OnDeformationFinish();
			}
		}

		protected virtual void OnDeformationBegin()
		{
			(_actor as PlayerAdventureActor).status = ActorStatus.Special;
			_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, GetDeformationNormalAttackId());
		}

		protected virtual int GetDeformationNormalAttackId()
		{
			return 11510000;
		}

		protected virtual void OnDeformationFinish()
		{
			LockAttackTarget = null;
			(_actor as PlayerAdventureActor).status = ActorStatus.Default;
			(_actor as PlayerAdventureActor).specialStatusTime = 0;
			_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, 11510000);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511541, out var _))
			{
				_actor.buffComponent?.RemoveBuffByBuffId(11541011);
				_actor.logicVariable.ToggleLogicTag("CanTrigger_P41", value: false);
			}
		}

		private void OnActorDied(IEvent evt)
		{
			AdventureActorDiedEvent adventureActorDiedEvent = evt as AdventureActorDiedEvent;
			if (adventureActorDiedEvent.killer == _actor && adventureActorDiedEvent.actor is MonsterAdventureActor)
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511543, out var _) && _runningSkillTypes.Contains(SkillType.Ultra))
				{
					_actor.buffComponent?.AddBuff(11543011, _actor);
				}
				OnSelfKillTarget(adventureActorDiedEvent);
			}
		}

		protected virtual void OnSelfKillTarget(AdventureActorDiedEvent diedEvent)
		{
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor)
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out var _) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P42") && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, damageTag_P42))
				{
					AdventureActor.AddFromAttr(11542001, _actor);
				}
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && adventureActorReceiveDamageEvent.to is MonsterAdventureActor)
			{
				OnDamage(adventureActorReceiveDamageEvent);
			}
		}

		protected virtual void OnDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		public override void OnStop()
		{
			base.OnStop();
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			if (_deformationStatusCor != null)
			{
				_actor.StopLogicCoroutine(_deformationStatusCor);
			}
			_deformationStatusCor = null;
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_DIED", OnActorDied);
			_runningSkillTypes?.Clear();
			if (_deformationStatusCor != null)
			{
				_actor.StopLogicCoroutine(_deformationStatusCor);
			}
			_deformationStatusCor = null;
		}
	}
	public class ParallelScript : ParallelBase
	{
		protected static readonly int damageTag_LightMark = CommonHelper.StringToHash("115_LightTagDamage");

		private static readonly int damageTag_TriggerLightMark = CommonHelper.StringToHash("115_LightTag_Trigger");

		private const string areaEffectKey_LightMark = "AreaEffect_11501_LightTag_Boom";

		private const string tipsKey_TriggerMark = "LightMark_Trigger_Effect_02";

		protected List<int> _damageTag_TriggerLightMark;

		public override void OnEnable()
		{
			base.OnEnable();
			if (_damageTag_TriggerLightMark == null)
			{
				_damageTag_TriggerLightMark = new List<int>();
			}
			else
			{
				_damageTag_TriggerLightMark.Clear();
			}
			_damageTag_TriggerLightMark.Add(damageTag_TriggerLightMark);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from == _actor && adventureActorReceiveDamageBeforeHitEvent.to is MonsterAdventureActor)
			{
				OnBeforeSelfHit(adventureActorReceiveDamageBeforeHitEvent);
			}
		}

		protected virtual void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (!(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monster) || !(adventureActorReceiveDamageEvent.from is PlayerAdventureActor playerAdventureActor))
			{
				return;
			}
			OnPlayerDamaged(adventureActorReceiveDamageEvent);
			if (playerAdventureActor == _actor)
			{
				OnSelfDamaged(adventureActorReceiveDamageEvent);
				if (CheckCanTriggerLightMark(monster, adventureActorReceiveDamageEvent.hitDamageTag))
				{
					TriggerLightMark(monster, adventureActorReceiveDamageEvent.hitDamageTag);
				}
			}
		}

		private bool CheckCanTriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			if (monster == null || hitDamageTag == null)
			{
				return false;
			}
			if (_damageTag_TriggerLightMark == null || _damageTag_TriggerLightMark.Count <= 0)
			{
				return false;
			}
			if (CommonUtils.CheckElementMark(CommonDefine.Light, monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				for (int i = 0; i < _damageTag_TriggerLightMark.Count; i++)
				{
					int hitTag = _damageTag_TriggerLightMark[i];
					if (CommonUtils.CheckHitByTag(hitDamageTag, hitTag))
					{
						return true;
					}
				}
			}
			return false;
		}

		private void TriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			ILRuntimeAPI.PlayAreaEffect(_actor, GetLightMarkAreaEffectKey(), monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			monster.buffComponent?.RemoveBuffByTag(CommonDefine.Light);
			CommonUtils.TriggerElementMarkEvent(CommonDefine.Light, GameEnum.AdventureActorElementTriggerType.LightElementTriggerType1, _actor, monster, "LightMark_Trigger_Effect_02");
			int num = (int)(long)_actor.logicVariable.GetLogicTagValue("TriggerLightMarkTimes");
			num++;
			_actor.logicVariable.SetLogicTagValue("TriggerLightMarkTimes", num);
			OnTriggerLightMark(monster, hitDamageTag);
		}

		protected virtual string GetLightMarkAreaEffectKey()
		{
			return "AreaEffect_11501_LightTag_Boom";
		}

		protected virtual void OnTriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
		}

		protected virtual void OnPlayerDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		protected virtual void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
		}
	}
