	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private const string actionTag_OneStage_Timeline = "Ultra_TL";

		private const string actionTag_TwoStage_Timeline = "Ultra_TL_H6";

		private const string actionTag_AllStage_NoTimeline = "Ultra_NoTL_H6";

		private static readonly int damageTag_Trigger = CommonHelper.StringToHash("Ultra_Damage_H6");

		private const int additionalAttrId = 11598021;

		private const int maxAdditionalAttrCount = 10;

		private static readonly FP maxShootTime = 3;

		private static readonly FP addSearchRange = 4;

		private const int perkId_42 = 511542;

		private const string actionTag_OneStage_Timeline_P42 = "Ultra_TL_P42";

		private const string actionTag_AllStage_NoTimeline_P42 = "Ultra_NoTL_H6_P42";

		private PlayTimeline _playTimeline;

		private AimTarget _aimTarget;

		private bool _lockDirection;

		private bool _isLoopShootStage;

		private FP _shootLoopTime;

		private int _triggerLightMarkTimes_OnBegin;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt();
			if (_playTimeline == null)
			{
				_playTimeline = new PlayTimeline();
			}
			_lockDirection = false;
			_isLoopShootStage = false;
			_shootLoopTime = 0;
			_triggerLightMarkTimes_OnBegin = (int)(long)_actor.logicVariable.GetLogicTagValue("TriggerLightMarkTimes");
			_actor.actorSearchTargetInfo.AddSearchRange(addSearchRange, ActorSearchTarget.SearchType.allRange);
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = true;
			_actor.EnableInvincible();
			_actor.EnableSuperArmor();
			_actor.EnableImmuneControl();
			SearchTargetAndAim();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
		}

		public void OnStart()
		{
			_playTimeline.Play(_actor, PlayOneStageTimelineCombo, PlayOneStageNoTimelineCombo, 1, addPlayTime: false);
		}

		protected void PlayOneStageTimelineCombo()
		{
			string text = "Ultra_TL";
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out var _) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P42"))
			{
				text = "Ultra_TL_P42";
			}
			string actionTag = text;
			System.Action onComboLoop = OnOneStageLoopAfterTimeline;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
			_actor.ResumeAnimationGroup();
			_isLoopShootStage = true;
		}

		protected void PlayOneStageNoTimelineCombo()
		{
			string text = "Ultra_NoTL_H6";
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out var _) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P42"))
			{
				text = "Ultra_NoTL_H6_P42";
			}
			string actionTag = text;
			System.Action onComboLoop = OnOneStageLoopNoTimeline;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
			_actor.ResumeAnimationGroup();
			_isLoopShootStage = true;
		}

		protected void OnOneStageLoopNoTimeline()
		{
			if (_shootLoopTime >= maxShootTime)
			{
				_isLoopShootStage = false;
				SearchTargetAndAim();
				_lockDirection = true;
				base.comboAttack.CancelAttack();
			}
		}

		protected void OnOneStageLoopAfterTimeline()
		{
			if (_shootLoopTime >= maxShootTime)
			{
				_isLoopShootStage = false;
				SearchTargetAndAim();
				_lockDirection = true;
				_playTimeline.Play(_actor, PlayTwoStageCombo, PlayTwoStageCombo, 2);
			}
		}

		public void OnUpdate()
		{
			if (_isLoopShootStage)
			{
				_shootLoopTime += _actor.LogicDeltaTime;
			}
			if (!_lockDirection)
			{
				SearchTargetAndAim();
			}
		}

		protected void SearchTargetAndAim()
		{
			TSVector2 tSVector = _actor.tsTransform.Forward;
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				_actor.attackTarget = null;
				_actor.attackTarget = CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
				if (_actor.attackTarget != null)
				{
					tSVector = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				}
			}
			else
			{
				_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
				if (_actor.attackTarget != null)
				{
					tSVector = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				}
				else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput())
				{
					tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				}
			}
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			if (_actor.aimMode != AdventureActor.AimMode.LockDirection)
			{
				_aimTarget.Aim(_actor, null, tSVector);
			}
			else
			{
				_actor.tsTransform.Forward = tSVector;
			}
		}

		protected void PlayTwoStageCombo()
		{
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("Ultra_TL_H6", flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (!(adventureActorReceiveDamageBeforeHitEvent.from != _actor) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, damageTag_Trigger))
			{
				int num = (int)(long)_actor.logicVariable.GetLogicTagValue("TriggerLightMarkTimes") - _triggerLightMarkTimes_OnBegin;
				num = ((num <= 10) ? num : 10);
				if (num > 0)
				{
					AdventureActor.AddFromAttr(11598021, _actor, num);
				}
			}
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			_actor.DisableInvincible();
			_actor.DisableSuperArmor();
			_actor.DisableImmuneControl();
			_actor.actorSearchTargetInfo.AddSearchRange(-addSearchRange, ActorSearchTarget.SearchType.allRange);
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = false;
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			_lockDirection = false;
			_isLoopShootStage = false;
			_shootLoopTime = 0;
		}
	}
