		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			if ((_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				FP specialStatusTime = (_actor as PlayerAdventureActor).specialStatusTime;
				if (specialStatusTime > 0)
				{
					_actor.ReplaceAnimationGroup(1);
					base.DeformationStatusCor = _actor.StartLogicCoroutine(DeformationStatus(specialStatusTime), runImmediately: true);
				}
				else
				{
					(_actor as PlayerAdventureActor).status = ActorStatus.Default;
				}
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511509, out var perkLevel))
			{
				if (_perkLogicCor_P9 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P9);
				}
				_perkLogicCor_P9 = _actor.StartLogicCoroutine(PerkLogic_P9());
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511513, out perkLevel))
			{
				_playerSkillCd.SetSkillTotalSection(ActionKey.A, _playerSkillCd.GetSkillCD(ActionKey.A).originalTotalSectionAmount + 1);
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.A);
			}
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

