		{
			_runningSkillTypes.Add(SkillType.Skill);
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, base.OnSkillFinish))
			{
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511541, out var _) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P41"))
				{
					_actor.buffComponent?.AddBuff(11541011, _actor);
				}
				ForceStopDeformationStatusCor();
				base.DeformationStatusCor = _actor.StartLogicCoroutine(DeformationStatus(durationTime_Deformation), runImmediately: true);
			}
		}

		protected override void OnButtonDPress()
		{
			_runningSkillTypes.Add(SkillType.Ultra);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out var _))
			{
				_actor.logicVariable.ToggleLogicTag("CanTrigger_P42", base.InDeformationStatus);
			}
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, base.OnUltraSkillFinish))
			{
				ForceStopDeformationStatusCor();
			}
		}

		protected override bool CastIndependentRushSkill()
		{
			return ILRuntimeAPI.CreateSkill(base.InDeformationStatus ? 11571000 : _playerSkillCd.GetCurrentBindSkillId(ActionKey.C), _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: true, SkillCountdownTiming.Start, null, null, ingoreCDAndEnergy: false, isRushJoinDodge: false);
		}

		protected override void OnActorSkillFinish(SkillType skillType, bool success)
		{
			base.OnActorSkillFinish(skillType, success);
			if (skillType == SkillType.NormalAttack && success && base.InDeformationStatus)
			{
				_canUpdateTarget = true;
			}
		}

		protected override void OnDeformationBegin()
		{
			base.OnDeformationBegin();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511506, out var _))
			{
				if (_perkLogicCor_P6 != null)
				{
					_actor.StopLogicCoroutine(_perkLogicCor_P6);
				}
				_perkLogicCor_P6 = _actor.StartLogicCoroutine(PerkLogic_P6(), runImmediately: true);
			}
		}

		private IEnumerator DeformationStatus(FP durationTime)
		{
			OnDeformationBegin();
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintStart", _playerSkillCd.GetCurrentBindSkillId(ActionKey.B), durationTime_Deformation.AsFloat(), a3: true, durationTime.AsFloat());
			_canUpdateTarget = true;
			FP statusTime = durationTime;
			FP normalAttackCD = 0;
			while (true)
			{
				int perkLevel;
				if (_canUpdateTarget)
				{
					if (_actor.attackTarget != null && ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511501, out perkLevel) && _runningSkillTypes.Contains(SkillType.NormalAttack))
					{
						UpdateAttackTarget(forceUpdate: true);
						_canUpdateTarget = false;
					}
					else
					{
						UpdateAttackTarget();
					}
				}
				if (AimTarget() && _actor.DistanceWithRadius(_actor.attackTarget) <= CommonUtils.GetAttackRange(_actor))
				{
					if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511501, out perkLevel) && _actor.logicVariable.GetLogicTagToggle("CanTriggerPerk_P6"))
					{
						if (ILRuntimeAPI.CreateSkill(11511030, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
						{
							_actor.logicVariable.ToggleLogicTag("CanTriggerPerk_P6", value: false);
						}
					}
					else if (normalAttackCD <= 0)
					{
						_runningSkillTypes.Add(SkillType.NormalAttack);
						ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate(bool success)
						{
							OnNormalAttackFinish(success);
							if (success)
							{
								int num = (int)(long)_actor.logicVariable.GetLogicTagValue("SkillNormalAttackStage");
								normalAttackCD = GetNormalAttackCD(num);
								int num2 = ((num >= 4) ? 1 : (num + 1));
								_actor.logicVariable.SetLogicTagValue("SkillNormalAttackStage", num2);
							}
						});
					}
				}
				if (normalAttackCD > 0)
				{
					normalAttackCD -= _actor.LogicDeltaTime;
				}
				(_actor as PlayerAdventureActor).specialStatusTime = statusTime;
				statusTime -= _actor.LogicDeltaTime;
				if (!(statusTime > 0))
				{
					break;
				}
				yield return null;
			}
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _playerSkillCd.GetCurrentBindSkillId(ActionKey.B));
			OnDeformationFinish();
			while (!ILRuntimeAPI.CreateSkill(11531002, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false))
			{
				yield return null;
			}
			base.DeformationStatusCor = null;
		}

		protected override void ForceStopDeformationStatusCor()
		{
			base.ForceStopDeformationStatusCor();
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _playerSkillCd.GetCurrentBindSkillId(ActionKey.B));
		}

		private void OnReceiveCustomEvent(IEvent evt)
		{
			AdventureActorCustomEvent adventureActorCustomEvent = evt as AdventureActorCustomEvent;
			if (adventureActorCustomEvent.actor != _actor)
			{
				return;
			}
			if (adventureActorCustomEvent.eventHashCode == EventHash_Irradiation_UpdateTarget)
			{
				_canUpdateTarget = true;
			}
			else if (adventureActorCustomEvent.eventHashCode == EventHash_AfterFunnelFireHit && adventureActorCustomEvent.intParamList != null && adventureActorCustomEvent.intParamList.Count > 0)
			{
				switch ((AnimationSlotConfigComponent.SlotType)adventureActorCustomEvent.intParamList[0])
				{
				case AnimationSlotConfigComponent.SlotType.Extra_1:
					FunnelStrengthen_P9_1 = false;
					break;
				case AnimationSlotConfigComponent.SlotType.Extra_2:
					FunnelStrengthen_P9_2 = false;
					break;
				case AnimationSlotConfigComponent.SlotType.Extra_3:
					FunnelStrengthen_P9_3 = false;
					break;
				case AnimationSlotConfigComponent.SlotType.Extra_4:
					FunnelStrengthen_P9_4 = false;
					break;
				}
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511502, out var perkLevel) && _actor.buffComponent.GetBuffNumByID(11502011) >= 12 && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_P2))
			{
				AdventureActor.AddFromAttr(11502011, _actor);
			}
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511509, out perkLevel) || !CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_P9))
			{
				return;
			}
			foreach (KeyValuePair<AnimationSlotConfigComponent.SlotType, int> item in damageTagDic_Funnel)
			{
				AnimationSlotConfigComponent.SlotType key = item.Key;
				int value = item.Value;
				if (CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, value))
				{
					string tag = $"{key}_{511509}";
					if (_actor.logicVariable.GetLogicTagToggle(tag))
					{
						AdventureActor.AddFromAttr(11509001, _actor);
					}
				}
			}
		}

		protected override void OnDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnDamage(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511502, out var _) || !CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P2))
			{
				return;
			}
			if (_lastTargetId_P2 <= 0)
			{
				_lastTargetId_P2 = monsterAdventureActor.Id;
			}
			else
			{
				if (_actor.logicVariable.GetLogicTagToggle("CanTrigger_P2"))
				{
					return;
				}
				if (_lastTargetId_P2 == monsterAdventureActor.Id)
				{
					_actor.buffComponent.AddBuff(11502011, _actor);
					if (_actor.buffComponent.GetBuffNumByID(11502011) >= 12)
					{
						_actor.logicVariable.ToggleLogicTag("CanTrigger_P2", value: true);
						_actor.buffComponent.AddBuff(11502012, _actor);
						AdventureActorCustomEvent adventureActorCustomEvent = AdventureActorCustomEvent.Generate();
						adventureActorCustomEvent.sender = this;
						adventureActorCustomEvent.actor = _actor;
						adventureActorCustomEvent.eventHashCode = EventHash_Trigger_LaserStrengthen;
						_actor.DispatchEvent(adventureActorCustomEvent);
					}
				}
				else
				{
					_lastTargetId_P2 = monsterAdventureActor.Id;
					_actor.buffComponent.RemoveBuffByBuffId(11502011, 1);
				}
			}
		}

		protected override void OnDeformationFinish()
		{
			base.OnDeformationFinish();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511502, out var _))
			{
				_actor.buffComponent.RemoveBuffByBuffId(11502011);
				_actor.buffComponent.RemoveBuffByBuffId(11502012);
				_actor.logicVariable.ToggleLogicTag("CanTrigger_P2", value: false);
				_lastTargetId_P2 = 0L;
			}
			if (_perkLogicCor_P6 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P6);
			}
			_perkLogicCor_P6 = null;
		}

		private IEnumerator PerkLogic_P6()
		{
			_actor.logicVariable.ToggleLogicTag("CanTriggerPerk_P6", value: true);
			FP interval = triggerInterval_P6;
			while (true)
			{
				if (interval > 0)
				{
					if (!_actor.logicVariable.GetLogicTagToggle("CanTriggerPerk_P6"))
					{
						interval -= _actor.LogicDeltaTime;
					}
				}
				else
				{
					_actor.logicVariable.ToggleLogicTag("CanTriggerPerk_P6", value: true);
					interval += triggerInterval_P6;
				}
				yield return null;
			}
		}

		private IEnumerator PerkLogic_P9()
		{
			FP interval = triggerInterval_P9;
			while (true)
			{
				if (interval > 0)
				{
					interval -= _actor.LogicDeltaTime;
				}
				else
				{
					FunnelStrengthen_P9_1 = true;
					FunnelStrengthen_P9_2 = true;
					FunnelStrengthen_P9_3 = true;
					FunnelStrengthen_P9_4 = true;
					interval += triggerInterval_P9;
				}
				yield return null;
			}
		}

		protected override int GetDeformationNormalAttackId()
		{
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511501, out var _))
			{
				return 11511010;
			}
			return 11511000;
		}

		private void UpdateAttackTarget(bool forceUpdate = false)
		{
			if (forceUpdate)
			{
				_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			}
			else if (base.LockAttackTarget != null)
			{
				if (CommonUtils.CheckTargetIsValid(base.LockAttackTarget, base.LockAttackTargetId))
				{
					_actor.attackTarget = base.LockAttackTarget;
				}
				else
				{
					_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
					base.LockAttackTarget = null;
				}
			}
			else
			{
				_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			}
			bool num = base.InDeformationStatus && _runningSkillTypes.Contains(SkillType.NormalAttack);
			int perkLevel;
			bool flag = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511508, out perkLevel) && _runningSkillTypes.Contains(SkillType.Skill);
			if (num || flag)
			{
				base.LockAttackTarget = _actor.attackTarget;
			}
			else
			{
				base.LockAttackTarget = null;
			}
		}

		private bool AimTarget()
		{
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			int perkLevel;
			bool flag = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511508, out perkLevel) && _runningSkillTypes.Contains(SkillType.Skill);
			if (_actor.attackTarget == null || _actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill2))
			{
				if (flag)
				{
					_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
				}
				else if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget.Cancel();
				}
				return false;
			}
			if (_runningSkillTypes.Contains(SkillType.Dodge))
			{
				TSVector2 forward = _actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position;
				if (_actor.specialDodgeMode)
				{
					_aimTarget.Aim(_actor, null, forward.normalized, playStartAnim: true, null, null, 1);
					_actor.tsTransform.Forward = forward;
					return true;
				}
				if (flag)
				{
					_aimTarget.Aim(_actor, null, _actor.tsTransform.Forward);
					_actor.tsTransform.Forward = forward;
				}
				else if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget.Cancel();
				}
				return false;
			}
			TSVector2 forward2 = _actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position;
			_aimTarget.Aim(_actor, null, forward2.normalized, playStartAnim: true, null, null, 1);
			_actor.tsTransform.Forward = forward2;
			return true;
		}

		private FP GetNormalAttackCD(int stage)
		{
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511501, out var _))
			{
				return 0;
			}
			if (normalAttackCDDic_Deformation.TryGetValue(stage, out var value))
			{
				return value;
			}
			return 0;
		}

		private void Clear()
		{
			_lastTargetId_P2 = 0L;
			if (_perkLogicCor_P6 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P6);
			}
			_perkLogicCor_P6 = null;
			if (_perkLogicCor_P9 != null)
			{
				_actor.StopLogicCoroutine(_perkLogicCor_P9);
			}
			_perkLogicCor_P9 = null;
			FunnelStrengthen_P9_1 = false;
			FunnelStrengthen_P9_2 = false;
			FunnelStrengthen_P9_3 = false;
			FunnelStrengthen_P9_4 = false;
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
			MonoSingleton<LuaManager>.Instance?.FireEvent("SkillHintEnd", _playerSkillCd.GetCurrentBindSkillId(ActionKey.B));
			Clear();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private static readonly int damageTag_MainControl = CommonHelper.StringToHash("115_Main");

		private const int additionalAttrId_MainControl = 11593001;

		private const int perkId_3 = 511503;

		private static readonly int damageTag_P3 = CommonHelper.StringToHash("115_P06");

		private const int buffId_P3 = 11503011;

		private const string areaEffectKey_P3 = "AreaEffect_11501_Main_Skill_P06_Beam";

		private const int perkId_5 = 511505;

		private static readonly int damageTag_P5 = CommonHelper.StringToHash("115_P05");

		private const int buffId_P5 = 11505011;

		private const int perkId_7 = 511507;

		private static readonly FP triggerRadius_P7 = 8;

		private const int additionalAttrId_P7 = 11507001;

		private const int perkId_10 = 511510;

		private static readonly int damageTag_P10 = CommonHelper.StringToHash("115_B2_Cannon");

		private const int buffId_P10 = 11510011;

		private const int perkId_11 = 511511;

		private const string areaEffectKey_LightMark_P11 = "AreaEffect_11501_LightTag_Boom_H2";

		private const int additionalAttrId_P11 = 11511001;

		private const int perkId_12 = 511512;

		private static readonly int damageTag_TriggerLightMark_P12 = CommonHelper.StringToHash("115_P12");

		private const int buffId_P12 = 11512011;

		private const int perkId_13 = 511513;

		private const string areaEffectPath_P13 = "AreaEffect_11501_LimitDodge_Stun";

		private const int parameterId_13 = 11513011;

		private HashSet<long> _triggerSet_P10;

		private FP _lastTriggerTime_P13;

		public override void OnEnable()
		{
			base.OnEnable();
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511512, out var _))
			{
				_damageTag_TriggerLightMark?.Add(damageTag_TriggerLightMark_P12);
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_MainControl))
			{
				AdventureActor.AddFromAttr(11593001, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511507, out var perkLevel))
			{
				ILRuntimeAPI.SearchByRangeAndPosition(_actor, monsterAdventureActor.tsTransform.Position, triggerRadius_P7, delegate(List<LogicEntity> enemyList)
				{
					if (enemyList != null && enemyList.Count <= 1)
					{
						AdventureActor.AddFromAttr(11507001, _actor);
					}
				}, isConfront: true);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511511, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, ParallelScript.damageTag_LightMark))
			{
				AdventureActor.AddFromAttr(11511001, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monster = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511505, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P5))
			{
				_actor.buffComponent.AddBuff(11505011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511503, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P3) && !monster.buffComponent.CheckBuffByBuffID(11503011))
			{
				ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_11501_Main_Skill_P06_Beam", monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity areaEffect)
				{
					AreaEffect_FollowComponent areaEffectComponent = areaEffect.GetAreaEffectComponent<AreaEffect_FollowComponent>();
					if (areaEffectComponent != null)
					{
						areaEffectComponent.targetType = AreaEffect_FollowComponent.FollowTargetType.SpecifiedTarget;
						areaEffectComponent.FollowTarget = monster;
					}
				}, (AdventureActor)null);
				monster.buffComponent.AddBuff(11503011, _actor);
			}
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511510, out perkLevel) || !CommonUtils.CheckElementMark(CommonDefine.Light, monster) || !CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P10))
			{
				return;
			}
			if (_triggerSet_P10 == null)
			{
				_triggerSet_P10 = new HashSet<long>();
			}
			if (!_triggerSet_P10.Add(monster.Id))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent.AddBuff(11510011, _actor);
			}
		}

		protected override string GetLightMarkAreaEffectKey()
		{
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511511, out var _))
			{
				return "AreaEffect_11501_LightTag_Boom_H2";
			}
			return base.GetLightMarkAreaEffectKey();
		}

		protected override void OnTriggerLightMark(MonsterAdventureActor monster, IList<int> hitDamageTag)
		{
			base.OnTriggerLightMark(monster, hitDamageTag);
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511512, out var _) && hitDamageTag.Contains(damageTag_TriggerLightMark_P12))
			{
				_actor.buffComponent.AddBuff(11512011, _actor);
			}
		}

		private void OnCastSkill(IEvent evt)
		{
			if (!(evt is AdventureActorCastSkillEvent { sender: PlayerAdventureActor sender } adventureActorCastSkillEvent) || !(sender == _actor) || adventureActorCastSkillEvent.skillEventInfo.skillSlotType != GameEnum.skillSlotType.A || !ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511513, out var _))
			{
				return;
			}
			FP scriptValue = CommonUtils.GetScriptValue(_actor, 11513011);
			if (_lastTriggerTime_P13 <= 0 || _actor.LogicTime - _lastTriggerTime_P13 > scriptValue)
			{
				if (!string.IsNullOrEmpty("AreaEffect_11501_LimitDodge_Stun"))
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_11501_LimitDodge_Stun", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
				_lastTriggerTime_P13 = _actor.LogicTime;
			}
		}

		private void Clear()
		{
			_triggerSet_P10?.Clear();
			_lastTriggerTime_P13 = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL", OnCastSkill);
			Clear();
		}
	}
	public class SkillScript_FunnelFire_MainControl : SkillAdvancedBase
	{
		protected const string eventName_SingleShoot = "115_Main_Shoot";

		protected const string eventName_IrradiationShoot = "115_Main_Sustain_Shoot";

		protected const string eventName_SalvoShoot = "115_Main_Salvo_Shoot";

		private const string laserFx_Single = "fx_11501_bullet_B2_Attack_Cannon";

		private const string laserFx_Single_Strengthen = "fx_11501_bullet_B1P02_Cannon_Shoot_Strengthen";

		private const string laserFx_Single_Refraction = "fx_11501_bullet_B2_Attack_Cannon";

		private const string laserFx_Irradiation = "fx_11501_bullet_B2_Attack_Cannon_Sustain";

		private const string laserFx_Irradiation_Strengthen = "fx_11501_bullet_B2_Attack_Cannon_Sustain_Strengthen";

