		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_irradiationInterval = 0;
			_salvoShootIndex = 0;
			_strengthen = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511502, out var perkLevel) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P2");
			_refraction = ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511504, out perkLevel);
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = true;
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnReceiveCustomEvent);
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals(eventName, "115_Main_Shoot"))
			{
				int num = (int)(long)_actor.logicVariable.GetLogicTagValue("SkillNormalAttackStage");
				AnimationSlotConfigComponent.SlotType slotType = allSlotTypes[num - 1];
				SingleShoot(slotType);
			}
			else if (string.Equals(eventName, "115_Main_Sustain_Shoot"))
			{
				IrradiationShoot();
			}
			else if (string.Equals(eventName, "115_Main_Salvo_Shoot"))
			{
				OnBeginSalvoShoot();
			}
		}

		protected void SingleShoot(AnimationSlotConfigComponent.SlotType slotType)
		{
			if (_actor.attackTarget == null || slotType == AnimationSlotConfigComponent.SlotType.None)
			{
				return;
			}
			string text = (_strengthen ? "fx_11501_bullet_B1P02_Cannon_Shoot_Strengthen" : "fx_11501_bullet_B2_Attack_Cannon");
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511509, out var perkLevel))
			{
				string tag = $"{slotType}_{511509}";
				text = (_actor.logicVariable.GetLogicTagToggle(tag) ? "fx_11501_bullet_B1P02_Cannon_Shoot_Strengthen" : text);
			}
			GameObject gameObject = _actor.comboGroup.relatedResourceConfig?.GetFXByAlias(text);
			if (gameObject != null)
			{
				GameObject fxPrefab = gameObject;
				Vector3 position = _actor.transform.position;
				Quaternion identity = Quaternion.identity;
				UnityEngine.Transform selfSlot = GetSelfSlot(slotType);
				UnityEngine.Transform transform = _actor.attackTarget.transform;
				AdventureFXPlayer.PlayFX(fxPrefab, 1f, position, identity, 1f, selfSlot, default(Vector3), transform);
			}
			else
			{
				NovaLogger.Error("资源配置文件中未找到单发激光连线特效:" + text);
			}
			int num = hitDamageIdDic[slotType][0];
			ILRuntimeAPI.HitActor(_actor, _actor.attackTarget as AdventureActor, num, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
			if (_refraction)
			{
				FindRefractionTarget();
				string text2 = "fx_11501_bullet_B2_Attack_Cannon";
				if (CommonUtils.HavePersonalPerk(_actor.dataID, 511509, out perkLevel))
				{
					string tag2 = $"{slotType}_{511509}";
					text2 = (_actor.logicVariable.GetLogicTagToggle(tag2) ? "fx_11501_bullet_B1P02_Cannon_Shoot_Strengthen" : text2);
				}
				gameObject = _actor.comboGroup.relatedResourceConfig?.GetFXByAlias(text2);
				for (int i = 0; i < _refractionTargets.Count; i++)
				{
					UnityEngine.Transform slotNode = (_actor.attackTarget as AdventureActor).slotConfig.GetSlotNode(AnimationSlotConfigComponent.SlotType.Body);
					if (i > 0)
					{
						slotNode = _refractionTargets[i - 1].slotConfig.GetSlotNode(AnimationSlotConfigComponent.SlotType.Body);
					}
					AdventureActor adventureActor = _refractionTargets[i];
					if (gameObject != null)
					{
						GameObject fxPrefab2 = gameObject;
						Vector3 position2 = _actor.transform.position;
						Quaternion identity2 = Quaternion.identity;
						UnityEngine.Transform source = slotNode;
						UnityEngine.Transform transform = adventureActor.transform;
						AdventureFXPlayer.PlayFX(fxPrefab2, 1f, position2, identity2, 1f, source, default(Vector3), transform);
					}
					else
					{
						NovaLogger.Error("资源配置文件中未找到单发激光折射连线特效:fx_11501_bullet_B2_Attack_Cannon");
					}
					num = hitDamageIdDic[slotType][1];
					ILRuntimeAPI.HitActor(_actor, adventureActor, num, (string)null, (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.Small, 0, (GameObject)null);
				}
			}
			OnFunnelFire(slotType);
		}

		protected void IrradiationShoot()
		{
			StopIrradiation(dontPlaySubFX: true);
			if (_actor.attackTarget == null)
			{
				return;
			}
			if (_irradiationFxs == null)
