				_irradiationFxs = new List<AdventureFXPlayer>();
			}
			if (_refraction)
			{
				FindRefractionTarget();
			}
			GameObject gameObject = _actor.comboGroup.relatedResourceConfig?.GetFXByAlias("fx_11501_bullet_B2_Attack_Cannon_Sustain");
