	public class SkillScript_NormalAttack_Irradiation_MainControl : SkillScript_FunnelFire_MainControl
	{
		private const string actionTag = "Main_Cannon_P01_Sustain";

		private static readonly FP interruptDistance = 12;

		private static readonly FP checkDistanceInterval = 1;

		private const string stopLaserSoundEvent = "char_11501_skill_branch2_all_laser_stop";

		private const int perkId_6 = 511506;

		private long _attackTargetId;

		private FP _checkDistanceInterval;

		private bool _canSalvoShoot;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_attackTargetId = _actor.attackTarget.Id;
			_checkDistanceInterval = checkDistanceInterval;
			_canSalvoShoot = false;
		}

		public void OnStart()
		{
			Action<string> onCustomEvent = base.OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack("Main_Cannon_P01_Sustain", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		protected override void OnBeginSalvoShoot()
		{
			_canSalvoShoot = CommonUtils.HavePersonalPerk(_actor.dataID, 511506, out var _);
		}

		public void OnUpdate()
		{
			bool flag = false;
			if ((_actor as PlayerAdventureActor).status == ActorStatus.Special)
			{
				if (_actor.attackTarget == null)
				{
					flag = true;
				}
				else if (_actor.attackTarget.Id != _attackTargetId)
				{
					_checkDistanceInterval = checkDistanceInterval;
					ChangeIrradiationTarget();
					flag = false;
				}
				else if (_checkDistanceInterval > 0)
				{
					_checkDistanceInterval -= _actor.LogicDeltaTime;
				}
				else
				{
					_checkDistanceInterval = checkDistanceInterval;
					flag = _actor.DistanceWithRadius(_actor.attackTarget) > interruptDistance;
				}
			}
			else
			{
				flag = true;
			}
			if (_canSalvoShoot && !flag && _actor.logicVariable.GetLogicTagToggle("CanTriggerPerk_P6"))
			{
				_actor.logicVariable.ToggleLogicTag("CanTriggerPerk_P6", value: false);
				SalvoShoot();
			}
			if (flag)
			{
				InterruptIrradiation();
				base.comboAttack.CancelAttack();
			}
		}

		private void ChangeIrradiationTarget()
		{
			StopSalvoShoot();
			_attackTargetId = _actor.attackTarget.Id;
			OnCustomEvent("115_Main_Sustain_Shoot");
		}

		private void InterruptIrradiation()
		{
			StopSalvoShoot();
			StopIrradiation();
			MonoSingleton<WwiseAudioManager>.Instance?.PlaySound("char_11501_skill_branch2_all_laser_stop");
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			MonoSingleton<WwiseAudioManager>.Instance?.PlaySound("char_11501_skill_branch2_all_laser_stop");
			_attackTargetId = 0L;
			_checkDistanceInterval = 0;
			_canSalvoShoot = false;
		}
	}
