	public class ActionScript_Support : ActionScript
	{
		private enum TraceType
		{
			None,
			TraceWithTarget,
			TraceWithoutTarget,
			ForceTarce
		}

		private const int skillId_NormalAttack_Deformation = 11512000;

		private const int skillId_Deformation_Exit = 11532002;

		private static readonly FP addRange_Search = 2;

		private static readonly FP attackRange = 15;

		private static readonly FP durationTime_Deformation = 12;

		private static readonly Dictionary<int, FP> normalAttackCDDic_Deformation = new Dictionary<int, FP>
		{
			[1] = 0,
			[2] = 0,
			[3] = 0,
			[4] = 0
		};

		private static readonly FP distance_BeginTrace_WithTarget = 8;

		private static readonly FP distance_StopTrace_WithTarget = 5;

		private static readonly FP distance_BeginTrace_WithoutTarget = 4;

		private static readonly FP distance_StopTrace_WithoutTarget = 4;

		private static readonly FP distance_BeginForceTrace = 16;

		private static readonly FP distance_StopForceTrace = 4;

		private const int perkId_22 = 511522;

		private const int skillId_NormalAttack_Deformation_P22 = 11512220;

		private const int perkId_25 = 511525;

		private const int buffId_P25 = 11525011;

		private const string triggerFxKey_P25 = "fx_11501_base_B2P25_Blade_LightPiece";

		private const int perkId_28 = 511528;

		private static readonly int damageTag_P28 = CommonHelper.StringToHash("115_Support_Blade");

		private const int buffId_P28 = 11528011;

		private const int perkId_29 = 511529;

		private static readonly int damageTag_P29 = CommonHelper.StringToHash("115_Support_Blade");

		private const int buffId_P29 = 11529011;

		private const int perkId_32 = 511532;

		private const int parameterId_32 = 11532011;

		private static readonly FP CheckTraceInterval = 0.5;

		private FP _checkTraceInterval;

		private TraceType _traceType;

		private TraceTarget _traceTarget;

		private CoroutineNode _checkForceTraceCor;

		protected override void OnActionEnable()
		{
			base.OnActionEnable();
			_traceType = TraceType.None;
		}

		public override void OnStart()
		{
			base.OnStart();
			_actor.actorSearchTargetInfo.AddSearchRange(addRange_Search, ActorSearchTarget.SearchType.allRange);
		}

		protected override void OnCastSkill()
		{
			_runningSkillTypes.Add(SkillType.Skill);
			if (!ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, base.OnSkillFinish))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511525, out var perkLevel))
			{
				int buffNumByID = _actor.buffComponent.GetBuffNumByID(11525011);
				if (buffNumByID > 0)
				{
					CommonUtils.PlayOneOffFx(_actor, "fx_11501_base_B2P25_Blade_LightPiece");
					_actor.logicVariable.SetLogicTagValue("TriggerCount_P25", buffNumByID);
					_actor.buffComponent.RemoveBuffByBuffId(11525011);
				}
				else
				{
					_actor.logicVariable.SetLogicTagValue("TriggerCount_P25", 0);
				}
			}
			_actor.logicVariable.SetLogicTagValue("TriggerTimes_P27", 0);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511541, out perkLevel) && _actor.logicVariable.GetLogicTagToggle("CanTrigger_P41"))
			{
				_actor.buffComponent?.AddBuff(11541011, _actor);
			}
			ForceStopDeformationStatusCor();
			((PlayerAdventureActor)_actor).isResidentAssist = true;
			base.DeformationStatusCor = _actor.StartLogicCoroutine(DeformationStatus(), runImmediately: true);
		}

		protected override void OnCastUltimate()
		{
			_runningSkillTypes.Add(SkillType.Ultra);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511542, out var _))
			{
				_actor.logicVariable.ToggleLogicTag("CanTrigger_P42", base.InDeformationStatus);
			}
			if (ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, base.OnUltraSkillFinish))
			{
				((PlayerAdventureActor)_actor).isResidentAssist = false;
				ForceStopDeformationStatusCor();
			}
		}

		public override void OnUpdate()
		{
			if ((_actor as PlayerAdventureActor).status == ActorStatus.Default || !((PlayerAdventureActor)_actor).isResidentAssist)
			{
				_traceTarget?.CancelTrace();
			}
			else if (_actor.movementState == ActorState.StandBy)
			{
				if (_checkTraceInterval > 0)
				{
					_checkTraceInterval -= _actor.LogicDeltaTime;
					return;
				}
				TraceType traceType = CheckTraceType();
				if (traceType != TraceType.None)
				{
					BeginTrace(traceType);
				}
				_checkTraceInterval = CheckTraceInterval;
			}
			else
			{
				_checkTraceInterval = 0;
			}
		}

		private TraceType CheckTraceType()
		{
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			FP fP = _actor.DistanceWithRadius(activedPlayerActor);
			TraceType result = TraceType.None;
			if (fP > distance_BeginForceTrace)
			{
				result = TraceType.ForceTarce;
			}
			else if (_actor.attackTarget != null && fP > distance_BeginTrace_WithTarget)
			{
				result = TraceType.TraceWithTarget;
			}
			else if (_actor.attackTarget == null && fP > distance_BeginTrace_WithoutTarget)
			{
				result = TraceType.TraceWithoutTarget;
			}
			return result;
		}

		private void BeginTrace(TraceType traceType)
		{
			if (traceType == TraceType.None)
			{
				return;
			}
			if (_traceTarget == null)
			{
				_traceTarget = new TraceTarget();
			}
			else
			{
				_traceTarget.Clear();
			}
			FP stopDistance = 0;
			switch (traceType)
			{
			case TraceType.TraceWithTarget:
				stopDistance = distance_StopTrace_WithTarget;
				break;
			case TraceType.TraceWithoutTarget:
				stopDistance = distance_StopTrace_WithoutTarget;
				break;
			case TraceType.ForceTarce:
				stopDistance = distance_StopForceTrace;
				break;
			}
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			_traceTarget.BeginTrace(_actor, activedPlayerActor, stopDistance, -1, -1, null, null, NavAgentTypeNames.NavigationUpdateQualityLevel.MedQualityNavigationUpdate, AdventureActor.MovementMode.Run, OnTraceFinish);
			_traceType = traceType;
			if (_traceType != TraceType.ForceTarce)
			{
				if (_checkForceTraceCor != null)
				{
					_actor.StopLogicCoroutine(_checkForceTraceCor);
				}
				_checkForceTraceCor = _actor.StartLogicCoroutine(CheckEnterForceTrace());
			}
		}

		private IEnumerator CheckEnterForceTrace()
		{
			FP checkTraceInterval = CheckTraceInterval;
			while (true)
			{
				if (_checkTraceInterval > 0)
				{
					checkTraceInterval -= _actor.LogicDeltaTime;
				}
				else
				{
					LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
					if (_actor.DistanceWithRadius(activedPlayerActor) > distance_BeginForceTrace)
					{
						break;
					}
				}
				yield return null;
			}
			_checkForceTraceCor = null;
			BeginTrace(TraceType.ForceTarce);
		}

		private void OnTraceFinish()
		{
			_traceType = TraceType.None;
			if (_checkForceTraceCor != null)
			{
				_actor.StopLogicCoroutine(_checkForceTraceCor);
			}
			_checkForceTraceCor = null;
		}

		protected override void OnActorSkillFinish(SkillType skillType, bool success)
		{
			base.OnActorSkillFinish(skillType, success);
			if ((uint)(skillType - 2) <= 1u && success)
			{
				(_actor as PlayerAdventureActor).isAssistAIFinish = true;
			}
		}

		private IEnumerator DeformationStatus()
		{
			OnDeformationBegin();
			FP statusTime = durationTime_Deformation;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511532, out var _))
			{
				statusTime += CommonUtils.GetScriptValue(_actor, 11532011);
			}
			FP normalAttackCD = 0;
			while (true)
			{
				_actor.attackTarget = null;
				_actor.attackTarget = CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
				if (_traceType != TraceType.ForceTarce)
				{
					if (_actor.attackTarget != null)
					{
						if (_aimTarget == null)
						{
							_aimTarget = new AimTarget();
						}
						TSVector2 normalized = (_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
						if (_actor.aimMode != AdventureActor.AimMode.LockDirection)
						{
							_aimTarget.Aim(_actor, null, normalized, playStartAnim: true, null, null, 0);
						}
						else
						{
							_actor.tsTransform.Forward = normalized;
						}
						if (_actor.DistanceWithRadius(_actor.attackTarget) <= attackRange)
						{
							_runningSkillTypes.Add(SkillType.NormalAttack);
							ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate(bool success)
							{
								OnNormalAttackFinish(success);
								if (success)
								{
									int num = (int)(long)_actor.logicVariable.GetLogicTagValue("SkillNormalAttackStage");
									normalAttackCD = GetNormalAttackCD(num);
									int num2 = ((num >= 4) ? 1 : (num + 1));
									_actor.logicVariable.SetLogicTagValue("SkillNormalAttackStage", num2);
								}
							});
						}
					}
					else
					{
						_aimTarget?.Cancel();
					}
				}
				else
				{
					_aimTarget?.Cancel();
				}
				if (normalAttackCD > 0)
				{
					normalAttackCD -= _actor.LogicDeltaTime;
				}
				(_actor as PlayerAdventureActor).specialStatusTime = statusTime;
				statusTime -= _actor.LogicDeltaTime;
				if (!(statusTime > 0))
				{
					break;
				}
				yield return null;
			}
			OnDeformationFinish();
			while (!ILRuntimeAPI.CreateSkill(11532002, _actor, SkillPhaseFeatureFlag.CertainSkillId, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, OnExitSkillFinish))
			{
				yield return null;
			}
			base.DeformationStatusCor = null;
		}

		private void OnExitSkillFinish(bool success)
		{
			if (success)
			{
				((PlayerAdventureActor)_actor).isResidentAssist = false;
			}
		}

		protected override int GetDeformationNormalAttackId()
		{
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511522, out var _))
			{
				return 11512220;
			}
			return 11512000;
		}

		private FP GetNormalAttackCD(int stage)
		{
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511522, out var _))
			{
				return 0;
			}
			if (normalAttackCDDic_Deformation.TryGetValue(stage, out var value))
			{
				return value;
			}
			return 0;
		}

		protected override void OnDeformationBegin()
		{
			base.OnDeformationBegin();
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511528, out var _))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent?.RemoveBuffByBuffId(11528011);
			}
		}

		protected override void OnDeformationFinish()
		{
			base.OnDeformationFinish();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511529, out var _))
			{
				_actor.buffComponent?.RemoveBuffByBuffId(11529011);
			}
		}

		protected override void OnDamage(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnDamage(damageEvent);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511529, out var _) && base.InDeformationStatus && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P29))
			{
				_actor.buffComponent?.AddBuff(11529011, _actor);
			}
		}

		protected override void OnSelfKillTarget(AdventureActorDiedEvent diedEvent)
		{
			base.OnSelfKillTarget(diedEvent);
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511528, out var _) || diedEvent.damageTag == null || !CommonUtils.CheckHitByTag(diedEvent.damageTag, damageTag_P28))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent?.AddBuff(11528011, _actor);
			}
		}

		public override void OnStop()
		{
			base.OnStop();
			_actor.actorSearchTargetInfo.AddSearchRange(-addRange_Search, ActorSearchTarget.SearchType.allRange);
			Clear();
		}

		private void Clear()
		{
			(_actor as PlayerAdventureActor).status = ActorStatus.Default;
			(_actor as PlayerAdventureActor).specialStatusTime = 0;
			_traceTarget?.Clear();
			_traceType = TraceType.None;
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
		}

		protected override void OnActionDisable()
		{
			base.OnActionDisable();
			_actor.actorSearchTargetInfo.ResetSearchRange(ActorSearchTarget.SearchType.allRange);
		}
	}
