				{
					actorL.buffComponent?.AddBuff(11533011, _actor);
				}
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("FIREFLY_SKILL_SHOOT", OnReceiveShootEvent);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
		}

		private void OnReceiveShootEvent(IEvent evt)
		{
			FireflySkillShootEvent fireflySkillShootEvent = evt as FireflySkillShootEvent;
			_actor.StartLogicCoroutine(Shoot(fireflySkillShootEvent.bulletKey, fireflySkillShootEvent.bulletIndex, fireflySkillShootEvent.target), runImmediately: true);
		}

		private IEnumerator Shoot(string bulletKey, int bulletIndex, AdventureActor target)
		{
			if (target == null)
			{
				yield break;
			}
			TSVector2 position = target.tsTransform.Position;
			long targetId = target.Id;
			FP delay = bulletShootDelay;
			while (delay > 0)
			{
				if (CommonUtils.CheckTargetIsValid(target, targetId))
				{
					position = target.tsTransform.Position;
				}
				delay -= _actor.LogicDeltaTime;
				yield return null;
			}
			AdventureBulletBase adventureBulletBase = ILRuntimeAPI.Shoot(bulletKey, _actor, default(FP), position, default(FP), position, null, AimType.Position, BulletDirectionType.BulletToTarget);
			if (bulletTagDic.TryGetValue(bulletIndex, out var value) && adventureBulletBase != null)
			{
				adventureBulletBase.AddSubTag(value);
			}
		}

		private void OnBulletFinish(IEvent evt)
		{
			AdventureBulletFinishEvent adventureBulletFinishEvent = evt as AdventureBulletFinishEvent;
			if (!(adventureBulletFinishEvent.owner == _actor))
			{
				return;
			}
			AdventureBulletBase adventureBulletBase = adventureBulletFinishEvent.sender as AdventureBulletBase;
			if (!(adventureBulletBase != null))
			{
				return;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511523, out var perkLevel))
			{
				if (adventureBulletBase.CheckBulletTag(bulletTag_Support))
				{
					_actor.StartLogicCoroutine(PerkLogic_P23("Bullet_11501_Support_Skill_Blade_P23_Back", adventureBulletFinishEvent.bulletPosition));
				}
				else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511521, out perkLevel) && adventureBulletBase.CheckBulletTag(bulletTag_Support_P21))
				{
					_actor.StartLogicCoroutine(PerkLogic_P23("Bullet_11501_Support_Skill_Blade_P23_Back_Strengthen", adventureBulletFinishEvent.bulletPosition));
				}
			}
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511527, out perkLevel) || (!adventureBulletBase.CheckBulletTag(bulletTag_Support) && !adventureBulletBase.CheckBulletTag(bulletTag_Support_P21)))
			{
				return;
			}
			int num = _actor.logicVariable.GetLogicTagValue("TriggerTimes_P27").AsInt();
			if (num < 4)
			{
				if (adventureBulletBase.CheckBulletTag(bulletTag_Support))
				{
					_actor.StartLogicCoroutine(PerkLogic_P27("AreaEffect_11501_Support_Skill_Blade_P24_Ground", adventureBulletFinishEvent.bulletPosition));
				}
				else if (CommonUtils.HavePersonalPerk(_actor.dataID, 511521, out perkLevel) && adventureBulletBase.CheckBulletTag(bulletTag_Support_P21))
				{
					_actor.StartLogicCoroutine(PerkLogic_P27("AreaEffect_11501_Support_Skill_Blade_P24_StrengthenGround", adventureBulletFinishEvent.bulletPosition));
				}
				_actor.logicVariable.SetLogicTagValue("TriggerTimes_P27", num + 1);
			}
		}

		private IEnumerator PerkLogic_P23(string bulletKey, TSVector2 shootPosition)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(shootDelay_P23));
			LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
			AdventureActor actor = _actor;
			FP positionY = shootPositionY_P23;
			LogicEntity target = activedPlayerActor;
			AdventureBulletBase bullet = ILRuntimeAPI.Shoot(bulletKey, actor, default(FP), shootPosition, positionY, default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
			if (bullet == null)
			{
				yield break;
			}
			while (true)
			{
				if (bullet.target == null || bullet.target.IsDead())
				{
					bullet.Finish(cancel: true);
					yield break;
				}
				if (!(bullet.DistanceWithRadius(bullet.target) > 0))
				{
					break;
				}
				yield return null;
			}
			if (bullet.target is PlayerAdventureActor playerAdventureActor)
			{
				PlayFX playFX = new PlayFX();
				playFX.Play(_actor, null, "fx_11501_base_Support_Skill_Blade_P23_Back_Strengthen", default(FP), playerAdventureActor.tsTransform.Position, default(TSVector2));
				playFX.fxInstance.Bind(playerAdventureActor.gameObject, playerAdventureActor.gameObject);
				playerAdventureActor.buffComponent.AddBuff(11523011, _actor);
			}
			bullet.Finish(cancel: true);
		}

		private IEnumerator PerkLogic_P27(string areaEffectKey, TSVector2 position)
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(generateDelay_P27));
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffectKey, position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
		}

		public void OnUpdate()
		{
			ActorState = _actor.state;
		}

		private void OnElementMarkTrigger(IEvent evt)
		{
			if (evt is AdventureElementMarkTriggerEvent adventureElementMarkTriggerEvent && CommonUtils.HavePersonalPerk(_actor.dataID, 511525, out var _) && adventureElementMarkTriggerEvent.elementType == GameEnum.elementType.LE)
			{
				_actor.buffComponent?.AddBuff(11525011, _actor);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor monsterAdventureActor = beforeHitEvent.to as MonsterAdventureActor;
			if (CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_Support))
			{
				AdventureActor.AddFromAttr(11595001, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511522, out var perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_Trigger_P22))
			{
				AdventureActor.AddFromAttr(11522011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511525, out perkLevel))
			{
				int num = (int)(long)_actor.logicVariable.GetLogicTagValue("TriggerCount_P25");
				if (num > 0)
				{
					AdventureActor.AddFromAttr(11525001, _actor, num);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511526, out perkLevel))
			{
				int buffNumByID = monsterAdventureActor.buffComponent.GetBuffNumByID(11526011);
				if (buffNumByID > 0)
				{
					AdventureActor.AddFromAttr(11526001, _actor, buffNumByID);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511532, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_P32))
			{
				AdventureActor.AddFromAttr(11532001, _actor);
			}
		}

		protected override void OnPlayerDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnPlayerDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (!(damageEvent.from == SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor) || !CommonUtils.HavePersonalPerk(_actor.dataID, 511524, out var _) || !monsterAdventureActor.buffComponent.CheckBuffByBuffID(11524011))
			{
				return;
			}
			if (_lastTriggerTime_P24 == null)
			{
				_lastTriggerTime_P24 = new Dictionary<long, FP>();
			}
			if (_lastTriggerTime_P24.TryGetValue(monsterAdventureActor.Id, out var value))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 11524011);
				if (_actor.LogicTime - value > scriptValue)
				{
					ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 115322401, "fx_11501_hit_2", "fx_11501_Base_Support_Skill_Blade_P24_Blade", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.None, 0, (GameObject)null);
					_lastTriggerTime_P24[monsterAdventureActor.Id] = _actor.LogicTime;
				}
			}
			else
			{
				ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 115322401, "fx_11501_hit_2", "fx_11501_Base_Support_Skill_Blade_P24_Blade", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, (FP)(-1), HitBox.HurtAnimType.None, 0, (GameObject)null);
				_lastTriggerTime_P24.Add(monsterAdventureActor.Id, _actor.LogicTime);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			MonsterAdventureActor monsterAdventureActor = damageEvent.to as MonsterAdventureActor;
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511524, out var perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P24) && _buffCount_P24 < 3)
			{
				monsterAdventureActor.buffComponent?.AddBuff(11524011, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511526, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P26))
			{
				monsterAdventureActor.buffComponent?.AddBuff(11526011, _actor);
			}
			if (CommonUtils.HavePersonalPerk(_actor.dataID, 511531, out perkLevel) && CommonUtils.CheckHitByTag(damageEvent.hitDamageTag, damageTag_P31))
			{
				monsterAdventureActor.buffComponent?.AddBuff(3011, _actor);
				_actor.buffComponent?.AddBuff(11531011, _actor);
			}
		}

		private void OnGetBuff(IEvent evt)
		{
			if (evt is AdventureActorGetBuff adventureActorGetBuff && adventureActorGetBuff.from == _actor && adventureActorGetBuff.eventInfo != null && adventureActorGetBuff.eventInfo.buffId == 11524011)
			{
				_buffCount_P24++;
			}
		}

		private void OnRemoveBuff(IEvent evt)
		{
			if (evt is AdventureActorRemoveBuff adventureActorRemoveBuff && adventureActorRemoveBuff.froms.Count > 0 && adventureActorRemoveBuff.froms.Contains(_actor) && adventureActorRemoveBuff.eventInfo != null && adventureActorRemoveBuff.eventInfo.buffId == 11524011 && _buffCount_P24 > 0)
			{
				_buffCount_P24--;
			}
		}

		private void OnSelfEnter()
		{
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511533, out var _))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent?.AddBuff(11533012, _actor);
			}
		}

		private void OnSelfExit()
		{
			if (!ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511533, out var _))
			{
				return;
			}
			foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
			{
				actorL.buffComponent?.RemoveBuffByBuffId(11533012);
			}
		}

		private void Clear()
		{
			_actorState = ActorState.Null;
			_buffCount_P24 = 0;
			_lastTriggerTime_P24?.Clear();
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("FIREFLY_SKILL_SHOOT", OnReceiveShootEvent);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("BULLET_FINISH", OnBulletFinish);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ELEMENT_MARK_TRIGGER", OnElementMarkTrigger);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_GET_BUFF", OnGetBuff);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_REMOVE_BUFF", OnRemoveBuff);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511533, out var _))
			{
				foreach (PlayerAdventureActor actorL in SceneSingleton<AdventurePlayerController>.Instance.ActorLs)
				{
					actorL.buffComponent?.RemoveBuffByBuffId(11533011);
				}
			}
			Clear();
		}
	}
	public class SkillScript_FunnelFire_Support : SkillAdvancedBase
	{
		private static readonly Dictionary<int, string> bulletKeyDic = new Dictionary<int, string>
		{
			[1] = "Bullet_11501_Support_Skill_Blade_1_Up_Right",
			[2] = "Bullet_11501_Support_Skill_Blade_2_Up_Left",
			[3] = "Bullet_11501_Support_Skill_Blade_3_Down_Right",
			[4] = "Bullet_11501_Support_Skill_Blade_4_Down_Left"
		};

		private const string shootEventName = "BladeShoot";

		private const int perkId_21 = 511521;

		private static readonly Dictionary<int, string> bulletKeyDic_P1 = new Dictionary<int, string>
		{
			[1] = "Bullet_11501_Support_Skill_Blade_1_Up_Right_Strengthen",
			[2] = "Bullet_11501_Support_Skill_Blade_2_Up_Left_Strengthen",
			[3] = "Bullet_11501_Support_Skill_Blade_3_Down_Right_Strengthen",
			[4] = "Bullet_11501_Support_Skill_Blade_4_Down_Left_Strengthen"
		};

		private int _bulletIndex;

		private bool _reinforced;

		protected int BulletIndex
		{
			get
			{
				return _bulletIndex;
			}
			set
			{
				if (_bulletIndex != value)
				{
					_bulletIndex = value;
					if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 511521, out var _))
					{
						_reinforced = true;
					}
					else
					{
						_reinforced = false;
					}
				}
			}
		}

		protected bool ReinForced => _reinforced;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_actor.isChangeAimLockedTargetWhenCurrentAttackTargetInValid = true;
		}

		public void OnUpdate()
		{
			if (_actor.attackTarget == null)
			{
				base.comboAttack?.InterruptAttack();
			}
			else if ((_actor as PlayerAdventureActor).status != ActorStatus.Special)
			{
				base.comboAttack?.CancelAttack();
			}
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals("BladeShoot", eventName))
			{
				Shoot();
			}
		}

		protected virtual void Shoot()
		{
			if (!(_actor.attackTarget == null))
			{
				FireflySkillShootEvent fireflySkillShootEvent = FireflySkillShootEvent.Generate();
				fireflySkillShootEvent.sender = _actor;
				fireflySkillShootEvent.bulletKey = GetBulletKey();
				fireflySkillShootEvent.bulletIndex = BulletIndex;
				fireflySkillShootEvent.target = _actor.attackTarget as AdventureActor;
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(fireflySkillShootEvent);
			}
		}

		private string GetBulletKey()
		{
