			{
				LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor, useInputDirection: false, activeActorTargetFirst: true);
				if (assistantAttackTarget != null)
				{
					_actor.LookAt(assistantAttackTarget.tsTransform.Position, 0f);
				}
				System.Action onComboFinish = OnRushFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack("Support_Blade_Exit_P30_Rush", flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
