			{
				string actionTag = GetActionTag();
				System.Action onInterrupt = OnFinish;
				System.Action onComboFinish = OnInterrupt;
				BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onInterrupt, onComboFinish);
				_actor.ResumeAnimationGroup();
