		public void TriggerFireMark(MonsterAdventureActor monster, GameEnum.skillSlotType skillSlotType)
		{
			if (!CommonUtils.CheckTriggerElementMarkCD(_actor, monster))
			{
				return;
			}
			if (skillSlotType == GameEnum.skillSlotType.D)
			{
				monster.buffComponent.RemoveBuffByTag(CommonDefine.Fire);
				ILRuntimeAPI.PlayAreaEffect(_actor, fireAreaEffect, monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity aoe)
				{
					aoe.ModifyTag(UltraAreaTag);
				}, (AdventureActor)null);
			}
			else
			{
				monster.buffComponent.RemoveBuffByTag(CommonDefine.Fire);
				ILRuntimeAPI.PlayAreaEffect(_actor, fireAreaEffect, monster.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity aoe)
				{
					aoe.ModifyTag(SkillAreaTag);
				}, (AdventureActor)null);
			}
			CommonUtils.TriggerElementMarkEvent(CommonDefine.Fire, GameEnum.AdventureActorElementTriggerType.None, _actor, monster, "FireMark_Trigger_Effect_01");
		}

		public bool CheckCd(int perkId, FP Cd)
		{
			if (Cd <= 0)
			{
				return true;
			}
			bool result = false;
			if (perkCd.TryGetValue(perkId, out var value))
			{
				if (_actor.LogicTime - value > Cd)
				{
					result = true;
					perkCd[perkId] = _actor.LogicTime;
				}
			}
			else
			{
				perkCd.Add(perkId, _actor.LogicTime);
				result = true;
			}
			return result;
		}

		public bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
