	public class ReflectWeapon
	{
		public long uid;

		public int weaponType;

		public string firBullet;

		public int reflectCount;

		public int extraCount;

		public string sedBullet_1;

		public FP reboundRange;

		public string sedBullet_2;

		public FP scale_2;

		public TSVector2 Position;

		public FP PositionY;

		public AdventureActor owner;

		public Action<ReflectWeapon> OnFinish;

		private LogicEntity _atkTarget;

		public long targetId;

		private CoroutineNode corMain;

		private Dictionary<long, int> shootCache = new Dictionary<long, int>();

		private FP curScale;

		public bool isFinished;

		private LogicEntity atkTarget
		{
			get
			{
				if (_atkTarget == null)
				{
					return null;
				}
				if (_atkTarget is AdventureActor adventureActor)
				{
					if (!adventureActor.isSneak && !adventureActor.isPenetrate && adventureActor.actorHealthInfo.isAlive)
					{
						return _atkTarget;
					}
					return null;
				}
				return null;
			}
			set
			{
				_atkTarget = value;
			}
		}

		public void Shoot(LogicEntity target, TSVector2 shootPosXZ, FP shootPosY = default(FP))
		{
			curScale = 0;
			isFinished = false;
			extraCount = 0;
			_atkTarget = target;
			targetId = target.Id;
			corMain = owner.StartLogicCoroutine(OnMainLogic(shootPosXZ, shootPosY));
		}

		public void AddExtraCount(int count)
		{
			extraCount += count;
		}

		private IEnumerator OnMainLogic(TSVector2 shootPosXZ, FP shootPosY)
		{
			TSVector2 lastPos = atkTarget.tsTransform.Position;
			if (weaponType != 2)
			{
				string bulletAlias = firBullet;
				AdventureActor actor = owner;
				LogicEntity target = atkTarget;
				AdventureBulletBase bullet = ILRuntimeAPI.Shoot(bulletAlias, actor, default(FP), shootPosXZ, shootPosY, default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				while (!bullet.isFinished)
				{
					Position = bullet.tsTransform.Position;
					PositionY = bullet.tsTransform.PositionY;
					yield return null;
				}
			}
			for (int i = 0; i < reflectCount + extraCount; i++)
			{
				LogicEntity logicEntity = ((weaponType == 2) ? atkTarget : GetReboundTarget(lastPos));
				if (logicEntity == null)
				{
					break;
				}
				string bulletAlias2 = ((weaponType == 2) ? sedBullet_2 : sedBullet_1);
				AdventureActor actor2 = owner;
				TSVector2 position = lastPos;
				LogicEntity target = logicEntity;
				AdventureBulletBase bullet = ILRuntimeAPI.Shoot(bulletAlias2, actor2, default(FP), position, shootPosY, default(TSVector2), target, AimType.Target, BulletDirectionType.BulletToTarget);
				bullet.tagUid = uid;
				if (weaponType == 2)
				{
					curScale += scale_2;
					if (curScale > 0)
					{
						(bullet as AdventureVerticalProjectile).ChangeTrailFxSize(curScale.AsFloat());
					}
				}
				lastPos = logicEntity.tsTransform.Position;
				while (!bullet.isFinished)
				{
					Position = bullet.tsTransform.Position;
					PositionY = bullet.tsTransform.PositionY;
					yield return null;
				}
			}
			Finish();
		}

		private LogicEntity GetReboundTarget(TSVector2 center)
		{
			List<LogicEntity> list = ILRuntimeAPI.SearchByRangeAndPosition(owner, center, reboundRange, null, isConfront: true, onlyAlive: true, includeSelf: false, (LogicEntity entity) => entity.tsTransform.Position != center);
			if (list.Count > 0)
			{
				return list[TSRandom.Range(0, list.Count)];
			}
			return null;
		}

		private void ShuffleList<T>(List<T> list)
		{
			for (int num = list.Count - 1; num > 0; num--)
			{
				int index = TSRandom.instance.Next(0, num);
				T value = list[index];
				list[index] = list[num];
				list[num] = value;
			}
		}

		public void Finish()
		{
			OnFinish?.Invoke(this);
			isFinished = true;
			shootCache.Clear();
			owner.StopLogicCoroutine(corMain);
			corMain = null;
			owner = null;
			atkTarget = null;
			OnFinish = null;
		}
	}
