			SkillScript_Support skillScript_Support = this;
			string actionTag = ((index == 1) ? key_1_first : key_1);
			System.Action onInterrupt = SkillFinishOrInterrupt;
			RequestComboAttack req = skillScript_Support.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onInterrupt, null, null, fadeOutAnim: true);
			if (!back)
			{
				_actor.movementFSM.EnableRootMotionForceDir(finalDir);
				while (!req.isRecoveryBegin)
				{
					lookAtTarget.BeginLookAt(_actor, target, 0, rotationSpeed, null);
					yield return null;
				}
				_actor.movementFSM.DisableRootMotionForceDir();
			}
			else
			{
				while (!req.isRecoveryBegin)
				{
					yield return null;
				}
			}
			_actor.ResumeMovementAgent();
			SkillScript_Support skillScript_Support2 = this;
			string actionTag2 = key_2;
			onInterrupt = SkillFinishOrInterrupt;
			req = skillScript_Support2.BeginAttack(actionTag2, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: true, target, null, default(TSVector2), null, null, null, onInterrupt, null, null, fadeOutAnim: true);
			while (!req.isRecoveryBegin)
			{
				yield return null;
			}
		}
	}
	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private const string actionKey1 = "Ultra_TL";

		private const string actionKey2 = "Ultra_NoTL";

		private const string bulletPath = "fx_11401_bullet_fire_ultra_super";

		private const string fxPath = "";

		private const string starFxPath = "fx_11401_loop_skillmax_fazhen";

		private const string endFxPath = "fx_11401_base_skillmax_fazhen_end";

		private readonly FP shootInterval = 0.033;

		private readonly FP shootTime = 6;

		private readonly FP endTime = 6;

		private readonly FP speed = 8f;

		private readonly FP beginShoot = 0.25;

		private readonly FP srcInnerRadius = 0.7;

		private readonly FP srcOuterRadius = 0.9;

		private readonly FP desInnerRadius = 0;

		private readonly FP desOuterRadius = 4;

		private const float offsetNearClip = -2f;

		private const float offsetNearClip2 = 0.1f;

		private const float fxScale = 1f;

		private const int moveAare = 20;

		private readonly FP radius = 15;

		private FP delayTime = 1.3;

		private string area_main = "AreaEffect_114_Ultra_H6_MainControl";

		private string area_support = "AreaEffect_114_Ultra_H6";

		private FP area_time = 4;

		private CoroutineNode corMain;

		private CoroutineNode corShoot;

		private CoroutineNode corFollow;

		private TrueSyncTransform objActor;

		private PlayTimeline _playTimeline = new PlayTimeline();

		private TSVector2 center = new TSVector2(Screen.width / 2, Screen.height / 2);

		private PlayFX playFX = new PlayFX();

		private PlayFX playStartFX = new PlayFX();

		private PlayFX playEndFX = new PlayFX();

		private AdventureCustomCameraControlHandler adventureCustomCameraControlHandler;

		private List<AdventureFXPlayer> adventureFXPlayerList = new List<AdventureFXPlayer>();

		private string actionKey;

		private bool outControll;

		private bool isAssist;

		private TSVector2 lastTargetPos;

		private LogicEntity target;

		private AreaEffectEntity areaEffectEntity;

		private long areaEffectId;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			isAssist = (_actor as PlayerAdventureActor).isAssist;
			if (isAssist)
			{
				outControll = true;
			}
			else
			{
				outControll = false;
			}
			_actor.EnableInvincible();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: false);
			_playTimeline.Play(_actor, delegate
			{
				actionKey = "Ultra_TL";
				MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: true);
				StartCoroutine(ref corMain, DoMainLogic(hasTimeline: true));
			}, delegate
			{
				actionKey = "Ultra_NoTL";
				MonoSingleton<LuaManager>.Instance.FireEvent("UICloseEvent", a1: true);
				StartCoroutine(ref corMain, DoMainLogic(hasTimeline: false));
			});
		}

		public void OnStop()
		{
			Clear();
		}

		public void OnUpdate()
		{
			DoUpdateLogic();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
			StopCoroutine(ref corShoot);
			StopCoroutine(ref corFollow);
			CoroutineManager.CancelCoroutine(StartVisualFollow());
			ExitControl();
			_actor.DisableInvincible();
		}

		private IEnumerator DoMainLogic(bool hasTimeline)
		{
			SkillScript_Ultra skillScript_Ultra = this;
			string actionTag = actionKey;
			System.Action onComboFinish = OnFinishOrInterrupt;
			System.Action onInterrupt = OnFinishOrInterrupt;
			RequestComboAttack req = skillScript_Ultra.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
			if (!hasTimeline)
			{
				while (!req.isAnticipationEnd)
				{
					yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(delayTime));
				}
			}
			target = SeachTarget();
			if (!outControll)
			{
				EnterControl();
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(beginShoot));
			StartCoroutine(ref corShoot, Shoot());
			FP totleTime_st = endTime;
			if (GetPerkLv(ParallelScript.perkId_st, out var _))
			{
				totleTime_st = ParallelScript.totleTime_st;
			}
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(totleTime_st));
			StopCoroutine(ref corShoot);
			if (!outControll)
			{
				playEndFX.Play(_actor, "fx_11401_base_skillmax_fazhen_end", 1f, adventureCustomCameraControlHandler.vitrualCm, Vector3.zero, Vector3.zero);
			}
			playStartFX.Stop();
			_actor.CancelAttack();
		}

		private void EnterControl()
		{
			ModuleController<AdventureModuleController>.Instance.ActivePlayerCameraTrigger("UltraVmTiriggger_Gizmo");
			adventureCustomCameraControlHandler = ModuleController<AdventureModuleController>.Instance.CurCameraTriggerGizmo.CustomCameraControlHandlers[0];
			UnityEngine.Transform vmPlayer = adventureCustomCameraControlHandler.vmPlayer;
			objActor = vmPlayer.GetComponent<TrueSyncTransform>();
			objActor.Init();
			objActor.transformSyncEnabled = true;
			bool raycastHit;
			if (target != null)
			{
				objActor.Position = target.tsTransform.Position;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
			else
			{
				LogicEntity activedPlayerActor = SceneSingleton<AdventurePlayerController>.Instance.activedPlayerActor;
				objActor.Position = activedPlayerActor.tsTransform.Position;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
			playStartFX.Play(_actor, _skill, "fx_11401_loop_skillmax_fazhen", 0, TSVector2.zero, _actor.tsTransform.Forward);
		}

		private void ExitControl()
		{
			if (outControll)
			{
				return;
			}
			foreach (AdventureFXPlayer adventureFXPlayer in adventureFXPlayerList)
			{
				if (adventureFXPlayer.isPlaying)
				{
					adventureFXPlayer.Stop();
				}
			}
			playStartFX.Stop();
			playEndFX.Stop();
			ILRuntimeAPI.StopAreaEffect(areaEffectId);
			ModuleController<AdventureModuleController>.Instance.DeactivePlayerCameraTrigger("UltraVmTiriggger_Gizmo");
		}

		private IEnumerator Shoot()
		{
			adventureFXPlayerList.Clear();
			FP escapeTime = 0;
			lastTargetPos = TSVector2.zero;
			FP totleShootTime = shootTime;
			if (GetPerkLv(ParallelScript.perkId_st, out var _))
			{
				totleShootTime = ParallelScript.totleTime_st;
			}
			for (; escapeTime < totleShootTime; escapeTime += shootInterval)
			{
				_ = Vector3.zero;
				_ = TSVector2.zero;
				Vector3 position;
				TSVector2 targetPosition;
				if (!outControll)
				{
					TSVector2 tSVector = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
					while (tSVector.y > Screen.height || tSVector.y < 0)
					{
						tSVector = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
					}
					position = new Vector3((float)tSVector.x, (float)tSVector.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + -2f);
					Vector3 position2 = new Vector3((float)tSVector.x, (float)tSVector.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + 0.1f);
					position = MonoSingleton<GameCameraStackManager>.Instance.mainCamera.ScreenToWorldPointAsHFOV(position);
					position2 = MonoSingleton<GameCameraStackManager>.Instance.mainCamera.ScreenToWorldPointAsHFOV(position2);
					if (!string.IsNullOrEmpty(""))
					{
						AdventureFXPlayer adventureFXPlayer = playFX.Play(_actor, "", 1f, position2, Quaternion.identity, adventureCustomCameraControlHandler.vitrualCm);
						if ((bool)adventureFXPlayer)
						{
							adventureFXPlayerList.Add(adventureFXPlayer);
						}
					}
					targetPosition = TrueSyncExtensions.RandomPointInsideRing(objActor.Position, desInnerRadius, desOuterRadius);
					lastTargetPos = objActor.Position;
				}
				else
				{
					TSVector2 tSVector2 = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
					while (tSVector2.y > Screen.height || tSVector2.y < 0)
					{
						tSVector2 = TrueSyncExtensions.RandomPointInsideRing(center, Screen.width / 2 * srcInnerRadius, Screen.width / 2 * srcOuterRadius);
					}
					position = UnityEngine.Rendering.Universal.CameraExtensions.ScreenToWorldPointAsHFOV(position: new Vector3((float)tSVector2.x, (float)tSVector2.y, MonoSingleton<GameCameraStackManager>.Instance.mainCamera.nearClipPlane + -2f), camera: MonoSingleton<GameCameraStackManager>.Instance.mainCamera);
					if (lastTargetPos == TSVector2.zero)
					{
						lastTargetPos = ((target != null) ? target.tsTransform.Position : _actor.tsTransform.Position);
					}
					targetPosition = TrueSyncExtensions.RandomPointInsideRing(lastTargetPos, desInnerRadius, desOuterRadius);
				}
				ILRuntimeAPI.Shoot(position: new TSVector2(position.x, position.z), bulletAlias: "fx_11401_bullet_fire_ultra_super", actor: _actor, range: 0, positionY: position.y, targetPosition: targetPosition, target: null, aimType: AimType.Position, bulletDirectionType: BulletDirectionType.BulletToTarget);
				yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(shootInterval));
			}
		}

		private void DoUpdateLogic()
		{
			TSVector2 direction = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (!(direction != TSVector2.zero) || !objActor)
			{
				return;
			}
			FP logicDeltaTime = _actor.LogicDeltaTime;
			TSVector2 tSVector = new TSVector2(direction.x * speed * logicDeltaTime, direction.y * speed * logicDeltaTime);
			TSVector2 tSVector2 = objActor.Position + tSVector;
			if (TSVector2.Distance(_actor.tsTransform.Position, tSVector2) > 20)
			{
				return;
			}
			bool raycastHit;
			if (!_actor.LinecastNavmeshGraph(objActor.Position, tSVector2, out var _))
			{
				objActor.Position += tSVector;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
				return;
			}
			TSVector2 origin = objActor.Position;
			TSVector2 linecastHitPoint2;
			if (SceneSingleton<DeterministicCollisionManager>.Instance.RoughRaycast(ref origin, ref direction, 1, 4096))
			{
				objActor.Position += tSVector;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
			else if (!_actor.LinecastNavmeshGraph(objActor.Position + direction * 1, tSVector2 + direction * 1, out linecastHitPoint2))
			{
				objActor.Position += tSVector;
				objActor.PositionY = CommonHelper.GetTerrainHeight(objActor.Position.ToVector2(), objActor.PositionY.AsFloat(), out raycastHit);
			}
		}

		private IEnumerator StartVisualFollow()
		{
			while (true)
			{
				areaEffectEntity.SyncFx();
				yield return null;
			}
		}

		private IEnumerator StartLogicFollow()
		{
			while (true)
			{
				areaEffectEntity.tsTransform.Position = objActor.Position;
				yield return null;
			}
		}

		private void OnFinishOrInterrupt()
		{
			_skill?.Clear();
		}

		private LogicEntity SeachTarget()
		{
			if (_actor.attackTarget != null)
			{
				return _actor.attackTarget;
			}
			return CommonUtils.SearchNearTargetByCircle(_actor, radius);
		}

		public bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
	public class Skill_Admission : SkillAdvancedBase
	{
		private const ComboInputBuffer.ActionKey _actionKey = ComboInputBuffer.ActionKey.H;

		private readonly FP backDistance = 6;

		private FP dashSpeed = 30;

		private readonly FP duration = 0.3;

		private readonly FP distance = 0.01;

		private CoroutineNode corMain;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			StartCoroutine(ref corMain, DoMainLogic());
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			StopCoroutine(ref corMain);
		}

		private IEnumerator DoMainLogic()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(0f));
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (duration > 0f && distance > 0f)
			{
				_actor.Dodge(tSVector, distance, duration, null, null, comboWithAttack: true);
			}
			BeginAttack(ComboInputBuffer.ActionKey.H, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, delegate
			{
				_skill?.Clear();
			}, delegate
			{
				_skill?.Clear();
			});
		}

		private bool SearchValidPoint(ref TSVector2 desPos)
		{
			desPos = _actor.tsTransform.Position - backDistance * _actor.tsTransform.Forward;
			if (_actor.QueryPositionReachable(desPos))
			{
				return true;
			}
			return false;
		}
	}
}
namespace AIScript.Character._11301
{
	public class ActionBehaviour : ActorActionBase
	{
		private enum AIState
		{
			None,
			Normal,
			Special
		}

		private FP normalAtkBreakTime = 1;

		private int evt_strong = CommonHelper.StringToHash("StrongAtk");

		protected PlayerSkillCd _skillManage;

		private ActorSearchTarget actorSearchInfo;

		private IState curState;

		private readonly IdleState_1 idleState_1 = new IdleState_1();

		private readonly IdleState_2 idleState_2 = new IdleState_2();

		private readonly AimState aimState = new AimState();

		private readonly NormalAttackState normalAttackState = new NormalAttackState();

		private SkillState skillState;

		private readonly AimTarget _aimTarget = new AimTarget();

		private AIState curAIState = AIState.Normal;

		private AIState lastAIState = AIState.Normal;

		private FP lastNormalTime;

		private int curNormalPhase;

		private int normalPhaseCount = 3;

		protected override void OnActionEnable()
		{
			_skillManage = _actor.GetLogicComponent<PlayerSkillCd>();
			actorSearchInfo = _actor.GetLogicComponent<ActorSearchTarget>();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastEndSkill);
			_actor.AddEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			idleState_1.Init(_actor, _skillManage, _aimTarget);
			idleState_2.Init(_actor, _skillManage, _aimTarget);
			aimState.Init(_actor, _skillManage, _aimTarget);
			normalAttackState.Init(_actor, _skillManage, _aimTarget);
			curNormalPhase = 0;
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_CASTSKILL_END", OnCastEndSkill);
			_actor.RemoveEventListener("ACTOR_CUSTOM_EVENT", OnCustomEvent);
			Clear();
		}

		public override void OnStart()
		{
			base.OnStart();
			DoMainLogic();
		}

		public void OnUpdate()
		{
			MainLoop();
		}

		public override void OnStop()
		{
			base.OnStop();
			Clear();
		}

		private void Clear()
		{
			_aimTarget.Cancel();
			_actor.movementMode = AdventureActor.MovementMode.Run;
		}

		protected override void OnButtonAPress()
		{
			CastSkill(ActionKey.A, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonAClickOrCancel()
		{
		}

		protected override void OnButtonBPress()
		{
			CastSkill(ActionKey.B, SkillPhaseFeatureFlag.Skill1);
			_actor.logicVariable.ToggleLogicTag("HoldingKeyD", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable?.ToggleLogicTag("HoldingKeyD", value: false);
		}

		protected override bool CastIndependentRushSkill()
		{
			return CastSkill(ActionKey.C, SkillPhaseFeatureFlag.Skill2, 0, isInterruptAttack: true, isRushJoinDodge: false);
		}

		protected override void OnButtonDPress()
		{
			CastSkill(ActionKey.D, SkillPhaseFeatureFlag.Ultimate);
		}

		private void OnTrCastSkill(IEvent _evt)
		{
			ActorTryCastSkill actorTryCastSkill = _evt as ActorTryCastSkill;
			if (actorTryCastSkill.sender as AdventureActor == _actor)
			{
				CastSkill(ActionKey.None, actorTryCastSkill.flag, actorTryCastSkill.skillId, actorTryCastSkill.isInterruptAttack);
			}
		}

		private void OnCastEndSkill(IEvent evt)
		{
			AdventureActorCastSkillEndEvent adventureActorCastSkillEndEvent = evt as AdventureActorCastSkillEndEvent;
			if (_actor != null && adventureActorCastSkillEndEvent.sender as AdventureActor == _actor && adventureActorCastSkillEndEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.NORMAL)
			{
				lastNormalTime = _actor.LogicTime;
			}
		}

		private void OnCustomEvent(IEvent evt)
		{
			if (evt is AdventureActorCustomEvent adventureActorCustomEvent)
			{
				_ = adventureActorCustomEvent.eventHashCode;
				_ = evt_strong;
			}
		}

		private bool CastSkill(ActionKey key, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int skillId = 0, bool isInterruptAttack = true, bool isRushJoinDodge = true)
		{
			skillState = new SkillState();
			skillState.Init(_actor, _skillManage, _aimTarget);
			skillState.actionKey = key;
			skillState.specialSkill = skillId;
			skillState.skillPhaseFeatureFlag = skillPhaseFeatureFlag;
			skillState.isInterruptAttack = isInterruptAttack;
			skillState.isRushJoinDodge = isRushJoinDodge;
			skillState.Enter();
			if (skillState.CanCast)
			{
				curState.Exit();
				curState = skillState;
			}
			return skillState.CanCast;
		}

		private void DoMainLogic()
		{
			if (curState == null)
			{
				if (_actor.logicVariable.GetLogicTagToggle("switch_state"))
				{
					curState = idleState_2;
				}
				else
				{
					curState = idleState_1;
				}
				curState.Enter();
			}
		}

		private void MainLoop()
		{
			_actor.attackTarget = actorSearchInfo.GetLockingConfrontActor(useInputDirection: true);
			if (curState.IsEnd)
			{
				curState = GetNextState();
				curState.Enter();
			}
			else
			{
				curState.Update();
			}
		}

		private IState GetNextState()
		{
			if (curAIState == AIState.Normal)
			{
				return GetNextState_Normal();
			}
			return GetNextState_Special();
		}

		private bool CheckSwitchState()
		{
			curAIState = ((!_actor.logicVariable.GetLogicTagToggle("switch_state")) ? AIState.Normal : AIState.Special);
			bool result = lastAIState != curAIState;
			lastAIState = curAIState;
			return result;
		}

		private void ResetNormalPharse()
		{
			curNormalPhase = 0;
		}

		private IState GetNextState_Normal()
		{
			if (_actor.attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
				bool isObstacleBetweenActorAndTargetAndPreventNormalAttack = base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack;
				if (CommonUtils.GetAttackRange(_actor) > fP && !isObstacleBetweenActorAndTargetAndPreventNormalAttack)
				{
					if (_actor.LogicTime - lastNormalTime > normalAtkBreakTime)
					{
						ResetNormalPharse();
					}
					curNormalPhase = curNormalPhase % normalPhaseCount + 1;
					_actor.logicVariable.SetLogicTagValue("curNormalPhase", curNormalPhase);
					lastNormalTime = _actor.LogicTime;
					return normalAttackState;
				}
			}
			return idleState_1;
		}

		private IState GetNextState_Special()
		{
			if (_actor.attackTarget != null)
			{
				if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget && !(_actor as PlayerAdventureActor).dodgeButtonHold)
				{
					return aimState;
				}
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
					if (CommonUtils.GetAttackRange(_actor) > fP)
					{
						return normalAttackState;
					}
				}
			}
			return idleState_2;
		}
	}
	public enum fsmStatus
	{
		Enter,
		Exit
	}
	public class IState
	{
		private fsmStatus fsmStatus;

		public AdventureActor _actor;

		public PlayerSkillCd _skillManage;

		public AimTarget _aimTarget;

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public void Init(AdventureActor actor, PlayerSkillCd skillManager, AimTarget aimTarget)
		{
			_actor = actor;
			_skillManage = skillManager;
			_aimTarget = aimTarget;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
		}
	}
