		public virtual void OnCastEndSkill(AdventureActorCastSkillEndEvent evt)
		{
			if (CheckTalentLevel(3) && evt.skillEventInfo.skillSlotType == GameEnum.skillSlotType.D)
			{
				_actor.buffComponent.RemoveBuffByBuffId(buffId_F3);
			}
