		private IEnumerator CastArea()
		{
			FP timer = 0;
			FP playerTimer = 0;
			ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_10, _actor.tsTransform.Position, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
			while (timer < time_10)
			{
				if (playerTimer >= interval_10)
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, areaEffect_10, _actor.tsTransform.Position, _actor.tsTransform.Rotation, (Action<AreaEffectEntity>)null, (AdventureActor)null);
					playerTimer = 0;
				}
				yield return null;
				timer += _actor.LogicDeltaTime;
				playerTimer += _actor.LogicDeltaTime;
			}
		}
