			System.Action onAnticipationEnd = OnAnticipationEnd;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, null, onInterrupt, onCustomEvent, null, fadeOutAnim: false, onComboLoop);
		}

		protected void OnAnticipationEnd()
		{
		}

		protected void OnComboLoop()
		{
			currentLoop_count++;
			if (currentLoop_count >= loopCount)
			{
				base.comboAttack.CancelAttack();
			}
		}

		protected virtual void OnRecoveryBegin()
		{
			string actionTag = GetActionTag(2);
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			System.Action onAnticipationEnd = OnStepTwoBegin;
