			if (!(adventureActorCastSkillEvent.sender as PlayerAdventureActor != _actor) && adventureActorCastSkillEvent.skillEventInfo.skillSlotType == GameEnum.skillSlotType.A && comboStep == 3 && !_actor.logicVariable.GetLogicTagToggle("DogeSkill"))
