			System.Action onInterrupt = OnInterrupt;
			System.Action onComboFinish = OnFinish;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt, onCustomEvent, onActivationEnd);
			_actor.logicVariable.ToggleLogicTag("DogeSkill", value: false);
		}

		protected void OnAnticipationEnd()
		{
			if (skillPerk2 && comboStep != 2 && comboStep != 4)
			{
				_actor.logicVariable.ToggleLogicTag("DogeSkill", value: true);
			}
			else
			{
				OnStepTwoBegin();
			}
		}

		protected virtual void OnActivationEnd()
		{
			if (!skillPerk2 || comboStep == 2 || comboStep == 4)
			{
				ReBindSkill();
				_actor.logicVariable.ToggleLogicTag("DogeSkill", value: false);
				return;
			}
			string actionTag = GetActionTag();
			System.Action onComboFinish = OnFinish_Two;
			System.Action onInterrupt = OnInterrupt;
			System.Action onAnticipationEnd = OnStepTwoBegin;
			Action<string> onCustomEvent = OnCustomEvent;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt, onCustomEvent);
			_actor.logicVariable.ToggleLogicTag("DogeSkill", value: false);
		}

		protected void OnStepTwoBegin()
		{
			ReBindSkill();
			_actor.logicVariable.ToggleLogicTag("DogeSkill", value: false);
		}

		protected override void OnCustomEvent(string eventName)
		{
			base.OnCustomEvent(eventName);
			if (eventName.Equals(event_start_inv))
			{
				_actor.EnableInvincible();
				_actor.movAgent.canBlock = false;
			}
			else if (eventName.Equals(event_end_inv))
			{
				_actor.DisableInvincible();
				_actor.movAgent.canBlock = true;
			}
		}

		protected virtual void OnFinish()
		{
			if (!skillPerk2 || (comboStep != 1 && comboStep != 3))
			{
				OnFinish_Two();
			}
		}

		protected virtual void OnFinish_Two()
		{
			_skill.Clear();
		}

		protected virtual void OnInterrupt()
		{
			ReBindSkill();
			_skill.Clear();
		}

		private void ReBindSkill()
		{
			if (beRebind)
			{
				return;
			}
			beRebind = true;
			bool flag = skillPerk1;
			if (flag)
			{
				flag = ((!skillPerk2) ? (comboStep == 1 || comboStep == 3) : (comboStep == 2 || comboStep == 4));
			}
			if (flag)
			{
				if (_skill.skillId == Parallel.skillId_StageOne)
				{
					_skillManager.BindSkillIdToButton(ActionKey.B, Parallel.skillId_StageTwo);
					_actor.logicVariable.ToggleLogicTag("BeginReset", value: true);
					ModuleController<AdventureModuleController>.Instance?.SetLevelLogicValue("112BeginReset", value: true);
				}
				else
				{
					_skillManager.BindSkillIdToButton(ActionKey.B, Parallel.skillId_StageOne);
				}
			}
		}

		public void OnUpdate()
		{
			if (_skill.skillId == Parallel.skillId_StageOne)
			{
				LockDirection();
			}
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_actor.movementFSM.runtimeIgonreRootMotion = true;
			}
			else
			{
				_actor.movementFSM.runtimeIgonreRootMotion = false;
			}
		}
	}
}
namespace AIScript.Character._11101
{
	public class ActionBehaviour : ActorActionBase
	{
		private PlayerSkillCd _skillManage;

		private ActorSearchTarget actorSearchInfo;

		private IState curState;

		private NormalAttackState normalAttackState = new NormalAttackState();

		private SkillState skillState;

		private AimTarget _aimTarget = new AimTarget();

		protected override void OnActionEnable()
		{
			_skillManage = _actor.GetLogicComponent<PlayerSkillCd>();
			actorSearchInfo = _actor.GetLogicComponent<ActorSearchTarget>();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			normalAttackState.Init(_actor, _skillManage, _aimTarget);
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			Clear();
		}

		public override void OnStart()
		{
			base.OnStart();
			DoMainLogic();
		}

		public void OnUpdate()
		{
			MainLoop();
		}

		public override void OnStop()
		{
			base.OnStop();
			Clear();
		}

		private void Clear()
		{
			_aimTarget.Cancel();
			_actor.movementMode = AdventureActor.MovementMode.Run;
			curState?.Exit();
			curState = null;
		}

		protected override void OnButtonAPress()
		{
			CastSkill(ActionKey.A, SkillPhaseFeatureFlag.Dodge);
		}

		protected override void OnButtonBPress()
		{
			CastSkill(ActionKey.B, SkillPhaseFeatureFlag.Skill1);
			_actor.logicVariable.ToggleLogicTag("HoldingKeyD", value: true);
		}

		protected override void OnButtonBCancel()
		{
			_actor.logicVariable?.ToggleLogicTag("HoldingKeyD", value: false);
		}

		protected override bool CastIndependentRushSkill()
		{
			return CastSkill(ActionKey.C, SkillPhaseFeatureFlag.Skill2, 0, isInterruptAttack: true, isRushJoinDodge: false);
		}

		protected override void OnButtonDPress()
		{
			CastSkill(ActionKey.D, SkillPhaseFeatureFlag.Ultimate);
		}

		private void OnTrCastSkill(IEvent _evt)
		{
			ActorTryCastSkill actorTryCastSkill = _evt as ActorTryCastSkill;
			if (actorTryCastSkill.sender as AdventureActor == _actor)
			{
				CastSkill(ActionKey.None, actorTryCastSkill.flag, actorTryCastSkill.skillId, actorTryCastSkill.isInterruptAttack);
			}
		}

		private bool CastSkill(ActionKey key, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int skillId = 0, bool isInterruptAttack = true, bool isRushJoinDodge = true)
		{
			skillState = new SkillState();
			skillState.Init(_actor, _skillManage, _aimTarget);
			skillState.actionKey = key;
			skillState.specialSkill = skillId;
			skillState.skillPhaseFeatureFlag = skillPhaseFeatureFlag;
			skillState.isInterruptAttack = isInterruptAttack;
			skillState.isRushJoinDodge = isRushJoinDodge;
			skillState.Enter();
			if (skillState.CanCast)
			{
				curState?.Exit();
				curState = skillState;
			}
			return skillState.CanCast;
		}

		private void DoMainLogic()
		{
		}

		private void MainLoop()
		{
			_actor.attackTarget = actorSearchInfo.GetLockingConfrontActor(useInputDirection: true);
			if (curState == null || curState.IsEnd)
			{
				curState = GetNextState();
				curState?.Enter();
			}
			else
			{
				curState.Update();
			}
		}

		private IState GetNextState()
		{
			if (_actor.attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
				bool isObstacleBetweenActorAndTargetAndPreventNormalAttack = base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack;
				bool flag = fP <= CommonUtils.GetAimRange(_actor);
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
				{
					if (isObstacleBetweenActorAndTargetAndPreventNormalAttack || !flag)
					{
						_aimTarget.Cancel();
					}
				}
				else if (flag && !(_actor as PlayerAdventureActor).dodgeButtonHold && !isObstacleBetweenActorAndTargetAndPreventNormalAttack)
				{
					_aimTarget.Aim(_actor, _actor.attackTarget as AdventureActor);
				}
				if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && CommonUtils.GetAttackRange(_actor) > fP)
				{
					return normalAttackState;
				}
			}
			else if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
			{
				_aimTarget.Cancel();
			}
			return null;
		}
	}
	public class Action_Support : ActorActionBase
	{
		private FP contineTime = 5;

		private bool inAI;

		private FP timer;

		private IState curState;

		private MoveState moveState = new MoveState();

		private SkillState skillState;

		private NormalAttackState normalAttackState = new NormalAttackState();

		private PlayerSkillCd skillMgr;

		private AimTarget aimTarget = new AimTarget();

		private LogicEntity attackTarget;

		protected override void OnActionEnable()
		{
			skillMgr = _actor.GetLogicComponent<PlayerSkillCd>();
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			ModuleController<AdventureModuleController>.Instance.AddEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
			moveState.Init(_actor, skillMgr, aimTarget);
			normalAttackState.Init(_actor, skillMgr, aimTarget);
		}

		protected override void OnActionDisable()
		{
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_TRY_CAST_SKILL", OnTrCastSkill);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
			aimTarget.Cancel();
			_actor.movementMode = AdventureActor.MovementMode.Run;
		}

		public override void OnStart()
		{
			base.OnStart();
			inAI = false;
			timer = 0;
		}

		public override void OnStop()
		{
			base.OnStop();
			_actor.InterruptAttack(force: true);
			curState?.Exit();
			curState = null;
			inAI = false;
			timer = 0;
		}

		public void OnUpdate()
		{
			MainLoop();
		}

		private void OnTrCastSkill(IEvent _evt)
		{
			ActorTryCastSkill actorTryCastSkill = _evt as ActorTryCastSkill;
			if (actorTryCastSkill.sender as AdventureActor == _actor)
			{
				CastSkill(ActionKey.None, actorTryCastSkill.flag, actorTryCastSkill.skillId, actorTryCastSkill.isInterruptAttack);
			}
		}

		private void CastSkill(ActionKey key, SkillPhaseFeatureFlag skillPhaseFeatureFlag, int skillId = 0, bool isInterruptAttack = true)
		{
			skillState = new SkillState();
			skillState.Init(_actor, skillMgr, aimTarget);
			skillState.actionKey = key;
			skillState.specialSkill = skillId;
			skillState.skillPhaseFeatureFlag = skillPhaseFeatureFlag;
			skillState.isInterruptAttack = isInterruptAttack;
			skillState.Enter();
			if (skillState.CanCast)
			{
				curState?.Exit();
				curState = skillState;
			}
		}

		private void MainLoop()
		{
			attackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			if (inAI)
			{
				if (curState == null || curState.IsEnd)
				{
					curState = GetNextState();
					curState?.Enter();
				}
				else
				{
					curState.Update();
				}
			}
		}

		private IState GetNextState()
		{
			if (attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(attackTarget);
				if (_actor.actorSearchTargetInfo.visionAttackRange > fP)
				{
					bool isObstacleBetweenActorAndTargetAndPreventNormalAttack = base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack;
					bool flag = fP <= CommonUtils.GetAimRange(_actor);
					if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
					{
						if (isObstacleBetweenActorAndTargetAndPreventNormalAttack || !flag)
						{
							aimTarget.Cancel();
						}
					}
					else if (flag && !(_actor as PlayerAdventureActor).dodgeButtonHold && !isObstacleBetweenActorAndTargetAndPreventNormalAttack)
					{
						aimTarget.Aim(_actor, _actor.attackTarget as AdventureActor);
					}
					return normalAttackState;
				}
				return moveState;
			}
			if (_actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget)
			{
				aimTarget.Cancel();
			}
			return null;
		}

		protected override void OnCastUltimate()
		{
			base.OnCastUltimate();
		}

		private void OnAreaEffectFinish(IEvent evt)
		{
			AdventureAreaEffectFinishEvent adventureAreaEffectFinishEvent = evt as AdventureAreaEffectFinishEvent;
			if (_actor != null && adventureAreaEffectFinishEvent.owner.Id == _actor.Id)
			{
				AreaEffectEntity areaEffect = ILRuntimeAPI.GetAreaEffect(adventureAreaEffectFinishEvent.entityID);
				if (areaEffect != null && areaEffect.CheckTag(ParallelScript.areaTag_A))
				{
					inAI = false;
					(_actor as PlayerAdventureActor).isAssistAIFinish = true;
				}
			}
		}
	}
	public enum fsmStatus
	{
		Enter,
		Exit
	}
	public class IState
	{
		private fsmStatus fsmStatus;

		public AdventureActor _actor;

		public PlayerSkillCd _skillManage;

		public AimTarget _aimTarget;

		public bool IsEnd => fsmStatus == fsmStatus.Exit;

		public void Init(AdventureActor actor, PlayerSkillCd skillManager, AimTarget aimTarget)
		{
			_actor = actor;
			_skillManage = skillManager;
			_aimTarget = aimTarget;
		}

		public virtual void Enter()
		{
			fsmStatus = fsmStatus.Enter;
		}

		public virtual void Update()
		{
		}

		public virtual void Exit()
		{
			fsmStatus = fsmStatus.Exit;
		}

		public LogicEntity GetAttackTarget()
		{
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				return CommonUtils.GetAssistantAttackTarget(_actor);
			}
			return _actor.attackTarget;
		}
	}
	public class NormalAttackState : IState
	{
		private FP meleeAttackDistance = 0.2;

		private int skillId = 11110002;

		private FP skillCd = 3;

		public override void Enter()
		{
			base.Enter();
			if (!ILRuntimeAPI.CreateSkill(_skillManage.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false, SkillCountdownTiming.Start, delegate
			{
				Exit();
			}))
			{
				Exit();
			}
		}

		public override void Update()
		{
			base.Update();
			LogicEntity attackTarget = GetAttackTarget();
			if (attackTarget != null)
			{
				if (_actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
				{
					_actor.InterruptAttack(force: true);
				}
				FP fP = _actor.DistanceWithRadius(attackTarget);
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("lastTime");
				if (meleeAttackDistance > fP && _actor.LogicTime - logicTagValue > skillCd)
				{
					_actor.logicVariable.SetLogicTagValue("lastTime", _actor.LogicTime);
					ActorTryCastSkill actorTryCastSkill = ActorTryCastSkill.Generate();
					actorTryCastSkill.sender = _actor;
					actorTryCastSkill.skillId = skillId;
					actorTryCastSkill.flag = SkillPhaseFeatureFlag.Skill2;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(actorTryCastSkill);
				}
			}
		}
	}
	public class SkillState : IState
	{
		private FP meleeAttackDistance = 0.2;

		private int skillId = 11110002;

		private FP skillCd = 3;

		public ActionKey actionKey;

		public SkillPhaseFeatureFlag skillPhaseFeatureFlag;

		public bool CanCast;

		public int specialSkill;

		public bool isInterruptAttack;

		public bool isRushJoinDodge;

		public override void Enter()
		{
			base.Enter();
			SkillCountdownTiming skillCountdownTiming = SkillCountdownTiming.Start;
			int currentBindSkillId;
			if (specialSkill != 0)
			{
				currentBindSkillId = specialSkill;
			}
			else
			{
				currentBindSkillId = _skillManage.GetCurrentBindSkillId(actionKey);
				if (actionKey == ActionKey.B)
				{
					skillCountdownTiming = SkillCountdownTiming.End;
				}
			}
			int num = currentBindSkillId;
			AdventureActor actor = _actor;
			SkillPhaseFeatureFlag skillCastBehaviourType = skillPhaseFeatureFlag;
			SkillCountdownTiming countdownTiming = skillCountdownTiming;
			CanCast = ILRuntimeAPI.CreateSkill(num, actor, skillCastBehaviourType, SkillLauncherType.Character, isInterruptAttack, isBreakable: false, countdownTiming, delegate
			{
				Exit();
			}, null, ingoreCDAndEnergy: false, isRushJoinDodge);
		}

		public override void Update()
		{
			base.Update();
			LogicEntity attackTarget = GetAttackTarget();
			if (attackTarget != null && _actor.attackComboPhase == Combo.Phase.Recovery && _actor.CheckBreakAttack(SkillPhaseFeatureFlag.Normal))
			{
				_actor.InterruptAttack(force: true);
				FP fP = _actor.DistanceWithRadius(attackTarget);
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("lastTime");
				if (meleeAttackDistance > fP && _actor.LogicTime - logicTagValue > skillCd)
				{
					_actor.logicVariable.SetLogicTagValue("lastTime", _actor.LogicTime);
					ActorTryCastSkill actorTryCastSkill = ActorTryCastSkill.Generate();
					actorTryCastSkill.sender = _actor;
					actorTryCastSkill.skillId = skillId;
					actorTryCastSkill.flag = SkillPhaseFeatureFlag.Skill2;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(actorTryCastSkill);
				}
			}
		}
	}
	public class MoveState : IState
	{
		public override void Update()
		{
			base.Update();
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			if (assistantAttackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(assistantAttackTarget);
				if (_actor.actorSearchTargetInfo.visionAttackRange > fP)
				{
					Exit();
				}
				else
				{
					_actor.MoveTo(assistantAttackTarget.tsTransform.Position, 0.1f);
				}
			}
			else
			{
				Exit();
			}
		}

		public override void Exit()
		{
			base.Exit();
			_actor.StandBy((System.Action)null);
		}
	}
