		public override void OnEnable()
		{
			base.OnEnable();
			normalComboTime = 0;
			if (GetPerk(511003))
			{
				cd_03_Ct = cd_03;
			}
			if (GetPerk(511013))
			{
				PlayerSkillCd playerSkillCd = (_actor as PlayerAdventureActor).playerSkillCd;
				SkillInfo skillCD = playerSkillCd.GetSkillCD(ActionKey.A);
				playerSkillCd.SetSkillTotalSection(ActionKey.A, skillCD.totalSectionAmount + 1, forceMaxSection: true);
			}
			for (int i = 0; i < SceneSingleton<AdventurePlayerController>.Instance.ActorLs.Count; i++)
			{
				PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance.ActorLs[i];
				if (playerAdventureActor.actorElementInfo.elementType == GameEnum.elementType.DE)
				{
					if (GetPerk(511033))
					{
						playerAdventureActor.buffComponent.AddBuff(11053311, _actor);
					}
					if (GetPerk(511011))
					{
						_actor.buffComponent.AddBuff(11051111, _actor);
					}
				}
			}
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("TRIGGER_PERFECTDODGE", OnTriggerPerfectDodge);
			ModuleController<AdventureModuleController>.Instance?.AddEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
		}

		public override void OnDisable()
		{
			base.OnDisable();
			fsEntitys.Clear();
			areaLeftId = 0L;
			areaBoomId = 0L;
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("ADVENTURE_ACTOR_RECEIVE_DAMAGE", OnReceiveDamage);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("TRIGGER_PERFECTDODGE", OnTriggerPerfectDodge);
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("AREA_EFFECT_FINISH", OnAreaEffectFinish);
		}

		private void OnAreaEffectFinish(IEvent evt)
		{
			AdventureAreaEffectFinishEvent adventureAreaEffectFinishEvent = evt as AdventureAreaEffectFinishEvent;
			if (_actor != null && adventureAreaEffectFinishEvent.owner.Id == _actor.Id && adventureAreaEffectFinishEvent.sender is AreaEffectEntity areaEffectEntity)
			{
				if (GetPerk(511022) && areaEffectEntity.CheckTag(leftAreaTag))
				{
					ILRuntimeAPI.PlayAreaEffect(_actor, "Actor/Character/11001/Weapons/AreaEffect_110_Support_QuanZhang_Boom", areaEffectEntity.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
				}
				if (areaEffectEntity.Id == areaLeftId)
				{
					ILRuntimeAPI.StopAreaEffect(areaBoomId);
				}
			}
		}

		private void OnElementMarkTrigger(IEvent evt)
		{
		}

		protected void OnTriggerPerfectDodge(IEvent evt)
		{
			_ = (evt as AdventurePerfectDodgeTrigger).actor != _actor;
		}

		private void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (_actor == null || adventureActorReceiveDamageBeforeHitEvent.to == null || adventureActorReceiveDamageBeforeHitEvent.hitDamageTag == null)
			{
				return;
			}
			MonsterAdventureActor monsterAdventureActor = adventureActorReceiveDamageBeforeHitEvent.to as MonsterAdventureActor;
			if (monsterAdventureActor != null)
			{
				if (GetPerk(511025) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, skillB_tag))
				{
					AdventureActor.AddFromAttr(11052501, _actor);
				}
				if (GetPerk(511026) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, skillB_tag) && monsterAdventureActor.buffComponent.CheckBuffByBuffID(11090000))
				{
					AdventureActor.AddFromAttr(11052601, _actor);
				}
			}
		}

		private void OnReceiveDamage(IEvent evt)
		{
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (_actor != null && _actor.Id == adventureActorReceiveDamageEvent.from.Id && adventureActorReceiveDamageEvent.to is MonsterAdventureActor monsterAdventureActor && adventureActorReceiveDamageEvent.hitDamageTag != null)
			{
				if (GetPerk(511005) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, skillMainTag) && TSRandom.Range(0, 100) < (monsterAdventureActor.buffComponent.CheckBuffByBuffTag(darkBuff_tag) ? 70 : 35))
				{
					ILRuntimeAPI.HitActor(_actor, (AdventureActor)monsterAdventureActor, 110300003, "Actor/Character/11001/Fx/fx_11001_base_T5_DaoGuang", (string)null, false, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
				}
				if (GetPerk(511007) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, nrmalAtkTag))
				{
					_actor.buffComponent.AddBuff(11050711, _actor);
				}
				if (GetPerk(511027) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, skillB_tag) && adventureActorReceiveDamageEvent.isCrit)
				{
					PlayerAdventureActor playerAdventureActor = SceneSingleton<AdventurePlayerController>.Instance?.ActivedPlayerActor;
					if (playerAdventureActor != null)
					{
						playerAdventureActor.buffComponent.AddBuff(11052711, _actor);
					}
				}
				if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, darkBoomHit))
				{
					OnDarkHit(monsterAdventureActor, adventureActorReceiveDamageEvent.hitDamageTag);
				}
			}
			else
			{
				if (fsEntitys.Count <= 0 || !(adventureActorReceiveDamageEvent.to is MonsterAdventureActor monster) || adventureActorReceiveDamageEvent.hitDamageTag == null)
				{
					return;
				}
				for (int i = 0; i < fsEntitys.Count; i++)
				{
					if (fsEntitys[i].Id == adventureActorReceiveDamageEvent.from.Id)
					{
						if (CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, darkBoomHit))
						{
							OnDarkHit(monster, adventureActorReceiveDamageEvent.hitDamageTag);
						}
						break;
					}
				}
			}
		}

		private void OnDarkHit(AdventureActor _monster, IList<int> hitDamageTag)
		{
			if (!(_monster == null) && CommonUtils.CheckElementMark(CommonDefine.Dark, _monster) && CommonUtils.CheckTriggerElementMarkCD(_actor, _monster))
			{
				if (GetPerk(511006))
				{
					_actor.buffComponent.AddBuff(11050611, _actor);
				}
				if (GetPerk(511043) && CommonUtils.CheckHitByTag(hitDamageTag, ultral_atkTag))
				{
					_actor.buffComponent.AddBuff(11043011, _actor);
				}
				if (CommonUtils.CheckHitByTag(hitDamageTag, skillB_tag) && GetPerk(511025, cd_25))
				{
					(_actor as PlayerAdventureActor).playerSkillCd.ModifyResumeTimeAbs(-CommonUtils.GetScriptValue(_actor, 11052511), ActionKey.B);
				}
				_monster.buffComponent.RemoveBuffByTag(CommonDefine.Dark);
				ILRuntimeAPI.HitActor(_actor, _monster, 110000000, (string)null, "FX/ActorCommon/fx_common_base_DarkTirgger_AnZhuo", true, HitBox.FeatureFlag.None, (HitBox.HitBoxFeatureData)null, default(FP), HitBox.HurtAnimType.Small, 0, (GameObject)null);
				_monster.buffComponent.AddBuff(11090000, _actor);
				CommonUtils.TriggerElementMarkEvent(CommonDefine.Dark, GameEnum.AdventureActorElementTriggerType.DarkElementTriggerType1, _actor, _monster, "DarkMark_Trigger_Effect_03");
			}
		}

		private void OnSummonAvatar()
		{
			SummonCfg summonCfg = new SummonCfg();
			summonCfg.summonFollowType = SummonFollowType.NotFollow;
			summonCfg.summonAttrType = SummonAttrType.InheritByInitialSnapshot;
			summonCfg.summonRelation = SummonRelation.Coexisted;
			summonCfg.attrPercent = 100;
			FP leftTime = fsLeftTimeA;
			bool isAssist = (_actor as PlayerAdventureActor).isAssist;
			if (isAssist)
			{
				leftTime = fsLeftTimeB;
			}
			if (GetPerk(511009))
			{
				leftTime += CommonUtils.GetScriptValue(_actor, 11050901);
			}
			if (GetPerk(511024))
			{
				leftTime += (FP)5;
			}
			summonCfg.leftTime = leftTime;
			TSVector2 tSVector = _actor.RandomActorReachablePointInsideRing(_actor.tsTransform.Position, fsInnerR, fsOutsiseR);
			ILRuntimeAPI.SummonMonster(_actor, 0, isAssist ? 11000002 : 11000001, tSVector, _actor.tsTransform.Forward, summonCfg, (string)null, (Action<MonsterAdventureActor>)delegate(MonsterAdventureActor monster)
			{
				if (GetPerk(511003))
				{
					monster.buffComponent.AddBuff(11003011, _actor);
				}
				if (GetPerk(511004))
				{
					monster.buffComponent.AddBuff(11004011, _actor);
				}
				if (GetPerk(511009))
				{
					monster.buffComponent.AddBuff(11050911, _actor);
				}
				if (GetPerk(511010))
				{
					monster.buffComponent.AddBuff(11051011, _actor);
				}
				if (GetPerk(511012))
				{
					monster.buffComponent.AddBuff(11051211, _actor);
				}
				if (GetPerk(511031))
				{
					monster.buffComponent.AddBuff(11053111, _actor);
				}
				FP logicTagValue = _actor.logicVariable.GetLogicTagValue("110_skill");
				if (logicTagValue > 0)
				{
					monster.logicVariable.SetLogicTagValue("110_skill", logicTagValue);
				}
				_actor.PlayMovableFx("fx_11001_bullet_FenShen_BirthBullt", _actor.transform.position, monster.transform.position, 10f);
				fsEntitys.Add(monster);
			});
		}

		private void OnFsDieBoom(AdventureActor ac)
		{
			if (GetPerk(511008))
			{
				ILRuntimeAPI.PlayAreaEffect(ac, "AreaEffect_110_Main_FenShen_DieBoom", ac.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
			if (GetPerk(511029))
			{
				ILRuntimeAPI.PlayAreaEffect(ac, "AreaEffect_110_Support_FenShen_DieBoom", ac.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)null, (AdventureActor)null);
			}
		}

		public void OnUpdate()
		{
			FP logicTagValue = _actor.logicVariable.GetLogicTagValue("fenSheng");
			if (logicTagValue > 0)
			{
				if (fsEntitys.Count > 0 && (_actor as PlayerAdventureActor).isAssist)
				{
					for (int i = 0; i < fsEntitys.Count; i++)
					{
						(fsEntitys[i] as AdventureActor).DestroySelf();
					}
				}
				_actor.logicVariable.SetLogicTagValue("fenSheng", 0);
				for (int j = 0; j < logicTagValue; j++)
				{
					OnSummonAvatar();
				}
			}
			if (fsEntitys.Count > 0)
			{
				for (int num = fsEntitys.Count - 1; num > -1; num--)
				{
					if (fsEntitys[num].IsDead())
					{
						fsEntitys.RemoveAt(num);
					}
				}
			}
			if (cd_03_Ct > 0)
			{
				cd_03_Ct -= _actor.LogicDeltaTime;
				if (cd_03_Ct <= 0)
				{
					_actor.logicVariable.SetLogicTagValue("110_skill", 0);
					OnSummonAvatar();
					cd_03_Ct = cd_03;
				}
			}
			if (cd_11_Ct > 0)
			{
				cd_11_Ct -= _actor.LogicDeltaTime;
				if (cd_11_Ct <= 0)
				{
					_actor.logicVariable.SetLogicTagValue("110_skill", 1);
					AdventurActorNormalEvent adventurActorNormalEvent = AdventurActorNormalEvent.Generate();
					adventurActorNormalEvent.sender = _actor;
					adventurActorNormalEvent.stateID = 1;
					adventurActorNormalEvent.enventTag = "fsSkill";
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventurActorNormalEvent);
				}
			}
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		protected FP _dodgeDuration = 0.3;

		protected FP _dodgeDistance = 0.01;

		protected readonly ComboInputBuffer.ActionKey[] _actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };

		private static readonly float _realDodgeDistance = 4.233f;

		private static readonly float _crossDodgeAdditionDistance = 1.5f;

		private static readonly float _crossDodgeKeepAwayNavmeshEdgeDistance = 0.1f;

		private static readonly int _transitionRushSkillId = 0;

		protected Dodge _dodge;

		private bool iCrossObstacle;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_dodge?.Interrupte();
			_actor.DisableDodgeCrossObstacle();
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			if (GetPerk(511013))
			{
				_actor.buffComponent.AddBuff(11051311, _actor);
			}
			iCrossObstacle = GetPerk(511012);
			if (iCrossObstacle)
			{
				_actor.EnableDodgeCrossObstacle();
			}
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				if (iCrossObstacle)
				{
					CommonUtils.CheckAndSetDodgeCrossObstacleMode(_actor, _realDodgeDistance, _crossDodgeAdditionDistance, _crossDodgeKeepAwayNavmeshEdgeDistance);
				}
				ComboInputBuffer.ActionKey[] actionKeys = _actionKeys;
				System.Action onActivationEnd = OnActivationEnd;
				System.Action onRecoveryBegin = OnRecoveryBegin;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack(actionKeys, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, onRecoveryBegin, onComboFinish, onInterrupt, null, onActivationEnd);
				if (_dodge == null)
				{
					_dodge = new Dodge();
				}
				TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (tSVector == TSVector2.zero)
				{
					tSVector = _actor.tsTransform.Forward.normalized;
				}
				_dodge.Begin(_actor, tSVector, _dodgeDuration, _dodgeDistance, null, comboWithAttack: true);
			}
		}

		protected void OnActivationEnd()
		{
			CommonUtils.ClearDodgeCrossObstacleMode(_actor);
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ILRuntimeAPI.CreateSkill(specialSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
					OnFinish();
				}
			}
			else if (SceneSingleton<AdventurePlayerController>.Instance.HasMovementInput() && _transitionRushSkillId != 0)
			{
				ILRuntimeAPI.CreateSkill(_transitionRushSkillId, _actor, SkillPhaseFeatureFlag.Skill2, SkillLauncherType.Character, isInterruptAttack: false);
				OnFinish();
			}
		}

		protected void OnAnticipationEnd()
		{
		}

		protected void OnRecoveryBegin()
		{
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		private readonly Dictionary<int, string> actionTags = new Dictionary<int, string>
		{
			[0] = "Atk1",
			[1] = "Atk2",
			[2] = "Atk3",
			[3] = "Atk4"
		};

		private readonly string zhFsTag = "110_NrmAtk_ZhaoHuanFenShen";

		private readonly string fsCcTag = "110_FenShen_ChongCi";

		private int attackCount;

		private readonly FP saveComboIndexTime = 1;

		protected override void OnSkillDisable()
		{
			Parallel.normalComboTime = _actor.LogicTime;
			_actor.movementFSM.runtimeIgonreRootMotion = false;
			base.OnSkillDisable();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_actor.attackTarget != null)
			{
				if (_actor.LogicTime > Parallel.normalComboTime + saveComboIndexTime)
				{
					attackCount = 0;
				}
				else
				{
					attackCount = (int)(long)_actor.logicVariable.GetLogicTagValue("normalCount");
				}
				if (actionTags.TryGetValue(attackCount, out var value))
				{
					string actionTag = value;
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					System.Action onAnticipationEnd = OnAnticipationEnd;
					Action<string> onCustomEvent = OnCustomEvent;
					BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, null, null, default(TSVector2), onAnticipationEnd, null, onComboFinish, onInterrupt, onCustomEvent);
				}
				else
				{
					OnInterrupt();
				}
			}
			else
			{
				OnInterrupt();
			}
		}

		protected void OnAnticipationEnd()
		{
			attackCount++;
			if (attackCount >= actionTags.Count)
			{
				attackCount = 0;
			}
			_actor.logicVariable.SetLogicTagValue("normalCount", attackCount);
		}

		protected void OnRecoveryBegin()
		{
		}

		protected void OnCustomEvent(string eventName)
		{
			if (zhFsTag.Equals(eventName))
			{
				_actor.logicVariable.SetLogicTagValue("110_skill", 0);
				if (Parallel.fsEntitys.Count == 0)
				{
					_actor.logicVariable.SetLogicTagValue("fenSheng", 1);
				}
			}
			else if (fsCcTag.Equals(eventName))
			{
				_actor.logicVariable.SetLogicTagValue("110_skill", 1);
				AdventurActorNormalEvent adventurActorNormalEvent = AdventurActorNormalEvent.Generate();
				adventurActorNormalEvent.sender = _actor;
				adventurActorNormalEvent.stateID = 1;
				adventurActorNormalEvent.enventTag = "fsSkill";
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventurActorNormalEvent);
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		public virtual void OnUpdate()
		{
			LockDirection();
			if (SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection() != TSVector2.zero)
			{
				_actor.movementFSM.runtimeIgonreRootMotion = true;
			}
			else
			{
				_actor.movementFSM.runtimeIgonreRootMotion = false;
			}
		}
	}
