	public class SkillScript_Ultra : SkillAdvancedBase
	{
		private const string actionTag_Loop_Timeline = "Ultra_TL_Loop";

		private const string actionTag_Loop_NoTimeline = "Ultra_NoTL_Loop";

		private const string actionTag_End = "Ultra_End";

		private const int totalLoopTime = 5;

		private const int perkId_42 = 510842;

		private const string actionTag_End_Perk42 = "Ultra_P42_End";

		private int _totalLoopTime;

		private bool _canAim;

		private AimTarget _aimTarget;

		private PlayTimeline _playTimeline;

		private int _loopTime;

		private TSVector2 _direction;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			DefaultLookAt();
			_totalLoopTime = 5;
			_canAim = true;
			_loopTime = 0;
			_direction = _actor.tsTransform.Forward;
			_actor.EnableInvincible();
			_actor.EnableSuperArmor();
			_actor.EnableImmuneControl();
		}

		public void OnStart()
		{
			if (_playTimeline == null)
			{
				_playTimeline = new PlayTimeline();
			}
			_playTimeline.Play(_actor, PlayTimelineShootCombo, PlayNoTimelineShootCombo);
		}

		private void PlayTimelineShootCombo()
		{
			string loopStageActionTag = GetLoopStageActionTag(haveTimeline: true);
			System.Action onComboLoop = OnShootComboLoop;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(loopStageActionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
		}

		private void PlayNoTimelineShootCombo()
		{
			string loopStageActionTag = GetLoopStageActionTag(haveTimeline: false);
			System.Action onComboLoop = OnShootComboLoop;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(loopStageActionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, null, fadeOutAnim: false, onComboLoop);
		}

		private string GetLoopStageActionTag(bool haveTimeline)
		{
			if (!haveTimeline)
			{
				return "Ultra_NoTL_Loop";
			}
			return "Ultra_TL_Loop";
		}

		protected void OnShootComboLoop()
		{
			_loopTime++;
			if (_loopTime >= _totalLoopTime)
			{
				string text = "Ultra_End";
				if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510842, out var _))
				{
					text = "Ultra_P42_End";
				}
				_canAim = !((PlayerAdventureActor)_actor).isAssist;
				string actionTag = text;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
			}
		}

		public void OnUpdate()
		{
			if (_canAim)
			{
				LogicEntity attackTarget = GetAttackTarget();
				if (attackTarget != null)
				{
					_direction = (attackTarget.tsTransform.Position - _actor.tsTransform.Position).normalized;
				}
				if (_aimTarget == null)
				{
					_aimTarget = new AimTarget();
				}
				if (_actor.aimMode != AdventureActor.AimMode.LockDirection)
				{
					_aimTarget.Aim(_actor, null, _direction);
				}
				else
				{
					_actor.tsTransform.Forward = _direction;
				}
			}
		}

		private LogicEntity GetAttackTarget()
		{
			if ((_actor as PlayerAdventureActor).isAssist)
			{
				return CommonUtils.GetAssistantAttackTarget(_actor);
			}
			return _actor.attackTarget;
		}

		private void OnFinish()
		{
			_skill.Clear();
		}

		private void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.DisableInvincible();
			_actor.DisableSuperArmor();
			_actor.DisableImmuneControl();
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
			_loopTime = 0;
		}
	}
	public class ActionScript_MainControl : ActorActionBase
	{
		private const int skillId_DefaultNormalAttack = 10810000;

		private const int skillId_SpecialNormalAttack = 10812000;

		private const int ammoCountMax_SpecialAmmo = 10;

		private AimTarget _aimTarget;

		private bool _lockSkill;

		private bool LockSkill
		{
			get
			{
				return _lockSkill;
			}
			set
			{
				if (_lockSkill != value)
				{
					_lockSkill = value;
					MonoSingleton<LuaManager>.Instance.FireEntityEvent("SkillUseableByActionKey", _actor.Id, 2, !_lockSkill);
				}
			}
		}

		protected override void OnActionEnable()
		{
			PlayerAdventureActor playerAdventureActor = _actor as PlayerAdventureActor;
			playerAdventureActor.ammoInfo.SetOriginIntValue(GameEnum.AmmoType.Special1, 10, 1);
			if (playerAdventureActor.status == ActorStatus.Default)
			{
				_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, 10810000);
				MonoSingleton<LuaManager>.Instance?.FireEvent("PlayerSwitchGun", 3);
				playerAdventureActor.ammoInfo.ammoType = GameEnum.AmmoType.Main;
				_actor.ammoInfo.bulletT = GameEnum.bulletType.Shotgun;
				playerAdventureActor.enableReload = true;
			}
			else
			{
				_playerSkillCd.BindSkillIdToButton(ActionKey.Normal, 10812000);
				MonoSingleton<LuaManager>.Instance?.FireEvent("PlayerSwitchGun", 4);
				playerAdventureActor.ammoInfo.ammoType = GameEnum.AmmoType.Special1;
				_actor.ammoInfo.bulletT = GameEnum.bulletType.FireShotgun;
				playerAdventureActor.enableReload = false;
			}
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			else
			{
				_aimTarget.Clear();
			}
			LockSkill = false;
		}

		protected override void OnButtonAPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.A), _actor, SkillPhaseFeatureFlag.Dodge, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		protected override void OnButtonBPress()
		{
			if (!LockSkill)
			{
				ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.B), _actor, SkillPhaseFeatureFlag.Skill1, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
			}
		}

		protected override void OnButtonDPress()
		{
			ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.D), _actor, SkillPhaseFeatureFlag.Ultimate, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
		}

		public void OnUpdate()
		{
			if (_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal) == 10812000 && _actor.ammoInfo.ammoCount >= _actor.ammoInfo.ammoCountMax)
			{
				LockSkill = true;
			}
			else
			{
				LockSkill = false;
			}
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(useInputDirection: true);
			if (_actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Ultimate))
			{
				return;
			}
			if (_actor.attackTarget == null || _actor.actorSkillManage.HaveSkill(SkillPhaseFeatureFlag.Skill2 | SkillPhaseFeatureFlag.Dodge) || base.IsObstacleBetweenActorAndTargetAndPreventNormalAttack)
			{
				if (_actor.aimMode != AdventureActor.AimMode.Forward)
				{
					_aimTarget.Cancel();
				}
				return;
			}
			FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
			if (fP < CommonUtils.GetAimRange(_actor))
			{
				if (_actor.aimMode != AdventureActor.AimMode.AimAtAttackTarget)
				{
					_aimTarget.Aim(_actor, (AdventureActor)_actor.attackTarget, default(TSVector2), playStartAnim: true);
				}
				if (fP <= CommonUtils.GetAttackRange(_actor) && _actor.aimMode == AdventureActor.AimMode.AimAtAttackTarget && _actor.ammoInfo.ammoCount > 0)
				{
					ILRuntimeAPI.CreateSkill(_playerSkillCd.GetCurrentBindSkillId(ActionKey.Normal), _actor, SkillPhaseFeatureFlag.Normal, SkillLauncherType.Character, isInterruptAttack: true, isBreakable: false);
				}
			}
			else if (_actor.aimMode != AdventureActor.AimMode.Forward)
			{
				_aimTarget.Cancel();
			}
		}

		protected override void OnActionDisable()
		{
			LockSkill = false;
			_aimTarget?.Cancel();
			_aimTarget?.Clear();
		}
	}
	public class ParallelScript_MainControl : ParallelScript
	{
		private static readonly int damageTag_NormalAttack = CommonHelper.StringToHash("108_Attack");

		private static readonly int damageTag_DefaultNormalAttack = CommonHelper.StringToHash("108_Bullet");

		private static readonly int damageTag_SpecialNormalAttack = CommonHelper.StringToHash("108_FireBullet");

		private static readonly int damageTag_MainControl = CommonHelper.StringToHash("108_Main");

		private const int perkId_3 = 510803;

		private const int skillTotalSectionAmount_3 = 5;

		private const int perkId_5 = 510805;

		private const int additionalAttrId_5 = 10850501;

		private const int perkId_6 = 510806;

		private readonly FP cd_6 = 4;

		private const int perkId_7 = 510807;

		private const int triggerCritTimes_7 = 10;

		private const int buffId_7 = 10850711;

		private const int perkId_8 = 510808;

		private const int buffId_8 = 10850801;

		private const int perkId_10 = 510810;

		private const int triggerTimes_10 = 6;

		private const int parameterId_10 = 10851001;

		private const int additionalAttrId_10 = 10851001;

		private const int perkId_11 = 510811;

		private const int parameterId_11 = 10851111;

		private const int additionalAttrId_11 = 10851101;

		private const int perkId_12 = 510812;

		private readonly FP triggerDistance_12 = 4;

		private const int additionalAttrId_12 = 10851201;

		private const int perkId_13 = 510813;

		private const int buffId_13 = 10851301;

		private int _additionalAttrCount_5;

		private FP _lastTriggerTime_6;

		private int _triggerCritTimes_7;

		private int _triggerTimes_10;

		public override void OnEnable()
		{
			base.OnEnable();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510803, out var perkLevel))
			{
				_playerSkillCd.SetSkillTotalSection(ActionKey.B, 5, forceMaxSection: true);
			}
			else
			{
				_playerSkillCd.ResetSkillTotalSection(ActionKey.B);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510813, out perkLevel))
			{
				_damageTag_TriggerFireMark?.Add(ParallelScript.damageTag_UltraSkill);
			}
			ModuleController<AdventureModuleController>.Instance.AddEventListener("KASIMIRA_NORMALATTACK_FINISH", OnNormalAttackFinish);
		}

		protected override void OnCastNormalSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
			base.OnCastNormalSkill(castSkillEvent);
			_additionalAttrCount_5 = 0;
		}

		private void OnNormalAttackFinish(IEvent evt)
		{
			KasimiraNormalAttackFinishEvent obj = evt as KasimiraNormalAttackFinishEvent;
			_actor.logicVariable.ToggleLogicTag("TriggerPerk_1", value: false);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510806, out var perkLevel) && _actor.logicVariable.GetLogicTagToggle("TriggerPerk_6"))
			{
				_lastTriggerTime_6 = _actor.LogicTime;
				_actor.logicVariable.ToggleLogicTag("TriggerPerk_6", value: false);
			}
			if (obj.isSpecial && ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510810, out perkLevel))
			{
				_triggerTimes_10++;
				if (_triggerTimes_10 >= 6)
				{
					FP scriptValue = CommonUtils.GetScriptValue(_actor, 10851001);
					_playerSkillCd.ModifyResumeTimeAbs(-scriptValue, ActionKey.B);
					_triggerTimes_10 = 0;
				}
			}
		}

		protected override void OnCastSkill(AdventureActorCastSkillEvent castSkillEvent)
		{
			base.OnCastSkill(castSkillEvent);
			_actor.logicVariable.ToggleLogicTag("TriggerPerk_1", value: true);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510806, out var _) && (_lastTriggerTime_6 <= 0 || _actor.LogicTime - _lastTriggerTime_6 > cd_6))
			{
				_actor.logicVariable.ToggleLogicTag("TriggerPerk_6", value: true);
			}
		}

		protected override void OnSelfAttacked(AdventureActorReceiveAttackEvent attackEvent)
		{
			base.OnSelfAttacked(attackEvent);
			MonsterAdventureActor monsterAdventureActor = attackEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510805, out var perkLevel) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, damageTag_MainControl))
			{
				_additionalAttrCount_5++;
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510808, out perkLevel) && CommonUtils.CheckHitByTag(attackEvent.hitDamageTag, damageTag_SpecialNormalAttack))
			{
				monsterAdventureActor.buffComponent.AddBuff(10850801, _actor);
			}
		}

		protected override void OnBeforeSelfHit(AdventureActorReceiveDamageBeforeHitEvent beforeHitEvent)
		{
			base.OnBeforeSelfHit(beforeHitEvent);
			MonsterAdventureActor aEntity = beforeHitEvent.to as MonsterAdventureActor;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510805, out var perkLevel) && _additionalAttrCount_5 > 0 && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_MainControl))
			{
				AdventureActor.AddFromAttr(10850501, _actor, _additionalAttrCount_5);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510810, out perkLevel) && CommonUtils.CheckHitByTag(beforeHitEvent.hitDamageTag, damageTag_SpecialNormalAttack))
			{
				AdventureActor.AddFromAttr(10851001, _actor);
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510811, out perkLevel))
			{
				FP scriptValue = CommonUtils.GetScriptValue(_actor, 10851111);
				if (_actor.actorHealthInfo.hpPercentage * 100 > scriptValue)
				{
					AdventureActor.AddFromAttr(10851101, _actor);
				}
			}
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510812, out perkLevel) && beforeHitEvent.elementType == GameEnum.elementType.FE && aEntity.DistanceWithRadius(_actor) < triggerDistance_12)
			{
				AdventureActor.AddFromAttr(10851201, _actor);
			}
		}

		protected override void OnSelfDamaged(AdventureActorReceiveDamageEvent damageEvent)
		{
			base.OnSelfDamaged(damageEvent);
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510807, out var _) && damageEvent.isCrit)
			{
				_triggerCritTimes_7++;
				if (_triggerCritTimes_7 >= 10)
				{
					_actor.buffComponent.AddBuff(10850711, _actor);
					_triggerCritTimes_7 = 0;
				}
			}
		}

		protected override void OnTriggerFireMark()
		{
			base.OnTriggerFireMark();
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510813, out var _))
			{
				_actor.buffComponent.AddBuff(10851301, _actor);
			}
		}

		private void Clear()
		{
			_additionalAttrCount_5 = 0;
			_lastTriggerTime_6 = 0;
			_triggerCritTimes_7 = 0;
			_triggerTimes_10 = 0;
		}

		public override void OnDisable()
		{
			base.OnDisable();
			ModuleController<AdventureModuleController>.Instance?.RemoveEventListener("KASIMIRA_NORMALATTACK_FINISH", OnNormalAttackFinish);
			Clear();
		}
	}
