	public class SkillScript_B1_Skill : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey[] actionKeys_Loop = new ComboInputBuffer.ActionKey[3]
		{
			ComboInputBuffer.ActionKey.E,
			ComboInputBuffer.ActionKey.X,
			ComboInputBuffer.ActionKey.X
		};

		private readonly ComboInputBuffer.ActionKey[] actionKeys_Attack = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey._2 };

		protected const int holdShield_AddWeightBuffId = 10731003;

		protected const int holdShield_ReduceDamageBuffId = 10731001;

		protected const int holdShield_ReduceMoveSpeedBuffId = 10731002;

		protected readonly FP runAnimationSpd_InSkill = 2.2;

		protected const int reduceCD = 12;

		protected const string lightMarkTag = "LightTag1";

		protected static readonly int counterAttackDamageTag = CommonHelper.StringToHash("StrikeBack");

		private const int perkId_1 = 510701;

		private const int maxAddAttrCount = 5;

		private readonly Dictionary<int, int> additionalAttrIdDic_1 = new Dictionary<int, int>
		{
			[1] = 10755111,
			[2] = 10755121,
			[3] = 10755131,
			[4] = 10755141,
			[5] = 10755151
		};

		private const int perkId_2 = 510702;

		private readonly Dictionary<int, int> buffIdDic_2 = new Dictionary<int, int>
		{
			[1] = 10755211,
			[2] = 10755221,
			[3] = 10755231,
			[4] = 10755241,
			[5] = 10755251
		};

		private const int perkId_3 = 510703;

		private readonly Dictionary<int, int> buffIdDic_3 = new Dictionary<int, int>
		{
			[1] = 10755311,
			[2] = 10755321,
			[3] = 10755331,
			[4] = 10755341,
			[5] = 10755351
		};

		protected int _curReduceDamageBuffId;

		protected bool _beginSecondStage;

		protected readonly List<FP> _receiveAttackTime = new List<FP>(10);

		protected AimTarget _aimTarget;

		protected PlayerSkillCd _skillManager;

		protected FP _originRunAnimationSpd;

		protected bool _searchUseInputDirection;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			_skillManager = _actor.GetLogicComponent<PlayerSkillCd>();
			_curReduceDamageBuffId = 0;
			_beginSecondStage = false;
			_receiveAttackTime.Clear();
			_originRunAnimationSpd = _actor.actorInfo.runAnimationSpd;
			_actor.actorInfo.runAnimationSpd = runAnimationSpd_InSkill;
			_searchUseInputDirection = true;
			ModuleController<AdventureModuleController>.Instance.AddEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
		}

		public virtual void OnStart()
		{
			SearchTargetAndAim();
			ComboInputBuffer.ActionKey[] keys = actionKeys_Loop;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(keys, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
			_curReduceDamageBuffId = 10731001;
			if (ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510702, out var perkLevel))
			{
				_curReduceDamageBuffId = buffIdDic_2[perkLevel];
			}
			_actor.buffComponent.AddBuff(10731003, _actor);
			_actor.buffComponent.AddBuff(_curReduceDamageBuffId, _actor);
			_actor.buffComponent.AddBuff(10731002, _actor);
		}

		public void OnUpdate()
		{
			SearchTargetAndAim();
			if (!_beginSecondStage && !_actor.logicVariable.GetLogicTagToggle("HoldingKeyB"))
			{
				_beginSecondStage = true;
				_aimTarget?.Cancel();
				_actor.buffComponent.RemoveBuffByBuffId(10731003);
				_actor.buffComponent.RemoveBuffByBuffId(_curReduceDamageBuffId);
				_actor.buffComponent.RemoveBuffByBuffId(10731002);
				if (_receiveAttackTime.Count > 0)
				{
					CounterAttack();
					AfterCounterAttack();
				}
				else
				{
					base.comboAttack.CancelAttack();
				}
			}
		}

		protected void SearchTargetAndAim()
		{
			if (_aimTarget == null)
			{
				_aimTarget = new AimTarget();
			}
			_actor.attackTarget = _actor.actorSearchTargetInfo.GetLockingConfrontActor(_searchUseInputDirection);
			if (_actor.attackTarget != null)
			{
				_actor.currentAttackTarget = _actor.attackTarget;
				_aimTarget.Aim(_actor, (AdventureActor)_actor.aimLockedTarget);
				_searchUseInputDirection = false;
				return;
			}
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward;
			}
			_aimTarget.Aim(_actor, null, tSVector);
			_actor.tsTransform.Forward = tSVector;
			_searchUseInputDirection = true;
		}

		protected virtual void CounterAttack()
		{
			ComboInputBuffer.ActionKey[] keys = actionKeys_Attack;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(keys, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		protected virtual void AfterCounterAttack()
		{
		}

		protected override void OnReceiveAttack(IEvent evt)
		{
			if (!((evt as AdventureActorReceiveAttackEvent).to != _actor))
			{
				_receiveAttackTime.Add(_actor.LogicTime);
			}
		}

		protected void OnBeforeHit(IEvent evt)
		{
			AdventureActorReceiveDamageBeforeHitEvent adventureActorReceiveDamageBeforeHitEvent = evt as AdventureActorReceiveDamageBeforeHitEvent;
			if (adventureActorReceiveDamageBeforeHitEvent.from == _actor && ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510701, out var perkLevel) && CommonUtils.CheckHitByTag(adventureActorReceiveDamageBeforeHitEvent.hitDamageTag, counterAttackDamageTag))
			{
				int count = _receiveAttackTime.Count;
				int count2 = ((count > 5) ? 5 : count);
				AdventureActor.AddFromAttr(additionalAttrIdDic_1[perkLevel], _actor, count2);
			}
		}

		protected override void OnReceiveDamage(IEvent evt)
		{
			base.OnReceiveDamage(evt);
			AdventureActorReceiveDamageEvent adventureActorReceiveDamageEvent = evt as AdventureActorReceiveDamageEvent;
			if (adventureActorReceiveDamageEvent.from == _actor && ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, 510703, out var perkLevel))
			{
				AdventureActor adventureActor = adventureActorReceiveDamageEvent.to as AdventureActor;
				if (adventureActor != null && adventureActor.CheckTag("LightTag1") && CommonUtils.CheckHitByTag(adventureActorReceiveDamageEvent.hitDamageTag, counterAttackDamageTag))
				{
					adventureActor.buffComponent?.AddBuff(buffIdDic_3[perkLevel], _actor);
				}
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			ModuleController<AdventureModuleController>.Instance.RemoveEventListener("ACTOR_RECEIVE_DAMAGE_BEFORE_HIT", OnBeforeHit);
			_aimTarget?.Cancel();
			_actor.buffComponent.RemoveBuffByBuffId(10731003);
			_actor.buffComponent.RemoveBuffByBuffId(_curReduceDamageBuffId);
			_actor.buffComponent.RemoveBuffByBuffId(10731002);
			_actor.actorInfo.runAnimationSpd = _originRunAnimationSpd;
			_searchUseInputDirection = true;
			_curReduceDamageBuffId = 0;
			_beginSecondStage = false;
			if (_receiveAttackTime.Count <= 0)
			{
				_skillManager.ModifyResumeTimeAbs(-12, ActionKey.B);
			}
			_receiveAttackTime.Clear();
		}
	}
	public class SkillScript_B2_Skill : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[3]
		{
			ComboInputBuffer.ActionKey.F,
			ComboInputBuffer.ActionKey.X,
			ComboInputBuffer.ActionKey.X
		};

		protected const string shootShieldEvent = "ThrowShield";

		protected const string shieldKey = "Bullet_107_B2_Skill_ThrowShield";

		protected const string reboundShieldKey = "Bullet_107_B2T1_Skill_ThrowShield";

		protected const string reboundShieldKey_T12 = "Bullet_107_B2T12_Skill_ThrowShield";

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_actor.attackTarget != null)
			{
				_actor.LookAt(_actor.attackTarget.tsTransform.Position, 0f);
			}
			ComboInputBuffer.ActionKey[] keys = actionKeys;
			Action<string> onCustomEvent = OnCustomEvent;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(keys, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, onCustomEvent);
		}

		protected void OnCustomEvent(string eventName)
		{
			if (string.Equals("ThrowShield", eventName))
			{
				PlayerAdventureActor playerAdventureActor = _actor as PlayerAdventureActor;
				string alias = GetShieldKey();
				GameObject fXByAlias = playerAdventureActor.comboGroup.relatedResourceConfig.GetFXByAlias(alias);
				if (fXByAlias != null)
				{
					SceneSingleton<SpecialEntityManager>.Instance.PlaySpecialProcess(playerAdventureActor, fXByAlias, playerAdventureActor.transform.position, playerAdventureActor.transform.rotation);
				}
			}
		}

		protected string GetShieldKey()
		{
			PlayerTalentGroupType talentGroupType = (_actor as PlayerAdventureActor).GetTalentGroupType();
			if (talentGroupType == PlayerTalentGroupType.Group1 || talentGroupType == PlayerTalentGroupType.Group12 || talentGroupType == PlayerTalentGroupType.Group13 || talentGroupType == PlayerTalentGroupType.Group14)
			{
				if (talentGroupType == PlayerTalentGroupType.Group12)
				{
					return "Bullet_107_B2T12_Skill_ThrowShield";
				}
				return "Bullet_107_B2T1_Skill_ThrowShield";
			}
			return "Bullet_107_B2_Skill_ThrowShield";
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}
	}
