		private IEnumerator DoCastAreaEffect()
		{
			yield return _actor.WaitTime(firstDelay_5);
			List<int> dirList = new List<int>();
			while (true)
			{
				dirList.Clear();
				for (int i = 0; i < maxCount_5; i++)
				{
					dirList.Add(i);
				}
				float num = 360f / (float)dirList.Count;
				CommonUtils.SearchNearTargetsByCircle(_actor, range_5, isConfront: true, includeSelf: false, entities);
				for (int j = 0; j < maxCount_5; j++)
				{
					if (entities.Count > 0)
					{
						int index = TSRandom.Range(0, Math.Min(1, entities.Count));
						LogicEntity monster = entities[index];
						entities.RemoveAt(index);
						ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_10301_Support_P25_Shadow", _actor.tsTransform.Position, default(FP), (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
						{
							AreaEffect_FollowComponent logicComponent = entity.GetLogicComponent<AreaEffect_FollowComponent>();
							if (logicComponent != null)
							{
								logicComponent.enabled = true;
								logicComponent.targetType = AreaEffect_FollowComponent.FollowTargetType.SpecifiedTarget;
								logicComponent.FollowTarget = monster;
							}
							AreaEffect_MoveComponent logicComponent2 = entity.GetLogicComponent<AreaEffect_MoveComponent>();
							if (logicComponent2 != null)
							{
								logicComponent2.enabled = false;
							}
						}, (AdventureActor)null);
						continue;
					}
					int index2 = TSRandom.Range(0, dirList.Count);
					FP degrees = (float)dirList[index2] * num + startAngle_5;
					dirList.RemoveAt(index2);
					TSVector2 tSVector = TSVector2.Rotate(TSVector2.up, degrees);
					ILRuntimeAPI.PlayAreaEffect(_actor, "AreaEffect_10301_Support_P25_Shadow", _actor.tsTransform.Position, tSVector.GetAngle(), (Action<AreaEffectEntity>)delegate(AreaEffectEntity entity)
					{
						AreaEffect_FollowComponent logicComponent = entity.GetLogicComponent<AreaEffect_FollowComponent>();
						if (logicComponent != null)
						{
							logicComponent.enabled = false;
						}
						AreaEffect_MoveComponent logicComponent2 = entity.GetLogicComponent<AreaEffect_MoveComponent>();
						if (logicComponent2 != null)
						{
							logicComponent2.enabled = true;
						}
					}, (AdventureActor)null);
				}
				yield return _actor.WaitTime(interval_5);
			}
		}
	}
	public class SkillScript_B1_S2 : SkillAdvancedBase
	{
		private string key_Base = "B1_Skill_P03_Base";

		private string key_Strong = "B1_Skill_P03";

		private readonly FP radius = 10;

		private const int perkId_3 = 510303;

		private const int buffId_3 = 10303011;

		private ActorSearchTarget actorSearchInfo;

		private List<LogicEntity> entities = new List<LogicEntity>();

		private List<DeterministicCollider> colliders = new List<DeterministicCollider>();

		private bool isReBind;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			actorSearchInfo = _actor.GetLogicComponent<ActorSearchTarget>();
			isReBind = false;
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_actor.buffComponent.RemoveBuffByBuffId(10303011);
			_actor.CancelAiming();
			entities.Clear();
			colliders.Clear();
			ReBindS1(isInterrupt: true);
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		private void SkillFinish()
		{
			_skill?.Clear();
		}

		private void SkillInterrupt()
		{
			_skill?.Clear();
		}

		public void OnUpdate()
		{
			actorSearchInfo.GetEnterVisionAlertActors(entities, colliders);
			if (entities.Count == 0)
			{
				LogicEntity logicEntity = SearchTarget();
				if (logicEntity != null)
				{
					_actor.CancelAiming();
					_actor.Aim(logicEntity.tsTransform.Position - _actor.tsTransform.Position, 0f);
				}
			}
		}

		private LogicEntity SearchTarget()
		{
			if (!(_actor.attackTarget != null))
			{
				return CommonUtils.SearchNearTargetByCircle(_actor, radius);
			}
			return _actor.attackTarget;
		}

		private void DoMainLogic()
		{
			int lv;
			string actionTag = ((GetPerkLv(510303, out lv) && _actor.buffComponent.CheckBuffByBuffID(10303011)) ? key_Strong : key_Base);
			LogicEntity attackTarget = _actor.attackTarget;
			System.Action action = onRecoveryBegin;
			System.Action onComboFinish = SkillFinish;
			System.Action onInterrupt = SkillInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: true, attackTarget, null, default(TSVector2), null, action, onComboFinish, onInterrupt);
		}

		private void onRecoveryBegin()
		{
			ReBindS1(isInterrupt: false);
		}

		private void ReBindS1(bool isInterrupt)
		{
			if (!isReBind)
			{
				isReBind = true;
				AdventurRebindSkill adventurRebindSkill = AdventurRebindSkill.Generate();
				adventurRebindSkill.sender = _actor;
				adventurRebindSkill.slotKey = ActionKey.B;
				adventurRebindSkill.skillId = Parallel_B1.skillId_S1;
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventurRebindSkill);
			}
		}

		private bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
