			DoMainLogic();
		}

		private void SkillFinish()
		{
			_skill?.Clear();
		}

		private void SkillInterrupt()
		{
			_skill?.Clear();
		}

		public void OnUpdate()
		{
			actorSearchInfo.GetEnterVisionAlertActors(entities, colliders);
			if (entities.Count == 0)
			{
				LogicEntity logicEntity = SearchTarget();
				if (logicEntity != null)
				{
					_actor.CancelAiming();
					_actor.Aim(logicEntity.tsTransform.Position - _actor.tsTransform.Position, 0f);
				}
			}
		}

		private void DoMainLogic()
		{
			_actor.attackTarget = SearchTarget();
			aimDirec();
			int key = _actor.logicVariable.GetLogicTagValue("lastSkillPhase").AsInt();
			string text = dicKey[key];
			if (GetPerkLv(510309, out var _))
			{
				text = dicKey_P9[key];
			}
			string actionTag = text;
			Action<string> action = onCustomEvent;
			System.Action action2 = onRecoveryBegin;
			System.Action onComboFinish = SkillFinish;
			System.Action onInterrupt = SkillInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, action2, onComboFinish, onInterrupt, action);
		}

		public void aimDirec()
		{
			if (_actor.attackTarget != null)
			{
				_actor.Aim(_actor.attackTarget.tsTransform.Position - _actor.tsTransform.Position, 0f);
				return;
			}
			TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (movementInputDirection != TSVector2.zero)
			{
				_actor.Aim(movementInputDirection, 0f);
			}
			else
			{
				_actor.Aim(_actor.tsTransform.Forward, 0f);
			}
		}

		public virtual void onCustomEvent(string eventName)
		{
			if (eventName.Equals(evt_shoot))
			{
				int num = _actor.logicVariable.GetLogicTagValue("lastSkillPhase").AsInt();
				num = ++num % skillSections;
				_actor.logicVariable.SetLogicTagValue("lastSkillPhase", num);
			}
		}

		private void onRecoveryBegin()
		{
			if (_actor.attackTarget == null)
			{
				_actor.CancelAiming();
			}
			ReBindS2(isInterrupt: false);
		}

		private LogicEntity SearchTarget()
		{
			if (!(_actor.attackTarget != null))
			{
				return CommonUtils.SearchNearTargetByCircle(_actor, radius);
			}
			return _actor.attackTarget;
		}

		private void ReBindS2(bool isInterrupt)
		{
			if (GetPerkLv(510303, out var _) && !isReBind)
			{
				isReBind = true;
				AdventurRebindSkill adventurRebindSkill = AdventurRebindSkill.Generate();
				adventurRebindSkill.sender = _actor;
				adventurRebindSkill.slotKey = ActionKey.B;
				adventurRebindSkill.skillId = Parallel_B1.skillId_S2;
				ModuleController<AdventureModuleController>.Instance.DispatchEvent(adventurRebindSkill);
			}
		}

		private bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
	public class SkillScript_B2_Skill : SkillAdvancedBase
	{
		private string key_base = "B2_Skill";

		private string key_P1 = "B2P21_Skill_Loop";

		private string key_P2 = "B2P22_Skill_Big";

		private string key_P12 = "B2P21P22_Skill_BigLoop";

		private string key_P24 = "B2P24_EndShoot";

		private readonly FP duration = 1;

		private readonly FP distance = 0.01;

		private FP baseTime = 5;

		private FP traceStopDis = 2;

		private FP shakeOffset = 4;

		private int skillEndHit = CommonHelper.StringToHash("skillEndHit");

		private const int perkId_1 = 510321;

		private const int perkId_2 = 510325;

		private const int perkId_4 = 510324;

		private CoroutineNode corMain;

		private CoroutineNode corDodge;

		private CoroutineNode corDefault;

		private Dodge dodge = new Dodge();

		private string actionKey;

		private FP dTime;

		public PlayerSkillCd skillMgr;

		private CoroutineNode corShake;

		private bool isInSkake;

		private LogicEntity lastTarget;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
			skillMgr = _actor.GetLogicComponent<PlayerSkillCd>();
			isInSkake = false;
			lastTarget = null;
			_actor.PauseMovementBlock();
			dTime = 0;
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			StopCoroutine(ref corMain);
			StopCoroutine(ref corDodge);
			StopCoroutine(ref corDefault);
			StopShake();
			_actor.ResumeMovementBlock();
			_actor.CancelAiming();
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		private void onFinishOrInterrupt()
		{
			_skill?.Clear();
		}

		private void DoMainLogic()
		{
			actionKey = key_base;
			if (_actor.logicVariable.GetLogicTagToggle("AutoSkill"))
			{
				StartCoroutine(ref corDefault, Skill_Default());
				return;
			}
			int lv;
			bool perkLv = GetPerkLv(510321, out lv);
			bool perkLv2 = GetPerkLv(510325, out lv);
			if (perkLv && perkLv2)
			{
				actionKey = key_P12;
			}
			else
			{
				if (perkLv)
				{
					actionKey = key_P1;
				}
				if (perkLv2)
				{
					actionKey = key_P2;
				}
			}
			if (!perkLv)
			{
				StartCoroutine(ref corDodge, Skill_Dodge());
			}
			else
			{
				StartCoroutine(ref corMain, Skill_Rotate());
			}
		}

		private IEnumerator Skill_Default()
		{
			if (GetPerkLv(510324, out var _))
			{
				LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
				if (assistantAttackTarget != null)
				{
					_actor.LookAt(assistantAttackTarget.tsTransform.Position, 0);
				}
				RequestComboAttack req = BeginAttack(actionKey, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, null, null, null, fadeOutAnim: true);
				while (!req.isRecoveryBegin)
				{
					yield return null;
				}
				PlayAddCombo();
				yield break;
			}
			LogicEntity assistantAttackTarget2 = CommonUtils.GetAssistantAttackTarget(_actor);
			if (assistantAttackTarget2 != null)
			{
				_actor.LookAt(assistantAttackTarget2.tsTransform.Position, 0);
			}
			SkillScript_B2_Skill skillScript_B2_Skill = this;
			string actionTag = actionKey;
			System.Action onComboFinish = onFinishOrInterrupt;
			System.Action onInterrupt = onFinishOrInterrupt;
			skillScript_B2_Skill.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
		}

		private IEnumerator Skill_Dodge()
		{
			_actor.CancelAiming();
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			if (assistantAttackTarget != null)
			{
				tSVector = assistantAttackTarget.tsTransform.Position - _actor.tsTransform.Position;
			}
			else if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward;
			}
			dodge.Begin(_actor, tSVector, distance, duration);
			if (GetPerkLv(510324, out var _))
			{
				RequestComboAttack req = BeginAttack(actionKey, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, null, null, null, fadeOutAnim: true);
				while (!req.isRecoveryBegin)
				{
					yield return null;
				}
				PlayAddCombo();
			}
			else
			{
				SkillScript_B2_Skill skillScript_B2_Skill = this;
				string actionTag = actionKey;
				System.Action onComboFinish = onFinishOrInterrupt;
				System.Action onInterrupt = onFinishOrInterrupt;
				skillScript_B2_Skill.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
			}
		}

		private IEnumerator Skill_Rotate()
		{
			if (GetPerkLv(510324, out var lv))
			{
				RequestComboAttack req = BeginAttack(actionKey, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, null, null, null, fadeOutAnim: true);
				while (!req.isAnticipationEnd)
				{
					yield return null;
				}
			}
			else
			{
				SkillScript_B2_Skill skillScript_B2_Skill = this;
				string actionTag = actionKey;
				System.Action onInterrupt = onFinishOrInterrupt;
				System.Action onComboFinish = onFinishOrInterrupt;
				RequestComboAttack req = skillScript_B2_Skill.BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt);
				while (!req.isAnticipationEnd)
				{
					yield return null;
				}
			}
			while (true)
			{
				LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
				if (assistantAttackTarget != null && assistantAttackTarget is AdventureActor adventureActor)
				{
					if (lastTarget != null && lastTarget.Id != assistantAttackTarget.Id)
					{
						StopShake();
					}
					lastTarget = assistantAttackTarget;
					if (!isInSkake)
					{
						if (adventureActor.movementState == ActorState.StandBy)
						{
							if (TSVector2.Distance(assistantAttackTarget.tsTransform.Position, _actor.tsTransform.Position) <= traceStopDis)
							{
								_actor.StandBy((System.Action)null);
								StartCoroutine(ref corShake, ShakeMove(adventureActor));
							}
							else
							{
								_actor.TrackMove(assistantAttackTarget, traceStopDis, enableNavigation: false, NavAgentTypeNames.NavigationUpdateQualityLevel.LowQualityNavigationUpdate, AdventureActor.MovementMode.Walk);
							}
						}
						else
						{
							_actor.TrackMove(assistantAttackTarget, traceStopDis, enableNavigation: false, NavAgentTypeNames.NavigationUpdateQualityLevel.LowQualityNavigationUpdate, AdventureActor.MovementMode.Walk);
						}
					}
				}
				if (dTime > baseTime)
				{
					break;
				}
				dTime += _actor.LogicDeltaTime;
				yield return null;
			}
			StopShake();
			if (GetPerkLv(510324, out lv))
			{
				PlayAddCombo();
			}
			else
			{
				_actor.CancelAttack();
			}
		}

		public bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}

		private IEnumerator ShakeMove(AdventureActor target)
		{
			isInSkake = true;
			TSVector2 normalized = (target.tsTransform.Position - _actor.tsTransform.Position).normalized;
			TSVector2 forwradPos = target.tsTransform.Position + normalized * shakeOffset;
			TSVector2 backPos = target.tsTransform.Position - normalized * shakeOffset;
			MoveTo(forward: true, forwradPos, backPos);
			while (!target.IsDead() && target.movementState == ActorState.StandBy)
			{
				yield return null;
			}
			_actor.StandBy((System.Action)null);
			isInSkake = false;
		}

		private void StopShake()
		{
			StopCoroutine(ref corShake);
			_actor.StandBy((System.Action)null);
			isInSkake = false;
		}

		private void MoveTo(bool forward, TSVector2 forwradPos, TSVector2 backPos)
		{
			_actor.MoveTo(forward ? forwradPos : backPos, 0.1, enableNavigation: false, AdventureActor.MovementMode.Walk, delegate
			{
				MoveTo(!forward, forwradPos, backPos);
			});
		}

		private void PlayAddCombo()
		{
			LogicEntity assistantAttackTarget = CommonUtils.GetAssistantAttackTarget(_actor);
			if (assistantAttackTarget != null)
			{
				_actor.LookAt(assistantAttackTarget.tsTransform.Position, 0);
			}
			string actionTag = key_P24;
			System.Action onComboFinish = onFinishOrInterrupt;
			System.Action onInterrupt = onFinishOrInterrupt;
			BeginAttack(actionTag, flushInputedKeys: true, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, null, fadeOutAnim: true);
		}
	}
	public class SkillScript_Dodge : SkillAdvancedBase
	{
		protected readonly ComboInputBuffer.ActionKey actionKey = ComboInputBuffer.ActionKey.D;

		private readonly FP duration = 0.3;

		private readonly FP distance = 0.01;

		protected Dodge _dodge;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			Clear();
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		private void Clear()
		{
			base.comboAttack?.Clear();
		}

		private void DoMainLogic()
		{
			_actor.PlayFX("fx_10501_base_skill1_1_shadow");
			ComboInputBuffer.ActionKey key = actionKey;
			System.Action onActivationEnd = OnActivationEnd;
			System.Action onComboFinish = OnFinish;
			System.Action onInterrupt = OnInterrupt;
			BeginAttack(key, flushInputedKeys: true, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, null, onActivationEnd);
			TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
			if (tSVector == TSVector2.zero)
			{
				tSVector = _actor.tsTransform.Forward.normalized;
			}
			if (_dodge == null)
			{
				_dodge = new Dodge();
			}
			_dodge.Begin(_actor, tSVector, duration, distance, null, comboWithAttack: true);
		}

		protected void OnActivationEnd()
		{
			if (((PlayerAdventureActor)_actor).dodgeButtonHold && !_actor.forbiddenRush)
			{
				int specialSkillId = ((PlayerAdventureActor)_actor).playerAIInfo.SpecialSkillId;
				if (specialSkillId != 0)
				{
					ActorTryCastSkill actorTryCastSkill = ActorTryCastSkill.Generate();
					actorTryCastSkill.sender = _actor;
					actorTryCastSkill.skillId = specialSkillId;
					actorTryCastSkill.isInterruptAttack = false;
					actorTryCastSkill.flag = SkillPhaseFeatureFlag.Skill2;
					ModuleController<AdventureModuleController>.Instance.DispatchEvent(actorTryCastSkill);
					OnFinish();
				}
			}
		}

		protected void OnFinish()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}

		protected void OnInterrupt()
		{
			_dodge?.Interrupte();
			_skill?.Clear();
		}
	}
	public class SkillScript_NormalAttack : SkillAdvancedBase
	{
		protected readonly string _customEventName = "Shoot1";

		private readonly string _actionKey = "Attack_1";

		private readonly string _actionKey1 = "Attack_P02_AOE";

		private const int perkId_2 = 510302;

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
		}

		public void OnStart()
		{
			DoMainLogic();
		}

		public void OnUpdate()
		{
			if (_actor.attackTarget == null)
			{
				base.comboAttack.InterruptAttack();
			}
		}

		private void DoMainLogic()
		{
			string actionTag = ParseKey();
			System.Action onComboFinish = onFinish;
			System.Action onInterrupt = onFinish;
			Action<string> action = onCustomEvent;
			BeginAttack(actionTag, flushInputedKeys: false, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, onComboFinish, onInterrupt, action);
		}

		private string ParseKey()
		{
			if (_actor.logicVariable.GetLogicTagToggle("attck_strong"))
			{
				return _actionKey1;
			}
			return _actionKey;
		}

		private void onCustomEvent(string eventName)
		{
			if (!eventName.Equals(_customEventName))
			{
				return;
			}
			AmmoInfo flowAmmoInfo = ActorHelper.GetFlowAmmoInfo(_actor.gameObject);
			if (flowAmmoInfo != null && flowAmmoInfo.ammoCount > 0)
			{
				flowAmmoInfo.RefreshAmmoCost(-1);
				if (_actor.logicVariable.GetLogicTagToggle("attck_strong") && flowAmmoInfo.ammoCount <= 0)
				{
					_actor.InterruptAttack(force: true);
				}
			}
		}

		private void onFinish()
		{
			_skill?.Clear();
		}

		private bool GetPerkLv(int perkId, out int lv)
		{
			return ModuleController<AdventureModuleController>.Instance.GetPersonalPerkLevel(_actor.dataID, perkId, out lv);
		}
	}
