	public class Skill0_Branch2 : SkillAdvancedBase
	{
		protected ComboAttack _comboAttack;

		protected CoroutineNode _waitForCoroutine;

		protected FP _waitTime = 10;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			if (_waitForCoroutine != null)
			{
				_actor.StopLogicCoroutine(_waitForCoroutine);
				_waitForCoroutine = null;
			}
			_actor.movementMode = AdventureActor.MovementMode.Run;
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public virtual void OnStart()
		{
			if (_skill != null)
			{
				SetSkillPhaseConfig(SkillPhaseFeatureFlag.Dodge | SkillPhaseFeatureFlag.Ultimate, null, SkillPhaseFeatureFlag.Dodge | SkillPhaseFeatureFlag.Ultimate, null);
				ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.D };
				_actor.movementMode = AdventureActor.MovementMode.Walk;
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				int skillId = ((_skill != null) ? _skill.skillId : 0);
				System.Action onAnticipationEnd = OnAnticipationEnd;
				System.Action onRecoveryBegin = OnRecoveryBegin;
				System.Action onComboFinish = OnFinish;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: false, skillId, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, null, onComboFinish);
				_waitForCoroutine = _actor.StartLogicCoroutine(WaitForCoroutine());
			}
		}

		protected void OnAnticipationEnd()
		{
		}

		protected void OnRecoveryBegin()
		{
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		protected IEnumerator WaitForCoroutine()
		{
			yield return _actor.StartLogicCoroutine(_actor.WaitForSeconds(_waitTime));
			_comboAttack?.CancelAttack();
			_waitForCoroutine = null;
		}

		public void OnUpdate()
		{
			if (_comboAttack != null && !_actor.logicVariable.GetLogicTagToggle("holdSkill"))
			{
				_comboAttack.CancelAttack();
			}
		}
	}
	public class Skill_Dodge : SkillAdvancedBase
	{
		protected ComboAttack _comboAttack;

		protected Dodge _dodge;

		protected FP _dodgeDuration = 0.5;

		protected FP _dodgeDistance = 4.5;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
			_dodge?.Interrupte();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				SetSkillPhaseConfig(SkillPhaseFeatureFlag.Ultimate, null, SkillPhaseFeatureFlag.Ultimate, null);
				TSVector2 movementInputDirection = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (movementInputDirection != TSVector2.zero)
				{
					_actor.ForceChangeDirection(movementInputDirection);
				}
				ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.E };
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				int skillId = ((_skill != null) ? _skill.skillId : 0);
				System.Action onAnticipationEnd = OnAnticipationEnd;
				System.Action onRecoveryBegin = OnRecoveryBegin;
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: true, autoLookAtTarget: false, null, null, default(TSVector2), onAnticipationEnd, onRecoveryBegin, null, onComboFinish, onInterrupt);
				if (_dodge == null)
				{
					_dodge = new Dodge();
				}
				TSVector2 tSVector = SceneSingleton<AdventurePlayerController>.Instance.GetMovementInputDirection();
				if (tSVector == TSVector2.zero)
				{
					tSVector = _actor.tsTransform.Forward.normalized;
				}
				_dodge.Begin(_actor, tSVector, _dodgeDuration, _dodgeDistance, null, comboWithAttack: true);
			}
		}

		protected void OnAnticipationEnd()
		{
		}

		protected void OnRecoveryBegin()
		{
			OnFinish();
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}
	}
	public class Skill_NormalAttack : SkillAdvancedBase
	{
		protected ComboAttack _comboAttack;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (!(_skill != null))
			{
				return;
			}
			SetSkillPhaseConfig(SkillPhaseFeatureFlag.Skill1 | SkillPhaseFeatureFlag.Dodge | SkillPhaseFeatureFlag.Ultimate, null, SkillPhaseFeatureFlag.Skill1 | SkillPhaseFeatureFlag.Dodge | SkillPhaseFeatureFlag.Ultimate, null);
			if (_actor.attackTarget != null)
			{
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[4];
				ComboAttack obj = _comboAttack;
				AdventureActor actor = _actor;
				AdventureSkill skill = _skill;
				int skillId = ((_skill != null) ? _skill.skillId : 0);
				System.Action onComboFinish = OnFinish;
				System.Action onInterrupt = OnInterrupt;
				Action<string> onCustomEvent = OnCustomEvent;
				obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: false, skillId, forceInterruptAttack: false, autoLookAtTarget: false, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
			}
			else
			{
				OnInterrupt();
			}
		}

		protected void OnRecoveryBegin()
		{
		}

		protected void OnCustomEvent(string eventName)
		{
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			OnFinish();
		}

		public void OnUpdate()
		{
			if (_actor.attackTarget != null)
			{
				FP fP = _actor.DistanceWithRadius(_actor.attackTarget);
				_canNormSkillDistance = fP <= CommonUtils.GetAttackRange(_actor);
			}
			if ((_actor.attackTarget == null || !_canNormSkillDistance) && _comboAttack != null)
			{
				_comboAttack.CancelAttack();
			}
		}
	}
	public class Skill_Ultra : SkillAdvancedBase
	{
		protected ComboAttack _comboAttack;

		protected PlayTimeline _playTimeline;

		protected override void OnSkillDisable()
		{
			base.OnSkillDisable();
			_comboAttack?.Clear();
		}

		protected override void OnSkillEnable()
		{
			base.OnSkillEnable();
		}

		public void OnStart()
		{
			if (_skill != null)
			{
				SetSkillPhaseConfig(SkillPhaseFeatureFlag.None, null, SkillPhaseFeatureFlag.None, null);
				if (_comboAttack == null)
				{
					_comboAttack = new ComboAttack();
				}
				if (_playTimeline == null)
				{
					_playTimeline = new PlayTimeline();
				}
				_playTimeline.Play(_actor, delegate
				{
					ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.X };
					ComboAttack obj = _comboAttack;
					AdventureActor actor = _actor;
					AdventureSkill skill = _skill;
					int skillId = ((_skill != null) ? _skill.skillId : 0);
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					Action<string> onCustomEvent = OnCustomEvent;
					obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: true, autoLookAtTarget: true, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
				}, delegate
				{
					ComboInputBuffer.ActionKey[] actionKeys = new ComboInputBuffer.ActionKey[1] { ComboInputBuffer.ActionKey.X };
					ComboAttack obj = _comboAttack;
					AdventureActor actor = _actor;
					AdventureSkill skill = _skill;
					int skillId = ((_skill != null) ? _skill.skillId : 0);
					System.Action onComboFinish = OnFinish;
					System.Action onInterrupt = OnInterrupt;
					Action<string> onCustomEvent = OnCustomEvent;
					obj.BeginAttack(actor, skill, actionKeys, flushInputedKeys: true, skillId, forceInterruptAttack: true, autoLookAtTarget: true, null, null, default(TSVector2), null, null, null, onComboFinish, onInterrupt, onCustomEvent);
				});
			}
		}

		protected void OnFinish()
		{
			_skill.Clear();
		}

		protected void OnInterrupt()
		{
			_skill.Clear();
		}

		protected void OnCustomEvent(string eventName)
		{
		}
	}
